/// `unify` raises its `TypeError` unlocated: it sees types, not source. Every
/// call is `unifyAt` (which stamps the location it is given) or sits under a
/// caller that stamps one with `locateLast` — 01 step 9: no type error leaves
/// inference without a place in the source.
const unifyUnlocated = unifyMod.unify;
const Lexer = @import("../lexer.zig").Lexer;
const lexerMod = @import("../lexer.zig");
const Parser = @import("../parser.zig").Parser;
const exprsMod = @import("../parser/exprs.zig");
const Module = @import("../module.zig").Module;
const comptimeMod = @import("../comptime.zig");
const formatMod = @import("../format.zig");

pub const InferError = error{ TypeError, OutOfMemory };

/// A single resolved top-level binding: the declaration name and its inferred type.
pub const Binding = struct {
    name: []const u8,
    type_: *T.Type,
};

/// Like `Binding` but also carries the typed expression tree for `val` declarations.
/// `typedExpr` is null for type declarations (record/struct/enum/interface/fn).
/// `decl` is the original AST declaration node.
/// `typeId` is set for record/struct/enum declarations (monotonic counter).
pub const TypedBinding = struct {
    name: []const u8,
    type_: *T.Type,
    typedExpr: ?ast.TypedExpr,
    decl: ast.DeclKind,
    typeId: ?usize = null,
};

// ── public entry point ────────────────────────────────────────────────────────

/// Infer types for an entire program.
///
/// Pass 1 registers all type definitions (record, struct, enum) and builds
/// constructor bindings in the environment.
/// Pass 2 infers every `val` and `fn` declaration in source order.
///
/// Returns a slice of `Binding` values in declaration order.
/// All memory is allocated in `env.arena`.
/// Decision 107 — every item of an import list binds exactly one local name
/// (`ImportPath.name()`: the alias, else the leaf). The names one module's
/// imports bind are unique: a second item binding a name already bound is
/// `import-name-collision`, located at that second item, in either spelling.
/// A repeated IDENTICAL item is not a collision — an `@emit` contribution
/// re-imports what its module already imports, and codegen dedups it the
/// same way (`seen_imports`). Runs for every `use` decl, `from "std"` or not,
/// on both inference entry points.
fn noteImportBindings(env: *Env, u: ast.ImportDecl) InferError!void {
    if (u.activationOnly) return;
    for (u.imports) |imp| {
        // A `*` opts an extension in by its declared name; the dispatch rewrite
        // emits `Name.method(recv)`, so a renamed binding is one it never
        // reaches. Refused rather than bound half-way.
        if (imp.activate and imp.alias != null) {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}* as {s}` — an activation names the extension it opts in; it cannot be renamed", .{ diagnostics.import_alias_on_activation, imp.leaf(), imp.alias.? });
            env.lastError = TypeError.custom(msg, "Drop the `as`: `import {Name*}` activates `Name` under its own name.").withLoc(imp.loc);
            return error.TypeError;
        }
        const local = imp.name();
        const gop = try env.importBound.getOrPut(local);
        if (gop.found_existing) {
            if (gop.value_ptr.samePath(imp)) continue;
            const first = gop.value_ptr.*;
            const first_path = try first.dotted(env.arena);
            const this_path = try imp.dotted(env.arena);
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is already bound by the import of `{s}`; `{s}` would bind it again", .{ diagnostics.import_name_collision, local, first_path, this_path });
            env.lastError = TypeError.custom(msg, "Rename one of the two with `as` (`url.parse as parseUrl`), or import the namespace and qualify the call.").withLoc(imp.loc);
            return error.TypeError;
        }
        gop.value_ptr.* = imp;
        try noteStdContextName(env, u, imp, local);
    }
}

/// Decision 354 — a leaf import of std's `context` module (`import
/// {context.Context, context.provide, context.context} from "std"`) records
/// the local name against the declaration it names, so the checker knows the
/// type and the two hooks it lowers whatever the import's `as` calls them.
fn noteStdContextName(env: *Env, u: ast.ImportDecl, imp: ast.ImportPath, local: []const u8) InferError!void {
    if (!imp.isQualified()) return;
    const src = try u.leafSource(imp, env.arena, false);
    const module = switch (src) {
        .module => |m| m,
        .root, .key => return,
    };
    if (std.mem.eql(u8, module, "std/hooks")) {
        // Decisions 771, 774 — std's `hooks.memo`, lowered where it is `use`d.
        if (std.mem.eql(u8, imp.leaf(), "memo")) try env.stdMemoNames.put(env.arena, local, {});
        return;
    }
    if (!std.mem.eql(u8, module, "std/context")) return;
    const leaf = imp.leaf();
    const which: envMod.StdContextName = if (std.mem.eql(u8, leaf, "Context"))
        .context_type
    else if (std.mem.eql(u8, leaf, "createContext"))
        .create_context
    else if (std.mem.eql(u8, leaf, "inject"))
        .inject
    else if (std.mem.eql(u8, leaf, "provide"))
        .provide
    else if (std.mem.eql(u8, leaf, "context"))
        .context
    else if (std.mem.eql(u8, leaf, "RenderScope"))
        .render_scope
    else
        return;
    try env.stdContextNames.put(env.arena, local, which);
}

/// Decision 106 — the root of std is pure: a module at `std/<name>` (one
/// segment under `std/`) imports nothing from `io/`, whether it spells the
/// std package bare (`import {io.fs.readText};`, the package's own root) or
/// `from "std"`, in the dotted or the grouped form (`io: {fs}`), and
/// including the namespace `io` itself. `io/` and `testing/` modules are two
/// segments deep and are not checked; neither is user code, where `io.` on
/// the import line is a reading signal and not a guarantee. No configuration
/// (decision 67). Located at the offending item.
fn checkStdRootPurity(env: *Env, u: ast.ImportDecl) InferError!void {
    if (!std.mem.startsWith(u8, env.modulePath, "std/")) return;
    const name = env.modulePath["std/".len..];
    if (std.mem.indexOfScalar(u8, name, '/') != null) return;
    const into_std = switch (u.source) {
        .root => true,
        .key => false,
        .module => |m| std.mem.eql(u8, m, "std"),
    };
    if (!into_std) return;
    for (u.imports) |imp| {
        if (!std.mem.eql(u8, imp.segments[0], "io")) continue;
        const path = try imp.dotted(env.arena);
        const msg = try std.fmt.allocPrint(env.arena, "{s}: std module `{s}` is at the root of std, which is pure; `{s}` imports from `io/`", .{ diagnostics.std_root_imports_io, name, path });
        env.lastError = TypeError.custom(msg, "Move the module under `io/` (it talks to the world), or take the value it needs as a parameter.").withLoc(imp.loc);
        return error.TypeError;
    }
}

/// `import {bool} from "std"` — marks each imported std module in
/// `env.stdImports` so qualified calls (`bool.negate(x)`) resolve against
/// `env.stdModules`. Returns true when the decl was a `from "std"` import
/// (fully handled here); unknown std module → clear type error.
///
/// Decision 107 — an item may carry a path. `import {io.fs} from "std"` (or
/// `io: {fs}`) binds the MODULE `io/fs` as the namespace `fs`;
/// `import {io.fs.readText as read}` binds the module's `pub fn` as the value
/// `read`; `import {collections.Dict}` registers that one `pub type`. Only the
/// leaf enters scope — neither `io` nor `fs` is bound by the last two.
fn markStdImports(env: *Env, u: ast.ImportDecl) InferError!bool {
    try checkStdRootPurity(env, u);
    try noteImportBindings(env, u);
    const from_std = switch (u.source) {
        .module => |m| std.mem.eql(u8, m, "std"),
        .root, .key => false,
    };
    if (!from_std) return false;
    for (u.imports) |imp| {
        const whole = try imp.fullPath(env.arena);
        // The leaf is a module (the namespace form, dotted or grouped).
        if (env.stdModules.contains(whole)) {
            try env.stdImports.put(imp.name(), whole);
            // Type export: register the module's `pub` record/struct/enum decls
            // into this env so case patterns and annotations can name them
            // (e.g. `Order` from `import {order} from "std"`). Each is a TYPE
            // only, as a namespace import of the program's own module: no
            // constructor or variant enters scope as a bare name — `failure`'s
            // `HostErrorName.Error` never shadows `Error`; it is reached as
            // `failure.HostErrorName.Error`.
            if (env.stdModuleTypes.get(whole)) |decls| {
                for (decls) |d| {
                    // Decision 170 — a type the module declares or imports by
                    // name is that declaration; the namespace's same-named
                    // type stays reachable only as what it is not here.
                    const tn: ?[]const u8 = switch (d) {
                        .type_ => |t| t.name,
                        .typeAlias => |a| a.name,
                        else => null,
                    };
                    if (tn) |n| if (env.explicitTypeNames.contains(n)) {
                        try env.shadowedStdTypes.put(env.arena, n, whole);
                        continue;
                    };
                    try registerStdTypeDecl(env, whole, imp, d, .type_only);
                }
            }
            continue;
        }
        // The leaf is a symbol of the module the prefix names.
        if (imp.isQualified()) {
            const mod_name = try imp.prefixPath(env.arena);
            const exports = env.stdModules.get(mod_name) orelse {
                const msg = try std.fmt.allocPrint(env.arena, "unknown \"std\" module `{s}` in import", .{mod_name});
                env.lastError = TypeError.custom(msg, "Only the leaf of an import path enters scope; the segments before it name a std module (`libs/std/src/root.bp` lists them).").withLoc(imp.loc);
                return error.TypeError;
            };
            const leaf = imp.leaf();
            var bound_type = false;
            if (env.stdModuleTypes.get(mod_name)) |decls| {
                for (decls) |d| {
                    const type_name = switch (d) {
                        .type_ => |t| t.name,
                        .typeAlias => |a| a.name,
                        else => continue,
                    };
                    if (!std.mem.eql(u8, type_name, leaf)) continue;
                    // Decision 603 — registered under its alias already
                    // (`preRegisterStdImportAliases`).
                    if (imp.alias) |al| if (env.renamedTypeImports.contains(al)) {
                        bound_type = true;
                        break;
                    };
                    // The types its fields and methods name come along as
                    // types only, as for a leaf import of the program's own
                    // module (`registerImportedTypeClosure`).
                    var module_decls = std.StringHashMap(ast.DeclKind).init(env.arena);
                    for (decls) |md| switch (md) {
                        .type_ => |t| try module_decls.put(t.name, md),
                        .typeAlias => |a| try module_decls.put(a.name, md),
                        else => {},
                    };
                    registerImportedTypeClosure(env, module_decls, d) catch |err| return locateInStd(env, err, mod_name, imp);
                    try registerStdTypeDecl(env, mod_name, imp, d, .with_bindings);
                    // Decision 110 — `as` binds a type leaf like any other.
                    if (imp.alias) |al| try registerImportedTypeAlias(env, d, al, imp.loc);
                    bound_type = true;
                    break;
                }
            }
            // A std decorator is reached through its module: the code it
            // `@emit`s names the module's functions through the handle the
            // annotation is written with (`#[mocks.mock]` → `mocks.invoke`),
            // and a leaf import gives it none.
            if (!bound_type and stdDecoratorNamed(env, mod_name, leaf)) {
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is a decorator of std module `{s}`, and a std decorator is reached through its module", .{ diagnostics.std_decorator_leaf_import, leaf, mod_name });
                const hint = try std.fmt.allocPrint(env.arena, "Import the module (`import {{{s}}} from \"std\"`) and write the annotation through it (`#[{s}.{s}]`).", .{ try std.mem.replaceOwned(u8, env.arena, mod_name, "/", "."), imp.segments[imp.segments.len - 2], leaf });
                env.lastError = TypeError.custom(msg, hint).withLoc(imp.loc);
                return error.TypeError;
            }
            if (!bound_type) {
                const ty = exports.get(leaf) orelse {
                    const msg = try std.fmt.allocPrint(env.arena, "std module `{s}` has no public `{s}`", .{ mod_name, leaf });
                    env.lastError = TypeError.custom(msg, "Check the name against the module's `pub` declarations (`libs/std/AGENTS.md` lists each module's surface).").withLoc(imp.loc);
                    return error.TypeError;
                };
                try env.bind(imp.name(), ty);
                try env.stdLeafFns.put(env.arena, imp.name(), .{ .module = mod_name, .name = leaf });
            }
            continue;
        }
        env.lastError = TypeError.custom(
            "unknown \"std\" module in import",
            "Available std modules: bool. (A `Result`'s `map` / `flatMap` / `unwrapOr` / `isOk` / `isError` are its methods: `r.map(f)`, no import.)",
        ).withLoc(imp.loc);
        return error.TypeError;
    }
    return true;
}

/// Register a `pub` type of std module `mod_name` that `imp` brings in.
/// `.type_only` takes back the constructor and variant bindings the
/// registration adds (a namespace import, as `registerTypesOnly` does for a
/// type's closure); `.with_bindings` keeps them (the type named by the leaf).
/// Decision 576 (13) — a module that imports one of `compiler.bp`'s aliases
/// (`import {compiler.Span} from "std"`) names it in its own type
/// declarations and signatures, which register before the module's imports
/// are marked: the imported aliases enter the scope first. An alias registers as a name
/// only (`registerTypeDecl`), so marking the import again later is the same.
/// An imported alias of an enum (`compiler.DeclKind`, `= __DeclKind`)
/// reaches its variants as the type does: `DeclKind.Fn` is `__DeclKind.Fn`
/// (decision 110's receiver rewrite, `importedTypeAliasReceiver`).
fn bindAliasNamespace(env: *Env, a: ast.TypeAliasDecl) InferError!void {
    const target = switch (a.target) {
        .named => |n| n,
        else => return,
    };
    if (env.bindings.get(a.name) != null) return;
    if (env.lookupTypeDef(target) == null) return;
    // As decision 110's `import {T as A}` (`registerImportedTypeAlias`): the
    // alias is the declared name at a call and a receiver, and its
    // constructor is the target's.
    try env.importedTypeAliases.put(env.arena, a.name, target);
    if (env.lookup(target)) |ctor| try env.bind(a.name, ctor);
}

pub fn preRegisterStdImportAliases(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| {
        if (decl != .use) continue;
        const u = decl.use;
        // A std module names a sibling with a bare `import {compiler.X};`.
        const from_std = switch (u.source) {
            .module => |m| std.mem.eql(u8, m, "std"),
            .root => env.inStd or std.mem.startsWith(u8, env.modulePath, "std/"),
            .key => false,
        };
        if (!from_std) continue;
        for (u.imports) |imp| {
            if (!imp.isQualified()) continue;
            const mod_name = try imp.prefixPath(env.arena);
            const decls = env.stdModuleTypes.get(mod_name) orelse continue;
            for (decls) |d| if (d == .typeAlias and std.mem.eql(u8, d.typeAlias.name, imp.leaf())) {
                try env.typeAliases.put(env.arena, d.typeAlias.name, d.typeAlias);
                try bindAliasNamespace(env, d.typeAlias);
            };
            // Decision 110 — `import {io.clock.Duration as D} from "std"`: the
            // signatures register before the imports are marked, so a function
            // declared after its caller would read `D` as a type of its own
            // (`expected D, got Duration`). The alias enters the scope first;
            // marking the import binds its constructor later.
            if (imp.alias) |al| for (decls) |d| {
                const type_name = switch (d) {
                    .type_ => |t| t.name,
                    .typeAlias => |a| a.name,
                    else => continue,
                };
                if (!std.mem.eql(u8, type_name, imp.leaf())) continue;
                // Decision 603 — beside this module's type of the name the
                // alias is std's type's identity here, as decision 310's
                // renamed import: registered under it, its signatures with it.
                if (env.renamedTypeImports.contains(al) and d == .type_) {
                    var module_decls = std.StringHashMap(ast.DeclKind).init(env.arena);
                    for (decls) |md| switch (md) {
                        .type_ => |t| try module_decls.put(t.name, md),
                        .typeAlias => |a| try module_decls.put(a.name, md),
                        else => {},
                    };
                    registerImportedTypeClosure(env, module_decls, d) catch |err| return locateInStd(env, err, mod_name, imp);
                    registerRenamedImportedType(env, d.type_, al) catch |err| return locateInStd(env, err, mod_name, imp);
                    break;
                }
                try registerImportedTypeAlias(env, d, al, imp.loc);
                break;
            };
        }
    }
}

fn registerStdTypeDecl(env: *Env, mod_name: []const u8, imp: ast.ImportPath, d: ast.DeclKind, mode: enum { type_only, with_bindings }) InferError!void {
    if (mode == .with_bindings) {
        registerTypeDecl(env, d) catch |err| return locateInStd(env, err, mod_name, imp);
        if (d == .typeAlias) try bindAliasNamespace(env, d.typeAlias);
        return;
    }
    var before = std.StringHashMap(void).init(env.arena);
    defer before.deinit();
    var kit = env.bindings.keyIterator();
    while (kit.next()) |k| try before.put(k.*, {});
    registerTypeDecl(env, d) catch |err| return locateInStd(env, err, mod_name, imp);
    var added: std.ArrayListUnmanaged([]const u8) = .empty;
    defer added.deinit(env.arena);
    var ait = env.bindings.keyIterator();
    while (ait.next()) |k| if (!before.contains(k.*)) try added.append(env.arena, k.*);
    for (added.items) |k| {
        if (env.bindings.get(k)) |ty| try env.typeOnlyCtors.put(k, ty);
        _ = env.bindings.remove(k);
    }
}

/// A refusal met while registering a std module's declaration is located in
/// that module's file (`libs/std/src/<mod>.bp`, the error's `origin`), the
/// importing module's `loc` the import item that brought it — never std's
/// line read against the program's file.
fn locateInStd(env: *Env, err: InferError, mod_name: []const u8, imp: ast.ImportPath) InferError {
    if (err == error.TypeError) {
        if (env.lastError) |*te| if (te.origin == null) {
            if (te.loc) |at| te.origin = .{ .file = try std.fmt.allocPrint(env.arena, "libs/std/src/{s}.bp", .{mod_name}), .loc = at };
            te.loc = imp.loc;
        };
    }
    return err;
}

/// Decision 170 — collect the type names this module declares (`type`, a
/// type alias, `behavior`) or imports by name from a module that is not std
/// (the item's leaf: `import {kit.store.Dict as OwnDict}` names `Dict`), into
/// `env.explicitTypeNames`, before any std import is marked.
///
/// Types are nominal by name in the checker, so one module holds one type of
/// a name: a `type Dict(…)` beside `import {collections.Dict} from "std"`,
/// two un-aliased imports of two modules' `Policy` (decision 170), a
/// type of this module beside an un-aliased import of a same-named type.
/// Each used to resolve silently to whichever registered
/// last; the second source is `import-name-collision` at its import item,
/// naming both. Two imported types of one declared name each under an alias
/// (`import {a.p.Policy as APolicy}; import {b.p.Policy as BPolicy};`, or one
/// of them un-aliased) are two types (decision 310), and so is an aliased
/// import beside a type of this module (decision 603), a std type's included:
/// the alias is the type's identity here (`Env.renamedTypeImports`). (Two functions of one name under
/// two aliases are legal too — a function is bound by its local name.)
fn noteExplicitTypeNames(env: *Env, program: ast.Program) InferError!void {
    // Declared name → where it comes from (a module path, or "" for this module).
    var sources: std.StringHashMapUnmanaged(TypeSource) = .empty;
    defer sources.deinit(env.arena);
    for (program.decls) |decl| switch (decl) {
        .type_ => |t| try noteTypeSource(env, &sources, t.name, .{ .label = "" }, null),
        .typeAlias => |a| try noteTypeSource(env, &sources, a.name, .{ .label = "" }, null),
        .behavior => |b| try noteTypeSource(env, &sources, b.name, .{ .label = "" }, null),
        else => {},
    };
    for (program.decls) |decl| switch (decl) {
        .use => |u| {
            const from_std = switch (u.source) {
                .module => |m| std.mem.eql(u8, m, "std"),
                .root, .key => false,
            };
            for (u.imports) |imp| {
                const leaf = imp.leaf();
                if (leaf.len == 0 or !std.ascii.isUpper(leaf[0])) continue;
                const prefix = try imp.prefixPath(env.arena);
                if (from_std) {
                    // A std leaf (`collections.Dict [as D]`) brings the type
                    // in under its declared name.
                    if (!imp.isQualified()) continue;
                    if (!stdModuleDeclaresType(env, prefix, leaf)) continue;
                    // Decision 603 — held under its alias beside this
                    // module's type of the name: two types.
                    if (imp.alias) |al| if (env.renamedTypeImports.contains(al)) continue;
                    try noteTypeSource(env, &sources, leaf, .{ .label = try std.fmt.allocPrint(env.arena, "std/{s}", .{prefix}) }, imp);
                    continue;
                }
                // Decision 310 — an item whose alias is its type's identity
                // here holds the alias, never the declared name: two of them,
                // or one beside an un-aliased item of the name, are two types.
                if (imp.alias) |al| if (env.renamedTypeImports.contains(al)) {
                    try env.explicitTypeNames.put(env.arena, al, {});
                    continue;
                };
                try env.explicitTypeNames.put(env.arena, leaf, {});
                // Only an item that resolved to a TYPE is a type source.
                const isType = if (imp.alias) |al| env.importedTypeAliases.contains(al) else env.lookupTypeDef(leaf) != null;
                if (!isType) continue;
                // A package's own item (no module prefix — row 33's
                // `import {App} from "pkg";`) is named by the package alone.
                const label = switch (u.source) {
                    .module, .key => |m| if (prefix.len == 0) m else try std.fmt.allocPrint(env.arena, "{s}:{s}", .{ m, prefix }),
                    .root => prefix,
                };
                // The item's identity is the module that declares what it
                // resolved to, not its spelling: `from "catalog"` and the
                // path `catalog.Widget` reach one declaration.
                const module: ?[]const u8 = if (env.importedTypeDecls.get(imp.name())) |d| d.module else null;
                try noteTypeSource(env, &sources, leaf, .{ .label = label, .module = module }, imp);
            }
        },
        else => {},
    };
}

fn stdModuleDeclaresType(env: *Env, mod: []const u8, name: []const u8) bool {
    const decls = env.stdModuleTypes.get(mod) orelse return false;
    for (decls) |d| {
        const tn = switch (d) {
            .type_ => |t| t.name,
            .typeAlias => |a| a.name,
            else => continue,
        };
        if (std.mem.eql(u8, tn, name)) return true;
    }
    return false;
}

/// Where a type name of a module comes from (`noteExplicitTypeNames`): the
/// label a refusal names it by (`""` for this module, `std/collections`,
/// `srv`, `a/p`), and — for a non-std import item — the module path of the
/// declaration it resolved to, which is what tells two sources apart.
const TypeSource = struct {
    label: []const u8,
    module: ?[]const u8 = null,

    fn same(a: TypeSource, b: TypeSource) bool {
        if (a.module) |am| if (b.module) |bm| return std.mem.eql(u8, am, bm);
        return std.mem.eql(u8, a.label, b.label);
    }
};

fn noteTypeSource(env: *Env, sources: *std.StringHashMapUnmanaged(TypeSource), name: []const u8, src_: TypeSource, imp: ?ast.ImportPath) InferError!void {
    const src = src_.label;
    if (!std.mem.startsWith(u8, src, "std/")) try env.explicitTypeNames.put(env.arena, name, {});
    if (sources.get(name)) |prev_| {
        if (prev_.same(src_)) return;
        const prev = prev_.label;
        const at = imp orelse return;
        const first = if (prev.len == 0) "this module" else try std.fmt.allocPrint(env.arena, "`{s}`", .{prev});
        const second = if (src.len == 0) "this module" else try std.fmt.allocPrint(env.arena, "`{s}`", .{src});
        const msg = try std.fmt.allocPrint(env.arena, "{s}: this module would hold two types declared `{s}` — {s}'s and {s}'s; a type is told apart by its declared name, so one module holds one type of a name, aliased or not", .{ diagnostics.import_name_collision, name, first, second });
        env.lastError = TypeError.custom(msg, "Use one of the two in this module, and reach the other through a module that holds only it (a function there that takes or answers it).").withLoc(at.loc);
        return error.TypeError;
    }
    try sources.put(env.arena, name, src_);
}

/// Whether `t` names the nominal type `name` anywhere in it.
fn typeNamesNominal(t: *T.Type, name: []const u8, depth: usize) bool {
    if (depth > 32) return false;
    const d = t.deref();
    return switch (d.*) {
        .named => |n| blk: {
            if (std.mem.eql(u8, n.name, name)) break :blk true;
            for (n.args) |a| if (typeNamesNominal(a, name, depth + 1)) break :blk true;
            break :blk false;
        },
        .func => |f| blk: {
            for (f.params) |p| if (typeNamesNominal(p, name, depth + 1)) break :blk true;
            break :blk typeNamesNominal(f.ret, name, depth + 1);
        },
        .union_ => |us| blk: {
            for (us) |u| if (typeNamesNominal(u, name, depth + 1)) break :blk true;
            break :blk false;
        },
        .record => |fs| blk: {
            for (fs) |f| if (typeNamesNominal(f.type_, name, depth + 1)) break :blk true;
            break :blk false;
        },
        .typeVar => false,
    };
}

/// Decision 170 — a call through a std namespace whose signature names a type
/// the namespace could not bring in (`env.shadowedStdTypes`: this module's own
/// or named import holds the name) is refused at the call. Types are nominal
/// by name, so the checker would read std's type as this module's and accept
/// a value of the wrong one.
fn refuseShadowedStdSignature(env: *Env, ns: []const u8, stdKey: []const u8, callee: []const u8, fnTy: *T.Type, loc: ast.Loc) InferError!void {
    var it = env.shadowedStdTypes.iterator();
    while (it.next()) |e| {
        if (!std.mem.eql(u8, e.value_ptr.*, stdKey)) continue;
        const name = e.key_ptr.*;
        if (!typeNamesNominal(fnTy, name, 0)) continue;
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}.{s}` names std/{s}'s `{s}`, and `{s}` in this module is another declaration", .{ diagnostics.ambiguous_import_use, ns, callee, stdKey, name, name });
        const hint = try std.fmt.allocPrint(env.arena, "One module holds one type of a name: import std's `{s}` in a module that does not declare or import another, or rename this module's.", .{name});
        env.lastError = TypeError.custom(msg, hint).withLoc(loc);
        return error.TypeError;
    }
}

/// Whether the std module `mod_name` declares the decorator `pub fn name`.
fn stdDecoratorNamed(env: *Env, mod_name: []const u8, name: []const u8) bool {
    const fns = env.stdModuleFns.get(mod_name) orelse return false;
    for (fns) |f| if (f.isPub and isDecoratorParams(f.params) and std.mem.eql(u8, f.name, name)) return true;
    return false;
}

/// A std module's decorators travel with its import, as a library's do: `import
/// {testing.mocks} from "std"` makes `pub fn mock(comptime decl: @Decl)` the
/// annotation `#[mocks.mock]` (the name the import binds, an alias included).
/// A leaf import of a decorator is refused by `markStdImports`
/// (`std-decorator-leaf-import`). Registered before `validateDecorators`,
/// which runs ahead of the `use` declarations' own inference; every handle is
/// noted in `Env.stdDecoratorHandles`, so an annotation through one that names
/// no decorator of the module is refused (`refuseUnknownAnnotationList`).
fn registerStdImportDecorators(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| {
        if (decl != .use) continue;
        const u = decl.use;
        const from_std = switch (u.source) {
            .module => |m| std.mem.eql(u8, m, "std"),
            .root, .key => false,
        };
        if (!from_std) continue;
        for (u.imports) |imp| {
            const whole = try imp.fullPath(env.arena);
            if (env.stdModules.contains(whole)) {
                try registerStdDecorators(env, whole, imp.name());
                try env.stdDecoratorHandles.put(env.arena, imp.name(), whole);
            }
        }
    }
}

/// Register the decorators (`pub fn d(comptime decl: @Decl, …)`) of the std
/// module `mod_name` in the importing env, each under `<handle>.<fn>` — the
/// namespace import `import {testing.mocks}` makes `#[mocks.mock]`. The
/// functions a decorator body reaches in its module travel with it
/// (`decoratorSupport`), as for a library's.
fn registerStdDecorators(env: *Env, mod_name: []const u8, handle: []const u8) InferError!void {
    const fns = env.stdModuleFns.get(mod_name) orelse return;
    var byName = std.StringHashMap(ast.FnDecl).init(env.arena);
    for (fns) |f| try byName.put(f.name, f);
    for (fns) |f| {
        if (!f.isPub or !isDecoratorParams(f.params)) continue;
        const name = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ handle, f.name });
        const support = try decoratorSupport(env.arena, byName, &env.importedFnSupport, f);
        const owner = try std.fmt.allocPrint(env.arena, "std/{s}", .{mod_name});
        try registerImportedDecorator(env, name, f, owner, support.fns, support.conflict);
    }
}

/// STD-001 (decision 518 (4)) — the refusal belongs to the CALL, never to the
/// import: `import {failure} from "std"` and `import {erlang.node}` are
/// accepted on every target, and a call of a std function that reaches a
/// host-bound declaration with no implementation for the build's target is
/// refused at the call, naming the function — and, when the declaration is
/// another function of the module the call goes through, that one too.
/// Inference never reads the target (decision 798 (4)): it records each call
/// that reaches a host declaration, with the declarations it reaches
/// (`stdHostsOf`), and `codegen/target_check.zig` refuses at emit the first
/// one whose host has no binding for the target. Pure-bp functions whose
/// bodies reach no host declaration are not recorded. A function value taken
/// without a call is the backend's refusal (`has no implementation for the
/// <t> backend`).
fn recordStdCall(env: *Env, mod_name: []const u8, name: []const u8, loc: ast.Loc) InferError!void {
    const hosts = try stdHostsOf(env, mod_name, name);
    if (hosts.len == 0) return;
    const call: envMod.StdCall = .{ .site = .{ .loc = loc }, .module = mod_name, .name = name, .hosts = hosts };
    try env.stdHostCalls.append(env.arena, call);
    if (env.targetTrace) |t| try t.calls.append(env.arena, call);
}

/// The host-bound declarations of std module `mod_name` a call of `name`
/// reaches — `name` itself when it is one, else the ones its body reaches
/// through the module's own functions —, in the order the call is followed.
/// The first of them with no binding for a target is the one a refusal names
/// on that target, whatever the target.
fn stdHostsOf(env: *Env, mod_name: []const u8, name: []const u8) InferError![]const envMod.StdHost {
    const fns = env.stdModuleAllFns.get(mod_name) orelse return &.{};
    const key = try std.fmt.allocPrint(env.arena, "{s}\x00{s}", .{ mod_name, name });
    if (env.stdHostsReached.get(key)) |known| return known;
    var hosts: std.ArrayListUnmanaged(envMod.StdHost) = .empty;
    var seen: std.StringHashMapUnmanaged(void) = .empty;
    var names: std.ArrayListUnmanaged([]const u8) = .empty;
    try names.append(env.arena, name);
    var i: usize = 0;
    while (i < names.items.len) : (i += 1) {
        const n = names.items[i];
        if (seen.contains(n)) continue;
        try seen.put(env.arena, n, {});
        const f = for (fns) |g| {
            if (std.mem.eql(u8, g.name, n)) break g;
        } else continue;
        if (f.body.len == 0 and f.isExternal()) try hosts.append(env.arena, .{ .name = f.name, .implementations = f.implementations });
        try ast.collectNames(env.arena, f.body, &names);
    }
    try env.stdHostsReached.put(env.arena, key, hosts.items);
    return hosts.items;
}

/// Append one `TypedBinding` per imported symbol in a `use` decl so the LSP's
/// completion/hover engine sees them. `import {…} from "std"` is marked (and
/// contributes no value bindings — std symbols resolve via `env.stdModules`).
/// `resolveImports` already bound each name, so we read the type from `env`.
fn appendImportBindings(
    env: *Env,
    list: *std.ArrayListUnmanaged(TypedBinding),
    decl: ast.DeclKind,
    u: ast.ImportDecl,
) InferError!void {
    // A `from "std"` namespace item contributes no value binding; a symbol
    // leaf of one (`import {dict.empty as newDict}`, decision 107) was bound
    // by `markStdImports` and is listed like any other import.
    _ = try markStdImports(env, u);
    for (u.imports) |imp| {
        const name = imp.name();
        if (env.lookup(name)) |ty| {
            try list.append(env.arena, .{
                .name = name,
                .type_ = ty,
                .typedExpr = null,
                .decl = decl,
            });
        }
    }
}

/// A module-level `fn`, `val` or `var` named like a primitive type
/// (`pub fn string() -> …`) took the type's name in its module: every `string`
/// annotation there read as the function, reported far from the declaration
/// (`language-gaps.md`, "A function named like a primitive type shadows the
/// type in its module"). Refused at the declaration's name as
/// `primitive-type-name-taken`. A method keeps its name (`rows.bool(…)` — a
/// member never shadows a type).
fn refuseDeclsNamedLikePrimitives(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| {
        const name, const loc, const what = switch (decl) {
            .@"fn" => |f| .{ f.name, f.nameLoc, "a function" },
            .val => |v| .{ v.name, v.nameLoc, if (v.mutable) "a `var`" else "a `val`" },
            else => continue,
        };
        // Decision 873 (3) — every lowercase type, `array` included.
        const taken = std.mem.eql(u8, name, "array") or for (scalar_type_names) |n| {
            if (std.mem.eql(u8, n, name)) break true;
        } else false;
        if (!taken) continue;
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` names a primitive type; {s} of this module cannot take its name", .{ diagnostics.primitive_type_name_taken, name, what });
        env.lastError = locatedAt(TypeError.custom(msg, "Rename the declaration."), loc);
        return error.TypeError;
    }
}

/// The types the checker gives to literals (decision 639 (a)): `1` is an
/// `i32`, `"a"` a `string` — a module cannot declare a type of one of these
/// names, where every other prelude name shadows (606 (1)).
pub const literal_type_names = ast.literal_type_names;

/// Decision 639 (a) — `type i32(value: i64)` refused at the name,
/// `primitive-type-redeclared`: a shadowing `i32` would make `val x: i32 = 1`
/// a mismatch between two `i32`s. Decision 799 (3) — a `behavior string { … }`
/// is a behavior named like that type, refused alike: a program adds members
/// to a primitive through a contract of its own implemented for it.
fn refuseTypesNamedLikeLiterals(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| {
        const name, const loc: ast.Loc, const what = switch (decl) {
            // The shorthand's `loc` is its name; the val form's is `type`.
            .type_ => |t| .{ t.name, t.loc, "type" },
            // An alias's `loc` is its `type` keyword: the name follows it.
            .typeAlias => |a| .{ a.name, ast.Loc{ .line = a.loc.line, .col = a.loc.col + "type ".len, .expansion = a.loc.expansion }, "type" },
            // Decision 641 — std's primitive type's own member table.
            .behavior => |b| if (b.primitiveType) continue else .{ b.name, b.nameLoc, "behavior" },
            else => continue,
        };
        const taken = for (literal_type_names) |n| {
            if (std.mem.eql(u8, n, name)) break true;
        } else false;
        if (!taken) continue;
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is the type of a literal; a module cannot declare a {s} of that name", .{ diagnostics.primitive_type_redeclared, name, what });
        const hint = if (decl == .behavior)
            try std.fmt.allocPrint(env.arena, "A program adds members to `{s}` through a contract of its own implemented for it: `behavior Shout {{ … }}` then `StringShout implement Shout for {s} {{}}` (decision 799).", .{ name, name })
        else
            "Rename the type: a literal is typed by the language, never by a name this module declares (decision 639).";
        env.lastError = locatedAt(TypeError.custom(msg, hint), loc);
        return error.TypeError;
    }
}

pub fn inferProgram(env: *Env, program: ast.Program) InferError![]Binding {
    env.foldableCall = callFoldable;
    var list: std.ArrayListUnmanaged(Binding) = .empty;
    env.testIndex = 0;
    // Decision 216 (3): before this module's decorators run, `Owner.Name`
    // may be an associated type they are about to declare.
    try noteOwnDecls(env, program);
    env.assocTypesPending = !env.skipDecoratorInvoke;

    try validateUniqueDefaults(env, program);
    try refuseDeclsNamedLikeImports(env, program);
    try refuseFnReturnMissing(env, program);
    try refuseDeclsNamedLikePrimitives(env, program);
    try refuseTypesNamedLikeLiterals(env, program);
    try noteExplicitTypeNames(env, program);
    try preRegisterStdImportAliases(env, program);

    // Pass 1: register type definitions and their constructors.
    try registerTypeAliases(env, program);
    try checkSelfSpelling(env, program);
    for (program.decls) |decl| {
        if (decl == .behavior and !decl.behavior.primitiveType) takeNameFromPrelude(env, decl.behavior.name);
        try registerTypeDecl(env, decl);
    }
    try registerExtensions(env, program);
    try buildScopeSnapshot(env, program);
    try registerFnSignatures(env, program);
    try registerAnnotationTypes(env, program);

    // Annotation processors run before bodies (see `inferProgramTyped`): a
    // decorator's `@emit`ed decls must be spliced before a body referencing them
    // is inferred. Bail out early when contributions exist — the spliced
    // re-analysis does the real inference.
    try registerStdImportDecorators(env, program);
    // Decision 380 — an annotation's argument may call a std function
    // through a namespace the module imports (`revalidate: clock.hours(1)`,
    // 290): the std imports are bound before the arguments are checked.
    for (program.decls) |d| if (d == .use) {
        _ = try markStdImports(env, d.use);
    };
    try validateDecorators(env, program);
    try refuseUnknownAnnotations(env, program);
    try refuseHooksReaderOutputs(env, program);
    try invokeDecorators(env, program, .plain);
    // Decision 575 (6) — every declaration's implementations: std's
    // `external` read where it is written, a library's source annotation
    // added by the run above.
    // A module whose decorators also emit, add a member or wrap is
    // re-analysed on the merged program, which receives them there
    // (`comptime.zig`); they stay on the env until then.
    if (!hasSplicedContributions(env)) try applyImplementContributions(env, program);
    try noteTemplateQueries(env, program);
    try noteDefaultQueries(env, program);
    env.assocTypesPending = false;
    if (env.contributions.items.len > 0 or env.memberContributions.items.len > 0 or env.typeContributions.items.len > 0 or env.typeinfoAllPending) {
        return list.toOwnedSlice(env.arena);
    }
    // Decision 668 — every type parameter bound by a parameter, checked once
    // the decorators' outputs are in.
    try refuseUnboundTypeParams(env, program);
    // Decision 575 (6) — every declaration's implementations, checked once the
    // decorators' outputs are in (a wrapper, a member: the re-analysis).
    try checkProgramImplementations(env, program);
    try refusePendingAssocType(env);

    // Pass 2: infer value-producing declarations in order.
    try noteHooksReaders(env, program);
    for (program.decls) |decl| {
        if (try inferDecl(env, decl)) |b| {
            try list.append(env.arena, b);
        }
    }
    // Decision 425 — a template call written as a record field's default
    // expands where it is written; the fill copies the expansion.
    try expandTemplateFieldDefaults(env, program);
    try refuseUnexpandedTemplateCalls(env, program);
    // Decision 375 — the nodes' `async` marks, before a `.hooks` reader reads them.
    // Decisions 378, 379 — each context read gets its type's declared default.
    try resolveContextReads(env);
    try refuseComponentAwaits(env);
    try markHookAsync(env);
    // Decision 376 — every function's stage, before a `.hooks` reader reads it.
    try markStages(env, program);
    // Decision 372 — the decorators that read `.hooks` run over the bodies.
    try runHooksReaders(env, program);

    // C10 second pass — every declaration is registered by now, so an annotation
    // that still names nothing is an unknown type, reported at the annotation.
    // Decision 328 — the method calls on a receiver still free when checked,
    // once every body has typed it.
    try resolvePendingReceiverCalls(env);
    try env.checkPendingTypeNames();
    try flushBirthWarnings(env);

    // Pass 3: semantic validation of `implement` blocks and struct accessors.
    // (Decorators already ran above, before body inference.)
    try validateProgram(env, program);
    try publishHookFns(env, program);
    // Decisions 384, 385 — what each name resolves to here, for the code
    // another module reads from this one.
    try writtenNames.publish(env, program);

    return list.toOwnedSlice(env.arena);
}

/// Like `inferProgram` but returns `TypedBinding` slices that include the
/// typed expression tree for each `val` declaration.
/// A package declares at most one `pub default mod` and one `pub default fn`; a
/// duplicate of either in one module is the error (NOT the location — they may be
/// declared in any module of the package). Cross-module pairing is the driver's
/// job (`registerExports`); this catches the per-module case for both inference
/// entry points.
fn validateUniqueDefaults(env: *Env, program: ast.Program) InferError!void {
    var default_mods: usize = 0;
    var default_fns: usize = 0;
    // 01 step 9 — the refusal points at the SECOND default, the duplicate.
    var dupLoc: ast.Loc = .{ .line = 0, .col = 0 };
    var dupFnLoc: ?ast.Loc = null;
    for (program.decls) |decl| switch (decl) {
        .mod => |m| if (m.isDefault) {
            default_mods += 1;
            if (default_mods == 2) dupLoc = m.loc;
        },
        .@"fn" => |f| if (f.isDefault) {
            default_fns += 1;
            // Decision 289 — at the later of the two: the `pub default
            // <name>;` line, or the default `fn`'s name.
            if (default_fns == 2) dupFnLoc = f.defaultBy orelse f.nameLoc;
        },
        else => {},
    };
    if (default_fns > 1) if (dupFnLoc) |at| {
        env.lastError = locatedAt(TypeError.custom(
            "default-twice: a module has one default function",
            "Keep one `pub default fn` (or `pub default <name>;`) per module (decision 289); the importer binds it under the module path.",
        ), at);
        return error.TypeError;
    };
    if (default_mods > 1 or default_fns > 1) {
        env.lastError = locatedAt(TypeError.custom(
            "a package declares at most one `pub default mod` and one `pub default fn`",
            "Remove the duplicate default declaration; a package has a single default module and handler.",
        ), dupLoc);
        return error.TypeError;
    }
}

/// A module-level `fn`, `val` or `var` named like an item one of the module's
/// imports binds (`import {page} from "deco";` beside `pub fn page(…)`) binds
/// the name twice: commonJS stopped at load (`Identifier 'page' has already
/// been declared`) while erlang ran. Refused at the declaration's name, on
/// every target, naming the import — `import-name-collision`, the rule two
/// import items already follow (decision 107). A type named like an imported
/// type is decision 170's collision, refused where the types are registered.
fn refuseDeclsNamedLikeImports(env: *Env, program: ast.Program) InferError!void {
    var imported = std.StringHashMap(ast.ImportPath).init(env.arena);
    defer imported.deinit();
    for (program.decls) |decl| switch (decl) {
        .use => |u| {
            if (u.activationOnly) continue;
            for (u.imports) |imp| if (!imp.activate) try imported.put(imp.name(), imp);
        },
        else => {},
    };
    if (imported.count() == 0) return;
    for (program.decls) |decl| {
        const name, const loc, const what = switch (decl) {
            .@"fn" => |f| .{ f.name, f.nameLoc, "a function" },
            .val => |v| .{ v.name, v.nameLoc, if (v.mutable) "a `var`" else "a `val`" },
            else => continue,
        };
        const imp = imported.get(name) orelse continue;
        const path = try imp.dotted(env.arena);
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is already bound by the import of `{s}`; {s} of this module would bind it again", .{ diagnostics.import_name_collision, name, path, what });
        env.lastError = locatedAt(TypeError.custom(msg, "Rename the declaration, or import the item under another name with `as`."), loc);
        return error.TypeError;
    }
}

/// Decision 622 — every function writes its return type, `-> void` included:
/// a free `fn` (`main` too), a method of a type or a behavior (a `default fn`, a
/// static, a `declare fn`), an `implement` / `extend` method. One that writes no
/// `->` is refused at its name, `fn-return-missing`, before any body is read —
/// its type is never taken from its `return`s or its tail (06 C9 removed). A
/// member the compiler synthesised (no location) is not the program's to fix.
/// A typed `fn` expression is refused where it is inferred
/// (`refuseFnExprReturnMissing`).
fn refuseFnReturnMissing(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| switch (decl) {
        .@"fn" => |f| if (f.returnType == null) {
            const what = if (f.anonymousDefault)
                "this `default fn`"
            else
                try std.fmt.allocPrint(env.arena, "`{s}`", .{f.name});
            return failFnReturnMissing(env, what, f.nameLoc, f.arrowOmittedHint);
        },
        .type_ => |td| try refuseTypeMethodsReturnMissing(env, td),
        .behavior => |bd| for (bd.methods) |m| {
            if (m.returnType == null and !isSynthesised(m.nameLoc))
                return failFnReturnMissing(env, try std.fmt.allocPrint(env.arena, "`{s}.{s}`", .{ bd.name, m.name }), m.nameLoc, null);
        },
        inline .implement, .extend => |b| for (b.methods) |m| {
            if (m.returnType == null and !isSynthesised(m.loc))
                return failFnReturnMissing(env, try std.fmt.allocPrint(env.arena, "`{s}.{s}`", .{ b.target, m.name }), m.loc, null);
        },
        else => {},
    };
}

fn refuseTypeMethodsReturnMissing(env: *Env, td: ast.TypeDecl) InferError!void {
    for (td.methods) |m| {
        if (m.returnType == null and !isSynthesised(m.nameLoc))
            return failFnReturnMissing(env, try std.fmt.allocPrint(env.arena, "`{s}.{s}`", .{ td.printedName(), m.name }), m.nameLoc, null);
    }
    for (td.assocTypes) |at| try refuseTypeMethodsReturnMissing(env, at);
}

fn isSynthesised(loc: ast.Loc) bool {
    return loc.line == 0 and loc.col == 0;
}

/// Decision 622, with 408 — a typed `fn` expression (`fn(n: i32) { … }`, a
/// parameter type written) writes its return type as a declaration does; an
/// untyped one (`fn(x) { … }`) is a lambda (583) and takes its type from its
/// position. Refused at the `fn`.
fn refuseFnExprReturnMissing(env: *Env, fk: anytype, loc: ast.Loc) InferError!void {
    if (fk.syntax != .fnExpr or fk.returnType != null or fk.paramTypes.len == 0) return;
    return failFnReturnMissing(env, "this `fn` expression", loc, null);
}

fn failFnReturnMissing(env: *Env, what: []const u8, loc: ast.Loc, omittedArrow: ?[]const u8) InferError {
    const msg = try std.fmt.allocPrint(env.arena, "{s}: {s} writes no return type — write -> void, or the type it answers", .{ diagnostics.fn_return_missing, what });
    const hint = if (omittedArrow) |t|
        try std.fmt.allocPrint(env.arena, "Every function writes its return type behind `->` (decisions 622, 846): write `-> {s}…`.", .{t})
    else
        "Every function writes its return type, `-> void` included (decision 622).";
    env.lastError = locatedAt(TypeError.custom(msg, hint), loc);
    return error.TypeError;
}

pub fn inferProgramTyped(env: *Env, program: ast.Program) InferError![]TypedBinding {
    env.foldableCall = callFoldable;
    var list: std.ArrayListUnmanaged(TypedBinding) = .empty;
    env.testIndex = 0;
    env.moduleDecls = program.decls;
    // Decision 216 (3): before this module's decorators run, `Owner.Name`
    // may be an associated type they are about to declare.
    try noteOwnDecls(env, program);
    env.assocTypesPending = !env.skipDecoratorInvoke;

    try validateUniqueDefaults(env, program);
    try refuseDeclsNamedLikeImports(env, program);
    try refuseFnReturnMissing(env, program);
    try refuseDeclsNamedLikePrimitives(env, program);
    try refuseTypesNamedLikeLiterals(env, program);
    try noteExplicitTypeNames(env, program);
    try preRegisterStdImportAliases(env, program);

    try registerTypeAliases(env, program);
    try checkSelfSpelling(env, program);
    for (program.decls) |decl| {
        if (decl == .behavior and !decl.behavior.primitiveType) takeNameFromPrelude(env, decl.behavior.name);
        try registerTypeDecl(env, decl);
    }
    try registerExtensions(env, program);
    try buildScopeSnapshot(env, program);
    try registerFnSignatures(env, program);
    try registerAnnotationTypes(env, program);
    try registerStdImportDecorators(env, program);

    // Annotation processors run BEFORE bodies are inferred: a decorator's
    // `@emit`ed declarations must be spliced (by `analyzeSource`) and present
    // before any body that references the generated decl is type-checked.
    // (Previously decorators ran in pass 3, after bodies — a body referencing a
    // generated decl failed spuriously, which blocked `@emit` under `botopink
    // test`. The serialized handles read only the AST, so no body inference is
    // needed first.)
    // Decision 380 — an annotation's argument may call a std function
    // through a namespace the module imports (`revalidate: clock.hours(1)`,
    // 290): the std imports are bound before the arguments are checked.
    for (program.decls) |d| if (d == .use) {
        _ = try markStdImports(env, d.use);
    };
    try validateDecorators(env, program);
    try refuseUnknownAnnotations(env, program);
    try refuseHooksReaderOutputs(env, program);
    try invokeDecorators(env, program, .plain);
    // Decision 575 (6) — every declaration's implementations: std's
    // `external` read where it is written, a library's source annotation
    // added by the run above.
    // A module whose decorators also emit, add a member or wrap is
    // re-analysed on the merged program, which receives them there
    // (`comptime.zig`); they stay on the env until then.
    if (!hasSplicedContributions(env)) try applyImplementContributions(env, program);
    try noteTemplateQueries(env, program);
    try noteDefaultQueries(env, program);
    env.assocTypesPending = false;
    if (env.contributions.items.len > 0 or env.memberContributions.items.len > 0 or env.typeContributions.items.len > 0 or env.typeinfoAllPending) {
        // A decorator `@emit`ed code: the spliced re-analysis (`analyzeSource`)
        // does the real, full inference of the generated declarations. But the
        // LSP needs a useful binding list even when that spliced code can't
        // type-check standalone (it may reference symbols only resolvable with
        // the project graph). Collect the bindings that don't depend on the
        // not-yet-spliced decls: imports, type declarations, and `fn`
        // signatures, and `val`s. A decl that fails to infer — a `val` whose body
        // references a generated decl, say — is tolerated (it just contributes no
        // binding) so one broken body never blanks the whole list. Generic — no
        // decorator framework is named here.
        for (program.decls) |decl| switch (decl) {
            .use => |u| try appendImportBindings(env, &list, decl, u),
            // N23 — a `val` is inferred tolerantly like the other decls: one
            // that references a not-yet-spliced decl fails and contributes no
            // binding; a well-typed one still binds (the LSP lists it).
            .val => {
                const maybe = inferDeclTyped(env, decl) catch |err| switch (err) {
                    error.TypeError => blk: {
                        env.lastError = null;
                        break :blk null;
                    },
                    else => return err,
                };
                if (maybe) |b| try list.append(env.arena, b);
            },
            else => {
                const maybe = inferDeclTyped(env, decl) catch |err| switch (err) {
                    error.TypeError => null,
                    else => return err,
                };
                if (maybe) |b| try list.append(env.arena, b);
            },
        };
        return list.toOwnedSlice(env.arena);
    }
    // Decision 668 — every type parameter bound by a parameter, checked once
    // the decorators' outputs are in.
    try refuseUnboundTypeParams(env, program);
    // Decision 575 (6) — every declaration's implementations, checked once the
    // decorators' outputs are in (a wrapper, a member: the re-analysis).
    try checkProgramImplementations(env, program);
    try refusePendingAssocType(env);

    try noteHooksReaders(env, program);
    for (program.decls) |decl| {
        switch (decl) {
            // `resolveImports` (called before inference in comptime.zig) already
            // called `env.bind(name, ty)` for each symbol in the `use` statement.
            // Emit one TypedBinding per import so the LSP completion engine can
            // see them — the dummy `name = ""` binding is gone.
            .use => |u| try appendImportBindings(env, &list, decl, u),
            else => {
                if (try inferDeclTyped(env, decl)) |b| {
                    try list.append(env.arena, b);
                }
            },
        }
    }
    // Decision 425 — a template call written as a record field's default
    // expands where it is written; the fill copies the expansion.
    try expandTemplateFieldDefaults(env, program);
    try refuseUnexpandedTemplateCalls(env, program);
    // Decision 375 — the nodes' `async` marks, before a `.hooks` reader reads them.
    // Decisions 378, 379 — each context read gets its type's declared default.
    try resolveContextReads(env);
    try refuseComponentAwaits(env);
    try markHookAsync(env);
    // Decision 376 — every function's stage, before a `.hooks` reader reads it.
    try markStages(env, program);
    // Decision 372 — the decorators that read `.hooks` run over the bodies.
    try runHooksReaders(env, program);

    // C10 second pass — every declaration is registered by now, so an annotation
    // that still names nothing is an unknown type, reported at the annotation.
    // Decision 328 — the method calls on a receiver still free when checked,
    // once every body has typed it.
    try resolvePendingReceiverCalls(env);
    try env.checkPendingTypeNames();
    try flushBirthWarnings(env);

    // Semantic validation of `implement` blocks and struct accessors. (Decorators
    // already ran above, before body inference.)
    try validateProgram(env, program);
    try publishHookFns(env, program);
    // Decisions 384, 385 — what each name resolves to here, for the code
    // another module reads from this one.
    try writtenNames.publish(env, program);

    return list.toOwnedSlice(env.arena);
}

// ── pass 3: semantic validation ───────────────────────────────────────────────

/// Validate `implement` blocks against the interfaces they claim to satisfy and
/// check that struct getters/setters agree with their backing field's type.
///
/// Runs after type registration so user-defined interface and field types are
/// already known. **Both** forms are checked for method coverage — the standalone
/// `implement … for …` block and the inline `type … implement I { }` clause
/// (decision 58). Interfaces neither declared in this program nor ambient
/// (decision 539 (6): `Display`, `Closeable`) — an imported one — are skipped:
/// their method sets are not visible here.
fn validateProgram(env: *Env, program: ast.Program) InferError!void {
    var interfaces = std.StringHashMap(ast.BehaviorDecl).init(env.arena);
    defer interfaces.deinit();
    for (program.decls) |decl| switch (decl) {
        .behavior => |d| try interfaces.put(d.name, d),
        else => {},
    };
    // Decision 539 (6) — an ambient behavior of `primitives.bp`'s compiler section (`Display`,
    // `Closeable`) is checked as one this program declares, unless the
    // program declares or imports its own of that name.
    var ait = env.ambientBehaviorDecls.iterator();
    while (ait.next()) |e| {
        if (interfaces.contains(e.key_ptr.*) or env.importedBehaviorDecls.contains(e.key_ptr.*)) continue;
        try interfaces.put(e.key_ptr.*, e.value_ptr.*);
    }

    for (program.decls) |decl| switch (decl) {
        .implement => |impl| try validateImplement(env, impl, interfaces),
        .type_ => |td| try validateInlineImplements(env, td, interfaces, program),
        else => {},
    };
    // Decision 800 — every implementor's member against its contract.
    try checkSignaturesWith(env, program, &interfaces);
}

/// Decision 58 — an inline `implement <Behavior> { }` on a type declaration
/// asserts that the type satisfies the behavior, and nothing verified the
/// assertion: `type Money(cents: i32) implement Display { }` **checked**, with
/// `Display` declared in the same file and with the long-registered `Generator`
/// too. Only the separate block was covered (the
/// `implement_missing_a_required_interface_method` snapshot family), so this was
/// the same family as decisions 37, 38 and 45 — the checker accepting what a
/// backend then answers on its own.
///
/// It is the same coverage check `validateImplement` runs, applied to the inline
/// form; decision 58 settles that it is not a question about meaning.
///
/// A required method is one the behavior declares with **no body** — a
/// `default fn` carries its own, so implementing it is optional. It is satisfied
/// by a member of the type's own body, or by a member of any separate
/// `implement <Behavior> for <this type>` block in the same program: writing both
/// halves is legal and the inline clause is what names the contract.
///
/// Interfaces this program neither declares nor reads ambient are skipped,
/// exactly as `validateImplement` skips them; an ambient behavior of
/// `primitives.bp`'s compiler section (`Display`, `Closeable`) is checked as a declared one
/// (decision 539 (6)).
fn validateInlineImplements(
    env: *Env,
    td: ast.TypeDecl,
    interfaces: std.StringHashMap(ast.BehaviorDecl),
    program: ast.Program,
) InferError!void {
    for (td.implement) |iface| {
        const iname = interfaceRefName(iface);
        const d = interfaces.get(iname) orelse continue;
        for (d.methods) |am| {
            if (am.body != null) continue; // a default method — optional
            if (typeDeclProvidesMethod(td, am.name)) continue;
            if (separateImplementProvides(program, td.name, iname, am.name)) continue;
            env.lastError = locatedAt(TypeError.missingMethod(td.name, iname, am.name), td.loc);
            return error.TypeError;
        }
    }
}

/// True when the type's own body provides `name` with a body. A `declare fn`
/// member is an abstract slot typed from its signature, so it provides nothing.
fn typeDeclProvidesMethod(td: ast.TypeDecl, name: []const u8) bool {
    for (td.methods) |m| {
        if (!std.mem.eql(u8, m.name, name)) continue;
        if (m.body != null) return true;
    }
    return false;
}

/// True when some `implement <iname> for <target>` block in this program provides
/// `name` — either unqualified, or qualified with `iname` itself.
fn separateImplementProvides(
    program: ast.Program,
    target: []const u8,
    iname: []const u8,
    name: []const u8,
) bool {
    for (program.decls) |decl| {
        const impl = switch (decl) {
            .implement => |i| i,
            else => continue,
        };
        if (!std.mem.eql(u8, impl.target, target)) continue;
        if (!implementsInterface(impl, iname)) continue;
        for (impl.methods) |m| {
            if (!std.mem.eql(u8, m.name, name)) continue;
            const q = m.qualifier orelse return true;
            if (std.mem.eql(u8, q, iname)) return true;
        }
    }
    return false;
}

/// True when interface `d` declares a method named `name` (abstract or default).
fn interfaceHasMethod(d: ast.BehaviorDecl, name: []const u8) bool {
    for (d.methods) |m| {
        if (std.mem.eql(u8, m.name, name)) return true;
    }
    return false;
}

/// The bare name of an interface type ref — the identifier the interface was
/// declared under. Generic interfaces (`Iface<A, B>`, `@Renderable`) reduce to
/// their head name (`Iface`, `Context`); non-name refs yield "".
fn interfaceRefName(ref: ast.TypeRef) []const u8 {
    return switch (ref) {
        .named => |n| n,
        .generic => |g| g.name,
        else => "",
    };
}

/// True when `name` is one of the interfaces this implement block declares.
fn implementsInterface(impl: ast.ImplementDecl, name: []const u8) bool {
    for (impl.interfaces) |iface| {
        if (std.mem.eql(u8, interfaceRefName(iface), name)) return true;
    }
    return false;
}

fn validateImplement(
    env: *Env,
    impl: ast.ImplementDecl,
    interfaces: std.StringHashMap(ast.BehaviorDecl),
) InferError!void {
    // Per-method checks: qualifier validity, method existence, ambiguity.
    for (impl.methods) |m| {
        if (m.qualifier) |q| {
            // The qualifier must name an interface this block implements.
            if (!implementsInterface(impl, q)) {
                env.lastError = locatedAt(TypeError.unknownInterface(q, m.name), m.loc);
                return error.TypeError;
            }
            // If the interface is visible, it must declare the method.
            if (interfaces.get(q)) |d| {
                if (!interfaceHasMethod(d, m.name)) {
                    env.lastError = locatedAt(TypeError.unknownMethod(impl.target, m.name), m.loc);
                    return error.TypeError;
                }
            }
        } else {
            // Unqualified: find which implemented interfaces declare this method.
            var first: ?[]const u8 = null;
            var second: ?[]const u8 = null;
            for (impl.interfaces) |iface| {
                const iname = interfaceRefName(iface);
                const d = interfaces.get(iname) orelse continue;
                if (!interfaceHasMethod(d, m.name)) continue;
                if (first == null) {
                    first = iname;
                } else if (second == null) {
                    second = iname;
                }
            }
            if (first == null) {
                env.lastError = locatedAt(TypeError.unknownMethod(impl.target, m.name), m.loc);
                return error.TypeError;
            }
            if (second) |snd| {
                env.lastError = locatedAt(TypeError.ambiguousMethod(m.name, first.?, snd), m.loc);
                return error.TypeError;
            }
        }
    }

    // Coverage: every abstract method of every implemented interface must be met.
    for (impl.interfaces) |iface| {
        const iname = interfaceRefName(iface);
        const d = interfaces.get(iname) orelse continue;
        for (d.methods) |am| {
            if (am.body != null) continue; // default method — implementing it is optional
            var covered = false;
            for (impl.methods) |m| {
                if (!std.mem.eql(u8, m.name, am.name)) continue;
                if (m.qualifier) |q| {
                    if (std.mem.eql(u8, q, iname)) {
                        covered = true;
                        break;
                    }
                } else {
                    covered = true;
                    break;
                }
            }
            // Decision 799 (1) — a primitive's own member meets a contract's
            // required one: `StringShout implement Shout for string {}` over
            // `fn length(self: Self) -> i32;` is met by `string`'s `length`.
            if (!covered and primitiveAnswers(env, impl.target, am.name)) covered = true;
            // Decision 872 (2) — a record's own method meets it alike, compared
            // with the contract's member in `checkImplementSignatures`.
            if (!covered and env.getInherentMethodDecl(impl.target, am.name) != null) covered = true;
            if (!covered) {
                env.lastError = locatedAt(TypeError.missingMethod(impl.target, iname, am.name), impl.loc);
                return error.TypeError;
            }
        }
    }
}

/// Whether the primitive `typeName` answers `member` by a member of its own —
/// one its std behavior (`String` for `string`), or what that extends,
/// declares as a method or a field.
fn primitiveAnswers(env: *Env, typeName: []const u8, member: []const u8) bool {
    var current: ?[]const u8 = primitiveInterfaceName(typeName) orelse return false;
    var guard: usize = 0;
    while (current) |cname| : (guard += 1) {
        if (guard >= 16) return false;
        const decl = env.stdBehaviorBase.get(cname) orelse env.assocInterfaceDecls.get(cname) orelse return false;
        for (decl.methods) |m| if (std.mem.eql(u8, m.name, member)) return true;
        for (decl.fields) |f| if (std.mem.eql(u8, f.name, member)) return true;
        current = if (decl.extends.len > 0) decl.extends[0] else null;
    }
    return false;
}

// ── decision 800: an implementor's member against its contract ────────────────

/// A name a signature renders as something else (decision 800): a contract's
/// type parameter as the argument the `implement` clause gives it, an
/// implementor member's own type parameter as the contract member's.
const SigName = struct { name: []const u8, as: []const u8 };

/// The scope a signature renders in: `Self` read as the implementing type,
/// and the names `SigName` rewrites.
const SigScope = struct {
    env: *Env,
    self_name: []const u8,
    names: []const SigName = &.{},
};

/// `t` as the signature check compares it (decision 800): `Self` the
/// implementing type, a renamed name replaced, a type alias read through,
/// `Array<T>` written `T[]` and a prelude wrapper with or without its `@` one
/// spelling. Anything else is the type as written — identical means
/// identical, no variance.
fn writeSigType(w: *std.Io.Writer, t: ast.TypeRef, s: SigScope, depth: u8) std.Io.Writer.Error!void {
    if (t.unionMembers()) |members| {
        for (members, 0..) |m, i| {
            if (i > 0) try w.writeAll(" | ");
            try writeSigType(w, m, s, depth);
        }
        return;
    }
    if (t.isSelf()) return w.writeAll(s.self_name);
    switch (t) {
        .named => |n| {
            for (s.names) |sn| if (std.mem.eql(u8, sn.name, n)) return w.writeAll(sn.as);
            if (depth < 8) if (s.env.lookupTypeAlias(n)) |a| if (a.genericParams.len == 0)
                return writeSigType(w, a.target, s, depth + 1);
            try w.writeAll(n);
        },
        .array => |e| {
            try writeSigType(w, e.*, s, depth);
            try w.writeAll("[]");
        },
        .tuple_ => |elems| {
            try w.writeAll("#(");
            for (elems, 0..) |e, i| {
                if (i > 0) try w.writeAll(", ");
                try writeSigType(w, e, s, depth);
            }
            try w.writeAll(")");
        },
        .labeledTuple => |lt| {
            try w.writeAll("#(");
            for (lt.elems, 0..) |e, i| {
                if (i > 0) try w.writeAll(", ");
                try w.print("{s}: ", .{lt.labels[i]});
                try writeSigType(w, e, s, depth);
            }
            try w.writeAll(")");
        },
        .optional => |e| {
            try w.writeAll("?");
            try writeSigType(w, e.*, s, depth);
        },
        .function => |f| {
            try w.writeAll("fn(");
            if (f.anyParams) try w.writeAll("..");
            for (f.params, 0..) |p, i| {
                if (i > 0) try w.writeAll(", ");
                try writeSigType(w, p, s, depth);
            }
            try w.writeAll(") -> ");
            try writeSigType(w, f.returnType.*, s, depth);
        },
        .generic => |g| {
            if (g.is_builtin and g.args.len == 1 and (std.mem.eql(u8, g.name, ast.expr_type_name) or std.mem.eql(u8, g.name, ast.expr_custom_type_name))) {
                try w.writeAll("syntax ");
                return writeSigType(w, g.args[0], s, depth);
            }
            if (g.args.len == 1 and std.mem.eql(u8, g.name, "array")) {
                try writeSigType(w, g.args[0], s, depth);
                return w.writeAll("[]");
            }
            if (!g.is_builtin and depth < 8) if (s.env.lookupTypeAlias(g.name)) |a| if (a.genericParams.len == g.args.len) {
                const names = s.env.arena.alloc(SigName, s.names.len + g.args.len) catch return error.WriteFailed;
                for (a.genericParams, g.args, 0..) |gp, arg, i| names[i] = .{
                    .name = gp.name,
                    .as = sigTypeText(arg, s) catch return error.WriteFailed,
                };
                @memcpy(names[g.args.len..], s.names);
                return writeSigType(w, a.target, .{ .env = s.env, .self_name = s.self_name, .names = names }, depth + 1);
            };
            try w.print("{s}<", .{g.name});
            for (g.args, 0..) |a, i| {
                if (i > 0) try w.writeAll(", ");
                try writeSigType(w, a, s, depth);
            }
            try w.writeAll(">");
        },
        .typeparam => |constraints| {
            try w.writeAll("type");
            for (constraints, 0..) |c, i| {
                try w.writeAll(if (i == 0) "<" else " | ");
                try writeSigType(w, c, s, depth);
            }
            if (constraints.len > 0) try w.writeAll(">");
        },
    }
}

/// A `syntax x: T` parameter's type: the tree type the parser keeps for it.
fn isSyntaxTypeRef(t: ast.TypeRef) bool {
    return switch (t) {
        .generic => |g| g.is_builtin and g.args.len == 1 and (std.mem.eql(u8, g.name, ast.expr_type_name) or std.mem.eql(u8, g.name, ast.expr_custom_type_name)),
        else => false,
    };
}

fn sigTypeText(t: ast.TypeRef, s: SigScope) (std.mem.Allocator.Error || std.Io.Writer.Error)![]const u8 {
    var out: std.Io.Writer.Allocating = .init(s.env.arena);
    try writeSigType(&out.writer, t, s, 0);
    return out.toOwnedSlice();
}

/// One member's signature, as the check reads it.
const SigMember = struct {
    name: []const u8,
    generics: []const ast.GenericParam = &.{},
    params: []const ast.Param,
    ret: ?ast.TypeRef,
    loc: ?ast.Loc = null,
    /// Names the written member reads as something else (a holder's type
    /// parameter as the block's target argument, decision 872 (2)).
    names: []const SigName = &.{},
};

/// `fn name<G>(p: T, …) -> R` in `s` — with the parameter names for the
/// refusal (`named`), or without them for the comparison (labels, parameter
/// names and defaults are free).
fn sigText(m: SigMember, s: SigScope, named: bool) (std.mem.Allocator.Error || std.Io.Writer.Error)![]const u8 {
    var out: std.Io.Writer.Allocating = .init(s.env.arena);
    const w = &out.writer;
    try w.print("fn {s}", .{m.name});
    if (m.generics.len > 0) {
        try w.writeAll("<");
        for (m.generics, 0..) |gp, i| {
            if (i > 0) try w.writeAll(", ");
            // The contract's names, positionally (`names` maps the written ones).
            var shown = gp.name;
            for (s.names) |sn| if (std.mem.eql(u8, sn.name, gp.name)) {
                shown = sn.as;
            };
            try w.writeAll(shown);
        }
        try w.writeAll(">");
    }
    try w.writeAll("(");
    for (m.params, 0..) |p, i| {
        if (i > 0) try w.writeAll(", ");
        // Decision 871 (3) — a parameter's `comptime` marker is part of the
        // signature; a `syntax` parameter writes its own (`writeSigType`).
        if (p.modifier == .@"comptime" and !isSyntaxTypeRef(p.typeRef)) try w.writeAll("comptime ");
        if (named) try w.print("{s}: ", .{p.name});
        try writeSigType(w, p.typeRef, s, 0);
    }
    try w.writeAll(") -> ");
    if (m.ret) |r| try writeSigType(w, r, s, 0) else try w.writeAll("void");
    return out.toOwnedSlice();
}

/// The behavior `name` a signature check reads: the program's own or an
/// ambient one (`interfaces`), an imported one, or one of the prelude's
/// behaviors a rule reads.
fn sigBehavior(env: *Env, interfaces: *const std.StringHashMap(ast.BehaviorDecl), name: []const u8) ?ast.BehaviorDecl {
    return interfaces.get(name) orelse env.importedBehaviorDecls.get(name) orelse env.ruleReadBehaviorDecls.get(name);
}

/// The member `name` of behavior `b` or of a behavior it extends, first found.
fn contractMember(env: *Env, interfaces: *const std.StringHashMap(ast.BehaviorDecl), b: ast.BehaviorDecl, name: []const u8, depth: u8) ?ast.BehaviorMethod {
    for (b.methods) |m| if (std.mem.eql(u8, m.name, name)) return m;
    if (depth >= 16) return null;
    for (b.extends) |sup| {
        const sb = sigBehavior(env, interfaces, sup) orelse continue;
        if (contractMember(env, interfaces, sb, name, depth + 1)) |m| return m;
    }
    return null;
}

/// The contract's type parameters as the clause `iface` gives them, in the
/// implementor's scope.
fn contractNames(b: ast.BehaviorDecl, iface: ast.TypeRef, s: SigScope) InferError![]const SigName {
    const args: []const ast.TypeRef = switch (iface) {
        .generic => |g| g.args,
        else => &.{},
    };
    if (args.len == 0 or args.len != b.genericParams.len) return &.{};
    const names = try s.env.arena.alloc(SigName, args.len);
    for (b.genericParams, args, 0..) |gp, a, i| names[i] = .{
        .name = gp.name,
        .as = sigTypeText(a, s) catch return error.OutOfMemory,
    };
    return names;
}

/// Decision 800 — `written` against the contract's member `contract`: the
/// same number of parameters, each parameter's type and the return type
/// identical with `Self` the implementing type; labels, parameter names and
/// defaults free; no variance. A difference is refused at the member,
/// `implement-signature-differs`, naming both signatures.
fn checkMemberSignature(env: *Env, behavior: []const u8, self_name: []const u8, contract_names: []const SigName, contract: ast.BehaviorMethod, written: SigMember) InferError!void {
    // Decision 8 (A1) — a plain implementer of a generic contract reads
    // `Self<…>` as `Self`: a type parameter the member introduces in
    // `Self<…>`'s arguments is bound to the clause's argument at its place
    // (`map<U>(…) -> Self<U>` under `implement Mappable<i32>` is `U = i32`),
    // and leaves the member's type parameters.
    var names: std.ArrayListUnmanaged(SigName) = .empty;
    try names.appendSlice(env.arena, contract_names);
    var generics: std.ArrayListUnmanaged(ast.GenericParam) = .empty;
    if (contract_names.len > 0 and std.mem.indexOfScalar(u8, self_name, '<') == null) {
        for (contract.params) |p| try bindSelfArgs(env, &names, contract_names, contract.genericParams, p.typeRef);
        if (contract.returnType) |r| try bindSelfArgs(env, &names, contract_names, contract.genericParams, r);
    }
    for (contract.genericParams) |gp| {
        if (sigNameIndex(names.items[contract_names.len..], gp.name) == null) try generics.append(env.arena, gp);
    }
    const cs: SigScope = .{ .env = env, .self_name = self_name, .names = names.items };
    // The member's own type parameters read as the contract member's, by position.
    var ws: SigScope = .{ .env = env, .self_name = self_name, .names = written.names };
    if (written.generics.len == generics.items.len and written.generics.len > 0) {
        const wnames = try env.arena.alloc(SigName, written.generics.len + written.names.len);
        for (written.generics, generics.items, 0..) |wg, cg, i| wnames[i] = .{ .name = wg.name, .as = cg.name };
        @memcpy(wnames[written.generics.len..], written.names);
        ws.names = wnames;
    }
    const cm: SigMember = .{ .name = contract.name, .generics = generics.items, .params = contract.params, .ret = contract.returnType };
    const ck = sigText(cm, cs, false) catch return error.OutOfMemory;
    const wk = sigText(written, ws, false) catch return error.OutOfMemory;
    if (std.mem.eql(u8, ck, wk)) return;
    return implError(env, written.loc, try std.fmt.allocPrint(
        env.arena,
        "{s}: `{s}.{s}` does not match the contract `{s}` — contract: {s} · written: {s}",
        .{
            diagnostics.implement_signature_differs,
            self_name,
            written.name,
            behavior,
            sigText(cm, cs, true) catch return error.OutOfMemory,
            sigText(written, ws, true) catch return error.OutOfMemory,
        },
    ), "Write the member with the contract's parameter types and return type, `Self` the implementing type — labels, parameter names and defaults are free.");
}

fn sigNameIndex(names: []const SigName, name: []const u8) ?usize {
    for (names, 0..) |n, i| if (std.mem.eql(u8, n.name, name)) return i;
    return null;
}

/// Decision 8 (A1) — each `Self<…>` in `t` whose argument at place `i` is one
/// of the member's own type parameters binds it to the contract argument at
/// place `i` (`contract_names[i]`).
fn bindSelfArgs(env: *Env, names: *std.ArrayListUnmanaged(SigName), contract_names: []const SigName, member_generics: []const ast.GenericParam, t: ast.TypeRef) InferError!void {
    switch (t) {
        .generic => |g| {
            if (t.isSelf()) {
                for (g.args, 0..) |a, i| {
                    if (i >= contract_names.len or a != .named) continue;
                    for (member_generics) |gp| if (std.mem.eql(u8, gp.name, a.named) and sigNameIndex(names.items, gp.name) == null)
                        try names.append(env.arena, .{ .name = gp.name, .as = contract_names[i].as });
                }
            }
            for (g.args) |a| try bindSelfArgs(env, names, contract_names, member_generics, a);
        },
        .array, .optional => |e| try bindSelfArgs(env, names, contract_names, member_generics, e.*),
        .tuple_ => |elems| for (elems) |e| try bindSelfArgs(env, names, contract_names, member_generics, e),
        .labeledTuple => |lt| for (lt.elems) |e| try bindSelfArgs(env, names, contract_names, member_generics, e),
        .function => |f| {
            for (f.params) |e| try bindSelfArgs(env, names, contract_names, member_generics, e);
            try bindSelfArgs(env, names, contract_names, member_generics, f.returnType.*);
        },
        else => {},
    }
}

/// `Name` or `Name<T, …>` — what `Self` reads as in a type's members.
fn sigSelfName(env: *Env, name: []const u8, generics: []const ast.GenericParam) InferError![]const u8 {
    if (generics.len == 0) return name;
    var out: std.Io.Writer.Allocating = .init(env.arena);
    const w = &out.writer;
    w.print("{s}<", .{name}) catch return error.OutOfMemory;
    for (generics, 0..) |gp, i| w.print("{s}{s}", .{ if (i > 0) ", " else "", gp.name }) catch return error.OutOfMemory;
    w.writeAll(">") catch return error.OutOfMemory;
    return out.toOwnedSlice() catch return error.OutOfMemory;
}

/// Decision 800 (3) — a type's own `implement` clause: each member the type
/// declares that a contract it names (or one that contract extends) declares.
fn checkTypeSignatures(env: *Env, td: ast.TypeDecl, interfaces: *const std.StringHashMap(ast.BehaviorDecl)) InferError!void {
    if (td.implement.len == 0) return;
    const self_name = try sigSelfName(env, td.name, td.genericParams);
    for (td.implement) |iface| {
        const b = sigBehavior(env, interfaces, interfaceRefName(iface)) orelse continue;
        const names = try contractNames(b, iface, .{ .env = env, .self_name = self_name });
        for (td.methods) |m| {
            const contract = contractMember(env, interfaces, b, m.name, 0) orelse continue;
            try checkMemberSignature(env, b.name, self_name, names, contract, .{
                .name = m.name,
                .generics = m.genericParams,
                .params = m.params,
                .ret = m.returnType,
                .loc = m.nameLoc,
            });
        }
    }
}

/// Decision 800 (3) — an extension block (`Sym implement B for T`): each
/// member against the contract that declares it (its qualifier's, when
/// written). Decision 872 (2) — a required member the block does not write is
/// the type's own (a primitive's, a record's), compared alike at the block;
/// decision 886 — a record's own method meets it only when it is `pub` or the
/// block is in the type's module, else `method-not-pub` at the block.
fn checkImplementSignatures(env: *Env, impl: ast.ImplementDecl, interfaces: *const std.StringHashMap(ast.BehaviorDecl)) InferError!void {
    for (impl.methods) |m| for (impl.interfaces) |iface| {
        const iname = interfaceRefName(iface);
        if (m.qualifier) |q| if (!std.mem.eql(u8, q, iname)) continue;
        const b = sigBehavior(env, interfaces, iname) orelse continue;
        const contract = contractMember(env, interfaces, b, m.name, 0) orelse continue;
        const names = try contractNames(b, iface, .{ .env = env, .self_name = impl.target });
        try checkMemberSignature(env, b.name, impl.target, names, contract, .{
            .name = m.name,
            .params = m.params,
            .ret = m.returnType,
            .loc = m.loc,
        });
    };
    for (impl.interfaces) |iface| {
        const iname = interfaceRefName(iface);
        const b = sigBehavior(env, interfaces, iname) orelse continue;
        for (b.methods) |am| {
            if (am.body != null) continue;
            if (blockWrites(impl, iname, am.name)) continue;
            const own = try suppliedMember(env, impl, am.name) orelse continue;
            if (own.private_to) |module| {
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}.{s}` is private to module `{s}` — `{s} implement {s} for {s}` is written in another module and cannot meet `{s}.{s}` with it", .{ diagnostics.method_not_pub, impl.target, am.name, module, impl.name, iname, impl.target, iname, am.name });
                return implError(env, impl.loc, msg, try std.fmt.allocPrint(env.arena, "Write `pub fn {s}` in `{s}`, or write the block in `{s}` (decision 886).", .{ am.name, module, module }));
            }
            const names = try contractNames(b, iface, .{ .env = env, .self_name = impl.target });
            try checkMemberSignature(env, b.name, impl.target, names, am, own.member);
        }
    }
}

/// Whether the block writes `name` for contract `iname` (unqualified, or
/// qualified with `iname`).
fn blockWrites(impl: ast.ImplementDecl, iname: []const u8, name: []const u8) bool {
    for (impl.methods) |m| {
        if (!std.mem.eql(u8, m.name, name)) continue;
        const q = m.qualifier orelse return true;
        if (std.mem.eql(u8, q, iname)) return true;
    }
    return false;
}

/// The member a type supplies to an extension block's contract (decision 872
/// (2)): a record's own method, or a primitive's own member (its type's
/// table and what that extends), its signature located at the block. A
/// record's method without `pub` of a type another module declares is
/// `private_to` that module (decision 886). The prelude's methods are its
/// `pub` surface (859 (3)).
const Supplied = struct { member: SigMember, private_to: ?[]const u8 = null };

fn suppliedMember(env: *Env, impl: ast.ImplementDecl, name: []const u8) InferError!?Supplied {
    if (env.getInherentMethodDecl(impl.target, name)) |m| {
        var supplied: Supplied = .{ .member = .{ .name = name, .generics = m.genericParams, .params = m.params, .ret = m.returnType, .loc = impl.loc } };
        if (!m.isPub) if (env.importedTypeDecls.get(impl.target)) |it| {
            supplied.private_to = it.module;
        };
        if (env.lookupTypeDef(impl.target)) |td| switch (td) {
            .record => |r| supplied.member.names = try holderNames(env, r.genericParams, impl.targetArgs),
            else => {},
        };
        return supplied;
    }
    var current: ?[]const u8 = primitiveInterfaceName(impl.target) orelse return null;
    var guard: usize = 0;
    while (current) |cname| : (guard += 1) {
        if (guard >= 16) return null;
        const decl = env.stdBehaviorBase.get(cname) orelse env.assocInterfaceDecls.get(cname) orelse return null;
        for (decl.methods) |m| {
            if (m.adoptedBy != null or !std.mem.eql(u8, m.name, name)) continue;
            const gps = try env.arena.alloc([]const u8, decl.genericParams.len);
            for (decl.genericParams, 0..) |gp, i| gps[i] = gp.name;
            return .{ .member = .{ .name = name, .generics = m.genericParams, .params = m.params, .ret = m.returnType, .loc = impl.loc, .names = try holderNames(env, gps, impl.targetArgs) } };
        }
        // A property (`array`'s `length`) is no signature to compare.
        for (decl.fields) |f| if (std.mem.eql(u8, f.name, name)) return null;
        current = if (decl.extends.len > 0) decl.extends[0] else null;
    }
    return null;
}

/// The holder's type parameters read as the block's target arguments
/// (`array<T>`'s `T` as `E` in `… for array<E>`).
fn holderNames(env: *Env, params: []const []const u8, args: []const ast.TypeRef) InferError![]const SigName {
    if (params.len == 0 or params.len != args.len) return &.{};
    const names = try env.arena.alloc(SigName, params.len);
    for (params, args, 0..) |p, a, i| names[i] = .{ .name = p, .as = sigTypeText(a, .{ .env = env, .self_name = "" }) catch return error.OutOfMemory };
    return names;
}

/// Decision 800 over a whole program — every type's own clause and every
/// extension block. `registerStdlib` runs it on the prelude's primitive
/// types, which its inference leaves out.
pub fn checkProgramSignatures(env: *Env, program: ast.Program) InferError!void {
    var interfaces = std.StringHashMap(ast.BehaviorDecl).init(env.arena);
    defer interfaces.deinit();
    for (program.decls) |decl| switch (decl) {
        .behavior => |d| try interfaces.put(d.name, d),
        else => {},
    };
    try checkSignaturesWith(env, program, &interfaces);
}

fn checkSignaturesWith(env: *Env, program: ast.Program, interfaces: *const std.StringHashMap(ast.BehaviorDecl)) InferError!void {
    for (program.decls) |decl| switch (decl) {
        .implement => |impl| try checkImplementSignatures(env, impl, interfaces),
        .type_ => |td| try checkTypeSignatures(env, td, interfaces),
        else => {},
    };
}

// ── stdlib preload ────────────────────────────────────────────────────────────

/// Parse and register all stdlib interface declarations into `env`.
///
/// The three stdlib source files are embedded at compile time via `@embedFile`.
/// Each file is lexed and parsed in a temporary arena that is freed immediately
/// after inference; the resulting type bindings live in `env.arena`.
fn inferDeclTyped(env: *Env, decl: ast.DeclKind) InferError!?TypedBinding {
    switch (decl) {
        .val => |v| {
            try refuseValuelessIf(env, v.value.*);
            // 01 R8 — `ValDecl` carries no location for its annotation; an
            // unlocated refusal there reds at the value.
            const annType: ?*T.Type = if (v.typeAnnotation) |ann|
                resolveAnnotationAt(env, ann, v.value.getLoc(), v.typeLoc) catch |err| return locateTypeRefError(env, err, v.value.getLoc())
            else
                null;
            if (annType == null) try refuseUntypedLambdaBinding(env, v.value.*);
            // When binding a lambda to a `fn(...) -> ...` annotation, feed the
            // annotation into the lambda so its params are typed from context.
            const prevDeclSite = env.contextDeclSite;
            env.contextDeclSite = if (v.mutable) null else v.value.getLoc();
            defer env.contextDeclSite = prevDeclSite;
            const typedExpr = if (annType != null and v.value.* == .function)
                try inferFunctionExprExpected(env, v.value.function, v.value.function.loc, annType, false)
            else
                // 00 · 01-checker — the annotation is this position's expected
                // type, so `val t: Token = .Color.Red.500;` resolves the path
                // on `Token`.
                try inferExprTypedExpecting(env, v.value.*, annType);
            const ty = typedExpr.getType();
            try noteContextDeclaration(env, v, annType orelse ty);
            // A behavior annotation takes an implementer (`val l: Lookup =
            // memory();`), as a parameter and a return do (`unifyArgument`).
            if (annType) |at| try unifyArgument(env, at, ty, v.value.getLoc());
            // The annotation is the DECLARED type — bind it, not the RHS type
            // (`val head: ?i32 = 5;` must bind `?i32`, or a later
            // `option.map(head, f)` sees a bare `i32`).
            const bindTy = annType orelse ty;
            if (v.isPub and annType == null) try refusePublicUnknown(env, bindTy, v.name, "val", v.value.getLoc());
            if (annType == null and isEmptyArrayLiteral(v.value.*))
                try env.birthWarnings.append(env.arena, .{ .name = v.name, .mutable = v.mutable, .type_ = bindTy, .loc = v.value.getLoc() });
            try validateMemoryAnnotations(env, v, bindTy);
            try noteTypeValue(env, v.name, v.value.*, annType == null and !v.mutable);
            if (v.mutable) try env.bind(v.name, bindTy) else try env.bindVal(v.name, bindTy);
            return .{ .name = v.name, .type_ = bindTy, .typedExpr = typedExpr, .decl = decl };
        },
        .@"fn" => |f| {
            const ty = try inferFnDecl(env, f);
            if (f.isPub and f.returnType == null and f.body.len > 0) {
                const d = ty.deref();
                if (d.* == .func) try refusePublicUnknown(env, d.func.ret, f.name, "fn", f.body[0].expr.getLoc());
            }
            try env.bind(f.name, ty);
            return .{ .name = f.name, .type_ = ty, .typedExpr = null, .decl = decl };
        },
        .type_ => |tdecl| switch (tdecl.shape) {
            .record => {
                const typeName = try buildRecordDeclName(env, tdecl);
                const typeId = if (env.lookupTypeDef(tdecl.name)) |td| switch (td) {
                    .record => |rec| rec.id,
                    else => null,
                } else null;
                try inferTypeMethods(env, tdecl.name, tdecl.genericParams, tdecl.methods);
                return .{ .name = tdecl.name, .type_ = try env.namedType(typeName), .typedExpr = null, .decl = decl, .typeId = typeId };
            },
            .enum_ => {
                const typeName = try buildEnumDeclName(env, tdecl);
                const typeId = if (env.lookupTypeDef(tdecl.name)) |td| switch (td) {
                    .enum_ => |en| en.id,
                    else => null,
                } else null;
                try inferTypeMethods(env, tdecl.name, tdecl.genericParams, tdecl.methods);
                return .{ .name = tdecl.name, .type_ = try env.namedType(typeName), .typedExpr = null, .decl = decl, .typeId = typeId };
            },
        },
        .behavior => |d| {
            const typeName = try buildInterfaceDeclName(env, d);
            try registerInterfaceAssociatedFns(env, d);
            try inferBehaviorDefaultBodies(env, d);
            // Decision 641 — a primitive type's member table binds no name:
            // `string` stays the type `registerBuiltins` bound.
            if (d.primitiveType) return null;
            return .{ .name = d.name, .type_ = try env.namedType(typeName), .typedExpr = null, .decl = decl };
        },
        // Handled in `inferProgramTyped` — each import name is looked up in env.
        // `from "std"` imports must be marked here too — the untyped path
        // (tests, LSP) otherwise leaves qualified-call receivers unbound.
        .use => |u| {
            _ = try markStdImports(env, u);
            return null;
        },
        // A test block produces no binding, but its body must type-check.
        .@"test" => |t| {
            try inferTestDecl(env, t);
            return null;
        },
        // An alias binds no value; its binding carries the target's type for
        // the tooling (hover, the `.d.ts`). `registerExports` keeps it out of
        // the value exports.
        .typeAlias => |a| {
            const ty = try checkTypeAliasDecl(env, a);
            return .{ .name = a.name, .type_ = ty, .typedExpr = null, .decl = decl };
        },
        else => return null,
    }
}

/// Whether `ty` mentions `unknown` anywhere — at its head, in a type argument,
/// a union member, a function's parameters or return, or a record field.
fn typeContainsUnknown(ty: *T.Type) bool {
    const t = ty.deref();
    return switch (t.*) {
        .named => |n| blk: {
            if (std.mem.eql(u8, n.name, ast.unknown_type_name)) break :blk true;
            for (n.args) |a| if (typeContainsUnknown(a)) break :blk true;
            break :blk false;
        },
        .func => |f| blk: {
            for (f.params) |p| if (typeContainsUnknown(p)) break :blk true;
            break :blk typeContainsUnknown(f.ret);
        },
        .union_ => |ms| blk: {
            for (ms) |m| if (typeContainsUnknown(m)) break :blk true;
            break :blk false;
        },
        .record => |fs| blk: {
            for (fs) |f| if (typeContainsUnknown(f.type_)) break :blk true;
            break :blk false;
        },
        .typeVar => false,
    };
}

/// 01 step 12 — the written spelling (`Token.Layout.Break`) of the first
/// section enum declaring a unit leaf `name`, or null.
fn sectionOwningLeaf(env: *Env, name: []const u8) InferError!?[]const u8 {
    var it = env.typeDefs.iterator();
    while (it.next()) |e| {
        const key = e.key_ptr.*;
        if (!std.mem.startsWith(u8, key, "__")) continue;
        const td = e.value_ptr.*;
        if (td != .enum_) continue;
        for (td.enum_.variants) |v| {
            if (!std.mem.eql(u8, v.name, name) or v.fields.len != 0) continue;
            return try std.mem.replaceOwned(u8, env.arena, key[2..], "__", ".");
        }
    }
    return null;
}

/// 01 step 12 — record that enum `enumName` declares `variant`, under its
/// qualified name and in the bare name's claimant list.
fn noteVariantClaim(env: *Env, enumName: []const u8, variant: []const u8, ctorType: *T.Type) InferError!void {
    try env.variantCtors.put(try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ enumName, variant }), ctorType);
    const prev = env.variantClaims.get(variant) orelse &.{};
    for (prev) |p| if (std.mem.eql(u8, p, enumName)) return;
    const next = try env.arena.alloc([]const u8, prev.len + 1);
    @memcpy(next[0..prev.len], prev);
    next[prev.len] = enumName;
    try env.variantClaims.put(variant, next);
}

/// 01 step 12 — a bare variant name two enums claim is a **named refusal**,
/// never the flat table's last writer (decision 67). Only a use that reached
/// a claimant's constructor through the table is judged: a local or a fn
/// that shadows the name is not a variant use.
fn refuseAmbiguousVariant(env: *Env, name: []const u8, ty: *T.Type, loc: ast.Loc) InferError!void {
    const claims = env.variantClaims.get(name) orelse return;
    if (claims.len < 2) return;
    // A name that is also a type or a behavior (`Array.range(…)`) is read as
    // that, not as a variant.
    if (env.lookupTypeDef(name) != null or env.assocInterfaceDecls.contains(name)) return;
    const isCtor = for (claims) |c| {
        const q = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ c, name });
        if (env.variantCtors.get(q)) |ct| if (ct == ty) break true;
    } else false;
    if (!isCtor) return;
    // The erlang emitter's own refusal of the same program reads this way
    // (`modules/variant/cells/variant_name_ambiguous`); the checker now says it first, for
    // every target.
    var names: std.ArrayListUnmanaged(u8) = .empty;
    var spellings: std.ArrayListUnmanaged(u8) = .empty;
    for (claims, 0..) |c, i| {
        if (i > 0) {
            try names.appendSlice(env.arena, " and of ");
            try spellings.appendSlice(env.arena, " or ");
        }
        try names.print(env.arena, "`{s}`", .{c});
        try spellings.print(env.arena, "`{s}.{s}`", .{ c, name });
    }
    const msg = try std.fmt.allocPrint(env.arena, "`{s}` is a variant of {s}, and nothing here says which — write {s}", .{ name, names.items, spellings.items });
    env.lastError = TypeError.custom(msg, "A bare variant name is resolved by the type its position expects; where nothing does, the qualified name says which enum is meant (decision 67: no silent pick).").withLoc(loc);
    return error.TypeError;
}

/// Decision 587 — a bare variant in expression position (`Two(t)`, `Red`) is
/// a located refusal naming the spellings that say which enum is meant:
/// `E.Two(t)`, and `.Two(t)` where the position expects `E`. A bare variant
/// stays a `case` pattern's (decision 8), and a local or a function that
/// shadows the name is not a variant use. `payload` is true for a call.
fn refuseBareVariant(env: *Env, name: []const u8, ty: *T.Type, loc: ast.Loc, payload: bool) InferError!void {
    const claims = env.variantClaims.get(name) orelse return;
    if (claims.len == 0) return;
    if (env.lookupTypeDef(name) != null or env.assocInterfaceDecls.contains(name)) return;
    if (env.localBindDepth(name) != null) return;
    const isCtor = for (claims) |c| {
        const q = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ c, name });
        if (env.variantCtors.get(q)) |ct| if (ct == ty) break true;
    } else false;
    if (!isCtor) return;
    const args: []const u8 = if (payload) "(…)" else "";
    var spellings: std.ArrayListUnmanaged(u8) = .empty;
    // An enum whose name no source can spell (`__`-mangled, a prelude's
    // internal one) is no spelling to offer.
    for (claims) |c| {
        if (std.mem.startsWith(u8, c, "__")) continue;
        if (spellings.items.len > 0) try spellings.appendSlice(env.arena, " or ");
        try spellings.print(env.arena, "`{s}.{s}{s}`", .{ c, name, args });
    }
    if (spellings.items.len == 0) try spellings.print(env.arena, "`{s}.{s}{s}`", .{ claims[0], name, args });
    const msg = try std.fmt.allocPrint(
        env.arena,
        "`{s}` is a variant, and a bare variant is no expression — write {s}, or `.{s}{s}` where the position expects the enum",
        .{ name, spellings.items, name, args },
    );
    env.lastError = TypeError.custom(msg, "A variant is built through its enum (`Shape.Square(2)`), or by its leading dot where the expected type names the enum; the bare name is a `case` pattern's only (decision 587).").withLoc(loc);
    return error.TypeError;
}

/// 01 step 9 — attach `loc` when the declaration recorded one (a synthesised
/// declaration carries `{0, 0}` and stays unlocated rather than point at
/// line 0).
fn locatedAt(err: TypeError, loc: ast.Loc) TypeError {
    if (loc.line == 0) return err;
    return err.withLoc(loc);
}

/// An unbound name, located. 01 step 13 — when the name was a local of a body
/// already inferred (`Env.closedLocals`), the message names that body: the
/// name existed, in another function, and a local ends with its body.
fn unboundAt(env: *Env, name: []const u8, loc: ast.Loc) InferError!TypeError {
    // An import whose module was refused earlier in the build: the name is
    // not unbound — its module did not check, and that module's own error is
    // the one to fix. Located at the import item, so every use of the item
    // answers the same line.
    if (env.failedImports.get(name)) |f| {
        // One wording for a name the module declares and for the module
        // itself as a namespace: a refused module exports nothing, so
        // `import {components.Card};` cannot tell the two apart.
        const msg = try std.fmt.allocPrint(
            env.arena,
            "{s}: `{s}` comes from `{s}`, which failed to check — its own errors are reported there ({s})",
            .{ diagnostics.import_of_failed_module, name, f.module, env.diagLabelOf(f.module) },
        );
        const hint = try std.fmt.allocPrint(env.arena, "Fix the errors reported in `{s}`; this module is checked against it once it checks.", .{f.module});
        return TypeError.custom(msg, hint).withLoc(f.loc);
    }
    if (env.namespaces.ambiguous.get(name)) |owners| {
        var names: std.ArrayListUnmanaged(u8) = .empty;
        for (owners, 0..) |o, i| {
            if (i > 0) try names.appendSlice(env.arena, if (i + 1 == owners.len) " and by " else ", by ");
            try names.print(env.arena, "`{s}`", .{o});
        }
        const msg = try std.fmt.allocPrint(
            env.arena,
            "{s}: `{s}` is imported from two declarations — declared `pub` by {s} — and this use does not say which",
            .{ diagnostics.ambiguous_import_use, name, names.items },
        );
        const hint = try std.fmt.allocPrint(env.arena, "Import it from the module that declares it (`import {{{s}}} from \"{s}\"`), or through the module as a namespace.", .{ name, owners[0] });
        return TypeError.custom(msg, hint).withLoc(loc);
    }
    // Decision 297 — in the branch `x is type` takes, `x` is a type: the type
    // form (`value_or_type.zig`'s `<f>__type`) has no parameter `x`.
    if (std.mem.endsWith(u8, env.currentFnName, valueOrType.twin_suffix)) {
        const original = env.currentFnName[0 .. env.currentFnName.len - valueOrType.twin_suffix.len];
        if (env.fnDecls.get(original)) |f| for (f.params) |p| {
            if (p.typeArgOf != null and std.mem.eql(u8, p.name, name)) {
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is a type where `{s} is type` holds — a type has no value to read", .{ diagnostics.type_arg_read, name, name });
                return TypeError.custom(msg, "Read the value in the branch where `x is type` is false.").withLoc(loc);
            }
        };
    }
    if (env.closedLocals.get(name)) |owner| {
        const msg = try std.fmt.allocPrint(env.arena, "unbound variable '{s}' — `{s}` is a local of `{s}`, and a local ends with its body", .{ name, name, owner });
        return TypeError.custom(msg, "Declare it where it is used, or pass it in as a parameter.").withLoc(loc);
    }
    // Decision 606 (2) — `print` and `panic` are std's, imported where used.
    if (std.mem.eql(u8, name, "print")) {
        const msg = try std.fmt.allocPrint(env.arena, "unbound variable '{s}' — `print` is std's `io.terminal.print`, imported where it is used", .{name});
        return TypeError.custom(msg, "Import it: `import {io.terminal.print} from \"std\";` (decision 606 (2)).").withLoc(loc);
    }
    if (std.mem.eql(u8, name, "panic")) {
        const msg = try std.fmt.allocPrint(env.arena, "unbound variable '{s}' — `panic` is std's `failure.panic`, imported where it is used", .{name});
        return TypeError.custom(msg, "Import it: `import {failure.panic} from \"std\";` (decision 606 (2)).").withLoc(loc);
    }
    // Decision 738 — neither `Pair` nor `Function` exists.
    if (std.mem.eql(u8, name, "Pair")) {
        const msg = try std.fmt.allocPrint(env.arena, "unbound variable '{s}' — a pair is the tuple `#(A, B)`", .{name});
        return TypeError.custom(msg, "Build it as `#(a, b)`, read it as `p._0` / `p._1` or `val #(a, b) = p` (decision 738).").withLoc(loc);
    }
    if (std.mem.eql(u8, name, "Function")) {
        const msg = try std.fmt.allocPrint(env.arena, "unbound variable '{s}' — the function combinators are std's `functions` module", .{name});
        return TypeError.custom(msg, "Import one by path: `import {functions.compose} from \"std\";` (decision 738).").withLoc(loc);
    }
    return TypeError.unboundVariable(name).withLoc(loc);
}

/// Decision 8 §2.4 — a `pub` declaration whose **inferred** type contains
/// `unknown` is an error: a public API says what it answers, and `unknown`
/// reached by inference is a type nobody chose. Writing `unknown` on purpose
/// (`pub fn parse(s: string) -> unknown`) is fine, so only a declaration with
/// no written type reaches here.
fn refusePublicUnknown(env: *Env, ty: *T.Type, name: []const u8, kw: []const u8, loc: ast.Loc) InferError!void {
    if (!typeContainsUnknown(ty)) return;
    const rendered = try snapshotMod.typeNameOf(env.arena, ty.deref());
    const msg = if (unifyMod.isUnknown(ty))
        try std.fmt.allocPrint(env.arena, "`pub {s} {s}` is inferred as `unknown`; a public declaration writes that type", .{ kw, name })
    else
        try std.fmt.allocPrint(env.arena, "`pub {s} {s}` is inferred as `{s}`, which contains `unknown`; a public declaration writes that type", .{ kw, name, rendered });
    const hint = if (std.mem.eql(u8, kw, "fn"))
        try std.fmt.allocPrint(env.arena, "A public fn states what it answers: write the return type (`-> unknown` when that is what `{s}` means to answer).", .{name})
    else
        try std.fmt.allocPrint(env.arena, "A public binding states its type: annotate it (`pub val {s}: unknown = …` when that is what it means).", .{name});
    env.lastError = TypeError.custom(msg, hint).withLoc(loc);
    return error.TypeError;
}

/// Decision 8 §1.4 — a binding born with nothing that decides its element type
/// (`var out = [];`). Recorded when the binding is inferred and turned into a
/// warning once the module is inferred (`flushBirthWarnings`), so the warning
/// can name the annotation to write with the element type the program settled
/// on — `var out: i32[] = [];` — or `unknown[]` when nothing settled it.
pub const BirthWarning = struct {
    name: []const u8,
    mutable: bool,
    type_: *T.Type,
    loc: ast.Loc,
};

fn isEmptyArrayLiteral(e: ast.Expr) bool {
    if (e != .collection) return false;
    const k = e.collection.kind;
    if (k != .arrayLit) return false;
    return k.arrayLit.elems.len == 0 and k.arrayLit.spreadExpr == null and k.arrayLit.spread == null;
}

fn flushBirthWarnings(env: *Env) InferError!void {
    for (env.birthWarnings.items) |bw| {
        const t = bw.type_.deref();
        const elem_text: []const u8 = blk: {
            if (t.* == .named and std.mem.eql(u8, t.named.name, "array") and t.named.args.len == 1) {
                const e = t.named.args[0].deref();
                if (e.* == .typeVar) break :blk ast.unknown_type_name;
                if (e.* == .named and e.named.args.len == 0) break :blk e.named.name;
                break :blk try snapshotMod.typeNameOf(env.arena, e);
            }
            break :blk ast.unknown_type_name;
        };
        const kw: []const u8 = if (bw.mutable) "var" else "val";
        const msg = try std.fmt.allocPrint(env.arena, "`{s}` is born with no element type — annotate it: `{s} {s}: {s}[] = [];`", .{ bw.name, kw, bw.name, elem_text });
        const hint = "An empty array literal decides no element type, and a type argument is decided where the value is born (decision 8 §1.4): what later uses make of it is not the declaration.";
        try env.warn(TypeError.custom(msg, hint).withLoc(bw.loc));
    }
    env.birthWarnings.clearRetainingCapacity();
}

// ── pass 1: type definition registration ─────────────────────────────────────

fn registerTypeDecl(env: *Env, decl: ast.DeclKind) InferError!void {
    switch (decl) {
        .type_ => |tdecl| {
            dropReflectionAlias(env, tdecl.name);
            // A type this module declares or imports is what its name means
            // here, in its own declaration too: `type Node { Rule(body: Node[]) }`
            // imported by another module registers while a prelude value of the
            // name (std's `compiler.Node`) still binds it, and the recursive
            // field would read "a value, not a type". Own declarations were
            // noted ahead of this (`noteOwnDecls`); this notes the imported.
            if (!env.ownTypeDecls.contains(tdecl.name)) try env.ownTypeDecls.put(env.arena, tdecl.name, tdecl.genericParams.len);
            switch (tdecl.shape) {
                .record => try registerRecord(env, tdecl),
                .enum_ => try registerEnum(env, tdecl),
            }
        },
        // An imported alias (`registerImportedTypeDecl`, the `from "std"`
        // type export) arrives here; a module's own were registered ahead of
        // every type by `registerTypeAliases`.
        .typeAlias => |a| try env.typeAliases.put(env.arena, a.name, a),
        else => {},
    }
}

/// T17 — the reflection records a `@Decl` hands out are declared under
/// internal names (`__Decl__Param`, `comptime.zig` `decl_reflection_src`) and
/// spelled `Param`, `Field`, `Method`, `DeclAnnotation` through prelude aliases. A
/// module that declares or imports a type of one of those names takes the
/// name: the alias leaves this module's scope, and the handle's members keep
/// their own identity.
fn dropReflectionAlias(env: *Env, name: []const u8) void {
    const alias = env.typeAliases.get(name) orelse return;
    const target = switch (alias.target) {
        .named => |n| n,
        else => return,
    };
    if (std.mem.startsWith(u8, target, "__Decl__")) _ = env.typeAliases.remove(name);
}

/// A `behavior` this module declares, or imports by its name, is what that
/// name means here, as a `type` of the name is (`registerTypeDecl`,
/// `dropReflectionAlias`): the prelude's declaration of the name — a type
/// (`Result`, `Field`, `Declared`), a reflection alias (`Param` =
/// `__Decl__Param`) or a bare unit variant (`DeclKind.Component`,
/// `Stage.Any`) — leaves this module's scope. Without it a type position
/// read the prelude's: `behavior Component` in `@Decl<Component>` was refused
/// "'Component' is a value, not a type", and `behavior Field` silently named
/// std's `Field`. The behavior's own binding (typed by its display name,
/// which holds a space) is kept.
pub fn takeNameFromPrelude(env: *Env, name: []const u8) void {
    dropReflectionAlias(env, name);
    if (env.typeDefs.get(name) != null and !env.ownTypeDecls.contains(name)) _ = env.typeDefs.remove(name);
    if (env.bindings.get(name)) |ty| {
        const d = ty.deref();
        const declBinding = d.* == .named and std.mem.indexOfScalar(u8, d.named.name, ' ') != null;
        if (!declBinding) _ = env.bindings.remove(name);
    }
}

/// Pre-pass (mutual recursion): bind every top-level `fn`/`pub fn` name to its
/// signature type BEFORE any body is inferred, so a function can call another
/// declared later in the same module (`renderToString` ⇄ `renderChildren`).
///
/// A top-level function's signature is fully determined by its declared
/// parameter and return types plus generic params — the body never changes it —
/// so the type built here matches what `inferFnDecl` later derives when it walks
/// the body (which re-binds the same name for self-recursion). This mirrors how
/// recursive `record` type names are registered in pass 1 before any use.
fn registerFnSignatures(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| switch (decl) {
        .@"fn" => |f| {
            try env.bind(f.name, try buildFnSignatureType(env, f));
            // C-04 — the signature type drops the `default` expressions; keep
            // the parameters as written so a short call can be told from a
            // call missing a required argument.
            try env.fnParams.put(f.name, f.params);
            try env.fnDecls.put(env.arena, f.name, f);
            registerDecoratorSig(env, f.name, f.params, f.genericParams, f);
            // C-01 — a template or decorator this module declares is owned by
            // this module's path, which its evaluated module atom names.
            try env.noteComptimeOwner(f, env.modulePath);
            if (f.typeGuardParam) |paramName| {
                var paramIndex: usize = 0;
                for (f.params, 0..) |p, i| {
                    if (std.mem.eql(u8, p.name, paramName)) {
                        paramIndex = i;
                        break;
                    }
                }
                // 06 C5 — the narrowed type is its own slot; `returnType` is `bool`.
                const narrowedName: []const u8 = if (f.typeGuardType) |gt| switch (gt) {
                    .named => |n| n,
                    else => paramName,
                } else paramName;
                try env.typeGuardFns.put(f.name, .{ .paramIndex = paramIndex, .narrowedTypeName = narrowedName });
            }
        },
        // A `declare fn` decorator (`declare fn service(comptime _: @Decl)`) —
        // the bodyless form a lib ships its markers as — parses as a delegate.
        else => {},
    };
}

/// True when `params` open with `comptime _: @Decl`, the signature shape that
/// marks a function as a decorator (annotation processor). The core recognizes
/// decorators purely by this shape — it never knows what a marker means (that is
/// the lib's job). Applies to both `pub fn` and `declare fn` forms.
pub fn isDecoratorParams(params: []const ast.Param) bool {
    if (params.len == 0) return false;
    const p0 = params[0];
    return p0.modifier == .@"comptime" and p0.typeRef.isDeclType();
}

/// Register a decorator imported from another module — its full `FnDecl` (body
/// included) — into this module's decorator table, so `#[name(args)]` sites here
/// argument-check against it AND run its body over each annotated declaration at
/// comptime. Mirrors `registerImportedTemplateFn` for the `@Expr` template case;
/// the core stays lib-agnostic (it carries the decorator across modules by its
/// generic `@Decl`-first shape, never by any lib's name). No-op for non-decorators.
pub fn registerImportedDecorator(env: *Env, name: []const u8, fn_decl: ast.FnDecl, owner: []const u8, support: []const ast.FnDecl, conflict: ?[]const u8) !void {
    registerDecoratorSig(env, name, fn_decl.params, fn_decl.genericParams, fn_decl);
    if (env.decorators.getPtr(name)) |sig| {
        sig.support = support;
        sig.conflict = conflict;
        sig.module = owner;
    }
    try env.noteComptimeOwner(fn_decl, owner);
}

/// What a decorator module needs beside the decorator (`decoratorSupport`),
/// or why it cannot be built: two functions it reaches share a name.
pub const Support = struct {
    fns: []const ast.FnDecl,
    /// Set when two DIFFERENT functions the body reaches carry one name — a
    /// module-local helper and one an imported function brings, say. The
    /// decorator module is one namespace, so one of them would silently answer
    /// for the other; the decorator is refused instead (decision 67).
    conflict: ?[]const u8 = null,
};

/// The functions `dfn`'s body calls or names, directly or through one another
/// — what a decorator module needs beside the decorator to compile. `lookup`
/// answers a name with a function of `dfn`'s own module; `imported` answers a
/// name the module IMPORTS with that function and every function it reaches
/// in its own module (`Env.importedFnSupport` — already closed, so their
/// bodies are not walked here: their names resolve where they were written).
/// A decorator, a template and a bodyless `declare fn` are left out: none of
/// them runs as a plain function in the decorator module. Before this a
/// decorator body could call no function at all (`call to undefined function
/// problemOf/1`), and then none it imported (`shout/1`).
pub fn decoratorSupport(
    arena: std.mem.Allocator,
    lookup: anytype,
    imported: *const std.StringHashMapUnmanaged([]const ast.FnDecl),
    dfn: ast.FnDecl,
) std.mem.Allocator.Error!Support {
    const kind: []const u8 = if (dfn.returnType) |rt| (if (rt.isTemplateReturnType()) "template" else "decorator") else "decorator";
    var out: std.ArrayListUnmanaged(ast.FnDecl) = .empty;
    // name → the body that name stands for in the decorator module.
    var bodies = std.StringHashMap([*]const ast.Stmt).init(arena);
    var seen = std.StringHashMap(void).init(arena);
    try seen.put(dfn.name, {});
    var names: std.ArrayListUnmanaged([]const u8) = .empty;
    try ast.collectNames(arena, dfn.body, &names);
    var i: usize = 0;
    while (i < names.items.len) : (i += 1) {
        const n = names.items[i];
        if (seen.contains(n)) continue;
        try seen.put(n, {});
        if (lookup.get(n)) |f| {
            if (f.body.len == 0 or isDecoratorParams(f.params)) continue;
            if (f.returnType) |rt| if (rt.isTemplateReturnType()) continue;
            if (try claimName(arena, &bodies, f, dfn.name, kind)) |c| return .{ .fns = out.items, .conflict = c };
            try out.append(arena, f);
            try ast.collectNames(arena, f.body, &names);
            continue;
        }
        const closure = imported.get(n) orelse continue;
        for (closure) |g| {
            if (bodies.get(g.name)) |b| if (b == g.body.ptr) continue;
            if (try claimName(arena, &bodies, g, dfn.name, kind)) |c| return .{ .fns = out.items, .conflict = c };
            try out.append(arena, g);
        }
    }
    return .{ .fns = out.items };
}

/// Records that `f.name` means `f` in the decorator module; the message when
/// the name already means another function.
fn claimName(arena: std.mem.Allocator, bodies: *std.StringHashMap([*]const ast.Stmt), f: ast.FnDecl, decorator: []const u8, kind: []const u8) std.mem.Allocator.Error!?[]const u8 {
    if (bodies.get(f.name)) |b| {
        if (b == f.body.ptr) return null;
        const what = if (std.mem.eql(u8, kind, "template")) "a template" else "a decorator";
        return try std.fmt.allocPrint(arena, "the {s} `{s}` reaches two different functions named `{s}` — one of its module's and one an imported function calls — and {s} runs as one module, where one name is one function", .{ kind, decorator, f.name, what });
    }
    try bodies.put(f.name, f.body.ptr);
    return null;
}

/// A plain function with a body, as a decorator module can carry it: not a
/// decorator, not a template, not a bodyless declaration.
pub fn isCarriableFn(f: ast.FnDecl) bool {
    if (f.body.len == 0 or isDecoratorParams(f.params)) return false;
    if (f.returnType) |rt| if (rt.isTemplateReturnType()) return false;
    return true;
}

/// Register an `implement` block imported and activated from another module
/// (`import { Name* } from "mod"`) into this module's extension table, so
/// `obj.method()` dispatches to it. Local extensions are auto-applied
/// ([[registerExtensions]]); imported ones are opt-in via the `*` activation —
/// they only land here when the importer asked for them. The dispatch table makes
/// no further local/imported distinction (every entry here is meant to resolve).
pub fn registerImportedExtension(env: *Env, im: ast.ImplementDecl) !void {
    try env.extensions.put(im.name, .{
        .name = im.name,
        .target = im.target,
        .interfaces = im.interfaces,
        .methods = try collectImplMethodNames(env, im.methods),
    });
}

/// Record a decorator's trailing signature (everything after the leading
/// `comptime _: @Decl`) so `#[name(args)]` applications can be argument-checked,
/// plus its full `FnDecl` (when it has a body) so the body can run over each
/// annotated declaration at comptime (P2). No-op for ordinary functions.
fn registerDecoratorSig(env: *Env, name: []const u8, params: []const ast.Param, generics: []const ast.GenericParam, fn_decl: ?ast.FnDecl) void {
    if (!isDecoratorParams(params)) return;
    env.decorators.put(name, .{ .params = params[1..], .fn_decl = fn_decl, .decl = params[0].typeRef, .generics = generics }) catch {};
}

/// True when a type's `implement` clause lists the builtin `@Annotation`
/// marker — the signal that a `record`/`struct`/`enum` may be used as an
/// annotation (`#[MyMarker(field: value)]` or, for an enum,
/// `#[@External.Variant(args)]`). Plain `Annotation` (no `@` prefix) is
/// matched too, since `implement` entries don't carry the builtin sigil.
fn implementsAnnotation(impls: []const ast.TypeRef) bool {
    for (impls) |t| switch (t) {
        .named => |n| if (std.mem.eql(u8, n, "Annotation")) return true,
        .generic => |g| if (std.mem.eql(u8, g.name, "Annotation")) return true,
        else => {},
    };
    return false;
}

/// Convert a record/struct/enum-variant field list into the `[]ast.Param`
/// shape `DecoratorSig` consumes. Field defaults flow through as `default`,
/// so the annotation argument validator applies them on a missing positional /
/// named arg — the same rule a fn-param default uses. The synthetic param
/// list lives in `env.arena`, so it outlives the registration call.
fn recordFieldsAsParams(env: *Env, fields: []const ast.Field) ![]ast.Param {
    var out = try env.arena.alloc(ast.Param, fields.len);
    for (fields, 0..) |f, i| {
        out[i] = .{
            .name = f.name,
            .typeRef = f.typeRef,
            .default = f.default,
        };
    }
    return out;
}

fn structFieldsAsParams(env: *Env, members: []const ast.StructMember) ![]ast.Param {
    var count: usize = 0;
    for (members) |m| if (m == .field) {
        count += 1;
    };
    var out = try env.arena.alloc(ast.Param, count);
    var i: usize = 0;
    for (members) |m| switch (m) {
        .field => |f| {
            out[i] = .{
                .name = f.name,
                .typeRef = f.typeRef,
                .default = f.init,
            };
            i += 1;
        },
        else => {},
    };
    return out;
}

fn enumVariantAsParams(env: *Env, variant: ast.EnumVariant) ![]ast.Param {
    var out = try env.arena.alloc(ast.Param, variant.fields.len);
    for (variant.fields, 0..) |f, i| {
        out[i] = .{
            .name = f.name,
            .typeRef = f.typeRef,
            .default = f.default,
        };
    }
    return out;
}

/// Register every `record`/`struct`/`enum` decl whose `implement` clause lists
/// `Annotation` as an annotation-style sig in `env.decorators`. Records and
/// structs go in under their bare name (`#[MyMarker(args)]`); each enum
/// variant goes in under the qualified path (`#[@External.Erlang(args)]` ⇒
/// `"External.Erlang"`). Skips ordinary types — the fn-shape `comptime _:
/// @Decl` decorator path keeps working untouched.
pub fn registerAnnotationTypes(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| switch (decl) {
        .type_ => |tdecl| switch (tdecl.shape) {
            .record => {
                if (!implementsAnnotation(tdecl.implement)) continue;
                const params = try recordFieldsAsParams(env, tdecl.recordFields());
                env.decorators.put(tdecl.name, .{ .params = params, .fn_decl = null }) catch {};
            },
            .enum_ => {
                if (!implementsAnnotation(tdecl.implement)) continue;
                for (tdecl.variants()) |v| {
                    const params = try enumVariantAsParams(env, v);
                    const qname = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ tdecl.name, v.name });
                    env.decorators.put(qname, .{ .params = params, .fn_decl = null }) catch {};
                }
            },
        },
        else => {},
    };
}

/// Build a top-level function's callable type (params → return) without binding
/// its parameters into `env` or inferring its body. Mirrors the signature half
/// of `inferFnDecl`: a generic map, `fn(...)`-param and ordinary-param
/// resolution, the return type, and generalization of declared generic params
/// the signature left unbound (so each call site instantiates them fresh).
fn buildFnSignatureType(env: *Env, f: ast.FnDecl) InferError!*T.Type {
    var genericMap = std.StringHashMap(*T.Type).init(env.arena);
    defer genericMap.deinit();
    for (f.genericParams) |gp| {
        try genericMap.put(gp.name, try env.freshVar());
    }

    var paramTypes = try env.arena.alloc(*T.Type, f.params.len);
    for (f.params, 0..) |p, i| {
        paramTypes[i] = try resolveParamType(env, p, genericMap);
    }

    const retType = if (f.returnType) |rt|
        try resolveReturnType(env, rt, f.returnTypeLoc, genericMap)
    else
        try env.namedType("void");

    // Generalize declared generic params the signature left unbound (same rule
    // as `inferFnDecl`): each becomes `.generic`, so use sites instantiate fresh.
    var git = genericMap.valueIterator();
    while (git.next()) |gv| {
        const resolved = gv.*.deref();
        if (resolved.* != .typeVar) continue;
        const cell = resolved.typeVar;
        switch (cell.state) {
            .unbound => |u| cell.state = .{ .generic = u.id },
            else => {},
        }
    }

    return env.funcType(paramTypes, retType);
}

/// Pre-pass for static extension dispatch: record inherent methods, register
/// named `implement`/`extend` blocks, collect activations, and validate
/// `implement` blocks against their interfaces.
///
/// Runs after type-definition registration (pass 1) and before expression
/// inference (pass 2) so `obj.method()` resolution sees the full picture.
fn registerExtensions(env: *Env, program: ast.Program) InferError!void {
    // Note: `implement`-vs-interface coverage (extra/missing methods) is validated
    // by `validateProgram`; this pre-pass only builds the dispatch tables.

    // Inherent methods + extension entries.
    for (program.decls) |decl| {
        switch (decl) {
            .type_ => |tdecl| switch (tdecl.shape) {
                .record => for (tdecl.methods) |im| try env.addInherentMethod(tdecl.name, im.name),
                .enum_ => for (tdecl.methods) |im| try env.addInherentMethod(tdecl.name, im.name),
            },
            .implement => |im| {
                try env.extensions.put(im.name, .{
                    .name = im.name,
                    .target = im.target,
                    .interfaces = im.interfaces,
                    .methods = try collectImplMethodNames(env, im.methods),
                });
                // Bind the symbol as a value so a qualified call `Sym.m(obj)` can
                // infer `Sym` as its receiver expression (it names a namespace of
                // methods, not a typed value — a fresh var types it permissively).
                try env.bind(im.name, try env.freshVar());
            },
            .extend => |ex| {
                // Rule A: methods are added to a type only through `implement
                // <Interface> for T`, which `validateImplement` checks against the
                // interface. A contract-free `extend` block is rejected.
                env.lastError = locatedAt(TypeError.extendRequiresInterface(ex.target), ex.loc);
                return error.TypeError;
            },
            else => {},
        }
    }

    // Activations carried by `use` declarations: an `import { name* } from "…"`
    // opts an *imported* extension into scope, while a bare `name*;`
    // (`activationOnly`) names a local symbol. Rule B: a locally-declared
    // extension is auto-applied in its module, so a bare `name*;` is never needed.
    for (program.decls) |decl| {
        switch (decl) {
            .use => |u| for (u.imports) |imp| {
                if (!imp.activate) continue;
                const nm = imp.name();
                if (u.activationOnly) {
                    // `*` is only for imports. A bare statement is redundant when it
                    // names a local extension, and otherwise names no extension.
                    env.lastError = locatedAt(if (env.extensions.contains(nm))
                        TypeError.redundantActivation(nm)
                    else
                        TypeError.notAnExtension(nm), imp.loc);
                    return error.TypeError;
                }
                try env.activations.put(nm, {});
            },
            else => {},
        }
    }
}

/// Build the V1 origin-scope snapshot for the module being inferred: every
/// top-level declaration plus imported names, mapped to a `BindingKind`
/// (expr-templates F4). The snapshot is attached to every `expr` capture so
/// template functions can `lookup` names in the *caller's* scope — function
/// locals are not visible (V1 limit recorded in the spec).
///
/// Runs after `resolveImports` (comptime.zig) bound the imports, so an
/// imported name's kind is derived from its bound type (`fn` vs value).
fn buildScopeSnapshot(env: *Env, program: ast.Program) InferError!void {
    const snap = template.ScopeSnapshot.init(env.arena, env.modulePath) catch return error.OutOfMemory;
    const here = env.modulePath;
    for (program.decls) |decl| switch (decl) {
        .@"fn" => |f| try snap.putDeclared(f.name, .fn_, false, f.name, try envMod.declIdentity(env.arena, here, f.name)),
        .val => |v| try snap.putDeclared(v.name, .val, false, v.name, try envMod.declIdentity(env.arena, here, v.name)),
        .type_ => |tdecl| switch (tdecl.shape) {
            .record => try snap.putDeclared(tdecl.name, .struct_, false, tdecl.name, try envMod.declIdentity(env.arena, here, tdecl.name)),
            .enum_ => try snap.putDeclared(tdecl.name, .enum_, false, tdecl.name, try envMod.declIdentity(env.arena, here, tdecl.name)),
        },
        .behavior => |i| try snap.putDeclared(i.name, .interface, false, i.name, try envMod.declIdentity(env.arena, here, i.name)),
        .use => |u| for (u.imports) |imp| {
            const name = imp.name();
            const kind: template.BindingKind = blk: {
                const ty = env.lookup(name) orelse break :blk .val;
                break :blk if (ty.deref().* == .func) .fn_ else .val;
            };
            // Decision 112 — an import answers with the declaration it
            // names, never with the alias it is bound under.
            if (env.importOwners.get(name)) |o| {
                try snap.putDeclared(name, kind, true, o.name, try envMod.declIdentity(env.arena, o.owner, o.name));
            } else try snap.put(name, kind, true);
        },
        else => {},
    };
    env.scopeSnapshot = snap;
}

fn collectImplMethodNames(env: *Env, methods: []const ast.ImplementMethod) ![]const []const u8 {
    var names = try env.arena.alloc([]const u8, methods.len);
    for (methods, 0..) |m, i| names[i] = m.name;
    return names;
}

fn extractImplementNames(arena: std.mem.Allocator, impls: []const ast.TypeRef) ![]const []const u8 {
    if (impls.len == 0) return &.{};
    var names = try arena.alloc([]const u8, impls.len);
    for (impls, 0..) |im, i| {
        names[i] = switch (im) {
            .named => |n| n,
            .generic => |g| g.name,
            else => "unknown",
        };
    }
    return names;
}

/// `text` with the effect wrappers spelled as the types in force — `Async`,
/// `Iter`, `AsyncIter`, `Component`, `Result` — not with the `@` a builtin
/// `TypeRef` renders (specs/retired.md). For a diagnostic's display only.
fn wrappersSpelled(arena: std.mem.Allocator, text: []const u8) ![]const u8 {
    var out: std.ArrayListUnmanaged(u8) = .empty;
    var i: usize = 0;
    while (i < text.len) : (i += 1) {
        if (text[i] == '@') {
            const rest = text[i + 1 ..];
            const wrapper = for (ast.EffectKind.all) |e| {
                const w = e.returnWrapper();
                if (std.mem.startsWith(u8, rest, w) and (rest.len == w.len or !std.ascii.isAlphanumeric(rest[w.len]))) break true;
            } else false;
            if (wrapper) continue;
        }
        try out.append(arena, text[i]);
    }
    return out.items;
}

/// Render a `TypeRef` to its source-level string form (heap-allocated in `arena`).
fn typeRefToString(arena: std.mem.Allocator, ref: ast.TypeRef) ![]const u8 {
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    try appendTypeRefStr(&buf, arena, ref);
    return buf.toOwnedSlice(arena);
}

/// True when any of `impls` is the marker `@Renderable` (decision 354): a
/// `@Component<R>` whose `R` implements it is a component.
fn implementsRenderable(impls: []const ast.TypeRef) bool {
    for (impls) |im| switch (im) {
        .generic => |g| if (g.is_builtin and std.mem.eql(u8, g.name, "Renderable")) return true,
        else => {},
    };
    return false;
}

/// Derive the `use` capability of a function from its declared return type
/// (decisions 102, 104, 128 and 354): `-> @Component<R>` grants `use`, for a
/// hook and a component alike, and nothing is unwrapped to find it.
/// `annotated` is the `@Component` return and nothing else — the same flag as
/// `env.inContextFn`.
fn contextInfoFromReturn(env: *Env, retType: ?ast.TypeRef, eff: ?ast.EffectKind, fnName: []const u8) InferError!envMod.FnContext {
    const display = if (retType) |rt| try wrappersSpelled(env.arena, try typeRefToString(env.arena, rt)) else "void";
    const annotated = eff == .component;
    if (retType) |rt| switch (rt) {
        .generic => |g| if (std.mem.eql(u8, g.name, "Component")) {
            return .{ .implementsContext = true, .returnDisplay = display, .annotated = annotated, .fnName = fnName };
        },
        else => {},
    };
    return .{ .implementsContext = false, .returnDisplay = display, .annotated = annotated, .fnName = fnName };
}

/// The display name of a named type (a value's head, for a diagnostic).
fn baseNameOfType(ty: *T.Type) ?[]const u8 {
    return switch (ty.deref().*) {
        .named => |n| n.name,
        else => null,
    };
}

/// True when `ty` is a hook: `@Component<R>` whose `R` does not implement
/// `@Renderable` (decision 354). A component, a plain value — is not.
fn isHookType(env: *Env, ty: *T.Type) bool {
    const t = ty.deref();
    if (t.* != .named or !std.mem.eql(u8, t.named.name, "Component") or t.named.args.len < 1) return false;
    return !isComponentType(env, ty);
}

/// Decision 8 §1.3 — `Box<i32>(value: 1)`, `first<string>([])`: type
/// arguments written at a use pin the callee's type parameters, in order. A
/// constructor's arguments are its type's parameters (`Box<T>`); a generic
/// fn's are its own (`fn first<T>`) — the declared signature is re-read with
/// each parameter bound to its argument and unified with the call. The count
/// must match exactly, and a callee with no type parameters takes none.
fn applyExplicitTypeArgs(env: *Env, c: ast.CallExprOf(.untyped), typed: TypedExpr) InferError!TypedExpr {
    if (c.kind != .call) return typed;
    const call = c.kind.call;
    const written = call.typeArgs orelse return typed;
    if (typed != .call) return typed;
    const loc = c.loc;
    const prevLoc = env.atTypeRef(loc);
    defer env.typeRefLoc = prevLoc;
    const resolved = try env.arena.alloc(*T.Type, written.len);
    for (written, 0..) |w, i| resolved[i] = try resolveTypeRef(env, w);
    const countError = struct {
        fn f(e: *Env, name: []const u8, declared: usize, given: usize, l: ast.Loc) InferError {
            const msg = if (declared == 0)
                std.fmt.allocPrint(e.arena, "`{s}` takes no type arguments, {d} given", .{ name, given }) catch return error.OutOfMemory
            else
                std.fmt.allocPrint(e.arena, "`{s}` takes {d} type argument{s}, {d} given", .{ name, declared, if (declared == 1) "" else "s", given }) catch return error.OutOfMemory;
            e.lastError = TypeError.custom(msg, "Write one type argument per type parameter the declaration names, in order (decision 8 §1.3).").withLoc(l);
            return error.TypeError;
        }
    }.f;
    const resultTy = typed.getType();
    // A function called through its module (`kit.resolve<Box>(…)`).
    if (call.receiver) |recv| if (recv.* == .identifier and recv.identifier.kind == .ident and env.namespaces.paths.contains(recv.identifier.kind.ident)) {
        const key = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ recv.identifier.kind.ident, call.callee });
        const f = env.importedFnDecls.get(key) orelse return countError(env, call.callee, 0, resolved.len, loc);
        return pinImportedFnTypeArgs(env, f, typed, resolved, resultTy, call.callee, loc, countError);
    };
    // A method call (`ctx.resolve<T>()`): the method's own type parameters
    // take the arguments; the type's are the receiver's.
    if (typed.call.kind == .call) if (typed.call.kind.call.receiver) |recv| {
        const recvTy = recv.getType().deref();
        const tn = nominalName(recvTy) orelse return countError(env, call.callee, 0, resolved.len, loc);
        const m = env.getInherentMethodDecl(tn, call.callee) orelse return countError(env, call.callee, 0, resolved.len, loc);
        if (m.genericParams.len != resolved.len) return countError(env, call.callee, m.genericParams.len, resolved.len, loc);
        var gm = std.StringHashMap(*T.Type).init(env.arena);
        defer gm.deinit();
        if (env.lookupTypeDef(tn)) |td| {
            const tps = td.genericParams();
            for (tps, 0..) |tp, i| if (i < recvTy.named.args.len) try gm.put(tp, recvTy.named.args[i]);
        }
        try gm.put("Self", recv.getType());
        for (m.genericParams, resolved) |gp, r| try gm.put(gp.name, r);
        const args = typed.call.kind.call.args;
        const declared = if (m.params.len > 0 and std.mem.eql(u8, m.params[0].name, "self")) m.params[1..] else m.params;
        for (declared, 0..) |p, i| {
            if (i >= args.len) break;
            if (args[i].label != null) break;
            const pt = try resolveTypeRefInContext(env, p.typeRef, gm);
            try unifyAt(env, pt, args[i].value.getType(), args[i].value.getLoc());
        }
        if (m.returnType) |rtRef| {
            const want = try resolveTypeRefInContext(env, rtRef, gm);
            try unifyAt(env, want, resultTy, loc);
        }
        return typed;
    };
    if (env.lookupTypeDef(call.callee)) |td| {
        const params = td.genericParams();
        if (params.len != resolved.len) return countError(env, call.callee, params.len, resolved.len, loc);
        const rt = resultTy.deref();
        if (rt.* == .named and rt.named.args.len == resolved.len) {
            for (rt.named.args, resolved) |a, r| try unifyAt(env, r, a, loc);
        }
        return typed;
    }
    if (env.fnDecls.get(call.callee)) |f| {
        if (f.genericParams.len != resolved.len) return countError(env, call.callee, f.genericParams.len, resolved.len, loc);
        var gm = std.StringHashMap(*T.Type).init(env.arena);
        defer gm.deinit();
        for (f.genericParams, resolved) |gp, r| try gm.put(gp.name, r);
        for (f.params, 0..) |p, i| {
            if (i >= typed.call.kind.call.args.len) break;
            if (typed.call.kind.call.args[i].label != null) break;
            const pt = try resolveTypeRefInContext(env, p.typeRef, gm);
            try unifyAt(env, pt, typed.call.kind.call.args[i].value.getType(), typed.call.kind.call.args[i].value.getLoc());
        }
        if (f.returnType) |rtRef| {
            const want = try resolveTypeRefInContext(env, rtRef, gm);
            try unifyAt(env, want, resultTy, loc);
        }
        return typed;
    }
    // An imported function: its declaration is written in its own module, so
    // its types are not re-read here; each place that names a type parameter
    // is met, through the shape around it, with what the call inferred there.
    if (env.importedFnDecls.get(call.callee)) |f| return pinImportedFnTypeArgs(env, f, typed, resolved, resultTy, call.callee, loc, countError);
    return countError(env, call.callee, 0, resolved.len, loc);
}

/// `f`, a function of another module, called with the type arguments
/// `resolved`: the count checked, then each argument and the result pinned.
fn pinImportedFnTypeArgs(
    env: *Env,
    f: ast.FnDecl,
    typed: TypedExpr,
    resolved: []const *T.Type,
    resultTy: *T.Type,
    callee: []const u8,
    loc: ast.Loc,
    countError: fn (*Env, []const u8, usize, usize, ast.Loc) InferError,
) InferError!TypedExpr {
    if (f.genericParams.len != resolved.len) return countError(env, callee, f.genericParams.len, resolved.len, loc);
    const args = typed.call.kind.call.args;
    for (f.params, 0..) |p, i| {
        if (i >= args.len) break;
        if (args[i].label != null) break;
        try pinTypeParams(env, f.genericParams, resolved, p.typeRef, args[i].value.getType(), args[i].value.getLoc());
    }
    if (f.returnType) |rtRef| try pinTypeParams(env, f.genericParams, resolved, rtRef, resultTy, loc);
    return typed;
}

/// Decision 8 §1.3 — each type parameter `ref` names (a declaration of
/// another module, written in its scope) unified with `pinned`, the type
/// argument the call wrote for it, at the matching place of `ty`: an array's
/// element, an optional's inner type, a generic type's arguments, a
/// function's parameters and return. A name that is no type parameter, and a
/// shape `ty` does not repeat, pin nothing.
fn pinTypeParams(env: *Env, generics: []const ast.GenericParam, pinned: []const *T.Type, ref: ast.TypeRef, ty: *T.Type, loc: ast.Loc) InferError!void {
    const d = ty.deref();
    switch (ref) {
        .named => |n| for (generics, pinned) |gp, r| {
            if (std.mem.eql(u8, gp.name, n)) return unifyAt(env, r, ty, loc);
        },
        .array => |inner| if (d.* == .named and std.mem.eql(u8, d.named.name, "array") and d.named.args.len == 1)
            try pinTypeParams(env, generics, pinned, inner.*, d.named.args[0], loc),
        .optional => |inner| if (optionalInner(d)) |o|
            try pinTypeParams(env, generics, pinned, inner.*, o, loc),
        .generic => |g| if (d.* == .named and d.named.args.len == g.args.len) {
            for (g.args, d.named.args) |a, t| try pinTypeParams(env, generics, pinned, a, t, loc);
        },
        .function => |fnRef| if (d.* == .func and d.func.params.len == fnRef.params.len) {
            for (fnRef.params, d.func.params) |a, t| try pinTypeParams(env, generics, pinned, a, t, loc);
            try pinTypeParams(env, generics, pinned, fnRef.returnType.*, d.func.ret, loc);
        },
        else => {},
    }
}

/// Decision 255 (1) — the type a type application names
/// (`Dict<string, unknown>.empty()`, `Opt<i32>.None`), its written arguments
/// resolved. The receiver must name a declared generic type (an import alias
/// is its declared name, decision 110) and take exactly as many arguments as
/// the type declares parameters; anything else is refused at the receiver.
const TypeApplication = struct {
    name: []const u8,
    def: envMod.TypeDef,
    args: []*T.Type,
};

fn resolveTypeApplication(env: *Env, receiver: *ast.Expr, written: []const ast.TypeRef) InferError!TypeApplication {
    const loc = receiver.getLoc();
    const isName = receiver.* == .identifier and receiver.identifier.kind == .ident;
    const writtenName = if (isName) receiver.identifier.kind.ident else "";
    const name = if (isName) importedTypeAliasTarget(env, writtenName) orelse writtenName else "";
    const def = (if (isName) env.lookupTypeDef(name) else null) orelse {
        const shown = if (isName) writtenName else "this receiver";
        const msg = try std.fmt.allocPrint(env.arena, "type arguments are written on `{s}`, which names no type", .{shown});
        env.lastError = TypeError.custom(msg, "A type application is a declared generic type's name followed by its type arguments: `Dict<string, i32>.empty()` (decision 255).").withLoc(loc);
        return error.TypeError;
    };
    const params = def.genericParams();
    if (params.len != written.len) {
        const msg = if (params.len == 0)
            try std.fmt.allocPrint(env.arena, "`{s}` takes no type arguments, {d} given", .{ writtenName, written.len })
        else
            try std.fmt.allocPrint(env.arena, "`{s}` takes {d} type argument{s}, {d} given", .{ writtenName, params.len, if (params.len == 1) "" else "s", written.len });
        env.lastError = TypeError.custom(msg, "Write one type argument per type parameter the declaration names, in order (decision 8 §1.3, decision 255).").withLoc(loc);
        return error.TypeError;
    }
    const prevLoc = env.atTypeRef(loc);
    defer env.typeRefLoc = prevLoc;
    const args = try env.arena.alloc(*T.Type, written.len);
    for (written, 0..) |w, i| args[i] = try resolveTypeRef(env, w);
    return .{ .name = name, .def = def, .args = args };
}

/// Decision 255 (1) — `Type<Args>.member(…)`: the member is called on the
/// instantiated type. A variant of a generic enum answers `Type<Args>`; a
/// static (or any inherent) fn has its declared signature re-read with the
/// type's parameters bound to the arguments — and `Self` to `Type<Args>` —
/// and unified with the call, so `Dict<string, unknown>.empty()` is a
/// `Dict<string, unknown>`. A member that is neither has no signature the
/// arguments could reach, and is refused at the call.
fn applyReceiverTypeArgs(env: *Env, c: ast.CallExprOf(.untyped), typed: TypedExpr) InferError!TypedExpr {
    if (c.kind != .call) return typed;
    const call = c.kind.call;
    const written = call.receiverTypeArgs orelse return typed;
    const receiver = call.receiver orelse return typed;
    const app = try resolveTypeApplication(env, receiver, written);
    const loc = c.loc;
    const resultTy = typed.getType();
    if (app.def == .enum_) for (app.def.enum_.variants) |v| {
        if (!std.mem.eql(u8, v.name, call.callee)) continue;
        try unifyAt(env, try env.namedTypeArgs(app.name, app.args), resultTy, loc);
        return typed;
    };
    const m = env.getInherentMethodDecl(app.name, call.callee) orelse {
        const msg = try std.fmt.allocPrint(env.arena, "`{s}` is not a variant or a fn declared by `{s}`, so its type arguments reach nothing", .{ call.callee, app.name });
        env.lastError = TypeError.custom(msg, "A type application calls a variant or a fn the type declares in its body (`Dict<string, i32>.empty()`).").withLoc(loc);
        return error.TypeError;
    };
    var gm = std.StringHashMap(*T.Type).init(env.arena);
    defer gm.deinit();
    for (app.def.genericParams(), app.args) |tp, a| try gm.put(tp, a);
    try gm.put("Self", try env.namedTypeArgs(app.name, app.args));
    for (m.genericParams) |gp| if (!gm.contains(gp.name)) try gm.put(gp.name, try env.freshVar());
    const args = typed.call.kind.call.args;
    for (m.params, 0..) |p, i| {
        if (i >= args.len) break;
        if (args[i].label != null) break;
        const pt = try resolveTypeRefInContext(env, p.typeRef, gm);
        try unifyAt(env, pt, args[i].value.getType(), args[i].value.getLoc());
    }
    if (m.returnType) |rtRef| {
        const want = try resolveTypeRefInContext(env, rtRef, gm);
        try unifyAt(env, want, resultTy, loc);
    }
    return typed;
}

/// Decision 791 (4) — `await c` over a `Component<R>`, refused at the
/// `await`: the message names `use c` (inside a component body) and `c` as a
/// child of the tree.
fn refuseAwaitComponent(env: *Env, ty: *T.Type, loc: ast.Loc) InferError {
    const shown = try snapshotMod.typeNameOf(env.arena, ty.deref());
    const msg = try std.fmt.allocPrint(env.arena, "{s}: `await` takes an `Async<T>`, and this is a `{s}` — a component is resolved by `use c` inside a component body, or placed in the tree as a child `c` (decision 791 (4))", .{ diagnostics.await_component, shown });
    env.lastError = TypeError.custom(msg, "In a component body write `val v = use c;`; elsewhere place `c` as a node's child, or run a root with `c.run(RenderScope.root())`.").withLoc(loc);
    return error.TypeError;
}

/// Decision 791 (4) — an `await` whose operand's type was still unresolved
/// at the `await` and resolved to a `Component<R>` is refused at the `await`.
fn refuseComponentAwaits(env: *Env) InferError!void {
    var it = env.taskAwaits.iterator();
    while (it.next()) |e| {
        const d = e.value_ptr.*.deref();
        if (d.* == .named and std.mem.eql(u8, d.named.name, "Component")) return refuseAwaitComponent(env, e.value_ptr.*, e.key_ptr.*);
    }
}

/// True when `ty` is a component: `@Component<R>` whose `R` implements
/// `@Renderable` (decision 354). A hook's `R` does not.
fn isComponentType(env: *Env, ty: *T.Type) bool {
    const t = ty.deref();
    if (t.* != .named or !std.mem.eql(u8, t.named.name, "Component") or t.named.args.len < 1) return false;
    return isRenderableType(env, t.named.args[0]);
}

/// True when `ty` names a type that implements `@Renderable`.
fn isRenderableType(env: *Env, ty: *T.Type) bool {
    const t = ty.deref();
    return switch (t.*) {
        .named => |n| if (env.lookupTypeDef(n.name)) |td| td.isRenderable() else false,
        else => false,
    };
}

/// The type a `use` binding destructures from: the `R` of the hook's
/// `@Component<R>`.
fn bindingSourceType(ty: *T.Type) *T.Type {
    const t = ty.deref();
    return switch (t.*) {
        .named => |n| if (std.mem.eql(u8, n.name, "Component") and n.args.len >= 1) n.args[0] else ty,
        else => ty,
    };
}

fn registerRecord(env: *Env, r: ast.TypeDecl) InferError!void {
    // Build generic param map: each param name → fresh generic type var.
    var genericMap = std.StringHashMap(*T.Type).init(env.arena);
    defer genericMap.deinit();
    var genericIds = try env.arena.alloc([]const u8, r.genericParams.len);
    for (r.genericParams, 0..) |gp, i| {
        const tv = try env.freshVar();
        try genericMap.put(gp.name, tv);
        genericIds[i] = gp.name;
    }

    // Resolve each field's type.
    var fields = try env.arena.alloc(envMod.FieldDef, r.recordFields().len);
    for (r.recordFields(), 0..) |f, i| {
        fields[i] = .{
            .name = f.name,
            .type_ = try resolveFieldType(env, f, genericMap),
        };
    }

    // §1G — resolve each generic param's optional default into a `*T.Type`
    // against the same `genericMap` so a default that references an earlier
    // param (e.g. `<T, U = T>`) binds correctly.
    var genericDefaults = try env.arena.alloc(?*T.Type, r.genericParams.len);
    for (r.genericParams, 0..) |gp, i| {
        genericDefaults[i] = if (gp.default) |dft|
            try resolveTypeRefInContext(env, dft, genericMap)
        else
            null;
    }

    // Register the type definition.
    const typeId = env.allocTypeId();
    const implNames = try extractImplementNames(env.arena, r.implement);
    try env.registerTypeDef(r.name, .{ .record = .{
        .name = r.name,
        .id = typeId,
        .genericParams = genericIds,
        .genericDefaults = genericDefaults,
        .fields = fields,
        .implements = implNames,
        .renderable = implementsRenderable(r.implement),
        .opaque_ = r.isOpaque,
        .makers = if (r.isOpaque) try opaqueTypes.makers(env.arena, r) else &.{},
    } });

    // Build constructor function type: `fn(T1, T2, ...) -> RecordName<A,B,...>`.
    // The return type carries the generic type vars so that after call-site
    // unification `typeNameOf` can display the instantiated form, e.g. `Pair<Int,String>`.
    var paramTypes = try env.arena.alloc(*T.Type, r.recordFields().len);
    for (fields, 0..) |f, i| paramTypes[i] = f.type_;
    var retArgs = try env.arena.alloc(*T.Type, r.genericParams.len);
    for (r.genericParams, 0..) |gp, i| retArgs[i] = genericMap.get(gp.name).?;
    const retType = try env.namedTypeArgs(r.name, retArgs);
    const ctorType = try env.funcType(paramTypes, retType);
    try env.bind(r.name, ctorType);

    // Constructor params (F4 fn-param-default-expansion): every record field
    // is also a ctor param; expose its `default` Expr to the transform pass so
    // `expandTrailingDefaults` injects missing trailing defaults at the
    // `Config(...)` call site. Same rule as fn-decl call defaults.
    try env.ctorParams.put(r.name, try recordFieldsAsParams(env, r.recordFields()));
    if (r.isNamespace) try env.namespaceTypes.put(r.name, {});
    if (r.derivedFrom.len > 0 or r.derivedPartial) try env.derivedTypes.put(r.name, .{ .from = r.derivedFrom, .partial = r.derivedPartial });

    // Inherent method signatures (self = the record instance type).
    try registerInherentMethodTypes(env, r.name, retType, &genericMap, r.methods);
}

/// Resolve and store the signatures of a type's inherent methods so a later
/// `recv.method(args)` call can recover the method's real return type (instead
/// of a fresh var). `instanceType` is what `Self` resolves to — the type
/// applied to its own generic cells; `typeGenerics` maps the type's generic
/// param names to those cells. The stored signature is self-first:
/// `fn(self: Instance, params…) -> Ret`. `makeMethodCall` instantiates it per
/// call site, so the shared cells never collapse across calls.
fn registerInherentMethodTypes(
    env: *Env,
    typeName: []const u8,
    instanceType: *T.Type,
    typeGenerics: *const std.StringHashMap(*T.Type),
    methods: []const ast.BehaviorMethod,
) InferError!void {
    for (methods) |im| {
        // Register the method NAME for dispatch. This runs from registerRecord/
        // /Struct/Enum, so it also covers types brought in by `import … from
        // "std"` (which `registerExtensions` never sees — it only scans the
        // local program's decls).
        try env.addInherentMethod(typeName, im.name);
        // C-04 — and its parameters as written. This runs BEFORE the
        // return-type gate below: a method without an annotated return still
        // has declared defaults, and its call sites still have to fill them.
        try env.setInherentMethodParams(typeName, im.name, im.params);
        try env.setInherentMethodDecl(typeName, im);

        // Only methods with an explicit return-type annotation get a stored
        // signature. Without one the true return type comes from body inference
        // (not available here), so we leave such calls to the fresh-var fallback
        // rather than mis-typing them as `void`.
        const retRef = im.returnType orelse continue;
        // Per-method generic scope: the type's generics + `Self` + the method's
        // own generic params (fresh vars).
        var gm = std.StringHashMap(*T.Type).init(env.arena);
        defer gm.deinit();
        var git = typeGenerics.iterator();
        while (git.next()) |e| try gm.put(e.key_ptr.*, e.value_ptr.*);
        try gm.put("Self", instanceType);
        for (im.genericParams) |gp| try gm.put(gp.name, try env.freshVar());

        const params = try env.arena.alloc(*T.Type, im.params.len);
        for (im.params, 0..) |p, i| {
            params[i] = try resolveParamType(env, p, gm);
        }
        const ret = try resolveReturnType(env, retRef, im.returnTypeLoc, gm);
        try env.setInherentMethodType(typeName, im.name, try env.funcType(params, ret));
    }
}

/// A program's own `behavior` named like one std registered — a primitive's
/// (`behavior String { default fn shout(self: Self) … }`) or any other — EXTENDS
/// std's: the declaration under the name is std's with the program's members
/// added (and its `extends` joined), so `"x".startsWith(…)` and the program's
/// `"x".shout()` both answer, in the checker and in every backend that reads
/// `assocInterfaceDecls`. A member std's declaration already has is
/// `behavior-member-redeclared` at the program's member. The same declaration
/// registered again (a second pass over the program) merges against std's
/// original (`Env.stdBehaviorBase`), never against itself.
fn extendStdBehavior(env: *Env, d: ast.BehaviorDecl) InferError!ast.BehaviorDecl {
    const base: ast.BehaviorDecl = env.stdBehaviorBase.get(d.name) orelse blk: {
        const existing = env.assocInterfaceDecls.get(d.name) orelse return d;
        if (existing.methods.ptr == d.methods.ptr) return d;
        if (std.mem.startsWith(u8, env.modulePath, "std/")) return d;
        try env.stdBehaviorBase.put(env.arena, d.name, existing);
        break :blk existing;
    };
    for (d.methods) |m| for (base.methods) |bm| {
        if (!std.mem.eql(u8, m.name, bm.name)) continue;
        // Decision 799 (4) — a contract's member the primitive already has,
        // refused at the implementation that would add it.
        if (m.adoptedBy) |by| {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}.{s}` is a member of `{s}` already — `{s} implement {s} for {s}` adds members to `{s}` and redeclares none", .{ diagnostics.behavior_member_redeclared, by.contract, m.name, by.target, by.implementation, by.contract, by.target, by.target });
            env.lastError = TypeError.custom(msg, "Give the contract's member another name.").withLoc(by.loc);
            return error.TypeError;
        }
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}.{s}` is a member of std's `{s}` already — a program's `behavior {s}` adds members to std's and redeclares none", .{ diagnostics.behavior_member_redeclared, d.name, m.name, d.name, d.name });
        var e = TypeError.custom(msg, "Give the member another name.");
        if (m.returnTypeLoc.line != 0) e = e.withLoc(m.returnTypeLoc);
        env.lastError = e;
        return error.TypeError;
    };
    var merged = d;
    merged.methods = try std.mem.concat(env.arena, ast.BehaviorMethod, &.{ base.methods, d.methods });
    merged.fields = try std.mem.concat(env.arena, ast.BehaviorField, &.{ base.fields, d.fields });
    var ext: std.ArrayListUnmanaged([]const u8) = .empty;
    try ext.appendSlice(env.arena, base.extends);
    for (d.extends) |x| {
        const has = for (ext.items) |y| {
            if (std.mem.eql(u8, x, y)) break true;
        } else false;
        if (!has) try ext.append(env.arena, x);
    }
    merged.extends = ext.items;
    if (merged.genericParams.len == 0) merged.genericParams = base.genericParams;
    return merged;
}

/// Register an interface's associated functions — `default fn` members with no
/// `self` receiver (`Array.range`, `Array.repeat`) — under the
/// qualified name `"<Interface>.<method>"`, so `inferCallExpr` can resolve a
/// `Interface.method(...)` call as a callable. Interface + method generics are
/// generalized to `.generic`, so each call site instantiates fresh vars
/// (let-polymorphism, same as top-level generic fns). Methods that take a `self`
/// receiver are instance methods (handled by the inherent-method machinery) and
/// are skipped here.
fn registerInterfaceAssociatedFns(env: *Env, d: ast.BehaviorDecl) InferError!void {
    // Record EVERY interface decl so codegen can emit its namespace/prototype
    // when used, and the dispatch can follow the `extends` chain (markers like
    // `Integer extends Number` link the tower).
    try env.assocInterfaceDecls.put(d.name, try extendStdBehavior(env, d));
    for (d.methods) |im| {
        const has_self = im.params.len > 0 and std.mem.eql(u8, im.params[0].name, "self");
        if (has_self) continue;

        var gm = std.StringHashMap(*T.Type).init(env.arena);
        defer gm.deinit();
        for (d.genericParams) |gp| try gm.put(gp.name, try env.freshVar());
        for (im.genericParams) |gp| try gm.put(gp.name, try env.freshVar());

        const params = try env.arena.alloc(*T.Type, im.params.len);
        for (im.params, 0..) |p, i| {
            params[i] = try resolveParamType(env, p, gm);
        }
        const ret = if (im.returnType) |rt|
            try resolveReturnType(env, rt, im.returnTypeLoc, gm)
        else
            try env.namedType("void");
        const fnTy = try env.funcType(params, ret);

        // Generalize remaining unbound generics → `.generic`.
        var git = gm.valueIterator();
        while (git.next()) |gv| {
            const resolved = gv.*.deref();
            if (resolved.* != .typeVar) continue;
            switch (resolved.typeVar.state) {
                .unbound => |u| resolved.typeVar.state = .{ .generic = u.id },
                else => {},
            }
        }

        const qname = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ d.name, im.name });
        try env.bind(qname, fnTy);
    }
}

/// Infer a call to an interface associated function (`Array.range(0, n)`). `fnTy` is
/// the registered signature (`.generic` params); each call instantiates fresh
/// vars, unifies them with the args, and yields the instantiated return type.
fn inferAssociatedFnCall(
    env: *Env,
    recvName: []const u8,
    callee: []const u8,
    fnTy: *T.Type,
    typedReceiver: ?*ast.TypedExpr,
    typedArgs: []ast.CallArgOf(.typed),
    typedTrailing: []ast.TrailingLambdaOf(.typed),
    loc: ast.Loc,
) InferError!TypedExpr {
    // Mark the interface used so codegen emits its namespace object.
    try env.usedAssocInterfaces.put(recvName, {});
    const inst = (try instantiateGenericType(env, fnTy)).deref();
    if (inst.* != .func) {
        env.lastError = TypeError.custom("not an associated function", "").withLoc(loc);
        return error.TypeError;
    }
    const fp = inst.func.params;
    const total = typedArgs.len + typedTrailing.len;
    // C-04 — the associated fn's declared defaults fill a short call, and a
    // label names its parameter, as on every other call path: the site holds
    // only the instantiated `T.func`, so the parameters as written come from
    // the behavior's declaration.
    const fill: ?envMod.DefaultFill = fillBlk: {
        if (typedTrailing.len != 0) break :fillBlk null;
        const declared = associatedFnParams(env, recvName, callee) orelse break :fillBlk null;
        if (declared.len != fp.len or typedArgs.len > declared.len) break :fillBlk null;
        if (typedArgs.len < declared.len) break :fillBlk try recordDefaultFill(env, loc, declared, typedArgs);
        const plan = try planLabelledCall(env, callee, declared, typedArgs, loc) orelse break :fillBlk null;
        try env.defaultInjections.put(loc, plan);
        break :fillBlk plan;
    };
    if (fill) |plan| {
        try unifyFilledArgs(env, plan, fp, typedArgs);
    } else {
        if (total != fp.len) {
            env.lastError = TypeError.arityMismatch(callee, fp.len, total).withLoc(loc);
            return error.TypeError;
        }
        for (typedArgs, 0..) |arg, i| {
            try unifyAt(env, fp[i], arg.value.getType(), arg.value.getLoc());
        }
    }
    // Trailing lambdas fill the remaining params; unify a fresh fn shape.
    for (typedTrailing, 0..) |tl, i| {
        const lamParams = try env.arena.alloc(*T.Type, tl.params.len);
        for (lamParams) |*lp| lp.* = try env.freshVar();
        try unifyAt(env, fp[typedArgs.len + i], try env.funcType(lamParams, try env.freshVar()), loc);
    }
    return TypedExpr{ .call = .{ .loc = loc, .type_ = inst.func.ret, .kind = .{ .call = .{
        .receiver = typedReceiver,
        .callee = callee,
        .is_builtin = false,
        .args = typedArgs,
        .trailing = typedTrailing,
    } } } };
}

/// The parameters as written of the behavior `ifaceName`'s associated fn
/// `callee` (a member with no `self`), or null.
fn associatedFnParams(env: *Env, ifaceName: []const u8, callee: []const u8) ?[]const ast.Param {
    const decl = env.assocInterfaceDecls.get(ifaceName) orelse return null;
    for (decl.methods) |m| {
        if (!std.mem.eql(u8, m.name, callee)) continue;
        if (m.params.len > 0 and std.mem.eql(u8, m.params[0].name, "self")) continue;
        return m.params;
    }
    return null;
}

fn registerEnum(env: *Env, e: ast.TypeDecl) InferError!void {
    var genericMap = std.StringHashMap(*T.Type).init(env.arena);
    defer genericMap.deinit();
    var genericIds = try env.arena.alloc([]const u8, e.genericParams.len);
    for (e.genericParams, 0..) |gp, i| {
        const tv = try env.freshVar();
        try genericMap.put(gp.name, tv);
        genericIds[i] = gp.name;
    }

    // §enum-sections F1 — synthesise one inner enum per section under a mangled
    // path-encoded name (`__<EnumName>__<SectionPath>`) and surface them on the
    // parent as wrapper variants `Section(__EnumName__Section)`. The synthesised
    // enums live in the type-def table only — their constructor names are NOT
    // bound at the top level; path-access (`.Section.Inner.Leaf`) lowers to the
    // wrapped form during expression inference (F2).
    var section_wrappers = try env.arena.alloc(envMod.VariantDef, e.sections().len);
    for (e.sections(), 0..) |sec, si| {
        const inner_name = try registerEnumSection(env, e.name, &.{}, sec);
        const wrapper_field = try env.arena.alloc(envMod.FieldDef, 1);
        wrapper_field[0] = .{ .name = "_inner", .type_ = try env.namedType(inner_name) };
        section_wrappers[si] = .{ .name = sec.name, .fields = wrapper_field };
    }

    // F4G-tail — variant ctor return type carries the enum's generic cells, so
    // a call site sees `Result2<T_cell, E_cell>` and unification at the use site
    // pins each cell (e.g. `Result2.Yes(42)` binds T_cell = i32) AND a
    // function-return annotation that omits trailing args (`-> Result2<i32>`
    // with `E = string` default) resolves to the same arity. Without the
    // args the ctor would produce bare `Result2` and the unifier would see
    // arity mismatch against the defaults-filled annotation.
    var ctorRetArgs = try env.arena.alloc(*T.Type, e.genericParams.len);
    for (e.genericParams, 0..) |gp, i| ctorRetArgs[i] = genericMap.get(gp.name).?;
    const ctorRetType = if (e.genericParams.len == 0)
        try env.namedType(e.name)
    else
        try env.namedTypeArgs(e.name, ctorRetArgs);

    var variants = try env.arena.alloc(envMod.VariantDef, e.variants().len + section_wrappers.len);
    for (e.variants(), 0..) |v, vi| {
        var fields = try env.arena.alloc(envMod.FieldDef, v.fields.len);
        for (v.fields, 0..) |f, fi| {
            fields[fi] = .{
                .name = f.name,
                .type_ = try resolveFieldType(env, f, genericMap),
            };
        }
        variants[vi] = .{ .name = v.name, .fields = fields };

        // Each variant is also a constructor: unit → `EnumName<...>`, payload
        // → `fn(T...) → EnumName<...>`.
        const ctorType = if (v.fields.len == 0)
            ctorRetType
        else blk: {
            var ps = try env.arena.alloc(*T.Type, v.fields.len);
            for (fields, 0..) |f, i| ps[i] = f.type_;
            break :blk try env.funcType(ps, ctorRetType);
        };
        try env.bind(v.name, ctorType);
        try noteVariantClaim(env, e.name, v.name, ctorType);

        // Constructor params (F4 fn-param-default-expansion): register the
        // variant under both its bare name (`Error`) and the qualified path
        // (`Level.Error`) so transform's `expandTrailingDefaults` finds it for
        // either call shape — `Error("boom")` or `Level.Error("boom")`.
        const variant_params = try enumVariantAsParams(env, v);
        try env.ctorParams.put(v.name, variant_params);
        const qname = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ e.name, v.name });
        try env.ctorParams.put(qname, variant_params);
    }
    // Append the section wrappers after the bare variants — order is irrelevant
    // for type-def semantics, but stable for snapshot determinism.
    for (section_wrappers, 0..) |w, wi| {
        variants[e.variants().len + wi] = w;
        // 01 step 12 — the wrapper's constructor under its qualified name
        // (`Token.Color`); it has no bare binding.
        const ps = try env.arena.alloc(*T.Type, 1);
        ps[0] = w.fields[0].type_;
        try env.variantCtors.put(try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ e.name, w.name }), try env.funcType(ps, ctorRetType));
    }

    // §1G — resolve generic defaults against the same map.
    var genericDefaults = try env.arena.alloc(?*T.Type, e.genericParams.len);
    for (e.genericParams, 0..) |gp, i| {
        genericDefaults[i] = if (gp.default) |dft|
            try resolveTypeRefInContext(env, dft, genericMap)
        else
            null;
    }

    const enumTypeId = env.allocTypeId();
    const implNames = try extractImplementNames(env.arena, e.implement);
    try env.registerTypeDef(e.name, .{ .enum_ = .{
        .name = e.name,
        .id = enumTypeId,
        .genericParams = genericIds,
        .genericDefaults = genericDefaults,
        .variants = variants,
        .implements = implNames,
        .renderable = implementsRenderable(e.implement),
    } });
    // Bind the enum name itself so `inferDecl` can look it up.
    const enumInstance = try env.namedType(e.name);
    try env.bind(e.name, enumInstance);

    // Inherent method signatures (self = the enum instance type).
    try registerInherentMethodTypes(env, e.name, enumInstance, &genericMap, e.methods);
}

/// Synthesise a single enum-section as a hidden inner enum. Walks nested
/// sections first (depth-first), then composes the section's own variant list
/// as: bare/payload variants from `sec.variants` (digit names get the `_`
/// prefix codegen needs) + wrapper variants for each nested sub-section. The
/// mangled name (`__<EnumName>__<Path>__<SectionName>`) is registered as a
/// `TypeDef.enum_` and returned for the caller to wrap.
fn registerEnumSection(
    env: *Env,
    enum_name: []const u8,
    parent_path: []const []const u8,
    sec: ast.EnumSection,
) InferError![]const u8 {
    // path = parent_path ++ [sec.name]
    var path = try env.arena.alloc([]const u8, parent_path.len + 1);
    for (parent_path, 0..) |p, i| path[i] = p;
    path[parent_path.len] = sec.name;

    // mangled = "__" + enum_name + "__" + path.join("__")
    var mbuf: std.ArrayList(u8) = .empty;
    try mbuf.appendSlice(env.arena, "__");
    try mbuf.appendSlice(env.arena, enum_name);
    for (path) |seg| {
        try mbuf.appendSlice(env.arena, "__");
        try mbuf.appendSlice(env.arena, seg);
    }
    const mangled = try mbuf.toOwnedSlice(env.arena);

    // Recurse into sub-sections first; collect their mangled names.
    var sub_wrappers = try env.arena.alloc(envMod.VariantDef, sec.sections.len);
    for (sec.sections, 0..) |sub, i| {
        const sub_name = try registerEnumSection(env, enum_name, path, sub);
        const f = try env.arena.alloc(envMod.FieldDef, 1);
        f[0] = .{ .name = "_inner", .type_ = try env.namedType(sub_name) };
        sub_wrappers[i] = .{ .name = sub.name, .fields = f };
    }

    var variants = try env.arena.alloc(envMod.VariantDef, sec.variants.len + sub_wrappers.len);
    for (sec.variants, 0..) |v, i| {
        var fields = try env.arena.alloc(envMod.FieldDef, v.fields.len);
        // Inner section variants do not see the parent's generic params — they
        // are concrete by construction. An empty map suffices.
        var empty_map = std.StringHashMap(*T.Type).init(env.arena);
        defer empty_map.deinit();
        for (v.fields, 0..) |f, fi| {
            fields[fi] = .{
                .name = f.name,
                .type_ = try resolveFieldType(env, f, empty_map),
            };
        }
        // Pure-digit leaves carry the underscore-prefixed name codegen expects.
        // `__` prefix (not single `_`) — `_500` would trip commonJS's
        // tuple-index heuristic (`t._N` → `t[N]`) and lower a variant
        // access to bracket-with-number `obj[500]`, which misses the
        // string-keyed `"_500"` slot. `__500` keeps the JS field-access
        // form `obj.__500` intact.
        const variant_name = if (v.numeric)
            try std.fmt.allocPrint(env.arena, "__{s}", .{v.name})
        else
            v.name;
        variants[i] = .{ .name = variant_name, .fields = fields };
    }
    for (sub_wrappers, 0..) |w, i| variants[sec.variants.len + i] = w;
    // 01 step 12 — each section variant's constructor under its qualified
    // name (`__Token__Color.Hex`), so a leading-dot payload path resolves
    // through the section and not through a flat bare name.
    const sectionTy = try env.namedType(mangled);
    // The section enum's own name answers as a receiver (`__Token__Color.Hex(…)`
    // is what a payload section path is spliced into), as a declared enum's
    // name does; no source can spell a `__`-mangled name.
    try env.bind(mangled, sectionTy);
    for (variants) |v| {
        const ctor = if (v.fields.len == 0) sectionTy else blk: {
            const ps = try env.arena.alloc(*T.Type, v.fields.len);
            for (v.fields, 0..) |f, i| ps[i] = f.type_;
            break :blk try env.funcType(ps, sectionTy);
        };
        try env.variantCtors.put(try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ mangled, v.name }), ctor);
    }

    const type_id = env.allocTypeId();
    try env.registerTypeDef(mangled, .{ .enum_ = .{
        .name = mangled,
        .id = type_id,
        .genericParams = &.{},
        .genericDefaults = &.{},
        .variants = variants,
        .implements = &.{},
    } });

    // §enum-sections F4 — also build the matching AST enum TypeDecl so the
    // post-inference `withSynthesisedEnumDecls` pass can prepend it to
    // `program.decls`, giving codegen a top-level enum to emit (mirroring
    // the manually-written enum-of-enum form, byte-identical at codegen).
    try registerSynthesisedEnumDecl(env, mangled, sec, sub_wrappers);

    return mangled;
}

/// §enum-sections F4 — assemble the AST enum `TypeDecl` for a synthesised inner
/// enum (the one `registerEnumSection` just registered under `mangled`). The
/// decl carries the section's bare/payload variants (`sec.variants`, with the
/// `_` prefix on numeric leaves matching the F1 mangling) followed by one
/// wrapper variant per sub-section (`{ name: <SubSection>, fields: [{name:
/// "_inner", typeRef: named "__Enum__Path__SubSection"}] }`). The decl lands
/// in `env.synthesisedEnumDecls` keyed by `mangled` — a later post-pass
/// inlines it into the program's top-level decls so codegen emits it normally.
fn registerSynthesisedEnumDecl(
    env: *Env,
    mangled: []const u8,
    sec: ast.EnumSection,
    sub_wrappers: []const envMod.VariantDef,
) InferError!void {
    var ast_variants = try env.arena.alloc(ast.EnumVariant, sec.variants.len + sub_wrappers.len);
    for (sec.variants, 0..) |v, i| {
        // `__` prefix (not single `_`) — `_500` would trip commonJS's
        // tuple-index heuristic (`t._N` → `t[N]`) and lower a variant
        // access to bracket-with-number `obj[500]`, which misses the
        // string-keyed `"_500"` slot. `__500` keeps the JS field-access
        // form `obj.__500` intact.
        const variant_name = if (v.numeric)
            try std.fmt.allocPrint(env.arena, "__{s}", .{v.name})
        else
            v.name;
        // Copy the variant fields (the AST owns them by slice, so we reslice
        // through the arena to keep ownership clean even though the source
        // EnumSection still references them).
        const fields = try env.arena.alloc(ast.Field, v.fields.len);
        for (v.fields, 0..) |f, fi| fields[fi] = f;
        ast_variants[i] = .{ .name = variant_name, .fields = fields, .numeric = v.numeric };
    }
    // Wrapper variants for nested sub-sections — single `_inner` field typed
    // to the sub-section's mangled name. The sub_wrappers slice carries the
    // resolved inner types; we recover the mangled name from the FieldDef's
    // named type for the AST TypeRef.
    for (sub_wrappers, 0..) |w, i| {
        std.debug.assert(w.fields.len == 1);
        const inner_type = w.fields[0].type_.deref();
        std.debug.assert(inner_type.* == .named);
        const fields = try env.arena.alloc(ast.Field, 1);
        fields[0] = .{
            .name = "_inner",
            .typeRef = .{ .named = inner_type.named.name },
            .default = null,
        };
        ast_variants[sec.variants.len + i] = .{
            .name = w.name,
            .fields = fields,
            .numeric = false,
        };
    }
    const enum_decl = ast.TypeDecl{
        .name = mangled,
        .isPub = false,
        .shape = .{ .enum_ = .{ .variants = ast_variants } },
    };
    try env.synthesisedEnumDecls.put(mangled, enum_decl);
}

// ── §enum-sections F2 — path-access resolution ──────────────────────────────
//
// A dot-shorthand chain rooted at a `.dotIdent` (`.Color.Red.500`) may resolve
// as a section path on an enum carrying sections (F1 desugar). The first
// segment is matched against every registered enum's variants — when a hit
// names a section wrapper (the synthesised `Section(_inner: __Enum__Section)`
// variant), the rest of the path walks through the inner enum's variants
// recursively. Pure-digit leaves (`500`) are looked up under their
// underscore-prefixed name (`_500`) to match the synthesised mangling.
//
// The lowering builds nested constructor calls: `Color(Red(_500))` where each
// call carries the proper type from the enum it constructs.

/// Walk an `identAccess` chain rooted at a `.dotIdent`, collect segments from
/// head to leaf, and try to resolve them as a section path on some enum.
/// Returns `null` when the chain doesn't root at a dotIdent or no enum
/// matches the path. Takes the leaf member + receiver separately because the
/// `identAccess` payload is an anonymous struct, not a nameable type.
///
/// 00 · 01-checker — WHICH enum carries the path is decided by the expected
/// type (`env.expectedType`), never by the order `env.typeDefs` happens to
/// hand the enums over: that map holds the synthesised section enums beside
/// the declared ones, so `.Color.Red.500` is carried by emilia's `Token` and
/// by `__Token__Border` alike and the winner used to change with the size of
/// the typedef set.
fn tryResolveEnumSectionPath(
    env: *Env,
    leaf_member: []const u8,
    leaf_receiver: *const ast.Expr,
    loc: ast.Loc,
) InferError!?TypedExpr {
    // Collect chain segments by walking inward through nested identAccess.
    // Top-level call supplies the LEAF member; we walk inward to the root
    // `dotIdent` whose name is the FIRST segment.
    var segs: std.ArrayList([]const u8) = .empty;
    defer segs.deinit(env.arena);
    // The location of each segment's node, parallel to `segs` (N17 — the
    // caret of an unresolved path points at the offending segment).
    var segLocs: std.ArrayList(ast.Loc) = .empty;
    defer segLocs.deinit(env.arena);
    try segs.append(env.arena, leaf_member);
    try segLocs.append(env.arena, loc);
    var cur: *const ast.Expr = leaf_receiver;
    // The enum a fully qualified chain names outright (`Token.Color.Red.500`).
    var qualified_owner: ?envMod.TypeDef.Enum = null;
    while (true) {
        if (cur.* != .identifier) return null;
        switch (cur.*.identifier.kind) {
            .identAccess => |sub| {
                try segs.append(env.arena, sub.member);
                try segLocs.append(env.arena, cur.*.getLoc());
                cur = sub.receiver;
            },
            .dotIdent => |name| {
                try segs.append(env.arena, name);
                try segLocs.append(env.arena, cur.*.getLoc());
                break;
            },
            .ident => |name| {
                // 00 · 01-checker — the fully qualified spelling names its
                // enum: `Token.Color.Red.500`. The root identifier is the
                // owner and the rest of the chain is the path, so the one
                // spelling that carries the answer in itself is not refused.
                // A two-segment `Color.Red` is an ordinary variant access and
                // stays on the regular identAccess path below.
                if (segs.items.len < 2) return null;
                const td = env.lookupTypeDef(name) orelse return null;
                if (td != .enum_) return null;
                qualified_owner = td.enum_;
                break;
            },
        }
    }
    // segs is leaf→head; reverse to head→leaf for path walking.
    std.mem.reverse([]const u8, segs.items);
    std.mem.reverse(ast.Loc, segLocs.items);

    if (qualified_owner) |owner| {
        // The enum is named, so there is no candidate set and nothing to be
        // ambiguous about. A chain that turns out not to be a section path is
        // handed back to the ordinary identAccess handling, which reports it.
        if (!enumCarriesSectionPath(env, owner, segs.items)) return null;
        // 01 step 4 (d) — where the position expects the SECTION's own type
        // (`val w: Token.Text = Token.Text.Italic;`), the path names a value
        // of that section, not of the enum carrying it.
        if (try sectionValueForExpected(env, owner.name, segs.items, loc)) |te| return te;
        return try resolveAndRecordSectionPath(env, owner, segs.items, loc);
    }

    if (segs.items.len < 2) return null;

    // Collect EVERY registered enum whose top-level variant matches the head
    // segment AND whose section tree carries the rest of the path. The set,
    // not the first hit, is what the choice is made from.
    // Also remember the enum whose HEAD segment matched (`enum_with_head`)
    // so a partial-match path (head OK, tail wrong: `.Color.Bogus`) can
    // raise ES4 with a focused message instead of bubbling a confusing
    // generic "unknown field" error from the fall-through code.
    var candidates: std.ArrayList([]const u8) = .empty;
    defer candidates.deinit(env.arena);
    // Every enum whose head segment matched a section wrapper — the set, so
    // the ES4 wording is not a function of the hash map's order.
    var heads: std.ArrayList([]const u8) = .empty;
    defer heads.deinit(env.arena);
    var it = env.typeDefs.iterator();
    while (it.next()) |entry| {
        const td = entry.value_ptr.*;
        if (td != .enum_) continue;
        const en = td.enum_;
        if (enumCarriesSectionPath(env, en, segs.items)) {
            if (!containsStr(candidates.items, en.name)) try candidates.append(env.arena, en.name);
            continue;
        }
        // Did the head segment at least match a section wrapper on this
        // enum? If yes, the user intended a section path on this enum — a
        // bad tail is an ES4 candidate.
        if (headSectionVariantOn(en, segs.items[0]) and !containsStr(heads.items, en.name)) {
            try heads.append(env.arena, en.name);
        }
    }

    if (candidates.items.len > 0) {
        // One carrier: the path names it. More than one: the expected type of
        // this position is what decides — an annotation, a declared parameter,
        // the return target, an array literal's element type.
        const chosen: ?[]const u8 = if (candidates.items.len == 1)
            candidates.items[0]
        else
            expectedEnumAmong(env.expectedType, candidates.items);
        if (chosen) |name| {
            const owner = env.lookupTypeDef(name).?.enum_;
            return try resolveAndRecordSectionPath(env, owner, segs.items, loc);
        }
        // ES5 — more than one enum carries the path and nothing here says
        // which. Refuse, naming every candidate: picking one is what made the
        // answer a function of the hash order, and the position that cannot
        // say what it expects is the position that has to spell it out.
        return raiseAmbiguousSectionPath(env, candidates.items, segs.items, segLocs.items[0]);
    }

    // ES4 — chain looks like a section path (`.<Section>.<more>` rooted at
    // a dotIdent, ≥ 2 segments) and the head matched a known section
    // wrapper, but the tail didn't resolve. Raise a focused error so the
    // user sees "enum 'Token' has no path '.Color.Bogus'" instead of the
    // generic fall-through diagnostic.
    if (heads.items.len > 0) {
        // One enum carries the head: it is the one meant. Several: the
        // position's expected type names it; with none, the refusal names
        // every one of them, sorted, instead of whichever the walk met first.
        const chosen: ?[]const u8 = if (heads.items.len == 1)
            heads.items[0]
        else
            expectedEnumAmong(env.expectedType, heads.items);
        const path_text = try sectionPathText(env, segs.items);
        const owner = chosen orelse {
            std.mem.sort([]const u8, heads.items, {}, struct {
                fn lessThan(_: void, a: []const u8, b: []const u8) bool {
                    return std.mem.order(u8, a, b) == .lt;
                }
            }.lessThan);
            var names: std.ArrayList(u8) = .empty;
            defer names.deinit(env.arena);
            for (heads.items, 0..) |name, i| {
                if (i > 0) try names.appendSlice(env.arena, if (i + 1 == heads.items.len) " and " else ", ");
                try names.append(env.arena, '"');
                try names.appendSlice(env.arena, name);
                try names.append(env.arena, '"');
            }
            const msg = try std.fmt.allocPrint(
                env.arena,
                "no enum has the path \"{s}\" — {s} each have a section \"{s}\" (ES4 — enum-sections path resolution)",
                .{ path_text, names.items, segs.items[0] },
            );
            const badLoc = if (segLocs.items.len > 1) segLocs.items[1] else loc;
            env.lastError = TypeError.custom(msg, "Check the section/variant chain against the enum declarations' `sections` trees; numeric leaves are matched under their declared digit form (`.Color.Red.500`).").withLoc(badLoc);
            return error.TypeError;
        };
        const msg = try std.fmt.allocPrint(
            env.arena,
            "enum \"{s}\" has no path \"{s}\" (ES4 — enum-sections path resolution)",
            .{ owner, path_text },
        );
        const bad = firstUnresolvedSectionSegment(env, env.lookupTypeDef(owner).?.enum_, segs.items);
        const badLoc = if (bad < segLocs.items.len) segLocs.items[bad] else loc;
        env.lastError = TypeError.custom(msg, "Check the section/variant chain against the enum declaration's `sections` tree; numeric leaves are matched under their declared digit form (`.Color.Red.500`).").withLoc(badLoc);
        return error.TypeError;
    }
    return null;
}

/// 01 step 4 (d) — `Token.Text.Italic` where `Token.Text` is expected: the
/// section enum's own variant (`__Token__Text.Italic`), recorded as the
/// path's rewrite. Null when the expectation is not the section the path's
/// prefix names.
fn sectionValueForExpected(env: *Env, owner: []const u8, path: []const []const u8, loc: ast.Loc) InferError!?TypedExpr {
    if (path.len < 2) return null;
    const want = (env.expectedType orelse return null).deref();
    if (want.* != .named) return null;
    var mbuf: std.ArrayList(u8) = .empty;
    try mbuf.appendSlice(env.arena, "__");
    try mbuf.appendSlice(env.arena, owner);
    for (path[0 .. path.len - 1]) |seg| {
        try mbuf.appendSlice(env.arena, "__");
        try mbuf.appendSlice(env.arena, seg);
    }
    if (!std.mem.eql(u8, mbuf.items, want.named.name)) return null;
    const td = env.lookupTypeDef(want.named.name) orelse return null;
    if (td != .enum_) return null;
    const leaf = path[path.len - 1];
    const has = for (td.enum_.variants) |v| {
        if (std.mem.eql(u8, v.name, leaf) and v.fields.len == 0) break true;
    } else false;
    if (!has) return null;
    const recv = try env.arena.create(ast.Expr);
    recv.* = .{ .identifier = .{ .loc = .{ .line = 0, .col = 0 }, .kind = .{ .ident = want.named.name } } };
    const node = try env.arena.create(ast.Expr);
    node.* = .{ .identifier = .{ .loc = .{ .line = 0, .col = 0 }, .kind = .{ .identAccess = .{ .receiver = recv, .member = leaf } } } };
    try env.enumSectionRewrites.put(loc, node);
    env.expectedType = null;
    return try inferExprTyped(env, node.*);
}

/// The chain as the user wrote it, leading dot and all: `.Color.Red.500`.
fn sectionPathText(env: *Env, path: []const []const u8) InferError![]const u8 {
    var buf: std.ArrayList(u8) = .empty;
    defer buf.deinit(env.arena);
    for (path) |seg| {
        try buf.append(env.arena, '.');
        try buf.appendSlice(env.arena, seg);
    }
    return buf.toOwnedSlice(env.arena);
}

/// ES5 — the path is carried by more than one enum and nothing at this
/// position says which. Refuse, naming every candidate.
///
/// Picking one is what made the answer depend on `env.typeDefs`' hash order,
/// and a pick cannot be right here: the two enums are different types and the
/// program means one of them. The candidates are sorted so the message is the
/// same on every run — the set comes off a hash map.
fn raiseAmbiguousSectionPath(
    env: *Env,
    candidates: [][]const u8,
    path: []const []const u8,
    loc: ast.Loc,
) InferError!?TypedExpr {
    std.mem.sort([]const u8, candidates, {}, struct {
        fn lessThan(_: void, a: []const u8, b: []const u8) bool {
            return std.mem.order(u8, a, b) == .lt;
        }
    }.lessThan);
    var names: std.ArrayList(u8) = .empty;
    defer names.deinit(env.arena);
    for (candidates, 0..) |name, i| {
        if (i > 0) try names.appendSlice(env.arena, if (i + 1 == candidates.len) " and " else ", ");
        try names.append(env.arena, '"');
        try names.appendSlice(env.arena, name);
        try names.append(env.arena, '"');
    }
    const msg = try std.fmt.allocPrint(
        env.arena,
        "the path \"{s}\" is carried by more than one enum — {s} — and nothing here says which (ES5 — enum-sections path ambiguity)",
        .{ try sectionPathText(env, path), names.items },
    );
    env.lastError = TypeError.custom(
        msg,
        "Give the position a type the path can be read against — a `val` annotation, a declared parameter, the function's return type — or write the path from its enum (`Token.Color.Red.500`).",
    ).withLoc(loc);
    return error.TypeError;
}

/// Resolve `path` in `en` and record the untyped rewrite for it.
///
/// The rewrite is the equivalent qualified-ctor form, stashed under this
/// chain's outermost loc. The post-inference rewrite pass
/// (`withEnumSectionRewrites` in `comptime.zig`) walks the untyped AST and
/// swaps the original chain for it, so codegen — which reads the untyped AST —
/// emits `Token.Color(__Token__Color.Red(…))` instead of the source text.
fn resolveAndRecordSectionPath(
    env: *Env,
    en: envMod.TypeDef.Enum,
    path: []const []const u8,
    loc: ast.Loc,
) InferError!?TypedExpr {
    const resolved = try resolveSectionPathInEnum(env, en, path, loc) orelse return null;
    if (try buildSectionPathRewrite(env, en, path)) |rewrite| {
        try env.enumSectionRewrites.put(loc, rewrite);
    }
    return resolved;
}

/// The candidate `expected` names, or null when the expectation says nothing
/// about the choice (there is none, it is still a type variable, or it names
/// an enum that carries no such path). `?Token` answers `Token`: the
/// expectation of an optional position is the optional's inner type.
fn expectedEnumAmong(expected: ?*T.Type, candidates: []const []const u8) ?[]const u8 {
    var ty = (expected orelse return null).deref();
    if (ty.* == .named and std.mem.eql(u8, ty.named.name, "optional") and ty.named.args.len == 1) {
        ty = ty.named.args[0].deref();
    }
    if (ty.* != .named) return null;
    for (candidates) |c| if (std.mem.eql(u8, c, ty.named.name)) return c;
    return null;
}

/// True when `en`'s section tree carries `path` all the way down to a unit
/// variant — the predicate form of `resolveSectionPathInEnum`, so the set of
/// carriers can be collected without building a typed node for each one. The
/// two walk the same steps and must keep agreeing: a path this answers `true`
/// for is a path `resolveSectionPathInEnum` resolves.
fn enumCarriesSectionPath(env: *Env, en: envMod.TypeDef.Enum, path: []const []const u8) bool {
    if (path.len == 0) return false;
    var current = en;
    for (path, 0..) |seg, i| {
        var matched: ?envMod.VariantDef = null;
        for (current.variants) |v| {
            if (std.mem.eql(u8, v.name, seg) or
                (looksNumeric(seg) and v.name.len > 1 and v.name[0] == '_' and v.name[1] == '_' and std.mem.eql(u8, v.name[2..], seg)))
            {
                matched = v;
                break;
            }
        }
        const variant = matched orelse return false;
        // The leaf of a section path is a unit variant; a payload variant
        // (`Hex(value: string)`) is a call, not the end of a chain.
        if (i + 1 == path.len) return variant.fields.len == 0;
        // Every inner segment must be a section wrapper.
        if (variant.fields.len != 1 or !std.mem.eql(u8, variant.fields[0].name, "_inner")) return false;
        const inner_type = variant.fields[0].type_.deref();
        if (inner_type.* != .named) return false;
        const inner_def = env.lookupTypeDef(inner_type.named.name) orelse return false;
        if (inner_def != .enum_) return false;
        current = inner_def.enum_;
    }
    return false;
}

/// Index of the first segment of `path` that does not name a variant or a
/// section wrapper on the way down `en`'s section tree.
fn firstUnresolvedSectionSegment(env: *Env, en: envMod.TypeDef.Enum, path: []const []const u8) usize {
    var current = en;
    for (path, 0..) |seg, i| {
        var matched: ?envMod.VariantDef = null;
        for (current.variants) |v| {
            if (std.mem.eql(u8, v.name, seg) or
                (looksNumeric(seg) and v.name.len > 1 and v.name[0] == '_' and v.name[1] == '_' and std.mem.eql(u8, v.name[2..], seg)))
            {
                matched = v;
                break;
            }
        }
        const variant = matched orelse return i;
        if (i + 1 == path.len) return path.len;
        if (variant.fields.len != 1 or !std.mem.eql(u8, variant.fields[0].name, "_inner")) return i + 1;
        const inner_type = variant.fields[0].type_.deref();
        if (inner_type.* != .named) return i + 1;
        const inner_def = env.lookupTypeDef(inner_type.named.name) orelse return i + 1;
        if (inner_def != .enum_) return i + 1;
        current = inner_def.enum_;
    }
    return path.len;
}

/// True iff `enum_def` has a section-wrapper variant named `head`. Used
/// by the ES4 partial-match detector to identify which enum the user
/// likely intended in a failed path-access chain.
fn headSectionVariantOn(enum_def: envMod.TypeDef.Enum, head: []const u8) bool {
    for (enum_def.variants) |v| {
        if (!std.mem.eql(u8, v.name, head)) continue;
        // A section wrapper carries exactly one `_inner` field whose type
        // is a named (synthesised) enum. Bare variants carry zero fields
        // and don't qualify as a "section path head".
        if (v.fields.len != 1) return false;
        if (!std.mem.eql(u8, v.fields[0].name, "_inner")) return false;
        return true;
    }
    return false;
}

/// §enum-sections F2 — assemble the UNTYPED AST equivalent of the qualified
/// nested ctor call (`<EnumName>.<Section>(_inner: <recurse>)` … leaf is
/// `<EnumName>.<variant>` identAccess). The codegen-side rewrite pass
/// substitutes this expression in place of the dot-shorthand chain.
///
/// All synthesised nodes carry the sentinel loc `{line=0, col=0}` so a
/// second pass over the rewritten tree (the transform walker recurses into
/// the substituted expression) does not re-trigger the rewrite map lookup —
/// real source locs always have `line >= 1`.
fn buildSectionPathRewrite(
    env: *Env,
    en: envMod.TypeDef.Enum,
    path: []const []const u8,
) InferError!?*const ast.Expr {
    if (path.len == 0) return null;
    const head = path[0];
    const rest = path[1..];

    var matched: ?envMod.VariantDef = null;
    for (en.variants) |v| {
        if (std.mem.eql(u8, v.name, head) or
            (looksNumeric(head) and v.name.len > 1 and v.name[0] == '_' and v.name[1] == '_' and std.mem.eql(u8, v.name[2..], head)))
        {
            matched = v;
            break;
        }
    }
    const variant = matched orelse return null;

    const synth_loc = ast.Loc{ .line = 0, .col = 0 };

    // Recv: `ident(en.name)` — the enum name binding lookup happens at
    // codegen via stringification only; no env lookup needed.
    const enum_recv = try env.arena.create(ast.Expr);
    enum_recv.* = ast.Expr{ .identifier = .{
        .loc = synth_loc,
        .kind = .{ .ident = en.name },
    } };

    if (rest.len == 0) {
        if (variant.fields.len != 0) return null;
        // Leaf: `<EnumName>.<variant>` identAccess.
        const leaf = try env.arena.create(ast.Expr);
        leaf.* = ast.Expr{ .identifier = .{
            .loc = synth_loc,
            .kind = .{ .identAccess = .{
                .receiver = enum_recv,
                .member = variant.name,
            } },
        } };
        return leaf;
    }

    // Non-leaf: must be a section wrapper.
    if (variant.fields.len != 1) return null;
    if (!std.mem.eql(u8, variant.fields[0].name, "_inner")) return null;
    const inner_type = variant.fields[0].type_.deref();
    if (inner_type.* != .named) return null;
    const inner_def = env.lookupTypeDef(inner_type.named.name) orelse return null;
    if (inner_def != .enum_) return null;

    const inner_rewrite = try buildSectionPathRewrite(env, inner_def.enum_, rest) orelse return null;

    // Build the call args slice with a single named `_inner` arg.
    const args = try env.arena.alloc(ast.CallArg, 1);
    args[0] = .{
        .label = "_inner",
        .value = @constCast(inner_rewrite),
        .comments = &.{},
    };
    const trailing = try env.arena.alloc(ast.TrailingLambda, 0);
    const call = try env.arena.create(ast.Expr);
    call.* = ast.Expr{ .call = .{
        .loc = synth_loc,
        .kind = .{ .call = .{
            .receiver = enum_recv,
            .callee = variant.name,
            .is_builtin = false,
            .args = args,
            .trailing = trailing,
        } },
    } };
    return call;
}

/// Try to resolve a path `[head, ..., leaf]` through enum `en`'s variants. The
/// head must match an enum variant; if that variant carries a single field
/// named `_inner` typed to a synthesised inner enum, recurse the rest of the
/// path into it. Pure-digit segments are looked up with an `_` prefix to
/// match the F1 mangling. Returns the built typed nested-ctor-call expression
/// or `null` if the path doesn't match.
///
/// The lowered shape is fully qualified at every level — leaves are emitted
/// as `identAccess(<EnumName>, <variant>)` and section wrappers as call
/// expressions whose receiver names the enum — so the codegen produces the
/// equivalent of the manually-written `Token.Color(__Token__Color.Red(…))`
/// form without needing to know which enum a bare `Color(...)` came from.
fn resolveSectionPathInEnum(
    env: *Env,
    en: envMod.TypeDef.Enum,
    path: []const []const u8,
    loc: ast.Loc,
) InferError!?TypedExpr {
    if (path.len == 0) return null;
    const head = path[0];
    const rest = path[1..];

    // Find the variant matching the head segment.
    var matched: ?envMod.VariantDef = null;
    for (en.variants) |v| {
        if (std.mem.eql(u8, v.name, head) or
            (looksNumeric(head) and v.name.len > 1 and v.name[0] == '_' and v.name[1] == '_' and std.mem.eql(u8, v.name[2..], head)))
        {
            matched = v;
            break;
        }
    }
    const variant = matched orelse return null;

    const enum_type = try env.namedType(en.name);

    if (rest.len == 0) {
        // Leaf: unit variant ⇒ `<EnumName>.<variant>` identAccess so codegen
        // emits the qualified form (`__Token__Color__Red._500` in JS). Bare
        // `dotIdent(_500)` would lose the enum context the synthesised inner
        // enums need. Payload variants without a section-wrapper `_inner`
        // field can't terminate a section-path chain.
        if (variant.fields.len != 0) return null;
        const enum_ident = try makeTypedPtr(env, TypedExpr{ .identifier = .{
            .loc = loc,
            .type_ = enum_type,
            .kind = .{ .ident = en.name },
        } });
        return TypedExpr{ .identifier = .{ .loc = loc, .type_ = enum_type, .kind = .{ .identAccess = .{
            .receiver = enum_ident,
            .member = variant.name,
        } } } };
    }

    // Non-leaf: variant must be a section wrapper — single `_inner` field
    // typed to a synthesised inner enum.
    if (variant.fields.len != 1) return null;
    if (!std.mem.eql(u8, variant.fields[0].name, "_inner")) return null;
    const inner_type = variant.fields[0].type_.deref();
    if (inner_type.* != .named) return null;
    const inner_def = env.lookupTypeDef(inner_type.named.name) orelse return null;
    if (inner_def != .enum_) return null;

    const inner_val = try resolveSectionPathInEnum(env, inner_def.enum_, rest, loc) orelse return null;
    const inner_ptr = try makeTypedPtr(env, inner_val);

    // Wrap in this section's ctor call with a qualified receiver:
    // `<EnumName>.Section(_inner: <inner_val>)`. The qualified form lets the
    // backends route through the parent enum's section-wrapper ctor without
    // needing a bare `Section` binding in env.
    const enum_ident = try makeTypedPtr(env, TypedExpr{ .identifier = .{
        .loc = loc,
        .type_ = enum_type,
        .kind = .{ .ident = en.name },
    } });
    var args = try env.arena.alloc(ast.CallArgOf(.typed), 1);
    args[0] = .{ .label = "_inner", .value = inner_ptr, .comments = &.{} };
    return TypedExpr{ .call = .{ .loc = loc, .type_ = enum_type, .kind = .{ .call = .{
        .receiver = enum_ident,
        .callee = variant.name,
        .is_builtin = false,
        .args = args,
        .trailing = &.{},
    } } } };
}

/// 01 step 12 — `.Color.Hex("#abc")` / `Token.Color.Hex("#abc")`: a section
/// path whose LEAF is a payload variant, written as a call. The unit-leaf path
/// (`.Color.Red.500`) is an identifier chain and `tryResolveEnumSectionPath`
/// answers it; a call was never walked, so its receiver `.Color` fell to the
/// flat table and resolved to whatever enum last declared a bare `Color` —
/// `Ns` in emilia, a type the author never wrote. The enum is chosen exactly
/// as the unit path chooses it: the one written (`Token.…`), the one carrier,
/// or the one the position expects; several carriers and no expectation is
/// ES5's refusal. The qualified constructor chain is spliced in through the
/// index channel, so no backend learns a shape.
fn tryResolveSectionPayloadCall(env: *Env, c: ast.CallExprOf(.untyped), receiver: *const ast.Expr, loc: ast.Loc) InferError!?TypedExpr {
    const call = c.kind.call;
    var segs: std.ArrayList([]const u8) = .empty;
    defer segs.deinit(env.arena);
    var cur: *const ast.Expr = receiver;
    var owner: ?envMod.TypeDef.Enum = null;
    var head_loc: ast.Loc = loc;
    while (true) {
        if (cur.* != .identifier) return null;
        switch (cur.*.identifier.kind) {
            .identAccess => |sub| {
                try segs.append(env.arena, sub.member);
                cur = sub.receiver;
            },
            .dotIdent => |name| {
                try segs.append(env.arena, name);
                head_loc = cur.*.getLoc();
                break;
            },
            .ident => |name| {
                // `Token.Color.Hex(…)`: the root names the enum, and at least
                // one section segment follows it (`Token.Hex(…)` is an
                // ordinary qualified constructor call).
                if (segs.items.len == 0) return null;
                const td = env.lookupTypeDef(name) orelse return null;
                if (td != .enum_) return null;
                owner = td.enum_;
                head_loc = cur.*.getLoc();
                break;
            },
        }
    }
    std.mem.reverse([]const u8, segs.items);
    try segs.append(env.arena, call.callee);
    const path = segs.items;

    const chosen: envMod.TypeDef.Enum = if (owner) |o| blk: {
        if (!enumCarriesPayloadSectionPath(env, o, path)) return null;
        break :blk o;
    } else blk: {
        var candidates: std.ArrayList([]const u8) = .empty;
        defer candidates.deinit(env.arena);
        var it = env.typeDefs.iterator();
        while (it.next()) |entry| {
            const td = entry.value_ptr.*;
            if (td != .enum_) continue;
            if (enumCarriesPayloadSectionPath(env, td.enum_, path) and !containsStr(candidates.items, td.enum_.name))
                try candidates.append(env.arena, td.enum_.name);
        }
        if (candidates.items.len == 0) return null;
        const pick: ?[]const u8 = if (candidates.items.len == 1) candidates.items[0] else expectedEnumAmong(env.expectedType, candidates.items);
        const name = pick orelse {
            const locs = try env.arena.alloc(ast.Loc, path.len);
            for (locs) |*l| l.* = head_loc;
            _ = try raiseAmbiguousSectionPath(env, candidates.items, path, locs[0]);
            return error.TypeError;
        };
        break :blk env.lookupTypeDef(name).?.enum_;
    };
    const tree = try buildPayloadSectionRewrite(env, chosen, path, c, loc) orelse return null;
    try env.indexRewrites.put(loc, tree);
    env.expectedType = null;
    return try inferExprTyped(env, tree.*);
}

/// `enumCarriesSectionPath` for a path whose leaf is a PAYLOAD variant: every
/// segment but the last is a section wrapper, the last a variant with fields.
fn enumCarriesPayloadSectionPath(env: *Env, en: envMod.TypeDef.Enum, path: []const []const u8) bool {
    if (path.len < 2) return false;
    var current = en;
    for (path, 0..) |seg, i| {
        var matched: ?envMod.VariantDef = null;
        for (current.variants) |v| {
            if (std.mem.eql(u8, v.name, seg)) {
                matched = v;
                break;
            }
        }
        const variant = matched orelse return false;
        const isWrapper = variant.fields.len == 1 and std.mem.eql(u8, variant.fields[0].name, "_inner");
        if (i + 1 == path.len) return variant.fields.len > 0 and !isWrapper;
        if (!isWrapper) return false;
        const inner_type = variant.fields[0].type_.deref();
        if (inner_type.* != .named) return false;
        const inner_def = env.lookupTypeDef(inner_type.named.name) orelse return false;
        if (inner_def != .enum_) return false;
        current = inner_def.enum_;
    }
    return false;
}

/// The untyped qualified chain for a payload section path: every wrapper is
/// `<Enum>.<Section>(_inner: …)` and the leaf is `<Section enum>.<Variant>(args)`
/// with the call's own arguments. The outermost node carries the call's loc
/// (it replaces the call); inner nodes the sentinel `{0, 0}`.
fn buildPayloadSectionRewrite(env: *Env, en: envMod.TypeDef.Enum, path: []const []const u8, c: ast.CallExprOf(.untyped), loc: ast.Loc) InferError!?*ast.Expr {
    const synth_loc = ast.Loc{ .line = 0, .col = 0 };
    const recv = try env.arena.create(ast.Expr);
    recv.* = .{ .identifier = .{ .loc = synth_loc, .kind = .{ .ident = en.name } } };
    const node = try env.arena.create(ast.Expr);
    if (path.len == 1) {
        var leaf = c;
        leaf.loc = loc;
        leaf.kind.call.receiver = recv;
        leaf.kind.call.callee = path[0];
        node.* = .{ .call = leaf };
        return node;
    }
    var inner_def: ?envMod.TypeDef.Enum = null;
    for (en.variants) |v| {
        if (!std.mem.eql(u8, v.name, path[0])) continue;
        const it = v.fields[0].type_.deref();
        if (it.* != .named) return null;
        const d = env.lookupTypeDef(it.named.name) orelse return null;
        if (d != .enum_) return null;
        inner_def = d.enum_;
    }
    const inner = try buildPayloadSectionRewrite(env, inner_def orelse return null, path[1..], c, synth_loc) orelse return null;
    const args = try env.arena.alloc(ast.CallArg, 1);
    args[0] = .{ .label = "_inner", .value = inner, .comments = &.{} };
    node.* = .{ .call = .{ .loc = loc, .kind = .{ .call = .{
        .receiver = recv,
        .callee = path[0],
        .is_builtin = false,
        .args = args,
        .trailing = &.{},
    } } } };
    return node;
}

/// True when every byte of `s` is an ASCII digit (`0`–`9`). Used to detect
/// numeric leaf segments (`500`, `4`) that the F1 desugar mangled to
/// `_500` / `_4`.
fn looksNumeric(s: []const u8) bool {
    if (s.len == 0) return false;
    for (s) |c| if (c < '0' or c > '9') return false;
    return true;
}

// ── pass 2: declaration inference ────────────────────────────────────────────

/// Build a signature name for a record declaration binding — the 1.0.3
/// surface, which is what hover, completion and signature help print for the
/// constructor: `"type Name<G>(f1: T1, f2: T2)"`, fields inline, body omitted.
/// It is the name of the binding's *type*, not of the record — the instances
/// are `named` by `r.name` alone — so the spelling is free to follow the
/// document; `record { … }` was the pre-1.0.3 surface, which no longer parses.
fn buildRecordDeclName(env: *Env, r: ast.TypeDecl) ![]const u8 {
    var buf: std.ArrayList(u8) = .empty;
    try buf.appendSlice(env.arena, "type ");
    try buf.appendSlice(env.arena, r.name);
    try appendGenericParamsStr(&buf, env.arena, r.genericParams);
    try buf.append(env.arena, '(');
    for (r.recordFields(), 0..) |f, i| {
        if (i > 0) try buf.appendSlice(env.arena, ", ");
        try buf.appendSlice(env.arena, f.name);
        try buf.appendSlice(env.arena, ": ");
        try appendTypeRefStr(&buf, env.arena, f.typeRef);
    }
    try buf.append(env.arena, ')');
    return try buf.toOwnedSlice(env.arena);
}

/// `<A, B>` after a declaration's name, or nothing when it has no generics —
/// the 1.0.3 spelling shared by the three declaration-name builders.
fn appendGenericParamsStr(buf: *std.ArrayList(u8), arena: std.mem.Allocator, params: anytype) !void {
    if (params.len == 0) return;
    try buf.append(arena, '<');
    for (params, 0..) |gp, i| {
        if (i > 0) try buf.appendSlice(arena, ", ");
        try buf.appendSlice(arena, gp.name);
    }
    try buf.append(arena, '>');
}

/// Build a signature name for a behavior declaration binding — the 1.0.3
/// surface: `"behavior Name<G> {\n    val x: T;\n    fn method<G>(params) -> R;\n}"`.
fn buildInterfaceDeclName(env: *Env, d: ast.BehaviorDecl) ![]const u8 {
    var buf: std.ArrayList(u8) = .empty;
    try buf.appendSlice(env.arena, "behavior ");
    try buf.appendSlice(env.arena, d.name);
    try appendGenericParamsStr(&buf, env.arena, d.genericParams);
    try buf.appendSlice(env.arena, " {\n");
    for (d.fields) |f| {
        try buf.appendSlice(env.arena, "    val ");
        try buf.appendSlice(env.arena, f.name);
        try buf.appendSlice(env.arena, ": ");
        try appendTypeRefStr(&buf, env.arena, f.typeRef);
        try buf.appendSlice(env.arena, ";\n");
    }
    for (d.methods) |m| {
        try buf.appendSlice(env.arena, "    fn ");
        try buf.appendSlice(env.arena, m.name);
        try appendGenericParamsStr(&buf, env.arena, m.genericParams);
        try buf.append(env.arena, '(');
        for (m.params, 0..) |p, i| {
            if (i > 0) try buf.appendSlice(env.arena, ", ");
            try buf.appendSlice(env.arena, p.name);
            if (p.modifier == .@"comptime") {
                try buf.appendSlice(env.arena, " comptime");
            }
            try buf.appendSlice(env.arena, ": ");
            try appendTypeRefStr(&buf, env.arena, p.typeRef);
        }
        try buf.append(env.arena, ')');
        if (m.returnType) |rt| {
            try buf.appendSlice(env.arena, " -> ");
            try appendTypeRefStr(&buf, env.arena, rt);
        }
        if (!m.is_default) try buf.appendSlice(env.arena, ";");
        try buf.append(env.arena, '\n');
    }
    try buf.append(env.arena, '}');
    return try buf.toOwnedSlice(env.arena);
}

/// Build a signature name for an enum declaration binding — the 1.0.3
/// surface, compact as the formatter prints it:
/// `"type Name<G> { Variant, Variant(field: Type) }"`.
fn buildEnumDeclName(env: *Env, e: ast.TypeDecl) ![]const u8 {
    var buf: std.ArrayList(u8) = .empty;
    try buf.appendSlice(env.arena, "type ");
    try buf.appendSlice(env.arena, e.name);
    try appendGenericParamsStr(&buf, env.arena, e.genericParams);
    try buf.appendSlice(env.arena, " { ");
    for (e.variants(), 0..) |v, vi| {
        if (vi > 0) try buf.appendSlice(env.arena, ", ");
        try buf.appendSlice(env.arena, v.name);
        if (v.fields.len > 0) {
            try buf.append(env.arena, '(');
            for (v.fields, 0..) |f, i| {
                if (i > 0) try buf.appendSlice(env.arena, ", ");
                try buf.appendSlice(env.arena, f.name);
                try buf.appendSlice(env.arena, ": ");
                try appendTypeRefStr(&buf, env.arena, f.typeRef);
            }
            try buf.append(env.arena, ')');
        }
    }
    try buf.appendSlice(env.arena, " }");
    return try buf.toOwnedSlice(env.arena);
}

/// Build a signature name for a fn declaration binding.
/// Format: `fn(name [comptime]: Type, ...) -> ReturnType`
/// The function name and generic params are omitted; modifiers are included.
fn buildFnSigName(env: *Env, f: ast.FnDecl) ![]const u8 {
    var buf: std.ArrayList(u8) = .empty;
    try buf.appendSlice(env.arena, "fn(");
    for (f.params, 0..) |p, i| {
        if (i > 0) try buf.appendSlice(env.arena, ", ");
        try buf.appendSlice(env.arena, p.name);
        if (p.modifier == .@"comptime") {
            try buf.appendSlice(env.arena, " comptime");
        }
        try buf.appendSlice(env.arena, ": ");
        try appendTypeRefStr(&buf, env.arena, p.typeRef);
    }
    try buf.append(env.arena, ')');
    if (f.returnType) |rt| {
        try buf.appendSlice(env.arena, " -> ");
        try appendTypeRefStr(&buf, env.arena, rt);
    }
    return try buf.toOwnedSlice(env.arena);
}

/// Append the string form of a TypeRef to `buf`.
fn appendTypeRefStr(buf: *std.ArrayListUnmanaged(u8), allocator: std.mem.Allocator, ref: ast.TypeRef) std.mem.Allocator.Error!void {
    switch (ref) {
        .named => |n| try buf.appendSlice(allocator, n),
        .array => |elem| {
            try appendTypeRefStr(buf, allocator, elem.*);
            try buf.appendSlice(allocator, "[]");
        },
        .tuple_ => |elems| {
            try buf.appendSlice(allocator, "#(");
            for (elems, 0..) |e, i| {
                if (i > 0) try buf.appendSlice(allocator, ", ");
                try appendTypeRefStr(buf, allocator, e);
            }
            try buf.append(allocator, ')');
        },
        .labeledTuple => |lt| {
            try buf.appendSlice(allocator, "#(");
            for (lt.elems, 0..) |e, i| {
                if (i > 0) try buf.appendSlice(allocator, ", ");
                try buf.appendSlice(allocator, lt.labels[i]);
                try buf.appendSlice(allocator, ": ");
                try appendTypeRefStr(buf, allocator, e);
            }
            try buf.append(allocator, ')');
        },
        .optional => |inner| {
            try buf.append(allocator, '?');
            try appendTypeRefStr(buf, allocator, inner.*);
        },
        .function => |f| {
            try buf.appendSlice(allocator, "fn(");
            if (f.anyParams) try buf.appendSlice(allocator, "..");
            for (f.params, 0..) |p, i| {
                if (i > 0) try buf.appendSlice(allocator, ", ");
                try appendTypeRefStr(buf, allocator, p);
            }
            try buf.appendSlice(allocator, ") -> ");
            try appendTypeRefStr(buf, allocator, f.returnType.*);
        },
        .generic => |b| {
            if (b.is_builtin) try buf.append(allocator, '@');
            try buf.appendSlice(allocator, b.name);
            try buf.append(allocator, '<');
            for (b.args, 0..) |a, i| {
                if (i > 0) try buf.appendSlice(allocator, ", ");
                try appendTypeRefStr(buf, allocator, a);
            }
            try buf.append(allocator, '>');
        },
        .typeparam => |constraints| {
            try buf.appendSlice(allocator, "typeparam");
            for (constraints, 0..) |c, i| {
                try buf.appendSlice(allocator, if (i == 0) " " else " | ");
                try appendTypeRefStr(buf, allocator, c);
            }
        },
    }
}

fn inferDecl(env: *Env, decl: ast.DeclKind) InferError!?Binding {
    switch (decl) {
        .val => |v| {
            // The annotation is resolved BEFORE the value so it can be this
            // position's expected type (00 · 01-checker) — see
            // `inferDeclTyped`'s `.val` case.
            const annType: ?*T.Type = if (v.typeAnnotation) |ann|
                resolveAnnotationAt(env, ann, v.value.getLoc(), v.typeLoc) catch |err| return locateTypeRefError(env, err, v.value.getLoc())
            else
                null;
            const prevDeclSite = env.contextDeclSite;
            env.contextDeclSite = if (v.mutable) null else v.value.getLoc();
            defer env.contextDeclSite = prevDeclSite;
            const ty = try inferExprExpecting(env, v.value.*, annType);
            try noteContextDeclaration(env, v, annType orelse ty);
            // Bind the DECLARED (annotated) type when present.
            var bindTy = ty;
            if (annType) |at| {
                try unifyArgument(env, at, ty, v.value.getLoc());
                bindTy = at;
            }
            if (v.isPub and annType == null) try refusePublicUnknown(env, bindTy, v.name, "val", v.value.getLoc());
            if (annType == null and isEmptyArrayLiteral(v.value.*))
                try env.birthWarnings.append(env.arena, .{ .name = v.name, .mutable = v.mutable, .type_ = bindTy, .loc = v.value.getLoc() });
            try validateMemoryAnnotations(env, v, bindTy);
            try noteTypeValue(env, v.name, v.value.*, annType == null and !v.mutable);
            if (v.mutable) try env.bind(v.name, bindTy) else try env.bindVal(v.name, bindTy);
            return .{ .name = v.name, .type_ = bindTy };
        },
        .@"fn" => |f| {
            const ty = try inferFnDecl(env, f);
            try env.bind(f.name, ty);
            const sigName = try buildFnSigName(env, f);
            return .{ .name = f.name, .type_ = try env.namedType(sigName) };
        },
        // Type declarations produce a binding whose type name encodes the body.
        .type_ => |tdecl| switch (tdecl.shape) {
            .record => {
                const typeName = try buildRecordDeclName(env, tdecl);
                return .{ .name = tdecl.name, .type_ = try env.namedType(typeName) };
            },
            .enum_ => {
                const typeName = try buildEnumDeclName(env, tdecl);
                return .{ .name = tdecl.name, .type_ = try env.namedType(typeName) };
            },
        },
        .behavior => |d| {
            const typeName = try buildInterfaceDeclName(env, d);
            try registerInterfaceAssociatedFns(env, d);
            return .{ .name = d.name, .type_ = try env.namedType(typeName) };
        },
        // A test block produces no binding, but its body must type-check.
        .@"test" => |t| {
            try inferTestDecl(env, t);
            return null;
        },
        // `from "std"` imports mark module namespaces (no value binding) —
        // the untyped path (tests, LSP) needs this too, not just
        // `inferProgramTyped`'s `.use` interception.
        .use => |u| {
            _ = try markStdImports(env, u);
            return null;
        },
        .typeAlias => |a| {
            _ = try checkTypeAliasDecl(env, a);
            return null;
        },
        // implement doesn't produce a value binding.
        else => return null,
    }
}

/// Type-check a `test { … }` body. Body is treated like a `#[@future]` fn
/// returning void: `await <future>` is accepted (the test runner awaits
/// the test fn's return value on every backend that supports futures —
/// commonJS via `async function`, erlang via the eager `@Future<T>` = `T`
/// rule that makes `await` an identity). `yield` stays rejected; `throw`
/// is lenient (a panic surfaces as the test's red diagnostic).
fn inferTestDecl(env: *Env, t: ast.TestDecl) InferError!void {
    // 01 step 13 — a test's locals end with the test.
    var bodyLog: std.ArrayListUnmanaged(Env.BindUndo) = .empty;
    const outerScope = env.openBodyScope(&bodyLog);
    defer env.closeBodyScope(&bodyLog, outerScope, t.name orelse "test");
    const savedThrowCtx = env.throwContext;
    env.throwContext = .unchecked;
    // Decision 595 — a region's `try`s stop at a function's border.
    const prevTryRegion = env.tryRegion;
    env.tryRegion = null;
    defer env.tryRegion = prevTryRegion;
    defer env.throwContext = savedThrowCtx;

    // `@src().fnName` inside a test body is the test name, verbatim (decision
    // 73); an anonymous `test { … }` gets the `test_<idx>` fallback the
    // commonJS registry gives it (`codegen/commonJS.zig`, `test_entries`).
    const savedFnName = env.currentFnName;
    env.currentFnName = t.name orelse try std.fmt.allocPrint(env.arena, "test_{d}", .{env.testIndex});
    env.testIndex += 1;
    defer env.currentFnName = savedFnName;

    const prevStarFn = env.starFn;
    const prevLabelsLen = env.labelStack.items.len;
    defer {
        env.starFn = prevStarFn;
        env.labelStack.shrinkRetainingCapacity(prevLabelsLen);
    }
    // §A3 follow-up — tests run inside an implicit task context so
    // callers can `await flush()` / `await fetch(url)` directly in
    // assertions. The lowering side (`commonJS.emitTestFn`) emits an
    // `async function` to match.
    env.starFn = .{
        .allowsAwait = true,
        .allowsYield = false,
        .iterItem = null,
        .fnLabel = null,
        .effect = .task,
    };
    env.labelStack.shrinkRetainingCapacity(0);

    try refuseRedeclaredBindings(env, t.body, &.{});
    _ = try inferBodyStmts(env, t.body);
}

// ── decision 575 (6): a declaration's implementations ──────────────────────
//
// A `declare fn` names its host sources with `#[external(…)]` (std's
// `external`, `libs/std/src/external.bp`) or a library's own source
// annotation; each source is a value of std's enum `Implementation`. Its
// shape — a label the variant does not declare, a value of another type — is
// the enum constructor's refusal (`checkDecoratorArgs` over `external`'s
// `comptime ..sources: Implementation[]`). The checks below are the ones no
// constructor states: a cell's form (decisions 305, 481), the tables a cell
// names (`op:`, `std:`, `wasi:`, `body:`, decisions 238, 440, 445), `result:`
// (431, 488, 490, 491), one implementation per target (`implementation-twice`,
// and on wasm one per host, 334), none on a declaration with a body
// (`implement-with-body`), and a bodyless declaration with none
// (`declare-without-implementation`).

/// Where a declaration with implementations stands.
const ImplSite = enum { top_level, type_method, behavior_member };

/// The declaration a list of implementations belongs to.
const ImplDecl = struct {
    name: []const u8,
    params: []const ast.Param,
    ret: ?ast.TypeRef,
    /// It has a body of its own.
    hasBody: bool,
    site: ImplSite,
    /// A behavior's `default fn`: its body is the fallback of a target the
    /// behavior gives no implementation for.
    isDefault: bool = false,
    /// A module-level `declare fn`: a `body:` cell and a wasm cell's signature
    /// are checked against it.
    fnDecl: ?ast.FnDecl = null,
    /// The type `Self` spells in a primitive behavior (`selfSpelling`).
    selfTy: ?[]const u8 = null,
    /// Where the declaration's name is written.
    loc: ?ast.Loc = null,
};

fn implError(env: *Env, loc: ?ast.Loc, msg: []const u8, hint: []const u8) InferError {
    var e = TypeError.custom(msg, hint);
    if (loc) |l| e = e.withLoc(l);
    env.lastError = e;
    return error.TypeError;
}

/// Every check of `d`'s implementations, in order: the sources' shapes (the
/// constructor's, then each cell's form), the declaration's body, one per
/// target, each implementation's tables.
fn checkImplementations(env: *Env, program: ast.Program, d: ImplDecl, annotations: []const ast.Annotation, impls: []const ast.Implementation) InferError!void {
    for (annotations) |a| {
        if (!implementationsParse.isSourceAnnotation(a)) continue;
        // Decision 621 — only the template is positional: a second
        // unlabelled argument is refused before the constructor reads it
        // into the next field.
        for (a.args, 0..) |arg, i| {
            const at = a.argLoc(i) orelse a.loc orelse ast.Loc{ .line = 0, .col = 0 };
            const src = (try implementationsParse.parseSource(env.arena, arg, at)) orelse continue;
            try refuseUnlabelledField(env, src);
        }
        if (env.decorators.get(a.name)) |sig| try checkDecoratorArgs(env, program, a, sig, .{ .name = d.name, .type_ = null });
        for (a.args, 0..) |arg, i| {
            const at = a.argLoc(i) orelse a.loc orelse ast.Loc{ .line = 0, .col = 0 };
            const src = (try implementationsParse.parseSource(env.arena, arg, at)) orelse continue;
            try checkSourceCells(env, program, src, d);
        }
    }
    if (impls.len == 0) return;
    if (d.hasBody and !d.isDefault) {
        return implError(env, impls[0].loc, try std.fmt.allocPrint(
            env.arena,
            "{s}: `{s}` has a body, and an implementation takes the place of one — `.{s}(…)` implements a bodyless `declare fn`",
            .{ diagnostics.implement_with_body, d.name, impls[0].target.variant() },
        ), "Delete the body and write `declare fn`, or delete the annotation: a function with a body is its own implementation on every target.");
    }
    try refuseAllBodies(env, d, impls);
    try refuseImplementationTwice(env, d, impls);
    for (impls) |impl| try checkImplementation(env, program, d, impl);
}

/// Decision 621 — in a cell of `Implementation` only the `template` is
/// positional: a second unlabelled argument is refused at the argument,
/// naming the label its value fits (`body:` for a name, `inline:` /
/// `result:` for a `bool`, …), else the labels the variant has.
fn refuseUnlabelledField(env: *Env, src: implementationsParse.Source) InferError!void {
    const target = src.target orelse return;
    for (src.args) |arg| {
        if (arg.labelled) continue;
        if (arg.field) |f| if (std.mem.eql(u8, f, "template")) continue;
        const value = try tokensText(env, arg.tokens);
        const fix: []const u8 = blk: {
            // A `bool` literal lexes as a name too: test it before `body:`.
            if (implementationsParse.boolOf(arg.tokens) != null) break :blk if (target == .erlang)
                try std.fmt.allocPrint(env.arena, "write `inline: {s}` or `result: {s}`", .{ value, value })
            else
                try std.fmt.allocPrint(env.arena, "write `result: {s}`", .{value});
            if (implementationsParse.identOf(arg.tokens)) |name| break :blk try std.fmt.allocPrint(env.arena, "write `body: {s}`", .{name});
            if (target == .wasm) {
                if (implementationsParse.stringOf(arg.tokens) != null) break :blk try std.fmt.allocPrint(env.arena, "write `op: {s}` or `std: {s}`", .{ value, value });
                if (implementationsParse.enumValueOf(arg.tokens)) |name| {
                    const host = std.mem.eql(u8, name, "Wasi") or std.mem.eql(u8, name, "Browser");
                    break :blk try std.fmt.allocPrint(env.arena, "write `{s}: {s}`", .{ if (host) "host" else "wasi", value });
                }
                if (arg.tokens.len > 0 and arg.tokens[0].kind == .leftSquareBracket) break :blk try std.fmt.allocPrint(env.arena, "write `needs: {s}`", .{value});
            }
            var labels: std.ArrayListUnmanaged(u8) = .empty;
            for (implementationsParse.fieldsOf(target)) |f| {
                if (std.mem.eql(u8, f, "template")) continue;
                if (labels.items.len > 0) try labels.appendSlice(env.arena, ", ");
                try labels.print(env.arena, "`{s}:`", .{f});
            }
            break :blk try std.fmt.allocPrint(env.arena, "write it by one of `.{s}`'s labels: {s}", .{ target.variant(), labels.items });
        };
        return implError(env, arg.loc, try std.fmt.allocPrint(
            env.arena,
            "{s}: a cell's field is written by its label — {s}",
            .{ diagnostics.external_field_unlabelled, fix },
        ), "Only the template is written by position (`.Erlang(\"lists:reverse($0)\")`); every other field by its label, in any order: `body:`, `inline:`, `result:`, and on `.Wasm` `op:`, `std:`, `wasi:`, `host:`, `needs:` (decision 621).");
    }
}

/// Decision 610 (3) — a declaration whose every implementation is a `body:`
/// cell runs the botopink body on every target it names: it is a bodied
/// `fn`, one form, and the annotation is refused. The cell exists for the
/// per-target split (`.Erlang("lists:reverse($0)")` beside
/// `.Wasm(body: reverseBody)`).
fn refuseAllBodies(env: *Env, d: ImplDecl, impls: []const ast.Implementation) InferError!void {
    for (impls) |impl| {
        const cell = impl.cell orelse return;
        if (cell.kind != .body) return;
    }
    const body = impls[0].cell.?.value;
    return implError(env, impls[0].loc, try std.fmt.allocPrint(
        env.arena,
        "{s}: every source of `{s}` is a `body:` cell — write the function with that body",
        .{ diagnostics.external_all_bodies, d.name },
    ), try std.fmt.allocPrint(
        env.arena,
        "A function every target runs in botopink is a bodied `fn`: give `{s}` the body of `{s}` and delete the annotation. `body:` is for the per-target split — a template on one target beside `.Wasm(body: {s})` (decision 610).",
        .{ d.name, body, body },
    ));
}

/// Decisions 305 and 481 — each source's cell, as written: one at most
/// (a template, `body:`, and on `.Wasm` also `op:`, `std:` and `wasi:`), at
/// least one, `body:` an identifier, and a template that is no prefixed
/// cell (`"fn:tanBody"`).
fn checkSourceCells(env: *Env, program: ast.Program, src: implementationsParse.Source, d: ImplDecl) InferError!void {
    const target = src.target orelse return;
    const wasm = target == .wasm;
    const variant = target.variant();
    var cells: usize = 0;
    for (src.args) |arg| {
        const field = arg.field orelse continue;
        const isCell = std.mem.eql(u8, field, "template") or std.mem.eql(u8, field, "body") or
            (wasm and (std.mem.eql(u8, field, "op") or std.mem.eql(u8, field, "std") or std.mem.eql(u8, field, "wasi")));
        if (!isCell) continue;
        cells += 1;
        if (cells > 1) return implError(env, arg.loc, try std.fmt.allocPrint(
            env.arena,
            "`.{s}` on `{s}` writes a second cell, `{s}:` — a {s}binding is one cell (decision 481)",
            .{ variant, d.name, field, if (wasm) "wasm " else "" },
        ), cell_hint);
        if (std.mem.eql(u8, field, "body")) {
            // Decision 610 (1) — a bare identifier naming a private bodied
            // `fn` of this module with the declaration's types; anything
            // else is refused at the argument.
            const name = implementationsParse.identOf(arg.tokens) orelse return implError(env, arg.loc, try std.fmt.allocPrint(
                env.arena,
                "{s}: `.{s}(body: {s})` on `{s}`: `body:` names a private fn of this module by its identifier, not {s} (decisions 305, 481) — write `body: <name>`",
                .{ diagnostics.external_body_not_a_fn, variant, try tokensText(env, arg.tokens), d.name, if (implementationsParse.stringOf(arg.tokens) != null) "a string" else "a value" },
            ), cell_hint);
            if (d.fnDecl) |fd| if (moduleBinds(env, program, name)) switch (try hostFnBinding.resolve(env.arena, fd, name, program, "", variant)) {
                .ok => {},
                .refused => |msg| return implError(env, arg.loc, try std.fmt.allocPrint(env.arena, "{s}: {s}", .{ diagnostics.external_body_not_a_fn, msg }), cell_hint),
            };
        }
        if (std.mem.eql(u8, field, "template")) if (implementationsParse.stringOf(arg.tokens)) |raw| {
            const inner = unquotedString(raw) orelse continue;
            for (ast.Implementation.CellKind.prefixes) |pre| {
                if (!(inner.len > pre.text.len and std.mem.startsWith(u8, inner, pre.text) and inner[pre.text.len] == ':')) continue;
                const labelled = try ast.wasmCellDisplay(env.arena, inner);
                // `op:` / `wasi:` / `std:` are `.Wasm`'s cells alone.
                const into = if (wasm or pre.kind == .body) variant else "Wasm";
                if (wasm) return implError(env, arg.loc, try std.fmt.allocPrint(
                    env.arena,
                    "`.Wasm({s})` on `{s}`: a wasm cell is a labelled argument, not a prefixed string (decision 481) — write `.Wasm({s})`",
                    .{ raw, d.name, labelled },
                ), cell_hint);
                return implError(env, arg.loc, try std.fmt.allocPrint(
                    env.arena,
                    "`.{s}({s})` on `{s}`: a binding cell is a labelled argument, not a prefixed string (decision 305) — write `.{s}({s})`",
                    .{ variant, raw, d.name, into, labelled },
                ), cell_hint);
            }
        };
    }
    // Decision 610 (2) — a source naming neither a template nor a cell.
    if (cells == 0) return implError(env, src.variantLoc, try std.fmt.allocPrint(
        env.arena,
        "{s}: `.{s}` on `{s}` names no code — {s}",
        .{ diagnostics.external_source_empty, variant, d.name, if (wasm) "a wasm binding is one cell: `op:`, `std:`, `wasi:`, `body:` or a template" else "write its template, or `body:` naming a private fn of this module" },
    ), cell_hint);
}

const cell_hint = "A binding is one labelled cell: `body: <private fn of this module>` or a template on every target; on wasm also `op: \"<opcode>\"`, `wasi: .<Adapter>` or `std: \"<module>.<function>\"` (std's alone).";

fn tokensText(env: *Env, toks: []const Token) InferError![]const u8 {
    if (toks.len == 0) return "";
    const first = toks[0].lexeme;
    const last = toks[toks.len - 1].lexeme;
    const begin = @intFromPtr(first.ptr);
    const end = @intFromPtr(last.ptr) + last.len;
    if (end < begin) return env.arena.dupe(u8, first);
    return first.ptr[0 .. end - begin];
}

/// Decision 575 (6) — one implementation per target; on wasm one per host
/// (decision 334): at most one `host: .Wasi`, at most one `host: .Browser`, and
/// one written without `host:` (which serves every host) stands alone.
fn refuseImplementationTwice(env: *Env, d: ImplDecl, impls: []const ast.Implementation) InferError!void {
    var seen_any = false;
    var seen_all = false;
    var seen = [_]bool{ false, false };
    for (impls, 0..) |impl, i| {
        if (impl.target == .wasm) {
            const twice = seen_all or (impl.host == null and seen_any) or (if (impl.host) |h| seen[@intFromEnum(h)] else false);
            if (twice) {
                const which = if (impl.host) |h| try std.fmt.allocPrint(env.arena, "host '{s}'", .{@tagName(h)}) else "every host";
                return implError(env, impl.loc, try std.fmt.allocPrint(
                    env.arena,
                    "`{s}` binds wasm twice for {s} — one `.Wasm(…)` per host",
                    .{ d.name, which },
                ), "Keep one binding per host: `host: .Wasi` and `host: .Browser` side by side, or one binding without `host:`, which serves every host.");
            }
            seen_any = true;
            if (impl.host) |h| seen[@intFromEnum(h)] = true else seen_all = true;
            continue;
        }
        for (impls[0..i]) |prev| if (prev.target == impl.target) {
            return implError(env, impl.loc, try std.fmt.allocPrint(
                env.arena,
                "{s}: `{s}` is implemented twice for `.{s}` — one implementation per target",
                .{ diagnostics.implementation_twice, d.name, impl.target.variant() },
            ), "Keep one `.<Target>(…)` per target across the declaration's annotations.");
        };
    }
}

/// The tables one implementation names, at the annotation that gave it.
fn checkImplementation(env: *Env, program: ast.Program, d: ImplDecl, impl: ast.Implementation) InferError!void {
    try refuseResultReturn(env, impl, d.name, d.ret, program);
    const cell = impl.cell orelse return;
    const variant = impl.target.variant();
    switch (cell.kind) {
        .body => {
            // Decision 305 — a botopink name: one the module does not bind
            // is the ordinary unbound-name error.
            if (!moduleBinds(env, program, cell.value)) {
                env.lastError = TypeError.unboundVariable(cell.value).withLoc(impl.loc orelse return error.TypeError);
                return error.TypeError;
            }
            if (d.fnDecl) |fd| switch (try hostFnBinding.resolve(env.arena, fd, cell.value, program, "", variant)) {
                .ok => {},
                .refused => |msg| return implError(env, impl.loc, try std.fmt.allocPrint(env.arena, "{s}: {s}", .{ diagnostics.external_body_not_a_fn, msg }), cell_hint),
            };
        },
        .op => if (wasmHostBinding.findOp(cell.value) == null) return implError(env, impl.loc, try std.fmt.allocPrint(
            env.arena,
            "`.Wasm(op: \"{s}\")` on `{s}`: `{s}` is not a wasm numeric instruction a binding names (an `op:` names one opcode, e.g. `op: \"f64.floor\"`)",
            .{ cell.value, d.name, cell.value },
        ), cell_hint),
        .wasi => if (wasmHostBinding.findAdapter(cell.value) == null) {
            const parsed = try wasmHostBinding.parse(env.arena, impl.text, .{ .params = &.{}, .result = null });
            return implError(env, impl.loc, try std.fmt.allocPrint(env.arena, "{s} (on `{s}`)", .{ parsed.refused.message, d.name }), cell_hint);
        },
        .std_ => try refuseStdBinding(env, impl, d.name, d.params, d.ret, d.selfTy),
    }
    if (d.fnDecl) |fd| if (fd.isDeclare) try refuseWasmSignature(env, impl, fd);
}

/// Decisions 238 and 393 — an `op:` cell's opcode types and a `wasi:`
/// adapter's signature are checked against the declaration at the annotation
/// on every target, read by the wasm backend's own reader
/// (`wat/host_binding.zig` `parse` over `signatureOf`): a binding no wasm
/// build reaches is refused as a wasm build refuses it, with its message.
fn refuseWasmSignature(env: *Env, impl: ast.Implementation, f: ast.FnDecl) InferError!void {
    const cell = impl.cell orelse return;
    if (cell.kind != .op and cell.kind != .wasi) return;
    switch (try wasmHostBinding.parse(env.arena, impl.text, try wasmHostBinding.signatureOf(env.arena, f))) {
        .ok => {},
        .refused => |r| return implError(env, impl.loc, try std.fmt.allocPrint(env.arena, "{s} (on `{s}`)", .{ r.message, f.name }), cell_hint),
    }
}

/// Decisions 431 (2), 488, 490 — `result: true` says the host call can fail
/// and the backend answers every failure as `Error(HostError(…))`, so the
/// declared return must be `@Result<…, HostError>` or
/// `@Async<@Result<…, HostError>>`, `HostError` being std's
/// `failure.HostError` by module identity (488): a type of another module
/// that happens to be named `HostError` is not it. Any other return is
/// refused at the annotation, so the flag has one reading.
fn refuseResultReturn(env: *Env, impl: ast.Implementation, name: []const u8, ret: ?ast.TypeRef, program: ast.Program) InferError!void {
    if (!impl.result) return;
    const variant = impl.target.variant();
    // Decision 491 — an `op:` cell is a wasm instruction and a `body:` cell a
    // botopink fn of the module (on every target, decision 305): neither is
    // a host call that raises, so `result:` there is refused.
    if (impl.cell) |c| if (c.kind == .op or c.kind == .body) {
        return implError(env, impl.loc, try std.fmt.allocPrint(
            env.arena,
            "`{s}`'s `.{s}({s}: …)` takes no `result:` — {s} `{s}:` cell is not a host call that can fail (decision 491)",
            .{ name, variant, c.kind.label(), if (c.kind == .op) "an" else "a", c.kind.label() },
        ), "Delete `result:`; a host call that can fail is a template binding, or a `wasi:` or `std:` cell on `.Wasm`.");
    };
    const shape: HostResultShape = if (ret) |r| hostResultShape(env, r, program) else .other;
    if (shape == .host_error) return;
    if (shape == .foreign_error) {
        return implError(env, impl.loc, try std.fmt.allocPrint(
            env.arena,
            "`{s}` writes `result: true` on `.{s}`, and its `HostError` is not std's `failure.HostError` — only std's counts, by module identity (decision 488)",
            .{ name, variant },
        ), "Import std's: `import {failure.HostError} from \"std\";`, and name the module's own type otherwise.");
    }
    const written = if (ret) |r| try std.fmt.allocPrint(env.arena, "{f}", .{r}) else "void";
    return implError(env, impl.loc, try std.fmt.allocPrint(
        env.arena,
        "`{s}` writes `result: true` on `.{s}`, so it must return `Result<…, HostError>` or `Async<Result<…, HostError>>`, not `{s}`",
        .{ name, variant, written },
    ), "`result: true` turns every way the host fails into `Error(HostError(…))`, std's `failure.HostError` (`import {failure.HostError} from \"std\";`). Without the flag the binding promises no failure: delete it, or declare the `Result`.");
}

/// How a `result: true` binding's return reads: `@Result<T, E>` or
/// `@Async<@Result<T, E>>` with `E` std's `failure.HostError` (`isStdHostError`)
/// — `.host_error`; that shape with `E` a type of another module spelled
/// `HostError` — `.foreign_error`; anything else — `.other`.
const HostResultShape = enum { host_error, foreign_error, other };

fn hostResultShape(env: *Env, r: ast.TypeRef, program: ast.Program) HostResultShape {
    const g = switch (r) {
        .generic => |g| g,
        else => return .other,
    };
    if (!g.is_builtin) return .other;
    const res = if (std.mem.eql(u8, g.name, "Async")) blk: {
        if (g.args.len != 1) return .other;
        break :blk switch (g.args[0]) {
            .generic => |ig| ig,
            else => return .other,
        };
    } else g;
    if (!res.is_builtin or !std.mem.eql(u8, res.name, "Result") or res.args.len != 2) return .other;
    if (isStdHostError(env, res.args[1], program)) return .host_error;
    const e = switch (res.args[1]) {
        .named => |n| n,
        else => return .other,
    };
    const leaf = if (std.mem.lastIndexOfScalar(u8, e, '.')) |i| e[i + 1 ..] else e;
    return if (std.mem.eql(u8, leaf, "HostError")) .foreign_error else .other;
}

/// Decision 488 — `t` names std's `failure.HostError`, by module identity:
/// an import item of `from "std"` whose path is `failure.HostError` binds the
/// name `t` spells (`failure.HostError` through the namespace is rewritten to
/// that item before the checker runs, `std_namespace.zig`), or, inside std's
/// `failure` module itself, its own `HostError`. A type the module declares,
/// or one imported from anywhere else, under the same name is not it.
fn isStdHostError(env: *Env, t: ast.TypeRef, program: ast.Program) bool {
    const n = switch (t) {
        .named => |n| n,
        else => return false,
    };
    if (env.inStd and std.mem.eql(u8, n, "HostError") and
        (std.mem.eql(u8, env.modulePath, "failure") or std.mem.eql(u8, env.modulePath, "std/failure")))
    {
        for (program.decls) |d| switch (d) {
            .type_ => |td| if (std.mem.eql(u8, td.name, "HostError")) return true,
            else => {},
        };
    }
    for (program.decls) |d| switch (d) {
        .type_ => |td| if (std.mem.eql(u8, td.name, n)) return false,
        else => {},
    };
    for (program.decls) |d| switch (d) {
        .use => |u| {
            // Inside std a module imports its sibling by path, without `from`
            // (`import {failure.HostError};`): that source is std itself.
            const from_std = if (u.source.packageName()) |pkg|
                std.mem.eql(u8, pkg, "std")
            else
                env.inStd and u.source == .root;
            if (!from_std) continue;
            for (u.imports) |imp| {
                if (!std.mem.eql(u8, imp.name(), n)) continue;
                const segs = imp.segments;
                if (segs.len == 2 and std.mem.eql(u8, segs[0], "failure") and std.mem.eql(u8, segs[1], "HostError")) return true;
            }
        },
        else => {},
    };
    return false;
}

/// True when `name` is bound at module level: a declaration of `program`
/// (a `fn`, a `val`) or a name the checker has registered (a fn signature, an
/// import, a builtin).
fn moduleBinds(env: *Env, program: ast.Program, name: []const u8) bool {
    if (env.lookup(name) != null) return true;
    for (program.decls) |d| switch (d) {
        .@"fn" => |g| if (std.mem.eql(u8, g.name, name)) return true,
        .val => |v| if (std.mem.eql(u8, v.name, name)) return true,
        else => {},
    };
    return false;
}

/// The text inside a plain string literal argument (`"f64.floor"`), or null.
fn unquotedString(arg: []const u8) ?[]const u8 {
    if (arg.len < 2 or arg[0] != '"' or arg[arg.len - 1] != '"') return null;
    if (std.mem.startsWith(u8, arg, "\"\"\"")) return null;
    return arg[1 .. arg.len - 1];
}

fn isIdentText(s: []const u8) bool {
    if (s.len == 0) return false;
    for (s, 0..) |c, i| {
        const ok = std.ascii.isAlphabetic(c) or c == '_' or (i > 0 and std.ascii.isDigit(c));
        if (!ok) return false;
    }
    return true;
}

/// The type `Self` spells in a primitive's member table a `std:` cell may
/// bind (decision 440 (3)): `string`'s is `string`, a `Float`'s `f64` — the
/// carrier a wasm program holds any float in. Null elsewhere: a `Self` there
/// is no type a std-wasm function takes.
fn selfSpelling(behavior: []const u8) ?[]const u8 {
    if (std.mem.eql(u8, behavior, "string")) return "string";
    if (std.mem.eql(u8, behavior, "Float")) return "f64";
    return null;
}

/// Decision 440 (3) — `.Wasm(std: "<module>.<function>")` names a function
/// std-wasm implements (`std_wasm.exports`), with the declaration's parameter
/// and return types exactly — and only in one of std's own modules (decision
/// 445, `Env.inStd`): anywhere else the cell is refused, naming the std
/// function to call instead. A name std-wasm lacks, or other types, is refused
/// at the annotation, on every target: the one cell serves the wasm codegen
/// and the comptime runtime alike.
fn refuseStdBinding(env: *Env, impl: ast.Implementation, name: []const u8, params: []const ast.Param, ret: ?ast.TypeRef, self_ty: ?[]const u8) InferError!void {
    if (impl.target != .wasm) return;
    const cell = impl.cell orelse return;
    if (cell.kind != .std_) return;
    const fname = cell.value;
    const shown = try ast.wasmCellDisplay(env.arena, impl.text);
    if (!env.inStd) {
        // Decision 445 — std-wasm's export names are internal to std: the
        // public contract is std's botopink API, named here.
        const instead = if (stdWasm.find(fname)) |ex|
            try std.fmt.allocPrint(env.arena, " — call std's `{s}` instead", .{ex.api})
        else
            "";
        return implError(env, impl.loc, try std.fmt.allocPrint(
            env.arena,
            "`.Wasm({s})` on `{s}`: a `std:` binding is std's alone (decision 445){s}",
            .{ shown, name, instead },
        ), "std-wasm's functions are std's implementation, reached through std's API; a module of another package binds a host function of its own (`body: <private fn>`, `op:`, `wasi:`).");
    }
    if (stdWasm.find(fname)) |ex| {
        const spelled = try env.arena.alloc([]const u8, params.len);
        for (params, spelled) |p, *out| out.* = spelledType(p.typeRef, self_ty);
        const r: ?[]const u8 = if (ret) |rt| spelledType(rt, self_ty) else null;
        if (stdWasm.matches(ex, spelled, r)) return;
        var buf: [128]u8 = undefined;
        var have: std.ArrayListUnmanaged(u8) = .empty;
        try have.append(env.arena, '(');
        for (spelled, 0..) |t, i| {
            if (i > 0) try have.appendSlice(env.arena, ", ");
            try have.appendSlice(env.arena, t);
        }
        try have.appendSlice(env.arena, ") -> ");
        try have.appendSlice(env.arena, r orelse "void");
        return implError(env, impl.loc, try std.fmt.allocPrint(
            env.arena,
            "`.Wasm({s})` on `{s}`: std-wasm's `{s}` is `{s}`, and `{s}` is declared `{s}` — a `std:` binding takes exactly its function's types (decision 440)",
            .{ shown, name, fname, stdWasm.signatureText(ex, &buf), name, have.items },
        ), "Declare the function with std-wasm's types, or bind it otherwise (`body: <private fn>`).");
    }
    // Front 164 s3 — a `.wat` leaf alone: its types are GC types, which the
    // wasm build checks against the declaration (`wat.zig`
    // `checkLeafSignature`).
    if (stdLeaves.find(fname) != null) return;
    return implError(env, impl.loc, try std.fmt.allocPrint(
        env.arena,
        "`.Wasm({s})` on `{s}`: std-wasm implements no `{s}` (decision 440)",
        .{ shown, name, fname },
    ), try std.fmt.allocPrint(env.arena, "A `std:` binding names one of std-wasm's functions: {s}.", .{stdWasm.names}));
}

/// Decision 575 (6) — a bodyless `declare fn` (top-level, a type's, static
/// included) is implemented by an annotation, or refused at the declaration;
/// a behavior's member is a signature or a `default fn`, never a `declare
/// fn`. A compiler-bodies module's bodyless declarations are the compiler's
/// builtins (`Env.compilerBodies`), which `#[builtin]` marks with decision
/// 575 (2).
fn refuseUnimplementedDeclares(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| switch (decl) {
        .behavior => |b| for (b.methods) |m| if (m.is_declare) {
            return implError(env, if (m.nameLoc.line > 0) m.nameLoc else null, try std.fmt.allocPrint(
                env.arena,
                "{s}: `{s}.{s}` is a `declare fn` inside a behavior — a behavior declares a member's signature, or a `default fn` with a body",
                .{ diagnostics.declare_in_behavior, b.name, m.name },
            ), "Delete `declare`: `fn name(self: Self) -> T;` is the member every implementor answers. A host function is a `declare fn` of a type, or a top-level one.");
        },
        else => {},
    };
    if (env.compilerBodies) return;
    for (program.decls) |decl| switch (decl) {
        // Decision 604 — no bodyless decorator either: a marker is a decorator
        // with an empty body (`pub fn page(syntax decl: unknown) {}`).
        .@"fn" => |f| if (f.isDeclare and f.body.len == 0 and f.implementations.len == 0) {
            return refuseUnimplemented(env, f.name, if (f.nameLoc.line > 0) f.nameLoc else null);
        },
        .type_ => |t| for (t.methods) |m| if (m.is_declare and m.body == null and m.implementations.len == 0) {
            return refuseUnimplemented(env, try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ t.name, m.name }), if (m.nameLoc.line > 0) m.nameLoc else null);
        },
        else => {},
    };
}

/// Decision 668 — a function's or a method's type parameter is bound by a
/// parameter: it occurs in a parameter's type, directly (`x: T`), inside one
/// (`Array<T>`, `fn(T) -> R`, `Self<T>`), or as the type token
/// `comptime t: type<T>`. The return type is never a binding site: a type
/// parameter written only there is refused at the declaration.
fn refuseUnboundTypeParams(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| switch (decl) {
        // A value-or-type function's type form (`value_or_type.zig`'s twin):
        // the type argument its call removed binds the parameter.
        .@"fn" => |f| if (!std.mem.endsWith(u8, f.name, valueOrType.twin_suffix)) {
            try refuseUnboundIn(env, f.name, f.genericParams, f.params, f.nameLoc);
        },
        .type_ => |t| for (t.methods) |m| {
            try refuseUnboundIn(env, try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ t.name, m.name }), m.genericParams, m.params, m.nameLoc);
        },
        .behavior => |b| for (b.methods) |m| {
            try refuseUnboundIn(env, try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ b.name, m.name }), m.genericParams, m.params, m.nameLoc);
        },
        else => {},
    };
}

fn refuseUnboundIn(env: *Env, name: []const u8, gps: []const ast.GenericParam, params: []const ast.Param, loc: ast.Loc) InferError!void {
    for (gps) |gp| {
        // A template's `anyvalue` answer: the built code's type binds it at
        // each call (426 (1)); no source spells it.
        if (std.mem.eql(u8, gp.name, ast.anyvalue_param_name)) continue;
        const bound = for (params) |p| {
            if (paramBindsTypeParam(p, gp.name)) break true;
        } else false;
        if (bound) continue;
        return implError(env, if (loc.line > 0) loc else null, try std.fmt.allocPrint(
            env.arena,
            "{s}: `{s}`'s type parameter `{s}` occurs in no parameter's type — nothing at a call binds it, and the return type never does",
            .{ diagnostics.type_parameter_unbound, name, gp.name },
        ), try std.fmt.allocPrint(
            env.arena,
            "Bind `{s}` by a parameter: `comptime t: type<{s}>` when the caller names the type, a parameter whose type carries it (`items: array<{s}>`, `self: Self<array<{s}>>`, `f: fn({s}) -> R`); or write `unknown` where no type is meant (decision 668).",
            .{ gp.name, gp.name, gp.name, gp.name, gp.name },
        ));
    }
}

/// Whether the parameter `p` binds the type parameter `name` (decision 668).
fn paramBindsTypeParam(p: ast.Param, name: []const u8) bool {
    if (p.typeArgOf) |t| if (std.mem.eql(u8, t, name)) return true;
    if (p.inlineFields) |fields| for (fields) |f| {
        if (typeRefHasTypeParam(f.typeRef, name)) return true;
    };
    return typeRefHasTypeParam(p.typeRef, name);
}

/// Whether the written type `t` is or holds the type parameter `name` — in
/// any position: an array's element, an optional's payload, a tuple's
/// element, a generic's argument, a function type's parameter or return, a
/// `type<…>` token's constraint.
fn typeRefHasTypeParam(t: ast.TypeRef, name: []const u8) bool {
    return switch (t) {
        .named => |n| std.mem.eql(u8, n, name),
        .array => |inner| typeRefHasTypeParam(inner.*, name),
        .optional => |inner| typeRefHasTypeParam(inner.*, name),
        .tuple_ => |elems| for (elems) |e| {
            if (typeRefHasTypeParam(e, name)) break true;
        } else false,
        .labeledTuple => |lt| for (lt.elems) |e| {
            if (typeRefHasTypeParam(e, name)) break true;
        } else false,
        .function => |f| typeRefHasTypeParam(f.returnType.*, name) or for (f.params) |e| {
            if (typeRefHasTypeParam(e, name)) break true;
        } else false,
        .generic => |g| std.mem.eql(u8, g.name, name) or for (g.args) |e| {
            if (typeRefHasTypeParam(e, name)) break true;
        } else false,
        .typeparam => |cs| for (cs) |e| {
            if (typeRefHasTypeParam(e, name)) break true;
        } else false,
    };
}

fn refuseUnimplemented(env: *Env, name: []const u8, loc: ?ast.Loc) InferError {
    return implError(env, loc, try std.fmt.allocPrint(
        env.arena,
        "{s}: `{s}` is a bodyless `declare fn`, and no annotation implements it",
        .{ diagnostics.declare_without_implementation, name },
    ), "Name its host code on each target: `#[@external(.Erlang(\"…\"), .JavaScript(\"…\"), .Wasm(…))]`, or give it a body (`fn`).");
}

/// Whether this pass's decorators contributed text the module is re-analysed
/// with (`@emit`, `addMember`, `addType`, `@TypeInfo.all`).
pub fn hasSplicedContributions(env: *Env) bool {
    return env.contributions.items.len > 0 or env.memberContributions.items.len > 0 or env.typeContributions.items.len > 0 or env.typeinfoAllPending;
}

/// Decision 575 (6) — each implementation a library's source annotation gave
/// (`compiler.implement`, `Env.implementContributions`) appended to its
/// declaration's, in the order the decorators ran.
pub fn applyImplementContributions(env: *Env, program: ast.Program) InferError!void {
    if (env.implementContributions.items.len == 0) return;
    for (env.implementContributions.items) |c| {
        for (program.decls) |*d| switch (d.*) {
            .@"fn" => |*f| if (c.owner == null and std.mem.eql(u8, f.name, c.target)) {
                f.implementations = try appendImpl(env, f.implementations, c.impl);
            },
            .type_ => |*t| if (c.owner) |o| if (std.mem.eql(u8, t.name, o)) for (t.methods) |*m| {
                if (std.mem.eql(u8, m.name, c.target)) m.implementations = try appendImpl(env, m.implementations, c.impl);
            },
            else => {},
        };
    }
    env.implementContributions.clearRetainingCapacity();
}

fn appendImpl(env: *Env, have: []ast.Implementation, impl: ast.Implementation) InferError![]ast.Implementation {
    const out = try env.arena.alloc(ast.Implementation, have.len + 1);
    @memcpy(out[0..have.len], have);
    out[have.len] = impl;
    return out;
}

/// The `Implementation` a decorator body built (its JSON, the prelude's
/// `'__bp_metaJson'/1`): a variant is a tuple `{Tag, Field…}` — its tag the
/// variant's name, its fields in declaration order — or null.
fn implementationOfJson(arena: std.mem.Allocator, v: std.json.Value) InferError!?ast.Implementation {
    const items = switch (v) {
        .object => |o| if (o.get("tuple")) |t| (if (t == .array) t.array.items else return null) else return null,
        else => return null,
    };
    if (items.len == 0 or items[0] != .string) return null;
    const tag = items[0].string;
    // An atom names the variant last: `…__v__erlang`, `'Erlang'`.
    const leaf = if (std.mem.lastIndexOf(u8, tag, "__v__")) |i| tag[i + "__v__".len ..] else tag;
    const target = ast.Implementation.Target.ofMember(if (std.ascii.eqlIgnoreCase(leaf, "beam")) "" else leaf) orelse return null;
    const fields = implementationsParse.fieldsOf(target);
    var impl: ast.Implementation = .{ .target = target };
    for (items[1..], 0..) |x, k| {
        if (k >= fields.len) break;
        const field = fields[k];
        const str: ?[]const u8 = if (x == .string) x.string else null;
        if (std.mem.eql(u8, field, "template")) {
            if (str) |t| impl.template = try arena.dupe(u8, t);
        } else if (std.mem.eql(u8, field, "inline")) {
            impl.inline_ = x == .bool and x.bool;
        } else if (std.mem.eql(u8, field, "result")) {
            impl.result = x == .bool and x.bool;
        } else if (std.mem.eql(u8, field, "op") or std.mem.eql(u8, field, "std")) {
            if (str) |t| impl.cell = .{ .kind = if (field[0] == 'o') .op else .std_, .value = try arena.dupe(u8, t) };
        }
    }
    impl.text = if (impl.cell) |c| try std.fmt.allocPrint(arena, "{s}:{s}", .{ c.kind.prefix(), c.value }) else try arena.dupe(u8, impl.template orelse "");
    if (impl.template == null and impl.cell == null) return null;
    return impl;
}

/// Every declaration's implementations (`checkImplementations`), then the
/// bodyless declarations none implements.
fn checkProgramImplementations(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| switch (decl) {
        .@"fn" => |f| try checkImplementations(env, program, .{
            .name = f.name,
            .params = f.params,
            .ret = f.returnType,
            .hasBody = !f.isDeclare or f.body.len > 0,
            .site = .top_level,
            .fnDecl = f,
            .loc = f.nameLoc,
        }, f.annotations, f.implementations),
        .type_ => |t| for (t.methods) |m| try checkImplementations(env, program, .{
            .name = m.name,
            .params = m.params,
            .ret = m.returnType,
            .hasBody = m.body != null,
            .site = .type_method,
            .loc = m.nameLoc,
        }, m.annotations, m.implementations),
        .behavior => |b| for (b.methods) |m| {
            try checkImplementations(env, program, .{
                .name = m.name,
                .params = m.params,
                .ret = m.returnType,
                .hasBody = m.body != null,
                .site = .behavior_member,
                .isDefault = m.is_default,
                .selfTy = selfSpelling(b.name),
                .loc = m.nameLoc,
            }, m.annotations, m.implementations);
            // After the sources' own checks: a source the constructor refuses
            // is named first, wherever it stands.
            try refuseExternalOnBehavior(env, b, m);
        },
        else => {},
    };
    try refuseUnimplementedDeclares(env, program);
}

/// Decision 617 (2), (3) — a behavior is a contract: its members are
/// signatures and `default fn` bodies, and host code lives on the type that
/// implements it (`#[compiler.external(…)] declare fn toString(self: Self) ->
/// string;` inside `pub type i32 implement Signed { … }`). An implementation
/// on a behavior's member is refused at the annotation, `external-on-behavior`.
/// What `prelude_cache.foldWidthMembers` read back onto a contract is the
/// types', and so is a primitive type's member table (decision 641:
/// `pub type string { … }`, `BehaviorDecl.primitiveType`) — the type's own
/// host code, written on the type.
fn refuseExternalOnBehavior(env: *Env, b: ast.BehaviorDecl, m: ast.BehaviorMethod) InferError!void {
    if (m.folded or m.implementations.len == 0 or b.primitiveType) return;
    const impl = m.implementations[0];
    return implError(env, impl.loc orelse m.nameLoc, try std.fmt.allocPrint(
        env.arena,
        "{s}: `{s}.{s}` is a behavior's member, and a behavior carries no host code — `.{s}(…)` belongs on the type that implements `{s}`",
        .{ diagnostics.external_on_behavior, b.name, m.name, impl.target.variant(), b.name },
    ), "Keep the signature (or a `default fn` body) on the behavior, and write `#[compiler.external(…)] declare fn …` on each type that implements it, `Self` the type.");
}

/// A written type as a `std:` cell's check spells it: a plain name as
/// written (`Self` as `self_ty` spells it), `string[]`, `?string`, `?bytes`, `?i32`
/// and `@Result<i64 | f64 | T, string>` as std-wasm's types spell them
/// (`std_wasm.Type`), anything else `another type`.
fn spelledType(t: ast.TypeRef, self_ty: ?[]const u8) []const u8 {
    return switch (t) {
        .named => |n| if (std.mem.eql(u8, n, "Self")) (self_ty orelse "Self") else n,
        .array => |e| if (std.mem.eql(u8, spelledType(e.*, self_ty), "string")) "string[]" else "another type",
        .optional => |e| blk: {
            const inner = spelledType(e.*, self_ty);
            if (std.mem.eql(u8, inner, "string")) break :blk "?string";
            // Decision 346 — `bytes`' codecs answer one when the text is one.
            if (std.mem.eql(u8, inner, "bytes")) break :blk "?bytes";
            if (std.mem.eql(u8, inner, "i32")) break :blk "?i32";
            break :blk "another type";
        },
        .generic => |g| blk: {
            if (!g.is_builtin or !std.mem.endsWith(u8, g.name, "Result") or g.args.len != 2) break :blk "another type";
            if (!std.mem.eql(u8, spelledType(g.args[1], self_ty), "string")) break :blk "another type";
            const ok = spelledType(g.args[0], self_ty);
            if (std.mem.eql(u8, ok, "i64")) break :blk "Result<i64, string>";
            if (std.mem.eql(u8, ok, "f64")) break :blk "Result<f64, string>";
            if (std.mem.eql(u8, ok, "T")) break :blk "Result<T, string>";
            break :blk "another type";
        },
        else => "another type",
    };
}

// ── generic decorator argument validation (annotation processors, P1) ─────────
//
// A decorator is any fn whose first param is `comptime _: @Decl` (recognized by
// `registerDecoratorSig` into `env.decorators`). Applying `#[d(args)]` is sugar
// for a comptime call `d(reflect(decl), args…)`; the trailing `args` are checked
// here against the decorator's declared signature — arity + argument types —
// with no lib knowledge. PLACEMENT rules (where a marker may sit) are the
// decorator body's job (P2), not the core's.

/// Validate every `#[decorator(args)]` application in `program` against the
/// recognized decorator's trailing signature. Annotations whose name is not a
/// recognized decorator are left untouched: builtins (`external`) validate
/// elsewhere, and an unknown bare marker stays lenient (a lib may not be loaded).
fn validateDecorators(env: *Env, program: ast.Program) InferError!void {
    try refuseNonComptimeDecoratorParams(env, program);
    try checkTypedMetaCalls(env, program);
    try checkTemplateAnnotations(env, program);
    if (env.decorators.count() == 0) return;
    for (program.decls) |decl| switch (decl) {
        .@"fn" => |f| try checkDecoratorAnnotations(env, program, f.annotations, .{ .name = f.name, .type_ = try fnDeclType(env, f.name) }),
        // Decision 356 — a decorator on a module-level `val` runs like one on a `fn`;
        // `@Decl<T>` binds `T` to the `val`'s type.
        .val => |v| {
            // Decision 356 names a `val`; a module `var` with a decorator is
            // refused at the annotation until it is decided (`116-c`).
            if (v.mutable) for (v.annotations) |a| {
                if (a.is_builtin or !env.decorators.contains(a.name)) continue;
                const msg = try std.fmt.allocPrint(env.arena, "`#[{s}]` annotates the module `var` `{s}`, and a decorator runs on a `val`, never on a `var`", .{ a.name, v.name });
                return decoratorError(env, a, msg, "Declare the binding with `val`, or move the decorator to a `val` or a `fn` that reads it.");
            };
            try checkDecoratorAnnotations(env, program, v.annotations, .{ .name = v.name, .type_ = try fnDeclType(env, v.name) });
        },
        .type_ => |tdecl| {
            const self = try typeDeclType(env, tdecl.name);
            try checkDecoratorAnnotations(env, program, tdecl.annotations, .{ .name = tdecl.name, .type_ = self, .isType = true });
            if (tdecl.shape == .record) for (tdecl.recordFields()) |fld| {
                try checkDecoratorAnnotations(env, program, fld.annotations, .{ .name = fld.name, .type_ = try fieldDeclType(env, tdecl, fld) });
            };
            for (tdecl.methods) |m| try checkDecoratorAnnotations(env, program, m.annotations, .{ .name = m.name, .type_ = null });
        },
        .behavior => |i| {
            try checkDecoratorAnnotations(env, program, i.annotations, .{ .name = i.name, .type_ = env.namedType(i.name) catch null });
            for (i.methods) |m| try checkDecoratorAnnotations(env, program, m.annotations, .{ .name = m.name, .type_ = null });
        },
        else => {},
    };
}

/// Every annotation list of `program` — a function's, a `val`'s, a type's, its
/// fields' and methods', a behavior's and its methods' — with the declaration
/// it annotates: the parameters and type parameters in scope for a template
/// annotation's holes (decision 311), and the owner a method's `Self` names.
const AnnotatedSite = struct {
    anns: []const ast.Annotation,
    params: []const ast.Param = &.{},
    generics: []const ast.GenericParam = &.{},
    owner: ?[]const u8 = null,
    ownerGenerics: []const ast.GenericParam = &.{},
    name: []const u8,
};

fn annotatedSites(env: *Env, program: ast.Program) InferError![]const AnnotatedSite {
    var out: std.ArrayListUnmanaged(AnnotatedSite) = .empty;
    for (program.decls) |decl| switch (decl) {
        .@"fn" => |f| try out.append(env.arena, .{ .anns = f.annotations, .params = f.params, .generics = f.genericParams, .name = f.name }),
        .val => |v| try out.append(env.arena, .{ .anns = v.annotations, .name = v.name }),
        .type_ => |t| {
            try out.append(env.arena, .{ .anns = t.annotations, .name = t.name });
            if (t.shape == .record) for (t.recordFields()) |fld| try out.append(env.arena, .{ .anns = fld.annotations, .name = fld.name });
            for (t.methods) |m| try out.append(env.arena, .{ .anns = m.annotations, .params = m.params, .generics = m.genericParams, .owner = t.name, .ownerGenerics = t.genericParams, .name = m.name });
        },
        .behavior => |b| {
            try out.append(env.arena, .{ .anns = b.annotations, .name = b.name });
            for (b.methods) |m| try out.append(env.arena, .{ .anns = m.annotations, .params = m.params, .generics = m.genericParams, .owner = b.name, .ownerGenerics = b.genericParams, .name = m.name });
        },
        else => {},
    };
    return out.items;
}

/// Decision 425 — a record field's (or a function parameter's) default that holds a template call
/// (`type Conf(label: string = dbl "x")`) is inferred against the field's type,
/// which expands it (`Env.templateExpansions` under the call's location): the
/// constructor's default fill (`transform.zig` `injectedDefault`) shares the
/// node, so every call that leaves the field out gets the expansion. Any other
/// default keeps its own checks.
fn expandTemplateFieldDefaults(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |d| {
        // A function's parameter default, the same way: the call's fill
        // shares the node.
        if (d == .@"fn") {
            const f = d.@"fn";
            if (memberFn.declParamIndex(f) != null) continue;
            if (f.returnType) |rt| if (rt.isTemplateReturnType()) continue;
            var genericMap = std.StringHashMap(*T.Type).init(env.arena);
            defer genericMap.deinit();
            for (f.genericParams) |gp| try genericMap.put(gp.name, try env.freshVar());
            for (f.params) |p| {
                const dv = p.default orelse continue;
                var finder: UnexpandedTemplateCall = .{ .env = env };
                finder.walk(ast.Expr, dv);
                if (finder.found == null) continue;
                const typed = try inferExprTyped(env, dv);
                if (p.destruct == null) try unifyAt(env, try resolveParamType(env, p, genericMap), typed.getType(), dv.getLoc());
            }
            continue;
        }
        if (d != .type_ or d.type_.shape != .record) continue;
        const t = d.type_;
        for (t.recordFields()) |fld| {
            const dv = fld.default orelse continue;
            var finder: UnexpandedTemplateCall = .{ .env = env };
            finder.walk(ast.Expr, dv);
            if (finder.found == null) continue;
            const typed = try inferExprTyped(env, dv);
            if (try fieldDeclType(env, t, fld)) |want| try unifyAt(env, want, typed.getType(), dv.getLoc());
        }
    }
}

/// Decision 425 — a template function exists only while the program
/// compiles, so a call of one that inference did not expand (no
/// `Env.templateExpansions` entry under its location) would reach a backend as
/// a run-time call of a function that is not there. Refused at the call
/// (`template-call-unexpanded`), never left to run as `undefined`. A
/// template's or a decorator's own body runs at build and is not walked.
pub fn refuseUnexpandedTemplateCalls(env: *Env, program: ast.Program) InferError!void {
    var finder: UnexpandedTemplateCall = .{ .env = env };
    for (program.decls) |d| {
        if (d == .@"fn") {
            const f = d.@"fn";
            if (memberFn.declParamIndex(f) != null) continue;
            if (f.returnType) |rt| if (rt.isTemplateReturnType()) continue;
        }
        finder.walk(ast.DeclKind, d);
        if (finder.found) |c| {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s} \"…\"` calls a template function here, where the compiler does not expand it", .{ diagnostics.template_call_unexpanded, c.callee });
            env.lastError = TypeError.custom(msg, "A template call expands wherever an expression may stand (decision 425); this position was missed — report it.").withLoc(c.loc);
            return error.TypeError;
        }
    }
}

const UnexpandedTemplateCall = struct {
    env: *Env,
    found: ?struct { callee: []const u8, loc: ast.Loc } = null,

    fn walk(self: *UnexpandedTemplateCall, comptime V: type, v: V) void {
        if (self.found != null) return;
        if (V == ast.Expr) if (v == .call and v.call.kind == .call) {
            const c = v.call.kind.call;
            if (!c.is_builtin and c.calleeExpr == null and
                (if (c.receiver == null) templateFnNamed(self.env, c.callee) != null else templateMethodNamed(self.env, c.callee) != null) and
                !self.env.templateMethodDeclined.contains(v.call.loc) and
                !self.env.templateExpansions.contains(v.call.loc))
            {
                self.found = .{ .callee = c.callee, .loc = v.call.loc };
                return;
            }
        };
        switch (@typeInfo(V)) {
            .pointer => |ptr| switch (ptr.size) {
                .one => if (@typeInfo(ptr.child) != .@"fn" and @typeInfo(ptr.child) != .@"opaque") self.walk(ptr.child, v.*),
                .slice => if (ptr.child != u8) for (v) |item| self.walk(ptr.child, item),
                else => {},
            },
            .optional => |o| if (v) |x| self.walk(o.child, x),
            .@"struct" => |st| inline for (st.fields) |fl| {
                if (!fl.is_comptime) self.walk(fl.type, @field(v, fl.name));
            },
            .@"union" => |un| if (un.tag_type != null) switch (v) {
                inline else => |payload| self.walk(@TypeOf(payload), payload),
            },
            else => {},
        }
    }
};

/// A template function's name as a receiver (`qlib.make(5)`, where a library
/// names its template after itself and the name is also the library's
/// namespace handle): typed by the template's binding, as before
/// `template-function-value`, which refuses the name read as a value.
fn templateNameReceiver(env: *Env, recv: ast.Expr) InferError!?*ast.TypedExpr {
    if (recv != .identifier or recv.identifier.kind != .ident) return null;
    const rn = recv.identifier.kind.ident;
    if (env.localBindDepth(rn) != null or templateFnNamed(env, rn) == null) return null;
    const ty = env.lookup(rn) orelse return null;
    return try makeTypedPtr(env, TypedExpr{ .identifier = .{ .loc = recv.identifier.loc, .type_ = ty, .kind = .{ .ident = rn } } });
}

/// Whether any annotation of `program` is a template annotation `#[f "…"]`.
fn hasTemplateAnnotation(env: *Env, program: ast.Program) InferError!bool {
    for (try annotatedSites(env, program)) |site| for (site.anns) |a| {
        if (a.template != null) return true;
    };
    return false;
}

/// The template function `name` names: an imported one, or one of this
/// module's (`Env.fnDecls` — decorators run before the bodies that register
/// a local template in `Env.templateFns`).
fn templateFnNamed(env: *Env, name: []const u8) ?ast.FnDecl {
    if (env.templateFns.get(name)) |t| return t;
    const f = env.fnDecls.get(name) orelse return null;
    const rt = f.returnType orelse return null;
    return if (rt.isTemplateReturnType()) f else null;
}

/// Decision 311 — the template annotation `#[f @`…`]`. `f` is a template
/// function written as an annotation, taking the annotated declaration's
/// handle beside its text (`memberFn.isTemplateAnnotation`, question s29-a);
/// refused at the annotation: a name that is no template function
/// (`template-annotation-not-template`), a template that takes no
/// `syntax decl` (`template-annotation-without-decl`), and any other form
/// naming a template — `#[f(…)]`, `#[f]`, `#[f "…"]` —
/// (`syntax-call-outside-syntax`, decision 577 (3)).
fn checkTemplateAnnotations(env: *Env, program: ast.Program) InferError!void {
    for (try annotatedSites(env, program)) |site| for (site.anns) |a| {
        if (a.is_builtin) continue;
        const at = a.loc orelse ast.Loc{ .line = 1, .col = 1 };
        const tfn = templateFnNamed(env, a.name);
        if (a.template == null) {
            const t = tfn orelse continue;
            if (env.decorators.contains(a.name)) continue;
            // Decision 577 (3) — `#[f(…)]` and `#[f]` naming a template.
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}{s}]` names the template `{s}`, which is written `#[{s} @`…`]`", .{ diagnostics.syntax_call_outside_syntax, a.name, if (a.args.len > 0) "(…)" else "", a.name, a.name });
            const hint = if (memberFn.isTemplateAnnotation(t))
                "A template takes its text unevaluated: write the template text after the name, `#[f @`…`]` (decision 577 (3))."
            else
                "A template takes its text unevaluated: write the template text after the name, `#[f @`…`]` — and declare `syntax decl: unknown` beside its `syntax q: string` (decisions 311, 577 (3)).";
            env.lastError = TypeError.custom(msg, hint).withLoc(at);
            return error.TypeError;
        }
        const t = tfn orelse {
            const what: []const u8 = if (env.decorators.contains(a.name))
                "a decorator"
            else if (env.lookup(a.name)) |ty| (if (ty.deref().* == .func) "a function that is not a template function" else "not a function") else "not declared";
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s} @`…`]` names `{s}`, which is {s}", .{ diagnostics.template_annotation_not_template, a.name, a.name, what });
            env.lastError = TypeError.custom(msg, "A template annotation names a template function — `fn f(syntax q: string, syntax decl: unknown) -> R` —; a decorator is written `#[f(…)]` (decisions 311, 578).").withLoc(at);
            return error.TypeError;
        };
        // Decision 577 (3) — a template annotation writes the template text.
        if (t.returnType) |rt| if (ast.isExprKeywordReturn(rt) and a.templateText == null) {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s} \"…\"]` names the template `{s}`, which is written `#[{s} @`…`]`", .{ diagnostics.syntax_call_outside_syntax, a.name, a.name, a.name });
            env.lastError = TypeError.custom(msg, "Write `#[f @`…`]` (decision 577 (3)).").withLoc(at);
            return error.TypeError;
        };
        if (!memberFn.isTemplateAnnotation(t)) {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s} @`…`]` names the template function `{s}`, which takes no `syntax decl: unknown` beside its text", .{ diagnostics.template_annotation_without_decl, a.name, a.name });
            env.lastError = TypeError.custom(msg, "Written as an annotation, a template receives the annotated declaration as its second parameter — `fn f(syntax q: string, syntax decl: unknown) -> R` — and records its outputs on it (decision 311, question s29-a).").withLoc(at);
            return error.TypeError;
        }
    };
}

/// Decision 15 gives the annotation grammar to the checker, and front 17 step
/// 3 recorded the hole: `#[@TotallyMadeUp.Nonsense(whatever: 42)]` parsed,
/// checked and was dropped — on a `fn`, a `var`, a type, a field, a method. A
/// misspelled family (`#[@BeamMemroy.Ets]`) moves where the state lives with
/// nothing said. Every `@`-prefixed annotation now names a family the compiler
/// reads, or an annotation type (`implement @Annotation`) the module can see;
/// anything else is `unknown-annotation` at the annotation, naming the family
/// an edit away when there is one. The removed `@External.<Target>` and
/// `@Host` name what replaced them (decision 575 (6)).
fn refuseUnknownAnnotations(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| switch (decl) {
        .@"fn" => |f| try refuseUnknownAnnotationList(env, program, f.annotations),
        .val => |v| try refuseUnknownAnnotationList(env, program, v.annotations),
        .type_ => |tdecl| {
            try refuseUnknownAnnotationList(env, program, tdecl.annotations);
            if (tdecl.shape == .record) for (tdecl.recordFields()) |fld| try refuseUnknownAnnotationList(env, program, fld.annotations);
            for (tdecl.methods) |m| try refuseUnknownAnnotationList(env, program, m.annotations);
        },
        .behavior => |i| {
            try refuseUnknownAnnotationList(env, program, i.annotations);
            for (i.methods) |m| try refuseUnknownAnnotationList(env, program, m.annotations);
        },
        else => {},
    };
}

/// B-145 — a bare `#[name]` that names no decorator, no annotation type and
/// no template function is refused at the annotation, naming what `name` is:
/// nothing, a namespace (a module of the package or an imported one), or a
/// value (a `val`, a function that is no decorator).
fn refuseAnnotationNotDecorator(env: *Env, program: ast.Program, a: ast.Annotation) InferError!void {
    // A template annotation is judged by `checkTemplateAnnotations`.
    if (a.template != null or templateFnNamed(env, a.name) != null) return;
    const head = if (std.mem.indexOfScalar(u8, a.name, '.')) |i| a.name[0..i] else a.name;
    var namespace = env.namespaces.modules.contains(head) or env.namespaces.paths.contains(head);
    var value = false;
    for (program.decls) |d| switch (d) {
        .mod => |m| if (std.mem.eql(u8, m.name, head)) {
            namespace = true;
        },
        .val => |v| if (std.mem.eql(u8, v.name, a.name)) {
            value = true;
        },
        .@"fn" => |f| if (std.mem.eql(u8, f.name, a.name)) {
            value = true;
        },
        else => {},
    };
    // A dotted path through a namespace (`#[local.serverOnly]`, `#[m.deco]`)
    // resolves its last segment in that module: it passes unless the module's
    // published exports are known and lack the name.
    if (namespace and std.mem.indexOfScalar(u8, a.name, '.') != null) {
        const dot = std.mem.indexOfScalar(u8, a.name, '.').?;
        const exports = env.namespaces.modules.get(head) orelse return;
        if (exports.contains(a.name[dot + 1 ..])) return;
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` names nothing — `{s}` has no `{s}`", .{ diagnostics.annotation_not_a_decorator, a.name, head, a.name[dot + 1 ..] });
        var err = TypeError.custom(msg, "An annotation names a decorator of the module, a `pub fn` whose first parameter is `comptime decl` of the declaration handle type.");
        if (a.loc) |l| err = err.withLoc(l);
        env.lastError = err;
        return error.TypeError;
    }
    const what: []const u8 = if (namespace)
        "a namespace"
    else if (value or env.lookup(a.name) != null)
        "a value"
    else
        "nothing";
    const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` names {s}, not a decorator", .{ diagnostics.annotation_not_a_decorator, a.name, what });
    var err = TypeError.custom(msg, "An annotation names a decorator — a `pub fn` whose first parameter is `comptime decl` of the declaration handle type — or an annotation type of your own; declare it, or delete the annotation.");
    if (a.loc) |l| err = err.withLoc(l);
    env.lastError = err;
    return error.TypeError;
}

fn refuseUnknownAnnotationList(env: *Env, program: ast.Program, anns: []const ast.Annotation) InferError!void {
    for (anns) |a| {
        // Decision 606 (4) — `#[compiler.external(…)]` is the source annotation.
        if (implementationsParse.isSourceAnnotation(a)) continue;
        // Decisions 663, 681, 774 — `compiler.stage` and
        // `compiler.beamMemory`, read by the compiler (`hostStage`,
        // `validateMemoryAnnotations`) as `compiler.external` is.
        if (a.stageOf() != null) {
            try refuseStageAnnotation(env, a);
            continue;
        }
        if (a.beamMemoryOf() != null) continue;
        // Decision 774 — the bare spelling names no decorator of its own.
        if (!a.is_builtin and (std.mem.eql(u8, a.name, "stage") or std.mem.eql(u8, a.name, "beamMemory")) and !env.decorators.contains(a.name)) {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}(…)]` is a member of `compiler` — write `#[compiler.{s}({s})]` (decision 774)", .{ diagnostics.unknown_annotation, a.name, a.name, try joinAnnotationArgs(env, a) });
            var e = TypeError.custom(msg, "`stage` and `beamMemory` are read by the compiler, as `external` is: one home, `compiler`.");
            if (a.loc) |l| e = e.withLoc(l);
            env.lastError = e;
            return error.TypeError;
        }
        if (!a.is_builtin) {
            // `#[mocks.mokc]` through a std module handle names a decorator
            // of that module or nothing: it used to do nothing, silently.
            if (env.decorators.contains(a.name)) continue;
            const dot = std.mem.indexOfScalar(u8, a.name, '.') orelse {
                try refuseAnnotationNotDecorator(env, program, a);
                continue;
            };
            const mod = env.stdDecoratorHandles.get(a.name[0..dot]) orelse {
                try refuseAnnotationNotDecorator(env, program, a);
                continue;
            };
            const msg = try std.fmt.allocPrint(env.arena, "{s}: std module `{s}` has no decorator `{s}`", .{ diagnostics.unknown_annotation, mod, a.name[dot + 1 ..] });
            var err = TypeError.custom(msg, "A std module's decorators are its `pub fn`s whose first parameter is `comptime decl: @Decl`.");
            if (a.loc) |l| err = err.withLoc(l);
            env.lastError = err;
            return error.TypeError;
        }
        if (ast.isRemovedEffectAnnotation(a.name)) continue;
        const family = if (std.mem.indexOfScalar(u8, a.name, '.')) |i| a.name[0..i] else a.name;
        // Decision 575 (6) — `@External.<Target>` and `@Host` are gone.
        if (std.mem.eql(u8, family, "External") or std.mem.eql(u8, a.name, "Host")) {
            const msg = if (std.mem.eql(u8, a.name, "Host"))
                try std.fmt.allocPrint(env.arena, "{s}: `#[@Host]` is gone (decision 575 (6))", .{diagnostics.unknown_annotation})
            else
                try std.fmt.allocPrint(env.arena, "{s}: `#[@{s}]` is gone — a `declare fn` names its sources with `#[@external(.{s}(…))]` (decision 575 (6))", .{ diagnostics.unknown_annotation, a.name, if (std.mem.indexOfScalar(u8, a.name, '.')) |i| a.name[i + 1 ..] else "<Target>" });
            var e = TypeError.custom(msg, "Each source is a value of std's `Implementation`: `#[@external(.Erlang(\"lists:member($1, $0)\"), .JavaScript(\"$0.includes($1)\"), .Wasm(op: \"f64.floor\"))]`.");
            if (a.loc) |l| e = e.withLoc(l);
            env.lastError = e;
            return error.TypeError;
        }
        // Decisions 663, 774 — `@Stage` and `@BeamMemory` are members of
        // `compiler` now: `#[compiler.stage(.Any)]`, `#[compiler.beamMemory(.Ets)]`.
        const msg = if (std.mem.eql(u8, family, "Stage") or std.mem.eql(u8, family, "BeamMemory")) msg: {
            const case = if (std.mem.indexOfScalar(u8, a.name, '.')) |i| a.name[i + 1 ..] else "<Case>";
            const args = a.writtenArgs();
            const inner = if (args.len == 0) "" else try std.fmt.allocPrint(env.arena, "({s})", .{try joinAnnotationArgs(env, a)});
            break :msg try std.fmt.allocPrint(env.arena, "{s}: `#[@{s}]` is gone — write `#[{s}(.{s}{s})]` (decisions 663, 774)", .{ diagnostics.unknown_annotation, a.name, if (std.mem.eql(u8, family, "Stage")) ast.stage_annotation else ast.beam_memory_annotation, case, inner });
        } else try std.fmt.allocPrint(env.arena, "{s}: `#[@{s}]` names no annotation", .{ diagnostics.unknown_annotation, a.name });
        var e = TypeError.custom(msg, "An annotation is a decorator written without the `@`: `#[compiler.external(…)]`, `#[compiler.stage(.Any)]`, `#[compiler.beamMemory(.<Mode>)]`, or a decorator of your own.");
        if (a.loc) |l| e = e.withLoc(l);
        env.lastError = e;
        return error.TypeError;
    }
}

/// An annotation's arguments as written, `label: value` where labelled.
fn joinAnnotationArgs(env: *Env, a: ast.Annotation) InferError![]const u8 {
    var out: std.ArrayListUnmanaged(u8) = .empty;
    for (a.writtenArgs(), 0..) |arg, i| {
        if (i > 0) try out.appendSlice(env.arena, ", ");
        if (a.labelOf(i)) |l| {
            try out.appendSlice(env.arena, l);
            try out.appendSlice(env.arena, ": ");
        }
        try out.appendSlice(env.arena, arg);
    }
    return out.items;
}

/// Decision 663 — `#[compiler.stage(…)]` takes `.Any` alone: a host function is `Run`
/// unless declared `Any` (376 (4)); `#[compiler.beamMemory(…)]` is read by
/// `validateMemoryAnnotations`.
fn refuseStageAnnotation(env: *Env, a: ast.Annotation) InferError!void {
    const arg = a.stageOf() orelse return;
    if (std.mem.eql(u8, arg.case, "Any") and arg.inner.len == 0) return;
    const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[compiler.stage({s})]` — a host function declares only `#[compiler.stage(.Any)]`", .{ diagnostics.unknown_annotation, try joinAnnotationArgs(env, a) });
    var e = TypeError.custom(msg, "A host function is `Run` unless it is declared `#[compiler.stage(.Any)]` (decision 376 (4)); a function with a body has the stage its body gives.");
    if (a.loc) |l| e = e.withLoc(l);
    env.lastError = e;
    return error.TypeError;
}

/// The declaration a decorator application annotates, as decision 280 (2)
/// reads it: its name (diagnostics) and its type — the type itself, a field's
/// type, a function's or a `val`'s type — which `@Decl<T>` binds `T` to; null where the
/// declaration has none (a method).
const DecoratedDecl = struct {
    name: []const u8,
    type_: ?*T.Type,
    /// A `type` declaration (decision 564: only a type implements a behavior).
    isType: bool = false,
};

/// A function's type as its signature registered it — or a module-level
/// `val`'s binding type (decision 356) — copied so a decorator's `@Decl<…>`
/// pattern binds against it without touching the binding.
fn fnDeclType(env: *Env, name: []const u8) InferError!?*T.Type {
    const t = env.lookup(name) orelse return null;
    var seen = std.AutoHashMap(*T.TypeCell, *T.Type).init(env.arena);
    defer seen.deinit();
    return try instantiateType(env, t, &seen, .allVars);
}

/// The type a `type` declaration names, a fresh variable per type parameter.
fn typeDeclType(env: *Env, name: []const u8) InferError!?*T.Type {
    const td = env.lookupTypeDef(name) orelse return null;
    const generics = switch (td) {
        inline else => |d| d.genericParams,
    };
    const args = try env.arena.alloc(*T.Type, generics.len);
    for (args) |*a| a.* = try env.freshVar();
    return try env.namedTypeArgs(name, args);
}

/// A record field's declared type, the record's type parameters fresh
/// variables. Null when it does not resolve here (its error is the field's).
fn fieldDeclType(env: *Env, owner: ast.TypeDecl, fld: ast.Field) InferError!?*T.Type {
    var map = std.StringHashMap(*T.Type).init(env.arena);
    defer map.deinit();
    for (owner.genericParams) |gp| try map.put(gp.name, try env.freshVar());
    const saved = env.lastError;
    return resolveTypeRefInContext(env, fld.typeRef, map) catch {
        env.lastError = saved;
        return null;
    };
}

/// Decision 280 (0) — every parameter of a decorator after its `@Decl` is
/// `comptime`, written out: its argument exists only while the program
/// compiles. Refused at the parameter, in the module that declares it.
fn refuseNonComptimeDecoratorParams(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| switch (decl) {
        .type_ => |t| for (t.methods) |m| try refuseComptimeDefaults(env, m.params, false),
        .behavior => |b| for (b.methods) |m| try refuseComptimeDefaults(env, m.params, false),
        else => {},
    };
    for (program.decls) |decl| {
        const name: []const u8, const params: []const ast.Param = switch (decl) {
            .@"fn" => |f| .{ f.name, f.params },
            else => continue,
        };
        if (!isDecoratorParams(params)) {
            // Decision 551 — a top-level function's `comptime` parameter may
            // default to a `@TypeInfo.all(…)` query, answered at the call.
            try refuseComptimeDefaults(env, params, decl == .@"fn" and !typeinfoAll.isTemplateFn(decl.@"fn"));
            continue;
        }
        for (params[1..]) |p| {
            if (p.modifier == .@"comptime") continue;
            const msg = try std.fmt.allocPrint(env.arena, "{s}: the decorator `{s}`'s parameter `{s}` is not `comptime`", .{ diagnostics.decorator_param_not_comptime, name, p.name });
            const hint = try std.fmt.allocPrint(env.arena, "A decorator's arguments exist only while the program compiles: write `comptime {s}: …` (decision 280).", .{p.name});
            env.lastError = TypeError.custom(msg, hint).withLoc(if (p.loc.line != 0) p.loc else p.typeLoc);
            return error.TypeError;
        }
    }
}

/// A `comptime` parameter takes a default only in a decorator (decision 280
/// (0)), where the annotation that leaves it out hands the body the default:
/// no call site of an ordinary function fills one, so it is refused at the
/// default — before 280 the parser refused it at the `=`.
/// Decision 551: `catalogue` admits a default that is a `@TypeInfo.all(…)`
/// query (a top-level function's, not a template's nor a method's).
/// Decision 616 — a `syntax` parameter is code as written, no value: its
/// default (`compiler.bp`'s `syntax at: ?unknown = null`) is not 280's.
fn refuseComptimeDefaults(env: *Env, params: []const ast.Param, catalogue: bool) InferError!void {
    for (params) |p| {
        if (p.modifier != .@"comptime" or p.arrival == .syntax) continue;
        const d = p.default orelse continue;
        if (catalogue and typeinfoAll.isCatalogueDefault(p)) continue;
        const msg = try std.fmt.allocPrint(env.arena, "{s}: the `comptime` parameter `{s}` takes a default only in a decorator", .{ diagnostics.comptime_default_outside_decorator, p.name });
        env.lastError = TypeError.custom(msg, "Pass the argument at every call, or make the function a decorator (`comptime decl: @Decl` first).").withLoc(d.getLoc());
        return error.TypeError;
    }
}

/// Check one declaration's annotation list.
fn checkDecoratorAnnotations(env: *Env, program: ast.Program, anns: []const ast.Annotation, target: DecoratedDecl) InferError!void {
    for (anns) |a| {
        if (a.is_builtin) continue; // refused by `refuseUnknownAnnotations`.
        // Decision 575 (6) — `external`'s sources: `checkImplementations`.
        if (implementationsParse.isSourceAnnotation(a)) continue;
        const sig = env.decorators.get(a.name) orelse continue;
        try checkDecoratorArgs(env, program, a, sig, target);
    }
}

/// Which argument each parameter of a decorator takes (after its `@Decl`):
/// `slots[p]` the index of parameter `p`'s argument, null when the annotation
/// leaves it out; `rest` the arguments of the variadic last parameter, in order.
pub const DecoratorArgMap = struct {
    slots: []?usize,
    rest: []const usize,
};

/// Decision 280 — the arguments of `#[name(args)]` meet the parameters as a
/// call's do: positional ones first, in order, then labelled ones by name; a
/// variadic last parameter (267) takes the positional ones left. Each refusal
/// is located at the argument.
fn mapDecoratorArgs(env: *Env, a: ast.Annotation, sig: envMod.DecoratorSig, owner: []const u8) InferError!DecoratorArgMap {
    const params = sig.params;
    const slots = try env.arena.alloc(?usize, params.len);
    @memset(slots, null);
    var rest: std.ArrayListUnmanaged(usize) = .empty;
    const variadicAt: ?usize = if (params.len > 0 and params[params.len - 1].variadic) params.len - 1 else null;
    var next: usize = 0;
    var labelled = false;
    for (a.args, 0..) |_, i| {
        if (a.labelOf(i)) |label| {
            labelled = true;
            const at = for (params, 0..) |p, j| {
                if (std.mem.eql(u8, p.name, label)) break j;
            } else {
                const msg = try std.fmt.allocPrint(env.arena, "`#[{s}]` has no parameter `{s}`", .{ a.name, label });
                return decoratorArgError(env, a, i, msg, "A label names one of the decorator's parameters (after its `@Decl`).");
            };
            if (variadicAt != null and at == variadicAt.?) {
                const msg = try std.fmt.allocPrint(env.arena, "`#[{s}]`'s `{s}` is variadic and takes no label", .{ a.name, label });
                return decoratorArgError(env, a, i, msg, "Pass the variadic parameter's arguments positionally, after the fixed ones (decision 267).");
            }
            if (slots[at] != null) {
                const msg = try std.fmt.allocPrint(env.arena, "`#[{s}]` gives `{s}` twice", .{ a.name, label });
                return decoratorArgError(env, a, i, msg, "Each parameter takes one argument.");
            }
            slots[at] = i;
            continue;
        }
        if (labelled) {
            const msg = try std.fmt.allocPrint(env.arena, "`#[{s}]` argument {d} is positional after a labelled one", .{ a.name, i + 1 });
            return decoratorArgError(env, a, i, msg, "Write the positional arguments first, then the labelled ones.");
        }
        if (variadicAt) |v| if (next >= v) {
            try rest.append(env.arena, i);
            continue;
        };
        if (next >= params.len) {
            const msg = try std.fmt.allocPrint(env.arena, "`#[{s}]` on `{s}` expects {d} argument(s), got {d}", .{ a.name, owner, params.len, a.args.len });
            return decoratorArgError(env, a, i, msg, "Match the decorator's declared parameters (after the leading `comptime _: @Decl`).");
        }
        slots[next] = i;
        next += 1;
    }
    return .{ .slots = slots, .rest = rest.items };
}

/// A default an omitted decorator argument takes: one `isClosedDefault`
/// admits, or a variant written `.Name` — resolved against the parameter's
/// type in the decorator's own module.
fn isClosedDecoratorDefault(e: ast.Expr) bool {
    if (e == .identifier and e.identifier.kind == .dotIdent) return true;
    return isClosedDefault(e);
}

/// Type-check a single `#[name(args…)]` application against the decorator's
/// signature (decision 280): `@Decl<T>`'s pattern against the annotated
/// declaration, then every argument against its parameter, `T` bound — at
/// the argument.
fn checkDecoratorArgs(env: *Env, program: ast.Program, a: ast.Annotation, sig: envMod.DecoratorSig, target: DecoratedDecl) InferError!void {
    const owner = target.name;
    const map = try mapDecoratorArgs(env, a, sig, owner);
    // An omitted parameter takes its default only when the default is closed
    // (`isClosedDecoratorDefault`): the decorator body runs in its own module,
    // where a default naming a binding of the declaring module has nothing to
    // read — the same rule C-04 applies to a function's default across a
    // module boundary.
    for (sig.params, 0..) |p, j| {
        if (p.variadic or map.slots[j] != null) continue;
        if (p.default) |d| {
            if (isClosedDecoratorDefault(d)) continue;
            const msg = try std.fmt.allocPrint(env.arena, "`#[{s}]` on `{s}` leaves out `{s}`, whose default names a binding the decorator body cannot read", .{ a.name, owner, p.name });
            return decoratorError(env, a, msg, "A decorator argument's default must be closed — a literal, `true` / `false`, a sign, a variant `.Name`, or an array / tuple of those; otherwise pass the argument.");
        }
        const msg = try std.fmt.allocPrint(env.arena, "`#[{s}]` on `{s}` expects {d} argument(s), got {d} — `{s}` is not given", .{ a.name, owner, sig.params.len, a.args.len, p.name });
        return decoratorError(env, a, msg, "Match the decorator's declared parameters (after the leading `comptime _: @Decl`).");
    }

    // The decorator's parameter types, its type parameters fresh: resolved
    // where it is declared for a local decorator, from its registered
    // signature (whose types came with the import) for an imported one.
    var generics = std.StringHashMap(*T.Type).init(env.arena);
    defer generics.deinit();
    for (sig.generics) |gp| try generics.put(gp.name, try env.freshVar());
    const declWant = if (sig.decl) |d| try resolveDecoratorParamType(env, d, generics) else null;
    const wants = try env.arena.alloc(?*T.Type, sig.params.len);
    for (sig.params, 0..) |p, j| wants[j] = if (p.typeRef == .typeparam) null else try resolveDecoratorParamType(env, p.typeRef, generics);

    // Decision 280 (2) — `@Decl<P>`: `P` meets the annotated declaration's
    // type, binding the type parameters it names; a declaration that does
    // not match is refused at the annotation.
    // Decision 564 — `@Decl<B>`, `B` a behavior: the declaration is a type
    // implementing `B`, refused at the annotation otherwise.
    const declBehavior: ?[]const u8 = sig.declBehavior orelse if (declWant) |dw| blk: {
        const d = dw.deref();
        if (d.* != .named or d.named.args.len != 1) break :blk null;
        const p = d.named.args[0].deref();
        if (p.* != .named or !(isBehaviorType(env, p) or isBehaviorName(env, p.named.name))) break :blk null;
        break :blk p.named.name;
    } else null;
    if (declBehavior) |b| {
        const implementsIt = if (target.isType) typeImplementsBehavior(env, owner, b) else false;
        if (!implementsIt) {
            const msg = try std.fmt.allocPrint(env.arena, "`#[{s}]` needs a type implementing `{s}` — `{s}` does not", .{ a.name, b, owner });
            const hint = try std.fmt.allocPrint(env.arena, "The decorator's `@Decl<{s}>` names the behavior its declarations implement (decision 564): write `implement {s}` on the type.", .{ b, b });
            return decoratorError(env, a, msg, hint);
        }
    } else if (declWant) |dw| if (dw.deref().* == .named and dw.deref().named.args.len == 1) {
        var pattern = dw.deref().named.args[0];
        // Decision 316 — `@Decl<fn(..) -> R>`: a function of any parameters;
        // only its return meets the declaration's.
        const anyParams = if (sig.decl) |d| declPatternAnyParams(d) else false;
        if (target.type_) |actual| {
            // Spelled before unifying, which binds the parameters it can.
            const prevMap = env.fnGenericMap;
            env.fnGenericMap = &generics;
            var spelled = try decoratorSpelling(env, pattern, 0);
            if (anyParams and pattern.deref().* == .func) {
                const ret = pattern.deref().func.ret;
                spelled = try std.fmt.allocPrint(env.arena, "fn(..) -> {s}", .{try decoratorSpelling(env, ret, 0)});
                if (actual.deref().* == .func) pattern = try env.funcType(actual.deref().func.params, ret);
            }
            env.fnGenericMap = prevMap;
            const saved = env.lastError;
            unifyUnlocated(env, pattern, actual) catch {
                env.lastError = saved;
                // A type declaration is spelled as one (613's wording).
                const msg = if (target.isType)
                    try std.fmt.allocPrint(env.arena, "`#[{s}]` expects a declaration of type `{s}`, and `{s}` is a type", .{ a.name, spelled, owner })
                else
                    try std.fmt.allocPrint(env.arena, "`#[{s}]` expects a declaration of type `{s}`, and `{s}` is `{s}`", .{ a.name, spelled, owner, try decoratorSpelling(env, actual, 0) });
                return decoratorError(env, a, msg, "The decorator's `@Decl<…>` names the shape of the declaration it annotates (decision 280).");
            };
        }
    };

    const values = try env.arena.alloc(envMod.DecoratorArgValue, sig.params.len);
    for (sig.params, 0..) |p, j| {
        const isType = p.typeRef == .typeparam;
        // Decision 364 (2) — what the body does with the parameter: an
        // argument not known at build is refused only where the body reads
        // it; one it never reads reaches it as `undefined`.
        const use: syntaxParam.Use = if (sig.fn_decl) |dfn| syntaxParam.useOf(dfn, p.name) else .{};
        if (p.variadic) {
            const elem: ?*T.Type = if (wants[j]) |w| blk: {
                const d = w.deref();
                break :blk if (d.* == .named and std.mem.eql(u8, d.named.name, "array") and d.named.args.len == 1) d.named.args[0] else null;
            } else null;
            var joined: std.ArrayListUnmanaged(u8) = .empty;
            var written: std.ArrayListUnmanaged(u8) = .empty;
            try joined.append(env.arena, '[');
            try written.append(env.arena, '[');
            var known = true;
            for (map.rest, 0..) |i, k| {
                const e = try checkDecoratorArg(env, program, a, i, p, elem, use);
                if (!e.known) known = false;
                if (k > 0) try joined.appendSlice(env.arena, ", ");
                if (k > 0) try written.appendSlice(env.arena, ", ");
                try written.appendSlice(env.arena, a.args[i]);
                if (e.known) try joined.appendSlice(env.arena, (try decoratorArgValue(env, program, e.expr.*, e.lexeme orelse a.args[i], elem, false, 0)).source);
            }
            try joined.append(env.arena, ']');
            try written.append(env.arena, ']');
            values[j] = if (known) .{ .source = joined.items, .built = true } else .{ .source = "undefined", .built = false, .absent = true };
            values[j].lexeme = written.items;
            continue;
        }
        if (map.slots[j]) |i| {
            const e = try checkDecoratorArg(env, program, a, i, p, wants[j], use);
            // Decision 575 (5) — `comptime t: type<T>`: the type argument binds
            // `T`, met with what the rest of the signature bound.
            if (isType and p.typeRef.typeparam.len == 1 and p.typeRef.typeparam[0] == .named) if (generics.get(p.typeRef.typeparam[0].named)) |bound| {
                const written: ast.TypeRef = .{ .named = std.mem.trim(u8, a.args[i], " ") };
                if (try resolveDecoratorParamType(env, written, std.StringHashMap(*T.Type).init(env.arena))) |argTy| {
                    const saved = env.lastError;
                    unifyUnlocated(env, bound, argTy) catch {
                        env.lastError = saved;
                        const msg = try std.fmt.allocPrint(env.arena, "type mismatch: `#[{s}]`'s `{s}` binds `{s}`, which is `{s}` here, to `{s}`", .{ a.name, p.name, p.typeRef.typeparam[0].named, try decoratorSpelling(env, bound, 0), a.args[i] });
                        env.lastError = TypeError.custom(msg, "A `type<T>` argument binds `T` (decision 575 (5)); the other parameters that name `T` must agree with it.").withLoc(a.argLoc(i) orelse a.loc orelse .{ .line = 0, .col = 0 });
                        return error.TypeError;
                    };
                }
            };
            values[j] = if (e.known)
                try decoratorArgValue(env, program, e.expr.*, e.lexeme orelse a.args[i], wants[j], isType, 0)
            else
                .{ .source = "undefined", .built = false, .absent = true };
            values[j].loc = a.argLoc(i);
            values[j].lexeme = a.args[i];
        } else {
            const d = p.default.?;
            const lexeme = try defaultLexeme(env.arena, d);
            values[j] = try decoratorArgValue(env, program, d, lexeme, wants[j], isType, 0);
            values[j].lexeme = lexeme;
        }
    }
    if (a.loc) |l| try env.decoratorArgValues.put(env.arena, l, values);
    // Decision 370 (2) — each type parameter as this annotation bound it
    // (`_` when nothing did), for the types of a member function.
    if (a.loc) |l| if (sig.generics.len > 0) {
        const typeArgs = try env.arena.alloc(memberFn.TypeArg, sig.generics.len);
        for (sig.generics, 0..) |gp, k| typeArgs[k] = .{ .name = gp.name, .spelled = try decoratorSpelling(env, generics.get(gp.name).?, 0) };
        try env.decoratorTypeArgs.put(env.arena, l, typeArgs);
    };
}

/// A decorator parameter's type in the applying module. Null when a name it
/// spells is not in scope here (a namespaced std decorator's own types):
/// that argument is checked by the body alone, as before decision 280.
fn resolveDecoratorParamType(env: *Env, ref: ast.TypeRef, generics: std.StringHashMap(*T.Type)) InferError!?*T.Type {
    const saved = env.lastError;
    const savedLoc = env.typeRefLoc;
    defer env.typeRefLoc = savedLoc;
    return resolveTypeRefInContext(env, ref, generics) catch |err| switch (err) {
        error.TypeError => {
            env.lastError = saved;
            return null;
        },
        else => |e| return e,
    };
}

/// Decision 316 — whether a decorator's `@Decl<…>` names `fn(..) -> R`, a
/// function of any parameters.
/// Decision 564 — the name `@Decl<B>` gives a decorator's declarations, when
/// `B` is a plain name (not one of the decorator's type parameters).
pub fn declPatternName(f: ast.FnDecl) ?[]const u8 {
    if (f.params.len == 0) return null;
    const decl = f.params[0].typeRef;
    if (!decl.isDeclType() or decl.generic.args.len != 1) return null;
    const arg = decl.generic.args[0];
    if (arg != .named) return null;
    for (f.genericParams) |g| if (std.mem.eql(u8, g.name, arg.named)) return null;
    return arg.named;
}

pub fn declPatternAnyParams(decl: ast.TypeRef) bool {
    if (decl != .generic or decl.generic.args.len != 1) return false;
    const p = decl.generic.args[0];
    return p == .function and p.function.anyParams;
}

/// The argument `a.args[i]` as an expression, every node located where the
/// argument stands in the file: the lexeme is a slice of the source, so it is
/// lexed behind as many line breaks and spaces as its start.
fn parseDecoratorArg(env: *Env, lexeme: []const u8, at: ast.Loc) InferError!*ast.Expr {
    const pad = (at.line -| 1) + (at.col -| 1);
    const src = try env.arena.alloc(u8, pad + lexeme.len);
    @memset(src[0..at.line -| 1], '\n');
    @memset(src[at.line -| 1..pad], ' ');
    @memcpy(src[pad..], lexeme);
    var lx = Lexer.init(src);
    const tokens = lx.scanAll(env.arena) catch return error.OutOfMemory;
    var p = Parser.init(tokens);
    const node = try env.arena.create(ast.Expr);
    node.* = p.parseExpr(env.arena) catch {
        const msg = try std.fmt.allocPrint(env.arena, "`{s}` is not one expression", .{lexeme});
        env.lastError = TypeError.custom(msg, "A decorator argument is one value.").withLoc(at);
        return error.TypeError;
    };
    return node;
}

/// The module-level `val` (not `var`) of `program` named `name`.
fn moduleVal(program: ast.Program, name: []const u8) ?ast.ValDecl {
    for (program.decls) |d| switch (d) {
        .val => |v| if (std.mem.eql(u8, v.name, name)) return v,
        else => {},
    };
    return null;
}

/// Decision 280 (0) — the part of a decorator argument not known while the
/// program compiles: a call of a function (`env("X")`, `now()`) — a
/// constructor builds a value from known ones —, a module `var`, or a module
/// `val` holding either. Null when every part is known.
fn decoratorArgNotKnownAt(env: *Env, program: ast.Program, e: ast.Expr, depth: usize) ?ast.Loc {
    if (depth > 16) return null;
    switch (e) {
        .call => |c| {
            if (c.kind != .call) return c.loc;
            const call = c.kind.call;
            // A constructor builds a value from known ones: a record's
            // (`Entity(…)`), a variant's — qualified (`Implementation.Erlang(…)`)
            // or written `.Erlang(…)`, its enum the parameter's (decision
            // 575 (6)).
            const variant = if (call.calleeExpr) |ce|
                ce.* == .identifier and ce.identifier.kind == .dotIdent
            else if (call.receiver) |r|
                r.* == .identifier and r.identifier.kind == .ident and env.lookupTypeDef(r.identifier.kind.ident) != null
            else
                false;
            if (variant or (call.receiver == null and !call.is_builtin and env.lookupTypeDef(call.callee) != null)) {
                for (call.args) |arg| if (decoratorArgNotKnownAt(env, program, arg.value.*, depth + 1)) |l| return l;
                return null;
            }
            // Decision 380 — a call of a function computed at build (an `Any`
            // one, `callFoldable`) over arguments known there is known there:
            // `revalidate: clock.hours(1)` (290).
            if (callFoldable(env, c)) {
                for (call.args) |arg| if (decoratorArgNotKnownAt(env, program, arg.value.*, depth + 1)) |l| return l;
                return null;
            }
            return c.loc;
        },
        .identifier => |id| switch (id.kind) {
            .ident => |n| {
                const v = moduleVal(program, n) orelse return null;
                if (v.mutable) return id.loc;
                return decoratorArgNotKnownAt(env, program, v.value.*, depth + 1);
            },
            else => return null,
        },
        .unaryOp => |u| return decoratorArgNotKnownAt(env, program, u.expr.*, depth + 1),
        .binaryOp => |b| return decoratorArgNotKnownAt(env, program, b.lhs.*, depth + 1) orelse
            decoratorArgNotKnownAt(env, program, b.rhs.*, depth + 1),
        .collection => |col| switch (col.kind) {
            .grouped => |inner| return decoratorArgNotKnownAt(env, program, inner.*, depth + 1),
            .arrayLit => |al| {
                for (al.elems) |x| if (decoratorArgNotKnownAt(env, program, x, depth + 1)) |l| return l;
                return null;
            },
            .tupleLit => |tl| {
                for (tl.elems) |x| if (decoratorArgNotKnownAt(env, program, x, depth + 1)) |l| return l;
                return null;
            },
            else => return null,
        },
        else => return null,
    }
}

/// One argument against its parameter (decision 280 (1), (3), (4)): the
/// argument as an expression, and whether it is known while the program
/// compiles (decision 364 (2)).
/// `lexeme` is the argument's source when the check rewrote it (a
/// decorator's name handed over as its identity), else null — the text as
/// written.
const CheckedDecoratorArg = struct { expr: *ast.Expr, known: bool, lexeme: ?[]const u8 = null };

fn checkDecoratorArg(env: *Env, program: ast.Program, a: ast.Annotation, i: usize, p: ast.Param, want: ?*T.Type, use: syntaxParam.Use) InferError!CheckedDecoratorArg {
    const loc = a.argLoc(i) orelse ast.Loc{ .line = 0, .col = 0 };
    const e = try parseDecoratorArg(env, a.args[i], loc);
    // Decision 268 — a `Decorator` parameter (`comptime marker:
    // @Expr<Decorator>`) takes a decorator's name, and nothing else: the
    // argument is handed over as the declaration's identity, what a
    // `DeclAnnotation.decorator` holds, so `marker.value.same(email)` compares
    // two identities (decision 371). A `Decorator[]` takes an array literal
    // of names. 144 B-10: the name was checked as the function it is.
    if (want) |w| if (try decoratorParamArg(env, e, optionalInner(w) orelse w)) {
        return .{ .expr = e, .known = true, .lexeme = try defaultLexeme(env.arena, e.*) };
    };
    const known = try checkDecoratorArgExpr(env, program, a, i, e, p, want, loc, use);
    return .{ .expr = e, .known = known };
}

fn checkDecoratorArgExpr(env: *Env, program: ast.Program, a: ast.Annotation, i: usize, e: *ast.Expr, p: ast.Param, want: ?*T.Type, loc: ast.Loc, use: syntaxParam.Use) InferError!bool {
    if (p.typeRef == .typeparam) {
        try checkDecoratorTypeArg(env, program, a, e.*, p, loc);
        return true;
    }
    // Decision 364 (2) — an argument not known at build (a call of a
    // function, a module `var`, a `val` holding one) is the program's to
    // evaluate: refused only where the body reads the parameter.
    const unknownAt = decoratorArgNotKnownAt(env, program, e.*, 0);
    if (unknownAt) |at| if (use.reads) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]`'s argument `{s}` is not known while the program compiles, and the decorator reads `{s}.value`", .{ diagnostics.decorator_value_not_comptime, a.name, a.args[i], p.name });
        env.lastError = TypeError.custom(msg, "`.value` answers an argument known at build — a literal, a variant, a field `.name`, a `val` or a constructor of those (decision 364 (2)); hand any other expression on to the program.").withLoc(at);
        return error.TypeError;
    };
    const w = want orelse return unknownAt == null;
    if (e.* == .identifier and e.identifier.kind == .dotIdent) {
        try checkDotNameArg(env, a, e.identifier.kind.dotIdent, p, w, loc);
        return unknownAt == null;
    }
    if (dotVariantCallName(e.*)) |name| if (declaredEnumOfParam(env, a, w) != null) {
        try checkDotVariantCallArg(env, a, e.call.kind.call, name, p, w, loc);
        return unknownAt == null;
    };
    // The parameter's type is the argument's expectation, as a call's is
    // (an integer literal takes the integer type asked for, `.Name` its enum).
    const prevExpected = env.expectedType;
    env.expectedType = optionalInner(w) orelse w;
    const got = blk: {
        defer env.expectedType = prevExpected;
        if (e.* == .identifier and e.identifier.kind == .ident and env.lookup(e.identifier.kind.ident) == null) {
            if (moduleVal(program, e.identifier.kind.ident)) |v| {
                if (v.typeAnnotation) |ta| if (try resolveDecoratorParamType(env, ta, std.StringHashMap(*T.Type).init(env.arena))) |t| break :blk t;
                break :blk try inferExpr(env, v.value.*);
            }
        }
        break :blk try inferExpr(env, e.*);
    };
    // A value meets `?T` as a `T` (`null` meets it whole).
    const target = if (optionalInner(w)) |inner| (if (optionalInner(got) == null) inner else w) else w;
    const saved = env.lastError;
    unifyArgument(env, target, got, loc) catch |err| switch (err) {
        error.TypeError => {
            env.lastError = saved;
            const msg = try std.fmt.allocPrint(env.arena, "type mismatch: `#[{s}]`'s `{s}` expects `{s}`, got `{s}`", .{ a.name, p.name, try decoratorSpelling(env, w, 0), try decoratorSpelling(env, got, 0) });
            env.lastError = TypeError.custom(msg, "A decorator argument is checked against its parameter like a call's (decision 280).").withLoc(loc);
            return error.TypeError;
        },
        else => |x| return x,
    };
    return unknownAt == null;
}

/// A type as a decorator diagnostic spells it: a function `fn(A) -> R`, an
/// unbound type parameter `_`.
fn decoratorSpelling(env: *Env, t: *T.Type, depth: usize) InferError![]const u8 {
    const d = t.deref();
    if (depth > 8) return "…";
    switch (d.*) {
        .func => |f| {
            var buf: std.ArrayListUnmanaged(u8) = .empty;
            try buf.appendSlice(env.arena, "fn(");
            for (f.params, 0..) |pt, i| {
                if (i > 0) try buf.appendSlice(env.arena, ", ");
                try buf.appendSlice(env.arena, try decoratorSpelling(env, pt, depth + 1));
            }
            try buf.appendSlice(env.arena, ") -> ");
            try buf.appendSlice(env.arena, try decoratorSpelling(env, f.ret, depth + 1));
            return buf.items;
        },
        .typeVar => return if (env.fnGenericMap != null) genericSpelling(env, d, depth) else "_",
        .named => |n| {
            if (std.mem.eql(u8, n.name, "optional") and n.args.len == 1) return std.fmt.allocPrint(env.arena, "?{s}", .{try decoratorSpelling(env, n.args[0], depth + 1)});
            if (std.mem.eql(u8, n.name, "array") and n.args.len == 1) return std.fmt.allocPrint(env.arena, "{s}[]", .{try decoratorSpelling(env, n.args[0], depth + 1)});
            if (std.mem.eql(u8, n.name, field_key_type_name) and n.args.len == 1) return std.fmt.allocPrint(env.arena, "Type.Field<{s}>", .{try decoratorSpelling(env, n.args[0], depth + 1)});
            if (n.args.len == 0) return n.name;
            var buf: std.ArrayListUnmanaged(u8) = .empty;
            try buf.appendSlice(env.arena, n.name);
            try buf.append(env.arena, '<');
            for (n.args, 0..) |x, i| {
                if (i > 0) try buf.appendSlice(env.arena, ", ");
                try buf.appendSlice(env.arena, try decoratorSpelling(env, x, depth + 1));
            }
            try buf.append(env.arena, '>');
            return buf.items;
        },
        else => return genericSpelling(env, d, depth),
    }
}

/// `comptime t: type` (decision 280 (1), lg2-f) — the argument names a type:
/// a type, an alias, a behavior or a primitive in scope here.
fn checkDecoratorTypeArg(env: *Env, program: ast.Program, a: ast.Annotation, e: ast.Expr, p: ast.Param, loc: ast.Loc) InferError!void {
    if (e == .identifier and e.identifier.kind == .ident) {
        const n = e.identifier.kind.ident;
        if (isTypeArgName(env, program, n)) return;
        if (env.lookup(n) == null) {
            env.lastError = TypeError.unknownTypeName(n).withLoc(loc);
            return error.TypeError;
        }
    }
    const got = try inferExpr(env, e);
    const msg = try std.fmt.allocPrint(env.arena, "type mismatch: `#[{s}]`'s `{s}` expects a `type`, got `{s}`", .{ a.name, p.name, try decoratorSpelling(env, got, 0) });
    env.lastError = TypeError.custom(msg, "Pass the type itself (`MailSender`), never its name as a string (decision 281).").withLoc(loc);
    return error.TypeError;
}

/// A name a `type` argument may be: a primitive, a type, an alias or a
/// behavior this module declares or imports.
fn isTypeArgName(env: *Env, program: ast.Program, n: []const u8) bool {
    if (isKnownTypeName(env, n) or env.lookupTypeAlias(n) != null or env.importedBehaviorDecls.contains(n)) return true;
    for (program.decls) |d| switch (d) {
        .behavior => |b| if (std.mem.eql(u8, b.name, n)) return true,
        .type_ => |t| if (std.mem.eql(u8, t.name, n)) return true,
        else => {},
    };
    // An imported record, struct or enum binds its constructor.
    if (env.lookup(n)) |t| {
        const d = t.deref();
        if (d.* == .func and d.func.ret.isNamed(n)) return true;
    }
    return false;
}

/// The name a `Type.Field<T>` holds the `T` of, after std's associated-type
/// rewrite (`assoc_types.zig`).
const field_key_type_name = "Type__Field";

/// `.name` (decision 280 (3), (4)) — against a `Type.Field<T>` a field of `T`,
/// against an enum one of its variants; the name exactly as declared.
fn checkDotNameArg(env: *Env, a: ast.Annotation, name: []const u8, p: ast.Param, want: *T.Type, loc: ast.Loc) InferError!void {
    const w = (optionalInner(want) orelse want).deref();
    if (w.* == .named and std.mem.eql(u8, w.named.name, field_key_type_name) and w.named.args.len == 1) {
        const t = w.named.args[0].deref();
        if (t.* != .named) {
            const msg = try std.fmt.allocPrint(env.arena, "`#[{s}]`'s `.{s}` names a field, and `{s}`'s `Type.Field<…>` has no type to read it from", .{ a.name, name, p.name });
            env.lastError = TypeError.custom(msg, "`.name` resolves against the `T` of `Type.Field<T>`: bind it through the decorator's `@Decl<T>` (decision 280 (2)).").withLoc(loc);
            return error.TypeError;
        }
        if (recordFieldNames(env, t.named.name)) |fields| {
            for (fields) |f| if (std.mem.eql(u8, f.name, name)) return;
        }
        env.lastError = TypeError.unknownField(t.named.name, name).withLoc(loc);
        return error.TypeError;
    }
    if (w.* == .named) if (declaringModuleEnum(env, a, w.named.name)) |td| {
        for (td.shape.enum_.variants) |v| if (std.mem.eql(u8, v.name, name)) return;
        const msg = try std.fmt.allocPrint(env.arena, "`.{s}` names no variant of `{s}`", .{ name, w.named.name });
        env.lastError = TypeError.custom(msg, "A variant is written exactly as declared, case included (decision 280 (4)).").withLoc(loc);
        return error.TypeError;
    };
    if (w.* == .named) if (env.lookupTypeDef(w.named.name)) |td| if (td == .enum_) {
        for (td.enum_.variants) |v| if (std.mem.eql(u8, v.name, name)) return;
        const msg = try std.fmt.allocPrint(env.arena, "`.{s}` names no variant of `{s}`", .{ name, w.named.name });
        env.lastError = TypeError.custom(msg, "A variant is written exactly as declared, case included (decision 280 (4)).").withLoc(loc);
        return error.TypeError;
    };
    const msg = try std.fmt.allocPrint(env.arena, "type mismatch: `#[{s}]`'s `{s}` is `{s}`, and `.{s}` names a field or a variant", .{ a.name, p.name, try decoratorSpelling(env, want, 0), name });
    env.lastError = TypeError.custom(msg, "`.name` is a field of `T` against `Type.Field<T>`, or a variant against an enum.").withLoc(loc);
    return error.TypeError;
}

/// The enum the decorator's module declares for a parameter typed `want` (or `?want`).
fn declaredEnumOfParam(env: *const Env, a: ast.Annotation, want: *T.Type) ?ast.TypeDecl {
    const w = (optionalInner(want) orelse want).deref();
    if (w.* != .named) return null;
    return declaringModuleEnum(env, a, w.named.name);
}

/// `.Lazy(afterMs: 5)` — the variant a leading-dot constructor call names.
fn dotVariantCallName(e: ast.Expr) ?[]const u8 {
    if (e != .call or e.call.kind != .call) return null;
    const ce = e.call.kind.call.calleeExpr orelse return null;
    if (ce.* != .identifier or ce.identifier.kind != .dotIdent) return null;
    return ce.identifier.kind.dotIdent;
}

/// Decisions 587, 603 — a dotted variant with a payload in an annotation
/// argument (`#[load(.Lazy(afterMs: 5))]`): the parameter's declared type
/// tells which enum declares it, as for a bare `.Eager` (`checkDotNameArg`).
/// The variant must exist and carry a payload, each label must name one of its
/// fields and each argument meets its field's type.
fn checkDotVariantCallArg(env: *Env, a: ast.Annotation, call: anytype, name: []const u8, p: ast.Param, want: *T.Type, loc: ast.Loc) InferError!void {
    const w = (optionalInner(want) orelse want).deref();
    const td = declaredEnumOfParam(env, a, want) orelse {
        const msg = try std.fmt.allocPrint(env.arena, "`.{s}(…)` names a variant by its leading dot, and `#[{s}]`'s `{s}` is `{s}`, which declares no enum to read it from", .{ name, a.name, p.name, try decoratorSpelling(env, want, 0) });
        env.lastError = TypeError.custom(msg, "Give the parameter an enum type that declares the variant, or write `Enum.Variant(…)`.").withLoc(loc);
        return error.TypeError;
    };
    const variants = td.shape.enum_.variants;
    const variant = for (variants) |v| {
        if (std.mem.eql(u8, v.name, name)) break v;
    } else {
        const msg = try std.fmt.allocPrint(env.arena, "`.{s}` names no variant of `{s}`", .{ name, w.named.name });
        env.lastError = TypeError.custom(msg, "A variant is written exactly as declared, case included (decision 280 (4)).").withLoc(loc);
        return error.TypeError;
    };
    if (call.args.len > variant.fields.len) {
        env.lastError = TypeError.arityMismatch(name, variant.fields.len, call.args.len).withLoc(loc);
        return error.TypeError;
    }
    for (call.args, 0..) |arg, i| {
        const field = if (arg.label) |l| for (variant.fields) |f| {
            if (std.mem.eql(u8, f.name, l)) break f;
        } else {
            env.lastError = TypeError.unknownField(name, l).withLoc(arg.value.getLoc());
            return error.TypeError;
        } else variant.fields[i];
        // A payload type this module cannot resolve (one the decorator's
        // module declares) is checked where the decorator runs.
        const fieldTy = resolveTypeRef(env, field.typeRef) catch continue;
        const prevExpected = env.expectedType;
        env.expectedType = fieldTy;
        defer env.expectedType = prevExpected;
        const got = try inferExpr(env, arg.value.*);
        unifyArgument(env, fieldTy, got, arg.value.getLoc()) catch |err| switch (err) {
            error.TypeError => {
                const msg = try std.fmt.allocPrint(env.arena, "type mismatch: `.{s}`'s `{s}` expects `{s}`, got `{s}`", .{ name, field.name, try decoratorSpelling(env, fieldTy, 0), try decoratorSpelling(env, got, 0) });
                env.lastError = TypeError.custom(msg, "A variant's payload is checked against its fields like a call's.").withLoc(arg.value.getLoc());
                return error.TypeError;
            },
            else => |x| return x,
        };
    }
}

/// The enum `name` an imported decorator's module declares: the type its
/// parameter names, read where the decorator is declared (never an enum of
/// the same name this module or another one holds).
fn declaringModuleEnum(env: *const Env, a: ast.Annotation, name: []const u8) ?ast.TypeDecl {
    const sig = env.decorators.get(a.name) orelse return null;
    if (sig.module.len == 0) return null;
    const registry = env.typeDeclRegistry orelse return null;
    const decls = registry.get(sig.module) orelse return null;
    const d = decls.get(name) orelse return null;
    return if (d == .type_ and d.type_.shape == .enum_) d.type_ else null;
}

/// The fields a record or struct type declares, in order; null for any other.
fn recordFieldNames(env: *Env, name: []const u8) ?[]const envMod.FieldDef {
    const td = env.lookupTypeDef(name) orelse return null;
    return switch (td) {
        .record => |r| r.fields,
        .struct_ => |s| s.fields,
        .enum_ => null,
    };
}

/// Decision 280 (1) — what parameter `p` hands the decorator body once its
/// argument is typed. A string, a number or a `bool` is the literal term it
/// is; a function or a type is its name, as before decision 280 (what the body
/// reads of one is question s24-a); anything else — an array, a record, a
/// variant, `null`, a field key — is built by a function of the decorator
/// module, a field key `.name` as the `Type.Field<T>` record (`name`,
/// `typeName`, `annotations`), and a module `val` as its value.
fn decoratorArgValue(env: *Env, program: ast.Program, e: ast.Expr, lexeme: []const u8, want: ?*T.Type, isType: bool, depth: usize) InferError!envMod.DecoratorArgValue {
    const plain: envMod.DecoratorArgValue = .{ .source = lexeme, .built = false };
    if (isType or depth > 16) return plain;
    switch (e) {
        .literal => |l| switch (l.kind) {
            .stringLit, .numberLit => return plain,
            else => {},
        },
        .unaryOp => |u| if (u.expr.* == .literal and u.expr.literal.kind == .numberLit) return plain,
        .identifier => |id| switch (id.kind) {
            .ident => |n| {
                if (std.mem.eql(u8, n, "true") or std.mem.eql(u8, n, "false")) return plain;
                if (env.lookup(n) == null) if (moduleVal(program, n)) |v| {
                    return decoratorArgValue(env, program, v.value.*, try defaultLexeme(env.arena, v.value.*), want, false, depth + 1);
                };
                return plain;
            },
            .dotIdent => |n| if (want) |w| {
                const d = (optionalInner(w) orelse w).deref();
                if (d.* == .named and std.mem.eql(u8, d.named.name, field_key_type_name) and d.named.args.len == 1) {
                    const t = d.named.args[0].deref();
                    if (t.* == .named) return .{ .source = fieldKeySource(env, program, t.named.name, n) catch return error.OutOfMemory, .built = true };
                }
            },
            else => {},
        },
        else => {},
    }
    // `.Lazy(afterMs: 5)` against an enum parameter: the decorator module
    // re-reads the source with no expectation, so the enum is written out.
    if (dotVariantCallName(e) != null) if (want) |w| {
        const d = (optionalInner(w) orelse w).deref();
        if (d.* == .named and env.lookupTypeDef(d.named.name) == null) return .{ .source = try std.fmt.allocPrint(env.arena, "{s}{s}", .{ d.named.name, lexeme }), .built = true };
    };
    // A section path (`.Pad.All.4`) is its qualified constructor
    // (`Tok.Pad(_inner: …)`): the decorator module re-reads the source as
    // written, untyped, where the path is a chain of map reads.
    if (try blockEval.sectionRewrittenExpr(env.arena, blockEval.Rewrites.of(env), e)) |r| return .{ .source = try defaultLexeme(env.arena, r), .built = true };
    return .{ .source = lexeme, .built = true };
}

/// `.name` against `Type.Field<T>` as the record the body reads (decision
/// 308): `__bp_FieldKey(name, typeName, annotations)`, which the decorator
/// module lowers to the map a `decl.fields` entry is. The type name and the
/// field's annotations come from `T`'s declaration when this module declares
/// it; a type imported from another module gives its field type as the
/// checker spells it and no annotations.
fn fieldKeySource(env: *Env, program: ast.Program, typeName: []const u8, field: []const u8) (InferError || std.Io.Writer.Error)![]const u8 {
    var out: std.Io.Writer.Allocating = .init(env.arena);
    const w = &out.writer;
    try w.writeAll("__bp_FieldKey(");
    try writeBpString(w, field);
    try w.writeAll(", ");
    var local: ?ast.Field = null;
    for (program.decls) |d| switch (d) {
        .type_ => |td| if (td.shape == .record and std.mem.eql(u8, td.name, typeName)) {
            for (td.recordFields()) |f| if (std.mem.eql(u8, f.name, field)) {
                local = f;
            };
        },
        else => {},
    };
    if (local) |f| {
        try writeBpString(w, try declTypeName(env.arena, f.typeRef));
        try w.writeAll(", [");
        for (f.annotations, 0..) |an, i| {
            if (i > 0) try w.writeAll(", ");
            try w.writeAll("__bp_DeclAnnotation(");
            try writeBpString(w, an.name);
            try w.writeAll(", [");
            for (an.writtenArgs(), 0..) |arg, k| {
                if (k > 0) try w.writeAll(", ");
                try writeBpString(w, arg);
            }
            try w.writeAll("], ");
            try writeBpString(w, try annotationDecoratorId(env, an));
            try w.writeAll(")");
        }
        try w.writeAll("])");
    } else {
        const spelled: []const u8 = if (recordFieldNames(env, typeName)) |fields| for (fields) |f| {
            if (std.mem.eql(u8, f.name, field)) break try genericSpelling(env, f.type_, 0);
        } else "" else "";
        try writeBpString(w, spelled);
        try w.writeAll(", [])");
    }
    return out.written();
}

/// `s` as a botopink string literal.
fn writeBpString(w: *std.Io.Writer, s: []const u8) std.Io.Writer.Error!void {
    try w.writeByte('"');
    for (s) |c| switch (c) {
        '"' => try w.writeAll("\\\""),
        '\\' => try w.writeAll("\\\\"),
        '$' => try w.writeAll("\\$"),
        '\n' => try w.writeAll("\\n"),
        '\r' => try w.writeAll("\\r"),
        '\t' => try w.writeAll("\\t"),
        else => try w.writeByte(c),
    };
    try w.writeByte('"');
}

/// The zero-argument function of the decorator module that builds a
/// parameter's value (`DecoratorArgValue.built`).
fn builtArgFn(env: *Env, name: []const u8, source: []const u8) InferError!ast.FnDecl {
    const src = try std.fmt.allocPrint(env.arena, "fn {s}() {{ return {s}; }}", .{ name, source });
    var lx = Lexer.init(src);
    const tokens = lx.scanAll(env.arena) catch return error.OutOfMemory;
    var p = Parser.init(tokens);
    const program = p.parse(env.arena) catch return error.OutOfMemory;
    if (program.decls.len != 1 or program.decls[0] != .@"fn") return error.OutOfMemory;
    return program.decls[0].@"fn";
}

/// A decorator refusal located at argument `i`.
fn decoratorArgError(env: *Env, a: ast.Annotation, i: usize, message: []const u8, hint: []const u8) InferError {
    var e = TypeError.custom(message, hint);
    if (a.argLoc(i)) |loc| e = e.withLoc(loc);
    env.lastError = e;
    return error.TypeError;
}

// ── generic decorator invocation (annotation processors, P2) ──────────────────
//
// After argument validation, the decorator's BODY runs over the declaration it
// annotates: the core serializes that declaration into a `@Decl` handle and the
// body (lib code) gives the marker meaning — validate placement/arguments via
// `fail`/`failAt`. The core knows nothing about any specific marker. Runs only
// in the full compile pipeline (`env.templateEval` set, node available); tooling
// paths (LSP / compileTypesOnly) skip it.

/// Render a `TypeRef` as the type name a `@Decl` handle exposes: the type as
/// the source spells it (`TypeRef.format`) — `string`, `Array<string>`,
/// `string[]`, `fn(i32) -> i32`, `#(string, string)`, `?i32`,
/// `@Async<HandlerResponse>`. Never erased to a head and never empty: a
/// decorator that admits `Array<string>` must be able to refuse
/// `Array<Element>`.
/// Decision 848 — `compiler.variants(d)`: one entry per constructible variant.
/// The enum's own variants, then for each section (depth-first) its wrapper
/// constructor (`Token.Color`, one field holding the section) and its leaves,
/// a leaf's `section` the enclosing sections' names joined by `.`.
fn variantHandles(env: *Env, tdecl: ast.TypeDecl) InferError![]const decoratorEval.VariantHandle {
    var out: std.ArrayListUnmanaged(decoratorEval.VariantHandle) = .empty;
    for (tdecl.variants()) |v| try out.append(env.arena, try variantHandle(env, v, null));
    for (tdecl.sections()) |sec| try appendSectionHandles(env, &out, tdecl.name, sec, null);
    return out.items;
}

fn appendSectionHandles(
    env: *Env,
    out: *std.ArrayListUnmanaged(decoratorEval.VariantHandle),
    enumName: []const u8,
    sec: ast.EnumSection,
    parent: ?[]const u8,
) InferError!void {
    const path = if (parent) |p| try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ p, sec.name }) else sec.name;
    const wrapper = try env.arena.alloc(decoratorEval.FieldHandle, 1);
    wrapper[0] = .{
        .name = "value",
        .typeName = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ enumName, path }),
        .annotations = &.{},
    };
    try out.append(env.arena, .{ .name = sec.name, .fields = wrapper, .section = parent });
    for (sec.variants) |v| try out.append(env.arena, try variantHandle(env, v, path));
    for (sec.sections) |sub| try appendSectionHandles(env, out, enumName, sub, path);
}

fn variantHandle(env: *Env, v: ast.EnumVariant, section: ?[]const u8) InferError!decoratorEval.VariantHandle {
    const fields = try env.arena.alloc(decoratorEval.FieldHandle, v.fields.len);
    for (v.fields, 0..) |f, i| fields[i] = .{
        .name = f.name,
        .typeName = try declTypeName(env.arena, f.typeRef),
        .annotations = f.annotations,
    };
    return .{ .name = v.name, .fields = fields, .section = section };
}

fn declTypeName(arena: std.mem.Allocator, tr: ast.TypeRef) std.mem.Allocator.Error![]const u8 {
    return switch (tr) {
        .named => |n| n,
        else => std.fmt.allocPrint(arena, "{f}", .{tr}),
    };
}

/// Run every body-carrying decorator applied to one declaration over its handle.
/// `memberOwner` is the type a `decl.addMember` joins (decision 216): the
/// annotated type itself, the type that owns an annotated field or method, and
/// null for a function — which has no body a member could join.
fn runDeclDecorators(
    env: *Env,
    ctx: envMod.TemplateEvalCtx,
    program: ast.Program,
    phase: DecoratorPhase,
    anns: []const ast.Annotation,
    handle: decoratorEval.DeclHandle,
    memberOwner: ?[]const u8,
    /// Set for a top-level declaration: what `@TypeInfo.all` records of it.
    declared: ?struct { kind: reflectionMod.DeclaredEntry.Kind, isPub: bool },
) InferError!void {
    for (anns) |a| {
        if (a.is_builtin) continue;
        // Decision 575 (6) — std's `external` implements what it is written
        // with: the parser read its sources (`parser/implementations.zig`),
        // and its body is that reading.
        if (implementationsParse.isSourceAnnotation(a)) continue;
        // Decisions 681, 774 — `compiler.stage` and `compiler.beamMemory`
        // are read where the stage and the storage are; their bodies run
        // over nothing.
        if (a.stageOf() != null or a.beamMemoryOf() != null) continue;
        // Decision 311 — `#[f "…"]` runs the template function `f` over the
        // declaration: the literal its `q`, the handle its `decl`
        // (`checkTemplateAnnotations` refused any other shape first).
        const tfn: ?ast.FnDecl = if (a.template != null) templateFnNamed(env, a.name) orelse continue else null;
        if (tfn) |t| if (!memberFn.isTemplateAnnotation(t)) continue;
        const sig: envMod.DecoratorSig = if (tfn) |t| .{ .params = &.{}, .fn_decl = t } else env.decorators.get(a.name) orelse continue;
        const dfn = sig.fn_decl orelse continue; // bodyless `declare fn` marker
        const capture: ?*const template.CapturedExpr = if (tfn) |t| try templateAnnotationCapture(env, a, t) else null;
        // Decision 372 — a decorator that reads `.hooks` runs in the second
        // phase, after the module's bodies; every other one in the first.
        const readsHooks = try decoratorReadsHooks(env, a);
        if (phase == .hooksReaders and !readsHooks) continue;
        // Decision 216 (4) — the program's catalogue, in the order decorators
        // are written: a `.hooks` reader's entry is recorded in the first
        // phase too, so a catalogue read sees it whatever phase runs it.
        if (phase == .plain) if (declared) |d| if (env.reflection) |r| try r.addDeclared(.{
            .module = env.modulePath,
            .name = handle.name,
            .kind = d.kind,
            .isPub = d.isPub,
            // A `val`'s is its declared type as written (decision 356), `""` when none.
            .returnTypeName = if (d.kind == .function or d.kind == .val) handle.returnType else "",
            .decorator_owner = env.comptimeOwnerOf(dfn),
            .decorator_name = dfn.name,
            .seq = 0,
        });
        // Decision 604 — a marker's empty body has nothing to run; the
        // catalogue entry above is its reading.
        if (dfn.body.len == 0) continue;
        if (phase == .plain and readsHooks) continue;

        // Decision 280 — each parameter's value as `checkDecoratorArgs` typed
        // it, in parameter order: a literal term, or a function of the
        // decorator module that builds it (`DecoratorArgValue.built`).
        const values: []const envMod.DecoratorArgValue = (if (a.loc) |l| env.decoratorArgValues.get(l) else null) orelse &.{};
        var plain = try env.arena.alloc(template.PlainArg, values.len);
        var builtFns: std.ArrayListUnmanaged(ast.FnDecl) = .empty;
        for (values, 0..) |v, j| {
            plain[j] = .{ .paramName = sig.params[j].name, .source = v.source, .absent = v.absent };
            if (!v.built or v.absent) continue;
            const fname = try std.fmt.allocPrint(env.arena, "__bp_decorator_arg_{d}", .{j + 1});
            try builtFns.append(env.arena, try builtArgFn(env, fname, v.source));
            plain[j].call = fname;
        }

        // Diagnostics point at the annotation. A `failAt` span has no source text
        // to map onto for a declaration, so it is reported at the annotation too.
        const owner = env.comptimeOwnerOf(dfn);
        const local = std.mem.eql(u8, owner, env.modulePath);
        const found: Support = if (local)
            try decoratorSupport(env.arena, env.fnDecls, &env.importedFnSupport, dfn)
        else if (tfn != null)
            // An imported template brings what its module computed
            // (`expandTemplateCallViaRuntime`'s rule).
            (if (env.importedTemplateSupport.get(@intFromPtr(dfn.body.ptr))) |ts| Support{ .fns = ts.fns, .conflict = ts.conflict } else Support{ .fns = &.{} })
        else
            .{ .fns = sig.support, .conflict = sig.conflict };
        if (found.conflict) |c| return decoratorError(env, a, c, "Rename one of the two functions, so each name the decorator reaches is one function.");
        // The record and enum types the decorator and its functions name
        // (a package record an imported helper builds) travel with them
        // (`block_eval.typesReached`); the evaluator's own (`DeclKind`,
        // `Span`) are injected by it.
        // Decision 587 — the types the body names once inference resolved its
        // leading-dot variants (`.Erlang(…)` is `Implementation.Erlang(…)`).
        var hosts = try hostCells.Writer.init(env, program.decls);
        const runDfn = if (local) try withBuildLoads(env, try hosts.rewrite(try sameLoweredFn(env, program, dfn))) else dfn;
        // Decision 380 — an argument is written in this module: its std calls
        // (`clock.hours(1)`, 290) are this module's to rename, and the std
        // functions they reach travel with it.
        for (builtFns.items) |*bf| bf.* = try hosts.rewrite(bf.*);
        const carried = try std.mem.concat(env.arena, ast.FnDecl, &.{ &.{runDfn}, found.fns, builtFns.items });
        const reached = try blockEval.typesReached(env, carried, if (tfn != null) &(templateEval.injected_names ++ [_][]const u8{ "__DeclKind", ast.decl_type_name }) else &.{ "__DeclKind", "__Span", "DeclKind", "Span", ast.decl_type_name }, if (tfn != null) "" else owner);
        const support = try std.mem.concat(env.arena, ast.FnDecl, &.{ found.fns, reached.fns, builtFns.items });
        // Decision 364 — the body reads `x.value`; the module holds the value
        // in `x` (`syntax_param.zig`), and `x.fail(m)` names its argument.
        // Decision 371 — this module's functions the run reaches are typed
        // first when they compare decorators, and their `same` calls lowered;
        // or when they write a section path, and the path resolved.
        // Decision 341 — the std calls of this module's functions renamed to
        // the std functions the module carries (`host_cells.zig`), which
        // join the support with the host functions the run reaches.
        // What only the run reads — the decorator's erased body and the erased
        // support functions, a copy of every function the run reaches — is scratch:
        // it is gone when the run ends, not held until the session ends (144 B-117).
        var run_scratch = std.heap.ArenaAllocator.init(std.heap.page_allocator);
        defer run_scratch.deinit();
        const rs = run_scratch.allocator();
        const erasedSupport = try rs.alloc(ast.FnDecl, support.len);
        for (support, 0..) |sf, k| {
            const own = local and k < found.fns.len and std.mem.eql(u8, env.comptimeOwnerOf(sf), env.modulePath);
            erasedSupport[k] = try syntaxParam.eraseForRun(rs, if (own) try hosts.rewrite(try sameLoweredFn(env, program, sf)) else sf, isDecoratorParams(sf.params));
        }
        const runSupport = if (local)
            try std.mem.concat(rs, ast.FnDecl, &.{ erasedSupport, try hostCells.hostSupport(env, &env.fnDecls, try std.mem.concat(rs, ast.FnDecl, &.{ &.{runDfn}, erasedSupport })) })
        else if (builtFns.items.len > 0)
            try std.mem.concat(rs, ast.FnDecl, &.{ erasedSupport, try withoutListed(rs, try hostCells.hostSupport(env, &env.fnDecls, builtFns.items), erasedSupport) })
        else
            erasedSupport;
        // Decision 451 (3) — the calls of the decorator and of the functions
        // of its module it reaches are located: in this module's own file, or
        // in the decorator's, which the diagnostic then names
        // (`srcPathOfModule`).
        const located = try locatedFns(env, dfn, srcPathOfModule(env, owner), support[0..found.fns.len]);
        const outcome = decoratorEval.evaluate(env.arena, ctx.io, ctx.build_root, owner, srcPathOfModule(env, owner), try syntaxParam.eraseForRun(rs, runDfn, true), runSupport, located, reached.types, try completeHandle(env, try withOwner(env, try withMethodMeta(env, handle, memberOwner), if (declared == null) memberOwner else null)), plain, capture, &env.comptimeTraces, &env.buildOutput) catch {
            return decoratorError(env, a, "the decorator evaluator failed to run", "Decorator bodies run on the wasm comptime runtime inside the compiler (decision 434); this failure is the compiler's, not the body's — report it.");
        };
        switch (outcome) {
            .ok => |raw| for (if (capture) |cap| try unplaceholderContributions(env.arena, raw, cap.paramName, try holeSourcesOf(env.arena, a.template.?)) else raw, 0..) |c, ci| {
                // Decision 372 — the bodies are inferred: a `.hooks` reader
                // gives the program no code (`refuseHooksReaderOutputs`
                // refuses the call where it is written; this is the call
                // reached some other way, at the annotation).
                if (phase == .hooksReaders and c.kind != .meta and c.kind != .typedMeta) {
                    const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` reads `.hooks` and gives the program code (`{s}`)", .{ diagnostics.decorator_hooks_output, a.name, switch (c.kind) {
                        .emit => "@emit",
                        .member => "addMember",
                        .memberFn => "addMember",
                        .compile => "compiler.init",
                        else => "addType",
                    } });
                    return decoratorError(env, a, msg, hooks_output_hint);
                }
                switch (c.kind) {
                    // `@emit(...)` sources — spliced into the module by `analyzeModule`.
                    .emit => try env.contributions.append(env.arena, c.source),
                    // `decl.addMember(source)` — parsed into the owner's body by
                    // `analyzeSource` (decision 216 (1)).
                    .member => {
                        const target = memberOwner orelse {
                            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` on the {s} `{s}` calls `decl.addMember`, and a member belongs to a type", .{ diagnostics.decorator_member_without_type, a.name, ownerlessKindWord(handle.kind), handle.name });
                            return decoratorError(env, a, msg, "`decl.addMember(source)` adds to the annotated `type` or `behavior` (or to the type that owns an annotated field or method); a function or a `val` has no body to add to.");
                        };
                        // Decision 669 — a decorator of another module: each
                        // name the text reads resolves where it was written.
                        // The `print` / `panic` its std imports bind are
                        // read the same way, a decorator of this module's too.
                        var renames: []const memberFn.Rename = &.{};
                        var stdCalls: []const stdCallsMod.Item = &.{};
                        if (try memberFn.parseSourceMember(env.arena, c.source)) |m| {
                            const func = try memberFn.methodAsFunction(env.arena, m);
                            if (!local) renames = try memberRenames(env, a, dfn, c, func, &.{}, &.{});
                            stdCalls = try sourceMemberStdCalls(env, owner, func);
                        }
                        try env.memberContributions.append(env.arena, .{ .target = target, .source = c.source, .loc = a.loc, .decorator = a.name, .call = try outputCallSite(env, dfn, owner, raw[0..ci], c.kind), .renames = renames, .stdCalls = stdCalls });
                    },
                    // `decl.addMember(name, fn…)` (decision 370 (2)) — the
                    // member function the body wrote, rendered for the type with
                    // each parameter's argument spliced where it is used.
                    .memberFn => {
                        const target = memberOwner orelse {
                            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` on the {s} `{s}` calls `decl.addMember`, and a member belongs to a type", .{ diagnostics.decorator_member_without_type, a.name, ownerlessKindWord(handle.kind), handle.name });
                            return decoratorError(env, a, msg, "`decl.addMember(name, fn…)` adds to the annotated `type` or `behavior` (or to the type that owns an annotated field or method); a function or a `val` has no body to add to.");
                        };
                        const source = try memberFnSource(env, a, dfn, sig, values, c, target, local);
                        try env.memberContributions.append(env.arena, .{ .target = target, .source = source, .loc = a.loc, .decorator = a.name, .call = try outputCallSite(env, dfn, owner, raw[0..ci], c.kind) });
                    },
                    // `compiler.init(f)` (decision 575 (3)) — the executor
                    // the body wrote, rendered with each parameter's argument
                    // and each local it reads spliced, joins the module beside
                    // its declarations: a function, and the module-level `val`
                    // that calls it, so the module's body (decision 140) runs
                    // it once before `main`, in call order.
                    // Decision 580 — its `val` stands at the annotated
                    // declaration's index, not at the module's end.
                    .compile => {
                        // Decision 613 — `decl` is the annotated declaration
                        // spliced as code and bound to it: a method or a field
                        // by its owner's path (`Users.make`, `Config.db`),
                        // never the bare name the module would resolve.
                        const isMember = std.mem.eql(u8, handle.kind, "Method") or std.mem.eql(u8, handle.kind, "Field");
                        const annotated = if (isMember) if (memberOwner) |o| try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ o, handle.name }) else handle.name else handle.name;
                        const source = try executorSource(env, a, dfn, sig, values, c, local, annotated);
                        try env.executorAnchors.append(env.arena, .{ .contribution = env.contributions.items.len, .decl = env.decoratedDeclIndex, .loc = a.loc, .call = try outputCallSite(env, dfn, owner, raw[0..ci], c.kind), .decorator = a.name });
                        try env.contributions.append(env.arena, source);
                    },
                    // `decl.addType(name, source)` (decision 216 (3)) — an
                    // associated type of the owner, merged as `__Owner__Name`.
                    .assoc => {
                        const assoc_owner = memberOwner orelse {
                            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` on the {s} `{s}` calls `decl.addType`, and an associated type belongs to a type", .{ diagnostics.decorator_type_without_owner, a.name, ownerlessKindWord(handle.kind), handle.name });
                            return decoratorError(env, a, msg, "`decl.addType(name, source)` declares a type named through the annotated `type` or `behavior` (`City.Columns`); a function or a `val` has none.");
                        };
                        const valid = c.name.len > 0 and std.ascii.isUpper(c.name[0]) and for (c.name) |ch| {
                            if (!std.ascii.isAlphanumeric(ch)) break false;
                        } else true;
                        if (!valid) {
                            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` names an associated type of `{s}` `{s}`, which is not a type name", .{ diagnostics.decorator_type_name, a.name, assoc_owner, c.name });
                            return decoratorError(env, a, msg, "An associated type is named like any type: one identifier of letters and digits, starting upper-case (`Columns`, read `City.Columns`).");
                        }
                        if (env.reflection) |r| if (!try r.addAssoc(env.modulePath, assoc_owner, c.name)) {
                            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` declares `{s}.{s}`, and `{s}` already has an associated type `{s}`", .{ diagnostics.decorator_type_duplicate, a.name, assoc_owner, c.name, assoc_owner, c.name });
                            return decoratorError(env, a, msg, "An owner's associated types have one name each; rename the one this decorator declares.");
                        };
                        try env.typeContributions.append(env.arena, .{ .owner = assoc_owner, .name = c.name, .source = c.source, .loc = a.loc, .decorator = a.name, .call = try outputCallSite(env, dfn, owner, raw[0..ci], c.kind) });
                    },
                    // `decl.setMeta(v)` / `decl.addMeta(v)` (decision 298) — a
                    // typed value keyed by its record type.
                    .typedMeta => try recordTypedMeta(env, a, dfn, handle, values, c, memberOwner),
                    // `compiler.implement(source)` (decision 575 (6)) — the
                    // annotated declaration's implementation.
                    .implement => {
                        var impl = (try implementationOfJson(env.arena, c.data orelse .null)) orelse {
                            return decoratorError(env, a, "`compiler.implement` was handed no `Implementation`", "Hand it a value of std's `Implementation`: `compiler.implement(.Erlang(\"lists:member($1, $0)\"))`.");
                        };
                        impl.loc = a.loc;
                        try env.implementContributions.append(env.arena, .{ .target = handle.name, .owner = memberOwner, .impl = impl });
                    },
                    // `decl.setMeta(key, value)` (decision 216 (2)) — recorded in
                    // the session's reflection under the decorator's own name,
                    // before any body of this module is inferred (a `.hooks`
                    // reader's after them, decision 372: a read of it in this
                    // module is answered then, `answerDeferredMetaReads`).
                    .meta => {
                        const is_member = std.mem.eql(u8, handle.kind, "Field") or std.mem.eql(u8, handle.kind, "Method");
                        if (is_member) {
                            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` on the {s} `{s}` calls `decl.setMeta`, and meta describes a top-level declaration", .{ diagnostics.decorator_meta_on_member, a.name, if (std.mem.eql(u8, handle.kind, "Field")) "field" else "method", handle.name });
                            return decoratorError(env, a, msg, "`@typeInfo(X)` reflects a `type`, a `behavior` or a `fn`; set the meta from a decorator on the declaration itself.");
                        }
                        const r = env.reflection orelse continue;
                        if (!try r.addMeta(env.modulePath, handle.name, .{ .decorator = dfn.name, .key = c.key, .value = c.value })) {
                            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` sets `{s}` on `{s}` twice", .{ diagnostics.decorator_meta_duplicate, a.name, c.key, handle.name });
                            return decoratorError(env, a, msg, "A decorator sets each of its keys once per declaration; `@typeInfo(X).meta` answers one value per key.");
                        }
                    },
                }
            },
            .fail => |fl| {
                // Decision 364 (3) — `x.fail(…)` reports at `x`'s argument.
                if (fl.arg) |j| if (j < values.len) if (values[j].loc) |l| {
                    env.lastError = TypeError.custom(fl.message, "raised by the decorator via `fail` on this argument").withLoc(l);
                    return error.TypeError;
                };
                return decoratorError(env, a, fl.message, "raised by the decorator via `fail`/`failAt`");
            },
            inline .err, .raised => |failed, tag| {
                // Decorators run before any body of the module is inferred
                // (a `.hooks` reader after them, decision 372), so
                // a type error in the module's own decorator body (`decl.nope`)
                // reached the evaluator first and came back as its run-time
                // failure (`{badkey,nope}`) at the annotation. Check the body
                // now — and the module's own helpers it reaches: a type
                // error, located in the body, is the answer.
                if (local) {
                    // The module's `from "std"` imports are marked by pass 2,
                    // which has not run: a std namespace the body reaches
                    // (`io.random.float()`, its `__bp_ns_io_random` local)
                    // would read as unbound in place of the run's failure.
                    // Every path from here returns an error, so pass 2 never
                    // marks them a second time.
                    for (program.decls) |d| switch (d) {
                        .use => |u| _ = try markStdImports(env, u),
                        else => {},
                    };
                    _ = try inferFnDecl(env, dfn);
                    for (support) |sf| if (std.mem.eql(u8, env.comptimeOwnerOf(sf), env.modulePath)) {
                        _ = try inferFnDecl(env, sf);
                    };
                }
                if (tag == .err) {
                    return decoratorError(env, a, failed, "the decorator could not be evaluated");
                } else {
                    // Decisions 451 (3), 532 — located at the call that raised,
                    // in its own file (this module's, or the decorator's); the
                    // annotation is the last frame that ran it.
                    return raisedFrom(env, failed.message, "the decorator's body raised; each call of the chain is a `called from` line, down to the annotation", failed.frames, a.loc orelse .{ .line = 1, .col = 1 });
                }
            },
        }
    }
}

/// Decision 311 — the literal of a template annotation `#[f "…"]` captured as
/// a call site's is (`captureExprArg`): unevaluated, with its location, module
/// and origin scope; `q.value` reads only a literal without a hole
/// (decision 364 (2)); a template text holds no hole (decision 577 (5)).
fn templateAnnotationCapture(env: *Env, a: ast.Annotation, tfn: ast.FnDecl) InferError!*const template.CapturedExpr {
    const written = a.template.?;
    const at = a.templateLoc orelse a.loc orelse ast.Loc{ .line = 1, .col = 1 };
    const node = try parseDecoratorArg(env, written, at);
    const q = tfn.params[0].name;
    // Decision 577 — a template text `#[f @`…`]` is its raw bytes.
    const text: ?[]const u8 = if (node.* == .literal and node.literal.kind == .stringLit) (a.templateText orelse node.literal.kind.stringLit) else null;
    const valueRead = syntaxParam.useOf(tfn, q).value;
    const cap = try env.arena.create(template.CapturedExpr);
    cap.* = .{
        .callee = a.name,
        .paramIndex = 0,
        .paramName = q,
        .node = node,
        .text = text,
        .multiline = std.mem.startsWith(u8, written, "\"\"\"") or (a.templateText != null and std.mem.indexOfScalar(u8, a.templateText.?, '\n') != null),
        .templateText = a.templateText != null,
        .loc = at,
        .modulePath = env.modulePath,
        .srcFile = env.srcPathOf(env.modulePath),
        .scope = env.scopeSnapshot,
        .valueRead = valueRead,
    };
    // Decision 415 (2) — what `q.lookup` / `q.bindings` answer.
    if (decoratorSameMod.mentionsMethod(tfn, "lookup") or decoratorSameMod.mentionsMethod(tfn, "bindings")) {
        cap.* = (try withLookupHandles(env, &.{cap.*}))[0];
    }
    return cap;
}

/// The source of each `${…}` hole of a template annotation's literal, in order.
fn holeSourcesOf(arena: std.mem.Allocator, written: []const u8) InferError![]const []const u8 {
    const quote: usize = if (std.mem.startsWith(u8, written, "\"\"\"")) 3 else 1;
    if (written.len < 2 * quote) return &.{};
    return exprsMod.holeSources(arena, written[quote .. written.len - quote]);
}

/// Decision 311 — a template annotation's outputs name a hole the way built
/// code does, by its placeholder (`__bp_hole_<q>_<i>`, a part's `code`); where
/// the output is written each placeholder becomes the expression the hole
/// holds, as written (a method's parameter, by name). Every string an output
/// carries is rewritten: a source and a typed meta value's strings.
fn unplaceholderContributions(
    arena: std.mem.Allocator,
    contributions: []const decoratorEval.Contribution,
    q: []const u8,
    holes: []const []const u8,
) InferError![]const decoratorEval.Contribution {
    if (holes.len == 0) return contributions;
    const out = try arena.dupe(decoratorEval.Contribution, contributions);
    for (out) |*c| {
        c.source = try unplaceholder(arena, c.source, q, holes);
        c.value = try unplaceholder(arena, c.value, q, holes);
        if (c.data) |d| c.data = try unplaceholderJson(arena, d, q, holes);
    }
    return out;
}

fn unplaceholderJson(arena: std.mem.Allocator, v: std.json.Value, q: []const u8, holes: []const []const u8) InferError!std.json.Value {
    switch (v) {
        .string => |s| return .{ .string = try unplaceholder(arena, s, q, holes) },
        .array => |arr| {
            var na = std.json.Array.init(arena);
            for (arr.items) |item| try na.append(try unplaceholderJson(arena, item, q, holes));
            return .{ .array = na };
        },
        .object => |obj| {
            var no: std.json.ObjectMap = .{};
            var it = obj.iterator();
            while (it.next()) |e| try no.put(arena, e.key_ptr.*, try unplaceholderJson(arena, e.value_ptr.*, q, holes));
            return .{ .object = no };
        },
        else => return v,
    }
}

fn unplaceholder(arena: std.mem.Allocator, s: []const u8, q: []const u8, holes: []const []const u8) InferError![]const u8 {
    const prefix = try std.fmt.allocPrint(arena, "__bp_hole_{s}_", .{q});
    if (std.mem.indexOf(u8, s, prefix) == null) return s;
    var out: std.ArrayListUnmanaged(u8) = .empty;
    var i: usize = 0;
    while (i < s.len) {
        if (std.mem.startsWith(u8, s[i..], prefix)) {
            var j = i + prefix.len;
            while (j < s.len and std.ascii.isDigit(s[j])) j += 1;
            const n = std.fmt.parseInt(usize, s[i + prefix.len .. j], 10) catch null;
            if (n) |k| if (k < holes.len) {
                try out.appendSlice(arena, holes[k]);
                i = j;
                continue;
            };
        }
        try out.append(arena, s[i]);
        i += 1;
    }
    return out.items;
}

/// Decision 370 (2) — the source of the member `decl.addMember(c.name, fn…)`
/// gives `target`: the body's `c.index`-th member function
/// (`member_fn.collect`), each decorator parameter it reads replaced by the
/// argument as the annotation wrote it, each type parameter by what the
/// annotation bound it to — and, for a decorator declared in another module,
/// every other name it writes renamed to resolve in the decorator's module
/// (decision 384, `memberRenames`). Refused at the annotation: a `self` that
/// is not `target` and a type parameter left unbound (`decorator-member-type`).
fn memberFnSource(
    env: *Env,
    a: ast.Annotation,
    dfn: ast.FnDecl,
    sig: envMod.DecoratorSig,
    values: []const envMod.DecoratorArgValue,
    c: decoratorEval.Contribution,
    target: []const u8,
    local: bool,
) InferError![]const u8 {
    const declName = memberFn.declParamName(dfn) orelse return decoratorError(env, a, "the decorator has no `@Decl` handle", "");
    const fns = try memberFn.collect(env.arena, dfn, declName);
    if (c.index >= fns.len) return decoratorError(env, a, "the decorator evaluator handed back a member function the body does not write", "Report it: `decl.addMember(name, fn…)` numbers the body's member functions in source order.");
    const func = fns[c.index];
    // A decorator of this module runs before its body is checked.
    if (local) try refuseMemberFnShape(env, func, dfn.params, dfn.body);
    const typeArgs: []const memberFn.TypeArg = (if (a.loc) |l| env.decoratorTypeArgs.get(l) else null) orelse &.{};

    // The member's types at this annotation.
    for (try memberFn.typeNames(env.arena, func)) |n| for (typeArgs) |ta| {
        if (!std.mem.eql(u8, ta.name, n) or std.mem.indexOfScalar(u8, ta.spelled, '_') == null) continue;
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]`'s member `{s}` writes the type parameter `{s}`, which this annotation leaves unbound", .{ diagnostics.decorator_member_type, a.name, c.name, n });
        return decoratorError(env, a, msg, "A member function's types are known where the decorator is applied: bind the type parameter through `@Decl<T>` or an argument (decision 370 (2)).");
    };
    if (func.kind.params.len > 0 and std.mem.eql(u8, func.kind.params[0], "self")) {
        const t = func.kind.paramTypes[0];
        const spelled: []const u8 = switch (t) {
            .named => |n| blk: {
                for (typeArgs) |ta| if (std.mem.eql(u8, ta.name, n)) break :blk ta.spelled;
                break :blk n;
            },
            else => "",
        };
        if (!std.mem.eql(u8, spelled, target) and !std.mem.eql(u8, spelled, "Self")) {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]`'s member `{s}` takes `self` as `{s}`, and the member joins `{s}`", .{ diagnostics.decorator_member_type, a.name, c.name, if (spelled.len > 0) spelled else "another type", target });
            return decoratorError(env, a, msg, "A method's `self` is the type it joins — `fn(self: T)` where `@Decl<T>` binds `T` to the annotated type (decision 370 (2)).");
        }
    }

    // Splice each decorator parameter's argument, then each local of the
    // body the member reads as the literal of the value the body handed
    // (decision 575 (4), the tree rule).
    const captured = try memberFn.capturedLocals(env.arena, dfn, func);
    const handed: []const std.json.Value = if (c.data) |d| (if (d == .array) d.array.items else &.{}) else &.{};
    // Decision 716 (3) — the handle is the annotated type as code.
    const splices = try env.arena.alloc(memberFn.Splice, values.len + captured.len + 1);
    for (values, 0..) |v, j| splices[j] = .{ .param = sig.params[j].name, .lexeme = try splicedArgLexeme(env, dfn, sig.params[j], v.lexeme, local) };
    splices[values.len + captured.len] = .{ .param = declName, .lexeme = target };
    for (captured, 0..) |n, k| {
        const v: std.json.Value = if (k < handed.len) handed[k] else .null;
        const lit = (try memberFn.literalSource(env.arena, v)) orelse {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]`'s member `{s}` reads `{s}`, a local of the decorator's body whose value is no literal", .{ diagnostics.decorator_member_local_not_literal, a.name, c.name, n });
            return localNotLiteral(env, a, sig, func, local, n, msg, "A member holds a local of the decorator's body as a literal: a string, a number, a `bool`, `null` or an array of those (decisions 575 (4), 759).");
        };
        splices[values.len + k] = .{ .param = n, .lexeme = lit };
    }

    // Decision 384 — a decorator of another module: each name its member
    // writes beyond the parameters resolves where the decorator wrote it.
    const renames: []const memberFn.Rename = if (local) &.{} else try memberRenames(env, a, dfn, c, func, splices, typeArgs);
    return memberFn.render(env.arena, c.name, func, splices, typeArgs, target, renames) catch return error.OutOfMemory;
}

/// Decision 669 — the `print` / `panic` a member `owner` hands on as text
/// reads, as `owner`'s std imports bind them (`Reflection.stdCalls`): an item
/// called bare, a namespace a call is made through.
fn sourceMemberStdCalls(env: *Env, owner: []const u8, func: ast.FunctionExpr) InferError![]const stdCallsMod.Item {
    const r = env.reflection orelse return &.{};
    var out: std.ArrayListUnmanaged(stdCallsMod.Item) = .empty;
    next: for (try memberFn.freeNames(env.arena, func)) |n| {
        for (out.items) |done| if (std.mem.eql(u8, done.local, n.name)) continue :next;
        const it = r.stdCalls.get(try reflectionMod.Reflection.scopeKey(env.arena, owner, n.name)) orelse continue;
        try out.append(env.arena, it);
    }
    return out.items;
}

/// Decision 575 (3) — the source `compiler.init(f)` gives the annotated
/// declaration's module: the body's `c.index`-th executor
/// (`member_fn.collectExecutors`) as a function, each decorator parameter it
/// reads replaced by the argument as the annotation wrote it, each local of
/// the body it reads by the literal of the value the body handed (the tree
/// rule, 575 (4)), each type parameter by what the annotation bound it to, and
/// — for a decorator declared in another module — every other name renamed to
/// resolve in the decorator's module (decision 384); then the module-level
/// `val` that runs it with the module's body.
fn executorSource(
    env: *Env,
    a: ast.Annotation,
    dfn: ast.FnDecl,
    sig: envMod.DecoratorSig,
    values: []const envMod.DecoratorArgValue,
    c: decoratorEval.Contribution,
    local: bool,
    /// Decision 581 (2) — what the handle is in the executor: the annotated
    /// declaration itself, spliced as code bound to it (decision 613) — its
    /// name, or a member's owner path (`Users.make`).
    annotated: []const u8,
) InferError![]const u8 {
    const declName = memberFn.declParamName(dfn) orelse return decoratorError(env, a, "the decorator has no `@Decl` handle", "");
    const fns = try memberFn.collectExecutors(env.arena, dfn, declName);
    if (c.index >= fns.len) return decoratorError(env, a, "the decorator evaluator handed back an executor the body does not write", "Report it: `compiler.init(f)` numbers the body's executors in source order.");
    const func = fns[c.index];
    // A decorator of this module runs before its body is checked.
    if (local) try refuseCaptures(env, func, dfn.params, dfn.body, true, true);
    const typeArgs: []const memberFn.TypeArg = (if (a.loc) |l| env.decoratorTypeArgs.get(l) else null) orelse &.{};
    const captured = try memberFn.capturedLocals(env.arena, dfn, func);
    const handed: []const std.json.Value = if (c.data) |d| (if (d == .array) d.array.items else &.{}) else &.{};
    const splices = try env.arena.alloc(memberFn.Splice, values.len + captured.len + 1);
    for (values, 0..) |v, j| splices[j] = .{ .param = sig.params[j].name, .lexeme = try splicedArgLexeme(env, dfn, sig.params[j], v.lexeme, local) };
    splices[values.len + captured.len] = .{ .param = declName, .lexeme = annotated };
    for (captured, 0..) |n, k| {
        const v: std.json.Value = if (k < handed.len) handed[k] else .null;
        // Decision 787 — a `Module` (or a `Refused`) a `compiler.load` read
        // of the body answered: the record's constructor, under the names
        // the module's load helper imports (`load.withLoadHelper`).
        const lit = (try memberFn.literalSource(env.arena, v)) orelse (try loadMod.recordSource(env.arena, v)) orelse {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]`'s executor reads `{s}`, a local of the decorator's body whose value is no literal", .{ diagnostics.decorator_member_local_not_literal, a.name, n });
            return localNotLiteral(env, a, sig, func, local, n, msg, "An executor holds a local of the decorator's body as a literal: a string, a number, a `bool`, `null` or an array of those (decisions 575 (4), 759).");
        };
        splices[values.len + k] = .{ .param = n, .lexeme = lit };
    }
    try refuseExecutorRuns(env, func, captured, handed);
    const renames: []const memberFn.Rename = if (local) &.{} else try memberRenames(env, a, dfn, c, func, splices, typeArgs);
    // The executor written as a function of no parameter answering nothing:
    // `fn() -> void { … }` (decision 622 — every function writes its return
    // type; a body answering nothing already refused a valued tail).
    var asFn = func;
    asFn.kind.syntax = .fnExpr;
    asFn.kind.params = &.{};
    asFn.kind.paramTypes = &.{};
    asFn.kind.returnType = .{ .named = "void" };
    const k = env.contributions.items.len;
    const name = try std.fmt.allocPrint(env.arena, "__bp_executor_{d}", .{k});
    const rendered = memberFn.render(env.arena, name, asFn, splices, typeArgs, "", renames) catch return error.OutOfMemory;
    const text = if (std.mem.startsWith(u8, rendered, "pub ")) rendered["pub ".len..] else rendered;
    return std.fmt.allocPrint(env.arena, "{s}\nval __bp_init_{d} = {s}();", .{ text, k, name });
}

/// Decisions 310, 603 — an argument of a decorator declared in another module,
/// spliced into this module: a variant written by its leading dot (`.Manual`,
/// or a default `.Eager`) against an enum parameter is a variant of the enum the
/// decorator's module names, never of a same-named type this module declares
/// or another module holds. It is spelled through the alias that names that
/// enum here (`Env.hygieneImports`), as a member's own type names are
/// (`memberRenames`).
fn splicedArgLexeme(env: *Env, dfn: ast.FnDecl, p: ast.Param, lexeme: []const u8, local: bool) InferError![]const u8 {
    if (local) return lexeme;
    const written = std.mem.trim(u8, lexeme, " ");
    if (written.len < 2 or written[0] != '.' or !(std.ascii.isAlphabetic(written[1]) or written[1] == '_')) return lexeme;
    const ref: ast.TypeRef = switch (p.typeRef) {
        .optional => |o| o.*,
        else => p.typeRef,
    };
    if (ref != .named) return lexeme;
    const r = env.reflection orelse return lexeme;
    const w = (try r.written(env.arena, env.comptimeOwnerOf(dfn), ref.named)) orelse return lexeme;
    if (!w.isType or w.namespace != .none) return lexeme;
    const td = typeDeclAt(env, &.{}, w.module, w.name) orelse return lexeme;
    if (td.shape != .enum_) return lexeme;
    if (writtenNames.renamedAliasOf(env, w.module, w.name)) |al| return std.mem.concat(env.arena, u8, &.{ al, written }) catch error.OutOfMemory;
    const alias = try writtenNames.typeAliasOf(env.arena, w.module, w.name);
    try env.hygieneImports.append(env.arena, .{ .alias = alias, .module = w.module, .name = w.name, .isType = true });
    return std.mem.concat(env.arena, u8, &.{ alias, written }) catch error.OutOfMemory;
}

/// Decision 384 — the names a member of a decorator declared in another
/// module writes, each renamed to the alias of what it resolves to in the
/// decorator's module (`written_names.zig`, `Reflection.scopes`): a value
/// bound by this module's re-analysis, a type imported by it under the alias
/// (`Env.hygieneImports`). The parameters, the member's own locals and the
/// decorator's type parameters are left alone, as is a name the decorator's
/// module neither declares nor imports (a builtin, a prelude name). A type
/// this module already holds under the same name from elsewhere is two types
/// (decisions 310, 603): the member names the hygiene alias, never the name.
fn memberRenames(
    env: *Env,
    a: ast.Annotation,
    dfn: ast.FnDecl,
    c: decoratorEval.Contribution,
    func: ast.FunctionExpr,
    splices: []const memberFn.Splice,
    typeArgs: []const memberFn.TypeArg,
) InferError![]const memberFn.Rename {
    _ = a;
    _ = c;
    const r = env.reflection orelse return &.{};
    const owner = env.comptimeOwnerOf(dfn);
    var out: std.ArrayListUnmanaged(memberFn.Rename) = .empty;
    var names: std.ArrayListUnmanaged([]const u8) = .empty;
    for (try memberFn.freeNames(env.arena, func)) |n| try names.append(env.arena, n.name);
    for (try memberFn.typeNames(env.arena, func)) |n| {
        if (!isPrimitiveTypeName(n) and !std.mem.eql(u8, n, "Self")) try names.append(env.arena, n);
    }
    next: for (names.items) |n| {
        for (splices) |sp| if (std.mem.eql(u8, sp.param, n)) continue :next;
        for (typeArgs) |ta| if (std.mem.eql(u8, ta.name, n)) continue :next;
        for (out.items) |done| if (std.mem.eql(u8, done.from, n)) continue :next;
        const w = (try r.written(env.arena, owner, n)) orelse continue;
        if (w.namespace != .none) continue;
        // Decision 310 — a type this module holds under an alias is named by it.
        if (w.isType) if (writtenNames.renamedAliasOf(env, w.module, w.name)) |al| {
            try out.append(env.arena, .{ .from = n, .to = al });
            continue;
        };
        const alias = if (w.isType) try writtenNames.typeAliasOf(env.arena, w.module, w.name) else try envMod.templateAlias(env.arena, w.module, w.name);
        try out.append(env.arena, .{ .from = n, .to = alias });
        try env.hygieneImports.append(env.arena, .{ .alias = alias, .module = w.module, .name = w.name, .isType = w.isType });
    }
    return out.items;
}

// ── decision 298 — typed meta, keyed by its type; 370 (1) its `@Expr` fields ─

/// The type declaration `name` of `module` as this analysis sees it: the
/// module's own declarations, else what the registry holds for `module`.
fn typeDeclAt(env: *Env, own: []const ast.DeclKind, module: []const u8, name: []const u8) ?ast.TypeDecl {
    if (std.mem.eql(u8, module, env.modulePath)) {
        for (own) |d| switch (d) {
            .type_ => |t| if (std.mem.eql(u8, t.name, name)) return t,
            else => {},
        };
        return null;
    }
    const registry = env.typeDeclRegistry orelse return null;
    const decls = registry.get(module) orelse return null;
    const d = decls.get(name) orelse return null;
    return if (d == .type_) d.type_ else null;
}

/// The record type a typed meta value's constructor names, resolved in this
/// module: its own type, an imported one (an alias answers the declaration),
/// or `ns.Name` through a namespace import.
fn metaCtorTarget(env: *Env, own: []const ast.DeclKind, ctor: typedMeta.Ctor) ?struct { module: []const u8, decl: ast.TypeDecl } {
    if (ctor.namespace) |ns| {
        const path = env.namespaces.paths.get(ns) orelse return null;
        const d = typeDeclAt(env, own, path, ctor.name) orelse return null;
        return .{ .module = path, .decl = d };
    }
    if (typeDeclAt(env, own, env.modulePath, ctor.name)) |d| return .{ .module = env.modulePath, .decl = d };
    const o = env.importOwners.get(ctor.name) orelse return null;
    const d = typeDeclAt(env, own, o.owner, o.name) orelse return null;
    return .{ .module = o.owner, .decl = d };
}

/// What a field of a meta record declared in `module` holds, or null when
/// the compiler cannot rebuild it where the meta is read
/// (`decorator-meta-field-type`).
fn metaFieldShape(env: *Env, own: []const ast.DeclKind, module: []const u8, tr: ast.TypeRef) InferError!?typedMeta.Shape {
    switch (tr) {
        .named => |n| {
            if (typedMeta.primitiveShape(n)) |s| return s;
            const d = typeDeclAt(env, own, module, n) orelse return null;
            if (d.isRecord() or d.variants().len == 0 or d.sections().len > 0 or d.genericParams.len > 0) return null;
            for (d.variants()) |v| if (v.fields.len > 0 or v.numeric) return null;
            return .variant;
        },
        .array => |inner| {
            const s = (try metaFieldShape(env, own, module, inner.*)) orelse return null;
            const p = try env.arena.create(typedMeta.Shape);
            p.* = s;
            return .{ .array = p };
        },
        .generic => |g| {
            // Decision 308 — a `Type.Field<T>`, rebuilt as its `.name`.
            if (!g.is_builtin and g.args.len == 1 and (std.mem.eql(u8, g.name, "Type__Field") or std.mem.eql(u8, g.name, "Type.Field"))) return .field_key;
            if (g.is_builtin or !std.mem.eql(u8, g.name, "array") or g.args.len != 1) return null;
            const s = (try metaFieldShape(env, own, module, g.args[0])) orelse return null;
            const p = try env.arena.create(typedMeta.Shape);
            p.* = s;
            return .{ .array = p };
        },
        .tuple_ => |elems| {
            const shapes = try env.arena.alloc(typedMeta.Shape, elems.len);
            for (elems, 0..) |e, i| shapes[i] = (try metaFieldShape(env, own, module, e)) orelse return null;
            return .{ .tuple = shapes };
        },
        .optional => |inner| {
            const s = (try metaFieldShape(env, own, module, inner.*)) orelse return null;
            if (s == .optional) return null;
            const p = try env.arena.create(typedMeta.Shape);
            p.* = s;
            return .{ .optional = p };
        },
        else => return null,
    }
}

/// Decision 298 — every typed meta call of each decorator this module
/// declares, checked where it is written and its record type recorded for
/// the annotations that run it (`Reflection.decoratorMetaTypes`): the value
/// is a record type's constructor written at the call
/// (`decorator-meta-not-record`), each field of it data the compiler rebuilds
/// where the meta is read or an `@Expr<T>` (`decorator-meta-field-type`), and
/// an `@Expr<T>` field given one of the decorator's `comptime x: @Expr<T>`
/// parameters as it is — such a parameter given to no other field
/// (`decorator-meta-expr-arg`, 370 (1)).
fn checkTypedMetaCalls(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| {
        if (decl != .@"fn") continue;
        const f = decl.@"fn";
        if (f.body.len == 0) continue;
        const declName = memberFn.declParamName(f) orelse continue;
        const calls = try typedMeta.collect(env.arena, f, declName);
        if (calls.len == 0) continue;
        const types = try env.arena.alloc(reflectionMod.MetaCallType, calls.len);
        for (calls, 0..) |call, k| {
            const verb = if (call.repeat) typedMeta.add_meta else typedMeta.set_meta;
            const ctor = typedMeta.ctorOf(call.value.*) orelse {
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `decl.{s}(…)` records a value of a record type, written as its constructor at the call", .{ diagnostics.decorator_meta_not_record, verb });
                env.lastError = TypeError.custom(msg, "The type is the meta's key (decision 298): `decl.setMeta(Entity(table: t.value))`, read `@typeInfo(X).meta(Entity)`.").withLoc(call.value.getLoc());
                return error.TypeError;
            };
            const target = metaCtorTarget(env, program.decls, ctor) orelse {
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `decl.{s}({s}(…))` names no record type of this module or its imports", .{ diagnostics.decorator_meta_not_record, verb, ctor.name });
                env.lastError = TypeError.custom(msg, "A meta value is a record — `type Entity(table: string)` — declared here or imported.").withLoc(call.value.getLoc());
                return error.TypeError;
            };
            if (!target.decl.isRecord()) {
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `decl.{s}({s}(…))` names a type that is not a record", .{ diagnostics.decorator_meta_not_record, verb, ctor.name });
                env.lastError = TypeError.custom(msg, "A meta value is a record — `type Entity(table: string)`.").withLoc(call.value.getLoc());
                return error.TypeError;
            }
            const fields = target.decl.recordFields();
            // Decision 575 (4), the tree rule — a field written `f: T` holds a
            // tree when the decorator fills it with an `expr` parameter: the
            // field is then what an `@Expr<T>` field was (370 (1)).
            const treeFed = try env.arena.alloc(bool, fields.len);
            @memset(treeFed, false);
            for (ctor.args, 0..) |arg, i| {
                const fi: ?usize = if (arg.label) |lbl| for (fields, 0..) |fld, j| {
                    if (std.mem.eql(u8, fld.name, lbl)) break j;
                } else null else if (i < fields.len) i else null;
                const at = fi orelse continue;
                if (metaExprParam(f, arg.value.*)) |pn| for (f.params) |p| {
                    if (p.arrival == .syntax and std.mem.eql(u8, p.name, pn)) treeFed[at] = true;
                };
            }
            const shapes = try env.arena.alloc(typedMeta.FieldShape, fields.len);
            for (fields, 0..) |fld, i| {
                const shape: typedMeta.Shape = if (fld.exprWrapped or treeFed[i]) .expr else (try metaFieldShape(env, program.decls, target.module, fld.typeRef)) orelse {
                    const msg = try std.fmt.allocPrint(env.arena, "{s}: the field `{s}: {f}` of the meta record `{s}` holds no data the compiler rebuilds where the meta is read", .{ diagnostics.decorator_meta_field_type, fld.name, fld.typeRef, target.decl.name });
                    env.lastError = TypeError.custom(msg, "A meta field is a string, an integer, a float, a `bool`, a variant of an enum without payloads, a `Type.Field<T>`, an array, an optional or a tuple of those — or `@Expr<T>`, filled with a decorator parameter (decision 370 (1)).").withLoc(call.value.getLoc());
                    return error.TypeError;
                };
                shapes[i] = .{ .name = fld.name, .shape = shape };
            }
            // Each argument against its field: an `@Expr<T>` field takes a
            // parameter's `@Expr` as it is, and such a parameter goes nowhere else.
            for (ctor.args, 0..) |arg, i| {
                const fi: ?usize = if (arg.label) |lbl| for (fields, 0..) |fld, j| {
                    if (std.mem.eql(u8, fld.name, lbl)) break j;
                } else null else if (i < fields.len) i else null;
                const field = fields[fi orelse continue];
                const param = metaExprParam(f, arg.value.*);
                if (field.exprWrapped and param == null) {
                    const msg = try std.fmt.allocPrint(env.arena, "{s}: the field `{s}` of `{s}` is an `@Expr<{f}>`, filled with one of the decorator's `comptime x: @Expr<T>` parameters as it is", .{ diagnostics.decorator_meta_expr_arg, field.name, target.decl.name, field.typeRef });
                    env.lastError = TypeError.custom(msg, "Hand the parameter on — `Check(rule: rule)` —: the expression the annotation wrote is spliced where the meta is read (decision 370 (1)).").withLoc(arg.value.getLoc());
                    return error.TypeError;
                }
                if (!field.exprWrapped and param != null and !treeFed[fi.?]) {
                    const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is an `@Expr`, and the field `{s}` of `{s}` is a `{f}`", .{ diagnostics.decorator_meta_expr_arg, param.?, field.name, target.decl.name, field.typeRef });
                    env.lastError = TypeError.custom(msg, "Read the value known at build with `.value` (decision 364 (2)), or declare the field `@Expr<T>` to hand the expression on (decision 370 (1)).").withLoc(arg.value.getLoc());
                    return error.TypeError;
                }
            }
            types[k] = .{ .module = target.module, .name = target.decl.name, .isPub = target.decl.isPub, .fields = shapes };
        }
        const r = env.reflection orelse continue;
        try r.decoratorMetaTypes.put(r.arena, try reflectionMod.Reflection.decoratorKey(r.arena, env.modulePath, f.name), types);
    }
}

/// The name of `f`'s `comptime x: @Expr<T>` parameter `e` is, written bare;
/// null for anything else.
fn metaExprParam(f: ast.FnDecl, e: ast.Expr) ?[]const u8 {
    if (e != .identifier or e.identifier.kind != .ident) return null;
    const n = e.identifier.kind.ident;
    for (f.params[1..]) |p| if (p.exprWrapped and std.mem.eql(u8, p.name, n)) return n;
    return null;
}

/// The `@Decl` parameter of the body being inferred — a decorator's first, a
/// template annotation function's second (decision 311) —, null elsewhere.
fn currentDeclParam(env: *Env) ?[]const u8 {
    const ps = env.currentParams;
    if (env.inDecoratorFn and ps.len > 0 and isDecoratorParams(ps)) return ps[0].name;
    if (env.inTemplateFn and memberFn.isTemplateAnnotationParams(ps)) return ps[1].name;
    return null;
}

/// Whether `call` is `<declName>.setMeta(v)` / `<declName>.addMeta(v)`.
fn isTypedMetaOn(call: anytype, declName: []const u8) bool {
    if (call.is_builtin or call.args.len != 1 or call.trailing.len != 0) return false;
    if (!std.mem.eql(u8, call.callee, typedMeta.set_meta) and !std.mem.eql(u8, call.callee, typedMeta.add_meta)) return false;
    const r = call.receiver orelse return false;
    return r.* == .identifier and r.identifier.kind == .ident and std.mem.eql(u8, r.identifier.kind.ident, declName);
}

/// Decision 298 — `decl.setMeta(v)` / `decl.addMeta(v)` in a decorator's body:
/// `v` is typed as written, each `comptime x: @Expr<T>` parameter handed to
/// an `@Expr<T>` field read as its `T` (370 (1); `checkTypedMetaCalls` held
/// the shape where the decorator is declared).
fn inferTypedMetaCall(env: *Env, call: anytype, loc: ast.Loc) InferError!TypedExpr {
    const value = call.args[0].value.*;
    const ctor = typedMeta.ctorOf(value) orelse {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `decl.{s}(…)` records a value of a record type, written as its constructor at the call", .{ diagnostics.decorator_meta_not_record, call.callee });
        env.lastError = TypeError.custom(msg, "The type is the meta's key (decision 298): `decl.setMeta(Entity(table: t.value))`, read `@typeInfo(X).meta(Entity)`.").withLoc(value.getLoc());
        return error.TypeError;
    };
    const Rebound = struct { name: []const u8, was: *T.Type };
    var rebound: std.ArrayListUnmanaged(Rebound) = .empty;
    for (ctor.args) |arg| {
        if (arg.value.* != .identifier or arg.value.identifier.kind != .ident) continue;
        const n = arg.value.identifier.kind.ident;
        const p = for (env.currentParams) |p| {
            if (p.exprWrapped and std.mem.eql(u8, p.name, n)) break p;
        } else continue;
        const was = env.lookup(p.name) orelse continue;
        const d = was.deref();
        const inner = if (d.* == .named and std.mem.eql(u8, d.named.name, ast.expr_type_name) and d.named.args.len == 1) d.named.args[0] else continue;
        try rebound.append(env.arena, .{ .name = p.name, .was = was });
        try env.bind(p.name, inner);
    }
    const valueTyped = try env.arena.create(TypedExpr);
    valueTyped.* = blk: {
        defer for (rebound.items) |r| env.bind(r.name, r.was) catch {};
        break :blk try inferExprTyped(env, value);
    };
    const recv = try env.arena.create(TypedExpr);
    recv.* = try inferExprTyped(env, call.receiver.?.*);
    const typedArgs = try env.arena.alloc(ast.CallArgOf(.typed), 1);
    typedArgs[0] = .{ .label = call.args[0].label, .value = valueTyped };
    return TypedExpr{ .call = .{ .loc = loc, .type_ = try env.namedType("void"), .kind = .{ .call = .{
        .receiver = recv,
        .callee = call.callee,
        .is_builtin = false,
        .args = typedArgs,
        .trailing = &.{},
    } } } };
}

/// Decision 298 — record the value one typed meta call of `dfn`'s body built
/// (`c.index`, `c.data`) on the declaration `handle` names: written back as
/// its constructor's arguments, each `@Expr<T>` field as the annotation wrote
/// the argument (370 (1)). Refused at the annotation: a field's or a method's
/// decorator (`decorator-meta-on-member`), a second value of a type the
/// declaration holds once (`decorator-meta-twice`).
fn recordTypedMeta(
    env: *Env,
    a: ast.Annotation,
    dfn: ast.FnDecl,
    handle: decoratorEval.DeclHandle,
    values: []const envMod.DecoratorArgValue,
    c: decoratorEval.Contribution,
    memberOwner: ?[]const u8,
) InferError!void {
    const declName = memberFn.declParamName(dfn) orelse return decoratorError(env, a, "the decorator has no `@Decl` handle", "");
    const calls = try typedMeta.collect(env.arena, dfn, declName);
    const verb = if (c.index < calls.len and calls[c.index].repeat) typedMeta.add_meta else typedMeta.set_meta;
    // Question s29-b — a method's typed meta (313: a repository method's
    // query) is recorded for its owner's decorators, which run after it and
    // read it on `decl.methods` (`m.meta(T)`).
    if (std.mem.eql(u8, handle.kind, "Method")) if (memberOwner) |owner| {
        return recordMethodTypedMeta(env, a, dfn, handle, c, calls, owner);
    };
    const is_member = std.mem.eql(u8, handle.kind, "Field") or std.mem.eql(u8, handle.kind, "Method");
    if (is_member) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` on the {s} `{s}` calls `decl.{s}`, and meta describes a top-level declaration", .{ diagnostics.decorator_meta_on_member, a.name, if (std.mem.eql(u8, handle.kind, "Field")) "field" else "method", handle.name, verb });
        return decoratorError(env, a, msg, "`@typeInfo(X)` reflects a `type`, a `behavior`, a `fn` or a `val`; record the meta from a decorator on the declaration itself.");
    }
    const r = env.reflection orelse return;
    const owner = env.comptimeOwnerOf(dfn);
    const types = r.decoratorMetaTypes.get(try reflectionMod.Reflection.decoratorKey(env.arena, owner, dfn.name)) orelse &.{};
    if (c.index >= calls.len or c.index >= types.len or c.data == null)
        return decoratorError(env, a, "the decorator evaluator handed back a typed meta value the body does not record", "Report it: `decl.setMeta(v)` / `decl.addMeta(v)` are numbered in source order.");
    const mt = types[c.index];
    const lexemes = try env.arena.alloc([]const u8, values.len);
    for (values, 0..) |v, j| lexemes[j] = v.lexeme;
    var bad: []const u8 = "";
    const args = typedMeta.render(env.arena, mt.fields, c.data.?, lexemes, &bad) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        error.Mismatch => {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` records a `{s}` on `{s}` whose field `{s}` the compiler cannot write back", .{ diagnostics.decorator_meta_field_type, a.name, mt.name, handle.name, bad });
            return decoratorError(env, a, msg, "A meta field holds data known at build — a string, a number, a `bool`, a variant — or a decorator parameter's `@Expr` (decision 370 (1)).");
        },
    };
    const hasExpr = for (mt.fields) |fs| {
        if (fs.shape == .expr and c.data.?.object.get(fs.name) != null) break true;
    } else false;
    if (!try r.addTypedMeta(env.modulePath, handle.name, .{
        .typeModule = mt.module,
        .typeName = mt.name,
        .typePub = mt.isPub,
        .args = args,
        .repeat = c.index < calls.len and calls[c.index].repeat,
        .hasExpr = hasExpr,
        .annotationModule = env.modulePath,
        .decorator = dfn.name,
    })) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` records a second `{s}` on `{s}`, which holds one", .{ diagnostics.decorator_meta_twice, a.name, mt.name, handle.name });
        return decoratorError(env, a, msg, "`decl.setMeta(v)` stores one value of its type per declaration (decision 298); a value that repeats is recorded with `decl.addMeta(v)` — every one, never mixed with `setMeta` — and read with `metaAll(T)`.");
    }
}

/// Question s29-b — one typed meta value a method's decorator recorded, kept
/// for the owner's decorators (`Env.methodTypedMeta`) as the term their body
/// reads: one value of a type per method (`decorator-meta-twice`), a type
/// recorded by `setMeta` or by `addMeta`, never both.
fn recordMethodTypedMeta(
    env: *Env,
    a: ast.Annotation,
    dfn: ast.FnDecl,
    handle: decoratorEval.DeclHandle,
    c: decoratorEval.Contribution,
    calls: []const typedMeta.Call,
    owner: []const u8,
) InferError!void {
    const r = env.reflection orelse return;
    const types = r.decoratorMetaTypes.get(try reflectionMod.Reflection.decoratorKey(env.arena, env.comptimeOwnerOf(dfn), dfn.name)) orelse &.{};
    if (c.index >= calls.len or c.index >= types.len or c.data == null)
        return decoratorError(env, a, "the decorator evaluator handed back a typed meta value the body does not record", "Report it: `decl.setMeta(v)` / `decl.addMeta(v)` are numbered in source order.");
    const mt = types[c.index];
    const repeat = calls[c.index].repeat;
    for (env.methodTypedMeta.items) |m| {
        if (!std.mem.eql(u8, m.owner, owner) or !std.mem.eql(u8, m.method, handle.name) or !std.mem.eql(u8, m.typeName, mt.name)) continue;
        if (repeat and m.repeat) continue;
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` records a second `{s}` on `{s}.{s}`, which holds one", .{ diagnostics.decorator_meta_twice, a.name, mt.name, owner, handle.name });
        return decoratorError(env, a, msg, "`decl.setMeta(v)` stores one value of its type per declaration (decision 298); a value that repeats is recorded with `decl.addMeta(v)` — every one, never mixed with `setMeta` — and read with `metaAll(T)`.");
    }
    try env.methodTypedMeta.append(env.arena, .{
        .owner = owner,
        .method = handle.name,
        .typeName = mt.name,
        .repeat = repeat,
        .value = try decoratorEval.metaValueTerm(env.arena, mt.fields, c.data.?),
    });
}

/// `handle` with the typed meta its methods recorded (question s29-b), for a
/// type's or a behavior's own decorators; `handle` itself otherwise.
fn withMethodMeta(env: *Env, handle: decoratorEval.DeclHandle, owner: ?[]const u8) InferError!decoratorEval.DeclHandle {
    if (handle.methods.len == 0 or env.methodTypedMeta.items.len == 0) return handle;
    if (!std.mem.eql(u8, handle.kind, "Type") and !std.mem.eql(u8, handle.kind, "Behavior")) return handle;
    const o = owner orelse return handle;
    var found: std.ArrayListUnmanaged(decoratorEval.MethodMeta) = .empty;
    for (env.methodTypedMeta.items) |m| {
        if (!std.mem.eql(u8, m.owner, o)) continue;
        try found.append(env.arena, .{ .method = m.method, .typeName = m.typeName, .value = m.value });
    }
    var out = handle;
    out.methodMeta = found.items;
    return out;
}

/// The record type a typed meta read names (`meta(Entity)`, `meta(orm.Entity)`):
/// its identity and a fresh instance of its type.
const MetaReadType = struct { module: []const u8, name: []const u8, spelled: []const u8, instance: *T.Type, generic: bool };

fn metaReadType(env: *Env, call: anytype, loc: ast.Loc) InferError!MetaReadType {
    const fail = struct {
        fn at(e: *Env, l: ast.Loc, callee: []const u8) InferError {
            const msg = std.fmt.allocPrint(e.arena, "{s}: `{s}(T)` takes one record type of this module or its imports — `{s}(Entity)`, `{s}(orm.Entity)`", .{ diagnostics.typeinfo_meta_type, callee, callee, callee }) catch return error.OutOfMemory;
            e.lastError = TypeError.custom(msg, "The meta's key is its record type (decision 298).").withLoc(l);
            return error.TypeError;
        }
    }.at;
    if (call.args.len != 1 or call.trailing.len != 0 or call.args[0].label != null) return fail(env, loc, call.callee);
    const arg = call.args[0].value.*;
    const target = reflectedDecl(env, arg) orelse return fail(env, arg.getLoc(), call.callee);
    const d = typeDeclAt(env, env.moduleDecls, target.module, target.name) orelse return fail(env, arg.getLoc(), call.callee);
    if (!d.isRecord()) return fail(env, arg.getLoc(), call.callee);
    const ctorType: ?*T.Type = switch (arg.identifier.kind) {
        .ident => |n| env.lookup(n) orelse env.typeOnlyCtors.get(n),
        .identAccess => |ia| blk: {
            const ns = ia.receiver.identifier.kind.ident;
            const exports = env.namespaces.modules.getPtr(ns) orelse break :blk null;
            const exported = exports.get(ia.member) orelse break :blk null;
            // Decision 310 — renamed as a namespace call's signature is.
            break :blk if (env.namespaces.paths.get(ns)) |path| try renameImportedType(env, exported, path) else exported;
        },
        else => null,
    };
    const ct = ctorType orelse return fail(env, arg.getLoc(), call.callee);
    var seen = std.AutoHashMap(*T.TypeCell, *T.Type).init(env.arena);
    defer seen.deinit();
    const inst = try instantiateType(env, ct, &seen, .allVars);
    const instance = if (inst.deref().* == .func) inst.deref().func.ret else return fail(env, arg.getLoc(), call.callee);
    const spelled = switch (arg.identifier.kind) {
        .ident => |n| n,
        .identAccess => |ia| try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ ia.receiver.identifier.kind.ident, ia.member }),
        else => unreachable,
    };
    return .{ .module = target.module, .name = target.name, .spelled = spelled, .instance = instance, .generic = d.genericParams.len > 0 };
}

/// A typed meta read's answer parsed on a line of its own past the module's
/// (`Env.typedMetaLines`).
fn typedMetaRewrite(env: *Env, text: []const u8) InferError!*ast.Expr {
    if (env.typedMetaLines == 0) env.typedMetaLines = typed_meta_first_line;
    const line = env.typedMetaLines;
    env.typedMetaLines += 1;
    const prefix = "val __bp_tm = ";
    const src = try std.fmt.allocPrint(env.arena, "{s}{s};", .{ prefix, text });
    var lx = Lexer.init(src);
    const tokens = env.arena.dupe(lexerMod.Token, lx.scanAll(env.arena) catch return error.OutOfMemory) catch return error.OutOfMemory;
    for (tokens) |*t| t.line += line;
    var p = Parser.init(tokens);
    const parsed = p.parse(env.arena) catch return error.OutOfMemory;
    if (parsed.decls.len != 1 or parsed.decls[0] != .val) return error.OutOfMemory;
    const node = try env.arena.create(ast.Expr);
    node.* = parsed.decls[0].val.value.*;
    return node;
}

/// Where typed meta answers start: past any module's own lines.
const typed_meta_first_line: usize = 1_000_000;

/// Decision 298 — `@typeInfo(X).meta(T)` → `?T`, `@typeInfo(X).metaAll(T)` →
/// `T[]`: the values the declaration's decorators recorded of the record type
/// `T`, answered at compile time — the constructors written back in the
/// read's place (`[T(…)].first()`, `[T(…), …]`) and typed here, in this
/// module, so an `@Expr<T>` field's expression (370 (1)) is checked and run
/// where it was written. Refused at the read: `T` naming no record type
/// (`typeinfo-meta-type`), `meta(T)` over several values
/// (`typeinfo-meta-several`), and a declaration of this module a `.hooks`
/// reader annotates, before it ran (`typeinfo-meta-hooks-pending`). A value
/// with `@Expr` fields read in another module than the annotation's has each
/// name the annotation wrote bound where it was written (decision 385,
/// `written_names.zig`). In a member a decorator hands on, `@typeInfo(T)` of
/// the decorator's type parameter is the read's type alone (decision 395 (1),
/// `typedMetaReadOfTypeParam`).
fn inferTypedMetaRead(env: *Env, call: anytype, loc: ast.Loc) InferError!TypedExpr {
    const one = std.mem.eql(u8, call.callee, "meta");
    const info = call.receiver.?.call.kind.call;
    if (info.args.len != 1 or info.trailing.len != 0) {
        env.lastError = TypeError.custom(diagnostics.typeinfo_unknown_declaration ++ ": `@typeInfo` takes one declaration — `@typeInfo(City)`, `@typeInfo(models.City)`", null).withLoc(call.receiver.?.call.loc);
        return error.TypeError;
    }
    if (try typedMetaReadOfTypeParam(env, call, info.args[0].value.*, loc, one)) |typed| return typed;
    const target = reflectedDecl(env, info.args[0].value.*) orelse {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `@typeInfo` reflects a declaration this module declares or imports, and this names none", .{diagnostics.typeinfo_unknown_declaration});
        env.lastError = TypeError.custom(msg, "Name a `type`, `behavior` or `fn` of this module, an imported one, or one through a namespace import (`models.City`).").withLoc(info.args[0].value.getLoc());
        return error.TypeError;
    };
    const mt = try metaReadType(env, call, loc);

    var found: std.ArrayListUnmanaged(reflectionMod.TypedMetaEntry) = .empty;
    if (env.reflection) |r| if (env.templateEval != null) {
        if (!env.hooksReadersRan and std.mem.eql(u8, target.module, env.modulePath)) {
            var it = env.hooksReaders.keyIterator();
            while (it.next()) |k| {
                if (!std.mem.startsWith(u8, k.*, target.name) or k.len <= target.name.len or k.*[target.name.len] != 0) continue;
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` carries a decorator that reads `.hooks`, which records its meta after this read", .{ diagnostics.typeinfo_meta_hooks_pending, target.name });
                env.lastError = TypeError.custom(msg, "A typed meta read of a declaration a `.hooks` reader annotates is answered in another module (decision 372 runs such a decorator after the module's bodies); question `130-s8-c`.").withLoc(loc);
                return error.TypeError;
            }
        }
        for (try r.typedMetaOf(env.arena, target.module, target.name)) |e| {
            if (std.mem.eql(u8, e.typeModule, mt.module) and std.mem.eql(u8, e.typeName, mt.name)) try found.append(env.arena, e);
        }
    };
    if (one and found.items.len > 1) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` holds {d} `{s}` values, and `meta({s})` answers one", .{ diagnostics.typeinfo_meta_several, target.name, found.items.len, mt.name, mt.spelled });
        env.lastError = TypeError.custom(msg, "Read every one with `metaAll(T)`; `decl.addMeta(v)` records a value that repeats (decision 298).").withLoc(loc);
        return error.TypeError;
    }
    // A generic meta record holding a `Type.Field<P>` of its one parameter
    // (`Sort<T>(by: Type.Field<T>)`): the key is the annotated declaration's
    // field, so the constructor is spelled with it (`Sort<Book>(by: .pages)`)
    // and `.pages` resolves against `Book` (decision 308).
    const ctor = if (try fieldKeyOwnerParam(env, mt.module, mt.name)) blk: {
        const arg = info.args[0].value.*;
        const shown = switch (arg.identifier.kind) {
            .ident => |n| n,
            .identAccess => |ia| if (ia.receiver.* == .identifier and ia.receiver.identifier.kind == .ident)
                try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ ia.receiver.identifier.kind.ident, ia.member })
            else
                break :blk mt.spelled,
            else => break :blk mt.spelled,
        };
        break :blk try std.fmt.allocPrint(env.arena, "{s}<{s}>", .{ mt.spelled, shown });
    } else mt.spelled;
    var text: std.ArrayListUnmanaged(u8) = .empty;
    try text.append(env.arena, '[');
    for (found.items, 0..) |e, i| {
        // Decision 385 — the annotation's names resolve where it wrote them.
        var renamed: usize = 0;
        const args = if (e.hasExpr and !std.mem.eql(u8, e.annotationModule, env.modulePath))
            try writtenNames.renameArgs(env.arena, e.args, writtenNames.Binder{ .env = env, .module = e.annotationModule, .renamed = &renamed }, &renamed)
        else
            e.args;
        if (i > 0) try text.appendSlice(env.arena, ", ");
        try text.print(env.arena, "{s}{s}", .{ ctor, args });
    }
    try text.append(env.arena, ']');
    if (one) try text.appendSlice(env.arena, ".first()");
    const rewrite = try typedMetaRewrite(env, text.items);
    try env.srcRewrites.put(loc, rewrite);
    const typed = try inferExprTyped(env, rewrite.*);
    const want = try env.namedTypeArgs(if (one) "optional" else "array", &.{mt.instance});
    try unifyAt(env, want, typed.getType(), loc);
    return typed;
}

/// Decision 631 — `typeName` and `annotations` are a `Type.Field<T>`'s build
/// members: read in a decorator's, a template's or the compiler's body, and
/// refused in a run-time body, where a field holds its owner and its name
/// alone (`Field(Book, "pages")`).
fn refuseFieldBuildMember(env: *Env, record: []const u8, member: []const u8, loc: ast.Loc) InferError!void {
    if (!std.mem.eql(u8, record, field_key_type_name)) return;
    if (!std.mem.eql(u8, member, "typeName") and !std.mem.eql(u8, member, "annotations")) return;
    if (env.inDecoratorFn or env.inTemplateFn or env.compilerBodies or env.inStd) return;
    const msg = try std.fmt.allocPrint(env.arena, "`{s}` is a build member of `Field`", .{member});
    env.lastError = TypeError.custom(msg, "A field crosses to run time as `Field(Owner, \"name\")`, its owner and its name (decision 631); read its type and its annotations at build, in a decorator's body.").withLoc(loc);
    return error.TypeError;
}

/// Decision 631 — a `.name` against a `Type.Field<T>` in the answer of a
/// typed meta read (the lines from `typed_meta_first_line` on): the field's
/// run-time form `Type__Field(T, "name")`, its constructor over the owner and
/// the name, the owner crossing to run time as the type's identity (decision
/// 758, `Env.runtimeTokenArgs`). Recorded in `Env.srcRewrites` under the
/// `.name`'s loc, which the transform swaps whole. A `.name` written in a
/// run-time body is no field: there is no run-time key (decision 599 (1)).
fn inferFieldRunTimeForm(env: *Env, name: []const u8, loc: ast.Loc) InferError!?TypedExpr {
    if (loc.line < typed_meta_first_line) return null;
    const exp = env.expectedType orelse return null;
    const d = (optionalInner(exp) orelse exp).deref();
    if (d.* != .named or !std.mem.eql(u8, d.named.name, field_key_type_name) or d.named.args.len != 1) return null;
    const t = d.named.args[0].deref();
    if (t.* != .named) return null;
    const owner = t.named.name;
    const fields = recordFieldNames(env, owner) orelse return null;
    for (fields) |f| {
        if (std.mem.eql(u8, f.name, name)) break;
    } else {
        env.lastError = TypeError.unknownField(owner, name).withLoc(loc);
        return error.TypeError;
    }
    const at = struct {
        fn of(l: ast.Loc, k: usize) ast.Loc {
            return .{ .line = l.line, .col = l.col + ast.field_form_synthetic_col + k, .expansion = l.expansion };
        }
    }.of;
    const ownerExpr = try env.arena.create(ast.Expr);
    ownerExpr.* = .{ .identifier = .{ .loc = at(loc, 1), .kind = .{ .ident = owner } } };
    const nameExpr = try env.arena.create(ast.Expr);
    nameExpr.* = .{ .literal = .{ .loc = at(loc, 2), .kind = .{ .stringLit = name } } };
    const args = try env.arena.alloc(ast.CallArg, 2);
    args[0] = .{ .label = null, .value = ownerExpr };
    args[1] = .{ .label = null, .value = nameExpr };
    const rewrite = try env.arena.create(ast.Expr);
    rewrite.* = .{ .call = .{ .loc = at(loc, 0), .kind = .{ .call = .{
        .receiver = null,
        .callee = field_key_type_name,
        .is_builtin = false,
        .args = args,
        .trailing = &.{},
    } } } };
    try env.runtimeTokenArgs.put(env.arena, ownerExpr.getLoc(), {});
    const prevExpected = env.expectedType;
    env.expectedType = null;
    defer env.expectedType = prevExpected;
    const typed = try inferExprTyped(env, rewrite.*);
    try unifyAt(env, try env.namedTypeArgs(field_key_type_name, &.{try env.namedType(owner)}), typed.getType(), loc);
    try env.srcRewrites.put(loc, rewrite);
    return typed;
}

/// Whether the meta record `name` of `module` has one type parameter and a
/// field holding a `Type.Field` of it (directly, in an array or an optional).
fn fieldKeyOwnerParam(env: *Env, module: []const u8, name: []const u8) InferError!bool {
    const d = typeDeclAt(env, env.moduleDecls, module, name) orelse return false;
    if (d.genericParams.len != 1 or !d.isRecord()) return false;
    const p = d.genericParams[0].name;
    for (d.recordFields()) |f| if (mentionsFieldKeyOf(f.typeRef, p)) return true;
    return false;
}

fn mentionsFieldKeyOf(tr: ast.TypeRef, param: []const u8) bool {
    return switch (tr) {
        .generic => |g| blk: {
            if (g.args.len == 1 and (std.mem.eql(u8, g.name, "Type__Field") or std.mem.eql(u8, g.name, "Type.Field")))
                break :blk g.args[0] == .named and std.mem.eql(u8, g.args[0].named, param);
            for (g.args) |a| if (mentionsFieldKeyOf(a, param)) break :blk true;
            break :blk false;
        },
        .array => |inner| mentionsFieldKeyOf(inner.*, param),
        .optional => |inner| mentionsFieldKeyOf(inner.*, param),
        else => false,
    };
}

/// `@typeInfo(X).meta(T)` / `.metaAll(T)` (decision 298).
fn isTypedMetaRead(e: ast.Expr) bool {
    if (e != .call or e.call.kind != .call) return false;
    const call = e.call.kind.call;
    if (call.is_builtin or call.calleeExpr != null) return false;
    if (!std.mem.eql(u8, call.callee, "meta") and !std.mem.eql(u8, call.callee, "metaAll")) return false;
    const r = call.receiver orelse return false;
    return r.* == .call and r.call.kind == .call and r.call.kind.call.is_builtin and std.mem.eql(u8, r.call.kind.call.callee, "typeInfo");
}

/// Decision 395 (1) — `@typeInfo(T).meta(C)` / `.metaAll(C)` in a member a
/// decorator hands on (`Env.memberFnGenerics`), `T` a type parameter of the
/// decorator: typed as the read's type (`?C<…>` / `C<…>[]`) and answered
/// nowhere — the member runs only where it is rendered into the annotated
/// type's module, `T` spelled as the type (`member_fn.render`), where the read
/// is answered and the member checked again (395 (2)). Null for any other
/// read.
fn typedMetaReadOfTypeParam(env: *Env, call: anytype, arg: ast.Expr, loc: ast.Loc, one: bool) InferError!?TypedExpr {
    if (arg != .identifier or arg.identifier.kind != .ident) return null;
    const generics = env.memberFnGenerics orelse return null;
    if (!generics.contains(arg.identifier.kind.ident)) return null;
    const mt = try metaReadType(env, call, loc);
    const typed = try inferExprTyped(env, (try typedMetaRewrite(env, if (one) "[].first()" else "[]")).*);
    const want = try env.namedTypeArgs(if (one) "optional" else "array", &.{mt.instance});
    try unifyAt(env, want, typed.getType(), loc);
    return typed;
}

/// Decision 298 — `d.meta(T)` → `?T`, `d.metaAll(T)` → `T[]` on a
/// `@TypeInfo.all` entry: the values its decorators recorded of the record
/// type `T`, carried by the entry (`Declared.typedMeta`, one thunk per
/// value, keyed by the type's identity — `typeinfo_all.zig`) and read with
/// the module's `declared__metaAll__<T>` (`typed_meta.withMetaHelper`). Not in a decorator's or a template's
/// body: the entries are run-time data (`typeinfo-meta-at-build`).
fn inferDeclaredMetaRead(env: *Env, call: anytype, recv: *ast.TypedExpr, loc: ast.Loc) InferError!TypedExpr {
    _ = recv;
    if (env.inDecoratorFn or env.inTemplateFn) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}(T)` on a catalogue entry reads run-time data, and this body runs while the program compiles", .{ diagnostics.typeinfo_meta_at_build, call.callee });
        env.lastError = TypeError.custom(msg, "Read an entry's typed meta in the program; a decorator's or a template's body reads `@typeInfo(X).meta(T)` (decision 298).").withLoc(loc);
        return error.TypeError;
    }
    const one = std.mem.eql(u8, call.callee, "meta");
    const mt = try metaReadType(env, call, loc);
    if (mt.generic) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}({s})` on a catalogue entry names a generic record, whose type arguments this read cannot spell", .{ diagnostics.typeinfo_meta_type, call.callee, mt.spelled });
        env.lastError = TypeError.custom(msg, "Read a generic meta record with `@typeInfo(X).meta(T)` / `.metaAll(T)`; through a `@TypeInfo.all` entry is question `130-s8-d`.").withLoc(call.args[0].value.getLoc());
        return error.TypeError;
    }
    const key = try envMod.declIdentity(env.arena, mt.module, mt.name);
    const reader = try typedMeta.metaAllFnName(env.arena, mt.spelled);
    if (env.lookup(reader) == null) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}({s})` on a catalogue entry names a record type this module neither declares nor imports by that name", .{ diagnostics.typeinfo_meta_type, call.callee, mt.spelled });
        env.lastError = TypeError.custom(msg, "Import the meta record (`import {orm.Entity};`) or reach it through a namespace import (`orm.Entity`).").withLoc(call.args[0].value.getLoc());
        return error.TypeError;
    }
    // `declared__metaAll__<T>(<receiver>.typedMeta, "<key>")`, `.first()` for `meta`.
    const line = blk: {
        if (env.typedMetaLines == 0) env.typedMetaLines = typed_meta_first_line;
        defer env.typedMetaLines += 1;
        break :blk env.typedMetaLines;
    };
    const at = struct {
        fn l(ln: usize, col: usize) ast.Loc {
            return .{ .line = ln, .col = col };
        }
    }.l;
    const slots = try env.arena.create(ast.Expr);
    slots.* = .{ .identifier = .{ .loc = at(line, 1), .kind = .{ .identAccess = .{ .receiver = call.receiver.?, .member = declared_meta_slots_field } } } };
    const keyLit = try env.arena.create(ast.Expr);
    var keyText: std.ArrayListUnmanaged(u8) = .empty;
    try typedMeta.writeBpString(env.arena, &keyText, key);
    keyLit.* = .{ .literal = .{ .loc = at(line, 2), .kind = .{ .stringLit = keyText.items[1 .. keyText.items.len - 1] } } };
    const args = try env.arena.alloc(ast.CallArg, 2);
    args[0] = .{ .label = null, .value = slots };
    args[1] = .{ .label = null, .value = keyLit };
    var rewrite = try env.arena.create(ast.Expr);
    // The module's own reader of `T` (`typed_meta.withMetaHelper`).
    rewrite.* = .{ .call = .{ .loc = at(line, 3), .kind = .{ .call = .{
        .receiver = null,
        .callee = reader,
        .is_builtin = false,
        .args = args,
        .trailing = &.{},
    } } } };
    if (one) {
        const all = rewrite;
        rewrite = try env.arena.create(ast.Expr);
        rewrite.* = .{ .call = .{ .loc = at(line, 4), .kind = .{ .call = .{
            .receiver = all,
            .callee = "first",
            .is_builtin = false,
            .args = &.{},
            .trailing = &.{},
        } } } };
    }
    env.usesDeclared = true;
    try env.srcRewrites.put(loc, rewrite);
    const typed = try inferExprTyped(env, rewrite.*);
    const want = try env.namedTypeArgs(if (one) "optional" else "array", &.{mt.instance});
    try unifyAt(env, want, typed.getType(), loc);
    return typed;
}

/// The `Declared` field that carries an entry's typed meta and the record of
/// one value (`comptime.zig` `decl_reflection_src`).
pub const declared_meta_slots_field = "typedMeta";
pub const declared_meta_slot_type = "DeclaredTypedMeta";

/// Whether `t` is a `Declared<…>` (`@TypeInfo.all`'s entry).
fn isDeclaredType(t: *T.Type) bool {
    const d = t.deref();
    return d.* == .named and std.mem.eql(u8, d.named.name, "Declared");
}

/// Whether `t` is a `decl.methods` entry's type (`Decl.Method`,
/// `comptime.zig` `decl_reflection_src`).
fn isReflectedMethodType(t: *T.Type) bool {
    const d = t.deref();
    return d.* == .named and (std.mem.eql(u8, d.named.name, "__Decl__Method") or std.mem.eql(u8, d.named.name, "Method"));
}

/// Question s29-b — `m.meta(T)` / `m.metaAll(T)` on a `decl.methods` entry, in
/// a decorator's (or a template annotation's) body: `?T` / `T[]`, the typed
/// meta the method's decorators recorded (they run before the owner's), read
/// while the program compiles (`syntax_param.eraseForRun`). `T` is a record
/// type written by its declared name (the run looks it up by that name).
fn inferMethodMetaRead(env: *Env, call: anytype, recv: *ast.TypedExpr, loc: ast.Loc) InferError!TypedExpr {
    if (currentDeclParam(env) == null) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}(T)` on a `decl.methods` entry is read by a decorator's body", .{ diagnostics.typeinfo_meta_type, call.callee });
        env.lastError = TypeError.custom(msg, "A method's typed meta is read while the program compiles, by its owner's decorator (question s29-b).").withLoc(loc);
        return error.TypeError;
    }
    return metaReadCall(env, call, recv, loc, "a `decl.methods` entry");
}

/// A typed meta read on a handle the run answers by the record's declared
/// name (`m.meta(T)` on a method entry, `d.meta(T)` on a tag's `@Decl`).
fn metaReadCall(env: *Env, call: anytype, recv: *ast.TypedExpr, loc: ast.Loc, on: []const u8) InferError!TypedExpr {
    const one = std.mem.eql(u8, call.callee, "meta");
    const mt = try metaReadType(env, call, loc);
    if (!std.mem.eql(u8, mt.spelled, mt.name) or mt.generic) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}({s})` on {s} names the record by another name than its declaration's `{s}`, or a generic record", .{ diagnostics.typeinfo_meta_type, call.callee, mt.spelled, on, mt.name });
        env.lastError = TypeError.custom(msg, "Write the meta record as it is declared — `m.meta(Query)` —: the method's values are keyed by that name (question s29-b).").withLoc(call.args[0].value.getLoc());
        return error.TypeError;
    }
    const argTyped = try env.arena.create(TypedExpr);
    argTyped.* = try inferExprTyped(env, call.args[0].value.*);
    const typedArgs = try env.arena.alloc(ast.CallArgOf(.typed), 1);
    typedArgs[0] = .{ .label = null, .value = argTyped };
    return TypedExpr{ .call = .{ .loc = loc, .type_ = try env.namedTypeArgs(if (one) "optional" else "array", &.{mt.instance}), .kind = .{ .call = .{
        .receiver = recv,
        .callee = call.callee,
        .is_builtin = false,
        .args = typedArgs,
        .trailing = &.{},
    } } } };
}

/// Decision 302 — `d.meta(T)` / `d.metaAll(T)` on a tag's `@Decl`: `?T` /
/// `T[]`, the typed meta the tag's annotations recorded, read where the
/// template runs (`syntax_param.eraseMetaReads`). On a decorator's own `@Decl`
/// parameter it is refused: a declaration's meta is read through
/// `@typeInfo(X).meta(T)`.
fn inferTagMetaRead(env: *Env, call: anytype, recv: *ast.TypedExpr, loc: ast.Loc) InferError!TypedExpr {
    if (currentDeclParam(env)) |dp| if (std.mem.eql(u8, typedIdentName(recv.*) orelse "", dp)) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}.{s}(T)` reads a tag's meta, and `{s}` is the declaration this decorator annotates", .{ diagnostics.typeinfo_meta_type, dp, call.callee, dp });
        env.lastError = TypeError.custom(msg, "A declaration's typed meta is read `@typeInfo(X).meta(T)` (decision 298); `d.meta(T)` reads what a tag's annotations recorded, on the `@Decl` `q.annotate` answers (decision 302).").withLoc(loc);
        return error.TypeError;
    };
    // Decision 415 (3) — a template body reads a meta at build when its
    // record is data: an `@Expr` field is code the program runs.
    if (env.inTemplateFn) {
        const mt = try metaReadType(env, call, loc);
        if (typeDeclAt(env, env.moduleDecls, mt.module, mt.name)) |td| for (td.recordFields()) |f| {
            // A tree (an `@Expr<T>` field, or a function field, which only a
            // tree fills — decision 575 (4)).
            if (!f.exprWrapped and f.typeRef != .function) continue;
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}({s})` is read while the program compiles, and `{s}`'s field `{s}` is an `@Expr` — code the program runs, not data", .{ diagnostics.template_lookup_meta_expr_field, call.callee, mt.spelled, mt.name, f.name });
            env.lastError = TypeError.custom(msg, "A template body reads a declaration's meta at build when every field is data — a string, a number, a `bool`, a variant, an array or an optional of those (decision 415 (3)).").withLoc(loc);
            return error.TypeError;
        };
    }
    return metaReadCall(env, call, recv, loc, "a tag's `@Decl`");
}

/// The `@Decl` methods that write the declaration (decision 216; 316's
/// `implement`).
fn isDeclWrite(callee: []const u8) bool {
    const writes = [_][]const u8{ "setMeta", "addMeta", "addMember", "addType", "implement" };
    for (writes) |w| if (std.mem.eql(u8, callee, w)) return true;
    return false;
}

/// Whether the call is `decl.implement(…)` on the declaration handle
/// (`compiler.implement`), whose one parameter is an `Implementation`.
fn isDeclImplementCall(receiver: ?*ast.TypedExpr, callee: []const u8) bool {
    const r = receiver orelse return false;
    return std.mem.eql(u8, callee, "implement") and isDeclHandleType(r.getType());
}

/// Whether `t` is the `@Decl` handle's type.
fn isDeclHandleType(t: *T.Type) bool {
    const d = t.deref();
    return d.* == .named and std.mem.eql(u8, d.named.name, ast.decl_type_name);
}

/// Decision 371 — `f`, a function of this module a decorator's run reaches,
/// with its `same` calls lowered (`decorator_same.zig`). A decorator runs
/// before the module's bodies are inferred, so a body that writes `same` is
/// inferred now — once, after the module's imports and `val`s are bound as
/// Pass 2 binds them — and its calls are typed and recorded before it runs.
/// A body that writes a section path (`.Pad.All.4`) is inferred now too, and
/// carried with the qualified constructor inference recorded for the path
/// (`block_eval.sectionRewritten`): the decorator module reads the body
/// untyped, where the path is a chain of map reads.
fn sameLoweredFn(env: *Env, program: ast.Program, f: ast.FnDecl) InferError!ast.FnDecl {
    const sections = f.body.len > 0 and blockEval.writesSectionPath(env, f);
    // Decision 587 — a variant constructor called with labels is typed now,
    // so its fill (the declaration order, the defaults left out) is known.
    const labelled = f.body.len > 0 and blockEval.writesLabelledCtorCall(f);
    if (f.body.len == 0 or !(decoratorSameMod.mentionsSame(f) or sections or labelled)) return f;
    const gop = try env.decoratorBodiesChecked.getOrPut(env.arena, @intFromPtr(f.body.ptr));
    if (!gop.found_existing) {
        if (!env.earlyValsBound) {
            env.earlyValsBound = true;
            for (program.decls) |d| if (d == .use or d == .val) {
                _ = try inferDecl(env, d);
            };
        }
        _ = try inferFnDecl(env, f);
    }
    const lowered = if (decoratorSameMod.mentionsSame(f)) try decoratorSameMod.lower(env.arena, &env.decoratorSame, f) else f;
    return if (sections or labelled) try blockEval.sectionRewritten(env.arena, blockEval.Rewrites.withFills(env), lowered) else lowered;
}

/// Decision 372 — the two phases a module's decorators run in: every
/// decorator that reads no `.hooks` before the bodies (`plain`), the ones
/// that read it after them (`hooksReaders`).
const DecoratorPhase = enum { plain, hooksReaders };

/// Decision 567 — the `decl.addMember` / `decl.addType` call of `dfn`'s body
/// that wrote the output `kind` follows `before` (the run's earlier outputs):
/// the k-th such call for the k-th output of its kind (`hooksMod.callSites`).
fn outputCallSite(env: *Env, dfn: ast.FnDecl, owner: []const u8, before: []const decoratorEval.Contribution, kind: decoratorEval.Contribution.Kind) !?envMod.CallSite {
    const callee: []const u8 = switch (kind) {
        .assoc => "addType",
        .compile => memberFn.compile_name,
        else => "addMember",
    };
    var nth: usize = 0;
    for (before) |b| {
        const same = switch (kind) {
            .assoc, .compile => b.kind == kind,
            else => b.kind == .member or b.kind == .memberFn,
        };
        if (same) nth += 1;
    }
    const sites = try hooksMod.callSites(env.arena, dfn, callee);
    if (sites.len == 0) return null;
    return .{ .file = srcPathOfModule(env, owner), .loc = sites[@min(nth, sites.len - 1)], .module = owner };
}

const hooks_output_hint = "A decorator that reads `.hooks` runs after the module's bodies are inferred (decision 372): it records meta (`decl.setMeta`) or refuses (`decl.fail`). Add members and types from a decorator that reads no `.hooks`.";

/// Decision 372 — the second phase: each decorator that reads `.hooks` runs
/// over the module's inferred bodies, then the meta reads that waited for it
/// are answered. Only where decorators run (`env.templateEval`), once per
/// analysis.
fn runHooksReaders(env: *Env, program: ast.Program) InferError!void {
    if (env.hooksReadersRan) return;
    env.hooksReadersRan = true;
    try invokeDecorators(env, program, .hooksReaders);
    try answerDeferredMetaReads(env);
}

/// Decision 372 — note each top-level declaration's annotation whose
/// decorator reads `.hooks` (`Env.hooksReaders`), before Pass 2 infers the
/// bodies that may read its meta.
fn noteHooksReaders(env: *Env, program: ast.Program) InferError!void {
    if (env.templateEval == null) return;
    for (program.decls) |decl| {
        const name: []const u8, const anns: []const ast.Annotation = switch (decl) {
            .@"fn" => |f| .{ if (f.anonymousDefault) moduleFileName(env.modulePath) else f.name, f.annotations },
            .val => |v| .{ v.name, v.annotations },
            .type_ => |t| .{ t.name, t.annotations },
            .behavior => |b| .{ b.name, b.annotations },
            else => continue,
        };
        for (anns) |a| {
            if (!try decoratorReadsHooks(env, a)) continue;
            const dfn = (env.decorators.get(a.name) orelse continue).fn_decl orelse continue;
            try env.hooksReaders.put(env.arena, try hooksReaderKey(env.arena, name, dfn.name), {});
            try env.hooksReaderIds.put(env.arena, try annotationDecoratorId(env, a), {});
        }
    }
}

fn hooksReaderKey(arena: std.mem.Allocator, name: []const u8, decorator: []const u8) ![]const u8 {
    return std.fmt.allocPrint(arena, "{s}\x00{s}", .{ name, decorator });
}

/// Decision 372 — a decorator of this module that reads `.hooks` (in its body
/// or a function it reaches) and gives the program code — `@emit(…)`,
/// `addMember(…)`, `addType(…)` — is refused at that call, whether or not it
/// annotates anything: it runs after the bodies, when code comes too late. A
/// call in a function of another module is reported at the decorator's name.
fn refuseHooksReaderOutputs(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| {
        if (decl != .@"fn") continue;
        const f = decl.@"fn";
        if (f.body.len == 0 or !isDecoratorParams(f.params)) continue;
        const found = try decoratorSupport(env.arena, env.fnDecls, &env.importedFnSupport, f);
        if (!hooksMod.readsMember(&.{f}, "hooks") and !hooksMod.readsMember(found.fns, "hooks")) continue;
        const carried = try std.mem.concat(env.arena, ast.FnDecl, &.{ &.{f}, found.fns });
        for (carried) |sf| {
            const call = hooksMod.outputCall(sf) orelse continue;
            const here = std.mem.eql(u8, env.comptimeOwnerOf(sf), env.modulePath);
            const msg = if (here)
                try std.fmt.allocPrint(env.arena, "{s}: the decorator `{s}` reads `.hooks` and calls `{s}`", .{ diagnostics.decorator_hooks_output, f.name, call.name })
            else
                try std.fmt.allocPrint(env.arena, "{s}: the decorator `{s}` reads `.hooks` and reaches `{s}`, which calls `{s}`", .{ diagnostics.decorator_hooks_output, f.name, sf.name, call.name });
            env.lastError = TypeError.custom(msg, hooks_output_hint).withLoc(if (here) call.at else f.nameLoc);
            return error.TypeError;
        }
    }
}

/// Decision 372 — answer each meta read that waited for a `.hooks` reader of
/// this module: the literal in its place gets the value, or the read is
/// refused as any read of a key no decorator set.
fn answerDeferredMetaReads(env: *Env) InferError!void {
    const r = env.reflection orelse return;
    for (env.deferredMetaReads.items) |d| {
        const entries = try r.metaOf(env.arena, d.module, d.name);
        const value = for (entries) |entry| {
            if (std.mem.eql(u8, entry.decorator, d.decorator) and std.mem.eql(u8, entry.key, d.key)) break entry.value;
        } else return metaMissing(env, d.name, d.decorator, d.key, entries, d.loc);
        d.rewrite.literal.kind.stringLit = try stringLiteralText(env.arena, value);
    }
    env.deferredMetaReads.clearRetainingCapacity();
}

/// `typeinfo-meta-missing` at the read.
fn metaMissing(env: *Env, name: []const u8, decorator: []const u8, key: []const u8, entries: []const reflectionMod.MetaEntry, loc: ast.Loc) InferError {
    var set: std.ArrayListUnmanaged(u8) = .empty;
    for (entries) |entry| {
        if (set.items.len > 0) try set.appendSlice(env.arena, ", ");
        try set.print(env.arena, "`{s}.{s}`", .{ entry.decorator, entry.key });
    }
    const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` has no meta `{s}.{s}`; {s}", .{
        diagnostics.typeinfo_meta_missing,                                                                                 name, decorator, key,
        if (set.items.len == 0) "no decorator set any" else try std.fmt.allocPrint(env.arena, "it has {s}", .{set.items}),
    });
    env.lastError = TypeError.custom(msg, "A key is what the decorator passed to `decl.setMeta(key, value)`, read under the decorator's own name.").withLoc(loc);
    return error.TypeError;
}

/// How a refusal names a declaration with no owner type: a `val` (decision
/// 356) or a function.
fn ownerlessKindWord(kind: []const u8) []const u8 {
    return if (std.mem.eql(u8, kind, "Val")) "val" else "function";
}

/// A closed default (`comptimeMod.isClosedDefault`) as the source lexeme an
/// annotation argument carries: the formatter's rendering of the expression.
fn defaultLexeme(arena: std.mem.Allocator, e: ast.Expr) InferError![]const u8 {
    var f = formatMod.Formatter.init(arena);
    const doc = f.fmtExpr(e) catch return error.OutOfMemory;
    return formatMod.render(arena, doc, std.math.maxInt(u16)) catch return error.OutOfMemory;
}

/// The display path of `module`'s file (`@src().file`, `src/deco.bp`): this
/// module's own, or the one the session recorded when `module` was analysed
/// (`Reflection.srcPaths`), else `<module>.bp`. A decorator or template body
/// run from another module is located in that file, so its diagnostic names it.
fn srcPathOfModule(env: *Env, module: []const u8) []const u8 {
    return env.srcPathOf(module);
}

/// Decisions 451 (3), 532 — the functions of a decorator's or template's run
/// whose calls are located: `head` (the body) in `head_file`, and the
/// functions it reaches (`support`), each in the file of the module it was
/// written in — the library's helper in the library's file.
fn locatedFns(env: *Env, head: ast.FnDecl, head_file: []const u8, support: []const ast.FnDecl) InferError![]const erlang.Located {
    var out: std.ArrayListUnmanaged(erlang.Located) = .empty;
    try out.append(env.arena, .{ .name = head.name, .file = head_file });
    for (support) |sf| try out.append(env.arena, .{ .name = sf.name, .file = env.srcPathOfDecl(sf) });
    return out.items;
}

/// Decision 532 — the refusal of a decorator or template body that raised: the
/// message of the raise, located at the call that raised, in its own file,
/// with a `called from` line for every call of the chain down to `entry`, the
/// annotation or the template's use in this module.
fn raisedFrom(env: *Env, message: []const u8, hint: []const u8, frames: []const blockEval.Frame, entry: ast.Loc) InferError {
    env.lastError = blockEval.raisedError(env, message, hint, frames, entry) catch return error.OutOfMemory;
    return error.TypeError;
}

/// Decision 759 — `decorator-member-local-not-literal`, located at the read
/// of `name` in the tree `func` (in the decorator's own file), the annotation
/// its `called from` line.
fn localNotLiteral(env: *Env, a: ast.Annotation, sig: envMod.DecoratorSig, func: ast.FunctionExpr, local: bool, name: []const u8, message: []const u8, hint: []const u8) InferError {
    const read: ?ast.Loc = for (try memberFn.freeNames(env.arena, func)) |f| {
        if (std.mem.eql(u8, f.name, name)) break f.loc;
    } else null;
    const at = read orelse return decoratorError(env, a, message, hint);
    const own = env.srcPathOf(env.modulePath);
    const file = if (local or sig.module.len == 0) own else env.srcPathOf(sig.module);
    const frames = try env.arena.alloc(errorMod.Frame, if (a.loc != null) 2 else 1);
    frames[0] = .{ .file = file, .loc = at };
    if (a.loc) |l| frames[1] = .{ .file = own, .loc = l };
    env.lastError = TypeError.custom(message, hint).withRaise(own, frames);
    return error.TypeError;
}

fn decoratorError(env: *Env, a: ast.Annotation, message: []const u8, hint: []const u8) InferError {
    var e = TypeError.custom(message, hint);
    if (a.loc) |loc| e = e.withLoc(loc);
    env.lastError = e;
    return error.TypeError;
}

/// Decision 216 (3) — a dotted type name the first analysis accepted on
/// credit (`Env.assocTypesPending`) and no decorator of the module declared:
/// with no re-analysis to follow, it is the unknown type it looks like. Tooling
/// that runs no decorator keeps it lenient.
fn refusePendingAssocType(env: *Env) InferError!void {
    const p = env.pendingAssocTypeName orelse return;
    env.pendingAssocTypeName = null;
    if (env.templateEval == null) return;
    var e = TypeError.unknownTypeName(p.name);
    if (p.loc) |l| e = e.withLoc(l);
    env.lastError = e;
    return error.TypeError;
}

/// The names `program` declares at top level (`Env.ownDecls`) — what
/// `@typeInfo(Name)` reflects in this module.
fn noteOwnDecls(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| {
        const name: []const u8 = switch (decl) {
            .@"fn" => |f| f.name,
            .type_ => |t| t.name,
            .behavior => |b| b.name,
            .val => |v| v.name,
            else => continue,
        };
        try env.ownDecls.put(env.arena, name, {});
        if (decl == .type_) try env.ownTypeDecls.put(env.arena, name, decl.type_.genericParams.len);
    }
}

/// The declaration `@typeInfo(<expr>)` reflects: the module that declares it
/// and the name it is declared under. `Name` is this module's own declaration
/// or an imported one (an alias answers the declaration, decision 110);
/// `ns.Name` is `Name` of the module the namespace import `ns` binds.
fn reflectedDecl(env: *Env, e: ast.Expr) ?struct { module: []const u8, name: []const u8 } {
    if (e != .identifier) return null;
    switch (e.identifier.kind) {
        .ident => |n| {
            if (env.ownDecls.contains(n)) return .{ .module = env.modulePath, .name = n };
            if (env.importOwners.get(n)) |o| return .{ .module = o.owner, .name = o.name };
            return null;
        },
        .identAccess => |ia| {
            if (ia.receiver.* != .identifier or ia.receiver.identifier.kind != .ident) return null;
            const path = env.namespaces.paths.get(ia.receiver.identifier.kind.ident) orelse return null;
            return .{ .module = path, .name = ia.member };
        },
        else => return null,
    }
}

/// A string as the source text of a string literal (`stringLit` keeps the
/// escapes as written; every backend emits them).
fn stringLiteralText(arena: std.mem.Allocator, text: []const u8) ![]const u8 {
    var out: std.ArrayListUnmanaged(u8) = .empty;
    for (text) |ch| switch (ch) {
        '\\' => try out.appendSlice(arena, "\\\\"),
        '"' => try out.appendSlice(arena, "\\\""),
        '\n' => try out.appendSlice(arena, "\\n"),
        '\t' => try out.appendSlice(arena, "\\t"),
        '\r' => try out.appendSlice(arena, "\\r"),
        else => try out.append(arena, ch),
    };
    return out.items;
}

/// Decision 216 (2) — a reflection read: `@typeInfo(X).name` and
/// `@typeInfo(X).meta.<decorator>.<key>`, answered at compile time as a string
/// constant (`env.srcRewrites` puts the literal in the read's place, the way
/// `@src()` is spliced; `transform.zig` replaces the access node at its loc).
/// Null when `ia` is not the end of such a read — a longer chain
/// (`….table.length`) reaches the read as its receiver.
fn inferTypeinfoRead(env: *Env, ia: anytype, loc: ast.Loc) InferError!?TypedExpr {
    var members: [8][]const u8 = undefined;
    var count: usize = 1;
    members[0] = ia.member;
    var node = ia.receiver;
    while (node.* == .identifier and node.identifier.kind == .identAccess) {
        if (count == members.len) return null;
        members[count] = node.identifier.kind.identAccess.member;
        count += 1;
        node = node.identifier.kind.identAccess.receiver;
    }
    if (node.* != .call or node.call.kind != .call) return null;
    const call = node.call.kind.call;
    if (!call.is_builtin or !std.mem.eql(u8, call.callee, "typeInfo")) return null;
    std.mem.reverse([]const u8, members[0..count]);
    const chain = members[0..count];

    const read: enum { name, meta } = if (std.mem.eql(u8, chain[0], "name")) .name else if (std.mem.eql(u8, chain[0], "meta")) .meta else {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `@typeInfo(…)` has no member `{s}`", .{ diagnostics.typeinfo_unknown_member, chain[0] });
        env.lastError = TypeError.custom(msg, "Read `.name` (the declaration's name) or `.meta.<decorator>.<key>` (what a decorator recorded with `decl.setMeta`).").withLoc(loc);
        return error.TypeError;
    };
    const complete: usize = if (read == .name) 1 else 3;
    if (chain.len > complete) return null;
    if (chain.len < complete) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `@typeInfo(…).{s}` names a decorator's meta without its key", .{ diagnostics.typeinfo_unknown_member, std.mem.join(env.arena, ".", chain) catch return error.OutOfMemory });
        env.lastError = TypeError.custom(msg, "A meta read is `.meta.<decorator>.<key>` — the decorator's own name, then the key it set.").withLoc(loc);
        return error.TypeError;
    }

    if (call.args.len != 1 or call.trailing.len != 0) {
        env.lastError = TypeError.custom(diagnostics.typeinfo_unknown_declaration ++ ": `@typeInfo` takes one declaration — `@typeInfo(City)`, `@typeInfo(models.City)`", null).withLoc(node.call.loc);
        return error.TypeError;
    }
    const target = reflectedDecl(env, call.args[0].value.*) orelse {
        const arg_loc = call.args[0].value.getLoc();
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `@typeInfo` reflects a declaration this module declares or imports, and this names none", .{diagnostics.typeinfo_unknown_declaration});
        env.lastError = TypeError.custom(msg, "Name a `type`, `behavior` or `fn` of this module, an imported one, or one through a namespace import (`models.City`).").withLoc(arg_loc);
        return error.TypeError;
    };

    const value: []const u8 = switch (read) {
        .name => target.name,
        .meta => value: {
            const decorator = chain[1];
            const key = chain[2];
            const r = env.reflection orelse break :value "";
            const entries = try r.metaOf(env.arena, target.module, target.name);
            for (entries) |entry| {
                if (std.mem.eql(u8, entry.decorator, decorator) and std.mem.eql(u8, entry.key, key)) break :value entry.value;
            }
            // Tooling that does not run decorators reads an empty constant
            // rather than refuse what the build accepts.
            if (env.templateEval == null) break :value "";
            // Decision 372 — a decorator of this module that reads `.hooks`
            // runs after the bodies: the read is answered when it ran.
            if (!env.hooksReadersRan and std.mem.eql(u8, target.module, env.modulePath) and
                env.hooksReaders.contains(try hooksReaderKey(env.arena, target.name, decorator)))
            {
                const pending = try env.arena.create(ast.Expr);
                pending.* = .{ .literal = .{ .loc = loc, .kind = .{ .stringLit = "" } } };
                try env.srcRewrites.put(loc, pending);
                try env.deferredMetaReads.append(env.arena, .{ .loc = loc, .rewrite = pending, .module = target.module, .name = target.name, .decorator = decorator, .key = key });
                return try inferExprTyped(env, pending.*);
            }
            return metaMissing(env, target.name, decorator, key, entries, loc);
        },
    };

    const rewrite = try env.arena.create(ast.Expr);
    rewrite.* = .{ .literal = .{ .loc = loc, .kind = .{ .stringLit = try stringLiteralText(env.arena, value) } } };
    try env.srcRewrites.put(loc, rewrite);
    return try inferExprTyped(env, rewrite.*);
}

/// Walk `program` and run body-carrying decorators over every annotated
/// declaration (and its methods). Mirrors `validateDecorators`' walk; runs after
/// it (so arguments are already validated).
/// Decision 289 — the last segment of a module path (`components/card` →
/// `card`): an anonymous default function's reflected name. The entry module
/// (path "") is `main`.
fn moduleFileName(path: []const u8) []const u8 {
    if (path.len == 0) return "main";
    const i = std.mem.lastIndexOfScalar(u8, path, '/') orelse return path;
    return path[i + 1 ..];
}

/// Decision 353 — each `@TypeInfo.all(…)` written in a template function's
/// body, its arguments resolved here, in the template's own module (the
/// decorators `with:` names are this module's or its imports'), and recorded
/// in the session's reflection under the template's owner and name. The
/// expansion answers it (`expandTemplateCallViaRuntime`) for the program the
/// call is compiled in. A query whose arguments break the catalogue's rule is
/// refused here, at the query; one whose `with:` names no decorator is left to
/// `checkCatalogueArguments` when the body is checked.
fn noteTemplateQueries(env: *Env, program: ast.Program) InferError!void {
    const r = env.reflection orelse return;
    for (try typeinfoAll.collectTemplates(env.arena, program)) |t| {
        var resolved: std.ArrayListUnmanaged(reflectionMod.TemplateQuery) = .empty;
        for (t.queries) |q| switch (try typeinfoAll.resolve(env.arena, env, program, env.modulePath, q)) {
            .ok => |rq| try resolved.append(env.arena, rq),
            .unanswered => {},
            .refused => |te| {
                env.lastError = te;
                return error.TypeError;
            },
        };
        try r.templateQueries.put(r.arena, try reflectionMod.Reflection.templateKey(r.arena, env.modulePath, t.name), resolved.items);
    }
}

/// Decision 551 — each `comptime` parameter whose default is a
/// `@TypeInfo.all(…)` query: its arguments resolved here, in the declaring
/// module (the decorators `with:` names are this module's or its imports'),
/// and recorded in the session's reflection under
/// `Reflection.defaultKey(module, fn, param)` — journaled with this module, so
/// a package read back from the code cache's level B holds it too. A call
/// that leaves the parameter out is answered for the program it is compiled
/// in (`comptime.zig` `fillCatalogueDefaults`). The parameter's type is the
/// answer's, `Declared<unknown>[]`, held at the default.
fn noteDefaultQueries(env: *Env, program: ast.Program) InferError!void {
    const r = env.reflection orelse return;
    for (try typeinfoAll.collectDefaults(env.arena, program)) |dq| {
        const rq = switch (try typeinfoAll.resolve(env.arena, env, program, env.modulePath, dq.query)) {
            .ok => |rq| rq,
            .unanswered => {
                const msg = try std.fmt.allocPrint(env.arena, "{s}: the default of `{s}`'s parameter `{s}` names no decorator in `with:`", .{ diagnostics.typeinfo_all_arguments, dq.fn_name, dq.param });
                env.lastError = TypeError.custom(msg, "Name a decorator this module declares or imports: `@TypeInfo.all(with: <decorator>)`.").withLoc(dq.query.loc);
                return error.TypeError;
            },
            .refused => |te| {
                env.lastError = te;
                return error.TypeError;
            },
        };
        const f = for (program.decls) |d| {
            if (d == .@"fn" and std.mem.eql(u8, d.@"fn".name, dq.fn_name)) break d.@"fn";
        } else continue;
        for (f.params) |p| if (std.mem.eql(u8, p.name, dq.param)) {
            var genericMap = std.StringHashMap(*T.Type).init(env.arena);
            defer genericMap.deinit();
            for (f.genericParams) |gp| try genericMap.put(gp.name, try env.freshVar());
            // Decision 564 — `Declared<B>[]` when the decorators share `B`.
            const entry = if (rq.member == null) rq.behavior orelse "unknown" else "unknown";
            const answer = try env.namedTypeArgs("array", &.{try env.namedTypeArgs("Declared", &.{try env.namedType(entry)})});
            try unifyAt(env, try resolveParamType(env, p, genericMap), answer, dq.query.loc);
        };
        const one = try r.arena.alloc(reflectionMod.TemplateQuery, 1);
        one[0] = rq;
        try r.templateQueries.put(r.arena, try reflectionMod.Reflection.defaultKey(r.arena, env.modulePath, dq.fn_name, dq.param), one);
    }
}

/// `fns` less the functions `have` already lists by name: the std functions
/// a decorator argument reaches beside the decorator's own closure, each once.
fn withoutListed(arena: std.mem.Allocator, fns: []const ast.FnDecl, have: []const ast.FnDecl) InferError![]const ast.FnDecl {
    var out: std.ArrayListUnmanaged(ast.FnDecl) = .empty;
    outer: for (fns) |f| {
        for (have) |h| if (std.mem.eql(u8, h.name, f.name)) continue :outer;
        try out.append(arena, f);
    }
    return out.items;
}

/// Decision 734 — the place `compiler.src()` answers in a decorator of the
/// declaration at `loc` of this module; null for a synthesised one.
fn declSrc(env: *Env, loc: ast.Loc) ?decoratorEval.SrcPoint {
    if (loc.line == 0) return null;
    return .{ .file = env.srcPath, .line = loc.line, .column = loc.col };
}

fn invokeDecorators(env: *Env, program: ast.Program, phase: DecoratorPhase) InferError!void {
    // Second pass: contributions already spliced. The `.hooks` readers run
    // in the analysis that infers the bodies, whichever it is.
    if (phase == .plain and env.skipDecoratorInvoke) return;
    if (env.decorators.count() == 0 and !try hasTemplateAnnotation(env, program)) return;
    const ctx = env.templateEval orelse return;
    for (program.decls, 0..) |decl, di| switch (decl) {
        .@"fn" => |f| {
            env.decoratedDeclIndex = di;
            const h = decoratorEval.DeclHandle{
                .kind = "Fn",
                // Decision 289 — an anonymous default is named by its file.
                .name = if (f.anonymousDefault) moduleFileName(env.modulePath) else f.name,
                .fields = &.{},
                .methods = &.{},
                .returnType = if (f.returnType) |rt| try declTypeName(env.arena, rt) else "",
                .annotations = f.annotations,
                .hooks = if (phase == .hooksReaders) try declHooksTerm(env, f) else &.{},
                .params = try paramHandles(env, f.params),
                .src = declSrc(env, if (f.startLoc.line > 0) f.startLoc else f.nameLoc),
            };
            try runDeclDecorators(env, ctx, program, phase, f.annotations, h, null, .{ .kind = .function, .isPub = f.isPub });
        },
        // Decision 356 — a module-level `val` reflects as `DeclKind.Val`:
        // its name and its declared type as written (`""` when none). It
        // owns no type, so `decl.addMember` / `decl.addType` are refused at
        // the annotation; `decl.setMeta` records meta like a `fn`'s, and the
        // `val` is an entry of `@TypeInfo.all`. A module `var` never gets
        // here with a decorator: `validateDecorators` refuses it first.
        .val => |v| {
            env.decoratedDeclIndex = di;
            const h = decoratorEval.DeclHandle{
                .kind = "Val",
                .name = v.name,
                .fields = &.{},
                .methods = &.{},
                .returnType = if (v.typeAnnotation) |tr| try declTypeName(env.arena, tr) else "",
                .annotations = v.annotations,
                .src = declSrc(env, v.nameLoc),
            };
            runDeclDecorators(env, ctx, program, phase, v.annotations, h, null, .{ .kind = .val, .isPub = v.isPub }) catch |err| {
                // Decision 788 — a top-level `comptime { … }`'s refusal names
                // the block, never the decorator it is read onto.
                if (err == error.TypeError and ast.isComptimeBlockName(v.name)) if (env.lastError) |te| {
                    env.lastError = try te.blockNamed(env.arena, true);
                };
                return err;
            };
        },
        .type_ => |tdecl| switch (tdecl.shape) {
            .record => {
                env.decoratedDeclIndex = di;
                var fields = try env.arena.alloc(decoratorEval.FieldHandle, tdecl.recordFields().len);
                for (tdecl.recordFields(), 0..) |fld, i| {
                    fields[i] = .{
                        .name = fld.name,
                        .typeName = try declTypeName(env.arena, fld.typeRef),
                        .annotations = fld.annotations,
                    };
                }
                // Question s29-b — a method's decorators run before its
                // owner's, which read the typed meta they recorded on
                // `decl.methods` (`m.meta(T)`, 313's repository).
                for (tdecl.methods) |m| {
                    const mh = decoratorEval.DeclHandle{
                        .kind = "Method",
                        .name = m.name,
                        .fields = &.{},
                        .methods = &.{},
                        .returnType = if (m.returnType) |rt| try declTypeName(env.arena, rt) else "",
                        .annotations = m.annotations,
                        .params = try paramHandles(env, m.params),
                        .src = declSrc(env, m.nameLoc),
                    };
                    try runDeclDecorators(env, ctx, program, phase, m.annotations, mh, tdecl.name, null);
                }
                const h = decoratorEval.DeclHandle{
                    .kind = "Type",
                    .name = tdecl.name,
                    .fields = fields,
                    .methods = tdecl.methods,
                    .returnType = "",
                    .annotations = tdecl.annotations,
                    .src = declSrc(env, if (tdecl.startLoc.line > 0) tdecl.startLoc else tdecl.loc),
                };
                try runDeclDecorators(env, ctx, program, phase, tdecl.annotations, h, tdecl.name, .{ .kind = .type_, .isPub = tdecl.isPub });
                for (tdecl.recordFields()) |fld| {
                    const fh = decoratorEval.DeclHandle{
                        .kind = "Field",
                        .name = fld.name,
                        .fields = &.{},
                        .methods = &.{},
                        .returnType = try declTypeName(env.arena, fld.typeRef),
                        .annotations = fld.annotations,
                    };
                    try runDeclDecorators(env, ctx, program, phase, fld.annotations, fh, tdecl.name, null);
                }
            },
            .enum_ => {
                env.decoratedDeclIndex = di;
                const names = try variantHandles(env, tdecl);
                // Question s29-b — a method's decorators run before its
                // owner's, which read the typed meta they recorded on
                // `decl.methods` (`m.meta(T)`, 313's repository).
                for (tdecl.methods) |m| {
                    const mh = decoratorEval.DeclHandle{
                        .kind = "Method",
                        .name = m.name,
                        .fields = &.{},
                        .methods = &.{},
                        .returnType = if (m.returnType) |rt| try declTypeName(env.arena, rt) else "",
                        .annotations = m.annotations,
                        .params = try paramHandles(env, m.params),
                        .src = declSrc(env, m.nameLoc),
                    };
                    try runDeclDecorators(env, ctx, program, phase, m.annotations, mh, tdecl.name, null);
                }
                const h = decoratorEval.DeclHandle{
                    .kind = "Type",
                    .name = tdecl.name,
                    .fields = &.{},
                    .variants = names,
                    .methods = tdecl.methods,
                    .returnType = "",
                    .annotations = tdecl.annotations,
                    .src = declSrc(env, if (tdecl.startLoc.line > 0) tdecl.startLoc else tdecl.loc),
                };
                try runDeclDecorators(env, ctx, program, phase, tdecl.annotations, h, tdecl.name, .{ .kind = .type_, .isPub = tdecl.isPub });
            },
        },
        .behavior => |i| {
            env.decoratedDeclIndex = di;
            // Behavior-level markers (`#[mock]`) reflect with kind `Behavior`,
            // exposing the interface's fields + method signatures. Its methods also
            // reflect individually (`#[getMapping]` on a route) as `Method`.
            var fields = try env.arena.alloc(decoratorEval.FieldHandle, i.fields.len);
            for (i.fields, 0..) |fld, idx| {
                fields[idx] = .{
                    .name = fld.name,
                    .typeName = try declTypeName(env.arena, fld.typeRef),
                    .annotations = &.{},
                };
            }
            // Question s29-b — a method's decorators run before its owner's.
            for (i.methods) |m| {
                const mh = decoratorEval.DeclHandle{
                    .kind = "Method",
                    .name = m.name,
                    .fields = &.{},
                    .methods = &.{},
                    .returnType = if (m.returnType) |rt| try declTypeName(env.arena, rt) else "",
                    .annotations = m.annotations,
                    .params = try paramHandles(env, m.params),
                };
                try runDeclDecorators(env, ctx, program, phase, m.annotations, mh, i.name, null);
            }
            const h = decoratorEval.DeclHandle{
                .kind = "Behavior",
                .name = i.name,
                .fields = fields,
                .methods = i.methods,
                .returnType = "",
                .annotations = i.annotations,
            };
            try runDeclDecorators(env, ctx, program, phase, i.annotations, h, i.name, .{ .kind = .behavior, .isPub = i.isPub });
        },
        else => {},
    };
}

/// `decl.params` — a function's or a method's own parameters as the handle
/// carries them (`01-checker` step 29, decision 280): each name and its type
/// as written, `self` included.
fn paramHandles(env: *Env, params: []const ast.Param) InferError![]const decoratorEval.ParamHandle {
    const out = try env.arena.alloc(decoratorEval.ParamHandle, params.len);
    for (params, 0..) |p, i| out[i] = .{ .name = p.name, .typeName = try declTypeName(env.arena, p.typeRef) };
    return out;
}

/// The index of the element labeled `label` (decision 8 §6), or null when no
/// element carries that label or two do (an ambiguous label names nothing).
fn tupleLabelIndex(labels: []const []const u8, label: []const u8) ?usize {
    var found: ?usize = null;
    for (labels, 0..) |l, i| {
        if (!std.mem.eql(u8, l, label)) continue;
        if (found != null) return null;
        found = i;
    }
    return found;
}

/// Parse a tuple-index member name (`_0`, `_1`, …) into its integer index.
/// Returns null for any other member name. Mirrors codegen's tupleIndexMember.
fn tupleMemberIndex(member: []const u8) ?usize {
    // `t._N` and the bare `t.N` both name element N.
    const digits = if (member.len > 0 and member[0] == '_') member[1..] else member;
    if (digits.len == 0) return null;
    for (digits) |ch| {
        if (!std.ascii.isDigit(ch)) return null;
    }
    return std.fmt.parseInt(usize, digits, 10) catch null;
}

/// True when `name` names a registered type definition with generic params.
fn typeDefHasGenerics(env: *Env, name: []const u8) bool {
    const td = env.lookupTypeDef(name) orelse return false;
    return switch (td) {
        .record => |r| r.genericParams.len > 0,
        .struct_ => |s| s.genericParams.len > 0,
        .enum_ => |e| e.genericParams.len > 0,
    };
}

/// Per-call-site instantiation of a generic type-def constructor. Without it
/// the registration-time generic cells unify destructively at the first call
/// (`Pair(first: p.second, …)` in one fn would bind `A := B` for every later
/// `Pair(1, "one")` — "expected i32, found string").
fn instantiateCtorType(env: *Env, callee: []const u8, ctorType: *T.Type) InferError!*T.Type {
    if (!typeDefHasGenerics(env, callee)) return ctorType;
    var seen = std.AutoHashMap(*T.TypeCell, *T.Type).init(env.arena);
    defer seen.deinit();
    return instantiateType(env, ctorType, &seen, .allVars);
}

/// Field type of a generic record instance: substitute the registration-time
/// generic cells with the instance's type args (`p: Pair<i32, string>` →
/// `p.second: string`). The cells are recovered positionally from the
/// constructor binding's return type (`fn(…) -> Pair<A_cell, B_cell>`).
/// Falls back to the registered (shared) field type when the shape doesn't
/// line up — never worse than the previous behavior.
fn instantiateFieldType(env: *Env, typeName: []const u8, instArgs: []*T.Type, fieldType: *T.Type) InferError!*T.Type {
    if (instArgs.len == 0) return fieldType;
    const ctor = env.lookup(typeName) orelse env.typeOnlyCtors.get(typeName) orelse return fieldType;
    const ctorResolved = ctor.deref();
    if (ctorResolved.* != .func) return fieldType;
    const ret = ctorResolved.func.ret.deref();
    if (ret.* != .named or ret.named.args.len != instArgs.len) return fieldType;

    var seen = std.AutoHashMap(*T.TypeCell, *T.Type).init(env.arena);
    defer seen.deinit();
    for (ret.named.args, instArgs) |cellTy, inst| {
        const cellResolved = cellTy.deref();
        if (cellResolved.* != .typeVar) continue;
        try seen.put(cellResolved.typeVar, inst);
    }
    if (seen.count() == 0) return fieldType;
    return instantiateType(env, fieldType, &seen, .allVars);
}

/// Which type-variable states `instantiateType` substitutes with fresh vars.
///   - `.allVars`: `.unbound` AND `.generic` — registration-time copies for
///     ctors / "std" module exports, where every var belongs to the scheme.
///   - `.genericOnly`: standard HM instantiation — only generalized
///     (`.generic`) vars are freshened; `.unbound` vars belong to the
///     enclosing inference in progress and must stay shared.
const InstantiateMode = enum { allVars, genericOnly };

/// Deep-copies `ty`, substituting type variables (per `mode`) with fresh
/// ones. Per-call-site instantiation — without it the shared fn type would
/// unify destructively at the first call site.
fn instantiateType(env: *Env, ty: *T.Type, seen: *std.AutoHashMap(*T.TypeCell, *T.Type), mode: InstantiateMode) InferError!*T.Type {
    const resolved = ty.deref();
    switch (resolved.*) {
        .typeVar => |cell| switch (cell.state) {
            .unbound => {
                if (mode == .genericOnly) return resolved;
                if (seen.get(cell)) |fresh| return fresh;
                const fresh = try env.freshVar();
                try seen.put(cell, fresh);
                return fresh;
            },
            .generic => {
                if (seen.get(cell)) |fresh| return fresh;
                const fresh = try env.freshVar();
                try seen.put(cell, fresh);
                return fresh;
            },
            .link => unreachable, // deref follows links
        },
        .named => |n| {
            if (n.args.len == 0) return resolved;
            const args = try env.arena.alloc(*T.Type, n.args.len);
            for (n.args, 0..) |a, i| args[i] = try instantiateType(env, a, seen, mode);
            const node = try env.arena.create(T.Type);
            // 06 N24 — a tuple's element labels (decision 8 §6) live on the
            // `named` node, so instantiating a generic signature has to carry
            // them: `fn ref<T>() -> #(current: T)` lost them here and
            // `r.current` reds "this tuple has no element labeled".
            node.* = .{ .named = .{ .name = n.name, .args = args, .labels = n.labels } };
            return node;
        },
        .func => |f| {
            const params = try env.arena.alloc(*T.Type, f.params.len);
            for (f.params, 0..) |p, i| params[i] = try instantiateType(env, p, seen, mode);
            const node = try env.arena.create(T.Type);
            node.* = .{ .func = .{ .params = params, .ret = try instantiateType(env, f.ret, seen, mode) } };
            return node;
        },
        .union_ => |members| {
            const copies = try env.arena.alloc(*T.Type, members.len);
            for (members, 0..) |m, i| copies[i] = try instantiateType(env, m, seen, mode);
            const node = try env.arena.create(T.Type);
            node.* = .{ .union_ = copies };
            return node;
        },
        .record => |fields| {
            const copies = try env.arena.alloc(T.Field, fields.len);
            for (fields, 0..) |f, i| copies[i] = .{ .name = f.name, .type_ = try instantiateType(env, f.type_, seen, mode) };
            const node = try env.arena.create(T.Type);
            node.* = .{ .record = copies };
            return node;
        },
    }
}

/// True when `ty` contains a generalized (`.generic`) type variable.
/// Cheap pre-check so `instantiateGenericType` can skip allocation in the
/// common monomorphic case.
fn hasGenericVar(ty: *T.Type) bool {
    const resolved = ty.deref();
    switch (resolved.*) {
        .typeVar => |cell| return cell.state == .generic,
        .named => |n| {
            for (n.args) |a| if (hasGenericVar(a)) return true;
            return false;
        },
        .func => |f| {
            for (f.params) |p| if (hasGenericVar(p)) return true;
            return hasGenericVar(f.ret);
        },
        .union_ => |members| {
            for (members) |m| if (hasGenericVar(m)) return true;
            return false;
        },
        .record => |fields| {
            for (fields) |f| if (hasGenericVar(f.type_)) return true;
            return false;
        },
    }
}

/// Standard HM instantiation: deep-copies `ty` substituting every `.generic`
/// var with a fresh unbound one. One substitution map across params + return,
/// so `fn(x: A) -> A` yields the SAME fresh var on both sides. Two calls to
/// the same generic fn each get their own fresh vars and never conflict.
/// Returns `ty` unchanged when it has no `.generic` vars (monomorphic case).
fn instantiateGenericType(env: *Env, ty: *T.Type) InferError!*T.Type {
    if (!hasGenericVar(ty)) return ty;
    var seen = std.AutoHashMap(*T.TypeCell, *T.Type).init(env.arena);
    defer seen.deinit();
    return instantiateType(env, ty, &seen, .genericOnly);
}

/// R3 (decision 8 §8, decision 15) — `#[@external(node, "…")]` in lower case.
///
/// The annotation grammar accepts any `#[@name(…)]`, and only the capitalised
/// path form `External.<Target>` is read as host-backed (`FnDecl.isExternal`,
/// `ast.zig`'s `startsWith("External.")`). A lower-case one therefore fell
/// through as an unknown annotation and was dropped: the `declare fn` bound no
/// host, `botopink check` exited 0, and nothing was said. Name the spelling
/// that works, at the annotation.
///
/// Only the `@`-prefixed builtin form is caught. `#[external(…)]` without the
/// `@` is a user-defined attribute — a decorator's own name — and means
/// something else entirely.
/// Decision 38 — a `val` is **immutable**, local or module-level. `val x = 0;
/// x = 1;` checked and then threw on node (`const`) and ran on the other three
/// targets; the rule moves to compile time, and the error names `var`.
/// Decision 148 (lg-b) — a write to a captured `var` (a local of an
/// enclosing body, bound outside the lambda being inferred) from a lambda
/// that is neither a `forEach` body nor a local closure called only at
/// statement position is refused at the write, on every target: on the BEAM
/// a closure gets a COPY of what it captures, so the write is lost, while
/// commonJS writes the shared cell. A counter shared across calls is a
/// module-level `var` with its `#[compiler.beamMemory(…)]` mode.
fn refuseCapturedVarWrite(env: *Env, name: []const u8, loc: ast.Loc) InferError!void {
    if (env.lambdaDepth == 0 or env.captureWriteOk) return;
    const d = env.localBindDepth(name) orelse return;
    if (d >= env.lambdaDepth) return;
    const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is a `var` of the enclosing body, and this lambda writes it — a lambda gets a copy of what it captures on the BEAM, so the write would not reach `{s}`", .{ diagnostics.captured_var_write, name, name });
    env.lastError = TypeError.custom(msg, "Write it in a `forEach` body or a local closure called as a statement (`val bump: fn() -> void = { -> n = n + 1; }; bump();`), return the new value from the lambda, or keep a counter shared across calls in a module-level `var` with its `#[compiler.beamMemory(…)]` mode.").withLoc(loc);
    return error.TypeError;
}

/// Whether `e` reads or calls the bare name `name` anywhere, a lambda body
/// included (`ast.exprMentions` answers true for any lambda, which would make
/// every closure passed to a call a use).
fn usesName(e: ast.Expr, name: []const u8) bool {
    return switch (e) {
        .function => |f| stmtsUseName(f.kind.body, name),
        .call => |c| switch (c.kind) {
            .call => |cc| blk: {
                if (cc.receiver) |r| if (usesName(r.*, name)) break :blk true;
                if (cc.receiver == null and !cc.is_builtin and std.mem.eql(u8, cc.callee, name)) break :blk true;
                if (cc.calleeExpr) |ce| if (usesName(ce.*, name)) break :blk true;
                for (cc.args) |a| if (usesName(a.value.*, name)) break :blk true;
                for (cc.trailing) |t| if (stmtsUseName(t.body, name)) break :blk true;
                break :blk false;
            },
            .pipeline => |p| usesName(p.lhs.*, name) or usesName(p.rhs.*, name),
        },
        .jump => |j| switch (j.kind) {
            .@"return", .throw_, .try_ => |v| if (v) |x| usesName(x.*, name) else false,
            .await_ => |x| usesName(x.*, name),
            .@"break" => |b| if (b.value) |x| usesName(x.*, name) else false,
            .yield => |y| if (y.value) |x| usesName(x.*, name) else false,
            .@"continue" => false,
        },
        .loop => |lp| usesName(lp.iter.*, name) or stmtsUseName(lp.body, name),
        .branch => |b| switch (b.kind) {
            .if_ => |i| usesName(i.cond.*, name) or stmtsUseName(i.then_, name) or
                (if (i.else_) |els| stmtsUseName(els, name) else false),
            .tryCatch => |tc| usesName(tc.expr.*, name) or usesName(tc.handler.*, name),
        },
        .binding => |b| switch (b.kind) {
            .localBind => |lb| usesName(lb.value.*, name),
            .localBindDestruct => |lb| usesName(lb.value.*, name),
            .assign => |a| usesName(a.value.*, name) or switch (a.target) {
                .name => |n| std.mem.eql(u8, n, name),
                .fieldAccess => |fa| usesName(fa.receiver.*, name),
            },
        },
        .collection => |c| switch (c.kind) {
            .case => |cs| blk: {
                for (cs.subjects) |x| if (usesName(x, name)) break :blk true;
                for (cs.arms) |arm| {
                    if (usesName(arm.body, name)) break :blk true;
                    if (arm.guard) |g| if (usesName(g, name)) break :blk true;
                }
                break :blk false;
            },
            .arrayLit => |al| blk: {
                for (al.elems) |x| if (usesName(x, name)) break :blk true;
                if (al.spread) |sp| if (std.mem.eql(u8, sp, name)) break :blk true;
                if (al.spreadExpr) |se| if (usesName(se.*, name)) break :blk true;
                break :blk false;
            },
            .tupleLit => |tl| blk: {
                for (tl.elems) |x| if (usesName(x, name)) break :blk true;
                break :blk false;
            },
            .range => |r| usesName(r.start.*, name) or (if (r.end) |x| usesName(x.*, name) else false),
            .grouped => |g| usesName(g.*, name),
            else => true,
        },
        .useHook => |u| usesName(u.kind.inner.*, name),
        else => ast.exprMentions(e, name),
    };
}

/// Every use of `name` in `stmts` is a call at statement position (`f(…);`,
/// its arguments not naming `f`) — in these statements or in the blocks of an
/// `if`, a loop or a `case` arm among them.
fn onlyStatementCalls(stmts: []const ast.Stmt, name: []const u8) bool {
    for (stmts) |st| if (!stmtOnlyCalls(st.expr, name)) return false;
    return true;
}

fn stmtOnlyCalls(e: ast.Expr, name: []const u8) bool {
    switch (e) {
        .call => |c| if (c.kind == .call) {
            const cc = c.kind.call;
            if (cc.receiver == null and cc.calleeExpr == null and !cc.is_builtin and std.mem.eql(u8, cc.callee, name)) {
                for (cc.args) |a| if (usesName(a.value.*, name)) return false;
                return cc.trailing.len == 0;
            }
            // `xs.forEach({ x -> f(x); })` — a `forEach` body is itself a
            // statement-position scope (decision 148's first exempt shape).
            if (std.mem.eql(u8, cc.callee, "forEach") and cc.receiver != null and cc.trailing.len == 0) {
                if (usesName(cc.receiver.?.*, name)) return false;
                for (cc.args) |a| {
                    if (a.value.* == .function) {
                        if (!onlyStatementCalls(a.value.function.kind.body, name)) return false;
                    } else if (usesName(a.value.*, name)) return false;
                }
                return true;
            }
        },
        .loop => |lp| return !usesName(lp.iter.*, name) and onlyStatementCalls(lp.body, name),
        .branch => |b| if (b.kind == .if_) {
            const i = b.kind.if_;
            if (usesName(i.cond.*, name)) return false;
            if (!onlyStatementCalls(i.then_, name)) return false;
            return if (i.else_) |els| onlyStatementCalls(els, name) else true;
        },
        else => {},
    }
    return !usesName(e, name);
}

fn stmtsUseName(stmts: []const ast.Stmt, name: []const u8) bool {
    for (stmts) |st| if (usesName(st.expr, name)) return true;
    return false;
}

fn isArrayType(t: *T.Type) bool {
    const d = t.deref();
    return d.* == .named and std.mem.eql(u8, d.named.name, "array");
}

/// Decision 148 — the `val f = { … }` statements of a block whose every later
/// use is a call at statement position (`f();`, its arguments not naming
/// `f`): the lambda they bind may write a captured `var`.
fn noteStatementClosures(env: *Env, stmts: []const ast.Stmt) InferError!void {
    for (stmts, 0..) |st, i| {
        if (st.expr != .binding) continue;
        const lb = switch (st.expr.binding.kind) {
            .localBind => |lb| lb,
            else => continue,
        };
        if (lb.value.* != .function) continue;
        const name = lb.name;
        const ok = onlyStatementCalls(stmts[i + 1 ..], name);
        if (ok) try env.statementClosures.put(env.arena, name, {}) else _ = env.statementClosures.remove(name);
    }
}

fn refuseValAssign(env: *Env, name: []const u8, loc: ast.Loc) InferError!void {
    if (!env.isVal(name)) return;
    var e = TypeError.custom(
        try std.fmt.allocPrint(env.arena, "`{s}` is a `val` and cannot be assigned", .{name}),
        try std.fmt.allocPrint(env.arena, "Declare it `var {s} = …` to reassign it, or bind the new value to a new name.", .{name}),
    );
    env.lastError = e.withLoc(loc);
    return error.TypeError;
}

/// `#[compiler.beamMemory(.<Mode>)]` on a module binding — front 17 step 3,
/// decisions 41, 547 and 663. A misread memory annotation does not fail, it
/// moves where the state lives, so every part is checked: the binding is a
/// `var`, and the mode is `BeamMemory`'s `Ets` (what a `var` with no
/// annotation means) or `PersistentTerm`, with no argument. Off the BEAM the
/// annotation is accepted and changes nothing (547, amending 167).
fn validateMemoryAnnotations(env: *Env, v: ast.ValDecl, bindTy: *T.Type) InferError!void {
    _ = bindTy;
    const members = [_][]const u8{ "Ets", "PersistentTerm" };
    for (v.annotations) |a| {
        const arg = a.beamMemoryOf() orelse continue;
        const loc = a.loc orelse v.value.getLoc();
        if (!v.mutable) return failAt(
            env,
            loc,
            try std.fmt.allocPrint(env.arena, "`#[{s}({s})]` needs a `var` — `{s}` is a `val`", .{ a.name, try joinAnnotationArgs(env, a), v.name }),
            try std.fmt.allocPrint(env.arena, "Write `#[{s}({s})] var {s}: T = …;`.", .{ a.name, try joinAnnotationArgs(env, a), v.name }),
        );
        var known = false;
        for (members) |m| known = known or std.mem.eql(u8, m, arg.case);
        if (!known) return failAt(
            env,
            loc,
            if (arg.case.len == 0)
                "`#[compiler.beamMemory(…)]` takes one argument, the mode — expected `.Ets` or `.PersistentTerm`"
            else
                try std.fmt.allocPrint(env.arena, "unknown member `{s}` in `BeamMemory` — expected `Ets` or `PersistentTerm`", .{arg.case}),
            "The member names how the BEAM holds the `var`; `Ets` is what a `var` with no annotation means.",
        );
        var items = arg.items();
        if (items.next()) |item| return failAt(
            env,
            loc,
            try std.fmt.allocPrint(env.arena, "unknown argument `{s}` — `.{s}` takes none", .{ item.label orelse item.value, arg.case }),
            try std.fmt.allocPrint(env.arena, "Write `#[compiler.beamMemory(.{s})]`.", .{arg.case}),
        );
    }
}

/// The value type `V` of a `Dict<K, V>`, or null when it is not spelled out.
fn keyedValueType(t: *T.Type) ?*T.Type {
    const d = t.deref();
    return switch (d.*) {
        .named => |n| if (n.args.len == 2) n.args[1] else null,
        else => null,
    };
}

fn failAt(env: *Env, loc: ast.Loc, msg: []const u8, hint: ?[]const u8) InferError {
    var e = TypeError.custom(msg, hint);
    env.lastError = e.withLoc(loc);
    return error.TypeError;
}

/// Is `t` the standard library's `Dict<K, V>`?
fn typeIsDict(t: *T.Type) bool {
    const d = t.deref();
    return switch (d.*) {
        .named => |n| std.mem.eql(u8, n.name, "Dict") or std.mem.startsWith(u8, n.name, "Dict<"),
        else => false,
    };
}

/// `an \`i32\`` / `a \`string[]\`` — the type in the `keyed` diagnostic.
fn describeForKeyed(env: *Env, t: *T.Type) ![]const u8 {
    const rendered = try snapshotMod.typeNameOf(env.arena, t);
    const article: []const u8 = if (rendered.len > 0 and std.mem.indexOfScalar(u8, "aeiouAEIOU", rendered[0]) != null) "an" else "a";
    return std.fmt.allocPrint(env.arena, "{s} `{s}`", .{ article, rendered });
}

/// Decision 37 — a record is **immutable**. `p.age = 31` and `self.count += 1`
/// both checked and both mutated in place; the decided form is a new value,
/// `Person(..p, age: 31)`, which the constructor's `..` spread already builds
/// (06 C11).
///
/// Only a receiver whose type is a record this module registered is refused.
/// Everything else keeps assigning: a receiver still an unresolved type
/// variable is an inference gap and must not red here, and a named type the env
/// cannot open — an imported record, a `@Result`/`?T` wrapper, a host object a
/// library binds — is not something this rule can speak for.
fn refuseRecordFieldAssign(
    env: *Env,
    receiver: ast.Expr,
    receiverType: *T.Type,
    field: []const u8,
    loc: ast.Loc,
) InferError!void {
    const t = receiverType.deref();
    if (t.* != .named) return;
    const typeName = t.named.name;
    const td = env.lookupTypeDef(typeName) orelse return;
    if (td != .record) return;
    // Name the receiver in the hint when it is something the author can spread:
    // a plain name (`p`, `self`). Anything else gets the shape without it.
    const spread: []const u8 = switch (receiver) {
        .identifier => |id| switch (id.kind) {
            .ident => |n| n,
            else => "…",
        },
        else => "…",
    };
    var e = TypeError.custom(
        try std.fmt.allocPrint(
            env.arena,
            "a `{s}` is immutable — its field `{s}` cannot be assigned",
            .{ typeName, field },
        ),
        try std.fmt.allocPrint(
            env.arena,
            "Build a new value instead: `{s}(..{s}, {s}: <value>)`.",
            .{ typeName, spread, field },
        ),
    );
    env.lastError = e.withLoc(loc);
    return error.TypeError;
}

fn inferFnDecl(env: *Env, f: ast.FnDecl) InferError!*T.Type {
    // 01 step 13 — the parameters and every local end with the body.
    var bodyLog: std.ArrayListUnmanaged(Env.BindUndo) = .empty;
    const outerScope = env.openBodyScope(&bodyLog);
    defer env.closeBodyScope(&bodyLog, outerScope, f.name);
    try checkRecordParams(env, f);

    // Build generic map.
    var genericMap = std.StringHashMap(*T.Type).init(env.arena);
    defer genericMap.deinit();
    for (f.genericParams) |gp| {
        try genericMap.put(gp.name, try env.freshVar());
    }

    // Collect typeparam constraints so call sites can validate comptime args.
    var typeparams: std.ArrayListUnmanaged(envMod.TypeparamConstraint) = .empty;
    // Collect `expr` meta-kind params so call sites capture their arguments
    // unevaluated (expr-templates F4).
    var exprParams: std.ArrayListUnmanaged(envMod.ExprParamInfo) = .empty;

    // Infer parameter types.
    var paramTypes = try env.arena.alloc(*T.Type, f.params.len);
    for (f.params, 0..) |p, i| {
        if (p.typeRef.isExprType()) {
            // An `@Expr<…>` parameter only exists at compile time — require the
            // `comptime` modifier so the binding-time is visible in the signature.
            if (p.modifier != .@"comptime") {
                env.lastError = TypeError.custom(
                    "an `@Expr` parameter requires the `comptime` modifier",
                    "Write it as `comptime name: @Expr<T>` — template arguments are captured at compile time.",
                ).withLoc(if (f.body.len > 0) f.body[0].expr.getLoc() else ast.Loc{ .line = 1, .col = 1 });
                return error.TypeError;
            }
            try exprParams.append(env.arena, .{ .paramIndex = i, .paramName = p.name });
        }
        if (p.typeRef == .typeparam) {
            const constraints = p.typeRef.typeparam;
            // Decision 575 (5) — `type<T>`, `T` one of the function's type
            // parameters, binds `T`: no constraint to check.
            const binds = constraints.len == 1 and constraints[0] == .named and for (f.genericParams) |gp| {
                if (std.mem.eql(u8, gp.name, constraints[0].named)) break true;
            } else false;
            const names = try env.arena.alloc([]const u8, if (binds) 0 else constraints.len);
            if (!binds) for (constraints, 0..) |c, ci| {
                names[ci] = switch (c) {
                    .named => |n| n,
                    else => "",
                };
            };
            try typeparams.append(env.arena, .{ .paramIndex = i, .paramName = p.name, .names = names });
        }
        // `fn(value: T) -> U` param: build a real func type (the typeRef is
        // just `.named "fn"`); names resolve via the generic map first.
        const ty = try resolveParamType(env, p, genericMap);
        paramTypes[i] = ty;
        if (p.destruct) |d| {
            // Destructuring param: bind each field name to its type.
            const tyName: []const u8 = switch (p.typeRef) {
                .named => |n| n,
                else => "",
            };
            const maybeTypeDef = env.typeDefs.get(tyName);
            switch (d) {
                .names => |*n| {
                    for (n.fields) |fld| {
                        const fieldTy = if (maybeTypeDef) |td|
                            if (td.findField(fld.field_name)) |f_| f_.type_ else try env.freshVar()
                        else
                            try env.freshVar();
                        try env.bind(fld.bind_name, fieldTy);
                    }
                },
                .tuple_ => |t| {
                    // For tuple destructuring, we'd need the tuple element types.
                    // For now, bind each name to a fresh type variable.
                    for (t) |fname| {
                        try env.bind(fname, try env.freshVar());
                    }
                },
                .list => {}, // List destructuring — no bindings to infer
                .ctor => {}, // Constructor destructuring — handled by pattern matching
            }
        } else if (p.exprWrapped) {
            // Decision 364 — the body holds the argument as the user's
            // expression, `Expr<T>`; its value is `x.value`.
            try env.bind(p.name, try env.namedTypeArgs(ast.expr_type_name, &.{ty}));
        } else {
            try env.bind(p.name, ty);
        }
    }
    const savedParams = env.currentParams;
    env.currentParams = f.params;
    defer env.currentParams = savedParams;

    // Infer return type.
    const retType = if (f.returnType) |rt|
        try resolveReturnType(env, rt, f.returnTypeLoc, genericMap)
    else
        try env.namedType("void");

    // The return type decides whether `use` is allowed in the body (a
    // `@Component<R>` return). Scope it to the body.
    const savedFnCtx = env.fnContext;
    env.fnContext = try contextInfoFromReturn(env, f.returnType, f.effect, f.name);
    defer env.fnContext = savedFnCtx;

    // `@src().fnName` inside this body (decision 73). A lambda in the body does
    // not change it — a lambda has no name.
    const savedFnName = env.currentFnName;
    env.currentFnName = f.name;
    defer env.currentFnName = savedFnName;

    // Decision 277 — a top-level function's body records its hook node: each
    // `use` and `@Component` call written in it, its lambdas' included.
    var hookBuilder: hooksMod.Builder = .{};
    const recordsHooks = isModuleFn(env, f);
    const savedHookBuilder = env.hookBuilder;
    env.hookBuilder = if (recordsHooks) &hookBuilder else null;
    defer env.hookBuilder = savedHookBuilder;
    // Decision 376 — a read of a `comptime` reflection parameter runs only at build.
    if (recordsHooks) hookBuilder.build = try hooksMod.buildResource(env.arena, f);

    // A `-> @Expr<…>` (or `-> @ExprCustom<…>`) return marks a template
    // function: its body runs at comptime, enabling the `@expr`/`@code`
    // construction builtins (and, for the custom carrier, `q.custom`).
    const savedInTemplate = env.inTemplateFn;
    env.inTemplateFn = if (f.returnType) |rt| rt.isTemplateReturnType() else false;
    defer env.inTemplateFn = savedInTemplate;
    const savedTemplateFn = env.currentTemplateFn;
    env.currentTemplateFn = if (env.inTemplateFn) f.name else null;
    defer env.currentTemplateFn = savedTemplateFn;
    // Decision 354 (3) — a decorator's body is compile-time evaluation with
    // no render tree: `use` there is refused.
    const savedInDecorator = env.inDecoratorFn;
    env.inDecoratorFn = isDecoratorParams(f.params);
    defer env.inDecoratorFn = savedInDecorator;
    // Decision 564 — a function expanded at its call site (562) may call a
    // behavior's function on a catalogue entry's `value`.
    const savedInExpansion = env.inExpansion;
    if (try hooksMod.isExpandedFn(env.arena, f)) env.inExpansion = true;
    defer env.inExpansion = savedInExpansion;
    // Decision 370 (2) — what a member function handed to `decl.addMember`
    // may not read.
    const savedDecoratorBody = env.decoratorBody;
    env.decoratorBody = if (env.inDecoratorFn or memberFn.isTemplateAnnotation(f)) f.body else null;
    defer env.decoratorBody = savedDecoratorBody;
    // Decision 354 — a component's body (its `R` implements `@Renderable`)
    // may `use provide`; where it first renders a child is tracked per body.
    if (env.fnContext) |*fc| fc.renderable = f.effect == .component and isComponentType(env, retType);
    const savedFirstRender = env.firstRenderAt;
    env.firstRenderAt = null;
    defer env.firstRenderAt = savedFirstRender;
    // Decision 357 — each body starts at its own top level.
    const savedUseConstruct = env.useConstruct;
    env.useConstruct = null;
    defer env.useConstruct = savedUseConstruct;
    const savedEarlyExit = env.earlyExitLine;
    env.earlyExitLine = null;
    defer env.earlyExitLine = savedEarlyExit;

    // Decision 118 — the effect is read from the SYNTACTIC return
    // (`f.effect`, set by the parser from the written wrapper). Decision 121 —
    // `throw` / `try` follow the fallible channel, computed from the return
    // apart from the level:
    //   - no declared return type          → unchecked (lenient: e.g. `catch throw …`)
    //   - a `@Result<U, E>` in some layer   → checked: the thrown value must be `E`;
    //     `return` / `throw` construct `{ok, V}` / `{error, E}` values
    //   - any other return type             → `throw` / `try` are illegal
    //     (`effect-try-without-fallible-channel`), or — under an alias to an
    //     effect wrapper — `effect-wrapper-behind-alias`
    const eff = f.effect;
    var throwCtx: envMod.ThrowContext = .unchecked;
    if (f.returnType) |_| {
        throwCtx = .plain;
        if (eff) |e| {
            if (fallibleErrorOf(e, retType)) |errTy| throwCtx = .{ .result = errTy };
        }
    }
    const savedThrowCtx = env.throwContext;
    env.throwContext = throwCtx;
    // Decision 595 — a region's `try`s stop at a function's border.
    const prevTryRegion = env.tryRegion;
    env.tryRegion = null;
    defer env.tryRegion = prevTryRegion;
    defer env.throwContext = savedThrowCtx;

    // Decision 118 rule 1 — an alias to an effect wrapper types the function
    // but activates nothing: a capability used in its body is refused as
    // `effect-wrapper-behind-alias`, naming the wrapper to write.
    const savedAliasWrapper = env.aliasWrapper;
    env.aliasWrapper = if (f.returnType != null and ast.EffectKind.fromReturnType(f.returnType) == null) aliasedWrapperOf(retType) else null;
    defer env.aliasWrapper = savedAliasWrapper;

    // Establish the effect context (saved/restored around the body) so nested
    // `await`/`yield` validate against this function, not an enclosing one.
    const prevStarFn = env.starFn;
    const prevLabelsLen = env.labelStack.items.len;
    defer {
        env.starFn = prevStarFn;
        env.labelStack.shrinkRetainingCapacity(prevLabelsLen);
    }
    if (eff) |e| {
        // Every effect gets a body context, whatever it grants: the chain
        // decides `allowsAwait` / `allowsYield`, and a capability it does not
        // grant is REFUSED at the site rather than skipped for want of a
        // context (decision 95 + 67).
        env.starFn = starCtxFromEffect(e, retType, f.label);
        if (f.label) |lbl| try env.labelStack.append(env.arena, lbl);
    } else {
        // A plain function body sees no effect context and no outer labels.
        env.starFn = null;
        env.labelStack.shrinkRetainingCapacity(0);
    }
    // The refusals name the body's effect: `env.fnEffect` is the return's.
    const savedFnEffect = env.fnEffect;
    env.fnEffect = eff;
    defer env.fnEffect = savedFnEffect;
    // `env.inContextFn` — the body of a `-> @Component<R>` fn. Decision 104 — this is the SAME flag as
    // `FnContext.annotated`: the `@Component` return sets both and nothing
    // else does. Save/restore it around the body so nested closures fall back
    // to false correctly.
    const savedInContextFn = env.inContextFn;
    env.inContextFn = eff == .component;
    defer env.inContextFn = savedInContextFn;

    // Self-recursion: bind the fn's own signature before walking the body so
    // `pushRange(out, start + 1, stop)` inside `pushRange` resolves. (Mutual
    // recursion across decls still needs a program-level pre-pass.)
    try env.bind(f.name, try env.funcType(paramTypes, retType));

    // Register type guard info for narrowing at call sites.
    if (f.typeGuardParam) |paramName| {
        // Find the parameter index matching the guard parameter name.
        var paramIndex: usize = 0;
        for (f.params, 0..) |p, i| {
            if (std.mem.eql(u8, p.name, paramName)) {
                paramIndex = i;
                break;
            }
        }
        // Record the narrowed type name (06 C5: its own slot, not `returnType`,
        // which a guard declares as `bool`).
        const narrowedName: []const u8 = if (f.typeGuardType) |gt| switch (gt) {
            .named => |n| n,
            else => paramName,
        } else paramName;
        try env.typeGuardFns.put(f.name, .{ .paramIndex = paramIndex, .narrowedTypeName = narrowedName });
    }

    // C1 — every `return <value>` in the body unifies with the declared
    // return type, or with an effect wrapper's inner channel.
    const savedReturnTarget = env.returnTarget;
    const savedReturnBareIsVoid = env.returnBareIsVoid;
    const savedReturnWhole = env.returnWhole;
    defer {
        env.returnTarget = savedReturnTarget;
        env.returnBareIsVoid = savedReturnBareIsVoid;
        env.returnWhole = savedReturnWhole;
    }
    env.returnWhole = if (f.returnType != null) retType else null;
    env.returnTarget = if (f.typeGuardParam != null)
        // A type guard (`-> x is T`) returns `bool`; `T` is the narrowed type.
        try env.namedType("bool")
    else
        returnTargetFor(retType, eff, f.returnType != null and !env.inTemplateFn);
    // Annotations inside the body see the fn's generic params (`var acc:
    // Array<#(P, O)> = []`), so a `return acc` unifies P with P, not with an
    // opaque named `P`.
    const savedFnGenericMap = env.fnGenericMap;
    env.fnGenericMap = &genericMap;
    defer env.fnGenericMap = savedFnGenericMap;
    const savedBodyParams = env.bodyParams;
    env.bodyParams = f.params;
    defer env.bodyParams = savedBodyParams;
    env.returnBareIsVoid = env.returnTarget != null and (eff == null or eff.? == .result or eff.? == .task);

    try refuseInlineParamRules(env, f);
    try refuseRedeclaredBindings(env, f.body, try paramNames(env, f.params));
    const tailTy = try inferBodyStmts(env, f.body);
    if (answersNothing(f.returnType) and f.typeGuardParam == null)
        try refuseValueTailInVoid(env, try std.fmt.allocPrint(env.arena, "`{s}`", .{f.name}), f.body, tailTy);
    try refuseFallingOffTheEnd(env, f, retType);
    if (recordsHooks) try finishHookNode(env, f, &hookBuilder);

    // Generalize (HM let-polymorphism): declared generic params still unbound
    // after the body is inferred become `.generic`. Every use site then gets a
    // fresh instantiation via `instantiateGenericType` — two calls in the same
    // scope never share vars. Params the body linked to a concrete type are
    // left alone (they were never polymorphic).
    var git = genericMap.valueIterator();
    while (git.next()) |gv| {
        const resolved = gv.*.deref();
        if (resolved.* != .typeVar) continue;
        const cell = resolved.typeVar;
        switch (cell.state) {
            .unbound => |u| cell.state = .{ .generic = u.id },
            else => {},
        }
    }

    if (typeparams.items.len > 0) {
        try env.registerTypeparams(f.name, try typeparams.toOwnedSlice(env.arena));
    }
    if (exprParams.items.len > 0) {
        try env.registerExprParams(f.name, try exprParams.toOwnedSlice(env.arena));
    }
    // A function returning `@Expr<T>` / `@ExprCustom<T>` is a template
    // function: its calls are expanded at comptime (F6) and the declaration
    // never reaches codegen.
    if (f.returnType) |rt| {
        if (rt.isTemplateReturnType()) try env.templateFns.put(f.name, f);
    }

    return env.funcType(paramTypes, retType);
}

/// A behavior's `default fn` bodies are checked like any method body, against
/// the member's own signature, with `self` typed as the behavior (`Self`):
/// `inferTypeMethods` over the members that carry a body. They were never
/// walked, so `return nothingHere(x) + true` checked clean and a `-> @Result`
/// default fn's `return` / `throw` recorded no wrapping for any backend.
fn inferBehaviorDefaultBodies(env: *Env, d: ast.BehaviorDecl) InferError!void {
    var n: usize = 0;
    for (d.methods) |m| {
        if (m.is_default and m.body != null) n += 1;
    }
    if (n == 0) return;
    const ms = try env.arena.alloc(ast.BehaviorMethod, n);
    var i: usize = 0;
    for (d.methods) |m| {
        if (!m.is_default or m.body == null) continue;
        ms[i] = m;
        i += 1;
    }
    // A default body is emitted once per implementer, where `self` is that
    // implementer: the backends dispatch its calls statically, so the
    // `.by_value` instance lowerings a `Self`-typed (behavior) receiver records
    // are dropped again — every other lowering (the `@Result` wrappings, the
    // `@Option` methods) stays.
    var before = std.AutoHashMap(ast.Loc, void).init(env.arena);
    defer before.deinit();
    var it = env.instanceLowerings.keyIterator();
    while (it.next()) |k| try before.put(k.*, {});
    // A primitive's behavior (`behavior String`, `behavior Array<T>`) types
    // `self` as the primitive (`string`, `array<T>`), so `self.length()` and
    // `stringSlice0(self, 1)` read the primitive's members and parameters.
    const selfName = primitiveOfInterface(d.name) orelse d.name;
    try inferTypeMethods(env, selfName, d.genericParams, ms);
    var added: std.ArrayListUnmanaged(ast.Loc) = .empty;
    var it2 = env.instanceLowerings.iterator();
    while (it2.next()) |e| {
        if (before.contains(e.key_ptr.*)) continue;
        // Decision 799 — a contract's member copied onto a primitive
        // (`adopt_defaults.zig`) is emitted for that primitive alone, at
        // lines of its own: a receiver it types as a primitive beside `self`
        // (`ys.all(…)` over `ys: Self<T>`) keeps its lowering.
        if (e.key_ptr.line >= adoptDefaults.first_line and e.value_ptr.* == .prim) continue;
        try added.append(env.arena, e.key_ptr.*);
    }
    for (added.items) |k| _ = env.instanceLowerings.remove(k);
}

/// Walk the bodies of a type's instance/associated methods (record / struct /
/// enum) to record the codegen instance-method lowerings (and type the calls
/// inside). Their signatures are registered earlier, but the bodies were never
/// walked — so a `self.xs.map(f)` call was neither typed nor recorded, and the
/// non-JS backends had no way to lower it.
///
/// Strict (06 C9): a type error in a method body fails the compile. A
/// behavior's `default fn` bodies come through here too
/// (`inferBehaviorDefaultBodies`).
fn inferTypeMethods(
    env: *Env,
    typeName: []const u8,
    typeGenerics: []const ast.GenericParam,
    methods: []const ast.BehaviorMethod,
) InferError!void {
    for (methods) |m| {
        const body = m.body orelse continue;
        if (m.is_declare) continue;
        // Decision 864 (4) — a method's record parameter is held to the same rules.
        try checkRecordParamList(env, m.name, m.params);

        // 01 step 13 — a method's parameters and locals end with its body.
        var bodyLog: std.ArrayListUnmanaged(Env.BindUndo) = .empty;
        const outerScope = env.openBodyScope(&bodyLog);
        defer env.closeBodyScope(&bodyLog, outerScope, m.name);

        // Decision 811 (1) — inside a method of `typeName`, an opaque
        // `typeName` is built and opened.
        const savedOpaqueOwner = env.opaqueOwner;
        env.opaqueOwner = typeName;
        defer env.opaqueOwner = savedOpaqueOwner;

        // `@src().fnName` inside a method is `Type.method` (decision 73).
        const savedFnName = env.currentFnName;
        env.currentFnName = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ typeName, m.name });
        defer env.currentFnName = savedFnName;

        var genericMap = std.StringHashMap(*T.Type).init(env.arena);
        defer genericMap.deinit();

        // `Self = Type<G0, G1, …>` over fresh generics shared with the params.
        const selfArgs = try env.arena.alloc(*T.Type, typeGenerics.len);
        for (typeGenerics, 0..) |gp, i| {
            const v = try env.freshVar();
            selfArgs[i] = v;
            try genericMap.put(gp.name, v);
        }
        const selfTy = if (typeGenerics.len == 0)
            try env.namedType(typeName)
        else
            try env.namedTypeArgs(typeName, selfArgs);
        try genericMap.put("Self", selfTy);

        // Method-level generics (`mapValues<C>`).
        for (m.genericParams) |gp| try genericMap.put(gp.name, try env.freshVar());
        const savedMethodGenericMap = env.methodGenericMap;
        env.methodGenericMap = &genericMap;
        defer env.methodGenericMap = savedMethodGenericMap;
        const savedBodyParams = env.bodyParams;
        env.bodyParams = m.params;
        defer env.bodyParams = savedBodyParams;

        // Bind parameters — a `self` receiver resolves through `Self`.
        for (m.params) |p| {
            const ty = try resolveParamType(env, p, genericMap);
            // Decision 364 — a `comptime x: @Expr<T>` is read `x.value`.
            try env.bind(p.name, if (p.exprWrapped) try env.namedTypeArgs(ast.expr_type_name, &.{ty}) else ty);
        }
        const savedParams = env.currentParams;
        env.currentParams = m.params;
        defer env.currentParams = savedParams;

        // Scope the return-type-derived `use`/effect context to this body.
        const savedFnCtx = env.fnContext;
        // Decision 118 — the method's return type is its effect, as a free
        // fn's is; decision 123 — an `@Iter` return that yields nothing is
        // a factory.
        const methodEffect = ast.EffectKind.ofMethod(m.returnType, m.body, m.marker);
        env.fnContext = try contextInfoFromReturn(env, m.returnType, methodEffect, m.name);
        env.fnContext.?.composeHelperOf = env.composedTypes.get(typeName);
        defer env.fnContext = savedFnCtx;
        // Decision 375, question 04s12-a — a `@Component` method is marked by
        // its body as a top-level function is (`Env.methodHooks`).
        var methodBuilder: hooksMod.Builder = .{};
        const marksMethod = methodEffect != null and methodEffect.? == .component and m.body != null;
        const savedMethodBuilder = env.hookBuilder;
        if (marksMethod) env.hookBuilder = &methodBuilder;
        defer env.hookBuilder = savedMethodBuilder;
        defer if (marksMethod) {
            env.methodHooks.put(env.arena, std.fmt.allocPrint(env.arena, "{s}.{s}", .{ typeName, m.name }) catch "", .{
                .uses = methodBuilder.uses.items,
                .calls = methodBuilder.calls.items,
                .dynamicCalls = methodBuilder.dynamicCalls.items,
                .is_async = methodBuilder.is_async,
            }) catch {};
        };
        // An effect annotation on a method is the method's, exactly as on a
        // free fn (decision 8 §9): the body gets the effect's context — a
        // generator method is a generator scope for its `yield`s (decision
        // 105), a plain method none.
        const savedStarFn = env.starFn;
        const savedFnEffect = env.fnEffect;
        const savedThrowCtx = env.throwContext;
        const savedLoopDepth = env.loopDepth;
        const prevTryRegion = env.tryRegion;
        env.tryRegion = null;
        defer env.tryRegion = prevTryRegion;
        const savedBreakScope = env.breakScope;
        const savedLabelsLen = env.labelStack.items.len;
        defer {
            env.starFn = savedStarFn;
            env.fnEffect = savedFnEffect;
            env.throwContext = savedThrowCtx;
            env.loopDepth = savedLoopDepth;
            env.breakScope = savedBreakScope;
            env.labelStack.shrinkRetainingCapacity(savedLabelsLen);
        }
        env.labelStack.shrinkRetainingCapacity(0);
        env.loopDepth = 0;
        env.breakScope = .none;
        if (methodEffect) |e| {
            const retTy = if (m.returnType) |rt| try resolveTypeRefInContext(env, rt, genericMap) else try env.freshVar();
            env.starFn = starCtxFromEffect(e, retTy, null);
            env.fnEffect = e;
            // Decision 121 — `throw` / `try` follow the fallible channel.
            env.throwContext = if (fallibleErrorOf(e, retTy)) |errTy| .{ .result = errTy } else .plain;
        } else {
            env.starFn = null;
            env.fnEffect = null;
        }
        // The declared return, whole: a returned value that is already that
        // wrapper (`return startApp(self)` in a `-> @Async<@Result<…>>` method)
        // passes through rather than being wrapped `Ok(…)` again
        // (`valuePassesThrough`), as in a free fn.
        const savedReturnWhole = env.returnWhole;
        defer env.returnWhole = savedReturnWhole;
        env.returnWhole = if (m.returnType) |rt| try resolveTypeRefInContext(env, rt, genericMap) else null;
        // C1 — every `return <value>` of an annotated method unifies with its
        // declared return, as a free fn's does; a member a decorator wrote
        // (`decl.addMember`) is checked the same way.
        const savedMethodReturnTarget = env.returnTarget;
        const savedMethodBareIsVoid = env.returnBareIsVoid;
        defer {
            env.returnTarget = savedMethodReturnTarget;
            env.returnBareIsVoid = savedMethodBareIsVoid;
        }
        env.returnTarget = if (env.returnWhole) |w| returnTargetFor(w, methodEffect, !env.inTemplateFn) else null;
        env.returnBareIsVoid = env.returnTarget != null and (methodEffect == null or methodEffect.? == .result or methodEffect.? == .task);

        // A method body is part of the strict contract, like a `default fn`
        // interface body (`inferInterfaceDefaultBodies`): a type error in it
        // fails the compile. Its return is the one it writes (decision 622 —
        // `refuseFnReturnMissing` refused a method writing none; nothing is
        // read off its `return`s, the inference 06 C9 added is gone).
        // The early-exit narrowing (`narrowAfterEarlyExit`) lives as long as
        // the block does, so it is collected here and restored below.
        var narrowed: std.ArrayListUnmanaged(PatternBindingSnapshot) = .empty;
        defer narrowed.deinit(env.arena);
        try refuseRedeclaredBindings(env, body, try paramNames(env, m.params));
        try noteStatementClosures(env, body);
        var tailTy: ?*T.Type = null;
        for (body, 0..) |stmt, si| {
            const deferFrame = if (stmt.deferred) enterDefer(env) else null;
            defer if (deferFrame) |f| leaveDefer(env, f);
            const typed = try inferExprTyped(env, stmt.expr);
            if (stmt.tail == .value) tailTy = typed.getType();
            try narrowAfterEarlyExit(env, stmt.expr, body[si + 1 ..], &narrowed);
        }
        if (narrowed.items.len > 0) try restorePatternBindings(env, narrowed.items);
        if (answersNothing(m.returnType))
            try refuseValueTailInVoid(env, try std.fmt.allocPrint(env.arena, "`{s}.{s}`", .{ typeName, m.name }), body, tailTy);
    }
}

/// The value layer of an effect return — what a `return` carries through the
/// wrapper (decision 119): `T` of `@Async<T>`, `T` of `@Component<T>`, the
/// item `T` of `@Iter<T>` / `@AsyncIter<T>`; the return itself for
/// `@Result<R, E>`, which IS the fallible layer.
fn effectValueLayer(eff: ast.EffectKind, retType: *T.Type) ?*T.Type {
    const t = retType.deref();
    if (t.* != .named) return null;
    const args = t.named.args;
    return switch (eff) {
        .result => retType,
        .task, .iterator, .stream => if (args.len >= 1) args[0] else null,
        .component => if (args.len >= 1) args[0] else null,
    };
}

/// True when `ty` resolves to `@Result<_, _>`.
fn isResultType(ty: *T.Type) bool {
    const t = ty.deref();
    return t.* == .named and std.mem.eql(u8, t.named.name, "Result");
}

/// Decision 121 — the fallible channel: the `E` of the `@Result<U, E>` layer
/// of an effect return (`@Result<U, E>` itself, `@Async<@Result<U, E>>`,
/// `@Component<@Result<U, E>>`, `@Iter<@Result<U, E>>`,
/// `@AsyncIter<@Result<U, E>>`), or null when no layer is a `@Result`. `throw`
/// and `try` read this and nothing else.
fn fallibleErrorOf(eff: ast.EffectKind, retType: *T.Type) ?*T.Type {
    const layer = effectValueLayer(eff, retType) orelse return null;
    const l = layer.deref();
    if (l.* != .named or !std.mem.eql(u8, l.named.name, "Result") or l.named.args.len < 2) return null;
    return l.named.args[1];
}

/// Decision 118 rule 1 — the effect wrapper an aliased return resolves to
/// (`Parser<i32>` → `Result`), or null when the resolved return is no effect
/// wrapper. Only asked of a return that is NOT written as the wrapper.
fn aliasedWrapperOf(retType: *T.Type) ?[]const u8 {
    const t = retType.deref();
    if (t.* != .named) return null;
    const e = ast.EffectKind.fromWrapperName(t.named.name) orelse return null;
    return e.returnWrapper();
}

/// C1 — the type a `return <value>` unifies with inside a fn whose declared
/// return type is `retType` (decision 119: `return` wraps through every
/// layer): the value layer of the effect's wrapper — and, when that layer is
/// `@Result<U, E>`, its `U` — the declared type otherwise. Null when returns
/// are not checked: no declared return type, a template fn, or a sequence
/// body (`@Iter` / `@AsyncIter` that yields, which forbids `return <expr>`).
/// 01 R7 — decision 2: a block is a statement, and a value leaves a body
/// through `return` (or a `break` of a value block). A plain `fn` whose written
/// return type has a value and whose body can reach its end without one used
/// to check — `fn f() -> i32 { val x = 1; }` — and each backend answered
/// whatever its block-as-value lowering produced. Refused at the return type.
/// A wrapper return is judged by what a fall-through would hand out: a
/// `@Result` in any layer (`@Result<void, E>` included) has a value — `Ok` or
/// `Error` — and its `ok` position is the empty `return;` (decision 74), so it
/// is refused like any value; a `@Async` / `@Component` whose value layer is a
/// value type is refused too; one whose value layer is `void` or `noreturn`
/// falls through as a `void` fn does. `@Iter` / `@AsyncIter` end by running
/// off their body and are not judged here; neither is a type guard.
/// 01 R7 — decision 2's other half: an `if` in value position needs both
/// branches, each ending in a value. `val y = if (c) { 1 };` checked and bound
/// whatever each backend's block-as-value lowering produced when `c` is false.
fn refuseValuelessIf(env: *Env, value: ast.Expr) InferError!void {
    if (value != .branch) return;
    const i = switch (value.branch.kind) {
        .if_ => |i| i,
        else => return,
    };
    if (i.else_ == null) {
        env.lastError = TypeError.custom(
            "an `if` without `else` has no value on its false side",
            "Give it an `else` branch, or bind the value inside the branch (decision 2: a block is a statement).",
        ).withLoc(value.branch.loc);
        return error.TypeError;
    }
}

fn refuseFallingOffTheEnd(env: *Env, f: ast.FnDecl, retType: *T.Type) InferError!void {
    if (f.returnType == null or f.typeGuardParam != null or f.isDeclare) return;
    if (env.inTemplateFn) return;
    if (f.isExternal()) return;
    const rt = retType.deref();
    if (f.effect) |eff| {
        switch (eff) {
            .iterator, .stream => return,
            .result => {},
            .task, .component => {
                const layer = (effectValueLayer(eff, retType) orelse return).deref();
                if (layer.* != .named) return;
                if (!std.mem.eql(u8, layer.named.name, "Result") and
                    (std.mem.eql(u8, layer.named.name, "void") or std.mem.eql(u8, layer.named.name, "noreturn"))) return;
            },
        }
    } else if (rt.* == .named and (std.mem.eql(u8, rt.named.name, "void") or std.mem.eql(u8, rt.named.name, "noreturn"))) return;
    if (!stmtsMayFallThrough(env, f.body)) return;
    const rendered = try snapshotMod.typeNameOf(env.arena, rt);
    const msg = try std.fmt.allocPrint(env.arena, "`{s}` declares `-> {s}` and its body can reach its end without a `return`", .{ f.name, rendered });
    // Decision 570 — an unmarked `-> Async<T>` / `-> Component<R>` body is an
    // ordinary function: the hint names the marker that would wrap its value.
    const hint: []const u8 = if (f.effect == null and unmarkedWrapper(retType) != null)
        try unmarkedWrapperHint(env, unmarkedWrapper(retType).?)
    else
        "A value leaves a function through `return` (decision 2): end every path with `return <value>;`, or `@panic(…)` / `@todo()` where it cannot happen.";
    var err = TypeError.custom(msg, hint);
    if (f.returnTypeLoc.line > 0) err = err.withLoc(f.returnTypeLoc) else if (f.body.len > 0) err = err.withLoc(f.body[0].expr.getLoc());
    env.lastError = err;
    return error.TypeError;
}

/// Whether control can run off the end of `stmts` — the last statement is not
/// a `return` / `throw`, an `if`/`else` or `case` whose every branch ends that
/// way, a `loop { }` (left only by `break` or `return`), or a call to a
/// `noreturn` builtin. Conservative the right way: anything it cannot read is
/// "may fall through" only where the statement plainly has no exit. Read on
/// either phase: a fn's parsed body, and a typed one.
fn stmtsMayFallThrough(env: *Env, stmts: anytype) bool {
    // A trailing comment is kept as a statement by the parser and is not one.
    var n = stmts.len;
    while (n > 0) : (n -= 1) {
        const e = stmts[n - 1].expr;
        if (e == .literal and e.literal.kind == .comment) continue;
        return exprMayFallThrough(env, e);
    }
    return true;
}

fn exprMayFallThrough(env: *Env, e: anytype) bool {
    return switch (e) {
        .jump => |j| switch (j.kind) {
            .@"return", .throw_, .@"break", .@"continue" => false,
            else => true,
        },
        .branch => |b| switch (b.kind) {
            .if_ => |i| blk: {
                const els = i.else_ orelse break :blk true;
                break :blk stmtsMayFallThrough(env, i.then_) or stmtsMayFallThrough(env, els);
            },
            else => true,
        },
        // A bare `loop { }` is left only by `break` (which ends the loop, and
        // the body falls through after it) or by `return`; which one is not
        // read here, so it is not refused — the lenient answer, never a false
        // refusal. `while` and `for` can always end normally.
        .loop => |l| l.keyword != .loop,
        .collection => |c| switch (c.kind) {
            .case => |cs| blk: {
                if (cs.arms.len == 0) break :blk true;
                for (cs.arms) |arm| if (exprMayFallThrough(env, arm.body)) break :blk true;
                break :blk false;
            },
            .grouped => |g| exprMayFallThrough(env, g.*),
            else => true,
        },
        .function => |fe| stmtsMayFallThrough(env, fe.kind.body),
        .call => |c| switch (c.kind) {
            .call => |cc| !callNeverReturns(env, cc),
            else => true,
        },
        else => true,
    };
}

/// Decision 570 — the marker a `-> Async<T>` / `-> Component<R>` return
/// names, or null for any other return: without it the body is an ordinary
/// function and returns the whole type.
fn unmarkedWrapper(retType: *T.Type) ?ast.EffectKind {
    const d = retType.deref();
    if (d.* != .named) return null;
    if (std.mem.eql(u8, d.named.name, "Async")) return .task;
    if (std.mem.eql(u8, d.named.name, "Component")) return .component;
    return null;
}

/// Decision 570 — the hint for an unmarked `-> Async<T>` / `-> Component<R>`
/// body: the marker that wraps the value, and `Async.resolve` for a task.
fn unmarkedWrapperHint(env: *Env, eff: ast.EffectKind) ![]const u8 {
    return switch (eff) {
        .task => "An unmarked function returns the whole `Async<T>` (decision 570): write `async fn` to return the value and let the marker wrap it, or return `Async.resolve(v)`.",
        else => try std.fmt.allocPrint(env.arena, "An unmarked function returns the whole `{s}<…>` (decision 570): write `{s} fn` to return the value and let the marker wrap it.", .{ eff.returnWrapper(), eff.markerWord() }),
    };
}

/// Decision 570 — a `return v` in an unmarked `-> Async<T>` /
/// `-> Component<R>` body whose `v` is no such wrapper: a type mismatch (the
/// body returns the whole type), named so, its hint naming the marker and
/// `Async.resolve`. Only where the return target IS the whole declared type
/// (an unmarked fn or method); a value still unresolved is left to unify.
fn refuseBareValueInUnmarked(env: *Env, target: *T.Type, value: *T.Type, loc: ast.Loc) InferError!void {
    const whole = env.returnWhole orelse return;
    if (whole != target) return;
    const eff = unmarkedWrapper(target) orelse return;
    const v = value.deref();
    if (v.* == .typeVar) return;
    if (v.* == .named) {
        if (std.mem.eql(u8, v.named.name, eff.returnWrapper())) return;
        if (std.mem.eql(u8, v.named.name, "noreturn")) return;
    }
    const expected = try snapshotMod.typeSignatureOf(env.arena, target);
    const got = try snapshotMod.typeSignatureOf(env.arena, value);
    const msg = try std.fmt.allocPrint(env.arena, "type mismatch: expected {s}, got {s} — this body carries no `{s}` marker, so it returns the whole `{s}`", .{ expected, got, eff.markerWord(), expected });
    env.lastError = TypeError.custom(msg, try unmarkedWrapperHint(env, eff)).withLoc(loc);
    return error.TypeError;
}

fn returnTargetFor(retType: *T.Type, eff: ?ast.EffectKind, checked: bool) ?*T.Type {
    if (!checked) return null;
    const e = eff orelse return retType;
    if (retType.deref().* != .named) return null;
    return switch (e) {
        .result => blk: {
            const args = retType.deref().named.args;
            break :blk if (args.len >= 1) args[0] else null;
        },
        .task, .component => blk: {
            const layer = effectValueLayer(e, retType) orelse break :blk null;
            const l = layer.deref();
            if (l.* == .named and std.mem.eql(u8, l.named.name, "Result") and l.named.args.len >= 1) break :blk l.named.args[0];
            break :blk layer;
        },
        .iterator, .stream => null,
    };
}

/// Build the effect body context (drives `await`/`yield` validation) from the
/// effect kind and its return type. EVERY effect gets one — `env.starFn` is
/// null only in a plain `fn` — so a capability the chain does not grant is
/// refused rather than falling through an absent context (decision 95 + 67).
fn starCtxFromEffect(eff: ast.EffectKind, retType: *T.Type, fnLabel: ?[]const u8) envMod.StarFnCtx {
    // `iterItem` is the one item channel: only `@Iter` / `@AsyncIter` carry
    // it, and both `yield <v>` and a sequence-level `break <v>` unify with it
    // (decision 122 — there is no completion channel).
    const yields = effectChain.grants(eff, .yield_);
    return .{
        .allowsAwait = effectChain.grants(eff, .await_),
        .allowsYield = yields,
        .iterItem = if (yields) effectValueLayer(eff, retType) else null,
        .fnLabel = fnLabel,
        .effect = eff,
    };
}

// ── expression inference ──────────────────────────────────────────────────────

/// The `InstanceLowering.division` an arithmetic operator of result type `t`
/// records: the integer type (onze F7's truncating `/`, decision 264's range
/// check), a float, or nothing while `t` is unresolved or not a number (a
/// string `+`).
pub fn arithKind(t: *T.Type) ?envMod.ArithKind {
    const d = t.deref();
    if (isFloatType(d)) return .float;
    inline for (@typeInfo(envMod.ArithKind).@"enum".fields) |f| {
        if (f.value != @intFromEnum(envMod.ArithKind.float) and d.isNamed(f.name)) return @enumFromInt(f.value);
    }
    return null;
}

fn isIntType(t: *T.Type) bool {
    return t.isNamed("i8") or t.isNamed("u8") or
        t.isNamed("i16") or t.isNamed("u16") or
        t.isNamed("i32") or t.isNamed("u32") or
        t.isNamed("i64") or t.isNamed("u64") or
        t.isNamed("isize") or t.isNamed("usize");
}

fn isFloatType(t: *T.Type) bool {
    return t.isNamed("f32") or t.isNamed("f64");
}

/// True when `t` satisfies a single typeparam constraint named `name`.
/// Besides exact name matches, the category names `int` and `float` match any
/// integer / floating-point primitive respectively.
fn typeSatisfiesConstraint(t: *T.Type, name: []const u8) bool {
    if (t.isNamed(name)) return true;
    if (std.mem.eql(u8, name, "int")) return isIntType(t);
    if (std.mem.eql(u8, name, "float")) return isFloatType(t);
    return false;
}

/// True when index `i` names a typeparam parameter in `constraints`.
fn isTypeparamIndex(constraints: []const envMod.TypeparamConstraint, i: usize) bool {
    for (constraints) |c| {
        if (c.paramIndex == i) return true;
    }
    return false;
}

/// The `expr` param info for parameter index `i`, or null when `i` is an
/// ordinary parameter.
fn exprParamAt(params: []const envMod.ExprParamInfo, i: usize) ?envMod.ExprParamInfo {
    for (params) |p| {
        if (p.paramIndex == i) return p;
    }
    return null;
}

/// Type-check and capture an argument bound to a `comptime p: expr T`
/// parameter (expr-templates F4). The argument unifies against the **inner**
/// `T` — it is an expression *of* `T`, not a value of `expr T` — and is
/// captured unevaluated with provenance (module path, location, origin-scope
/// snapshot) for the call-site expansion pass (F6).
///
/// V1 rule (spec): a source-capable template requires a **literal** string at
/// the call site (single or multiline, interpolation allowed) — a variable
/// carries no span or scope to attach.
fn captureExprArg(
    env: *Env,
    callee: []const u8,
    param: envMod.ExprParamInfo,
    rawArg: *const ast.Expr,
    typedArg: ast.CallArgOf(.typed),
    paramType: *T.Type,
    templateText: ?[]const u8,
) InferError!template.CapturedExpr {
    // Inner `T` of `expr T` (`expr` is encoded as a named type with one arg);
    // a bare `expr` param already carries a fresh var as its arg.
    const pDeref = paramType.deref();
    const inner: *T.Type = if (pDeref.* == .named and pDeref.named.args.len == 1)
        pDeref.named.args[0]
    else
        try env.freshVar();
    // Decision 719 — a `syntax` parameter of a type other than `string`
    // takes the expression written between the call's parentheses: checked
    // once against the parameter's declared type (716), as an argument is,
    // and captured as code, never executed at the call (720). Its text is
    // the expression as written (`compiler.text`), its location the
    // argument's (`compiler.source`).
    const expression = if (env.templateFns.get(callee)) |tfn| ast.syntaxExprIndex(tfn.params) != null else false;
    if (expression) {
        try unifyArgument(env, inner, typedArg.value.getType(), typedArg.value.getLoc());
        return template.CapturedExpr{
            .callee = callee,
            .paramIndex = param.paramIndex,
            .paramName = param.paramName,
            .node = rawArg,
            .text = try defaultLexeme(env.arena, rawArg.*),
            .multiline = false,
            .loc = rawArg.getLoc(),
            .modulePath = env.modulePath,
            .srcFile = env.srcPathOf(env.modulePath),
            .scope = env.scopeSnapshot,
        };
    }
    try unifyAt(env, inner, typedArg.value.getType(), typedArg.value.getLoc());

    // V1 literal rule. `text` stays null for `${…}` templates — the parts
    // live on the captured node. A hole-less multiline literal arrives as a
    // plain `stringLit` whose content keeps the `\n` after the opening `"""`,
    // so newline presence doubles as the multiline flag.
    var text: ?[]const u8 = null;
    var multiline = false;
    var isLiteral = false;
    // `newlines` only decides `multiline` for a hole-less literal: the lexer
    // stamps every token with the line it STARTS on, so a multiline literal's
    // loc is already its opening `"""` and needs no adjustment. (It used to
    // carry the CLOSING line, which this function compensated for by
    // subtracting the content's newlines.)
    var newlines: usize = 0;
    if (rawArg.* == .literal) {
        switch (rawArg.literal.kind) {
            .stringLit => |s| {
                // Decision 577 — a template text `@`…`` is its raw bytes,
                // which the literal spells escaped.
                text = templateText orelse s;
                newlines = std.mem.count(u8, text.?, "\n");
                multiline = newlines > 0;
                isLiteral = true;
            },
            .stringTemplate => |t| {
                multiline = t.multiline;
                // `${…}` holes are assumed single-line in V1.
                for (t.parts) |p| switch (p) {
                    .text => |s| newlines += std.mem.count(u8, s, "\n"),
                    .expr => {},
                };
                isLiteral = true;
            },
            else => {},
        }
    }
    if (!isLiteral) {
        env.lastError = TypeError.custom(
            "a `syntax` argument must be a literal string at the call site",
            "Write the template inline — `f \"\"\"…\"\"\"` or `f(\"…\")`; a variable carries no span or scope to capture (V1).",
        ).withLoc(typedArg.value.getLoc());
        return error.TypeError;
    }

    const valueRead = if (env.templateFns.get(callee)) |tfn| syntaxParam.useOf(tfn, param.paramName).value else false;

    const litLoc = rawArg.getLoc();
    return template.CapturedExpr{
        .callee = callee,
        .paramIndex = param.paramIndex,
        .paramName = param.paramName,
        .node = rawArg,
        .text = text,
        .multiline = multiline,
        .templateText = templateText != null,
        .loc = litLoc,
        .modulePath = env.modulePath,
        .srcFile = env.srcPathOf(env.modulePath),
        .scope = env.scopeSnapshot,
        .valueRead = valueRead,
    };
}

/// Register a template function imported from another module (expr-templates
/// F6-full): the export registry carries the full `FnDecl` so the importing
/// module can expand its calls. Derives the `@Expr` param infos the call-site
/// capture logic needs. NOTE (V1 hygiene caveat, recorded): code the template
/// builds re-infers in the *caller's* scope — library helpers it references
/// must be visible there.
pub fn registerImportedTemplateFn(env: *Env, name: []const u8, decl: ast.FnDecl, owner: []const u8) !void {
    try env.templateFns.put(name, decl);
    try env.noteComptimeOwner(decl, owner);
    var infos: std.ArrayListUnmanaged(envMod.ExprParamInfo) = .empty;
    for (decl.params, 0..) |p, i| {
        if (p.typeRef.isExprType()) {
            try infos.append(env.arena, .{ .paramIndex = i, .paramName = p.name });
        }
    }
    if (infos.items.len > 0) {
        try env.registerExprParams(name, try infos.toOwnedSlice(env.arena));
    }
}

/// Register a nominal type (record/struct/enum) imported from another module.
/// The export registry carries the full declaration so the importing module can
/// rebuild the `TypeDef` — its `implements` / `renderable` and fields, not just
/// the constructor value binding. Without this, an imported type's `implement`
/// clause is invisible here (e.g. the `use`-legality check `contextInfoFromReturn`
/// looks up `env.lookupTypeDef` and would find nothing). This mirrors the
/// `from "std"` type-export path, which re-runs `registerTypeDecl` over the
/// module's `pub` type decls. Registering in the importing env also re-binds the
/// constructor with this module's own type ids.
pub fn registerImportedTypeDecl(env: *Env, decl: ast.DeclKind) !void {
    try registerTypeDecl(env, decl);
}

/// Decision 110 rule 1 — `import {Dict as D}`: the alias is a local name of
/// the imported type (or type alias) IN THE CHECKER ONLY. The declaration is
/// registered under its own name (the emitted identity, decision 109), and
/// `alias` becomes a checker-local type alias of it with the same parameters
/// (`D<K, V>` is `Dict<K, V>`), erased before the backends like any alias.
/// A value use of the alias — the constructor `D(…)` — is renamed to the
/// declared name at the call (`Env.importedTypeAliases`, read by
/// `inferCallExpr`), so no backend sees `D`.
pub fn registerImportedTypeAlias(env: *Env, decl: ast.DeclKind, alias: []const u8, loc: ast.Loc) !void {
    const real: []const u8 = switch (decl) {
        .type_ => |t| t.name,
        .typeAlias => |a| a.name,
        else => return,
    };
    const params: []ast.GenericParam = switch (decl) {
        .type_ => |t| t.genericParams,
        .typeAlias => |a| a.genericParams,
        else => &.{},
    };
    const target: ast.TypeRef = if (params.len == 0) .{ .named = real } else blk: {
        const args = try env.arena.alloc(ast.TypeRef, params.len);
        for (params, 0..) |gp, i| args[i] = .{ .named = gp.name };
        break :blk .{ .generic = .{ .name = real, .args = args, .is_builtin = false } };
    };
    try env.typeAliases.put(env.arena, alias, .{
        .name = alias,
        .genericParams = params,
        .target = target,
        .loc = loc,
        .targetLoc = loc,
    });
    try env.importedTypeAliases.put(env.arena, alias, real);
    if (env.lookup(real)) |ctor| {
        try env.bind(alias, ctor);
        try env.importedTypeAliasCtors.put(env.arena, alias, ctor);
    }
}

/// Decision 310 — `import {m1.T as A}` beside an import of another module's
/// `T`: the declaration is registered under the alias, which is the type's
/// identity in this module (`Env.renamedTypeImports`); its own name in its
/// signatures is renamed with it. No checker alias is bound and no
/// constructor call renamed: the backends see the alias and map it back to
/// the declared name in its module.
pub fn registerRenamedImportedType(env: *Env, t: ast.TypeDecl, alias: []const u8) !void {
    try registerTypeDecl(env, .{ .type_ = try typeIdentity.renameDecl(env.arena, t, t.name, alias) });
}

/// Decision 310 — the type of a value imported from `owner`, its signature's
/// types renamed to this module's identities: a type `owner` names that is
/// one of `Env.renamedTypeImports` is spelled by its alias here (`site`'s
/// `makeSite() -> App` answers `SiteApp` where `App` is `srv`'s). Unchanged
/// when this module renames no type.
pub fn renameImportedType(env: *Env, ty: *T.Type, owner: []const u8) !*T.Type {
    if (env.renamedTypeImports.count() == 0) return ty;
    const Ctx = struct {
        env: *Env,
        owner: []const u8,
        pub fn rename(self: @This(), name: []const u8) ?[]const u8 {
            const module = renamedTypeOwner(self.env, self.owner, name) orelse return null;
            var it = self.env.renamedTypeImports.iterator();
            while (it.next()) |e| {
                if (std.mem.eql(u8, e.value_ptr.name, name) and std.mem.eql(u8, e.value_ptr.module, module)) return e.key_ptr.*;
            }
            return null;
        }
    };
    return typeIdentity.renameType(env.arena, ty, Ctx{ .env = env, .owner = owner }, 0);
}

/// The module that declares the type `owner` names `name` — `owner` itself,
/// or, for a type it imported, the module of the renamed import whose
/// declaration it is. Null when `name` is no renamed import's declared name.
fn renamedTypeOwner(env: *Env, owner: []const u8, name: []const u8) ?[]const u8 {
    var candidate = false;
    for (env.renamedTypeImports.values()) |v| if (std.mem.eql(u8, v.name, name)) {
        candidate = true;
    };
    if (!candidate) return null;
    const registry = env.typeDeclRegistry orelse return null;
    const decls = registry.get(owner) orelse return null;
    if (decls.contains(name)) return owner;
    var key_buf: [256]u8 = undefined;
    const key = std.fmt.bufPrint(&key_buf, "{s}{s}", .{ comptimeMod.imported_type_scope_prefix, name }) catch return null;
    const scoped = decls.get(key) orelse return null;
    if (scoped != .type_) return null;
    for (env.renamedTypeImports.values()) |v| {
        if (!std.mem.eql(u8, v.name, name)) continue;
        const d = (registry.get(v.module) orelse continue).get(name) orelse continue;
        if (d == .type_ and sameTypeDecl(d.type_, scoped.type_)) return v.module;
    }
    return null;
}

/// One parsed declaration reached through two registries (by its location and
/// its member list, which the copies share).
fn sameTypeDecl(a: ast.TypeDecl, b: ast.TypeDecl) bool {
    if (a.loc.line != b.loc.line or a.loc.col != b.loc.col) return false;
    return switch (a.shape) {
        .record => |fs| b.shape == .record and b.shape.record.ptr == fs.ptr,
        .enum_ => |e| b.shape == .enum_ and b.shape.enum_.variants.ptr == e.variants.ptr,
    };
}

/// 01 R2 — importing a type registers the closure of the types its
/// declaration mentions (field types and method signature types,
/// transitively) from the module it comes from, so `import { User }` works
/// when `User(role: Role)` and `Role` was not named in the clause. Each type
/// of the closure is registered as a TYPE only: the constructor and variant
/// bindings its registration adds are removed again — naming it in the
/// import is what brings its constructor into scope. Call before registering
/// `decl` itself: its fields resolve against the closure. A type the
/// module imported from a third one is found under the `"\x00"` scope key
/// `comptime.registerExports` writes (onze F2).
pub fn registerImportedTypeClosure(
    env: *Env,
    moduleDecls: std.StringHashMap(ast.DeclKind),
    decl: ast.DeclKind,
) !void {
    try registerTypeClosureDepth(env, moduleDecls, decl, 0);
}

fn registerTypeClosureDepth(
    env: *Env,
    moduleDecls: std.StringHashMap(ast.DeclKind),
    decl: ast.DeclKind,
    depth: usize,
) !void {
    if (depth >= 32) return;
    if (decl == .typeAlias) return registerAliasClosure(env, moduleDecls, decl.typeAlias, depth);
    if (decl != .type_) return;
    const td = decl.type_;
    var names: std.ArrayListUnmanaged([]const u8) = .empty;
    defer names.deinit(env.arena);
    for (td.recordFields()) |f| try collectTypeRefNames(env, f.typeRef, &names);
    for (td.variants()) |v| for (v.fields) |f| try collectTypeRefNames(env, f.typeRef, &names);
    for (td.methods) |m| {
        for (m.params) |p| try collectTypeRefNames(env, p.typeRef, &names);
        if (m.returnType) |rt| try collectTypeRefNames(env, rt, &names);
    }
    try registerTypesOnly(env, moduleDecls, names.items, td.name, depth);
}

/// 01 R2 for an imported FUNCTION: the types its signature names (a
/// `matchPath(…) -> ?RouteMatch` imported without `RouteMatch`) are registered
/// as types only, from the module it comes from, like a type's closure — so a
/// value it returns has its fields and methods here. Naming the type in the
/// import is still what brings its constructor into scope.
pub fn registerImportedSignatureClosure(
    env: *Env,
    moduleDecls: std.StringHashMap(ast.DeclKind),
    ty: *T.Type,
) !void {
    var names: std.ArrayListUnmanaged([]const u8) = .empty;
    defer names.deinit(env.arena);
    try collectTypeNames(env, ty, &names, 0);
    try registerTypesOnly(env, moduleDecls, names.items, "", 0);
}

fn collectTypeNames(env: *Env, ty: *T.Type, out: *std.ArrayListUnmanaged([]const u8), depth: usize) !void {
    if (depth >= 32) return;
    const t = ty.deref();
    switch (t.*) {
        .named => |n| {
            try out.append(env.arena, n.name);
            for (n.args) |a| try collectTypeNames(env, a, out, depth + 1);
        },
        .func => |f| {
            for (f.params) |p| try collectTypeNames(env, p, out, depth + 1);
            try collectTypeNames(env, f.ret, out, depth + 1);
        },
        .union_ => |us| for (us) |u| try collectTypeNames(env, u, out, depth + 1),
        else => {},
    }
}

/// Register each of `names` the module declares (or imports, under the scope
/// prefix) as a TYPE only, with its own closure first; `self_name` is skipped.
fn registerTypesOnly(
    env: *Env,
    moduleDecls: std.StringHashMap(ast.DeclKind),
    names: []const []const u8,
    self_name: []const u8,
    depth: usize,
) InferError!void {
    for (names) |n| {
        if (std.mem.eql(u8, n, self_name)) continue;
        if (env.lookupTypeDef(n) != null) continue;
        // A type the module imported rather than declared is in its map
        // under the scope prefix (`comptime.imported_type_scope_prefix`).
        const dep = moduleDecls.get(n) orelse blk: {
            var buf: [256]u8 = undefined;
            if (n.len + 1 > buf.len) continue;
            buf[0] = 0;
            @memcpy(buf[1 .. n.len + 1], n);
            break :blk moduleDecls.get(buf[0 .. n.len + 1]) orelse continue;
        };
        if (dep == .typeAlias) {
            try registerAliasClosure(env, moduleDecls, dep.typeAlias, depth + 1);
            continue;
        }
        if (dep != .type_) continue;
        try registerTypeClosureDepth(env, moduleDecls, dep, depth + 1);
        if (env.lookupTypeDef(n) != null) continue;
        // Register the type, then take back the bindings it added.
        var before = std.StringHashMap(void).init(env.arena);
        defer before.deinit();
        var kit = env.bindings.keyIterator();
        while (kit.next()) |k| try before.put(k.*, {});
        try registerTypeDecl(env, dep);
        var added: std.ArrayListUnmanaged([]const u8) = .empty;
        defer added.deinit(env.arena);
        var ait = env.bindings.keyIterator();
        while (ait.next()) |k| if (!before.contains(k.*)) try added.append(env.arena, k.*);
        for (added.items) |k| {
            if (env.bindings.get(k)) |ty| try env.typeOnlyCtors.put(k, ty);
            _ = env.bindings.remove(k);
        }
    }
}

fn collectTypeRefNames(env: *Env, ref: ast.TypeRef, out: *std.ArrayListUnmanaged([]const u8)) !void {
    switch (ref) {
        .named => |n| try out.append(env.arena, n),
        .array => |e| try collectTypeRefNames(env, e.*, out),
        .optional => |e| try collectTypeRefNames(env, e.*, out),
        .tuple_ => |es| for (es) |e| try collectTypeRefNames(env, e, out),
        .labeledTuple => |lt| for (lt.elems) |e| try collectTypeRefNames(env, e, out),
        .function => |f| {
            for (f.params) |e| try collectTypeRefNames(env, e, out);
            try collectTypeRefNames(env, f.returnType.*, out);
        },
        .generic => |g| {
            try out.append(env.arena, g.name);
            for (g.args) |e| try collectTypeRefNames(env, e, out);
        },
        .typeparam => |cs| for (cs) |e| try collectTypeRefNames(env, e, out),
    }
}

// ── template call-site expansion (expr-templates F6, V1 driver) ───────────────

/// Expand a call to a template function (`-> @Expr<…>`) at the call site.
///
/// The V1 driver expands bodies of the form `return E` where `E` is an
/// identifier naming an `@Expr` parameter (pass-through: the captured
/// template splices in), `@expr(E)` (explicit value/expression lift), or
/// `@code("…")` (parse generated source text into code). Construction is
/// always explicit — there is no implicit value lifting. Richer bodies
/// (template methods, control flow) need the comptime evaluation runtime —
/// F6-full, not this driver.
///
/// Splice + re-check: the expansion is re-inferred in the *caller's*
/// environment, then checked against a bounded return (`-> @Expr<T>`); a
/// bare `-> @Expr` reveals the expansion's own structural type per call
/// site. The expansion is recorded in `env.templateExpansions` (keyed by
/// call loc) and substituted into the untyped AST by the transform pass —
/// codegen never sees the call or the template function.
fn expandTemplateCall(
    env: *Env,
    tfn: ast.FnDecl,
    captures: []const template.CapturedExpr,
    plainArgs: []const template.PlainArg,
    retType: *T.Type,
    loc: ast.Loc,
) InferError!TypedExpr {
    // Decision 798 (2) — the expansion's origin, for `--emit-resolved`.
    try env.noteExpansionOrigin(loc, tfn);
    // Decision 353 — a body reading the program's catalogue is never reduced
    // by inspection: its queries are answered where the module is built.
    const reads_catalogue = (try templateQueriesOf(env, env.comptimeOwnerOf(tfn), tfn)).len > 0;
    const body = (if (reads_catalogue) null else classifyTemplateBody(tfn, captures)) orelse {
        // Not reducible by inspection — run the body in the eval runtime
        // (F6-full). Tooling paths carry no eval context and keep the error.
        if (env.templateEval != null) {
            return expandTemplateCallViaRuntime(env, tfn, captures, plainArgs, retType, loc);
        }
        env.lastError = TypeError.custom(
            "cannot expand this template function at compile time",
            "The V1 expansion driver supports bodies of the form `return <@Expr param>`, `return @expr(value)`, or `return @code(\"…\")` with a literal string; richer bodies need the eval runtime (full `compile` pipeline).",
        ).withLoc(loc);
        return error.TypeError;
    };

    const expansion: *const ast.Expr = switch (body) {
        .capture, .lifted => |node| node,
        .code => |src| parseCodeText(env, src, builtCodeOrigin(env, captures, loc)) orelse {
            env.lastError = TypeError.custom(
                "the `@code(…)` text does not parse as an expression",
                "The string handed to `@code` must be a single well-formed botopink expression.",
            ).withLoc(loc);
            return error.TypeError;
        },
    };

    return finishExpansionBuilt(env, expansion, retType, loc, .{ .callee = tfn.name });
}

/// The synthesised type of a `"std"` module or namespace receiver
/// (`bool.negate(x)`), which is no value.
fn isStdModuleType(t: *T.Type) bool {
    const d = t.deref();
    return d.* == .named and std.mem.eql(u8, d.named.name, "#std_module");
}

/// The template method `name` names (decisions 311 (3), 415 (1)): a template
/// function of the call site's scope — imported or this module's — whose
/// first parameter is `comptime self: @Expr<R>`.
fn templateMethodNamed(env: *Env, name: []const u8) ?ast.FnDecl {
    const tfn = templateFnNamed(env, name) orelse return null;
    return if (ast.isTemplateMethodSignature(tfn.params, tfn.returnType)) tfn else null;
}

/// Decisions 311 (3), 397 (3), 415 (1) — `value.method "…"` calling a template
/// method: the receiver is the call site's code, captured unevaluated as the
/// `self` parameter (its text is the expression as written, `self.text()`)
/// after its type is checked against `R`; every literal is captured as at a
/// call `f "…"`. The call expands as a template call does.
fn inferTemplateMethodCall(
    env: *Env,
    call: anytype,
    recv: *ast.TypedExpr,
    tfn: ast.FnDecl,
    loc: ast.Loc,
) InferError!TypedExpr {
    if (call.args.len + 1 != tfn.params.len) {
        env.lastError = TypeError.arityMismatch(call.callee, tfn.params.len - 1, call.args.len).withLoc(loc);
        return error.TypeError;
    }
    const raw = env.lookup(call.callee) orelse {
        env.lastError = try unboundAt(env, call.callee, loc);
        return error.TypeError;
    };
    const instantiated = (try instantiateGenericType(env, raw)).deref();
    if (instantiated.* != .func or instantiated.func.params.len != tfn.params.len) {
        env.lastError = TypeError.custom("a template method's type is not a function", "Report it: the template's signature was registered without its parameters.").withLoc(loc);
        return error.TypeError;
    }
    const f = instantiated.func;
    const recvExpr = call.receiver.?;
    // The receiver's type fits `R` as an argument does: a behavior accepts an
    // implementer.
    const selfType = f.params[0].deref();
    const want: *T.Type = if (selfType.* == .named and selfType.named.args.len == 1) selfType.named.args[0] else try env.freshVar();
    try unifyArgument(env, want, recv.getType(), recv.getLoc());

    var captures: std.ArrayListUnmanaged(template.CapturedExpr) = .empty;
    try captures.append(env.arena, .{
        .callee = call.callee,
        .paramIndex = 0,
        .paramName = tfn.params[0].name,
        .node = recvExpr,
        .text = try defaultLexeme(env.arena, recvExpr.*),
        .multiline = false,
        .loc = recvExpr.getLoc(),
        .modulePath = env.modulePath,
        .scope = env.scopeSnapshot,
    });
    for (call.args, 0..) |arg, i| {
        const pi = i + 1;
        const typed = try inferExprTyped(env, arg.value.*);
        const ta: ast.CallArgOf(.typed) = .{ .label = arg.label, .value = try makeTypedPtr(env, typed) };
        if (!tfn.params[pi].typeRef.isExprType() or tfn.params[pi].modifier != .@"comptime") {
            env.lastError = TypeError.custom(
                "a template method takes `comptime` `@Expr` parameters only",
                "Every parameter of a template method is the call site's code: the receiver (`comptime self: @Expr<R>`) and the literal (`comptime q: @Expr<…>`).",
            ).withLoc(arg.value.getLoc());
            return error.TypeError;
        }
        try captures.append(env.arena, try captureExprArg(env, call.callee, .{ .paramIndex = pi, .paramName = tfn.params[pi].name }, arg.value, ta, f.params[pi], call.templateText));
    }
    const slice = try captures.toOwnedSlice(env.arena);
    try env.exprCaptures.put(loc, slice);
    return expandTemplateCall(env, tfn, slice, &.{}, f.ret, loc);
}

/// Splice + re-check the chosen expansion in the caller's environment, verify
/// a concrete `-> @Expr<T>` bound (an unconstrained generic reveals the type
/// per call site instead), and record the substitution for the transform pass.
/// What a template run tells `finishExpansion` beside its code (decision
/// 426): the template's name, the `q.build` whose code the body answered
/// (`template_eval.numberBuilds`; null when not known — `@code`, a build in a
/// function the body calls, a body reduced by inspection), the template's
/// file when it is another module's, and its `q.note`s.
const BuiltInfo = envMod.TemplateBuilt;

/// Decision 426 — the call is typed by the code the template built for it:
/// the expansion is inferred in the caller's environment and its type is the
/// call's, so no free `T` of the signature survives (a bare `-> @Expr<T>`
/// takes the built type). The signature's answer is a bound the built type
/// fits (`unknown` holds anything), refused at the template's `build`
/// otherwise (`template-build-outside-bound`); the call then meets the type
/// expected where it stands as any expression does, at the call, and the
/// template's `q.note`s ride an error there (`Env.templateNotes`, `unifyAt`).
fn finishExpansionBuilt(env: *Env, expansion: *const ast.Expr, retType: *T.Type, loc: ast.Loc, built: BuiltInfo) InferError!TypedExpr {
    if (built.ast_nodes.len == 0) return finishExpansionTyped(env, expansion, retType, loc, built);
    return finishExpansionTyped(env, expansion, retType, loc, built) catch |err| {
        if (err != error.TypeError) return err;
        const le = env.lastError orelse return err;
        const at = le.loc orelse return err;
        // Decision 625 (2) — a `Name` nothing binds where the tree is
        // spliced is refused at the `ast` call, naming it.
        if (le.kind == .unboundVariable) for (built.ast_names) |n| {
            if (!at.eql(n.loc)) continue;
            const message = try std.fmt.allocPrint(env.arena, "`Name(\"{s}\")` names nothing in scope where the tree is spliced", .{n.name});
            return refuseAst(env, built.callee, message, built.at, built.file, loc);
        };
        // Decision 752 — a type error at a node of the tree is reported at
        // the call, naming the `ast` call's `file:line:col` and the node; the
        // caller's code a `Syntax` splices keeps its own location.
        const node = astBuild.nodeAt(built.ast_nodes, at) orelse return err;
        const file = built.file orelse srcPathOfModule(env, env.modulePath);
        const original = try le.message(env.arena);
        const described = try astBuild.describeNode(env.arena, node);
        const msg = if (built.at) |b|
            try std.fmt.allocPrint(env.arena, "{s} — in `{s}`'s tree at {s}:{d}:{d}, at the node `{s}`", .{ original, built.callee, file, b.line, b.col, described })
        else
            try std.fmt.allocPrint(env.arena, "{s} — in `{s}`'s tree, at the node `{s}`", .{ original, built.callee, described });
        env.lastError = TypeError.custom(msg, "A tree `compiler.ast` builds carries no location of its own: an error inside it is reported at the call that expanded it (decision 752).").withLoc(loc);
        return error.TypeError;
    };
}

fn finishExpansionTyped(env: *Env, expansion_in: *const ast.Expr, retType: *T.Type, loc: ast.Loc, built: BuiltInfo) InferError!TypedExpr {
    // 144 B-10 (decisions 192, 207) — the calls the built code makes of this
    // module's functions build their inline parameter types, as the written
    // ones do (`inline_types.zig` ran before the code existed).
    const expansion = try inlineTypes.rewriteBuilt(env.arena, expansion_in, &env.fnDecls);
    const typed = try inferExprTyped(env, expansion.*);
    const builtType = typed.getType();

    // The expansion carries only the executable `code` half (the `ast` tree is
    // stored separately for tooling). Verify it against the declared bound for
    // both carriers: `@Expr<T>` (named "Expr") and `@ExprCustom<T>` (the
    // `CustomExpr<T>` struct), whose `T` is the code's value type.
    const rDeref = retType.deref();
    if (rDeref.* == .named and rDeref.named.args.len == 1 and
        (std.mem.eql(u8, rDeref.named.name, ast.expr_type_name) or std.mem.eql(u8, rDeref.named.name, "CustomExpr")))
    {
        const bound = rDeref.named.args[0];
        unifyUnlocated(env, bound, builtType) catch |err| {
            if (err != error.TypeError) return err;
            const want = try errorMod.typeLabelFullAlloc(env.arena, bound);
            const got = try errorMod.typeLabelFullAlloc(env.arena, builtType);
            const callee = if (built.callee.len > 0) built.callee else "the template";
            const at = built.at orelse loc;
            if (built.file) |file| if (built.at) |b| {
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` built code of type `{s}` at {s}:{d}:{d}, outside its answer `{s}`", .{ diagnostics.template_build_outside_bound, callee, got, file, b.line, b.col, want });
                env.lastError = TypeError.custom(msg, "A template's answer is a bound its built code fits (decision 426 (2)): build code of that type, or widen the answer.").withLoc(loc);
                return error.TypeError;
            };
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` built code of type `{s}`, outside its answer `{s}`", .{ diagnostics.template_build_outside_bound, callee, got, want });
            env.lastError = TypeError.custom(msg, "A template's answer is a bound its built code fits (decision 426 (2)): build code of that type, or widen the answer.").withLoc(at);
            return error.TypeError;
        };
    }

    try env.templateExpansions.put(loc, expansion);
    if (built.notes.len > 0) try env.templateNotes.put(env.arena, loc, built.notes);
    return typed;
}

/// 01-compiler/14 step 8 (decision 355) — `captures` with each `${…}` hole's
/// build value (`block_eval.holeValue`): the template reads it as the part's
/// `value`, so it tells a hole known at build from one computed at render. A
/// hole known at build whose evaluation raises is refused at the hole.
fn withHoleValues(env: *Env, io: std.Io, captures: []const template.CapturedExpr) InferError![]const template.CapturedExpr {
    const out = try env.arena.dupe(template.CapturedExpr, captures);
    for (out) |*cap| {
        if (cap.node.* != .literal or cap.node.literal.kind != .stringTemplate) continue;
        var values: std.ArrayListUnmanaged(?template.Term) = .empty;
        for (cap.node.literal.kind.stringTemplate.parts) |part| switch (part) {
            .text => {},
            .expr => |hole| switch (try blockEval.holeValue(env, io, hole)) {
                .render => try values.append(env.arena, null),
                .build => |t| try values.append(env.arena, t),
                .refused => |r| {
                    const message = try std.fmt.allocPrint(env.arena, "this hole is known at build (decision 355) and its value raised there: {s}", .{r.message});
                    const hint = "A hole whose value is a literal, a `comptime` or a `val` known at build is evaluated while the program compiles, as a `comptime` is (decision 331).";
                    env.lastError = if (r.frames.len > 0)
                        try blockEval.raisedError(env, message, hint, r.frames, hole.getLoc())
                    else
                        TypeError.custom(message, hint).withLoc(r.loc);
                    return error.TypeError;
                },
            },
        };
        cap.holeValues = values.items;
    }
    return out;
}

/// Decision 415 (2) — `captures` with the `@Decl` handle of every word of
/// their text that names a declaration where the call stands: what
/// `q.lookup(word)` answers and `q.bindings()` lists. A declaration of this
/// module or an imported one (an alias answers the declaration it names,
/// decision 112) is reflected as a decorator's handle is — `name`, `kind`,
/// `module`, `fields`, `variants`, `methods`, `params` — with the typed meta
/// its decorators recorded (`meta`, read `d.meta(T)`): another module's ran
/// when that module was analysed, this module's before its bodies.
fn withLookupHandles(env: *Env, captures: []const template.CapturedExpr) InferError![]const template.CapturedExpr {
    const out = try env.arena.dupe(template.CapturedExpr, captures);
    for (out) |*cap| {
        const scope = cap.scope orelse continue;
        var handles: std.ArrayListUnmanaged(template.LookupHandle) = .empty;
        for (try templateEval.captureWords(env.arena, cap)) |word| {
            const entry = scope.entries.get(word) orelse continue;
            try handles.append(env.arena, .{ .local = word, .term = try decoratorEval.handleToTerm(env.arena, try lookupHandle(env, entry)) });
        }
        cap.handles = handles.items;
    }
    return out;
}

/// The read-only handle `q.lookup` answers for `entry`, a name of the call
/// site's scope (decision 415 (2)).
fn lookupHandle(env: *Env, entry: template.ScopeEntry) InferError!decoratorEval.DeclHandle {
    const own = env.ownDecls.contains(entry.name);
    const owner: ?envMod.TemplateImport = if (own) .{ .owner = env.modulePath, .name = entry.name } else env.importOwners.get(entry.name);
    const module = if (owner) |o| o.owner else "";
    const name = if (owner) |o| o.name else entry.declName;
    var h: decoratorEval.DeclHandle = .{
        .kind = entry.kind.declKindName(),
        .name = name,
        .fields = &.{},
        .methods = &.{},
        .returnType = "",
        .annotations = &.{},
        .module = module,
    };
    const decl: ?ast.DeclKind = if (own) for (env.moduleDecls) |d| {
        const n: []const u8 = switch (d) {
            .@"fn" => |f| f.name,
            .val => |v| v.name,
            .type_ => |t| t.name,
            .behavior => |b| b.name,
            else => continue,
        };
        if (std.mem.eql(u8, n, name)) break d;
    } else null else if (env.typeDeclRegistry) |reg| if (reg.get(module)) |decls| decls.get(name) else null else null;
    if (decl) |d| switch (d) {
        .@"fn" => |f| {
            h.kind = "Fn";
            h.returnType = if (f.returnType) |rt| try declTypeName(env.arena, rt) else "";
            h.annotations = f.annotations;
            h.params = try paramHandles(env, f.params);
        },
        .val => |v| {
            h.kind = "Val";
            h.returnType = if (v.typeAnnotation) |tr| try declTypeName(env.arena, tr) else "";
            h.annotations = v.annotations;
        },
        .type_ => |t| {
            h.kind = "Type";
            h.annotations = t.annotations;
            h.methods = t.methods;
            const fields = try env.arena.alloc(decoratorEval.FieldHandle, t.recordFields().len);
            for (t.recordFields(), 0..) |fld, i| fields[i] = .{ .name = fld.name, .typeName = try declTypeName(env.arena, fld.typeRef), .annotations = fld.annotations };
            h.fields = fields;
            if (t.shape == .enum_) {
                h.variants = try variantHandles(env, t);
            }
        },
        .behavior => |b| {
            h.kind = "Behavior";
            h.annotations = b.annotations;
            h.methods = b.methods;
            const fields = try env.arena.alloc(decoratorEval.FieldHandle, b.fields.len);
            for (b.fields, 0..) |fld, i| fields[i] = .{ .name = fld.name, .typeName = try declTypeName(env.arena, fld.typeRef), .annotations = &.{} };
            h.fields = fields;
        },
        else => {},
    };
    var metas: std.ArrayListUnmanaged(decoratorEval.TagMeta) = .empty;
    if (env.reflection) |r| if (module.len > 0) for (try r.typedMetaOf(env.arena, module, name)) |e| {
        try metas.append(env.arena, .{ .typeName = e.typeName, .repeat = e.repeat, .value = try lookupMetaTerm(env, e) });
    };
    // Decision 372's pattern — a `.hooks` reader of this module records its
    // meta after the bodies: read before it ran, the meta is refused.
    const pending = own and !env.hooksReadersRan and blk: {
        var it = env.hooksReaders.keyIterator();
        while (it.next()) |k| {
            if (std.mem.startsWith(u8, k.*, name) and k.len > name.len and k.*[name.len] == 0) break :blk true;
        }
        break :blk false;
    };
    h.lookup = .{ .identity = entry.identity, .local = entry.name, .meta = metas.items, .pending = pending };
    h.decoratorIds = try handleDecoratorIds(env, h);
    return h;
}

/// A typed meta value of a looked-up declaration as the term the template
/// body reads (decision 415 (3)): its record's fields from the constructor's
/// arguments, a field the value left out from its default as written.
fn lookupMetaTerm(env: *Env, e: reflectionMod.TypedMetaEntry) InferError!decoratorEval.Term {
    const td = typeDeclAt(env, env.moduleDecls, e.typeModule, e.typeName) orelse typeDeclAt(env, env.moduleDecls, e.typeModule, try std.mem.concat(env.arena, u8, &.{ "\x01", e.typeName }));
    const fields = if (td) |t| t.recordFields() else &.{};
    const names = try env.arena.alloc([]const u8, fields.len);
    const defaults = try env.arena.alloc(?[]const u8, fields.len);
    for (fields, 0..) |f, i| {
        names[i] = f.name;
        defaults[i] = if (f.default) |d| try defaultLexeme(env.arena, d) else null;
    }
    return decoratorEval.metaArgsTerm(env.arena, names, defaults, e.args);
}

/// Run the template body in the node eval runtime and turn the protocol
/// result into an expansion (F6-full, slice 1). Limits (recorded follow-ups):
/// every parameter must be an `@Expr` capture (runtime params have no
/// comptime value) and captured templates must be hole-free (`${…}` parts
/// cannot cross into the evaluator yet).
fn expandTemplateCallViaRuntime(
    env: *Env,
    tfn: ast.FnDecl,
    captures_in: []const template.CapturedExpr,
    plainArgs: []const template.PlainArg,
    retType: *T.Type,
    loc: ast.Loc,
) InferError!TypedExpr {
    const ctx = env.templateEval.?;

    // All params must be accounted for: each is either an @Expr capture or a
    // plain-arg literal. Runtime params (no value at compile time) are rejected.
    if (captures_in.len + plainArgs.len != tfn.params.len) {
        env.lastError = TypeError.custom(
            "template function has parameters without compile-time values (V1)",
            "Every parameter must be either `comptime p: @Expr<T>` or receive a literal value at the call site.",
        ).withLoc(loc);
        return error.TypeError;
    }
    // Memoize by callee + capture texts + the scope entries of their words +
    // plain arg values (`templateEval.memoKey`, decision 237: O(text), never
    // O(scope)) — hole-free captures only: a holed template's expansion embeds
    // the call site's own hole expressions, so equal text parts at two sites
    // would alias the wrong holes.
    var holed = false;
    for (captures_in) |cap| {
        if (cap.text == null) holed = true;
    }
    // Decision 637 — a body that reads `compiler.holes(t)` gets each hole's
    // expression; the expansion embeds this call's holes, so it is not
    // memoized.
    const captures = if (decoratorSameMod.mentionsMethod(tfn, "holes")) blk: {
        holed = true;
        break :blk try withHoleCaptures(env, captures_in);
    } else captures_in;
    // `@ExprCustom<T>` calls are never memoized: each expansion also stores a
    // reference `CustomNode` tree keyed by *this* call's location, so the
    // evaluation must run per call site (the memo cache holds only the `code`
    // expression). Custom templates are opt-in and rare — correctness over the
    // node round-trip saving.
    const isCustomRet = blk: {
        const d = retType.deref();
        break :blk d.* == .named and std.mem.eql(u8, d.named.name, "CustomExpr");
    };
    const t_memo = stages.start();
    const memoKey: ?[]const u8 = if (holed or isCustomRet) null else try templateEval.memoKey(env.arena, tfn.name, captures, plainArgs);
    stages.stop(.memo_key, t_memo);
    if (memoKey) |key| {
        if (env.templateEvalCache.get(key)) |cached| {
            return finishExpansionBuilt(env, cached, retType, loc, env.templateEvalBuilt.get(key) orelse .{ .callee = tfn.name });
        }
    }

    // Decision 331, calls included — the template module carries the
    // functions its body reaches (its own module's, and the ones that module
    // imports with their closure) and the record and enum types they name, as
    // a decorator's does (`decoratorSupport`, `block_eval.typesReached`). An
    // imported template brings what its module computed
    // (`Env.importedTemplateSupport`); a local one computes it here.
    const owner = env.comptimeOwnerOf(tfn);
    const found: Support = if (env.importedTemplateSupport.get(@intFromPtr(tfn.body.ptr))) |s|
        .{ .fns = s.fns, .conflict = s.conflict }
    else if (owner.len == 0 or std.mem.eql(u8, owner, env.modulePath))
        try decoratorSupport(env.arena, env.fnDecls, &env.importedFnSupport, tfn)
    else
        .{ .fns = &.{} };
    if (found.conflict) |c| {
        env.lastError = TypeError.custom(c, "Rename one of the two functions, so each name the template reaches is one function.").withLoc(loc);
        return error.TypeError;
    }
    // A local function's tuple label reads were recorded by this module's
    // inference (`Env.tupleLabelReads`); an imported one's were applied when
    // its module exported it.
    // Decision 341 — the std calls of this module's functions renamed to the
    // std functions the module carries (`host_cells.zig`).
    var hosts = try hostCells.Writer.init(env, env.moduleDecls);
    const carried = try env.arena.alloc(ast.FnDecl, 1 + found.fns.len);
    for (carried, 0..) |*c, i| {
        const f = if (i == 0) tfn else found.fns[i - 1];
        const own = if (i == 0) owner.len == 0 or std.mem.eql(u8, owner, env.modulePath) else if (env.fnDecls.get(f.name)) |g| g.body.ptr == f.body.ptr else false;
        c.* = if (own) try hosts.rewrite(try templateEval.relabelTupleReads(env.arena, &env.tupleLabelReads, f)) else f;
    }
    // Decision 637 — the templates its body calls run with it, at build.
    // An imported template's were lowered where its module exported it.
    // Lowered first: a hole's expression (`${self}`) is the body's, renamed
    // with it below.
    const lowered: BuildLowered = if (owner.len == 0 or std.mem.eql(u8, owner, env.modulePath)) try lowerBuildTemplateCalls(env, carried[0]) else .{ .decl = carried[0] };
    carried[0] = lowered.decl;
    // A template method's receiver parameter is no `self` to the backend
    // that lowers the module (decisions 311 (3), 415 (1)).
    carried[0] = try templateEval.renameTemplateSelf(env.arena, carried[0]);
    const carried_all = if (lowered.support.len == 0) carried else try std.mem.concat(env.arena, ast.FnDecl, &.{ carried, lowered.support });
    // Decision 353 — the body's `@TypeInfo.all(…)` queries answered for the
    // program this call is compiled in; the module carries the records the
    // answers build.
    const answered = try answerTemplateQueries(env, owner, carried[0], loc);
    carried[0] = answered.decl;
    const reached = try blockEval.typesReached(env, carried_all, &templateEval.injected_names, "");
    // The host functions and std functions the run reaches (decision 341); an
    // imported template's travelled with its export.
    const own_template = owner.len == 0 or std.mem.eql(u8, owner, env.modulePath);
    const hosted: []const ast.FnDecl = if (own_template) try hostCells.hostSupport(env, &env.fnDecls, carried_all) else &.{};
    const support = try std.mem.concat(env.arena, ast.FnDecl, &.{ carried_all[1..], reached.fns, hosted });
    const types = try std.mem.concat(env.arena, ast.DeclKind, &.{ reached.types, answered.types });
    var valued = try withHoleValues(env, ctx.io, captures);
    // Decision 415 (2) — what `q.lookup` / `q.bindings` answer.
    const looksUp = decoratorSameMod.mentionsMethod(carried[0], "lookup") or decoratorSameMod.mentionsMethod(carried[0], "bindings") or for (support) |f| {
        if (decoratorSameMod.mentionsMethod(f, "lookup") or decoratorSameMod.mentionsMethod(f, "bindings")) break true;
    } else false;
    if (looksUp) valued = try withLookupHandles(env, valued);
    // Decision 302 — a body that calls `q.annotate(decl, at)` reads the typed
    // meta of the tag's `@Decl` (`d.meta(T)`), lowered for the run; each call
    // past the answers so far stops the run with the annotation to apply,
    // which runs here, and the body runs again with its answer.
    const annotates = decoratorSameMod.mentionsMethod(carried[0], "annotate") or for (support) |f| {
        if (decoratorSameMod.mentionsMethod(f, "annotate")) break true;
    } else false;
    const readsMeta = annotates or looksUp;
    const runTfn = if (readsMeta) try syntaxParam.eraseMetaReads(env.arena, carried[0]) else carried[0];
    const runSupport = if (readsMeta) blk: {
        const out = try env.arena.alloc(ast.FnDecl, support.len);
        for (support, 0..) |f, i| out[i] = try syntaxParam.eraseMetaReads(env.arena, f);
        break :blk out;
    } else support;
    // Decision 426 (2) — each `q.build` of the body numbered, so the run
    // names the one whose code it answered.
    const numbered = try templateEval.numberBuilds(env.arena, runTfn);
    var extras: templateEval.Extras = .{};
    var tags: std.ArrayListUnmanaged(decoratorEval.DeclHandle) = .empty;
    // Decisions 451 (3), 532 — the calls of a template's body and of the
    // functions of its module it reaches are located, in that module's file
    // (the using module's own for a template it declares), which a raise's
    // diagnostic then names (`srcPathOfModule`).
    const located: []const erlang.Located = try locatedFns(env, numbered.f, srcPathOfModule(env, if (owner.len > 0) owner else env.modulePath), carried[1..]);
    const outcome = while (true) {
        const run = templateEval.evaluate(env.arena, ctx.io, ctx.build_root, owner, srcPathOfModule(env, owner), numbered.f, runSupport, located, types, valued, plainArgs, &env.comptimeTraces, &extras) catch {
            env.lastError = TypeError.custom(
                "the template evaluator failed to run",
                "Template bodies run on the wasm comptime runtime inside the compiler (decision 434); this failure is the compiler's, not the body's — report it.",
            ).withLoc(loc);
            return error.TypeError;
        };
        if (run != .need) break run;
        if (valued.len == 0 or tags.items.len >= max_tag_annotations) {
            env.lastError = TypeError.custom("the template ran more tag annotations than one expansion may", "A template runs each annotation of its text once per expansion (decision 302).").withLoc(loc);
            return error.TypeError;
        }
        const tagged = try runTagAnnotation(env, ctx, &valued[0], run.need, tags.items);
        try tags.append(env.arena, tagged);
        const terms = try env.arena.alloc(decoratorEval.Term, tags.items.len);
        for (tags.items, 0..) |h, i| terms[i] = try tagAnswerTerm(env.arena, h, i);
        const next = try env.arena.dupe(template.CapturedExpr, valued);
        for (next) |*cap| cap.tagAnswers = terms;
        valued = next;
    };

    // Decision 625 (2) — the `compiler.ast` call the body answered, where an
    // ill-formed tree is refused.
    const builtAt: ?ast.Loc = if (extras.build) |i| (if (i < numbered.locs.len) numbered.locs[i] else null) else if (numbered.locs.len == 1 and (outcome == .code or outcome == .ast)) numbered.locs[0] else null;
    var astNames: []const astBuild.Placed = &.{};
    var astNodes: []const astBuild.At = &.{};
    const expansion: *const ast.Expr = switch (outcome) {
        .ast => |tree| blk: {
            const built = try astExpansion(env, tfn, tree, captures, loc);
            switch (built) {
                .ok => |r| {
                    astNames = r.names;
                    astNodes = r.nodes;
                    break :blk r.expr;
                },
                .ill => |message| return refuseAst(env, tfn.name, message, builtAt, if (own_template) null else srcPathOfModule(env, owner), loc),
            }
        },
        .code => |src| blk: {
            const origin = builtCodeOrigin(env, captures, loc);
            const parsed = parseCodeTextAt(env, tfn, src, origin, if (captures.len > 0) &captures[0] else null, null) orelse {
                env.lastError = TypeError.custom(
                    "the code built by the template does not parse as an expression",
                    "`build(…)`/`@code(…)` output must be a single well-formed botopink expression.",
                ).withLoc(loc);
                return error.TypeError;
            };
            try applyDslHygiene(env, tfn, @constCast(parsed), src, origin, captures);
            // Splice the caller's `${…}` hole expressions back in place of
            // the `__bp_hole_<param>_<i>` placeholders the template embedded.
            substituteHoles(@constCast(parsed), captures);
            break :blk parsed;
        },
        .capture => |param| captureNodeFor(captures, param) orelse {
            env.lastError = TypeError.custom(
                "the template returned an unknown capture",
                "This is a template-evaluator protocol bug — please report it.",
            ).withLoc(loc);
            return error.TypeError;
        },
        .custom => |c| blk: {
            // The `code` half is spliced exactly like a plain `.code` outcome —
            // runtime/codegen never learn it came from `q.custom`.
            const origin = builtCodeOrigin(env, captures, loc);
            // The `ast` half: the reference tree the template built.
            const root = template.parseCustomNodeFromTree(env.arena, c.ast) catch return error.OutOfMemory;
            const parsed = parseCodeTextAt(env, tfn, c.code, origin, if (captures.len > 0) &captures[0] else null, root) orelse {
                env.lastError = TypeError.custom(
                    "the code built by the template does not parse as an expression",
                    "`q.custom(tree, code)` — the `code` must be a single well-formed botopink expression (e.g. from `q.build(…)`).",
                ).withLoc(loc);
                return error.TypeError;
            };
            try applyDslHygiene(env, tfn, @constCast(parsed), c.code, origin, captures);
            substituteHoles(@constCast(parsed), captures);
            const prov: ?*const template.CapturedExpr = if (captures.len > 0) &captures[0] else null;
            env.customAstByLoc.put(loc, .{
                .callee = tfn.name,
                .root = root,
                .file = if (prov) |p| p.modulePath else env.modulePath,
                .line = if (prov) |p| p.loc.line else loc.line,
                .col = if (prov) |p| p.loc.col else loc.col,
            }) catch return error.OutOfMemory;
            break :blk parsed;
        },
        .value => |v| valueToAstLiteral(env, v, loc, liftShapeOf(env, tfn)) orelse {
            env.lastError = TypeError.custom(
                "the template's `@expr(…)` value cannot be lifted as a literal",
                "V1 lifts numbers, strings, booleans, null, and arrays of those.",
            ).withLoc(loc);
            return error.TypeError;
        },
        .fail => |f| {
            const cap: ?*const template.CapturedExpr = blk: {
                if (f.param) |pn| for (captures) |*c| {
                    if (std.mem.eql(u8, c.paramName, pn)) break :blk c;
                };
                break :blk if (captures.len > 0) &captures[0] else null;
            };
            if (cap) |c| {
                env.lastError = template.failDiagnostic(c, f.span, f.message);
            } else {
                env.lastError = TypeError.custom(f.message, "raised by the template function via `fail`/`failAt`").withLoc(loc);
            }
            return error.TypeError;
        },
        .err => |msg| {
            env.lastError = TypeError.custom(
                msg,
                "Thrown while evaluating the template function's body at compile time.",
            ).withLoc(loc);
            return error.TypeError;
        },
        // Decision 532 — located at the call that raised, in the template's
        // own file; the call that expanded it is the last frame.
        .raised => |failed| return raisedFrom(env, failed.message, "the template's body raised; each call of the chain is a `called from` line, down to the call that expanded it", failed.frames, loc),
        // Answered by the loop above.
        .need => unreachable,
    };

    const built: BuiltInfo = .{
        .callee = tfn.name,
        .at = builtAt,
        .file = if (own_template) null else srcPathOfModule(env, owner),
        .notes = extras.notes,
        .ast_names = astNames,
        .ast_nodes = astNodes,
    };
    if (memoKey) |key| {
        env.templateEvalCache.put(key, expansion) catch return error.OutOfMemory;
        try env.templateEvalBuilt.put(env.arena, key, built);
    }
    return finishExpansionBuilt(env, expansion, retType, loc, built);
}

/// Decision 637 — a template's body with each template it calls at build
/// lowered (`build_template_calls.zig`), and those templates — under the name
/// they travel with — with the functions each reaches.
pub const BuildLowered = struct { decl: ast.FnDecl, support: []const ast.FnDecl = &.{} };

pub fn lowerBuildTemplateCalls(env: *Env, f: ast.FnDecl) InferError!BuildLowered {
    const Ctx = struct {
        env: *Env,

        pub fn isBuildTemplate(self: @This(), callee: []const u8) bool {
            const tf = self.env.templateFns.get(callee) orelse return false;
            return buildCalls.answersAnyvalue(tf);
        }

        pub fn holes(self: @This(), text: []const u8, textLoc: ast.Loc) buildCalls.Error![]ast.Expr {
            return textHoleExprs(self.env, text, textLoc) catch |err| switch (err) {
                error.OutOfMemory => error.OutOfMemory,
                else => error.HoleNotAnExpression,
            };
        }
    };
    var l: buildCalls.Lowering(Ctx) = .{ .arena = env.arena, .ctx = .{ .env = env } };
    const decl = l.lower(f) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        error.HoleNotAnExpression => return error.TypeError,
    };
    if (l.callees.items.len == 0) return .{ .decl = decl };
    var support: std.ArrayListUnmanaged(ast.FnDecl) = .empty;
    for (l.callees.items) |name| {
        const tf = env.templateFns.get(name) orelse continue;
        var carried = tf;
        carried.name = try buildCalls.carriedName(env.arena, name);
        try support.append(env.arena, carried);
        const reached: []const ast.FnDecl = if (env.importedTemplateSupport.get(@intFromPtr(tf.body.ptr))) |s|
            s.fns
        else
            (try decoratorSupport(env.arena, env.fnDecls, &env.importedFnSupport, tf)).fns;
        for (reached) |r| {
            const dup = for (support.items) |have| {
                if (std.mem.eql(u8, have.name, r.name)) break true;
            } else false;
            if (!dup) try support.append(env.arena, r);
        }
    }
    return .{ .decl = decl, .support = support.items };
}

/// Decision 637 — the `${…}` holes of the template text `text` written at
/// `textLoc` (its `` @` ``), each parsed where it is written; a hole that is
/// no expression is refused at it.
fn textHoleExprs(env: *Env, text: []const u8, textLoc: ast.Loc) InferError![]ast.Expr {
    const spans = try template.holeSpans(env.arena, text);
    const cap: template.CapturedExpr = .{
        .callee = "",
        .paramIndex = 0,
        .paramName = "",
        .node = undefined,
        .text = text,
        .multiline = false,
        .templateText = true,
        .loc = textLoc,
        .modulePath = env.modulePath,
        .scope = null,
    };
    const out = try env.arena.alloc(ast.Expr, spans.len);
    for (spans, out) |sp, *o| {
        const src = text[sp.start..sp.end];
        const at = template.mapSpanToLoc(&cap, sp);
        const node = parseCodeText(env, src, at) orelse {
            const msg = try std.fmt.allocPrint(env.arena, "this hole is no expression: `${{{s}}}`", .{src});
            env.lastError = TypeError.custom(msg, "A `${…}` hole of a template text holds one expression (decision 637).").withLoc(at);
            return error.TypeError;
        };
        o.* = node.*;
    }
    return out;
}

/// Decision 625 (2) — the code a `compiler.ast(node)` tree builds: each node
/// lowered (`ast_build.zig`), a `Lit` as the value's literal, a `Syntax` as the
/// caller's code it holds; the names the library wrote resolve in its module
/// (decision 112), the caller's code in the caller's.
const AstExpansion = union(enum) {
    ok: struct { expr: *const ast.Expr, names: []const astBuild.Placed, nodes: []const astBuild.At },
    ill: []const u8,
};

fn astExpansion(env: *Env, tfn: ast.FnDecl, tree: std.json.Value, captures: []const template.CapturedExpr, loc: ast.Loc) InferError!AstExpansion {
    const Ctx = struct {
        env: *Env,
        captures: []const template.CapturedExpr,

        pub fn lit(self: @This(), v: std.json.Value, at: ast.Loc) ?*const ast.Expr {
            if (holdsSyntax(v)) return null;
            const typed = templateEval.typedValue(self.env.arena, v) catch return null;
            return valueToAstLiteral(self.env, typed, at, null);
        }

        pub fn syntax(self: @This(), v: std.json.Value) ?*const ast.Expr {
            if (v != .object) return null;
            const param = v.object.get("__bp_capture") orelse return null;
            if (param != .string) return null;
            return captureNodeFor(self.captures, param.string);
        }

        fn holdsSyntax(v: std.json.Value) bool {
            return switch (v) {
                .object => |o| o.contains("__bp_capture") or for (o.values()) |x| {
                    if (holdsSyntax(x)) break true;
                } else false,
                .array => |a| for (a.items) |x| {
                    if (holdsSyntax(x)) break true;
                } else false,
                else => false,
            };
        }
    };
    var b: astBuild.Builder(Ctx) = .{ .arena = env.arena, .ctx = .{ .env = env, .captures = captures }, .origin = builtCodeOrigin(env, captures, loc) };
    const root = switch (try b.build(tree)) {
        .ok => |r| r,
        .ill => |m| return .{ .ill = m },
    };
    try applyAstHygiene(env, tfn, root);
    b.fill(root);
    return .{ .ok = .{ .expr = root, .names = b.names.items, .nodes = b.placed.items } };
}

/// Decision 625 (2) — `ast-ill-formed`, at the `compiler.ast` call: in this
/// module's template there, in another module's at the call it expands,
/// naming where the `ast` call is written.
fn refuseAst(env: *Env, callee: []const u8, message: []const u8, at: ?ast.Loc, file: ?[]const u8, loc: ast.Loc) InferError {
    const hint = "`compiler.ast(node)` builds code from a tree of `compiler.Node` records (decision 625 (2)): each node a kind `compiler.bp` declares, an `Arg` only in `Call.args`, each `Name` bound where the code is spliced.";
    if (file) |f| if (at) |a| {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}`'s tree at {s}:{d}:{d}: {s}", .{ diagnostics.ast_ill_formed, callee, f, a.line, a.col, message });
        env.lastError = TypeError.custom(msg, hint).withLoc(loc);
        return error.TypeError;
    };
    const msg = try std.fmt.allocPrint(env.arena, "{s}: {s}", .{ diagnostics.ast_ill_formed, message });
    env.lastError = TypeError.custom(msg, hint).withLoc(at orelse loc);
    return error.TypeError;
}

/// Decision 302 — the most tag annotations one expansion runs.
const max_tag_annotations = 4096;

/// The handle a tag annotation's run answered, as the term the template body
/// reads (`decorator_eval.handleToTerm`), with its index among the answers so
/// a later `q.annotate` of it runs over it, not over a fresh tag.
fn tagAnswerTerm(arena: std.mem.Allocator, h: decoratorEval.DeclHandle, index: usize) std.mem.Allocator.Error!decoratorEval.Term {
    const t = try decoratorEval.handleToTerm(arena, h);
    const entries = try arena.alloc(decoratorEval.Term.MapEntry, t.map.len + 1);
    @memcpy(entries[0..t.map.len], t.map);
    entries[t.map.len] = .{ .key = decoratorEval.Term.atomOf(preludeMod.answer_key), .value = decoratorEval.Term.int(@intCast(index)) };
    return decoratorEval.Term.mapOf(entries);
}

/// Decision 302 — run the annotation a template's `q.annotate(decl, at)`
/// names over the tag: `at` spans `name` or `name(args)` in the capture's
/// text; the name resolves in the caller's scope to a decorator, its
/// arguments are checked there as a declaration's annotation's are, and the
/// body runs over the tag's handle. Its one channel is typed meta: what it
/// records joins the handle answered (one `setMeta` of a type per tag,
/// `addMeta` repeats); `addMember`, `addType`, `@emit` and the string
/// `setMeta` are refused. Every refusal is located at the annotation in the
/// caller's text.
fn runTagAnnotation(
    env: *Env,
    ctx: envMod.TemplateEvalCtx,
    cap: *const template.CapturedExpr,
    need: anytype,
    answered: []const decoratorEval.DeclHandle,
) InferError!decoratorEval.DeclHandle {
    const text = try templateEval.captureText(env.arena, cap);
    const at = template.mapSpanToLoc(cap, need.span);
    const refuse = struct {
        fn f(e: *Env, l: ast.Loc, msg: []const u8, hint: []const u8) InferError {
            e.lastError = TypeError.custom(msg, hint).withLoc(l);
            return error.TypeError;
        }
    }.f;
    if (need.span.start > need.span.end or need.span.end > text.len)
        return refuse(env, cap.loc, "`q.annotate(decl, at)`: `at` is not a span of the template's text", "The span indexes `q.text()`: `Span(start, end, line)` around one annotation `name` or `name(args)`.");
    const written = std.mem.trim(u8, text[need.span.start..need.span.end], " \t\r\n");
    const lead = std.mem.indexOf(u8, text[need.span.start..need.span.end], written) orelse 0;

    // `#[<written>]` above a function, so the parser reads it as it reads a
    // declaration's annotation; each location is then moved onto the text.
    const src = try std.fmt.allocPrint(env.arena, "#[{s}]\nfn __bp_tagAnnotation() -> void {{}}", .{written});
    var lx = Lexer.init(src);
    const tokens = lx.scanAll(env.arena) catch return error.OutOfMemory;
    var parser = Parser.init(tokens);
    const parsed = parser.parse(env.arena) catch null;
    const anns: []const ast.Annotation = if (parsed) |p| (if (p.decls.len == 1 and p.decls[0] == .@"fn") p.decls[0].@"fn".annotations else &.{}) else &.{};
    if (anns.len != 1 or anns[0].is_builtin or anns[0].template != null) {
        const msg = try std.fmt.allocPrint(env.arena, "`{s}` is not one tag annotation — `name` or `name(args)`", .{written});
        return refuse(env, at, msg, "A tag annotation is one item of a `#[…]` (decision 302): a decorator's name and its arguments.");
    }
    const Mover = struct {
        src: []const u8,
        cap: *const template.CapturedExpr,
        base: usize,
        fn move(self: @This(), l: ast.Loc) ast.Loc {
            var line: usize = 1;
            var off: usize = 0;
            while (off < self.src.len and line < l.line) : (off += 1) {
                if (self.src[off] == '\n') line += 1;
            }
            const pos = off + (l.col -| 1);
            return template.mapSpanToLoc(self.cap, .{ .start = self.base + (pos -| 2), .end = self.base + (pos -| 2), .line = 1 });
        }
    };
    const mover: Mover = .{ .src = src, .cap = cap, .base = need.span.start + lead };
    var a = anns[0];
    a.loc = mover.move(a.loc orelse .{ .line = 1, .col = 3 });
    const argLocs = try env.arena.alloc(ast.Loc, a.argLocs.len);
    for (a.argLocs, 0..) |l, i| argLocs[i] = mover.move(l);
    a.argLocs = argLocs;

    const sig = env.decorators.get(a.name) orelse {
        const msg = try std.fmt.allocPrint(env.arena, "`#[{s}]` names no decorator in this scope — a tag annotation is a function whose first parameter is `comptime decl: @Decl`", .{a.name});
        return decoratorError(env, a, msg, "The annotation resolves where the template is written (decision 302): import it, or declare it here.");
    };
    const dfn = sig.fn_decl orelse {
        const msg = try std.fmt.allocPrint(env.arena, "`#[{s}]` is a bodyless marker and cannot run over a tag", .{a.name});
        return decoratorError(env, a, msg, "A tag annotation is a decorator with a body; it records what the template reads through `decl.setMeta` / `decl.addMeta` (decision 302).");
    };
    const program: ast.Program = .{ .decls = @constCast(env.moduleDecls) };
    try checkDecoratorArgs(env, program, a, sig, .{ .name = need.name, .type_ = null });

    // The tag's handle: a fresh one, or the answer the template handed back.
    const base: decoratorEval.DeclHandle = if (need.answer >= 0 and need.answer < answered.len) answered[@intCast(need.answer)] else blk: {
        var h: decoratorEval.DeclHandle = .{
            .kind = need.kind,
            .name = need.name,
            .fields = &.{},
            .methods = &.{},
            .returnType = "",
            .annotations = &.{},
            .attrs = need.attrs,
        };
        if (std.mem.eql(u8, need.kind, "Component")) if (env.fnDecls.get(need.name)) |f| {
            const c = try env.arena.create(decoratorEval.DeclHandle);
            c.* = .{
                .kind = "Fn",
                .name = f.name,
                .fields = &.{},
                .methods = &.{},
                .returnType = if (f.returnType) |rt| try declTypeName(env.arena, rt) else "",
                .annotations = f.annotations,
                .params = try paramHandles(env, f.params),
            };
            c.* = try completeHandle(env, c.*);
            h.component = c;
        };
        break :blk h;
    };
    if (!base.isTag()) {
        const msg = try std.fmt.allocPrint(env.arena, "`#[{s}]` runs over a tag's `@Decl`, and `q.tagDecl` builds one of kind `DeclKind.Element` or `DeclKind.Component` — not `{s}`", .{ a.name, base.kind });
        return decoratorError(env, a, msg, "Build the tag's handle with `q.tagDecl(DeclKind.Element, name, attrs)` (decision 302).");
    }

    // The run — a declaration's annotation's (`runDeclDecorators`).
    const values: []const envMod.DecoratorArgValue = (if (a.loc) |l| env.decoratorArgValues.get(l) else null) orelse &.{};
    var plain = try env.arena.alloc(template.PlainArg, values.len);
    var builtFns: std.ArrayListUnmanaged(ast.FnDecl) = .empty;
    for (values, 0..) |v, j| {
        plain[j] = .{ .paramName = sig.params[j].name, .source = v.source, .absent = v.absent };
        if (!v.built or v.absent) continue;
        const fname = try std.fmt.allocPrint(env.arena, "__bp_decorator_arg_{d}", .{j + 1});
        try builtFns.append(env.arena, try builtArgFn(env, fname, v.source));
        plain[j].call = fname;
    }
    const owner = env.comptimeOwnerOf(dfn);
    const local = std.mem.eql(u8, owner, env.modulePath);
    const found: Support = if (local)
        try decoratorSupport(env.arena, env.fnDecls, &env.importedFnSupport, dfn)
    else
        .{ .fns = sig.support, .conflict = sig.conflict };
    if (found.conflict) |c| return decoratorError(env, a, c, "Rename one of the two functions, so each name the decorator reaches is one function.");
    const carried = try std.mem.concat(env.arena, ast.FnDecl, &.{ &.{dfn}, found.fns, builtFns.items });
    const reached = try blockEval.typesReached(env, carried, &.{ "__DeclKind", "__Span", "DeclKind", "Span", ast.decl_type_name }, owner);
    const support = try std.mem.concat(env.arena, ast.FnDecl, &.{ found.fns, reached.fns, builtFns.items });
    var hosts = try hostCells.Writer.init(env, program.decls);
    const runDfn = if (local) try hosts.rewrite(try sameLoweredFn(env, program, dfn)) else dfn;
    // What only the run reads — the decorator's erased body and the erased
    // support functions, a copy of every function the run reaches — is scratch:
    // it is gone when the run ends, not held until the session ends (144 B-117).
    var run_scratch = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer run_scratch.deinit();
    const rs = run_scratch.allocator();
    const erasedSupport = try rs.alloc(ast.FnDecl, support.len);
    for (support, 0..) |sf, k| {
        const own = local and k < found.fns.len and std.mem.eql(u8, env.comptimeOwnerOf(sf), env.modulePath);
        erasedSupport[k] = try syntaxParam.eraseForRun(rs, if (own) try hosts.rewrite(try sameLoweredFn(env, program, sf)) else sf, isDecoratorParams(sf.params));
    }
    const runSupport = if (local) try std.mem.concat(rs, ast.FnDecl, &.{ erasedSupport, try hostCells.hostSupport(env, &env.fnDecls, try std.mem.concat(rs, ast.FnDecl, &.{ &.{runDfn}, erasedSupport })) }) else erasedSupport;
    const located = try locatedFns(env, dfn, srcPathOfModule(env, owner), support[0..found.fns.len]);
    const outcome = decoratorEval.evaluate(env.arena, ctx.io, ctx.build_root, owner, srcPathOfModule(env, owner), try syntaxParam.eraseForRun(rs, runDfn, true), runSupport, located, reached.types, try completeHandle(env, base), plain, null, &env.comptimeTraces, &env.buildOutput) catch {
        return decoratorError(env, a, "the decorator evaluator failed to run", "Decorator bodies run on the wasm comptime runtime inside the compiler (decision 434); this failure is the compiler's, not the body's — report it.");
    };
    var metas: std.ArrayListUnmanaged(decoratorEval.TagMeta) = .empty;
    try metas.appendSlice(env.arena, base.tagMeta);
    switch (outcome) {
        .ok => |contributions| for (contributions) |c| switch (c.kind) {
            .typedMeta => {
                const r = env.reflection orelse continue;
                const declName = memberFn.declParamName(dfn) orelse return decoratorError(env, a, "the decorator has no `@Decl` handle", "");
                const calls = try typedMeta.collect(env.arena, dfn, declName);
                const types = r.decoratorMetaTypes.get(try reflectionMod.Reflection.decoratorKey(env.arena, owner, dfn.name)) orelse &.{};
                if (c.index >= calls.len or c.index >= types.len or c.data == null)
                    return decoratorError(env, a, "the decorator evaluator handed back a typed meta value the body does not record", "Report it: `decl.setMeta(v)` / `decl.addMeta(v)` are numbered in source order.");
                const mt = types[c.index];
                const repeat = calls[c.index].repeat;
                for (metas.items) |m| {
                    if (!std.mem.eql(u8, m.typeName, mt.name)) continue;
                    if (repeat and m.repeat) continue;
                    const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` records a second `{s}` on the tag `{s}`, which holds one", .{ diagnostics.decorator_meta_twice, a.name, mt.name, need.name });
                    return decoratorError(env, a, msg, "`decl.setMeta(v)` stores one value of its type per tag (decision 302); a value that repeats is recorded with `decl.addMeta(v)` — every one, never mixed with `setMeta` — and read with `metaAll(T)`.");
                }
                try metas.append(env.arena, .{ .typeName = mt.name, .repeat = repeat, .value = try decoratorEval.metaValueTerm(env.arena, mt.fields, c.data.?) });
            },
            else => {
                const call = switch (c.kind) {
                    .emit => "@emit",
                    .member, .memberFn => "decl.addMember",
                    .assoc => "decl.addType",
                    else => "decl.setMeta(key, value)",
                };
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `#[{s}]` on the tag `{s}` calls `{s}`, and an annotation on a tag records typed meta only", .{ diagnostics.tag_annotation_output, a.name, need.name, call });
                return decoratorError(env, a, msg, "On a tag the annotation's one channel is typed meta (decision 302): `decl.setMeta(v)` / `decl.addMeta(v)`, read back by the template function with `d.meta(T)` / `d.metaAll(T)`.");
            },
        },
        .fail => |fl| {
            if (fl.arg) |j| if (j < values.len) if (values[j].loc) |l| {
                env.lastError = TypeError.custom(fl.message, "raised by the annotation via `fail` on this argument").withLoc(l);
                return error.TypeError;
            };
            return decoratorError(env, a, fl.message, "raised by the annotation via `fail`/`failAt`");
        },
        .err => |msg| return decoratorError(env, a, msg, "the annotation could not be evaluated"),
        .raised => |failed| return raisedFrom(env, failed.message, "the annotation's body raised; each call of the chain is a `called from` line, down to the annotation", failed.frames, a.loc orelse .{ .line = 1, .col = 1 }),
    }
    var out = base;
    out.tagMeta = metas.items;
    return out;
}

/// The records a template body's catalogue answer builds (`Declared`,
/// `DeclaredMeta`), as the template's comptime module declares them.
const template_declared_src =
    \\type DeclaredMeta(key: string, value: string)
    \\type DeclaredTypedMeta(key: string, value: unknown)
    \\type Declared(name: string, module: string, meta: DeclaredMeta[], returnTypeName: string, value: unknown, typedMeta: DeclaredTypedMeta[])
;

/// The queries a template function's body writes (`noteTemplateQueries`, by
/// its owner and name), or none.
fn templateQueriesOf(env: *Env, owner: []const u8, tfn: ast.FnDecl) InferError![]const reflectionMod.TemplateQuery {
    const r = env.reflection orelse return &.{};
    return r.templateQueries.get(try reflectionMod.Reflection.templateKey(env.arena, owner, tfn.name)) orelse &.{};
}

/// Decision 353 — `tfn` with each `@TypeInfo.all(…)` of its body replaced by
/// the answer for the program this expansion (at `loc`) is compiled in
/// (`typeinfo_all.answerForTemplate`), every answer recorded for the session's
/// staleness check (`Reflection.templateReads`), and the record declarations
/// the answers build. A rule of the catalogue the answer breaks is refused at
/// the expansion.
fn answerTemplateQueries(env: *Env, owner: []const u8, tfn: ast.FnDecl, loc: ast.Loc) InferError!struct { decl: ast.FnDecl, types: []const ast.DeclKind } {
    const queries = try templateQueriesOf(env, owner, tfn);
    if (queries.len == 0) return .{ .decl = tfn, .types = &.{} };
    const r = env.reflection.?;
    var answers: std.AutoHashMapUnmanaged(ast.Loc, *const ast.Expr) = .empty;
    var unvalued: ?[]const u8 = null;
    for (queries) |q| switch (try typeinfoAll.answerForTemplate(env.arena, r, q, loc)) {
        .ok => |a| {
            try answers.put(env.arena, q.loc, a.expr);
            try r.templateReads.append(r.arena, .{ .module = env.modulePath, .loc = loc, .query = q, .text = a.text });
            if (unvalued == null) unvalued = a.unvalued;
        },
        .refused => |te| {
            env.lastError = te;
            return error.TypeError;
        },
    };
    // Decision 356 — the body reads an entry's `value`, and an entry of the
    // answer is no `val` with a `comptime` initializer: refused at the read
    // when the template is this module's, else at the expansion naming it.
    if (unvalued) |entry| if (r.templateValueReads.get(try reflectionMod.Reflection.templateKey(env.arena, owner, tfn.name))) |read| {
        const mine = std.mem.eql(u8, owner, env.modulePath);
        // `entry` names the first such entry where the read is another module's.
        const msg = if (mine)
            try std.fmt.allocPrint(env.arena, "{s}: a template body reads the catalogue at build, where a declaration of the program is no value", .{diagnostics.typeinfo_all_template_value})
        else
            try std.fmt.allocPrint(env.arena, "{s}: the template expanded here reads an entry's `value` (at {s}:{d}:{d}), and `{s}` is no `val` whose initializer is `comptime` — it has no build value", .{ diagnostics.typeinfo_all_template_value, srcPathOfModule(env, owner), read.line, read.col, entry });
        env.lastError = TypeError.custom(msg, "Only a `val` whose initializer is `comptime` has a value at build (decision 356); read `name`, `module`, `meta` and `returnTypeName` of any other entry.").withLoc(if (mine) read else loc);
        return error.TypeError;
    };
    var lx = Lexer.init(template_declared_src);
    const tokens = lx.scanAll(env.arena) catch return error.OutOfMemory;
    var p = Parser.init(tokens);
    const decls = p.parse(env.arena) catch return error.OutOfMemory;
    return .{ .decl = try typeinfoAll.substitute(env.arena, tfn, &answers), .types = decls.decls };
}

/// Decision 112 — the names the template's LIBRARY wrote into `parsed` (the
/// built code of `src`) resolve in the library's module (`dsl_hygiene.zig`);
/// the consumer's text keeps resolving here. A template declared in this very
/// module has one author's scope and is left alone.
fn applyDslHygiene(env: *Env, tfn: ast.FnDecl, parsed: *ast.Expr, src: []const u8, origin: ast.Loc, captures: []const template.CapturedExpr) InferError!void {
    const owner = env.comptimeOwnerOf(tfn);
    if (std.mem.eql(u8, owner, env.modulePath)) return;
    const exports = env.templateOwnerExports.get(owner) orelse return;
    const spans = try dslHygiene.userSpans(env.arena, src, captures);
    try dslHygiene.apply(env.arena, parsed, src, origin, spans, HygieneResolver{ .env = env, .owner = owner, .exports = exports });
}

/// Decisions 112, 625 (2) — every name of a `compiler.ast` tree is the
/// library's (the caller's code a `Syntax` holds is spliced after).
fn applyAstHygiene(env: *Env, tfn: ast.FnDecl, root: *ast.Expr) InferError!void {
    const owner = env.comptimeOwnerOf(tfn);
    if (std.mem.eql(u8, owner, env.modulePath)) return;
    const exports = env.templateOwnerExports.get(owner) orelse return;
    try dslHygiene.applyAll(env.arena, root, HygieneResolver{ .env = env, .owner = owner, .exports = exports });
}

/// A name the template's owner module declares, bound under its alias.
const HygieneResolver = struct {
    env: *Env,
    owner: []const u8,
    exports: *const std.StringHashMap(*T.Type),

    pub fn aliasFor(self: @This(), name: []const u8) dslHygiene.Error!?[]const u8 {
        const ty = self.exports.get(name) orelse
            self.exports.get(try envMod.templatePrivateKey(self.env.arena, name)) orelse return null;
        const alias = try envMod.templateAlias(self.env.arena, self.owner, name);
        if (!self.env.templateImports.contains(alias)) {
            try self.env.templateImports.put(self.env.arena, alias, .{ .owner = self.owner, .name = name });
            // Module-wide, like an import: the expansion may sit in a
            // body whose scope closes before the next one uses it.
            const scope = self.env.bodyScope;
            self.env.bodyScope = null;
            defer self.env.bodyScope = scope;
            // Decision 310 — renamed as an imported value's type is.
            try self.env.bind(alias, try renameImportedType(self.env, ty, self.owner));
        }
        return alias;
    }
};

/// Replace `__bp_hole_<param>_<i>` placeholder identifiers in freshly parsed
/// template output with the caller's hole expressions (the i-th `${…}` part
/// of the named capture). The parsed tree is private to this expansion, so
/// in-place mutation is safe. Walks every expression-bearing position the
/// surface produces — closure / fn bodies, branches, loops, bindings, jumps —
/// so a template that splices its hole inside a lambda body (e.g. a query
/// DSL building `{ row -> row.x == __bp_hole_q_0 }`) still resolves.
fn substituteHoles(e: *ast.Expr, captures: []const template.CapturedExpr) void {
    switch (e.*) {
        .identifier => |id| switch (id.kind) {
            .ident => |name| {
                const hole = holeForPlaceholder(name, captures) orelse return;
                e.* = hole.*;
            },
            .identAccess => |ia| substituteHoles(ia.receiver, captures),
            else => {},
        },
        .binaryOp => |b| {
            substituteHoles(b.lhs, captures);
            substituteHoles(b.rhs, captures);
        },
        .unaryOp => |u| substituteHoles(u.expr, captures),
        .call => |c| switch (c.kind) {
            .call => |cc| {
                if (cc.receiver) |r| substituteHoles(r, captures);
                for (cc.args) |arg| substituteHoles(arg.value, captures);
                for (cc.trailing) |tl| substituteHolesStmts(tl.body, captures);
            },
            .pipeline => |pl| {
                substituteHoles(pl.lhs, captures);
                substituteHoles(pl.rhs, captures);
            },
        },
        .collection => |col| switch (col.kind) {
            .grouped => |g| substituteHoles(g, captures),
            .arrayLit => |al| for (al.elems) |*elem| substituteHoles(elem, captures),
            .tupleLit => |tl| for (tl.elems) |*elem| substituteHoles(elem, captures),
            else => {},
        },
        .literal => |lit| switch (lit.kind) {
            .stringTemplate => |t| for (t.parts) |part| switch (part) {
                .text => {},
                .expr => |hole| substituteHoles(hole, captures),
            },
            else => {},
        },
        .function => |fe| substituteHolesStmts(fe.kind.body, captures),
        .branch => |br| switch (br.kind) {
            .if_ => |i| {
                substituteHoles(i.cond, captures);
                substituteHolesStmts(i.then_, captures);
                if (i.else_) |els| substituteHolesStmts(els, captures);
            },
            .tryCatch => |tc| {
                substituteHoles(tc.expr, captures);
                substituteHoles(tc.handler, captures);
            },
        },
        .loop => |lp| {
            substituteHoles(lp.iter, captures);
            if (lp.indexRange) |ir| substituteHoles(ir, captures);
            substituteHolesStmts(lp.body, captures);
        },
        .binding => |bd| switch (bd.kind) {
            .localBind => |lb| substituteHoles(lb.value, captures),
            .assign => |as| {
                switch (as.target) {
                    .name => {},
                    .fieldAccess => |fa| substituteHoles(fa.receiver, captures),
                }
                substituteHoles(as.value, captures);
            },
            .localBindDestruct => |dd| substituteHoles(dd.value, captures),
        },
        .jump => |jp| switch (jp.kind) {
            .@"return" => |r| if (r) |expr| substituteHoles(expr, captures),
            .throw_ => |t| if (t) |expr| substituteHoles(expr, captures),
            .try_ => |t| if (t) |expr| substituteHoles(expr, captures),
            .await_ => |a| substituteHoles(a, captures),
            .@"break" => |b| if (b.value) |expr| substituteHoles(expr, captures),
            .@"continue" => {},
            .yield => |y| if (y.value) |expr| substituteHoles(expr, captures),
        },
        else => {},
    }
}

/// Walk a statement list and run `substituteHoles` over each statement's
/// expression. Used for function bodies, branch arms, loop bodies — every
/// place the surface threads a `[]Stmt` instead of a single expression.
fn substituteHolesStmts(stmts: []ast.Stmt, captures: []const template.CapturedExpr) void {
    for (stmts) |*s| substituteHoles(&s.expr, captures);
}

/// Resolve a `__bp_hole_<param>_<i>` placeholder to the i-th `${…}` hole
/// expression of the named capture, or null for ordinary identifiers.
fn holeForPlaceholder(name: []const u8, captures: []const template.CapturedExpr) ?*const ast.Expr {
    const prefix = "__bp_hole_";
    if (!std.mem.startsWith(u8, name, prefix)) return null;
    const rest = name[prefix.len..];
    const sep = std.mem.lastIndexOfScalar(u8, rest, '_') orelse return null;
    const param = rest[0..sep];
    const idx = std.fmt.parseInt(usize, rest[sep + 1 ..], 10) catch return null;

    for (captures) |cap| {
        if (!std.mem.eql(u8, cap.paramName, param)) continue;
        if (cap.node.* != .literal or cap.node.literal.kind != .stringTemplate) return null;
        var holeIdx: usize = 0;
        for (cap.node.literal.kind.stringTemplate.parts) |part| switch (part) {
            .text => {},
            .expr => |hole| {
                if (holeIdx == idx) return hole;
                holeIdx += 1;
            },
        };
        return null;
    }
    return null;
}

/// The labels of a tuple a template lifts (decision 8 §6), read from the
/// template body: `return @expr(#(server, debug))` labels its elements
/// `server` and `debug`, and `val server = #(host, port)` earlier in the body
/// labels the nested tuple. Children follow the elements; null = unlabeled.
const LiftShape = struct {
    labels: []const []const u8,
    children: []const ?*const LiftShape,
};

/// The shape of the value `tfn` lifts through `return @expr(E)` — the first
/// such return in the body — or null when the body builds no labeled tuple.
fn liftShapeOf(env: *Env, tfn: ast.FnDecl) ?*const LiftShape {
    for (tfn.body) |stmt| {
        if (stmt.expr != .jump or stmt.expr.jump.kind != .@"return") continue;
        const ret = stmt.expr.jump.kind.@"return" orelse continue;
        if (ret.* != .call or ret.call.kind != .call) continue;
        const cc = ret.call.kind.call;
        if (!cc.is_builtin or cc.args.len != 1 or !std.mem.eql(u8, cc.callee, "expr")) continue;
        return shapeOfExpr(env, tfn.body, cc.args[0].value.*, 0);
    }
    return null;
}

fn shapeOfExpr(env: *Env, body: []const ast.Stmt, e: ast.Expr, depth: usize) ?*const LiftShape {
    if (depth > 16) return null;
    switch (e) {
        .identifier => |id| {
            if (id.kind != .ident) return null;
            // The last `val`/`var` binding of that name in the body.
            var bound: ?*const ast.Expr = null;
            for (body) |stmt| {
                if (stmt.expr == .binding and stmt.expr.binding.kind == .localBind) {
                    const lb = stmt.expr.binding.kind.localBind;
                    if (std.mem.eql(u8, lb.name, id.kind.ident)) bound = lb.value;
                }
            }
            return if (bound) |b| shapeOfExpr(env, body, b.*, depth + 1) else null;
        },
        .collection => |col| switch (col.kind) {
            .grouped => |g| return shapeOfExpr(env, body, g.*, depth + 1),
            .tupleLit => |tl| {
                const labels = env.arena.alloc([]const u8, tl.elems.len) catch return null;
                const children = env.arena.alloc(?*const LiftShape, tl.elems.len) catch return null;
                for (tl.elems, 0..) |elem, i| {
                    labels[i] = if (elem == .identifier and elem.identifier.kind == .ident) elem.identifier.kind.ident else "";
                    children[i] = shapeOfExpr(env, body, elem, depth + 1);
                }
                const shape = env.arena.create(LiftShape) catch return null;
                shape.* = .{ .labels = labels, .children = children };
                return shape;
            },
            else => return null,
        },
        else => return null,
    }
}

/// Build a literal expression from a TypedValue produced by template evaluation.
/// A tuple takes the labels `shape` names; an object (a map the host built)
/// lifts as a tuple labeled by its keys.
fn valueToAstLiteral(env: *Env, v: templateEval.TypedValue, loc: ast.Loc, shape: ?*const LiftShape) ?*const ast.Expr {
    const node = env.arena.create(ast.Expr) catch return null;
    switch (v) {
        .integer => |n| {
            const text = std.fmt.allocPrint(env.arena, "{d}", .{n}) catch return null;
            node.* = .{ .literal = .{ .loc = loc, .kind = .{ .numberLit = text } } };
        },
        .float => |f| {
            // Decision 247 — a lifted float keeps its decimal point: `6.0`
            // printed as `6` would come back an integer literal, an `i32`.
            const raw = std.fmt.allocPrint(env.arena, "{d}", .{f}) catch return null;
            const text = if (std.mem.indexOfAny(u8, raw, ".eEn") == null) std.fmt.allocPrint(env.arena, "{s}.0", .{raw}) catch return null else raw;
            node.* = .{ .literal = .{ .loc = loc, .kind = .{ .numberLit = text } } };
        },
        .string => |str| {
            // The literal spells the value: its `\`, `"`, `$` and control
            // bytes escaped (a template text's raw bytes reach here, 577).
            const text = blockEval.stringLexeme(env.arena, str) catch return null;
            node.* = .{ .literal = .{ .loc = loc, .kind = .{ .stringLit = text } } };
        },
        .bool => |b| {
            node.* = .{ .identifier = .{ .loc = loc, .kind = .{ .ident = if (b) "true" else "false" } } };
        },
        .null => {
            node.* = .{ .literal = .{ .loc = loc, .kind = .null_ } };
        },
        .array => |items| {
            const elems = env.arena.alloc(ast.Expr, items.len) catch return null;
            for (items, 0..) |item, i| {
                const elem = valueToAstLiteral(env, item, loc, null) orelse return null;
                elems[i] = elem.*;
            }
            node.* = .{ .collection = .{ .loc = loc, .kind = .{ .arrayLit = .{ .elems = elems } } } };
        },
        .tuple => |items| {
            // The yaml case: the template computes a structure and the caller
            // gets a fully typed tuple whose labels come from the body.
            const matches = if (shape) |sh| sh.labels.len == items.len else false;
            const elems = env.arena.alloc(ast.Expr, items.len) catch return null;
            for (items, 0..) |item, i| {
                const child: ?*const LiftShape = if (matches) shape.?.children[i] else null;
                const elem = valueToAstLiteral(env, item, loc, child) orelse return null;
                elems[i] = elem.*;
            }
            node.* = .{ .collection = .{ .loc = loc, .kind = .{ .tupleLit = .{
                .elems = elems,
                .labels = if (matches) shape.?.labels else &.{},
            } } } };
        },
        .object => |pairs| {
            // A map built by host code lifts as a tuple labeled by its keys.
            const elems = env.arena.alloc(ast.Expr, pairs.len) catch return null;
            const labels = env.arena.alloc([]const u8, pairs.len) catch return null;
            for (pairs, 0..) |pair, i| {
                const value = valueToAstLiteral(env, pair.value, loc, null) orelse return null;
                elems[i] = value.*;
                labels[i] = env.arena.dupe(u8, pair.key) catch return null;
            }
            node.* = .{ .collection = .{ .loc = loc, .kind = .{ .tupleLit = .{ .elems = elems, .labels = labels } } } };
        },
    }
    return node;
}

/// What a V1-expandable template body (`return E`) reduces to. Construction
/// is explicit: no implicit value lifting — a constant only becomes code via
/// `@expr(…)`, and generated source only via `@code(…)`.
const TemplateBody = union(enum) {
    /// `return <expr param>` — the captured argument splices in unchanged.
    capture: *const ast.Expr,
    /// `return @expr(E)` — lift the explicit expression as code.
    lifted: *const ast.Expr,
    /// `return @code("…")` — parse the source text into code.
    code: []const u8,
};

/// Classify a template body for the V1 expansion driver, or null when the
/// body needs the runtime-backed evaluator (F6-full).
fn classifyTemplateBody(tfn: ast.FnDecl, captures: []const template.CapturedExpr) ?TemplateBody {
    if (tfn.body.len != 1) return null;
    const stmt = tfn.body[0];
    if (stmt.expr != .jump) return null;
    if (stmt.expr.jump.kind != .@"return") return null;
    const ret = stmt.expr.jump.kind.@"return" orelse return null;

    switch (ret.*) {
        // `return template` — pass-through: an @Expr param IS an expr value.
        .identifier => |id| {
            if (id.kind != .ident) return null;
            const node = captureNodeFor(captures, id.kind.ident) orelse return null;
            return .{ .capture = node };
        },
        // `return @expr(E)` / `return @code("…")` — explicit construction.
        .call => |c| {
            if (c.kind != .call) return null;
            const cc = c.kind.call;
            if (!cc.is_builtin or cc.args.len != 1) return null;
            const arg = cc.args[0].value;
            if (std.mem.eql(u8, cc.callee, "expr")) {
                // A lifted expression must not reference the template's own
                // parameters — splicing `t` into the caller would leave an
                // unbound name. Such bodies go to the eval runtime instead.
                for (tfn.params) |p| {
                    if (specializeMod.identInExpr(arg.*, p.name)) return null;
                }
                return if (isV1Liftable(arg)) .{ .lifted = arg } else null;
            }
            if (std.mem.eql(u8, cc.callee, "code")) {
                if (arg.* == .literal and arg.literal.kind == .stringLit) {
                    return .{ .code = arg.literal.kind.stringLit };
                }
                return null;
            }
            return null;
        },
        else => return null,
    }
}

/// Decision 429 — where an expansion's built code is located: a new
/// expansion id of this module, at the line and column of the literal the
/// template reads (`q.source()`, the first capture) or, with no capture, of
/// the call.
fn builtCodeOrigin(env: *Env, captures: []const template.CapturedExpr, loc: ast.Loc) ast.Loc {
    env.expansionCount += 1;
    const at = if (captures.len > 0) captures[0].loc else loc;
    return .{ .line = at.line, .col = at.col, .expansion = env.expansionCount };
}

/// Parse `@code` source text into an expression (allocated in the env arena).
/// Null when the text fails to lex/parse as a single expression. Every token
/// is located at `origin` (decision 429, `builtCodeOrigin`): its offset in
/// `src` read from the literal's line and column, in `origin`'s expansion.
fn parseCodeText(env: *Env, src: []const u8, origin: ast.Loc) ?*const ast.Expr {
    var lx = Lexer.init(src);
    const tokens = lx.scanAll(env.arena) catch return null;
    for (@constCast(tokens)) |*tok| {
        if (tok.line == 1) tok.col += origin.col -| 1;
        tok.line += origin.line -| 1;
        tok.expansion = origin.expansion;
    }
    var p = Parser.init(tokens);
    const node = env.arena.create(ast.Expr) catch return null;
    node.* = p.parseExpr(env.arena) catch return null;
    if (!p.check(.endOfFile)) return null;
    return node;
}

/// `parseCodeText` for the code a template answers from a template text
/// (decision 577 (1), 14s8-a (e)), located in the caller's file
/// (`template.mapSpanToLoc`) so an error in the built code is refused where
/// the text it came from is written:
///
/// - the text a leaf `CustomNode` of a `compiler.custom` tree spans is found
///   in the built code, in tree order, and its tokens are located at that span;
/// - every other identifier, number or string token the built code copied from
///   the template text — a hole's expression the sub-language parsed out of
///   `compiler.text(q)` and spliced — is located at its occurrence in the text
///   (a whole word at or after the previous match, outside every leaf's span,
///   so no two tokens share a location), on its own line of a multi-line text;
///   a name the template's own module declares is not looked up, so
///   `applyDslHygiene` still reads its offset in the code (decision 112);
/// - the rest keeps `builtCodeOrigin`'s location, its offset in the code.
fn parseCodeTextAt(env: *Env, tfn: ast.FnDecl, src: []const u8, origin: ast.Loc, cap: ?*const template.CapturedExpr, root: ?template.CustomNode) ?*const ast.Expr {
    const c = cap orelse return parseCodeText(env, src, origin);
    const text = c.text orelse return parseCodeText(env, src, origin);
    const Hole = struct { from: usize, to: usize, span_start: usize };
    var holes: std.ArrayListUnmanaged(Hole) = .empty;
    const Walk = struct {
        fn leaves(arena: std.mem.Allocator, n: template.CustomNode, out: *std.ArrayListUnmanaged(template.CustomNode)) !void {
            if (n.children.len == 0) return out.append(arena, n);
            for (n.children) |ch| try leaves(arena, ch, out);
        }
    };
    var leaves: std.ArrayListUnmanaged(template.CustomNode) = .empty;
    if (root) |r| Walk.leaves(env.arena, r, &leaves) catch return null;
    var cursor: usize = 0;
    for (leaves.items) |n| {
        if (n.span.end <= n.span.start or n.span.end > text.len) continue;
        const piece = text[n.span.start..n.span.end];
        const at = std.mem.indexOfPos(u8, src, cursor, piece) orelse continue;
        holes.append(env.arena, .{ .from = at, .to = at + piece.len, .span_start = n.span.start }) catch return null;
        cursor = at + piece.len;
    }
    // Copies are looked up only in a template text's raw bytes (577): a
    // string literal's `text` is escaped, its offsets are not the file's.
    if (holes.items.len == 0 and !c.templateText) return parseCodeText(env, src, origin);
    var lx = Lexer.init(src);
    const tokens = lx.scanAll(env.arena) catch return null;
    const owner = env.comptimeOwnerOf(tfn);
    const ownerExports = if (std.mem.eql(u8, owner, env.modulePath)) null else env.templateOwnerExports.get(owner);
    var copyCursor: usize = 0;
    for (@constCast(tokens)) |*tok| {
        const off = tok.offset;
        const hole: ?Hole = for (holes.items) |h| {
            if (off >= h.from and off < h.to) break h;
        } else null;
        const textAt: ?usize = if (hole) |h| h.span_start + (off - h.from) else if (c.templateText) copied: {
            if (tok.kind == .identifier) if (ownerExports) |ex| {
                if (ex.contains(tok.lexeme)) break :copied null;
                const key = envMod.templatePrivateKey(env.arena, tok.lexeme) catch return null;
                if (ex.contains(key)) break :copied null;
            };
            const at = copiedAt(text, tok.*, copyCursor, holes.items) orelse break :copied null;
            copyCursor = at + tok.lexeme.len;
            break :copied at;
        } else null;
        if (textAt) |t| {
            const at = template.mapSpanToLoc(c, .{ .start = t, .end = t, .line = 1 });
            tok.line = at.line;
            tok.col = at.col;
        } else {
            if (tok.line == 1) tok.col += origin.col -| 1;
            tok.line += origin.line -| 1;
        }
        tok.expansion = origin.expansion;
    }
    var p = Parser.init(tokens);
    const node = env.arena.create(ast.Expr) catch return null;
    node.* = p.parseExpr(env.arena) catch return null;
    if (!p.check(.endOfFile)) return null;
    return node;
}

/// Where a built-code token was copied from in the template text: the first
/// whole-word occurrence of its lexeme at or after `from` that no leaf span
/// (`taken`, each `span_start` and its length) covers; null for a token of
/// another kind, an empty string, or one the text does not spell after `from`
/// (`parseCodeTextAt`).
fn copiedAt(text: []const u8, tok: Token, from: usize, taken: anytype) ?usize {
    switch (tok.kind) {
        .identifier, .numberLiteral => {},
        .stringLiteral => if (tok.lexeme.len <= 2) return null,
        else => return null,
    }
    const word = tok.lexeme;
    if (word.len == 0) return null;
    const isWord = struct {
        fn f(ch: u8) bool {
            return std.ascii.isAlphanumeric(ch) or ch == '_';
        }
    }.f;
    const whole = struct {
        fn f(t: []const u8, w: []const u8, at: usize, comptime pred: fn (u8) bool) bool {
            if (pred(w[0]) and at > 0 and pred(t[at - 1])) return false;
            const end = at + w.len;
            if (pred(w[w.len - 1]) and end < t.len and pred(t[end])) return false;
            return true;
        }
    }.f;
    var pos = @min(from, text.len);
    search: while (std.mem.indexOfPos(u8, text, pos, word)) |at| : (pos = at + 1) {
        if (!whole(text, word, at, isWord)) continue;
        for (taken) |h| if (at + word.len > h.span_start and at < h.span_start + (h.to - h.from)) continue :search;
        return at;
    }
    return null;
}

/// The source lexeme of a literal (or bool-identifier) argument bound to a plain
/// template parameter (`template.PlainArg.source`). Returns null when the
/// expression is not a supported constant (string, number, null, true/false).
fn literalSourceAlloc(arena: std.mem.Allocator, expr: *const ast.Expr) error{OutOfMemory}!?[]const u8 {
    // Booleans are identifiers in the AST (not literal nodes).
    if (expr.* == .identifier) {
        const name = switch (expr.identifier.kind) {
            .ident => |n| n,
            else => return null,
        };
        if (std.mem.eql(u8, name, "true")) return "true";
        if (std.mem.eql(u8, name, "false")) return "false";
        return null;
    }
    if (expr.* != .literal) return null;
    return switch (expr.literal.kind) {
        // stringLit holds the literal's raw content (escapes unprocessed).
        .stringLit => |s| try std.fmt.allocPrint(arena, "\"{s}\"", .{s}),
        // numberLit is stored as raw source text.
        .numberLit => |n| try std.fmt.allocPrint(arena, "{s}", .{n}),
        .null_ => "null",
        else => null,
    };
}

/// The captured argument bound to the `@Expr` parameter named `name`.
fn captureNodeFor(captures: []const template.CapturedExpr, name: []const u8) ?*const ast.Expr {
    for (captures) |cap| {
        if (std.mem.eql(u8, cap.paramName, name)) return cap.node;
        // Decision 637 — a hole of the capture's text.
        for (cap.holes) |h| if (std.mem.eql(u8, h.paramName, name)) return h.node;
    }
    return null;
}

/// Decision 637 — `captures` with the `${…}` holes of each template text
/// parsed, each a capture of its own located where it is written in the
/// caller's text (`template.mapSpanToLoc`): what `compiler.holes(t)` answers.
/// A hole that is no expression is refused at it.
fn withHoleCaptures(env: *Env, captures: []const template.CapturedExpr) InferError![]const template.CapturedExpr {
    const out = try env.arena.dupe(template.CapturedExpr, captures);
    for (out) |*cap| {
        if (!cap.templateText) continue;
        const text = cap.text orelse continue;
        const spans = try template.holeSpans(env.arena, text);
        if (spans.len == 0) continue;
        const holes = try env.arena.alloc(template.CapturedExpr, spans.len);
        for (spans, holes, 0..) |sp, *h, i| {
            const src = text[sp.start..sp.end];
            const at = template.mapSpanToLoc(cap, sp);
            const node = parseCodeText(env, src, at) orelse {
                const msg = try std.fmt.allocPrint(env.arena, "this hole is no expression: `${{{s}}}`", .{src});
                env.lastError = TypeError.custom(msg, "A `${…}` hole of a template text holds one expression of the caller's (decision 637).").withLoc(at);
                return error.TypeError;
            };
            h.* = cap.*;
            h.paramName = try std.fmt.allocPrint(env.arena, "{s}#{d}", .{ cap.paramName, i });
            h.node = node;
            h.text = src;
            h.templateText = false;
            h.multiline = false;
            h.loc = at;
            h.holes = &.{};
            h.holeValues = &.{};
            h.tagAnswers = &.{};
            h.handles = &.{};
            h.valueRead = false;
        }
        cap.holes = holes;
    }
    return out;
}

/// True when `e` is a V1-liftable expression for `@expr(…)` — literals,
/// identifiers, operators, calls, collections. Control flow is conservatively
/// left to the runtime-backed evaluator (F6-full).
fn isV1Liftable(e: *const ast.Expr) bool {
    return switch (e.*) {
        .comptime_ => |ct| switch (ct.kind) {
            .comptimeExpr => |inner| isV1Liftable(inner),
            else => false,
        },
        .literal => |lit| switch (lit.kind) {
            .stringTemplate => |t| blk: {
                for (t.parts) |p| switch (p) {
                    .text => {},
                    .expr => |hole| if (!isV1Liftable(hole)) break :blk false,
                };
                break :blk true;
            },
            else => true,
        },
        .identifier => |id| switch (id.kind) {
            .identAccess => |ia| isV1Liftable(ia.receiver),
            else => true,
        },
        .binaryOp => |b| isV1Liftable(b.lhs) and isV1Liftable(b.rhs),
        .unaryOp => |u| isV1Liftable(u.expr),
        .call => |c| switch (c.kind) {
            .call => |cc| blk: {
                if (cc.receiver) |r| if (!isV1Liftable(r)) break :blk false;
                for (cc.args) |a| if (!isV1Liftable(a.value)) break :blk false;
                break :blk true;
            },
            .pipeline => |p| isV1Liftable(p.lhs) and isV1Liftable(p.rhs),
        },
        .collection => |col| switch (col.kind) {
            .grouped => |g| isV1Liftable(g),
            .arrayLit => |al| blk: {
                for (al.elems) |*elem| if (!isV1Liftable(elem)) break :blk false;
                break :blk true;
            },
            .tupleLit => |tl| blk: {
                for (tl.elems) |*elem| if (!isV1Liftable(elem)) break :blk false;
                break :blk true;
            },
            else => false,
        },
        else => false,
    };
}

/// Validate every constrained typeparam argument of a call against its declared
/// constraints. Unconstrained typeparams (empty `names`) accept any type.
/// On violation: sets `env.lastError` and returns `error.TypeError`.
fn validateTypeparams(
    env: *Env,
    constraints: []const envMod.TypeparamConstraint,
    typedArgs: []ast.CallArgOf(.typed),
) InferError!void {
    for (constraints) |c| {
        if (c.names.len == 0) continue; // unconstrained — accepts any type
        if (c.paramIndex >= typedArgs.len) continue;
        const argType = typedArgs[c.paramIndex].value.getType();
        var ok = false;
        for (c.names) |name| {
            if (typeSatisfiesConstraint(argType, name)) {
                ok = true;
                break;
            }
        }
        if (!ok) {
            env.lastError = TypeError
                .typeparamConstraint(c.paramName, argType, c.names)
                .withLoc(typedArgs[c.paramIndex].value.getLoc());
            return error.TypeError;
        }
    }
}

/// Gives `err`'s pending `TypeError` the location `loc` when it has none — the
/// stamp a caller holding the source position puts on an error raised below it
/// by `unifyUnlocated` (01 step 9). An error already located keeps its place.
fn locateLast(env: *Env, err: InferError, loc: ast.Loc) InferError {
    if (err == error.TypeError and loc.line != 0) {
        if (env.lastError) |*e| if (e.loc == null) {
            e.loc = loc;
        };
    }
    return err;
}

/// Calls `unify` and, if it fails, stamps the expression's location onto the error.
fn unifyAt(env: *Env, a: *T.Type, b: *T.Type, loc: ast.Loc) InferError!void {
    // `Children` coercion — applied before unification since `unifyAt` is
    // always called target-first (`unifyAt(param, arg)`).
    if (childrenCoercion(env, a, b)) return;
    // Decision 8 §6 T7 — read before `unify` links anything.
    const ta = a.deref();
    const tb = b.deref();
    unifyUnlocated(env, a, b) catch |err| {
        if (env.lastError) |*e| {
            // Decision 426 (4) — a template's `q.note(message)` rides an
            // error reported at its call.
            if (env.templateNotes.get(loc)) |notes| switch (e.kind) {
                .typeMismatch => |*m| m.notes = notes,
                else => {},
            };
            // The occurs check answers a type that would contain itself —
            // inside a generic fn, the declared `T` against a `?T` (`return
            // xs[0];` under `-> T`, an index answering `?T`) or a `T[]`. Named
            // as the mismatch it is, the type parameter spelled.
            if (e.kind == .recursiveType) {
                const msg = try std.fmt.allocPrint(env.arena, "type mismatch: expected `{s}`, got `{s}` — the second holds the first, so the two are never one type", .{ try genericSpelling(env, ta, 0), try genericSpelling(env, tb, 0) });
                const optional = tb.* == .named and std.mem.eql(u8, tb.named.name, "optional");
                env.lastError = TypeError.custom(msg, if (optional)
                    "An index and `at` answer an optional (`?T`): unwrap it (`xs[0] ?? fallback`, `case`) or declare the type `?T`."
                else
                    "Give the position the type the value has, or a value of the type the position declares.");
            }
            env.lastError.?.loc = loc;
        }
        return err;
    };
    try warnTupleLabelMismatch(env, ta, tb, loc);
}

/// A type as the source spells it, a generic fn's type parameter by its name
/// (`fnGenericMap`) — for the occurs-check refusal, where a bare `?` would say
/// nothing.
fn genericSpelling(env: *Env, t: *T.Type, depth: usize) InferError![]const u8 {
    const d = t.deref();
    if (depth > 8) return "…";
    switch (d.*) {
        .typeVar => {
            if (env.fnGenericMap) |gm| {
                var it = gm.iterator();
                while (it.next()) |e| if (e.value_ptr.*.deref() == d) return e.key_ptr.*;
            }
            return "?";
        },
        .named => |n| {
            if (std.mem.eql(u8, n.name, "optional") and n.args.len == 1) return std.fmt.allocPrint(env.arena, "?{s}", .{try genericSpelling(env, n.args[0], depth + 1)});
            if (std.mem.eql(u8, n.name, "array") and n.args.len == 1) return std.fmt.allocPrint(env.arena, "{s}[]", .{try genericSpelling(env, n.args[0], depth + 1)});
            if (n.args.len == 0) return n.name;
            var buf: std.ArrayListUnmanaged(u8) = .empty;
            try buf.appendSlice(env.arena, n.name);
            try buf.append(env.arena, '<');
            for (n.args, 0..) |a, i| {
                if (i > 0) try buf.appendSlice(env.arena, ", ");
                try buf.appendSlice(env.arena, try genericSpelling(env, a, depth + 1));
            }
            try buf.append(env.arena, '>');
            return buf.items;
        },
        else => return snapshotMod.typeNameOf(env.arena, d),
    }
}

/// Decision 8 §6 T7 — a tuple built from variables lends their names as
/// labels (T1); entering a written type whose label at that position is
/// another name, the written one wins (T3) and the author is told: the
/// variable's name says one thing and the type another. A warning (decision
/// 57's channel) — the program is fine, the names disagree.
fn warnTupleLabelMismatch(env: *Env, expected: *T.Type, got: *T.Type, loc: ast.Loc) InferError!void {
    if (expected == got) return;
    if (expected.* != .named or got.* != .named) return;
    if (!std.mem.eql(u8, expected.named.name, "tuple") or !std.mem.eql(u8, got.named.name, "tuple")) return;
    const want = expected.named.labels;
    const have = got.named.labels;
    if (want.len == 0 or have.len == 0) return;
    for (want, 0..) |w, i| {
        if (i >= have.len) break;
        const h = have[i];
        if (w.len == 0 or h.len == 0 or std.mem.eql(u8, w, h)) continue;
        const msg = try std.fmt.allocPrint(env.arena, "the variable `{s}` fills the element labeled `{s}`", .{ h, w });
        const hint = try std.fmt.allocPrint(env.arena, "The written type's label wins (decision 8 §6 T3): the element is read as `.{s}`. Rename the variable if it means the same thing.", .{w});
        try env.warn(TypeError.custom(msg, hint).withLoc(loc));
    }
}

/// True when `target` names a behavior and `source` is a named type that
/// implements it ([[typeImplementsBehavior]]) — a `MockCounter` returned where
/// the fn declares `-> Counter`.
fn behaviorCoercion(env: *Env, target: *T.Type, source: *T.Type) bool {
    const t = target.deref();
    const s = source.deref();
    if (t.* != .named or s.* != .named) return false;
    if (std.mem.eql(u8, t.named.name, s.named.name)) return false;
    return typeImplementsBehavior(env, s.named.name, t.named.name);
}

/// The checker's one answer to "does the declared type `typeName` implement
/// the behavior `behavior`": its own `implement` clause names `behavior` or a
/// behavior that `extends` it. An extension block (`Sym implement B for T`)
/// dispatches statically and makes no `T` a `B` value: no backend dispatches a
/// behavior call on a `T` to it.
fn typeImplementsBehavior(env: *Env, typeName: []const u8, behavior: []const u8) bool {
    const td = env.lookupTypeDef(typeName) orelse return false;
    const impls = switch (td) {
        .record => |r| r.implements,
        .struct_ => |st| st.implements,
        .enum_ => |e| e.implements,
    };
    for (impls) |i| if (behaviorReaches(env, i, behavior, 0)) return true;
    return false;
}

/// True when `ty` is a named `behavior` — declared here or imported.
fn isBehaviorType(env: *Env, ty: *T.Type) bool {
    const t = ty.deref();
    if (t.* != .named) return false;
    return env.behaviorDecl(t.named.name) != null;
}

/// 01 R4 — whether behavior `from` is `to` or extends it, through the
/// `extends` chain. `depth` bounds a cyclic chain.
fn behaviorReaches(env: *Env, from: []const u8, to: []const u8, depth: usize) bool {
    if (std.mem.eql(u8, from, to)) return true;
    if (depth >= 16) return false;
    const decl = env.behaviorDecl(from) orelse return false;
    for (decl.extends) |parent| {
        if (behaviorReaches(env, parent, to, depth + 1)) return true;
    }
    return false;
}

/// 01 R4 — an argument meets its declared parameter. A parameter (or a
/// constructor field) typed by a behavior accepts a value whose type
/// implements that behavior, directly or through `extends`; everything else
/// is `unifyAt`. Target-first, like `unifyAt`: the coercion only ever widens
/// an implementer into the behavior, never the reverse.
fn unifyArgument(env: *Env, param: *T.Type, arg: *T.Type, loc: ast.Loc) InferError!void {
    if (env.blockLocs.contains(loc)) try refuseBlockAt(env, param, arg, loc);
    if (behaviorCoercion(env, param, arg)) return;
    try unifyAt(env, param, arg, loc);
}

/// True when `source` coerces into a `Children`-typed `target`. A `Children`
/// parameter (the builder children model a markup DSL's `div { … }` needs)
/// accepts another `Children`, any array (`Element[]` — the list form), a
/// `string` (→ a text child), or a single value implementing `@Renderable` (an
/// `Element` → a one-element list). Coercion is one-directional: it only fires
/// when the *declared* type (`target`) is `Children`, never the reverse.
fn childrenCoercion(env: *Env, target: *T.Type, source: *T.Type) bool {
    const t = target.deref();
    if (t.* != .named or !std.mem.eql(u8, t.named.name, "Children")) return false;
    const s = source.deref();
    return switch (s.*) {
        .named => |n| std.mem.eql(u8, n.name, "Children") or
            std.mem.eql(u8, n.name, "array") or
            std.mem.eql(u8, n.name, "string") or
            isRenderableType(env, source),
        else => false,
    };
}
/// The refusal a `compiler_surface` builtin carries, reported at its place.
fn refuseSurface(env: *Env, args: []ast.CallArgOf(.typed), loc: ast.Loc) InferError {
    var parts: [3][]const u8 = .{ "", "", "" };
    for (args, 0..) |a, i| {
        if (i >= 3) break;
        if (a.value.* == .literal and a.value.literal.kind == .stringLit) parts[i] = a.value.literal.kind.stringLit;
    }
    const msg = try std.fmt.allocPrint(env.arena, "{s}: {s}", .{ parts[0], parts[1] });
    env.lastError = TypeError.custom(msg, parts[2]).withLoc(loc);
    return error.TypeError;
}

fn inferBuiltinCallReturnType(
    env: *Env,
    callee: []const u8,
    typedArgs: []ast.CallArgOf(.typed),
    typedTrailing: []ast.TrailingLambdaOf(.typed),
    loc: ast.Loc,
) InferError!*T.Type {
    // Decisions 575, 576 — a refusal `parser/compiler_surface.zig` wrote at
    // the place: `(code, message, hint)`.
    if (std.mem.eql(u8, callee, compilerSurface.refusal_builtin)) return refuseSurface(env, typedArgs, loc);
    // Decision 808 (1) — `compiler.init(f)` in a function whose every
    // parameter is `comptime` is typed `void` in its own module; where the
    // function is expanded, the executor's body is written at the call
    // (`expand_call.zig`).
    if (std.mem.eql(u8, callee, compilerSurface.init_here_builtin)) return env.namedType("void");
    try checkBuiltinArguments(env, callee, typedArgs, typedTrailing, loc);
    // ── `@Expr` construction builtins (expr-templates) ───────────────────────
    // Construction is explicit: `@expr(value)` lifts a comptime value as code
    // and `@code(text)` parses generated source text. Both only make sense
    // inside a template function (`-> @Expr<…>`), whose body runs at comptime.
    if (std.mem.eql(u8, callee, "expr") or std.mem.eql(u8, callee, "code")) {
        if (!env.inTemplateFn) {
            var e = TypeError.custom(
                "`@expr`/`@code` build comptime code — only valid inside a template function",
                "Declare the enclosing fn with a `-> @Expr<…>` return type.",
            );
            if (typedArgs.len >= 1) e = e.withLoc(typedArgs[0].value.getLoc());
            env.lastError = e;
            return error.TypeError;
        }
        if (std.mem.eql(u8, callee, "expr")) {
            // `@expr(v)`: the result is an expression OF the value's type.
            const inner: *T.Type = if (typedArgs.len >= 1) typedArgs[0].value.getType() else try env.freshVar();
            return env.namedTypeArgs(ast.expr_type_name, &.{inner});
        }
        // `@code(text)`: the produced expression's type is revealed at expansion.
        if (typedArgs.len >= 1) {
            try unifyAt(env, try env.namedType("string"), typedArgs[0].value.getType(), typedArgs[0].value.getLoc());
        }
        return env.namedTypeArgs(ast.expr_type_name, &.{try env.freshVar()});
    }

    // ── Type introspection / manipulation builtins (§1.0.0-beta) ─────────────
    // `@typeInfo(T) -> TypeInfo<T>` (decisions 248, 253) — the reflection of
    // `T`; its `.name` / `.meta.<d>.<k>` reads are answered before this arm
    // (`inferTypeinfoRead`). Comptime-only: no run-time code.
    if (std.mem.eql(u8, callee, "typeInfo")) {
        const reflected: *T.Type = blk: {
            if (typedArgs.len != 1) break :blk try env.freshVar();
            const arg = typedArgs[0].value;
            if (arg.* != .identifier or arg.identifier.kind != .ident) break :blk try env.freshVar();
            const name = arg.identifier.kind.ident;
            if (env.lookupTypeDef(name) == null and !isPrimitiveTypeName(name)) break :blk try env.freshVar();
            break :blk try env.namedType(name);
        };
        return env.namedTypeArgs("TypeInfo", &.{reflected});
    }
    // `@TypeOf(value: any) -> type` — returns the type of any value.
    // Comptime-only.
    if (std.mem.eql(u8, callee, "TypeOf")) {
        if (typedArgs.len > 0) return typedArgs[0].value.getType();
        return env.freshVar();
    }
    // `@makeRecord(fields: RecordField[]) -> type` — creates a new record type
    // from field descriptors. Comptime-only.
    if (std.mem.eql(u8, callee, "makeRecord")) {
        return env.freshVar();
    }
    // `@RecordKeys(T: type) -> string[]` — returns field name strings of a
    // record type. Comptime-only.
    if (std.mem.eql(u8, callee, "RecordKeys")) {
        // C6: the same `array` type a `string[]` annotation resolves to.
        return try env.namedTypeArgs("array", &.{try env.namedType("string")});
    }
    // `@Field(value: any, comptime name: string) -> any` — field access by
    // compile-time-known name. Comptime-only.
    if (std.mem.eql(u8, callee, "field")) {
        // C6: `@field(v, "x")` has the type of v's field `x` when the receiver
        // is a known non-generic record and the name is a literal; otherwise it
        // stays open (a fresh var), never the receiver's type.
        if (typedArgs.len >= 2) fieldBlk: {
            const recv = typedArgs[0].value.getType().deref();
            if (recv.* != .named) break :fieldBlk;
            const nameLit = switch (typedArgs[1].value.*) {
                .literal => |l| switch (l.kind) {
                    .stringLit => |str| str,
                    else => break :fieldBlk,
                },
                else => break :fieldBlk,
            };
            const td = env.lookupTypeDef(recv.named.name) orelse break :fieldBlk;
            const fields = switch (td) {
                .record => |r| if (r.genericParams.len == 0) r.fields else break :fieldBlk,
                .struct_ => |st| if (st.genericParams.len == 0) st.fields else break :fieldBlk,
                .enum_ => break :fieldBlk,
            };
            for (fields) |fd| {
                if (std.mem.eql(u8, fd.name, nameLit)) return fd.type_;
            }
            env.lastError = TypeError.unknownField(recv.named.name, nameLit).withLoc(typedArgs[1].value.getLoc());
            return error.TypeError;
        }
        return env.freshVar();
    }
    // `@emit(source)` — a comptime body (a decorator) contributes generated
    // top-level declarations, spliced into its module. Void; the source is parsed
    // + inferred in a second pass over the module (see `analyzeModule`).
    if (std.mem.eql(u8, callee, "emit")) {
        if (typedArgs.len >= 1) {
            try unifyAt(env, try env.namedType("string"), typedArgs[0].value.getType(), typedArgs[0].value.getLoc());
        }
        return env.namedType("void");
    }
    // `@comptimeError(message)` — report a compile-time error from comptime
    // code. Takes a string message and sets env.lastError, causing inference
    // to fail with a custom type error.
    if (std.mem.eql(u8, callee, "comptimeError")) {
        if (typedArgs.len >= 1) {
            const arg = typedArgs[0].value;
            const msg: []const u8 = switch (arg.*) {
                .literal => |lit| switch (lit.kind) {
                    .stringLit => |s| s,
                    else => "<non-string argument>",
                },
                else => "<non-literal argument>",
            };
            env.lastError = TypeError.custom(
                try std.fmt.allocPrint(env.arena, "comptime error: {s}", .{msg}),
                "This error was raised by @comptimeError during type checking.",
            ).withLoc(arg.getLoc());
            return error.TypeError;
        }
        env.lastError = TypeError.custom(
            "comptime error",
            "@comptimeError called without a message.",
        ).withLoc(loc);
        return error.TypeError;
    }
    // `@panic` / `@todo` / `@trap` never return: each is declared `-> noreturn`
    // (`failure.bp`'s `panic`, `primitives.bp`'s compiler section), and `noreturn` is the bottom type
    // `unify` accepts wherever a value is expected, so `val x: i32 = @todo();`
    // and `return @panic("…");` type in any position. A declared
    // `failure.bp`'s `panic` entry answers its own return; the name list only
    // holds the doc-only `trap`.
    if (builtinsMod.neverReturns(callee)) return env.namedType("noreturn");
    // `@module()` is declared `-> module` in `primitives.bp`'s compiler section but no target
    // lowers it (commonJS emitted `@module()` verbatim, erlang `module/0`
    // undefined): refused at the `@` rather than typed `void` in silence.
    if (std.mem.eql(u8, callee, "module")) {
        env.lastError = TypeError.custom(
            diagnostics.builtin_not_lowered ++ ": `@module()` is declared but no target lowers it",
            "Nothing reads a module value yet; import the module's members with `import {…} from \"…\"` instead.",
        ).withLoc(loc);
        return error.TypeError;
    }
    // The other builtins (`@print`, `@debug`, `@emit`, …) answer what their
    // declaration says — `void`. Anything else is a typo — refuse it
    // (decision 67) instead of compiling it to `void` in silence.
    if (isKnownBuiltinName(callee)) return env.namedType("void");
    env.lastError = TypeError.custom(
        try unknownBuiltinMessage(env, callee),
        "Builtin names are exact and lowercase (`@print`, `@panic`, `@src`); see `libs/std/src/primitives.bp`'s compiler section for the list.",
    ).withLoc(loc);
    return error.TypeError;
}

/// Decision 254 — the answer `typeinfo_all.plan` built for one
/// `@TypeInfo.all(…)`, typed `Declared<unknown>[]` whatever its entries are —
/// or, decision 564, `Declared<B>[]` when its decorators' `@Decl<B>` share
/// the behavior `behavior`.
/// Each entry is inferred on its own and met by `Declared<unknown>` (every
/// type is assignable to `unknown`), then carries that type: the entries never
/// unify with each other, so a function and a type's thunk, or two functions
/// of different signatures, sit in one answer.
fn inferCatalogueAnswer(env: *Env, answer: ast.Expr, loc: ast.Loc, behavior: ?[]const u8) InferError!TypedExpr {
    const declared_unknown = try env.namedTypeArgs("Declared", &.{try env.namedType("unknown")});
    const entry_type = if (behavior) |b| try env.namedTypeArgs("Declared", &.{try env.namedType(b)}) else declared_unknown;
    const array_type = try env.namedTypeArgs("array", &.{entry_type});
    if (answer != .collection or answer.collection.kind != .arrayLit) {
        const typed = try inferExprTyped(env, answer);
        try unifyAt(env, array_type, typed.getType(), loc);
        return typed;
    }
    const al = answer.collection.kind.arrayLit;
    const elems = try env.arena.alloc(ast.TypedExpr, al.elems.len);
    for (al.elems, 0..) |elem, i| {
        elems[i] = try inferExprTyped(env, elem);
        try unifyAt(env, declared_unknown, elems[i].getType(), elems[i].getLoc());
        switch (elems[i]) {
            inline else => |*e| e.type_ = entry_type,
        }
    }
    return TypedExpr{ .collection = .{ .loc = answer.collection.loc, .type_ = array_type, .kind = .{ .arrayLit = .{
        .elems = elems,
        .spread = al.spread,
        .spreadExpr = null,
        .comments = al.comments,
        .commentsPerElem = al.commentsPerElem,
        .trailingComma = al.trailingComma,
    } } } };
}

/// The type name `@src()` answers with (decision 73). Declared in
/// `comptime.zig`'s `decl_reflection_src`; spliced into a program that names it
/// by `withSourceLocationDecl`.
const source_location_type_name = "SourceLocation";

fn isKnownBuiltinName(callee: []const u8) bool {
    if (builtinsMod.find(callee) != null) return true;
    // The parser's own sugar: `x is T` lands as the `is` builtin and `xs[i]`
    // as the `[]` builtin call. Both are intercepted in `inferCallExpr`; the
    // names stay known for the parser's carriers only, so one that survived a
    // degraded module is not reported as a misspelled builtin — a hand-written
    // `@is(…)` is refused in `inferCallExpr` (decision 322).
    return std.mem.eql(u8, callee, ast.is_builtin_name) or std.mem.eql(u8, callee, ast.index_builtin_name) or
        std.mem.eql(u8, callee, ast.non_null_builtin_name);
}

pub fn isPrimitiveTypeName(name: []const u8) bool {
    const names = [_][]const u8{ "i8", "i16", "i32", "i64", "u8", "u16", "u32", "u64", "f32", "f64", "bool", "string", "void", "unknown" };
    for (names) |n| if (std.mem.eql(u8, n, name)) return true;
    return false;
}

/// Decision 252 — a call to a builtin held `.declaration` (`comptime/
/// builtins.zig`) meets its declaration (`Env.builtinDecls`, from
/// `primitives.bp`'s compiler section / `failure.bp`'s `panic`): no more arguments than it declares,
/// every parameter without a default given, a label naming a parameter, and
/// each argument's type the parameter's (generic parameters fresh per call; a
/// `type` parameter is the builtin's own to read). Refused at the call as
/// `builtin-arguments`, naming the declaration; a type that disagrees is the
/// ordinary mismatch, located at the argument.
fn checkBuiltinArguments(
    env: *Env,
    callee: []const u8,
    typedArgs: []ast.CallArgOf(.typed),
    typedTrailing: []ast.TrailingLambdaOf(.typed),
    loc: ast.Loc,
) InferError!void {
    const args = try env.arena.alloc(BuiltinArgument, typedArgs.len);
    for (typedArgs, args) |a, *out| out.* = .{ .label = a.label, .type_ = a.value.getType(), .loc = a.value.getLoc() };
    return checkDeclaredArguments(env, callee, args, typedTrailing.len, loc);
}

/// One argument of a builtin call, as `checkDeclaredArguments` reads it.
const BuiltinArgument = struct {
    label: ?[]const u8,
    type_: *T.Type,
    loc: ast.Loc,
};

/// `checkBuiltinArguments` over arguments typed by their caller — the
/// catalogue types `with:` by `decoratorArgumentType` (decision 268).
fn checkDeclaredArguments(
    env: *Env,
    callee: []const u8,
    typedArgs: []const BuiltinArgument,
    trailing: usize,
    loc: ast.Loc,
) InferError!void {
    const row = builtinsMod.find(callee) orelse return;
    if (row.held != .declaration) return;
    const decl = env.builtinDecls.get(callee) orelse return;
    const given = typedArgs.len + trailing;
    const refuse = struct {
        fn f(e: *Env, sig: []const u8, comptime fmt: []const u8, args: anytype, l: ast.Loc) InferError {
            const what = std.fmt.allocPrint(e.arena, fmt, args) catch return error.OutOfMemory;
            const msg = std.fmt.allocPrint(e.arena, "{s}: {s} — `@{s}` is declared in `primitives.bp`'s compiler section", .{ diagnostics.builtin_arguments, what, sig }) catch return error.OutOfMemory;
            e.lastError = TypeError.custom(msg, "Call it as its declaration says (`libs/std/src/primitives.bp`'s compiler section, decision 252).").withLoc(l);
            return error.TypeError;
        }
    }.f;
    // Decision 267 — a variadic last parameter takes every unlabelled
    // argument past the fixed ones, each checked against its element type.
    const variadicAt: ?usize = if (decl.params.len > 0 and decl.params[decl.params.len - 1].variadic) decl.params.len - 1 else null;
    if (variadicAt == null and given > decl.params.len) {
        return refuse(env, row.signature, "`@{s}` takes {d} argument{s}, {d} given", .{ callee, decl.params.len, if (decl.params.len == 1) "" else "s", given }, loc);
    }
    // Which parameter each argument binds: a label names one, an unlabelled
    // argument takes the next unbound, a trailing lambda the next after them.
    const bound = try env.arena.alloc(bool, decl.params.len);
    @memset(bound, false);
    var genericMap = std.StringHashMap(*T.Type).init(env.arena);
    for (decl.genericParams) |g| try genericMap.put(g.name, try env.freshVar());
    var next: usize = 0;
    for (typedArgs) |a| {
        if (variadicAt) |va| if (a.label == null) {
            while (next < va and bound[next]) next += 1;
            if (next >= va) {
                const p = decl.params[va];
                const want = try resolveTypeRefInContext(env, p.typeRef.array.*, genericMap);
                // Decision 332 — `@print(b)` writes a `bigint`'s digits; the
                // builtin's `unknown` is no run-time box a test reads.
                if (unifyMod.isUnknown(want) and unifyMod.mentionsBigint(a.type_)) continue;
                try unifyArgument(env, want, a.type_, a.loc);
                continue;
            }
        };
        const at: usize = if (a.label) |label| blk: {
            for (decl.params, 0..) |p, i| if (std.mem.eql(u8, p.name, label)) {
                if (p.variadic) return refuse(env, row.signature, "`{s}` of `@{s}` is variadic and takes no label", .{ label, callee }, a.loc);
                break :blk i;
            };
            return refuse(env, row.signature, "`@{s}` has no parameter `{s}`", .{ callee, label }, a.loc);
        } else blk: {
            while (next < bound.len and bound[next]) next += 1;
            break :blk next;
        };
        if (at >= bound.len or bound[at]) {
            return refuse(env, row.signature, "`@{s}` takes {d} argument{s}", .{ callee, decl.params.len, if (decl.params.len == 1) "" else "s" }, a.loc);
        }
        bound[at] = true;
        const p = decl.params[at];
        if (p.typeRef == .typeparam) continue;
        const want = try resolveTypeRefInContext(env, p.typeRef, genericMap);
        try unifyArgument(env, want, a.type_, a.loc);
    }
    for (0..trailing) |_| {
        while (next < bound.len and bound[next]) next += 1;
        if (next >= bound.len) return refuse(env, row.signature, "`@{s}` takes no trailing lambda", .{callee}, loc);
        bound[next] = true;
    }
    for (decl.params, bound) |p, b| {
        if (!b and p.default == null and !p.variadic) {
            return refuse(env, row.signature, "`@{s}` needs `{s}`", .{ callee, p.name }, loc);
        }
    }
}

/// Decision 332 — the primitive a call's receiver names as a type, when it
/// names one with associated functions (`bigint`; decision 346's `bytes`) and
/// no binding shadows it.
fn primitiveStaticReceiver(env: *Env, recv: ast.Expr) ?[]const u8 {
    if (recv != .identifier or recv.identifier.kind != .ident) return null;
    const name = recv.identifier.kind.ident;
    if (!std.mem.eql(u8, name, "bigint") and !std.mem.eql(u8, name, "bytes")) return null;
    // `registerBuiltins` binds each primitive's name to its type; a binding
    // of the name — a local, a parameter (`val bytes = b;`, decision 641's
    // lowercase names are ordinary ones) — shadows it, whatever its type.
    if (env.boundInBody(name)) return null;
    if (env.lookup(name)) |t| if (!t.deref().isNamed(name)) return null;
    return name;
}

/// Decision 332 — `bigint.of(n)` / `bigint.parse(text)`: the statics of
/// `primitives.bp`'s `pub type bigint { … }` (decision 262's form,
/// `string.fromCodepoint`'s; 641: the type holds them), called through the
/// type's own name. Each argument is inferred against its parameter (so
/// `bigint.of(5)` reads `5` as the `i64` it is passed as), and the backends
/// read the call through the type's member table (`bigint.of(…)`), the call
/// every one of them renders from its template. A name the type does not
/// declare is refused at the call.
fn inferPrimitiveStaticCall(env: *Env, call: anytype, recv: *ast.Expr, loc: ast.Loc) InferError!TypedExpr {
    const owner = recv.identifier.kind.ident;
    const iface = primitiveInterfaceName(owner) orelse unreachable;
    const key = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ iface, call.callee });
    const fnTy = env.lookup(key) orelse {
        const msg = try std.fmt.allocPrint(env.arena, "`{s}` has no associated function `{s}`", .{ owner, call.callee });
        const hint = if (std.mem.eql(u8, owner, "bytes"))
            "`bytes`' associated function is `bytes.fromUtf8(s)` (`primitives.bp`, decision 346); its methods are called on a value (`b.length()`)."
        else
            "`bigint`'s associated functions are `bigint.of(n)` and `bigint.parse(text)` (`primitives.bp`, decision 332); its methods are called on a value (`x.toString()`).";
        env.lastError = TypeError.custom(msg, hint).withLoc(loc);
        return error.TypeError;
    };
    const params: []const *T.Type = if (fnTy.deref().* == .func) fnTy.deref().func.params else &.{};
    const typedArgs = try env.arena.alloc(ast.CallArgOf(.typed), call.args.len);
    for (call.args, typedArgs, 0..) |a, *out, i| {
        const want: ?*T.Type = if (a.label == null and i < params.len) params[i] else null;
        const typed = try inferExprTypedExpecting(env, a.value.*, want);
        out.* = .{ .label = a.label, .value = try makeTypedPtr(env, typed) };
    }
    const typedTrailing = try env.arena.alloc(ast.TrailingLambdaOf(.typed), 0);
    const typedRecv = try env.arena.create(ast.TypedExpr);
    typedRecv.* = .{ .identifier = .{ .loc = recv.getLoc(), .type_ = try env.namedType(owner), .kind = .{ .ident = iface } } };
    const typed = try inferAssociatedFnCall(env, iface, call.callee, fnTy, typedRecv, typedArgs, typedTrailing, loc);
    // The program the backends lower calls the behavior by its name: the
    // receiver is renamed through the index channel, as decision 110's alias
    // is (`D.empty()`).
    if (!env.indexRewrites.contains(recv.getLoc())) {
        const ifaceRecv = try env.arena.create(ast.Expr);
        ifaceRecv.* = .{ .identifier = .{ .loc = recv.getLoc(), .kind = .{ .ident = iface } } };
        try env.indexRewrites.put(recv.getLoc(), ifaceRecv);
    }
    return typed;
}

/// Decision 268 — `@TypeInfo.all(…)`'s arguments against its declaration.
/// `with:` is typed by `decoratorArgumentType`; every other argument by
/// inference.
fn checkCatalogueArguments(env: *Env, call: anytype, loc: ast.Loc) InferError!void {
    const args = try env.arena.alloc(BuiltinArgument, call.args.len);
    for (call.args, args) |a, *out| {
        const is_with = if (a.label) |l| std.mem.eql(u8, l, "with") else false;
        const ty = if (is_with) (try decoratorArgumentType(env, a.value.*)) orelse (try inferExprTyped(env, a.value.*)).getType() else (try inferExprTyped(env, a.value.*)).getType();
        out.* = .{ .label = a.label, .type_ = ty, .loc = a.value.getLoc() };
        if (is_with) try refuseCatalogueOfHooksReader(env, a.value.*);
    }
    return checkDeclaredArguments(env, "TypeInfo.all", args, call.trailing.len, loc);
}

/// Decision 372 — a decorator `with:` names that reads `.hooks` and annotates
/// a declaration of this module runs after the module's bodies: the answer,
/// spliced while they are inferred, could not carry the meta it sets. Refused
/// at the name (`typeinfo-all-hooks-reader`, question s23-i); a reader of
/// another module ran before this one was analysed.
fn refuseCatalogueOfHooksReader(env: *Env, e: ast.Expr) InferError!void {
    if (env.hooksReaderIds.count() == 0) return;
    const names: []const ast.Expr = if (e == .collection and e.collection.kind == .arrayLit) e.collection.kind.arrayLit.elems else &.{e};
    for (names) |n| {
        const id = try decoratorNameId(env, n) orelse continue;
        if (!env.hooksReaderIds.contains(id)) continue;
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `@TypeInfo.all` lists a decorator that reads `.hooks` and annotates a declaration of this module; it runs after this module's bodies, so the answer could not carry its meta", .{diagnostics.typeinfo_all_hooks_reader});
        env.lastError = TypeError.custom(msg, "Read the catalogue from another module (an entry point is analysed after the modules it reaches), or read the meta with `@typeInfo(X).meta` (decision 372).").withLoc(n.getLoc());
        return error.TypeError;
    }
}

/// Decision 268 — the type `Decorator` is held only by a decorator's name: a
/// name (`component`, `web.route`) of a function whose first parameter is
/// `comptime _: @Decl` and which has a body is a `Decorator`, an array literal
/// of such names a `Decorator[]`. Null for anything else, which then keeps the
/// type inference gives it — no other value is assignable to `Decorator`.
fn decoratorArgumentType(env: *Env, e: ast.Expr) InferError!?*T.Type {
    if (e == .collection and e.collection.kind == .arrayLit) {
        const al = e.collection.kind.arrayLit;
        if (al.elems.len == 0 or al.spread != null or al.spreadExpr != null) return null;
        for (al.elems) |elem| if (!namesDecorator(env, elem)) return null;
        return try env.namedTypeArgs("array", &.{try env.namedType(decorator_type_name)});
    }
    if (!namesDecorator(env, e)) return null;
    return try env.namedType(decorator_type_name);
}

/// The builtin type of a decorator's name (`primitives.bp`'s compiler section, decision 268).
const decorator_type_name = "Decorator";

/// Decision 268 — `e`, an argument of a decorator parameter typed `w`, when
/// `w` is `Decorator` and `e` names a decorator, or `w` is `Decorator[]` and
/// `e` is an array literal of such names: each name is replaced by its
/// declaration's identity, the value a `Decorator` is carried as on the
/// comptime runtime (`decorator_same.zig`). False for anything else, which
/// then meets the parameter like any argument — the mismatch, since no other
/// value is a `Decorator`.
fn decoratorParamArg(env: *Env, e: *ast.Expr, w: *T.Type) InferError!bool {
    const d = w.deref();
    if (isDecoratorType(d)) {
        const id = try decoratorNameId(env, e.*) orelse return false;
        e.* = .{ .literal = .{ .loc = e.getLoc(), .kind = .{ .stringLit = id } } };
        return true;
    }
    if (d.* != .named or !std.mem.eql(u8, d.named.name, "array") or d.named.args.len != 1 or !isDecoratorType(d.named.args[0])) return false;
    if (e.* != .collection or e.collection.kind != .arrayLit) return false;
    const al = e.collection.kind.arrayLit;
    if (al.elems.len == 0 or al.spread != null or al.spreadExpr != null) return false;
    const ids = try env.arena.alloc([]const u8, al.elems.len);
    for (al.elems, ids) |elem, *id| id.* = try decoratorNameId(env, elem) orelse return false;
    const elems = try env.arena.alloc(ast.Expr, al.elems.len);
    for (al.elems, ids, elems) |elem, id, *out| out.* = .{ .literal = .{ .loc = elem.getLoc(), .kind = .{ .stringLit = id } } };
    var lit = al;
    lit.elems = elems;
    e.* = .{ .collection = .{ .loc = e.getLoc(), .kind = .{ .arrayLit = lit } } };
    return true;
}

fn isDecoratorType(t: *T.Type) bool {
    const d = t.deref();
    return d.* == .named and std.mem.eql(u8, d.named.name, decorator_type_name) and d.named.args.len == 0;
}

/// Decision 371 — `d.same(other)`, `fn same(self: Self, other: Decorator) ->
/// bool` of `primitives.bp`'s compiler section: `other` is a decorator's name (`serverOnly`,
/// `markers.serverOnly`, an alias — its declaration's identity, resolved
/// here) or a `Decorator` value (`b.decorator`); nothing else is a
/// `Decorator`, so any other argument is the mismatch at the argument. The
/// call is recorded (`Env.decoratorSame`) for the comptime runtime, which
/// compares the two identities (`decorator_same.zig`).
fn inferDecoratorSame(env: *Env, call: anytype, recv: *ast.TypedExpr, loc: ast.Loc) InferError!TypedExpr {
    const decoratorTy = try env.namedType(decorator_type_name);
    const labelOk = call.args.len == 1 and (call.args[0].label == null or std.mem.eql(u8, call.args[0].label.?, "other"));
    if (!labelOk or call.trailing.len != 0) {
        env.lastError = TypeError.custom(
            "`Decorator.same` takes one argument, `other: Decorator`",
            "Compare two decorators by their declaration: `a.decorator.same(serverOnly)` (decision 371).",
        ).withLoc(loc);
        return error.TypeError;
    }
    const arg = call.args[0].value.*;
    const argLoc = arg.getLoc();
    var other: ?[]const u8 = null;
    const typedArg: TypedExpr = if (try decoratorNameId(env, arg)) |id| blk: {
        other = id;
        break :blk .{ .literal = .{ .loc = argLoc, .type_ = decoratorTy, .kind = .{ .stringLit = id } } };
    } else blk: {
        const t = try inferExprTyped(env, arg);
        try unifyArgument(env, decoratorTy, t.getType(), argLoc);
        break :blk t;
    };
    try env.decoratorSame.put(env.arena, loc, .{ .other = other });
    const args = try env.arena.alloc(ast.CallArgOf(.typed), 1);
    args[0] = .{ .label = call.args[0].label, .value = try makeTypedPtr(env, typedArg) };
    return .{ .call = .{ .loc = loc, .type_ = try env.namedType("bool"), .kind = .{ .call = .{
        .receiver = recv,
        .callee = call.callee,
        .is_builtin = false,
        .args = args,
        .trailing = &.{},
    } } } };
}

/// The identity of the decorator `e` names — `name`, `ns.name`, an alias —
/// as `annotationDecoratorId` resolves an annotation's; null when `e` names
/// no decorator here, a local binding of the name included.
fn decoratorNameId(env: *Env, e: ast.Expr) InferError!?[]const u8 {
    if (e != .identifier) return null;
    const head: []const u8 = switch (e.identifier.kind) {
        .ident => |n| n,
        .identAccess => |ia| if (ia.receiver.* == .identifier and ia.receiver.identifier.kind == .ident) ia.receiver.identifier.kind.ident else return null,
        else => return null,
    };
    // A local of the body shadows the name — but for the binding a body
    // makes of its own function's name (self-recursion, `inferFnDecl`): in
    // `check`'s body, `check` is the decorator.
    if (env.localBindDepth(head)) |depth| {
        const self_binding = depth == 0 and std.mem.eql(u8, head, env.currentFnName) and
            (env.lookup(head) orelse return null).deref().* == .func;
        if (!self_binding) return null;
    }
    if (!namesDecorator(env, e)) return null;
    const spelled: []const u8 = switch (e.identifier.kind) {
        .ident => |n| n,
        else => try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ head, e.identifier.kind.identAccess.member }),
    };
    return try annotationDecoratorId(env, .{ .name = spelled, .args = &.{} });
}

/// Decision 371 — `f` with its `same` calls lowered for the comptime runtime
/// (`decorator_same.zig`) when `f` is a function of this module: the calls
/// were recorded by THIS module's inference, keyed by location, so a function
/// another module brought is left as it came (lowered when that module
/// exported it). `own` holds this module's functions by name.
pub fn lowerDecoratorSame(arena: std.mem.Allocator, env: *const Env, own: *const std.StringHashMap(ast.FnDecl), f: ast.FnDecl) !ast.FnDecl {
    const mine = own.get(f.name) orelse return f;
    if (mine.body.ptr != f.body.ptr) return f;
    return decoratorSameMod.lower(arena, &env.decoratorSame, f);
}

fn namesDecorator(env: *Env, e: ast.Expr) bool {
    if (e != .identifier) return false;
    const spelled: []const u8 = switch (e.identifier.kind) {
        .ident => |n| n,
        .identAccess => |ia| if (ia.receiver.* == .identifier and ia.receiver.identifier.kind == .ident)
            std.fmt.allocPrint(env.arena, "{s}.{s}", .{ ia.receiver.identifier.kind.ident, ia.member }) catch return false
        else
            return false,
        else => return false,
    };
    const sig = env.decorators.get(spelled) orelse return false;
    const f = sig.fn_decl orelse return false;
    // Decision 604 — a marker is a decorator with an empty body: only a
    // `declare fn` is bodyless.
    return f.body.len > 0 or !f.isDeclare;
}

/// `unknown-builtin: unknown builtin \`@name\`` — with the nearest known name
/// when one is an edit away (`@pritn` → `@print`), the way `removedBuiltinType`
/// points at a replacement.
fn unknownBuiltinMessage(env: *Env, callee: []const u8) ![]const u8 {
    for (builtinsMod.table) |row| {
        const candidate = row.name;
        if (editDistanceIsOne(callee, candidate)) {
            return std.fmt.allocPrint(
                env.arena,
                "{s}: unknown builtin `@{s}` — did you mean `@{s}`?",
                .{ diagnostics.unknown_builtin, callee, candidate },
            );
        }
    }
    return std.fmt.allocPrint(env.arena, "{s}: unknown builtin `@{s}`", .{ diagnostics.unknown_builtin, callee });
}

/// True when `a` becomes `b` by one substitution, one insertion, one deletion
/// or one adjacent transposition (case-insensitive: `@Src` is one edit from
/// `@src`).
fn editDistanceIsOne(a: []const u8, b: []const u8) bool {
    if (std.ascii.eqlIgnoreCase(a, b)) return a.len > 0 and !std.mem.eql(u8, a, b);
    if (a.len == b.len) {
        var diffs: usize = 0;
        var first: ?usize = null;
        for (a, b, 0..) |ca, cb, i| {
            if (std.ascii.toLower(ca) != std.ascii.toLower(cb)) {
                diffs += 1;
                if (first == null) first = i;
            }
        }
        if (diffs == 1) return true;
        if (diffs == 2) {
            const i = first.?;
            return i + 1 < a.len and
                std.ascii.toLower(a[i]) == std.ascii.toLower(b[i + 1]) and
                std.ascii.toLower(a[i + 1]) == std.ascii.toLower(b[i]);
        }
        return false;
    }
    const long, const short = if (a.len > b.len) .{ a, b } else .{ b, a };
    if (long.len != short.len + 1) return false;
    var i: usize = 0;
    var j: usize = 0;
    var skipped = false;
    while (i < long.len and j < short.len) {
        if (std.ascii.toLower(long[i]) == std.ascii.toLower(short[j])) {
            i += 1;
            j += 1;
        } else {
            if (skipped) return false;
            skipped = true;
            i += 1;
        }
    }
    return true;
}

/// True when `name` is the prelude record `__Source` or an alias of it.
fn callsSourceRecord(env: *Env, name: []const u8) bool {
    if (std.mem.eql(u8, name, "__Source")) return true;
    const alias = env.typeAliases.get(name) orelse return false;
    return switch (alias.target) {
        .named => |n| std.mem.eql(u8, n, "__Source"),
        else => false,
    };
}

/// `@src()` (1.0.10-beta front 01-std, decision 73): a `SourceLocation(file,
/// line, column, fnName)` naming the call site, evaluated here and never at
/// run time. The call is rewritten into the ordinary constructor call
/// `SourceLocation(file: "<env.srcPath>", line: L, column: C, fnName: "<env.currentFnName>")`
/// with four literal arguments: the typed node is that call (so the typed AST
/// carries the record type) and the untyped rewrite is recorded in
/// `env.srcRewrites` for the transform pass to splice, the way `@makeRecord`
/// and template expansions are. Every backend then lowers it through the
/// record-constructor path it already has — no codegen file knows `@src`.
///
/// `line`/`column` are the 1-based position of the `@` token — the numbers a
/// diagnostic prints; `file` is the package-relative path (`env.srcPath`);
/// `fnName` is the enclosing fn / `Type.method` / test name, `""` at module
/// level. Zero arguments, no trailing lambda: anything else is
/// `src-takes-no-arguments`.
fn inferSrcBuiltin(env: *Env, call: anytype, loc: ast.Loc) InferError!TypedExpr {
    if (call.args.len != 0 or call.trailing.len != 0) {
        env.lastError = TypeError.custom(
            diagnostics.src_takes_no_arguments ++ ": `@src()` takes no arguments",
            "Write `@src()` — the location is the call site's own; there is nothing to pass.",
        ).withLoc(loc);
        return error.TypeError;
    }
    env.usesSourceLocation = true;

    const strLit = struct {
        fn make(e: *Env, l: ast.Loc, text: []const u8) !*ast.Expr {
            const node = try e.arena.create(ast.Expr);
            node.* = .{ .literal = .{ .loc = l, .kind = .{ .stringLit = text } } };
            return node;
        }
        fn number(e: *Env, l: ast.Loc, n: usize) !*ast.Expr {
            const node = try e.arena.create(ast.Expr);
            node.* = .{ .literal = .{ .loc = l, .kind = .{ .numberLit = try std.fmt.allocPrint(e.arena, "{d}", .{n}) } } };
            return node;
        }
    };
    const args = try env.arena.alloc(ast.CallArg, 4);
    args[0] = .{ .label = "file", .value = try strLit.make(env, loc, env.srcPath) };
    args[1] = .{ .label = "line", .value = try strLit.number(env, loc, loc.line) };
    args[2] = .{ .label = "column", .value = try strLit.number(env, loc, loc.col) };
    args[3] = .{ .label = "fnName", .value = try strLit.make(env, loc, env.currentFnName) };
    const rewrite = try env.arena.create(ast.Expr);
    rewrite.* = .{ .call = .{ .loc = loc, .kind = .{ .call = .{
        .receiver = null,
        .callee = source_location_type_name,
        .is_builtin = false,
        .args = args,
        .trailing = &.{},
    } } } };
    // Decision 734 — in a decorator's body the place is the annotated
    // declaration's, one per run: the call stays, and the decorator's module
    // answers it (`decorator_eval.srcForm`).
    const params = env.currentParams;
    const inDecorator = (params.len > 0 and params[0].typeRef.isDeclType()) or (params.len > 1 and params[1].typeRef.isDeclType());
    if (!inDecorator) try env.srcRewrites.put(loc, rewrite);
    return inferExprTyped(env, rewrite.*);
}

/// Decision 519 — `@embed(path)`: the file `path` names in the package that
/// wrote it, read at build through the module's reader (`Env.packageFiles`)
/// and rewritten, like `@src()`, into the private record's constructor
/// `Asset(path: …, bytes: …, size: …, hash: …)` (`embed.asset`) — every
/// backend embeds the bytes, and the program never reads the file. A `Build`
/// builtin: the path is known at build (a literal, a constant `val`, a
/// `comptime`, an `Any` call of those — `blockEval.knownAtBuild`), else the
/// argument is refused (`comptime-arg-not-known`). An absolute path, one with
/// a `..` segment, a missing file and a compiler with no reader are refused.
fn inferEmbedBuiltin(env: *Env, call: anytype, loc: ast.Loc) InferError!TypedExpr {
    if (call.args.len != 1 or call.trailing.len != 0 or (call.args[0].label != null and !std.mem.eql(u8, call.args[0].label.?, "path"))) {
        env.lastError = TypeError.custom(
            diagnostics.embed_arguments ++ ": `@embed` takes one argument, the path",
            "Write `@embed(\"assets/logo.png\")` — the path of a file of the package, relative to its `botopink.json`.",
        ).withLoc(loc);
        return error.TypeError;
    }
    const arg = call.args[0].value;
    const argLoc = arg.getLoc();
    // A `comptime` parameter's value: the path is each caller's, read where
    // the call is written (`noteEmbedCall`); the body reads the `Asset` the
    // call passes (`embed.zig` § a path through a `comptime` parameter).
    if (embedMod.paramOfArg(arg.*, env.currentParams)) |param| {
        if (isDecoratorParams(env.currentParams) or env.inTemplateFn) {
            env.lastError = TypeError.custom(
                diagnostics.comptime_arg_not_known ++ ": `@embed` reads a `comptime` parameter of a body that runs at build",
                "A decorator's or a template's body runs at build on the comptime runtime, which reads no file yet: pass the `Asset` itself, `@embed(\"…\")` written where the path is known.",
            ).withLoc(argLoc);
            return error.TypeError;
        }
        const names = env.embedParamFns.get(env.currentFnName) orelse &.{};
        const known = for (names) |n| {
            if (std.mem.eql(u8, n, param)) break true;
        } else false;
        if (!known) {
            const grown = try env.arena.alloc([]const u8, names.len + 1);
            @memcpy(grown[0..names.len], names);
            grown[names.len] = param;
            try env.embedParamFns.put(env.arena, env.currentFnName, grown);
        }
        env.usesAsset = true;
        const read = try env.arena.create(ast.Expr);
        read.* = .{ .identifier = .{ .loc = loc, .kind = .{ .ident = try embedMod.hiddenName(env.arena, param) } } };
        try env.srcRewrites.put(loc, read);
        return TypedExpr{ .call = .{ .loc = loc, .type_ = try env.namedType("Asset"), .kind = .{ .call = .{
            .receiver = null,
            .callee = "embed",
            .is_builtin = true,
            .args = &.{},
            .trailing = &.{},
        } } } };
    }
    const path = try embedPathValue(env, arg) orelse {
        env.lastError = TypeError.custom(
            diagnostics.comptime_arg_not_known ++ ": the path of `@embed` is not known at build",
            "`@embed` reads its file while the program compiles (decision 519): pass a literal, a constant `val`, a `comptime` value or a `comptime` parameter's value.",
        ).withLoc(argLoc);
        return error.TypeError;
    };
    const rewrite = try embedRead(env, path, argLoc, loc);
    try env.srcRewrites.put(loc, rewrite);
    try env.embedRewrites.put(env.arena, loc, rewrite);
    var typed = try inferExprTyped(env, rewrite.*);
    // A fresh type node per call: a `val` bound to it carries the node, and
    // `a.text()` finds the bytes by it (`Env.assetTypes`).
    const fresh = try env.arena.create(T.Type);
    fresh.* = typed.getType().deref().*;
    switch (typed) {
        inline else => |*e| e.type_ = fresh,
    }
    try env.assetTypes.put(env.arena, fresh, rewrite.call.kind.call.args[1].value.literal.kind.bytesLit);
    return typed;
}

/// Decisions 780, 782 — `comptime compiler.load(path)`: the file `path`
/// names in the package, read by `@embed`'s rules (a path known at build,
/// relative to the package's `botopink.json`, no absolute path, no `..`),
/// compiled now as the entry of a package of its own (`load.compileFile`)
/// and rewritten into the call that answers its `Result` (`load.rewrite`):
/// `Ok` when it compiles, `Error` its refusals. A path refused, a file
/// missing and a compiler with no reader are refusals of the caller, at the
/// argument; the loaded file's own refusals never are.
fn inferLoadBuiltin(env: *Env, call: anytype, loc: ast.Loc) InferError!TypedExpr {
    if (call.args.len != 1 or call.trailing.len != 0 or (call.args[0].label != null and !std.mem.eql(u8, call.args[0].label.?, "path"))) {
        env.lastError = TypeError.custom(
            diagnostics.load_arguments ++ ": `compiler.load` takes one argument, the path",
            "Write `comptime compiler.load(\"src/cases/broken.bp\")` — the path of a file of the package, relative to its `botopink.json` (decision 780).",
        ).withLoc(loc);
        return error.TypeError;
    }
    const arg = call.args[0].value;
    const argLoc = arg.getLoc();
    const path = try embedPathValue(env, arg) orelse {
        env.lastError = TypeError.custom(
            diagnostics.comptime_arg_not_known ++ ": the path of `compiler.load` is not known at build",
            "`compiler.load` compiles its file while the program compiles (decision 780): pass a literal, a constant `val` or a `comptime` value.",
        ).withLoc(argLoc);
        return error.TypeError;
    };
    const ds = try answerLoad(env, path, argLoc);
    const rewrite = try loadMod.rewrite(env.arena, loc, .{ .path = path }, ds);
    try env.srcRewrites.put(loc, rewrite);
    return inferExprTyped(env, rewrite.*);
}

/// The refusals of the file `path` names, compiled at build
/// (`load.compileFile`), empty when it compiles; a path refused, a file
/// missing, a compiler with no reader and a cycle are refusals of the
/// caller, at `argLoc`.
fn answerLoad(env: *Env, path: []const u8, argLoc: ast.Loc) InferError![]const loadMod.Diagnostic {
    if (embedMod.checkPath(path)) |refusal| {
        env.lastError = switch (refusal) {
            .absolute => TypeError.custom(
                try std.fmt.allocPrint(env.arena, "{s}: `compiler.load(\"{s}\")` names an absolute path", .{ diagnostics.load_path_absolute, path }),
                "A path of `compiler.load` is relative to the `botopink.json` of the package that writes it (decision 780).",
            ),
            .outside_package => TypeError.custom(
                try std.fmt.allocPrint(env.arena, "{s}: `compiler.load(\"{s}\")` leaves the package", .{ diagnostics.load_path_outside_package, path }),
                "A path of `compiler.load` names a file of the package that writes it: no `..` segment (decision 780).",
            ),
        }.withLoc(argLoc);
        return error.TypeError;
    }
    const files = env.packageFiles orelse {
        env.lastError = TypeError.custom(
            try std.fmt.allocPrint(env.arena, "{s}: `compiler.load(\"{s}\")` cannot be read — this compiler reads no file", .{ diagnostics.load_no_reader, path }),
            "The compiler that runs in a browser is handed no reader (decision 780): build the program with the `botopink` CLI.",
        ).withLoc(argLoc);
        return error.TypeError;
    };
    const answer = loadMod.compileFile(env.arena, .{
        .path = path,
        .files = files,
        .io = if (env.templateEval) |ctx| ctx.io else files.io,
        .build_root = if (env.templateEval) |ctx| ctx.build_root else null,
    }) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        else => {
            env.lastError = TypeError.custom(
                try std.fmt.allocPrint(env.arena, "{s}: `compiler.load(\"{s}\")` could not compile the file ({s})", .{ diagnostics.load_file_missing, path, @errorName(err) }),
                "The file is compiled as the entry of a package of its own (decision 780).",
            ).withLoc(argLoc);
            return error.TypeError;
        },
    };
    const ds = switch (answer) {
        .diagnostics => |ds| ds,
        .missing => {
            env.lastError = TypeError.custom(
                try std.fmt.allocPrint(env.arena, "{s}: `compiler.load(\"{s}\")` names no file of the package", .{ diagnostics.load_file_missing, path }),
                "The path is relative to the `botopink.json` of the package that writes it (decision 780).",
            ).withLoc(argLoc);
            return error.TypeError;
        },
        .cycle => {
            env.lastError = TypeError.custom(
                try std.fmt.allocPrint(env.arena, "{s}: `compiler.load(\"{s}\")` loads a file that is being loaded", .{ diagnostics.load_cycle, path }),
                "A loaded file is compiled at build as a package of its own; one that loads itself, through any chain of loads, would never end (decision 780 (5)).",
            ).withLoc(argLoc);
            return error.TypeError;
        },
        .std_initialising => {
            env.lastError = TypeError.custom(
                try std.fmt.allocPrint(env.arena, "{s}: `compiler.load(\"{s}\")` is read while std's own declarations are first registered", .{ diagnostics.load_cycle, path }),
                "A nested compile needs std ready; it never re-enters std's one-time initialisation (decision 780 (5)).",
            ).withLoc(argLoc);
            return error.TypeError;
        },
    };
    return ds;
}

/// Decisions 787, 792 — `fd`, a body that runs at build (a top-level
/// `comptime { … }`, a decorator), with each `compiler.load` read it writes
/// answered now: the comptime runtime builds the answer
/// (`load.runtimeAnswer`) — a `Module` an executor captures, which
/// `executorSource` writes back as the record's constructor. A read whose
/// path is not known is left to the runtime, which refuses it.
fn withBuildLoads(env: *Env, fd: ast.FnDecl) InferError!ast.FnDecl {
    if (!(try loadMod.fnReads(env.arena, fd))) return fd;
    const Ctx = struct {
        env: *Env,
        pub fn answer(self: @This(), e: ast.Expr) anyerror!?ast.Expr {
            const call = e.call.kind.call;
            if (call.args.len != 1) return null;
            const arg = call.args[0].value;
            const path = (try loadMod.foldedPath(self.env.arena, arg)) orelse return null;
            const ds = try answerLoad(self.env, path, arg.getLoc());
            return try loadMod.runtimeAnswer(self.env.arena, e.call.loc, .{ .path = path }, ds);
        }
    };
    return loadMod.replaceReads(env.arena, ast.FnDecl, fd, Ctx{ .env = env }) catch |err| switch (err) {
        error.OutOfMemory => error.OutOfMemory,
        error.TypeError => error.TypeError,
        else => error.OutOfMemory,
    };
}

/// Decision 519 — the `Asset(…)` constructor of the file `path` of this
/// module's package, read now, located at `loc`: an absolute path or one with
/// a `..` segment is refused at `argLoc`, a compiler with no reader and a
/// missing file at `loc`.
fn embedRead(env: *Env, path: []const u8, argLoc: ast.Loc, loc: ast.Loc) InferError!*ast.Expr {
    if (embedMod.checkPath(path)) |refusal| {
        env.lastError = switch (refusal) {
            .absolute => TypeError.custom(
                try std.fmt.allocPrint(env.arena, "{s}: `@embed(\"{s}\")` names an absolute path", .{ diagnostics.embed_path_absolute, path }),
                "A path of `@embed` is relative to the `botopink.json` of the package that writes it (decision 519).",
            ),
            .outside_package => TypeError.custom(
                try std.fmt.allocPrint(env.arena, "{s}: `@embed(\"{s}\")` leaves the package", .{ diagnostics.embed_path_outside_package, path }),
                "A path of `@embed` names a file of the package that writes it: no `..` segment (decision 519).",
            ),
        }.withLoc(argLoc);
        return error.TypeError;
    }
    const files = env.packageFiles orelse {
        env.lastError = TypeError.custom(
            try std.fmt.allocPrint(env.arena, "{s}: `@embed(\"{s}\")` cannot be read — this compiler reads no file", .{ diagnostics.embed_no_reader, path }),
            "The compiler that runs in a browser is handed no reader (decision 519): build the program with the `botopink` CLI.",
        ).withLoc(loc);
        return error.TypeError;
    };
    const bytes = files.readFile(env.arena, path) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        error.FileNotFound, error.Unreadable => {
            env.lastError = TypeError.custom(
                try std.fmt.allocPrint(env.arena, "{s}: `@embed(\"{s}\")` names no file of the package", .{ diagnostics.embed_file_missing, path }),
                "The path is relative to the `botopink.json` of the package that writes it (decision 519).",
            ).withLoc(loc);
            return error.TypeError;
        },
    };
    env.usesAsset = true;
    return embedMod.asset(env.arena, loc, try blockEval.stringLexeme(env.arena, path), bytes);
}

/// Decision 519 — a call of a function whose `@embed` reads a `comptime`
/// parameter's value (`embed.embedParams`, this module's or an imported
/// one's): the path the call passes is read here, in the caller's package,
/// and the `Asset` is the call's argument for `__embed_<p>`
/// (`Env.embedCallArgs`, appended by the transform).
fn noteEmbedCall(env: *Env, call: anytype, declParams: ?[]const ast.Param, argParamIndex: ?[]const usize, loc: ast.Loc) InferError!void {
    const callee: ast.FnDecl = if (env.fnDecls.get(call.callee)) |f| f else if (env.importedFnSupport.get(call.callee)) |closure|
        (if (closure.len > 0) closure[0] else return)
    else
        return;
    const names = env.embedParamsSeen.get(call.callee) orelse names: {
        const found = try embedMod.embedParams(env.arena, callee);
        try env.embedParamsSeen.put(env.arena, call.callee, found);
        break :names found;
    };
    if (names.len == 0) return;
    const params = declParams orelse callee.params;
    const extra = try env.arena.alloc(ast.CallArg, names.len);
    for (names, extra) |name, *out| {
        const pi = for (params, 0..) |p, i| {
            if (std.mem.eql(u8, p.name, name)) break i;
        } else return;
        const ai: usize = if (argParamIndex) |slots| for (slots, 0..) |s, i| {
            if (s == pi) break i;
        } else return else pi;
        if (ai >= call.args.len) return;
        const arg = call.args[ai].value;
        const argLoc = arg.getLoc();
        const path = try embedPathValue(env, arg) orelse {
            env.lastError = TypeError.custom(
                try std.fmt.allocPrint(env.arena, "{s}: the path `{s}` passes to `@embed` is not known at build", .{ diagnostics.comptime_arg_not_known, name }),
                "`@embed` reads its file while the program compiles (decision 519): pass a literal, a constant `val` or a `comptime` value.",
            ).withLoc(argLoc);
            return error.TypeError;
        };
        out.* = .{ .label = null, .value = try embedRead(env, path, argLoc, argLoc) };
    }
    try env.embedCallArgs.put(env.arena, loc, extra);
}

/// Decision 519 — the value of `@embed`'s argument at build, or null when it
/// is not known there. A string literal is read as written; anything else
/// known at build (`blockEval.knownAtBuild`) is evaluated as a hole's value is.
fn embedPathValue(env: *Env, arg: *const ast.Expr) InferError!?[]const u8 {
    if (arg.* == .literal and arg.literal.kind == .stringLit) {
        return try templateEval.lexemeBytes(env.arena, arg.literal.kind.stringLit);
    }
    if (!blockEval.knownAtBuild(env, arg, 0)) return null;
    const io = if (env.templateEval) |ctx| ctx.io else if (env.packageFiles) |f| f.io else return null;
    return switch (try blockEval.holeValue(env, io, arg)) {
        .build => |t| switch (t) {
            .binary => |b| b,
            else => null,
        },
        else => null,
    };
}

/// Decision 519 — `a.text()` on an `Asset`: computed at build, rewritten into
/// the string literal of the bytes (`srcRewrites`, under the call's loc);
/// bytes that are not UTF-8 are refused at the call. The bytes are those of
/// the `@embed` whose type node the receiver carries (`Env.assetTypes`): an
/// `@embed` call, a `val` bound to one. Any other `Asset` (a parameter, a
/// function's answer) is not known where the call is checked, and refused.
fn inferAssetText(env: *Env, call: anytype, rp: *ast.TypedExpr, loc: ast.Loc) InferError!TypedExpr {
    if (call.args.len != 0 or call.trailing.len != 0) {
        env.lastError = TypeError.custom(
            diagnostics.embed_arguments ++ ": `text()` takes no argument",
            "Write `a.text()` — the bytes of the `Asset` as UTF-8 text.",
        ).withLoc(loc);
        return error.TypeError;
    }
    const bytes = env.assetTypes.get(rp.getType().deref()) orelse {
        env.lastError = TypeError.custom(
            diagnostics.embed_text_not_at_build ++ ": `text()` reads an `Asset` whose bytes are not known here",
            "`text()` is computed at build (decision 519): call it on an `@embed(…)`, or on a `val` bound to one.",
        ).withLoc(loc);
        return error.TypeError;
    };
    if (!std.unicode.utf8ValidateSlice(bytes)) {
        env.lastError = TypeError.custom(
            diagnostics.embed_text_not_utf8 ++ ": `text()` reads bytes that are not UTF-8",
            "The file is not UTF-8 text (decision 519): read its bytes with `.bytes`.",
        ).withLoc(loc);
        return error.TypeError;
    }
    const lit = try env.arena.create(ast.Expr);
    lit.* = .{ .literal = .{ .loc = loc, .kind = .{ .stringLit = try blockEval.stringLexeme(env.arena, bytes) } } };
    try env.srcRewrites.put(loc, lit);
    return TypedExpr{ .literal = .{ .loc = loc, .type_ = try env.namedType("string"), .kind = .{ .stringLit = lit.literal.kind.stringLit } } };
}

/// Decision 538 — `a.open()` on an `Asset`: the `File` of std's `io.fs` over
/// the embedded bytes, with no `@Result` (the build proved the file exists).
/// `File` is a std type, and an `Asset` is the compiler's: the call is
/// rewritten, like `@embed`, into `<fs>.openAsset(a)` where `<fs>` is the name
/// this module gave std's `io.fs` (`import {io.fs} from "std"`), so the module
/// that opens an `Asset` is one that imports the file system.
fn inferAssetOpen(env: *Env, call: anytype, loc: ast.Loc) InferError!TypedExpr {
    if (call.args.len != 0 or call.trailing.len != 0) {
        env.lastError = TypeError.custom(
            diagnostics.embed_arguments ++ ": `open()` takes no argument",
            "Write `a.open()` — the `File` over the bytes of the `Asset`.",
        ).withLoc(loc);
        return error.TypeError;
    }
    var fs_name: ?[]const u8 = null;
    var it = env.stdImports.iterator();
    while (it.next()) |e| {
        if (std.mem.eql(u8, e.value_ptr.*, "io/fs")) {
            // The shortest name when several bind the module: the same one on every run.
            if (fs_name == null or e.key_ptr.*.len < fs_name.?.len or (e.key_ptr.*.len == fs_name.?.len and std.mem.lessThan(u8, e.key_ptr.*, fs_name.?))) fs_name = e.key_ptr.*;
        }
    }
    const fs = fs_name orelse {
        env.lastError = TypeError.custom(
            diagnostics.embed_open_needs_fs ++ ": `open()` hands the `Asset` to std's file system, which this module does not import",
            "Add `import {io.fs} from \"std\";` — the `File` an `Asset` opens as is std's.",
        ).withLoc(loc);
        return error.TypeError;
    };
    const receiver = try env.arena.create(ast.Expr);
    receiver.* = .{ .identifier = .{ .loc = loc, .kind = .{ .ident = fs } } };
    const args = try env.arena.alloc(ast.CallArgOf(.untyped), 1);
    args[0] = .{ .label = null, .value = call.receiver.? };
    const rewrite = try env.arena.create(ast.Expr);
    rewrite.* = .{ .call = .{ .loc = loc, .kind = .{ .call = .{
        .receiver = receiver,
        .callee = "openAsset",
        .is_builtin = false,
        .args = args,
        .trailing = &.{},
    } } } };
    try env.srcRewrites.put(loc, rewrite);
    return inferExprTyped(env, rewrite.*);
}

/// Whether `ty` is std's `compiler.Module` (decision 786): the record
/// `compiler.load` answers, `name`, `path` and `target`.
fn isLoadModuleType(env: *Env, ty: *T.Type) bool {
    const d = ty.deref();
    if (d.* != .named or !std.mem.eql(u8, d.named.name, "Module")) return false;
    const td = env.lookupTypeDef("Module") orelse return true;
    _ = td;
    return true;
}

/// Decision 792 (4) — the `run()` calls an executor writes, refused where
/// they are written before the captured `Module` is spliced: on the `module`
/// of a `Refused`, `run-module-refused`; on a file with no `main`,
/// `load-no-main`.
fn refuseExecutorRuns(env: *Env, func: ast.FunctionExpr, captured: []const []const u8, handed: []const std.json.Value) InferError!void {
    for (try loadMod.runCalls(env.arena, func)) |rc| {
        var r = rc.receiver;
        while (r.* == .collection and r.collection.kind == .grouped) r = r.collection.kind.grouped;
        const local: []const u8, const member: ?[]const u8 = switch (r.*) {
            .identifier => |id| switch (id.kind) {
                .ident => |n| .{ n, null },
                .identAccess => |acc| if (acc.receiver.* == .identifier and acc.receiver.identifier.kind == .ident) .{ acc.receiver.identifier.kind.ident, acc.member } else continue,
                else => continue,
            },
            else => continue,
        };
        const k = for (captured, 0..) |n, i| {
            if (std.mem.eql(u8, n, local)) break i;
        } else continue;
        if (k >= handed.len) continue;
        const path = loadMod.valuePath(handed[k], member) orelse continue;
        const entry = loadMod.entryOf(path) orelse continue;
        if (entry.diagnostics.len > 0) return refuseRun(env, .refused, path, rc.loc);
        if (!entry.has_main) return refuseRun(env, .no_main, path, rc.loc);
    }
}

fn refuseRun(env: *Env, why: enum { refused, no_main }, path: []const u8, loc: ast.Loc) InferError {
    env.lastError = switch (why) {
        .refused => TypeError.custom(
            try std.fmt.allocPrint(env.arena, "{s}: `run()` is called on the `Module` of `{s}`, whose load refused", .{ diagnostics.run_module_refused, path }),
            "A `Refused`'s `module` names a file that did not compile: there is no `main` to run (decision 792 (4)). Run the `Module` on the `Ok` side.",
        ),
        .no_main => TypeError.custom(
            try std.fmt.allocPrint(env.arena, "{s}: `run()` is called on `{s}`, which declares no `main`", .{ diagnostics.load_no_main, path }),
            "`run()` runs the loaded file's `main` (decision 787 (3)): declare `pub fn main()` in it.",
        ),
    }.withLoc(loc);
    return error.TypeError;
}

/// Decisions 787, 792 — `m.run()`: written directly in a `compiler.init`
/// body (an executor, `__bp_executor_<k>`), else `run-outside-init`; on the
/// `Module` of a load that refused, `run-module-refused`; on a file with no
/// `main`, `load-no-main` — each at the call. The loaded package joins the
/// program (`load.noteRun`, `comptime.compileWith`), and the call is
/// rewritten to `load.run_fn` over its `main` (`load.runRewrite`), so it
/// answers `Result<void, RunFailure>` (decision 806).
fn inferModuleRun(env: *Env, call: anytype, loc: ast.Loc) InferError!?TypedExpr {
    if (call.args.len != 0 or call.trailing.len != 0) {
        env.lastError = TypeError.custom(
            "`run()` takes no argument",
            "Write `m.run()` — it runs the loaded file's `main` (decision 787).",
        ).withLoc(loc);
        return error.TypeError;
    }
    if (!std.mem.startsWith(u8, env.currentFnName, "__bp_executor_") and env.initArgDepth == 0) {
        env.lastError = TypeError.custom(
            diagnostics.run_outside_init ++ ": `run()` is called outside a `compiler.init` body",
            "A loaded file's `main` runs when the program runs, at the point of an init body that calls `run()` (decisions 787, 792 (7)): write `compiler.init({ -> try m.run() catch { f -> … }; })` in the body that runs at build, never in a function it calls.",
        ).withLoc(loc);
        return error.TypeError;
    }
    const path = (try loadMod.receiverPath(env.arena, call.receiver.?)) orelse {
        // The body that runs at build, checked before its executor is: the
        // `Module` is a local of the body there, its file known once the
        // executor holds it (`load.recordSource`).
        if (env.initArgDepth > 0) return try declaredModuleRun(env, try inferExprTyped(env, (try loadMod.runRewrite(env.arena, loc, null)).*), loc);
        env.lastError = TypeError.custom(
            diagnostics.run_module_untraced ++ ": `run()` is called on a `Module` that no `compiler.load` of the body answered",
            "Call `run()` on the `Module` the body's `compiler.load` answered, captured by the init body or a `val` bound to it (decisions 787, 792 (4)).",
        ).withLoc(loc);
        return error.TypeError;
    };
    const entry = loadMod.entryOf(path) orelse {
        env.lastError = TypeError.custom(
            try std.fmt.allocPrint(env.arena, "{s}: `run()` is called on `{s}`, which no `compiler.load` of this build loaded", .{ diagnostics.run_module_untraced, path }),
            "Call `run()` on the `Module` the body's `compiler.load` answered (decision 787).",
        ).withLoc(loc);
        return error.TypeError;
    };
    if (entry.diagnostics.len > 0) return refuseRun(env, .refused, path, loc);
    if (!entry.has_main) return refuseRun(env, .no_main, path, loc);
    try loadMod.noteRun(path);
    const alias = try loadMod.runAlias(env.arena, try loadMod.packageName(env.arena, path));
    const present = env.lookup(alias) != null;
    const rewrite = try loadMod.runRewrite(env.arena, loc, if (present) alias else null);
    try env.srcRewrites.put(loc, rewrite);
    return try declaredModuleRun(env, try inferExprTyped(env, rewrite.*), loc);
}

/// The lowered `m.run()` answers what `compiler.bp` declares `Module.run` to
/// answer, `Result<void, RunFailure>` (decision 806).
fn declaredModuleRun(env: *Env, typed: TypedExpr, loc: ast.Loc) InferError!TypedExpr {
    const sig = env.getInherentMethodType("Module", "run") orelse return typed;
    const f = sig.deref();
    if (f.* == .func) try unifyAt(env, f.func.ret, typed.getType(), loc);
    return typed;
}

/// Whether `ty` is the builtin `Asset` (decision 519).
fn isAssetType(ty: *T.Type) bool {
    const d = ty.deref();
    return d.* == .named and std.mem.eql(u8, d.named.name, "Asset");
}

/// Evaluate `@makeRecord(fields)` at inference time when `fields` is a literal
/// array of RecordField values. Extracts field names and type names from the
/// untyped AST, looks up the types, and creates a synthetic record type.
///
/// Returns a TypedExpr on success, null when the argument cannot be statically
/// evaluated (delegates to the general builtin path which returns a fresh var).
fn tryEvalMakeRecord(env: *Env, arg: ast.Expr, loc: ast.Loc) InferError!?TypedExpr {
    switch (arg) {
        .collection => |col| switch (col.kind) {
            .arrayLit => |al| {
                if (al.elems.len == 0) {
                    // Empty record.
                    return try makeSyntheticRecordType(env, &.{});
                }
                var fields: std.ArrayListUnmanaged(envMod.FieldDef) = .empty;
                for (al.elems) |*elem| {
                    // Each element should be a call: RecordField(name: "x", typeName: "i32")
                    switch (elem.*) {
                        .call => |ec| switch (ec.kind) {
                            .call => |ecc| {
                                var fieldName: ?[]const u8 = null;
                                var typeName: ?[]const u8 = null;
                                for (ecc.args) |farg| {
                                    if (farg.label) |label| {
                                        if (std.mem.eql(u8, label, "name")) {
                                            switch (farg.value.*) {
                                                .literal => |lit| switch (lit.kind) {
                                                    .stringLit => |s| fieldName = s,
                                                    else => {},
                                                },
                                                else => {},
                                            }
                                        } else if (std.mem.eql(u8, label, "typeName")) {
                                            switch (farg.value.*) {
                                                .literal => |lit| switch (lit.kind) {
                                                    .stringLit => |s| typeName = s,
                                                    else => {},
                                                },
                                                else => {},
                                            }
                                        }
                                    }
                                }
                                const name = fieldName orelse {
                                    env.lastError = TypeError.custom(
                                        "@makeRecord: RecordField missing 'name'",
                                        "Each RecordField must have a 'name' label.",
                                    ).withLoc(loc);
                                    return error.TypeError;
                                };
                                const tname = typeName orelse {
                                    env.lastError = TypeError.custom(
                                        "@makeRecord: RecordField missing 'typeName'",
                                        "Each RecordField must have a 'typeName' label.",
                                    ).withLoc(loc);
                                    return error.TypeError;
                                };
                                // Resolve the type name to a Type.
                                const ty = try env.namedType(tname);
                                try fields.append(env.arena, .{ .name = name, .type_ = ty });
                            },
                            else => return null,
                        },
                        else => return null,
                    }
                }
                return try makeSyntheticRecordType(env, fields.items);
            },
            else => return null,
        },
        else => return null,
    }
}

/// Create a synthetic/anonymous record type from field definitions and return
/// a TypedExpr holding the type value.
fn makeSyntheticRecordType(env: *Env, fields: []envMod.FieldDef) !TypedExpr {
    const typeId = env.allocTypeId();
    const syntheticName = try std.fmt.allocPrint(env.arena, "#synth_{d}", .{typeId});

    // Build the record Type (anonymous structural record).
    var recordFields = try env.arena.alloc(T.Field, fields.len);
    for (fields, 0..) |f, i| {
        recordFields[i] = .{ .name = f.name, .type_ = f.type_ };
    }
    const recordTy = try env.arena.create(T.Type);
    recordTy.* = .{ .record = recordFields };

    // Register the type definition so it can be looked up by name.
    try env.registerTypeDef(syntheticName, .{ .record = .{
        .name = syntheticName,
        .id = typeId,
        .genericParams = &.{},
        .fields = fields,
    } });

    // Bind the name as a constructor.
    var paramTypes = try env.arena.alloc(*T.Type, fields.len);
    for (fields, 0..) |f, i| paramTypes[i] = f.type_;
    const ctorType = try env.funcType(paramTypes, recordTy);
    try env.bind(syntheticName, ctorType);

    return TypedExpr{ .identifier = .{
        .loc = .{ .line = 0, .col = 0 },
        .type_ = recordTy,
        .kind = .{ .ident = syntheticName },
    } };
}

fn unwrapResultType(ty: *T.Type) ?*T.Type {
    const t = ty.deref();
    return switch (t.*) {
        .named => |n| if (std.mem.eql(u8, n.name, "Result") and n.args.len >= 1)
            n.args[0]
        else
            null,
        else => null,
    };
}

/// Unwrap the Ok type of a `@Result<D, E>` operand for `try`/`catch`.
/// A still-unresolved type variable is allowed (its `Result`-ness is unknown);
/// any other concrete non-Result type is a compile-time error.
fn tryUnwrapOrError(env: *Env, rawTy: *T.Type, loc: ast.Loc) InferError!*T.Type {
    if (unwrapResultType(rawTy)) |ty| return ty;
    const d = rawTy.deref();
    if (d.* == .typeVar) return rawTy;
    env.lastError = TypeError.tryOnNonResult(d).withLoc(loc);
    return InferError.TypeError;
}

/// `@Async<T>` -> `T` (decision 120). `@Component<R>` extends `@Async`, and
/// decision 104 has every caller `await` a component: it awaits to `R`
/// (decision 354). `@AsyncIter<T>` is iterated with `for await`, never awaited
/// whole. Returns null when `ty` is no Async.
/// Decision 432 — the `task_await` / `task_return` lowerings of a checked
/// module, put into `out`: an `await` or a whole-wrapper `return` whose
/// operand is a `@Async<X>` with `X` a `@Result`, or a type left open (a type
/// parameter — a failing task may reach generic code). A `@Component`, and a
/// `@Async` of any other type, records nothing.
pub fn taskLowerings(env: *const Env, out: *std.AutoHashMap(ast.Loc, envMod.InstanceLowering)) !void {
    var ait = env.taskAwaits.iterator();
    while (ait.next()) |e| if (awaitMayFail(e.value_ptr.*)) {
        const slot = try out.getOrPut(e.key_ptr.*);
        if (!slot.found_existing) slot.value_ptr.* = .task_await;
    };
    var rit = env.taskReturns.iterator();
    while (rit.next()) |e| if (taskMayFail(e.value_ptr.*)) {
        const slot = try out.getOrPut(e.key_ptr.*);
        if (!slot.found_existing) slot.value_ptr.* = .task_return;
    };
    var bit = env.failingTaskBlocks.keyIterator();
    while (bit.next()) |k| {
        const slot = try out.getOrPut(k.*);
        if (!slot.found_existing) slot.value_ptr.* = .failing_task_block;
    }
}

/// Decision 150 — every `case` / `if` whose value is the union of its arms
/// (`env.unionValues`), written for the backends as
/// `InstanceLowering.union_value` at its loc: the union (`unknown` when a
/// member cannot be written — a type variable, a structural record) and each
/// arm's type. Read once the module is inferred, so every variable an arm
/// left open is as resolved as it will be.
pub fn unionValueLowerings(env: *const Env, arena: std.mem.Allocator, out: *std.AutoHashMap(ast.Loc, envMod.InstanceLowering)) !void {
    var it = env.unionValues.iterator();
    while (it.next()) |e| {
        const u = e.value_ptr.type_.deref();
        if (u.* != .union_) continue;
        const members = try arena.alloc(ast.TypeRef, u.union_.len);
        const named = for (u.union_, 0..) |m, i| {
            members[i] = (try typeRefOfType(arena, env, m)) orelse break false;
        } else true;
        const arms = try arena.alloc(?ast.TypeRef, e.value_ptr.arms.len);
        for (e.value_ptr.arms, 0..) |a, i| arms[i] = if (a) |t| try typeRefOfType(arena, env, t) else null;
        const ty: ast.TypeRef = if (named)
            .{ .generic = .{ .name = ast.union_type_name, .args = members, .is_builtin = false } }
        else
            .{ .named = ast.unknown_type_name };
        const slot = try out.getOrPut(e.key_ptr.*);
        if (!slot.found_existing) slot.value_ptr.* = .{ .union_value = .{ .type_ = ty, .arms = arms } };
    }
}

/// 144 B-78 (decision 521) — `ty` is written as text at `loc` (`env.textValues`).
fn noteTextValue(env: *Env, loc: ast.Loc, ty: *T.Type) !void {
    const slot = try env.textValues.getOrPut(loc);
    if (!slot.found_existing) slot.value_ptr.* = .empty;
    try slot.value_ptr.append(env.arena, ty);
}

/// Decision 530 — a template hole (a `string +` operand) holding a value whose text
/// JavaScript's coercion would not write as `@print` does is recorded under
/// `ast.text_hole_col`, and `textValueLowerings` turns it into the lowering commonJS
/// reads to write the value through the text helper.
fn noteTextHole(env: *Env, loc: ast.Loc, ty: *T.Type) !void {
    if (!textHoleNeedsHelper(ty)) return;
    var key = loc;
    key.col += ast.text_hole_col;
    try noteTextValue(env, key, ty);
}

/// Whether `ty` is written as text by the helper: a named type that is not a scalar
/// (`string`, a number, `bool`) — a record, an enum, an array, a tuple, a generic type, or
/// an optional of one. A type variable and anything the checker cannot name keep JavaScript's reading.
fn textHoleNeedsHelper(ty: *T.Type) bool {
    const d = ty.deref();
    if (d.* != .named) return false;
    // An optional is written as its payload is: `null` is JavaScript's own text for it.
    if (std.mem.eql(u8, d.named.name, "optional") and d.named.args.len == 1) return textHoleNeedsHelper(d.named.args[0]);
    const scalars = [_][]const u8{ "string", "i8", "i16", "i32", "i64", "u8", "u16", "u32", "u64", "isize", "usize", "f32", "f64", "bool", "bigint", "decimal", "void" };
    for (scalars) |s| if (std.mem.eql(u8, d.named.name, s)) return false;
    return true;
}

fn isPrintBuiltin(name: []const u8) bool {
    for ([_][]const u8{ "print", "println", "debug" }) |b| if (std.mem.eql(u8, name, b)) return true;
    return false;
}

/// Where a float sits in `ty`, as commonJS's print shapes read it: `f` a
/// float, `?` dropped (an optional prints its payload), `[`… an array, `#(`…`)`
/// a tuple, `_` anything else. Two readings of one value agree when their
/// texts are equal.
fn textShapeOf(out: *std.ArrayListUnmanaged(u8), arena: std.mem.Allocator, ty: *T.Type) !void {
    const d = ty.deref();
    // A function value's parameters (144 B-115): `(`…`)`.
    if (d.* == .func) {
        try out.append(arena, '(');
        for (d.func.params) |p| try textShapeOf(out, arena, p);
        return out.append(arena, ')');
    }
    if (d.* != .named) return out.append(arena, '_');
    const n = d.named;
    if (n.args.len == 0) return out.append(arena, if (std.mem.eql(u8, n.name, "f64") or std.mem.eql(u8, n.name, "f32")) 'f' else '_');
    if (std.mem.eql(u8, n.name, "optional") and n.args.len == 1) return textShapeOf(out, arena, n.args[0]);
    if (std.mem.eql(u8, n.name, "array") and n.args.len == 1) {
        try out.append(arena, '[');
        return textShapeOf(out, arena, n.args[0]);
    }
    if (std.mem.eql(u8, n.name, "tuple")) {
        try out.appendSlice(arena, "#(");
        for (n.args) |a| try textShapeOf(out, arena, a);
        return out.append(arena, ')');
    }
    return out.append(arena, '_');
}

/// 144 B-78 (decision 521) — every value written as text whose type holds a
/// float (or a tuple, 144 B-115), as `InstanceLowering.text_value` at its loc plus
/// `ast.text_synthetic_col`: commonJS writes that float through `__bp_f64`
/// where its own reading of the tree cannot type it (an imported record's
/// field, a generic method's answer). A loc inferred more than once records
/// only when every reading agrees — one JS body serves them all.
pub fn textValueLowerings(env: *const Env, arena: std.mem.Allocator, out: *std.AutoHashMap(ast.Loc, envMod.InstanceLowering)) !void {
    var it = env.textValues.iterator();
    while (it.next()) |e| {
        const tys = e.value_ptr.items;
        if (tys.len == 0) continue;
        // Decision 530 — a hole the text helper writes: recorded as it is keyed.
        // 144 B-114 — a generic call's argument: keyed already, and like a value
        // written as text, recorded only when its type holds a float.
        // 144 B-115 — a generic fn named as a value: keyed already, recorded
        // as an argument is.
        const is_fn_value = e.key_ptr.col >= ast.text_fn_value_col;
        const is_arg = !is_fn_value and e.key_ptr.col >= ast.text_arg_col;
        const is_hole = !is_arg and !is_fn_value and e.key_ptr.col >= ast.text_hole_col;
        var first: std.ArrayListUnmanaged(u8) = .empty;
        try textShapeOf(&first, arena, tys[0]);
        const holds_float = std.mem.indexOfScalar(u8, first.items, 'f') != null;
        const holds_tuple = std.mem.indexOfScalar(u8, first.items, '#') != null;
        // 144 B-115 — a tuple too: JavaScript holds it as an array, and
        // `@print` writes `#(1, 2)` only where its shape says so.
        if (!is_hole and !holds_float and !holds_tuple) continue;
        const agree = for (tys[1..]) |t| {
            var other: std.ArrayListUnmanaged(u8) = .empty;
            try textShapeOf(&other, arena, t);
            if (!std.mem.eql(u8, first.items, other.items)) break false;
        } else true;
        if (!agree) continue;
        const ref = (try typeRefOfType(arena, env, tys[0])) orelse continue;
        var key = e.key_ptr.*;
        if (!is_hole and !is_arg and !is_fn_value) key.col += ast.text_synthetic_col;
        const slot = try out.getOrPut(key);
        if (!slot.found_existing) slot.value_ptr.* = .{ .text_value = ref };
    }
}

/// The written form of a checker type; null for a type variable, a union or
/// a structural record — what nothing names. Shared by the scope lowering's
/// carried types (`context_lower.zig`, decision 504) and `unionValueLowerings`.
pub fn typeRefOfType(arena: std.mem.Allocator, env: *const Env, ty: *T.Type) anyerror!?ast.TypeRef {
    const d = ty.deref();
    switch (d.*) {
        .named => |n| {
            if (n.args.len == 0) {
                if (std.mem.eql(u8, n.name, "array") or std.mem.eql(u8, n.name, "tuple") or std.mem.eql(u8, n.name, "optional")) return null;
                return .{ .named = n.name };
            }
            const args = try arena.alloc(ast.TypeRef, n.args.len);
            for (n.args, 0..) |a, i| args[i] = (try typeRefOfType(arena, env, a)) orelse return null;
            if (std.mem.eql(u8, n.name, "array") and args.len == 1) {
                const inner = try arena.create(ast.TypeRef);
                inner.* = args[0];
                return .{ .array = inner };
            }
            if (std.mem.eql(u8, n.name, "optional") and args.len == 1) {
                const inner = try arena.create(ast.TypeRef);
                inner.* = args[0];
                return .{ .optional = inner };
            }
            if (std.mem.eql(u8, n.name, "tuple")) {
                if (n.labels.len > 0) return .{ .labeledTuple = .{ .elems = args, .labels = n.labels } };
                return .{ .tuple_ = args };
            }
            const builtin = env.lookupTypeDef(n.name) == null and isBuiltinWrapperName(n.name);
            return .{ .generic = .{ .name = n.name, .args = args, .is_builtin = builtin } };
        },
        .func => |f| {
            const params = try arena.alloc(ast.TypeRef, f.params.len);
            for (f.params, 0..) |p, i| params[i] = (try typeRefOfType(arena, env, p)) orelse return null;
            const ret = try arena.create(ast.TypeRef);
            ret.* = (try typeRefOfType(arena, env, f.ret)) orelse return null;
            return .{ .function = .{ .params = params, .returnType = ret } };
        },
        else => return null,
    }
}

/// The builtin wrappers a checker type names without `@` (`Result`, `Async`,
/// …): written back as builtin generics.
fn isBuiltinWrapperName(name: []const u8) bool {
    for ([_][]const u8{ "Result", "Async", "Component", "AsyncIter", "Future", "Option" }) |w| if (std.mem.eql(u8, name, w)) return true;
    return false;
}

/// True for an `await` whose operand may be a failing task: `taskMayFail`, or
/// any operand that is not a `@Async` of a settled type nor a `@Component` — a
/// call through a record's function field is typed by the value it settles
/// with (`@Result<…>`) or `unknown`, and the reading leaves a value that is no
/// failing task as it is.
fn awaitMayFail(ty: *T.Type) bool {
    const t = ty.deref();
    if (t.* == .named and (std.mem.eql(u8, t.named.name, "Async") or std.mem.eql(u8, t.named.name, "Component"))) return taskMayFail(ty);
    return true;
}

/// True for a task that may be a failing one: a `@Async<X>` whose `X` is a
/// `@Result`, `unknown` or not resolved to a named type (a type parameter, an
/// open variable), and an operand the checker typed `unknown` or left open (a
/// call through a record's function field answers `unknown`). The reading
/// (`__bp_await`) leaves every other task as it is, so an open type costs a
/// call, never a wrong answer.
fn taskMayFail(ty: *T.Type) bool {
    const t = ty.deref();
    switch (t.*) {
        .typeVar => return true,
        .named => |n| {
            if (std.mem.eql(u8, n.name, "unknown")) return true;
            if (!std.mem.eql(u8, n.name, "Async") or n.args.len < 1) return false;
        },
        else => return false,
    }
    const x = t.named.args[0].deref();
    return switch (x.*) {
        .named => |n| std.mem.eql(u8, n.name, "Result") or std.mem.eql(u8, n.name, "unknown"),
        .typeVar => true,
        else => false,
    };
}

fn unwrapTaskType(ty: *T.Type) ?*T.Type {
    const t = ty.deref();
    return switch (t.*) {
        .named => |n| if (std.mem.eql(u8, n.name, "Async") and n.args.len >= 1)
            n.args[0]
        else if (std.mem.eql(u8, n.name, "Component") and n.args.len >= 1)
            n.args[0]
        else
            null,
        else => null,
    };
}

/// Shallow structural equality check ---- used by case-arm deduplication.
/// Does NOT unify type variables; treats any typeVar as distinct from a named type.
fn typesSameShape(a: *T.Type, b: *T.Type) bool {
    const ta = a.deref();
    const tb = b.deref();
    if (ta == tb) return true;
    return switch (ta.*) {
        .named => |na| switch (tb.*) {
            .named => |nb| std.mem.eql(u8, na.name, nb.name),
            else => false,
        },
        .union_ => |ua| switch (tb.*) {
            .union_ => |ub| ua.len == ub.len,
            else => false,
        },
        .typeVar => switch (tb.*) {
            .typeVar => |cellB| ta.typeVar == cellB,
            else => false,
        },
        else => false,
    };
}

/// Number of leading required generic arguments for a known builtin wrapper.
/// Returns null for builtins without a fixed arity (e.g. `@Decl`, `array`,
/// `optional`, `tuple`) so the resolver leaves their arg-count checks alone.
///   - `@Async<T>` / `@Iter<T>` / `@AsyncIter<T>`  → 1 (decisions 120, 122)
///   - `@Result<R, E>`                             → 2
///   - `@Component<R>`                             → 1 (decision 354: the base
///     parameter is gone; the parser refuses `@Component<R>` at `C`)
///   - `@Renderable`                               → 0 (the bare marker)
///   - `@Expr<T>` / `@ExprCustom<T>`               → 1
fn builtinRequiredGenericArgs(name: []const u8) ?usize {
    const eq = std.mem.eql;
    if (eq(u8, name, "Async")) return 1;
    if (eq(u8, name, "Iter")) return 1;
    if (eq(u8, name, "AsyncIter")) return 1;
    if (eq(u8, name, "Result")) return 2;
    if (eq(u8, name, "Component")) return 1;
    if (eq(u8, name, "Renderable")) return 0;
    if (eq(u8, name, ast.expr_type_name)) return 1;
    if (eq(u8, name, ast.expr_custom_type_name)) return 1;
    return null;
}

/// The FULL declared arity of a known builtin wrapper — required plus
/// defaulted parameters — or null for builtins without a fixed arity. RG5: an
/// argument past it is refused (decision 67 — a type argument nothing reads
/// is not dropped silently). No effect wrapper declares a default any more.
fn builtinMaxGenericArgs(name: []const u8) ?usize {
    return builtinRequiredGenericArgs(name);
}

/// Full default-position list for the known builtin wrappers, when the
/// caller supplied `given` leading args. Decisions 120 / 122 removed the last
/// defaulted wrappers (`@Future<T, E = any>` and the generators), so none
/// declares a default and the answer is always null; the hook stays for a
/// wrapper that grows one.
fn builtinDefaultFilledArgs(env: *Env, name: []const u8, given: usize) ?[]const []const u8 {
    _ = env;
    _ = name;
    _ = given;
    return null;
}

/// 06 N30 — resolve a param's annotation with its source location in scope, so
/// an unknown type name reds at the annotation instead of at the file.
fn resolveParamType(env: *Env, p: ast.Param, genericMap: std.StringHashMap(*T.Type)) InferError!*T.Type {
    const prev = env.atTypeRef(p.typeLoc);
    defer env.typeRefLoc = prev;
    return resolveTypeRefInContext(env, p.typeRef, genericMap);
}

/// 06 N30 — the same for a record/variant field's annotation.
fn resolveFieldType(env: *Env, f: ast.Field, genericMap: std.StringHashMap(*T.Type)) InferError!*T.Type {
    const prev = env.atTypeRef(f.typeLoc);
    defer env.typeRefLoc = prev;
    return resolveTypeRefInContext(env, f.typeRef, genericMap);
}

/// 06 N30 — the same for a declared return type (`-> Foo`). Only the sites that
/// register a declaration pass the location: a signature re-resolved at a call
/// site would carry the *declaring* file's coordinates into the caller's
/// diagnostic, and the declaring module already reds on its own annotation.
fn resolveReturnType(
    env: *Env,
    ref: ast.TypeRef,
    loc: ast.Loc,
    genericMap: std.StringHashMap(*T.Type),
) InferError!*T.Type {
    const prev = env.atTypeRef(loc);
    defer env.typeRefLoc = prev;
    return resolveTypeRefInContext(env, ref, genericMap);
}

/// Decision 8 §1.2 — `Self` follows §1.1: inside a `type` or `behavior` with
/// type parameters it is written `Self<…>` (bare `Self` is refused), and in a
/// declaration without them it is written `Self` (`Self<…>` is refused). A
/// syntactic walk over each method's parameter and return annotations, at the
/// declaration, because `Self` resolves to the RECEIVER wherever a behavior's
/// signature is instantiated — too late to say which declaration was wrong.
fn checkSelfSpelling(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| switch (decl) {
        .type_ => |t| try checkSelfInMethods(env, t.name, t.genericParams.len, t.methods),
        .behavior => |b| try checkSelfInMethods(env, b.name, b.genericParams.len, b.methods),
        else => {},
    };
}

fn checkSelfInMethods(env: *Env, owner: []const u8, arity: usize, methods: []const ast.BehaviorMethod) InferError!void {
    for (methods) |m| {
        for (m.params) |p| try checkSelfRef(env, owner, arity, p.typeRef, p.typeLoc);
        if (m.returnType) |rt| try checkSelfRef(env, owner, arity, rt, m.returnTypeLoc);
    }
}

fn checkSelfRef(env: *Env, owner: []const u8, arity: usize, ref: ast.TypeRef, loc: ast.Loc) InferError!void {
    switch (ref) {
        .named => |n| if (arity > 0 and std.mem.eql(u8, n, "Self")) {
            const msg = try std.fmt.allocPrint(env.arena, "Self needs {d} type argument{s}: `{s}` declares {d}", .{ arity, if (arity == 1) "" else "s", owner, arity });
            var params: std.ArrayListUnmanaged(u8) = .empty;
            for (0..arity) |i| try params.appendSlice(env.arena, if (i == 0) "…" else ", …");
            const hint = try std.fmt.allocPrint(env.arena, "Inside a declaration with type parameters, `Self` carries them: write `Self<{s}>` (decision 8 §1.2).", .{params.items});
            env.lastError = TypeError.custom(msg, hint).withLoc(loc);
            return error.TypeError;
        },
        .generic => |g| {
            if (arity == 0 and std.mem.eql(u8, g.name, "Self")) {
                const msg = try std.fmt.allocPrint(env.arena, "`{s}` declares no type parameter, so `Self` takes no type argument", .{owner});
                env.lastError = TypeError.custom(msg, "Write `Self` (decision 8 §1.2).").withLoc(loc);
                return error.TypeError;
            }
            for (g.args) |a| try checkSelfRef(env, owner, arity, a, loc);
        },
        .array => |e| try checkSelfRef(env, owner, arity, e.*, loc),
        .optional => |e| try checkSelfRef(env, owner, arity, e.*, loc),
        .tuple_ => |es| for (es) |e| try checkSelfRef(env, owner, arity, e, loc),
        .labeledTuple => |lt| for (lt.elems) |e| try checkSelfRef(env, owner, arity, e, loc),
        .function => |f| {
            for (f.params) |e| try checkSelfRef(env, owner, arity, e, loc);
            try checkSelfRef(env, owner, arity, f.returnType.*, loc);
        },
        else => {},
    }
}

/// The type parameters of `td` a written use must supply: the leading ones
/// with no declared default.
fn requiredGenericArgs(td: envMod.TypeDef) usize {
    const params = td.genericParams().len;
    const dflts = td.genericDefaults();
    if (dflts.len == 0) return params;
    var n: usize = 0;
    for (dflts) |d| {
        if (d != null) break;
        n += 1;
    }
    return n;
}

/// Decision 8 §1.1 / §1.2 — a written generic type (or `Self` of a generic
/// declaration) without all of its type arguments. Located at the annotation.
fn refuseGenericArity(env: *Env, name: []const u8, required: usize, declared: usize, given: usize) InferError {
    const msg = if (given == 0)
        try std.fmt.allocPrint(env.arena, "{s} needs {d} type argument{s}", .{ name, required, if (required == 1) "" else "s" })
    else
        try std.fmt.allocPrint(env.arena, "{s} needs {d} type argument{s}, {d} given", .{ name, required, if (required == 1) "" else "s", given });
    const hint = if (std.mem.eql(u8, name, "Self"))
        try std.fmt.allocPrint(env.arena, "Inside a declaration with type parameters `Self` carries them: write `Self<…>` with {d} argument{s} (decision 8 §1.2).", .{ declared, if (declared == 1) "" else "s" })
    else
        try std.fmt.allocPrint(env.arena, "A written type carries all of its type arguments (decision 8 §1.1): write `{s}<…>` with {d}.", .{ name, required });
    var err = TypeError.custom(msg, hint);
    if (env.typeRefLoc) |l| err = err.withLoc(l);
    env.lastError = err;
    return error.TypeError;
}

/// Resolve an `ast.TypeRef` to a `*T.Type` using a generic-parameter map.
/// Used when the type ref appears inside a generic context (record/enum registration).
fn resolveTypeRefInContext(env: *Env, ref: ast.TypeRef, genericMap: std.StringHashMap(*T.Type)) InferError!*T.Type {
    switch (ref) {
        .named => |n| {
            // The builtin record is declared in a prelude the backends never
            // see; a module that names it gets its declaration spliced in
            // (`comptime.zig`, `withSourceLocationDecl`).
            if (std.mem.eql(u8, n, source_location_type_name)) env.usesSourceLocation = true;
            if (std.mem.eql(u8, n, yield_step_type_name)) env.usesYieldStep = true;
            // Decision 578 (4) — `anyvalue` is a template's return (read as
            // its built code's type) and nothing else — but in std's
            // `compiler.bp`, where `Compiler.build` declares it as its answer.
            if (std.mem.eql(u8, n, ast.anyvalue_type_name) and !std.mem.eql(u8, env.modulePath, "std/compiler")) {
                var err = TypeError.custom(diagnostics.anyvalue_outside_template ++ ": `anyvalue` — a value whose type is known once its code is built — is written only as a template's return", "A template (`fn f(syntax q: string) -> anyvalue`) answers the code it builds; anywhere else write the type.");
                if (env.typeRefLoc) |l| err = err.withLoc(l);
                env.lastError = err;
                return error.TypeError;
            }
            // 1.0.5 decision 31 — `any` is deleted. It was a closed type no
            // botopink value inhabited (`val a: any = 1` read "expected any,
            // got i32"); what a host parameter or handle means by it is
            // `unknown`, which holds any value and is tested before use.
            if (std.mem.eql(u8, n, "any") and !genericMap.contains(n) and env.lookupTypeDef(n) == null and env.typeAliases.get(n) == null) {
                var err = TypeError.custom(
                    diagnostics.any_type_removed ++ ": there is no type `any`",
                    "`any` was removed (1.0.5 decision 31). A value of any type is `unknown`: it takes every value, and is tested with `is` before it is used as another type.",
                );
                if (env.typeRefLoc) |l| err = err.withLoc(l);
                env.lastError = err;
                return error.TypeError;
            }
            if (!genericMap.contains(n)) {
                if (env.typeAliases.get(n)) |alias| return expandTypeAlias(env, alias, &.{}, genericMap);
                // Decision 8 §1.1 — a written generic type carries all of its
                // type arguments: `fn get(b: Box)` for a `type Box<T>` used to
                // mean "any args" and check.
                if (env.lookupTypeDef(n)) |td| {
                    const required = requiredGenericArgs(td);
                    if (required > 0) return refuseGenericArity(env, n, required, td.genericParams().len, 0);
                }
            }
            return env.resolveTypeName(n, genericMap);
        },
        .array => |elem| {
            const elemTy = try resolveTypeRefInContext(env, elem.*, genericMap);
            const args = try env.arena.alloc(*T.Type, 1);
            args[0] = elemTy;
            return env.namedTypeArgs("array", args);
        },
        .tuple_ => |elems| {
            const args = try env.arena.alloc(*T.Type, elems.len);
            for (elems, 0..) |e, i| args[i] = try resolveTypeRefInContext(env, e, genericMap);
            return env.namedTypeArgs("tuple", args);
        },
        .labeledTuple => |lt| {
            const args = try env.arena.alloc(*T.Type, lt.elems.len);
            for (lt.elems, 0..) |e, i| args[i] = try resolveTypeRefInContext(env, e, genericMap);
            const ty = try env.namedTypeArgs("tuple", args);
            ty.named.labels = lt.labels;
            return ty;
        },
        .optional => |inner| {
            const innerTy = try resolveTypeRefInContext(env, inner.*, genericMap);
            const args = try env.arena.alloc(*T.Type, 1);
            args[0] = innerTy;
            return env.namedTypeArgs("optional", args);
        },
        .function => |f| {
            // Build a `.func` type so a `fn(A, B) -> R` annotation unifies with
            // lambda/anonymous-function values, propagating the annotated param
            // and return types into the value's fresh type variables.
            const paramTypes = try env.arena.alloc(*T.Type, f.params.len);
            for (f.params, 0..) |p, i| {
                paramTypes[i] = try resolveTypeRefInContext(env, p, genericMap);
            }
            const returnType = try resolveTypeRefInContext(env, f.returnType.*, genericMap);
            return env.funcType(paramTypes, returnType);
        },
        .generic => |b| {
            if (!b.is_builtin) {
                if (env.typeAliases.get(b.name)) |alias| return expandTypeAlias(env, alias, b.args, genericMap);
                // Decision 44 (1.0.5) — `?T` is the one optional spelling:
                // `optional<T>` (the checker's own internal name, which used
                // to check clean) and `Option<T>` / `Optional<T>` are refused
                // with the `@Option<T>` diagnostic, unless the module declares
                // a type of that name.
                const isOptionalSpelling = std.mem.eql(u8, b.name, "optional") or std.mem.eql(u8, b.name, "Option") or std.mem.eql(u8, b.name, "Optional");
                if (isOptionalSpelling and env.lookupTypeDef(b.name) == null and b.args.len == 1) {
                    var err = TypeError.custom(
                        try std.fmt.allocPrint(env.arena, "`{s}<T>` is not a type — the optional type is written `?T`", .{b.name}),
                        "Replace the annotation with `?T` (e.g. `?i32`).",
                    );
                    if (env.typeRefLoc) |l| err = err.withLoc(l);
                    env.lastError = err;
                    return error.TypeError;
                }
                if (std.mem.eql(u8, b.name, yield_step_type_name)) env.usesYieldStep = true;

                // Decision 8 §1.2 — `Self<…>` inside a declaration is the
                // declaration's own type applied to the written arguments
                // (`Self<U>` in `type Box<T>` is `Box<U>`). Where `Self` stands
                // for a non-generic implementer of a generic behavior (A1),
                // `Self<…>` is that implementer as it is.
                if (std.mem.eql(u8, b.name, "Self")) {
                    if (genericMap.get("Self")) |selfTy| {
                        const sd = selfTy.deref();
                        if (sd.* == .named) {
                            if (sd.named.args.len == 0) return sd;
                            if (sd.named.args.len != b.args.len)
                                return refuseGenericArity(env, "Self", sd.named.args.len, sd.named.args.len, b.args.len);
                            const sargs = try env.arena.alloc(*T.Type, b.args.len);
                            for (b.args, 0..) |a, i| sargs[i] = try resolveTypeRefInContext(env, a, genericMap);
                            return env.namedTypeArgs(sd.named.name, sargs);
                        }
                    }
                }
                // Decision 8 §1.1 — fewer arguments than the type's required
                // parameters (`Pair<i32>` for a `Pair<A, B>`).
                if (env.lookupTypeDef(b.name)) |td| {
                    const required = requiredGenericArgs(td);
                    if (b.args.len < required) return refuseGenericArity(env, b.name, required, td.genericParams().len, b.args.len);
                }
                // RG5 on a declared type — an argument past the parameters
                // the type declares is refused at the annotation, as it is on
                // a builtin wrapper: `YieldStep<T, E>` after decision 122 took
                // `E` away, and any `Pair<A, B>` written with a third.
                if (env.lookupTypeDef(b.name)) |td| {
                    const max = td.genericParams().len;
                    if (b.args.len > max) {
                        var err = TypeError.custom(
                            try std.fmt.allocPrint(env.arena, "{s}: `{s}` takes {s}{d} type argument{s}, {d} given", .{ diagnostics.generic_arg_count_exceeded, b.name, if (max == 0) "" else "at most ", max, if (max == 1) "" else "s", b.args.len }),
                            if (std.mem.eql(u8, b.name, yield_step_type_name))
                                "`YieldStep<T>` is `{ Yield(value: T), Done }` (decision 122): an item that can fail is a `Result`, so write `YieldStep<Result<T, E>>`."
                            else
                                "Drop the extra type argument: the type declares no parameter for it.",
                        );
                        if (env.typeRefLoc) |l| err = err.withLoc(l);
                        env.lastError = err;
                        return error.TypeError;
                    }
                }
            }
            // Decision 8 §3 — `A | B` reaches inference as a `generic` under the
            // reserved name `ast.union_type_name`; `unionMembers()` reads the
            // members back. It is a union type, not a nominal one called `|`,
            // which is what the old resolution produced ("expected |, got i32").
            if (ref.unionMembers()) |members| {
                var flat: std.ArrayListUnmanaged(*T.Type) = .empty;
                for (members) |m| {
                    const mt = try resolveTypeRefInContext(env, m, genericMap);
                    try appendUnionMember(env, &flat, mt);
                }
                // `finishUnion` collapses `A | A` to `A`: the grammar allows the
                // spelling and nothing downstream should meet a one-member union.
                return finishUnion(env, flat.items);
            }
            // RG3 (§1G) — required generic argument missing. Each known builtin
            // wrapper has a fixed required-arg minimum: the parameters before
            // the defaulted trailing range. Catching it here covers the
            // `@Future<>` / `@ResultGenerator<>` shape; user-defined types' defaults
            // are tracked separately on `TypeDef.genericParams` (follow-up).
            if (b.is_builtin) {
                if (builtinRequiredGenericArgs(b.name)) |required| {
                    if (b.args.len < required) {
                        var err = TypeError.custom(
                            "generic-required-arg-missing: a required generic argument is missing",
                            "Provide every leading (non-defaulted) type argument; only the trailing defaulted range may be omitted.",
                        );
                        if (env.typeRefLoc) |l| err = err.withLoc(l);
                        env.lastError = err;
                        return error.TypeError;
                    }
                }
                // RG5 — an argument past the declared arity names a channel
                // the wrapper does not have (`@ResultGenerator<T, E, C>` after
                // decision 103 took `C` away) and is refused at the annotation.
                if (builtinMaxGenericArgs(b.name)) |max| {
                    if (b.args.len > max) {
                        var err = TypeError.custom(
                            try std.fmt.allocPrint(env.arena, "{s}: `@{s}` takes at most {d} type argument{s}, {d} given", .{ diagnostics.generic_arg_count_exceeded, b.name, max, if (max == 1) "" else "s", b.args.len }),
                            "Drop the extra type argument: the wrapper declares no channel for it.",
                        );
                        if (env.typeRefLoc) |l| err = err.withLoc(l);
                        env.lastError = err;
                        return error.TypeError;
                    }
                }
            }
            // §1G default-fill — when fewer trailing args are supplied than the
            // builtin declares, the missing positions take their declared
            // defaults. `@Future<User>` ⇒ `@Future<User, any>`; `@ResultGenerator<i32>`
            // ⇒ `@ResultGenerator<i32, any>`; `@Generator<T>` has one parameter
            // and nothing to fill. `@Result` and `@Context` declare no
            // defaults — RG3 above already rejected an under-supplied form.
            const filled_args = if (b.is_builtin)
                builtinDefaultFilledArgs(env, b.name, b.args.len)
            else
                null;
            // User-typeDef defaults (§1G consumer-threading): when a non-
            // builtin generic name resolves to a registered TypeDef whose
            // params declared defaults, the omitted trailing slots take
            // those resolved defaults. Builtins above and user types here
            // share the post-fill flow; only the source of the default
            // differs.
            const user_defaults: ?[]const ?*T.Type = if (!b.is_builtin) blk: {
                const td = env.lookupTypeDef(b.name) orelse break :blk null;
                const dflts = td.genericDefaults();
                if (dflts.len == 0 or b.args.len >= dflts.len) break :blk null;
                break :blk dflts;
            } else null;
            const arg_count = if (filled_args) |fa|
                fa.len
            else if (user_defaults) |ud|
                ud.len
            else
                b.args.len;
            const args = try env.arena.alloc(*T.Type, arg_count);
            for (b.args, 0..) |a, i| {
                args[i] = try resolveTypeRefInContext(env, a, genericMap);
            }
            if (filled_args) |fa| {
                for (b.args.len..fa.len) |i| {
                    args[i] = try env.namedType(fa[i]);
                }
            } else if (user_defaults) |ud| {
                for (b.args.len..ud.len) |i| {
                    // A null default at this position means the param is
                    // required (the parser's strict-trailing rule means a
                    // null here can only follow a non-null one — RG3
                    // would have caught the under-supplied form, but be
                    // defensive: fall back to a fresh type var).
                    args[i] = ud[i] orelse try env.freshVar();
                }
            }
            // `?T` is the ONLY optional spelling — optional is not a concrete
            // type (user decision, 2026-06-06). The nominal forms `@Option<T>` /
            // `@Optional<T>` are rejected with a pointed diagnostic; the stdlib
            // `interface Option<T>` is the declarative reference for `?T`'s
            // methods, not a type.
            if (b.is_builtin and (std.mem.eql(u8, b.name, "Option") or std.mem.eql(u8, b.name, "Optional"))) {
                var err = TypeError.custom(
                    "`@Option<T>` is not a type — the optional type is written `?T`",
                    "Replace the annotation with `?T` (e.g. `?i32`).",
                );
                if (env.typeRefLoc) |l| err = err.withLoc(l);
                env.lastError = err;
                return error.TypeError;
            }
            // `@Expr<T>` is encoded like `optional`/`array` — a named type with
            // one arg, so structural unification gives `@Expr<T> ~ @Expr<U>
            // iff T ~ U` for free. The generic parameter is mandatory; a type
            // only the expansion knows is an ordinary fn generic
            // (`fn yaml<T>(…) -> @Expr<T>`), resolved via `genericMap` above.
            // `array<T>` is the array type `T[]` (decision 641): a named type
            // with one arg, as array-literal inference writes it (`[1, 2]`
            // infers as named "array").
            // `@ExprCustom<T>` is the marker spelling of the carrier struct
            // `CustomExpr<T>` (`{ code: Expr<T>, ast: CustomNode }`) — normalise
            // it so a template fn's `-> @ExprCustom<T>` return unifies with the
            // `q.custom(…)` value the body produces (exactly as `@Expr` ↔ the
            // `Expr` interface).
            const name = if (b.is_builtin and std.mem.eql(u8, b.name, ast.expr_custom_type_name))
                "CustomExpr"
            else
                b.name;
            // A dotted name (`collections.Dict<…>`) is a section path or an
            // associated type, resolved by `resolveTypeName`'s dotted rule —
            // never a nominal type spelled with a dot, which no declaration
            // makes and no value inhabits. A std module's type written through
            // its namespace became the leaf in `std_namespace.expand`.
            if (!b.is_builtin and std.mem.indexOfScalar(u8, name, '.') != null) {
                const head = try env.resolveTypeName(name, genericMap);
                const hd = head.deref();
                if (hd.* != .named) return head;
                return env.namedTypeArgs(hd.named.name, args);
            }
            // A generic application's head name is looked up like the bare
            // name: recorded here, refused `unknown type` by
            // `checkPendingTypeNames` once every declaration is registered.
            if (!b.is_builtin and !genericMap.contains(name) and !std.mem.eql(u8, name, "Self") and !std.mem.eql(u8, name, "array") and std.mem.indexOfScalar(u8, name, '.') == null and std.mem.indexOf(u8, name, "__") == null)
                env.notePendingTypeName(name);
            return env.namedTypeArgs(name, args);
        },
        // A comptime typeparam accepts a value of any type at the call site;
        // its constraints are validated separately (see `validateTypeparams`).
        // Resolve to a fresh variable so unification against it never fails.
        // Decision 575 (5) — `type<T>` with `T` a type parameter in scope: the
        // type argument binds `T`.
        .typeparam => |cs| {
            if (cs.len == 1 and cs[0] == .named) if (genericMap.get(cs[0].named)) |t| return t;
            return env.freshVar();
        },
        // Anonymous record type `{ f: T, … }` — a structural `Type.record` that
        // unifies field-by-field with a `record { … }` literal (same field set,
        // declaration order; see unify.zig).
    }
}

/// Resolve an `ast.TypeRef` annotation to a `*T.Type` (no generic context).
fn resolveTypeRef(env: *Env, ref: ast.TypeRef) InferError!*T.Type {
    if (env.fnGenericMap) |gm| return resolveTypeRefInContext(env, ref, gm.*);
    var genericMap = std.StringHashMap(*T.Type).init(env.arena);
    defer genericMap.deinit();
    return resolveTypeRefInContext(env, ref, genericMap);
}

// ── type aliases (decision 118 rule 1) ───────────────────────────────────────

/// Pass 1, ahead of every `type`: a record field or a signature may name an
/// alias declared further down, so every alias of the module is in scope
/// before anything resolves. Then each target is checked once (arity of what
/// it names, recursion, and — through `pendingTypeNames` — unknown names), at
/// the target's own location.
fn registerTypeAliases(env: *Env, program: ast.Program) InferError!void {
    for (program.decls) |decl| switch (decl) {
        .typeAlias => |a| try env.typeAliases.put(env.arena, a.name, a),
        else => {},
    };
    for (program.decls) |decl| switch (decl) {
        .typeAlias => |a| _ = try resolveTypeAliasTarget(env, a),
        else => {},
    };
}

/// The target with every parameter a fresh variable, located at the target.
fn resolveTypeAliasTarget(env: *Env, a: ast.TypeAliasDecl) InferError!*T.Type {
    const prev = env.atTypeRef(a.targetLoc);
    defer env.typeRefLoc = prev;
    const args = try env.arena.alloc(ast.TypeRef, a.genericParams.len);
    for (a.genericParams, 0..) |gp, i| args[i] = .{ .named = gp.name };
    var map = std.StringHashMap(*T.Type).init(env.arena);
    defer map.deinit();
    for (a.genericParams) |gp| try map.put(gp.name, try env.freshVar());
    return expandTypeAlias(env, a, args, map);
}

/// Pass 2: an alias may not take a name a type of the module (or a primitive)
/// already has — the alias would shadow it in every annotation. Answers the
/// target's type, for the declaration's binding.
fn checkTypeAliasDecl(env: *Env, a: ast.TypeAliasDecl) InferError!*T.Type {
    const taken = env.lookupTypeDef(a.name) != null or blk: {
        const b = env.bindings.get(a.name) orelse break :blk false;
        break :blk b.deref().isNamed(a.name);
    };
    if (taken) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` already names a type; an alias cannot take it", .{ diagnostics.type_alias_name_taken, a.name });
        env.lastError = TypeError.custom(msg, "Give the alias a name of its own.").withLoc(a.loc);
        return error.TypeError;
    }
    return resolveTypeAliasTarget(env, a);
}

/// `Name<args>` where `Name` is an alias: the target, with each parameter
/// bound to its argument resolved in the CALLER's generic scope. The target's
/// other names resolve in the module's scope, never the caller's generics —
/// `type Box<T> = T[];` inside `fn f<U>(x: Box<U>)` is `U[]`.
fn expandTypeAlias(
    env: *Env,
    alias: ast.TypeAliasDecl,
    args: []const ast.TypeRef,
    callerMap: std.StringHashMap(*T.Type),
) InferError!*T.Type {
    if (args.len != alias.genericParams.len) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` takes {d} type argument{s}, {d} given", .{
            diagnostics.type_alias_arity,
            alias.name,
            alias.genericParams.len,
            if (alias.genericParams.len == 1) "" else "s",
            args.len,
        });
        var err = TypeError.custom(msg, "Write the alias with one argument per parameter it declares.");
        if (env.typeRefLoc) |l| err = err.withLoc(l);
        env.lastError = err;
        return error.TypeError;
    }
    for (env.aliasExpanding.items) |open| {
        if (!std.mem.eql(u8, open, alias.name)) continue;
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` expands to itself", .{ diagnostics.type_alias_recursive, alias.name });
        var err = TypeError.custom(msg, "An alias names a type that already exists; declare a recursive type with `type Name(…)` or `type Name { … }`.");
        if (env.typeRefLoc) |l| err = err.withLoc(l);
        env.lastError = err;
        return error.TypeError;
    }
    var map = std.StringHashMap(*T.Type).init(env.arena);
    defer map.deinit();
    for (alias.genericParams, args) |gp, arg| {
        try map.put(gp.name, try resolveTypeRefInContext(env, arg, callerMap));
    }
    try env.aliasExpanding.append(env.arena, alias.name);
    defer _ = env.aliasExpanding.pop();
    return resolveTypeRefInContext(env, alias.target, map);
}

/// 01 R2 for an alias: importing `Parser` registers the alias and the types
/// its target names from the module it comes from, as types only.
fn registerAliasClosure(
    env: *Env,
    moduleDecls: std.StringHashMap(ast.DeclKind),
    a: ast.TypeAliasDecl,
    depth: usize,
) InferError!void {
    // The alias an import names was registered ahead of every type
    // (`preRegisterStdImportAliases`); its closure is still walked here, at
    // the import (depth 0): a union alias whose members are not imported by
    // name (`compiler.Node`, decision 625 (2)) brings them as types.
    if (depth >= 32 or (depth > 0 and env.typeAliases.contains(a.name))) return;
    try env.typeAliases.put(env.arena, a.name, a);
    var names: std.ArrayListUnmanaged([]const u8) = .empty;
    defer names.deinit(env.arena);
    try collectTypeRefNames(env, a.target, &names);
    for (names.items) |n| {
        if (env.lookupTypeDef(n) != null or env.typeAliases.contains(n)) continue;
        // A type the module imported rather than declared is in its map
        // under the scope prefix (`comptime.imported_type_scope_prefix`).
        const dep = moduleDecls.get(n) orelse blk: {
            var buf: [256]u8 = undefined;
            if (n.len + 1 > buf.len) continue;
            buf[0] = 0;
            @memcpy(buf[1 .. n.len + 1], n);
            break :blk moduleDecls.get(buf[0 .. n.len + 1]) orelse continue;
        };
        switch (dep) {
            .typeAlias => |d| try registerAliasClosure(env, moduleDecls, d, depth + 1),
            .type_ => {
                try registerTypeClosureDepth(env, moduleDecls, dep, depth + 1);
                if (env.lookupTypeDef(n) != null) continue;
                var before = std.StringHashMap(void).init(env.arena);
                defer before.deinit();
                var kit = env.bindings.keyIterator();
                while (kit.next()) |k| try before.put(k.*, {});
                try registerTypeDecl(env, dep);
                var added: std.ArrayListUnmanaged([]const u8) = .empty;
                defer added.deinit(env.arena);
                var ait = env.bindings.keyIterator();
                while (ait.next()) |k| if (!before.contains(k.*)) try added.append(env.arena, k.*);
                for (added.items) |k| _ = env.bindings.remove(k);
            },
            else => {},
        }
    }
}

/// Infer the type of an expression, returning a *Type.
/// On type error: sets `env.lastError` and returns `error.TypeError`.
/// This is a thin wrapper around `inferExprTyped` ---- it discards the typed node.
pub fn inferExpr(env: *Env, expr: ast.Expr) InferError!*T.Type {
    return (try inferExprTyped(env, expr)).getType();
}

// ── typed expression construction ─────────────────────────────────────────────

const TypedExpr = ast.TypedExpr;
const TypedStmt = ast.StmtOf(.typed);
const PatternBindingSnapshot = struct {
    name: []const u8,
    previous: ?*T.Type,
    /// Set by `bindNarrowed`: the name was a `val` before it was narrowed and
    /// is restored as one (a plain `bind` would make it assignable).
    wasVal: bool = false,
    /// Set by `bindNarrowed`: the snapshot is a narrowing, and `prevDecl` is
    /// the `narrowedDecl` entry the name had before it (null: none).
    narrowed: bool = false,
    prevDecl: ?*T.Type = null,
};

/// Allocate a heap-owned TypedExpr in env.arena.
fn makeTypedPtr(env: *Env, node: TypedExpr) !*TypedExpr {
    const ptr = try env.arena.create(TypedExpr);
    ptr.* = node;
    return ptr;
}

/// Convert a slice of untyped statements to typed ones (arena-allocated).
/// The statement walk for a body that needs no typed nodes back — a plain
/// `fn`, a method and a `test` block. It exists so those three apply the
/// early-exit narrowing the same way `inferStmtsTyped` does: `if (x == null) {
/// return …; }` narrows `x` for the REST of the block, and a body walked with a
/// bare `for` loop would have been the one shape where it did not.
/// Decisions 152 and 205 — no binding reuses a name already bound in the
/// function where it stands: a second `val` / `var` / destructured name, an
/// `if` binder, a loop binder or a `case` arm's binder whose name an
/// enclosing block of the same function — or the function's parameters —
/// already bound is `binding-redeclared` at the second binding, naming the
/// first, in every block and every `case` arm. A sibling block's bindings
/// ended with that block (`walkNestedBlock`), so two `if` branches may each
/// bind `n`. A lambda is another function: it is
/// checked on its own when it is inferred (`inferFunctionExprExpected`), and
/// the walk does not enter it; a `case` arm's block body is not a lambda and
/// is walked. erlang rebound a reused name and commonJS refused to load.
fn refuseRedeclaredBindings(env: *Env, stmts: []const ast.Stmt, params: []const []const u8) InferError!void {
    var seen: std.StringHashMapUnmanaged(?ast.Loc) = .empty;
    defer seen.deinit(env.arena);
    for (params) |p| {
        if (p.len == 0 or std.mem.eql(u8, p, "_")) continue;
        try seen.put(env.arena, p, null);
    }
    try walkBindingStmts(env, &seen, stmts);
}

const SeenNames = std.StringHashMapUnmanaged(?ast.Loc);

fn walkBindingStmts(env: *Env, seen: *SeenNames, stmts: []const ast.Stmt) InferError!void {
    for (stmts) |st| try walkBindingExpr(env, seen, st.expr);
}

/// A nested block: its bindings end with it (the visible-scope reading).
fn walkNestedBlock(env: *Env, seen: *SeenNames, stmts: []const ast.Stmt) InferError!void {
    var inner = try seen.clone(env.arena);
    try walkBindingStmts(env, &inner, stmts);
}

fn walkBindingExpr(env: *Env, seen: *SeenNames, e: ast.Expr) InferError!void {
    switch (e) {
        .binding => |b| switch (b.kind) {
            .localBind => |lb| {
                try walkBindingExpr(env, seen, lb.value.*);
                try noteBlockBinding(env, seen, lb.name, b.loc);
            },
            .localBindDestruct => |lb| {
                try walkBindingExpr(env, seen, lb.value.*);
                switch (lb.pattern) {
                    .names => |n| for (n.fields) |f| try noteBlockBinding(env, seen, f.bind_name, b.loc),
                    .tuple_ => |t| for (t) |name| try noteBlockBinding(env, seen, name, b.loc),
                    .list, .ctor => |p| try notePatternBinders(env, seen, p, b.loc),
                }
            },
            .assign => |a| try walkBindingExpr(env, seen, a.value.*),
        },
        .branch => |b| switch (b.kind) {
            .if_ => |i| {
                try walkBindingExpr(env, seen, i.cond.*);
                // The binder of `if (x) { v -> … }` belongs to the then-block.
                var thenSeen = try seen.clone(env.arena);
                if (i.binding) |bn| if (!std.mem.eql(u8, bn, ast.nullish_binding_name)) try noteBlockBinding(env, &thenSeen, bn, b.loc);
                try walkBindingStmts(env, &thenSeen, i.then_);
                if (i.else_) |els| try walkNestedBlock(env, seen, els);
            },
            .tryCatch => |tc| {
                try walkBindingExpr(env, seen, tc.expr.*);
                try walkBindingExpr(env, seen, tc.handler.*);
            },
        },
        .loop => |lp| {
            try walkBindingExpr(env, seen, lp.iter.*);
            var inner = try seen.clone(env.arena);
            for (lp.params) |p| try noteBlockBinding(env, &inner, p, lp.loc);
            try walkBindingStmts(env, &inner, lp.body);
        },
        .collection => |c| switch (c.kind) {
            .case => |cs| {
                for (cs.subjects) |x| try walkBindingExpr(env, seen, x);
                for (cs.arms) |arm| {
                    var armSeen = try seen.clone(env.arena);
                    const sp = &armSeen;
                    try notePatternBinders(env, sp, arm.pattern, arm.patternLoc);
                    if (arm.guard) |g| try walkBindingExpr(env, sp, g);
                    // A block arm (`Pattern { n -> … }`, `p -> { … }`) is the
                    // arm's own block, not another function.
                    if (arm.body == .function and arm.body.function.kind.syntax == .lambda) {
                        for (arm.body.function.kind.params) |p| try noteBlockBinding(env, sp, p, arm.patternLoc);
                        try walkBindingStmts(env, sp, arm.body.function.kind.body);
                    } else try walkBindingExpr(env, sp, arm.body);
                }
            },
            .arrayLit => |al| for (al.elems) |x| try walkBindingExpr(env, seen, x),
            .tupleLit => |tl| for (tl.elems) |x| try walkBindingExpr(env, seen, x),
            .grouped => |g| try walkBindingExpr(env, seen, g.*),
            else => {},
        },
        .call => |c| switch (c.kind) {
            .call => |cc| {
                if (cc.receiver) |r| try walkBindingExpr(env, seen, r.*);
                for (cc.args) |a| try walkBindingExpr(env, seen, a.value.*);
            },
            .pipeline => |pl| {
                try walkBindingExpr(env, seen, pl.lhs.*);
                try walkBindingExpr(env, seen, pl.rhs.*);
            },
        },
        .binaryOp => |op| {
            try walkBindingExpr(env, seen, op.lhs.*);
            try walkBindingExpr(env, seen, op.rhs.*);
        },
        .unaryOp => |op| try walkBindingExpr(env, seen, op.expr.*),
        .jump => |j| switch (j.kind) {
            .@"return", .throw_, .try_ => |v| if (v) |x| try walkBindingExpr(env, seen, x.*),
            .await_ => |x| try walkBindingExpr(env, seen, x.*),
            .@"break" => |br| if (br.value) |x| try walkBindingExpr(env, seen, x.*),
            .yield => |y| if (y.value) |x| try walkBindingExpr(env, seen, x.*),
            .@"continue" => {},
        },
        // A lambda (another function), a literal, a name, a comptime value.
        else => {},
    }
}

/// The names a pattern binds (a lower-case bare name, a payload's field or
/// whole-payload binder, a list element or rest); an `or` pattern's
/// alternatives bind the same names, so the first one is read.
fn notePatternBinders(env: *Env, seen: *SeenNames, p: ast.Pattern, loc: ast.Loc) InferError!void {
    switch (p) {
        .ident => |n| {
            if (n.len == 0 or isVariantPath(n) or std.ascii.isUpper(n[0])) return;
            if (std.mem.eql(u8, n, "true") or std.mem.eql(u8, n, "false") or std.mem.eql(u8, n, "null")) return;
            try noteBlockBinding(env, seen, n, loc);
        },
        .variant => |v| switch (v.payload) {
            .binding => |b| try noteBlockBinding(env, seen, b, loc),
            .fields => |fs| for (fs) |f| try noteBlockBinding(env, seen, f, loc),
            .literals => |ps| for (ps) |q| try notePatternBinders(env, seen, q, loc),
        },
        .list => |l| {
            for (l.elems) |el| switch (el) {
                .bind => |b| try noteBlockBinding(env, seen, b, loc),
                else => {},
            };
            if (l.spread) |sp| if (sp.len > 0) try noteBlockBinding(env, seen, sp, loc);
        },
        .@"or" => |alts| if (alts.len > 0) try notePatternBinders(env, seen, alts[0], loc),
        .multi => |ps| for (ps) |q| try notePatternBinders(env, seen, q, loc),
        else => {},
    }
}

fn noteBlockBinding(env: *Env, seen: *SeenNames, name: []const u8, loc: ast.Loc) InferError!void {
    if (name.len == 0 or std.mem.eql(u8, name, "_") or std.mem.startsWith(u8, name, "__bp")) return;
    if (seen.get(name)) |first| {
        const msg = if (first) |f|
            try std.fmt.allocPrint(env.arena, "{s}: `{s}` is already bound in this function, by the binding at {d}:{d}", .{ diagnostics.binding_redeclared, name, f.line, f.col })
        else
            try std.fmt.allocPrint(env.arena, "{s}: `{s}` is already bound in this function, as a parameter", .{ diagnostics.binding_redeclared, name });
        const hint = try std.fmt.allocPrint(env.arena, "A name is bound once per function — an inner block and a `case` arm included. Give the second binding its own name, or make the first a `var` and assign it: `{s} = …;`.", .{name});
        env.lastError = TypeError.custom(msg, hint).withLoc(loc);
        return error.TypeError;
    }
    try seen.put(env.arena, name, loc);
}

/// Decision 207 — what keeps a call's labels one reading
/// (`comptime/inline_types.zig`): one inline parameter type per function, and
/// none of its fields named like another parameter of the function. Each
/// refused at the inline type.
fn refuseInlineParamRules(env: *Env, f: ast.FnDecl) InferError!void {
    var seen: ?ast.Param = null;
    for (f.params) |p| {
        const fields = p.inlineFields orelse continue;
        if (seen) |first| {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` takes a second inline type (`{s}`) — one parameter of a function may have one, `{s}` already does", .{ diagnostics.inline_type_position, f.name, p.name, first.name });
            env.lastError = TypeError.custom(msg, "Name one of the two types (`type Options(…)`), or merge their fields into the one inline type.").withLoc(p.typeLoc);
            return error.TypeError;
        }
        seen = p;
        for (fields) |fd| for (f.params) |other| {
            if (std.mem.eql(u8, other.name, p.name) or !std.mem.eql(u8, other.name, fd.name)) continue;
            const msg = try std.fmt.allocPrint(env.arena, "{s}: the field `{s}` of the {s} of `{s}` is named like the parameter `{s}`, so `{s}({s}: …)` would mean two things", .{ diagnostics.inline_type_position, fd.name, p.name, f.name, other.name, f.name, fd.name });
            env.lastError = TypeError.custom(msg, "Rename the field or the parameter.").withLoc(p.typeLoc);
            return error.TypeError;
        };
    }
}

/// Decision 207 — a call's field labels build an inline parameter type only
/// in the module that declares the function (`comptime/inline_types.zig`
/// rewrites them there): the type is not exported, so a call from another
/// module that writes the fields is refused by name rather than read as
/// labels of the function.
fn refuseInlineFieldsAcrossModules(env: *Env, callee: []const u8, params: []const ast.Param, args: []const ast.CallArgOf(.untyped), loc: ast.Loc) InferError!void {
    for (params) |p| {
        const fields = p.inlineFields orelse continue;
        for (args) |a| {
            const l = a.label orelse continue;
            const isField = for (fields) |fd| {
                if (std.mem.eql(u8, fd.name, l)) break true;
            } else false;
            if (!isField) continue;
            const isParam = for (params) |q| {
                if (std.mem.eql(u8, q.name, l)) break true;
            } else false;
            if (isParam) continue;
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}:` is a field of the {s} of `{s}`, an inline type built only in the module that declares `{s}`", .{ diagnostics.inline_type_position, l, p.name, callee, callee });
            env.lastError = TypeError.custom(msg, "Call it through a function of that module, or name the type there (`pub type LinkProps(…)`) and build it here.").withLoc(loc);
            return error.TypeError;
        }
    }
}

/// The names of a parameter list, for `refuseRedeclaredBindings`.
fn paramNames(env: *Env, params: []const ast.Param) InferError![]const []const u8 {
    const out = try env.arena.alloc([]const u8, params.len);
    for (params, 0..) |p, i| out[i] = p.name;
    return out;
}

/// Infer a body's statements in order. Answers the type of its decision-409
/// tail (`tail == .value`, the last expression written without `;`) when it
/// has one, for the caller to judge against what the body answers.
fn inferBodyStmts(env: *Env, body: []const ast.Stmt) InferError!?*T.Type {
    var tailTy: ?*T.Type = null;
    try noteStatementClosures(env, body);
    var narrowed: std.ArrayListUnmanaged(PatternBindingSnapshot) = .empty;
    defer narrowed.deinit(env.arena);
    const savedStatementBlock = env.statementBlockLoc;
    defer env.statementBlockLoc = savedStatementBlock;
    for (body, 0..) |stmt, si| {
        env.statementBlockLoc = statementBlockLocOf(stmt.expr);
        env.useStatementLoc = if (stmt.expr == .useHook) stmt.expr.useHook.loc else null;
        const deferFrame = if (stmt.deferred) enterDefer(env) else null;
        defer if (deferFrame) |f| leaveDefer(env, f);
        const ty = try inferExpr(env, stmt.expr);
        if (stmt.tail == .value) tailTy = ty;
        env.useStatementLoc = null;
        try narrowAfterEarlyExit(env, stmt.expr, body[si + 1 ..], &narrowed);
        // Decision 357 — a `use` after this statement would not run on every call.
        if (env.useConstruct == null and env.earlyExitLine == null and ast.exprMayExitEarly(stmt.expr))
            env.earlyExitLine = stmt.expr.getLoc().line;
    }
    if (narrowed.items.len > 0) try restorePatternBindings(env, narrowed.items);
    return tailTy;
}

/// Decision 409 — a body that answers nothing (no `-> R`, or `-> void`)
/// takes no value from its tail: a last expression written without `;` must
/// be `void` (or never return). Refused at the expression otherwise.
fn refuseValueTailInVoid(env: *Env, what: []const u8, body: []const ast.Stmt, tailTy: ?*T.Type) InferError!void {
    const ty = tailTy orelse return;
    const tailStmt = for (0..body.len) |k| {
        if (body[body.len - 1 - k].tail == .value) break body[body.len - 1 - k];
    } else return;
    const loc = tailStmt.expr.getLoc();
    const d = ty.deref();
    if (d.* == .named and (std.mem.eql(u8, d.named.name, "void") or std.mem.eql(u8, d.named.name, "noreturn"))) return;
    if (d.* == .typeVar) return unifyAt(env, ty, try env.namedType("void"), loc);
    const rendered = try snapshotMod.typeNameOf(env.arena, ty);
    const msg = try std.fmt.allocPrint(env.arena, "{s} answers nothing, and its last expression, written without `;`, is a `{s}`", .{ what, rendered });
    const hint = try std.fmt.allocPrint(env.arena, "A body's last expression without `;` is its value (decision 409): end it with `;` to discard the value, or declare `-> {s}`.", .{rendered});
    env.lastError = TypeError.custom(msg, hint).withLoc(loc);
    return error.TypeError;
}

/// Whether a written return answers nothing: none, or `void`.
const answersNothing = ast.answersNothing;

/// Decision 525 — the location of `stmt` when it is a `case` or a block `{ … }`
/// written as a whole statement (its value discarded), else null.
fn statementBlockLocOf(stmt: ast.Expr) ?ast.Loc {
    if (stmt != .collection or stmt.collection.kind != .case) return null;
    return stmt.collection.loc;
}

fn inferStmtsTyped(env: *Env, stmts: []const ast.Stmt) InferError![]TypedStmt {
    try noteStatementClosures(env, stmts);
    const out = try env.arena.alloc(TypedStmt, stmts.len);
    // The early-exit narrowing (`narrowAfterEarlyExit`) outlives the `if` that
    // states it, so this is where it is applied and where it ends: a name
    // narrowed by a guard clause is narrowed for the REST of this block and
    // restored when the block does.
    var narrowed: std.ArrayListUnmanaged(PatternBindingSnapshot) = .empty;
    defer narrowed.deinit(env.arena);
    const savedStatementBlock = env.statementBlockLoc;
    defer env.statementBlockLoc = savedStatementBlock;
    for (stmts, 0..) |s, i| {
        env.statementBlockLoc = statementBlockLocOf(s.expr);
        const deferFrame = if (s.deferred) enterDefer(env) else null;
        defer if (deferFrame) |f| leaveDefer(env, f);
        out[i] = .{ .expr = try inferExprTyped(env, s.expr), .tail = s.tail, .deferred = s.deferred };
        try narrowAfterEarlyExit(env, s.expr, stmts[i + 1 ..], &narrowed);
    }
    if (narrowed.items.len > 0) try restorePatternBindings(env, narrowed.items);
    return out;
}

/// Convert a slice of untyped trailing lambdas to typed ones (arena-allocated).
fn inferTrailingLambdasTyped(env: *Env, trailing: []const ast.TrailingLambda) InferError![]ast.TrailingLambdaOf(.typed) {
    const out = try env.arena.alloc(ast.TrailingLambdaOf(.typed), trailing.len);
    // C1 — a trailing lambda's `return`s belong to the lambda (a
    // `use memo { -> return … }`), never to the enclosing fn.
    const savedReturnTarget = env.returnTarget;
    const savedReturnBareIsVoid = env.returnBareIsVoid;
    const savedReturnWhole = env.returnWhole;
    defer {
        env.returnTarget = savedReturnTarget;
        env.returnBareIsVoid = savedReturnBareIsVoid;
        env.returnWhole = savedReturnWhole;
    }
    env.returnWhole = null;
    for (trailing) |tl| if (tl.isBlock) {
        // Decision 525 — a trailing `{` without `->` is a block, and a trailing
        // position expects a function.
        env.lastError = TypeError.custom(
            diagnostics.block_not_function ++ ": expected a function, got a block's value — missing `->`?",
            "A `{` without `->` is a block, never a closure (decision 525): a trailing lambda with no parameter is written `f(x) { -> … }`.",
        ).withLoc(tl.loc);
        return error.TypeError;
    };
    const targets = try env.arena.alloc(*T.Type, trailing.len);
    for (trailing, 0..) |tl, i| {
        targets[i] = try env.freshVar();
        env.returnTarget = targets[i];
        env.returnBareIsVoid = false;
        out[i] = .{
            .label = tl.label,
            .params = tl.params,
            .body = try inferStmtsTyped(env, tl.body),
        };
    }
    return out;
}

/// Decision 8 §5.2 — a **type pattern**: an arm whose pattern is a bare type
/// name (`i32 { n -> … }`, `string { s -> … }`, `Person { p -> … }`) tests the
/// matched value's type and narrows the arm to it. Returns the tested type, or
/// null when the name is an ordinary binder.
///
/// The name has to be a type the env knows AND not a variant of the subject —
/// a variant path is read as a variant first, which is what keeps
/// `case s { Circle { … } }` a variant arm.
fn typePatternType(env: *Env, pattern: ast.Pattern, subjectType: *T.Type) InferError!?*T.Type {
    const name = typePatternName(env, pattern, subjectType) orelse return null;
    const named = try env.namedType(name);
    // Decision 810 (3) — over a union, the member the pattern names: a generic
    // one's arguments are the subject's own (`Box<T> { b -> b.item }` reads a
    // `T`).
    const s = subjectType.deref();
    if (s.* == .union_) for (s.union_) |m| if (memberTestedBy(m, named)) return m;
    return named;
}

/// Decision 810 (3) — the arguments written on a type pattern (`Box<T> { … }`)
/// follow `is`'s rule (810 (1)): accepted when the type they write is a member
/// of the subject's type, a type parameter nothing binds `is-type-parameter`,
/// any other argument one no run-time test can see.
fn checkTypePatternArgs(env: *Env, arm: ast.CaseArm, subjectType: *T.Type) InferError!void {
    if (arm.patternTypeArgs.len == 0 or arm.pattern != .ident) return;
    const ref = ast.TypeRef{ .generic = .{ .name = arm.pattern.ident, .args = arm.patternTypeArgs, .is_builtin = false } };
    _ = resolveTypeRef(env, ref) catch |err| return locateLast(env, err, arm.patternLoc);
    if (try boundTypeTestIdentity(env, subjectType, ref, arm.patternLoc) != null) return;
    try refuseUnboundTypeArgument(env, ref, arm.patternLoc);
    try checkIsTestableType(env, ref, arm.patternLoc);
}

/// The type name a pattern tests as a type pattern, or null when it is an
/// ordinary binder. Split out of `typePatternType` because the coverage walk
/// (§5.4) has to ask the question from `patternIsCatchAll`, which allocates
/// nothing and cannot fail: a type pattern is **not** a catch-all, and reading
/// it as one is what let `case x { i32 { … } }` stand in for `_`.
fn typePatternName(env: *Env, pattern: ast.Pattern, subjectType: *T.Type) ?[]const u8 {
    const name = switch (pattern) {
        .ident => |n| n,
        else => return null,
    };
    if (isVariantPath(name)) return null;
    if (isEnumVariantNameForSubject(env, subjectType, name)) return null;
    if (!isKnownTypeName(env, name)) return null;
    return name;
}

/// A name the env can resolve as a type: a primitive, or a declaration this
/// module registered. Deliberately *not* every name — an unregistered one is a
/// binder, which is what every arm written before decision 8 relies on.
fn isKnownTypeName(env: *Env, name: []const u8) bool {
    for (scalar_type_names) |p| if (std.mem.eql(u8, name, p)) return true;
    // Decision 810 (3) — a behavior is a type pattern too (`Composable<T> {
    // k -> … }`), tested by its identity.
    return env.lookupTypeDef(name) != null or behaviorDeclaredName(env, name) != null;
}

/// Decision 8 §5.1 P8 — the bare variant name inside a pattern's written path.
///
/// The parser keeps the path exactly as written, because the leading `.` is
/// what tells a variant path from a binding (`dff3446`): `Circle`,
/// `Shape.Circle` and `.Circle` all reach here, and only the last segment names
/// a variant. Every variant table in the checker is keyed by the bare name, so
/// nothing matched `.Circle` and every variant read as missing.
fn bareVariantName(written: []const u8) []const u8 {
    if (std.mem.lastIndexOfScalar(u8, written, '.')) |i| return written[i + 1 ..];
    return written;
}

/// True when a pattern's written name is a **path** and so can never be a
/// binding — `.None`, `Maybe.None`, `Token.Text.Bold`. A path that names no
/// variant of the subject is a mistake, not a catch-all binder.
fn isVariantPath(written: []const u8) bool {
    return std.mem.indexOfScalar(u8, written, '.') != null;
}

fn isEnumVariantNameForSubject(env: *Env, subjectType: *T.Type, candidate: []const u8) bool {
    const ty = subjectType.deref();
    if (ty.* != .named) return false;
    const bare = bareVariantName(candidate);
    if (env.lookupTypeDef(ty.named.name)) |td| {
        switch (td) {
            .enum_ => |en| {
                for (en.variants) |v| {
                    if (std.mem.eql(u8, v.name, bare)) return true;
                }
            },
            else => {},
        }
    }
    return false;
}

fn saveAndBindPatternName(
    env: *Env,
    snapshots: *std.ArrayListUnmanaged(PatternBindingSnapshot),
    name: []const u8,
    ty: *T.Type,
) InferError!void {
    var seen = false;
    for (snapshots.items) |s| {
        if (std.mem.eql(u8, s.name, name)) {
            seen = true;
            break;
        }
    }
    if (!seen) {
        try snapshots.append(env.arena, .{
            .name = name,
            .previous = env.lookup(name),
        });
    }
    try env.bind(name, ty);
}

fn restorePatternBindings(env: *Env, snapshots: []const PatternBindingSnapshot) InferError!void {
    var i = snapshots.len;
    while (i > 0) {
        i -= 1;
        const snapshot = snapshots[i];
        if (snapshot.narrowed) {
            if (snapshot.prevDecl) |d|
                try env.narrowedDecl.put(env.arena, snapshot.name, d)
            else
                _ = env.narrowedDecl.remove(snapshot.name);
        }
        if (snapshot.previous) |old| {
            if (snapshot.wasVal) try env.bindVal(snapshot.name, old) else try env.bind(snapshot.name, old);
        } else {
            _ = env.bindings.remove(snapshot.name);
        }
    }
}

fn bindPatternNamesForSubject(
    env: *Env,
    pattern: ast.Pattern,
    subjectType: *T.Type,
    snapshots: *std.ArrayListUnmanaged(PatternBindingSnapshot),
) InferError!void {
    switch (pattern) {
        .wildcard, .stringLit => {},
        .numberLit => |text| try checkNumberPattern(env, text, subjectType),
        .ident => |name| {
            if (isEnumVariantNameForSubject(env, subjectType, name)) return;
            // §5.2 — a bare type name is a type pattern, not a binder: it tests
            // the value and binds nothing. The arm's own binder is its lambda
            // parameter (`i32 { n -> … }`), bound by `inferCaseArmBody`.
            if (try typePatternType(env, pattern, subjectType)) |tested| {
                // Decision 332 (question 139-a) — as `is`: no type pattern
                // tests for a `bigint` or tests one.
                if (unifyMod.mentionsBigint(tested) or unifyMod.mentionsBigint(subjectType)) {
                    env.lastError = TypeError.custom(
                        diagnostics.bigint_type_test ++ ": a type pattern does not test a `bigint`",
                        "A `bigint`'s type is static (decision 332): match its value (`0n`, `1n...9n`) instead.",
                    );
                    return error.TypeError;
                }
                // Decision 346 — nor `Bytes`: erlang and beam hold it and a
                // `string` alike.
                if (unifyMod.mentionsBytes(tested) or unifyMod.mentionsBytes(subjectType)) {
                    env.lastError = TypeError.custom(
                        diagnostics.bytes_type_test ++ ": a type pattern does not test `bytes`",
                        "`bytes`' type is static (decision 346): a value typed `bytes` is one, and nothing else is.",
                    );
                    return error.TypeError;
                }
                return;
            }
            // C8 — a binder names the matched value itself.
            try saveAndBindPatternName(env, snapshots, name, subjectType);
        },
        .variant => |v| {
            // Decision 247 — a range's two bounds are number (or string)
            // patterns over the subject itself.
            if (v.shape == .range and v.payload == .literals) {
                for (v.payload.literals) |bound| try bindPatternNamesForSubject(env, bound, subjectType, snapshots);
                return;
            }
            // Decision 811 (1) — a record pattern opens the value: refused on
            // an opaque type outside its own methods.
            if (v.shape == .variant and !isEnumVariantNameForSubject(env, subjectType, v.name)) {
                try opaqueTypes.refusePattern(env, env.importedTypeAliases.get(v.name) orelse v.name);
            }
            // C8 — each payload binding takes the variant field's declared type,
            // instantiated against the subject's generic args. A record's
            // constructor pattern (`val assert Person(n, a) = p catch …`, the
            // subject a `Person | i32`) takes the record's field types: left
            // fresh, `a.toString()` had no lowering on wasm.
            const payload = try variantPayloadTypes(env, subjectType, v.name) orelse
                if (v.shape == .variant) try recordPatternFieldTypes(env, v.name, v.labels, switch (v.payload) {
                    .binding => 1,
                    .fields => |f| f.len,
                    .literals => |l| l.len,
                }) else null;
            switch (v.payload) {
                .binding => |binding| {
                    const ty = if (payload) |p| (if (p.len == 1) p[0] else try env.freshVar()) else try env.freshVar();
                    try saveAndBindPatternName(env, snapshots, binding, ty);
                },
                .fields => |fields| {
                    for (fields, 0..) |binding, i| {
                        const ty = if (payload) |p| (if (p.len == fields.len) p[i] else try env.freshVar()) else try env.freshVar();
                        try saveAndBindPatternName(env, snapshots, binding, ty);
                    }
                },
                .literals => |args| {
                    for (args, 0..) |arg, i| {
                        const ty = if (payload) |p| (if (p.len == args.len) p[i] else try env.freshVar()) else try env.freshVar();
                        try bindPatternNamesForSubject(env, arg, ty, snapshots);
                    }
                },
            }
        },
        .list => |lst| {
            // C8 — elements take the array's element type, the spread the array type.
            const st = subjectType.deref();
            const elemTy: ?*T.Type = if (st.* == .named and std.mem.eql(u8, st.named.name, "array") and st.named.args.len == 1) st.named.args[0] else null;
            for (lst.elems) |elem| {
                switch (elem) {
                    .bind => |name| try saveAndBindPatternName(env, snapshots, name, elemTy orelse try env.freshVar()),
                    .numberLit => |text| if (elemTy) |et| try checkNumberPattern(env, text, et),
                    else => {},
                }
            }
            if (lst.spread) |name| {
                if (name.len > 0) try saveAndBindPatternName(env, snapshots, name, if (elemTy != null) subjectType else try env.freshVar());
            }
        },
        .@"or" => |patterns| {
            if (patterns.len == 0) return;
            const before = snapshots.items.len;
            try bindPatternNamesForSubject(env, patterns[0], subjectType, snapshots);
            // C8 — a name bound by every alternative is the unification of its
            // types across them; disagreeing alternatives red.
            for (patterns[1..]) |alt| {
                var local: std.ArrayListUnmanaged(PatternBindingSnapshot) = .empty;
                defer local.deinit(env.arena);
                try bindPatternNamesForSubject(env, alt, subjectType, &local);
                for (local.items) |ls| {
                    const newTy = env.lookup(ls.name) orelse continue;
                    var inFirst = false;
                    for (snapshots.items[before..]) |fs| {
                        if (std.mem.eql(u8, fs.name, ls.name)) inFirst = true;
                    }
                    if (inFirst) {
                        if (ls.previous) |prev| {
                            // Located by the caller that holds the pattern's
                            // place (`locateLast`).
                            try unifyUnlocated(env, prev, newTy);
                            try env.bind(ls.name, prev);
                        }
                    } else {
                        try snapshots.append(env.arena, ls);
                    }
                }
            }
        },
        .multi => {},
    }
}

/// The types of the `count` elements of a record's constructor pattern: the
/// field each stands at — its label, else its position. A non-generic record
/// the module can open, written bare and filled completely; null otherwise,
/// and the bindings stay fresh.
fn recordPatternFieldTypes(env: *Env, writtenName: []const u8, labels: []const []const u8, count: usize) InferError!?[]*T.Type {
    if (std.mem.indexOfScalar(u8, writtenName, '.') != null) return null;
    const td = env.lookupTypeDef(writtenName) orelse return null;
    const r = switch (td) {
        .record => |r| r,
        else => return null,
    };
    if (r.genericParams.len != 0 or count != r.fields.len) return null;
    const out = try env.arena.alloc(*T.Type, count);
    for (out, 0..) |*o, i| {
        if (labels.len > i and labels[i].len > 0) {
            const at = for (r.fields, 0..) |f, k| {
                if (std.mem.eql(u8, f.name, labels[i])) break k;
            } else return null;
            o.* = r.fields[at].type_;
        } else o.* = r.fields[i].type_;
    }
    return out;
}

/// C8 — the declared payload field types of `variantName` for a value of
/// `subjectType`, instantiated against the subject's generic args; null when
/// the subject's type or the variant is not known (the bindings stay fresh).
/// `@Result<R, E>`: `Ok` → [R], `Err`/`Error` → [E]; `?T`: `Some` → [T].
fn variantPayloadTypes(env: *Env, subjectType: *T.Type, writtenName: []const u8) InferError!?[]*T.Type {
    const st = subjectType.deref();
    if (st.* != .named) return null;
    const n = st.named;
    const eq = std.mem.eql;
    // §5.1 P8 — the written form may be a path (`.Some`, `Maybe.Some`); the
    // payload table is keyed by the bare variant name.
    const variantName = bareVariantName(writtenName);
    if (eq(u8, n.name, "Result") and n.args.len >= 2) {
        if (eq(u8, variantName, "Ok")) return try env.arena.dupe(*T.Type, n.args[0..1]);
        if (eq(u8, variantName, "Err") or eq(u8, variantName, "Error")) return try env.arena.dupe(*T.Type, n.args[1..2]);
        return null;
    }
    if (eq(u8, n.name, "optional") and n.args.len == 1) {
        if (eq(u8, variantName, "Some")) return try env.arena.dupe(*T.Type, n.args[0..1]);
        return null;
    }
    const td = env.lookupTypeDef(n.name) orelse return null;
    if (td != .enum_) return null;
    const en = td.enum_;
    var fields: ?[]envMod.FieldDef = null;
    for (en.variants) |vd| {
        if (eq(u8, vd.name, variantName)) fields = vd.fields;
    }
    const fs = fields orelse return null;
    const out = try env.arena.alloc(*T.Type, fs.len);
    // The registration cells of a generic enum are the args of any of its
    // variant constructors' result type (`Enum<A_cell, …>`).
    var seen = std.AutoHashMap(*T.TypeCell, *T.Type).init(env.arena);
    defer seen.deinit();
    if (en.genericParams.len > 0 and n.args.len == en.genericParams.len) {
        for (en.variants) |vd| {
            const ctor = env.lookup(vd.name) orelse env.typeOnlyCtors.get(vd.name) orelse continue;
            const cd = ctor.deref();
            const ret = if (cd.* == .func) cd.func.ret.deref() else cd;
            if (ret.* != .named or !eq(u8, ret.named.name, en.name) or ret.named.args.len != n.args.len) continue;
            for (ret.named.args, n.args) |cellTy, inst| {
                const cr = cellTy.deref();
                if (cr.* == .typeVar) try seen.put(cr.typeVar, inst);
            }
            break;
        }
    }
    for (fs, 0..) |f, i| {
        out[i] = if (seen.count() > 0) try instantiateType(env, f.type_, &seen, .allVars) else f.type_;
    }
    return out;
}

/// 06 C9 — whether `td` answers `member` by some route other than an inherent
/// method: a field of function type called like a method (`c.set(9)` on
/// `#(value, set)`-shaped records), or a `default fn` the type adopts from a
/// behavior it implements (through that behavior's `extends` chain). Both are
/// legitimate and neither is registered in `inherentMethods`, so the unknown-
/// method check has to ask before it reds.
fn typeAnswersMember(env: *Env, td: envMod.TypeDef, member: []const u8) bool {
    if (td.fields()) |fs| {
        for (fs) |f| {
            if (std.mem.eql(u8, f.name, member)) return true;
        }
    }
    const implements: []const []const u8 = switch (td) {
        .record => |r| r.implements,
        .struct_ => |st| st.implements,
        .enum_ => |e| e.implements,
    };
    for (implements) |iface| {
        if (behaviorDeclaresMember(env, iface, member, 0)) return true;
    }
    return false;
}

/// Whether `iface` — or anything it extends — declares `method` as a method
/// with no body (a `default fn` is emitted with the implementer, so it is not
/// the value's own). `depth` bounds a cyclic `extends` chain.
fn behaviorDeclaresBodyless(env: *Env, iface: []const u8, method: []const u8, depth: usize) bool {
    if (depth >= 16) return false;
    const decl = env.behaviorDecl(iface) orelse return false;
    for (decl.methods) |m| {
        if (std.mem.eql(u8, m.name, method)) return !m.is_default and !m.is_declare and m.body == null;
    }
    for (decl.extends) |parent| {
        if (behaviorDeclaresBodyless(env, parent, method, depth + 1)) return true;
    }
    return false;
}

const BehaviorMethodFound = struct { decl: ast.BehaviorDecl, method: ast.BehaviorMethod };

/// The bodyless method `iface` — or anything it extends — declares under
/// `method`, with the behavior that declares it.
fn behaviorBodylessMethod(env: *Env, iface: []const u8, method: []const u8, depth: usize) ?BehaviorMethodFound {
    if (depth >= 16) return null;
    const decl = env.behaviorDecl(iface) orelse return null;
    for (decl.methods) |m| {
        if (std.mem.eql(u8, m.name, method)) {
            if (m.is_default or m.is_declare or m.body != null) return null;
            return .{ .decl = decl, .method = m };
        }
    }
    for (decl.extends) |parent| {
        if (behaviorBodylessMethod(env, parent, method, depth + 1)) |found| return found;
    }
    return null;
}

/// The type a call of a behavior's bodyless method answers on a value of the
/// behavior `iface`: the declared return, `Self` being the receiver and the
/// behavior's own type parameters its type arguments, each argument unified
/// with the parameter it fills. Null when the declaration names no return, or
/// the call is not the plain positional shape this reads.
fn behaviorMethodCallType(
    env: *Env,
    iface: []const u8,
    recvPtr: *ast.TypedExpr,
    method: []const u8,
    typedArgs: []ast.CallArgOf(.typed),
    typedTrailing: []ast.TrailingLambdaOf(.typed),
) InferError!?*T.Type {
    const found = behaviorBodylessMethod(env, iface, method, 0) orelse return null;
    return behaviorFoundCallType(env, found, recvPtr, typedArgs, typedTrailing);
}

/// The `default fn` `iface` — or anything it extends — declares under
/// `method`, with the behavior that declares it.
fn behaviorDefaultMethod(env: *Env, iface: []const u8, method: []const u8, depth: usize) ?BehaviorMethodFound {
    if (depth >= 16) return null;
    const decl = env.behaviorDecl(iface) orelse return null;
    for (decl.methods) |m| {
        if (std.mem.eql(u8, m.name, method)) {
            if (!m.is_default or m.body == null) return null;
            return .{ .decl = decl, .method = m };
        }
    }
    for (decl.extends) |parent| {
        if (behaviorDefaultMethod(env, parent, method, depth + 1)) |found| return found;
    }
    return null;
}

/// A call of a `default fn` a nominal type adopts from a behavior it
/// implements answers the member's declared return, `Self` the receiver —
/// as a call of a bodyless member does on a value of the behavior. It was a
/// fresh variable, so `sq.checked().isOk()` on a `-> @Result` default fn
/// found no `@Result` lowering.
fn adoptedDefaultCallType(
    env: *Env,
    td: envMod.TypeDef,
    recvPtr: *ast.TypedExpr,
    method: []const u8,
    typedArgs: []ast.CallArgOf(.typed),
    typedTrailing: []ast.TrailingLambdaOf(.typed),
) InferError!?*T.Type {
    const implements: []const []const u8 = switch (td) {
        .record => |r| r.implements,
        .struct_ => |st| st.implements,
        .enum_ => |e| e.implements,
    };
    for (implements) |iface| {
        const found = behaviorDefaultMethod(env, iface, method, 0) orelse continue;
        return behaviorFoundCallType(env, found, recvPtr, typedArgs, typedTrailing);
    }
    return null;
}

fn behaviorFoundCallType(
    env: *Env,
    found: BehaviorMethodFound,
    recvPtr: *ast.TypedExpr,
    typedArgs: []ast.CallArgOf(.typed),
    typedTrailing: []ast.TrailingLambdaOf(.typed),
) InferError!?*T.Type {
    const rt = found.method.returnType orelse return null;
    const params = found.method.params;
    const rest = if (params.len > 0 and std.mem.eql(u8, params[0].name, "self")) params[1..] else params;
    if (typedTrailing.len != 0 or rest.len != typedArgs.len) return null;
    for (typedArgs) |ta| if (ta.label != null) return null;
    var gm = std.StringHashMap(*T.Type).init(env.arena);
    defer gm.deinit();
    const recvTy = recvPtr.getType();
    try gm.put("Self", recvTy);
    const named = recvTy.deref();
    for (found.decl.genericParams, 0..) |gp, i| {
        const arg = if (named.* == .named and i < named.named.args.len) named.named.args[i] else try env.freshVar();
        try gm.put(gp.name, arg);
    }
    for (found.method.genericParams) |gp| try gm.put(gp.name, try env.freshVar());
    for (rest, typedArgs) |p, ta| {
        try unifyAt(env, try paramTypeInContext(env, p, gm), ta.value.getType(), ta.value.getLoc());
    }
    return try resolveTypeRefInContext(env, rt, gm);
}

/// Decisions 311 (3), 415 (1) — whether a value of the type `typeName` has a
/// method `method` of its own, which a template method of the same name never
/// shadows: one written in the type's body, one a behavior it implements
/// declares — its `default fn` included, through `extends` — or, for a value
/// of a behavior, one that behavior declares.
fn receiverHasMethod(env: *Env, typeName: []const u8, method: []const u8) bool {
    if (env.hasInherentMethod(typeName, method)) return true;
    if (behaviorDeclaresSelfMethod(env, typeName, method, 0)) return true;
    const td = env.lookupTypeDef(typeName) orelse return false;
    const implements: []const []const u8 = switch (td) {
        .record => |r| r.implements,
        .struct_ => |st| st.implements,
        .enum_ => |e| e.implements,
    };
    for (implements) |iface| if (behaviorDeclaresSelfMethod(env, iface, method, 0)) return true;
    return false;
}

/// Whether `iface` — or anything it extends — declares `method` as a method
/// taking `self` (bodyless or a `default fn`); an associated function is
/// called through the behavior's name, never on a value. `depth` bounds a
/// cyclic `extends` chain.
fn behaviorDeclaresSelfMethod(env: *Env, iface: []const u8, method: []const u8, depth: usize) bool {
    if (depth >= 16) return false;
    const decl = env.behaviorDecl(iface) orelse return false;
    for (decl.methods) |m| {
        if (std.mem.eql(u8, m.name, method)) return m.params.len > 0 and std.mem.eql(u8, m.params[0].name, "self");
    }
    for (decl.extends) |parent| {
        if (behaviorDeclaresSelfMethod(env, parent, method, depth + 1)) return true;
    }
    return false;
}

/// Whether `iface` — or anything it extends — declares `member`. `depth` bounds
/// a cyclic `extends` chain.
fn behaviorDeclaresMember(env: *Env, iface: []const u8, member: []const u8, depth: usize) bool {
    if (depth >= 16) return false;
    const decl = env.behaviorDecl(iface) orelse return false;
    for (decl.methods) |m| {
        if (std.mem.eql(u8, m.name, member)) return true;
    }
    for (decl.fields) |f| {
        if (std.mem.eql(u8, f.name, member)) return true;
    }
    for (decl.extends) |parent| {
        if (behaviorDeclaresMember(env, parent, member, depth + 1)) return true;
    }
    return false;
}

/// Decision 2 — whether a branch's statements end in something that HAS a
/// value. Every binding expression (an assignment, a `val`/`var`, a
/// destructuring) and a loop are statements: they end the branch with nothing
/// for the other branch to agree with.
fn stmtsYieldValue(stmts: []const ast.StmtOf(.typed)) bool {
    if (stmts.len == 0) return false;
    const last = lastNonComment(stmts) orelse return false;
    return switch (last.expr) {
        .binding => false,
        .loop => false,
        else => true,
    };
}

/// 06 N24 / decision 8 §6 — `c.set(9)` where `set` is a LABEL of the tuple
/// `c`, naming an element of function type. Types the call from that element's
/// signature and records the positional rewrite the backends need
/// (`c._1(9)`), the same `enumSectionRewrites` channel the member-access path
/// uses for `row.pop` → `row._1`. Null when the receiver is not a labelled
/// tuple, or the callee is not one of its labels — every other dispatch then
/// runs as before.
fn inferTupleLabelCall(
    env: *Env,
    recvPtr: ?*ast.TypedExpr,
    recvExpr: ?*ast.Expr,
    callee: []const u8,
    typedArgs: []ast.CallArgOf(.typed),
    typedTrailing: []ast.TrailingLambdaOf(.typed),
    loc: ast.Loc,
) InferError!?TypedExpr {
    const recv = recvPtr orelse return null;
    const written = recvExpr orelse return null;
    const rt = recv.getType().deref();
    if (rt.* != .named or !std.mem.eql(u8, rt.named.name, "tuple")) return null;
    const idx = tupleLabelIndex(rt.named.labels, callee) orelse return null;
    if (idx >= rt.named.args.len) return null;

    const elem = rt.named.args[idx].deref();
    const retType: *T.Type = switch (elem.*) {
        .func => |f| blk: {
            const total = typedArgs.len + typedTrailing.len;
            if (f.params.len != total) {
                env.lastError = TypeError.arityMismatch(callee, f.params.len, total).withLoc(loc);
                return error.TypeError;
            }
            try refuseLabelsOnFunctionValue(env, callee, typedArgs);
            for (typedArgs, f.params[0..typedArgs.len]) |ta, p| {
                try unifyAt(env, p, ta.value.getType(), ta.value.getLoc());
            }
            break :blk f.ret;
        },
        else => try env.freshVar(),
    };

    const positional = try std.fmt.allocPrint(env.arena, "_{d}", .{idx});
    const rewrite = try env.arena.create(ast.Expr);
    rewrite.* = .{ .call = .{ .loc = loc, .kind = .{ .call = .{
        .receiver = written,
        .callee = positional,
        .is_builtin = false,
        .args = &.{},
        .trailing = &.{},
    } } } };
    try env.enumSectionRewrites.put(loc, rewrite);

    return TypedExpr{ .call = .{ .loc = loc, .type_ = retType, .kind = .{ .call = .{
        .receiver = recvPtr,
        .callee = positional,
        .is_builtin = false,
        .args = typedArgs,
        .trailing = typedTrailing,
    } } } };
}

/// 06 C3 — arithmetic constrains its operands to a numeric type, reported at
/// the offending operand. `"a" * "b"` and `-"s"` used to check: `*` only
/// unified the two sides with each other (two strings agree) and `-` applied
/// no constraint at all. Permissive for a type variable an inference gap has
/// not resolved, and for any named type the env does not know to be
/// non-numeric — only the types that certainly hold no arithmetic red.
/// The two type kinds decision 8 says must be **narrowed before they are
/// used**: `unknown` (§2.2) and a union (§3.3). Both carry a set of
/// possibilities rather than one type, and both reach the same five operations
/// — arithmetic, `+`, an ordering comparison, a field read and a method call —
/// through a permissive tail that would otherwise accept silently.
///
/// `@print(x)`, `x == y`, `x != y`, assignment and passing to a generic
/// parameter stay allowed for both, and reach inference by paths this is not on.
///
/// §3.3's own rule is narrower than this: a use is allowed when **every**
/// member allows it. Deciding that means re-resolving the operation once per
/// member, which this front has not built; refusing the union outright refuses
/// more than §3.3 and is never wrong, and the fix — narrow first — is the same
/// sentence either way.
///
/// `what` completes "cannot …", so it is a verb phrase.
fn refuseUnknownUse(env: *Env, ty: *T.Type, loc: ast.Loc, what: []const u8) InferError!void {
    const t = ty.deref();
    if (unifyMod.isUnknown(t)) {
        var e = TypeError.custom(
            try std.fmt.allocPrint(env.arena, "cannot {s} an `unknown` value", .{what}),
            "Narrow it first: `if (x is i32) { … }` makes `x` an `i32` inside the block.",
        );
        env.lastError = e.withLoc(loc);
        return error.TypeError;
    }
    if (t.* == .union_) {
        const rendered = try snapshotMod.typeNameOf(env.arena, t);
        // §3.2 — name the branch that widened it, when inference made it.
        const widened: []const u8 = if (env.unionOrigins.get(t)) |o|
            (if (std.mem.eql(u8, o.kind, "array element"))
                try std.fmt.allocPrint(env.arena, " (the array element at {d}:{d} made it one: the literal's elements disagree)", .{ o.loc.line, o.loc.col })
            else
                try std.fmt.allocPrint(env.arena, " (the `{s}` at {d}:{d} made it one: its branches disagree)", .{ o.kind, o.loc.line, o.loc.col }))
        else
            "";
        var e = TypeError.custom(
            try std.fmt.allocPrint(env.arena, "cannot {s} a `{s}` — not every member of the union answers it{s}", .{ what, rendered, widened }),
            "Narrow it first: a `case` with one arm per member, or `if (v is i32) { … }`.",
        );
        env.lastError = e.withLoc(loc);
        return error.TypeError;
    }
}

/// Decision 8 §4.2 — what may stand on the right of `is`: a primitive, a named
/// type's constructor, a tuple `#(…)`, and a generic type applied to `unknown`
/// only.
///
/// `Box<i32>` is the error the section names: a run-time test can see that a
/// value is a `Box`, and cannot see what is in it, so `Box<i32>` would be a
/// promise the test does not keep. `Box<unknown>` says exactly what the test
/// can answer. A tuple is checkable — arity and each element are — and so are
/// the other structural spellings the grammar builds out of type refs.
/// Decision 297 — the type a call argument names, when it is a type written
/// where a `comptime x: V | type<T>` parameter is: a primitive or a declared
/// type, not a local value.
fn typeArgName(env: *Env, e: ast.Expr) ?[]const u8 {
    if (e != .identifier or e.identifier.kind != .ident) return null;
    const n = e.identifier.kind.ident;
    if (env.localBindDepth(n) != null) return null;
    if (isPrimitiveTypeName(n) or env.lookupTypeDef(n) != null) return n;
    return null;
}

/// Decision 297 — a type argument typed as the parameter's value form with
/// `T` bound to the type (`pick(User)` against `comptime s: Box<T> | type<T>`
/// is a `Box<User>`), so unifying it with the parameter binds `T` and the
/// call's return reads it. Any other name the value form mentions that is no
/// type is a fresh variable.
fn typeArgument(env: *Env, p: ast.Param, typeParam: []const u8, typeName: []const u8, e: ast.Expr) InferError!TypedExpr {
    var map = std.StringHashMap(*T.Type).init(env.arena);
    try map.put(typeParam, try env.namedType(typeName));
    try freshNamesOf(env, p.typeRef, &map);
    const ty = try resolveTypeRefInContext(env, p.typeRef, map);
    return TypedExpr{ .identifier = .{ .loc = e.identifier.loc, .type_ = ty, .kind = .{ .ident = typeName } } };
}

fn freshNamesOf(env: *Env, ref: ast.TypeRef, map: *std.StringHashMap(*T.Type)) InferError!void {
    switch (ref) {
        .named => |n| if (!map.contains(n) and !isPrimitiveTypeName(n) and env.lookupTypeDef(n) == null and env.typeAliases.get(n) == null) {
            try map.put(n, try env.freshVar());
        },
        .generic => |g| for (g.args) |a| try freshNamesOf(env, a, map),
        else => {},
    }
}

/// Decision 297 — a call whose argument is a type calls the function's type
/// form (`value_or_type.zig`'s twin `<name>__type`) with that argument
/// removed: recorded as the call's rewrite, and the callee's name noted so an
/// import of it brings the twin along.
fn noteTypeArgCall(env: *Env, c: ast.CallExprOf(.untyped), at: usize, loc: ast.Loc) InferError!void {
    const call = c.kind.call;
    var direct = c;
    const args = try env.arena.alloc(ast.CallArg, call.args.len - 1);
    @memcpy(args[0..at], call.args[0..at]);
    @memcpy(args[at..], call.args[at + 1 ..]);
    direct.kind.call.args = args;
    direct.kind.call.callee = try std.fmt.allocPrint(env.arena, "{s}{s}", .{ call.callee, valueOrType.twin_suffix });
    const spliced = try env.arena.create(ast.Expr);
    spliced.* = .{ .call = direct };
    spliced.call.loc = loc;
    try env.indexRewrites.put(loc, spliced);
    try env.typeArgTwins.put(env.arena, call.callee, {});
}

/// Decision 280 (0), read by 297 — the argument of a `comptime` parameter is
/// known while the program compiles: a run-time value (a local binding or a
/// parameter of the enclosing function that is not itself `comptime`) is
/// refused at the argument, as `comptime-arg-not-known`. A decorator's
/// `@Decl` and a template's `@Expr` parameters are not arguments of a call.
fn refuseRuntimeComptimeArg(env: *Env, p: ast.Param, e: ast.Expr) InferError!void {
    if (p.modifier != .@"comptime") return;
    if (p.typeRef.isDeclType()) return;
    if (p.typeRef == .generic and p.typeRef.generic.is_builtin) return;
    const at = runtimeNameIn(env, e) orelse return;
    const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is a run-time value, and the parameter `{s}` is `comptime` — its argument is known while the program compiles", .{ diagnostics.comptime_arg_not_known, at.name, p.name });
    env.lastError = TypeError.custom(msg, "Pass a literal, a type, a constructor of known values, or a `comptime` parameter of the enclosing function (decisions 280, 297).").withLoc(at.loc);
    return error.TypeError;
}

const RuntimeName = struct { name: []const u8, loc: ast.Loc };

/// The first name `e` reads that holds a run-time value: a local binding, or a
/// parameter of the enclosing function that is not `comptime`.
fn runtimeNameIn(env: *Env, e: ast.Expr) ?RuntimeName {
    switch (e) {
        .identifier => |id| {
            if (id.kind == .identAccess) {
                const inner = runtimeNameIn(env, id.kind.identAccess.receiver.*) orelse return null;
                return .{ .name = inner.name, .loc = inner.loc };
            }
            if (id.kind != .ident) return null;
            const n = id.kind.ident;
            if (env.localBindDepth(n) == null) return null;
            if (env.fnDecls.get(env.currentFnName)) |f| for (f.params) |fp| {
                if (fp.modifier == .@"comptime" and std.mem.eql(u8, fp.name, n)) return null;
            };
            // A type method's `comptime` parameter is as known as a
            // function's: its body's parameters are `bodyParams`, and its
            // name is no `fnDecls` entry.
            for (env.bodyParams) |fp| {
                if (fp.modifier == .@"comptime" and std.mem.eql(u8, fp.name, n)) return null;
            }
            return .{ .name = n, .loc = id.loc };
        },
        .unaryOp => |u| return runtimeNameIn(env, u.expr.*),
        .binaryOp => |b| return runtimeNameIn(env, b.lhs.*) orelse runtimeNameIn(env, b.rhs.*),
        .call => |c| {
            if (c.kind != .call) return null;
            if (c.kind.call.receiver) |r| if (runtimeNameIn(env, r.*)) |n| return n;
            for (c.kind.call.args) |a| if (runtimeNameIn(env, a.value.*)) |n| return n;
            return null;
        },
        // Decision 562 — a field of a run-time value is one (`box.n`), as is
        // a hole, an element, a member of one.
        .literal => |l| switch (l.kind) {
            .stringTemplate => |t| {
                for (t.parts) |p| switch (p) {
                    .text => {},
                    .expr => |h| if (runtimeNameIn(env, h.*)) |n| return n,
                };
                return null;
            },
            else => return null,
        },
        .collection => |col| switch (col.kind) {
            .grouped => |g| return runtimeNameIn(env, g.*),
            .arrayLit => |al| {
                for (al.elems) |el| if (runtimeNameIn(env, el)) |n| return n;
                return null;
            },
            .tupleLit => |tl| {
                for (tl.elems) |el| if (runtimeNameIn(env, el)) |n| return n;
                return null;
            },
            else => return null,
        },
        else => return null,
    }
}

/// Decision 667 — `ref`, the type an `is` tests, when it names a `comptime t:
/// type<T>` parameter of the body being inferred: the `T` it stands for. Null
/// for anything else.
fn typeTokenRef(env: *const Env, ref: ast.TypeRef) ?ast.TypeRef {
    if (ref != .named) return null;
    const p = typeTokenParam(env.bodyParams, ref.named) orelse return null;
    return p.typeRef.typeparam[0];
}

/// Decision 758 — `ref`, the type an `is` tests, when it names a run-time type
/// token `t: type<T>` (no `comptime`) of the body being inferred: the `T` it
/// stands for. Null for anything else.
fn runtimeTokenRef(env: *const Env, ref: ast.TypeRef) ?ast.TypeRef {
    if (ref != .named) return null;
    const p = runtimeTokenParam(env.bodyParams, ref.named) orelse return null;
    return p.typeRef.typeparam[0];
}

/// The parameter `name` of `params` when it is a run-time `t: type<T>` one.
fn runtimeTokenParam(params: []const ast.Param, name: []const u8) ?ast.Param {
    for (params) |p| {
        if (!std.mem.eql(u8, p.name, name)) continue;
        if (p.modifier != .@"comptime" and p.typeRef == .typeparam and p.typeRef.typeparam.len == 1) return p;
        return null;
    }
    return null;
}

/// The parameter `name` of `params` when it is a `comptime t: type<T>` one.
fn typeTokenParam(params: []const ast.Param, name: []const u8) ?ast.Param {
    for (params) |p| {
        if (!std.mem.eql(u8, p.name, name)) continue;
        if (p.modifier == .@"comptime" and p.typeRef == .typeparam and p.typeRef.typeparam.len == 1) return p;
        return null;
    }
    return null;
}

/// Decision 667 — `v is T` with `T` a type parameter of the enclosing function
/// (or of its type): erased at run time, no target can decide it. The way out
/// is a type token, in either form (decisions 757, 758).
fn refuseIsTypeParameter(env: *Env, ref: ast.TypeRef, loc: ast.Loc) InferError!void {
    return refuseIsTypeParameterIn(env, ref, null, loc);
}

/// `refuseIsTypeParameter` for `ref` written inside the tested type `outer`
/// (`x is Box<T>`, decision 810 (1)), which the message names.
fn refuseIsTypeParameterIn(env: *Env, ref: ast.TypeRef, outer: ?ast.TypeRef, loc: ast.Loc) InferError!void {
    if (ref != .named or std.mem.eql(u8, ref.named, "Self")) return;
    const n = ref.named;
    const inScope = (if (env.fnGenericMap) |gm| gm.contains(n) else false) or
        (if (env.methodGenericMap) |gm| gm.contains(n) else false);
    if (!inScope) return;
    const written = if (outer) |o| try std.fmt.allocPrint(env.arena, "{f}", .{o}) else n;
    const msg = try std.fmt.allocPrint(env.arena, "{s}: `is {s}` tests the type parameter `{s}`, which no target knows at run time — take the type as `comptime t: type<{s}>` or `t: type<{s}>` and test `v is t`", .{ diagnostics.is_type_parameter, written, n, n, n });
    const hint = try std.fmt.allocPrint(env.arena, "`fn get<{s}>(self: Registry, comptime t: type<{s}>) -> ?{s} {{ … if (e is t) … }}`, called `r.get(Users)`, is specialised per type (decision 757); `t: type<{s}>` without `comptime` is the type's identity at run time, one function for every type (decision 758).", .{ n, n, n, n });
    env.lastError = TypeError.custom(msg, hint).withLoc(loc);
    return error.TypeError;
}

/// Decision 810 (1) — `v is X<A, …>` where `X<A, …>` is a member of `v`'s
/// static type (`v` itself when its type is no union): the arguments are bound
/// through `v`'s type, so the test needs only `X`'s identity. Answers the form
/// the backends test, `X<unknown, …>`; null when the written type is not such
/// a member (a union, a type with no argument, or arguments `unknown` alone
/// need nothing of this).
fn boundTypeTestIdentity(env: *Env, valueType: *T.Type, tested: ast.TypeRef, loc: ast.Loc) InferError!?ast.TypeRef {
    _ = loc;
    if (tested != .generic or tested.unionMembers() != null) return null;
    const g = tested.generic;
    const allUnknown = for (g.args) |a| {
        if (!(a == .named and std.mem.eql(u8, a.named, ast.unknown_type_name))) break false;
    } else true;
    if (allUnknown) return null;
    const want = try resolveTypeRef(env, tested);
    if (staticMemberMatching(valueType, want) == null) return null;
    const args = try env.arena.alloc(ast.TypeRef, g.args.len);
    for (args) |*a| a.* = .{ .named = ast.unknown_type_name };
    return ast.TypeRef{ .generic = .{ .name = g.name, .args = args, .is_builtin = g.is_builtin, .bare = g.bare } };
}

/// The member of `valueType` (the type itself when it is no union) that is
/// `want`: the same named type with the same arguments, a written `unknown`
/// argument matching any. Null when none is.
fn staticMemberMatching(valueType: *T.Type, want: *T.Type) ?*T.Type {
    const v = valueType.deref();
    const members: []const *T.Type = if (v.* == .union_) v.union_ else &.{v};
    for (members) |m| if (sameTypeWritten(m, want)) return m;
    return null;
}

/// `a` and `b` are one type as written: the same type variable, or the same
/// head with the same arguments; an `unknown` on `b`'s side matches anything.
fn sameTypeWritten(a: *T.Type, b: *T.Type) bool {
    const da = a.deref();
    const db = b.deref();
    if (da == db) return true;
    if (unifyMod.isUnknown(db)) return true;
    switch (da.*) {
        .named => |na| {
            if (db.* != .named) return false;
            const nb = db.named;
            if (!std.mem.eql(u8, na.name, nb.name) or na.args.len != nb.args.len) return false;
            for (na.args, nb.args) |x, y| if (!sameTypeWritten(x, y)) return false;
            return true;
        },
        .func => |fa| {
            if (db.* != .func) return false;
            const fb = db.func;
            if (fa.params.len != fb.params.len) return false;
            for (fa.params, fb.params) |x, y| if (!sameTypeWritten(x, y)) return false;
            return sameTypeWritten(fa.ret, fb.ret);
        },
        .typeVar => return db.* == .typeVar and da.typeVar == db.typeVar,
        else => return false,
    }
}

/// Decision 810 (1), (3) — the declared name of the behavior `name` names
/// (one this module declares, imports or finds ambient), or null.
fn behaviorDeclaredName(env: *Env, name: []const u8) ?[]const u8 {
    for (env.moduleDecls) |d| if (d == .behavior and std.mem.eql(u8, d.behavior.name, name)) return name;
    if (env.importedBehaviorDecls.get(name)) |b| return b.name;
    if (env.ambientBehaviorDecls.get(name)) |b| return b.name;
    return null;
}

/// Decision 810 (1) — the tested type the backends lower: a behavior's
/// (`v is Composable<unknown>`) is `ast.behavior_test_prefix` and its declared
/// name, the identity every implementing type carries; any other unchanged.
fn behaviorTestRef(env: *Env, ref: ast.TypeRef) InferError!ast.TypeRef {
    const name = switch (ref) {
        .named => |n| n,
        .generic => |g| if (ref.unionMembers() != null or g.is_builtin) return ref else g.name,
        else => return ref,
    };
    if (env.lookupTypeDef(name) != null) return ref;
    const declared = behaviorDeclaredName(env, name) orelse return ref;
    return .{ .named = try std.fmt.allocPrint(env.arena, "{s}{s}", .{ ast.behavior_test_prefix, declared }) };
}

/// Decision 810 (1) — `x is List<T>` with `T` a type parameter of the
/// enclosing function that `x`'s type does not bind: `is-type-parameter`, as
/// the bare `x is T` is (667).
fn refuseUnboundTypeArgument(env: *Env, tested: ast.TypeRef, loc: ast.Loc) InferError!void {
    if (tested != .generic or tested.unionMembers() != null) return;
    for (tested.generic.args) |a| try refuseIsTypeParameterIn(env, a, tested, loc);
}

/// Decision 757 — a call of an ordinary function or method (one with a body:
/// no decorator, no template) that passes a type to a `comptime t: type<T>`
/// parameter: the arguments' positions and the names they write (a type, or
/// a `comptime t: type<T>` parameter of the body the call sits in, handed
/// on), recorded under the call's loc for `type_token.zig`, which drops them
/// from the call and calls the copy of the callee specialised for those
/// types. A type token never reaches run time.
fn noteTypeTokenArgs(env: *Env, c: ast.CallExprOf(.untyped), typed: TypedExpr) InferError!void {
    if (c.kind != .call) return;
    const call = c.kind.call;
    var owner: ?[]const u8 = null;
    const params: []const ast.Param = typeTokenCalleeParams(env, call, typed, &owner) orelse &.{};
    var at: std.ArrayListUnmanaged(usize) = .empty;
    var names: std.ArrayListUnmanaged([]const u8) = .empty;
    for (call.args, 0..) |arg, i| {
        const handed = typeTokenHandOn(env, arg.value.*);
        // Decision 758 — a type written where a run-time token is taken
        // crosses to run time as the type's identity (`__bp_type_token`).
        if (arg.label == null and i < params.len and runtimeTokenParam(params, params[i].name) != null) {
            if (arg.value.* == .identifier and arg.value.identifier.kind == .ident) {
                const n = arg.value.identifier.kind.ident;
                if (runtimeTokenParam(env.bodyParams, n) == null and (isPrimitiveTypeName(n) or env.lookupTypeDef(importedTypeAliasTarget(env, n) orelse n) != null))
                    try env.runtimeTokenArgs.put(env.arena, arg.value.getLoc(), {});
            }
            continue;
        }
        const isToken = arg.label == null and i < params.len and typeTokenParam(params, params[i].name) != null;
        if (!isToken) {
            // A type token is a type at build: only another call's token
            // takes it.
            if (handed) |n| {
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is a type, handed on only to a `comptime t: type<T>` parameter", .{ diagnostics.expr_value_of_type, n });
                env.lastError = TypeError.custom(msg, "A `comptime t: type<T>` parameter is the type its copy of the function is specialised for (decision 757): test with `v is t`, or hand it to another `comptime` type parameter.").withLoc(arg.value.getLoc());
                return error.TypeError;
            }
            continue;
        }
        const written: []const u8 = handed orelse switch (arg.value.*) {
            .identifier => |id| switch (id.kind) {
                .ident => |n| n,
                else => continue,
            },
            else => continue,
        };
        try at.append(env.arena, i);
        try names.append(env.arena, written);
    }
    if (at.items.len == 0) return;
    try env.typeTokenCalls.put(env.arena, c.loc, .{
        .at = try at.toOwnedSlice(env.arena),
        .names = try names.toOwnedSlice(env.arena),
        .owner = owner,
    });
}

/// The parameters (after `self`) of the ordinary function or method `call`
/// calls when it takes type tokens, its owner type in `owner` for a method;
/// null for any other callee.
fn typeTokenCalleeParams(env: *Env, call: anytype, typed: TypedExpr, owner: *?[]const u8) ?[]const ast.Param {
    if (call.is_builtin or call.args.len == 0) return null;
    if (call.receiver) |recv| {
        if (recv.* == .identifier and recv.identifier.kind == .ident and env.namespaces.paths.contains(recv.identifier.kind.ident)) {
            const key = std.fmt.allocPrint(env.arena, "{s}.{s}", .{ recv.identifier.kind.ident, call.callee }) catch return null;
            const f = env.importedFnDecls.get(key) orelse return null;
            if (!isTypeTokenCallee(f)) return null;
            return f.params;
        }
        // A std module's function through its namespace, `async.failed(…)`.
        if (recv.* == .identifier and recv.identifier.kind == .ident) if (env.stdImports.get(recv.identifier.kind.ident)) |key| {
            const fns = env.stdModuleFns.get(key) orelse return null;
            for (fns) |f| if (f.isPub and std.mem.eql(u8, f.name, call.callee)) {
                if (!isTypeTokenCallee(f)) return null;
                return f.params;
            };
            return null;
        };
        if (typed != .call or typed.call.kind != .call) return null;
        const recvTyped = typed.call.kind.call.receiver orelse return null;
        const tn = nominalName(recvTyped.getType().deref()) orelse return null;
        const m = env.getInherentMethodDecl(tn, call.callee) orelse return null;
        if (m.body == null) return null;
        owner.* = tn;
        return if (m.params.len > 0 and std.mem.eql(u8, m.params[0].name, "self")) m.params[1..] else m.params;
    }
    const f = env.fnDecls.get(call.callee) orelse env.importedFnDecls.get(call.callee) orelse {
        if (env.localBindDepth(call.callee) != null) return null;
        return if (recordTokenCallee(env, call.callee)) |rc| rc.params else null;
    };
    if (!isTypeTokenCallee(f)) return null;
    return f.params;
}

/// The parameters (after `self`) and the own type parameters of the function
/// or type method a call names, for `typeTokenArgType`.
const TokenCallee = struct {
    params: []const ast.Param,
    generics: []const ast.GenericParam,
    /// A record constructor's own type parameters, by name.
    genericNames: []const []const u8 = &.{},
};

/// Decision 631 — a record constructor whose field takes a run-time type
/// (`Type.Field<T>(owner: type<T>, …)`): its fields as parameters and its
/// own type parameters, so a type written where the field takes it is typed
/// as the type (`typeTokenArgType`) and crosses to run time as its identity
/// (`noteTypeTokenArgs`).
fn recordTokenCallee(env: *Env, callee: []const u8) ?TokenCallee {
    const ps = env.ctorParams.get(callee) orelse return null;
    const td = env.lookupTypeDef(callee) orelse return null;
    const generics = switch (td) {
        .record => |r| r.genericParams,
        .struct_ => |r| r.genericParams,
        .enum_ => return null,
    };
    for (ps) |p| if (p.modifier != .@"comptime" and p.typeRef == .typeparam) return .{ .params = ps, .generics = &.{}, .genericNames = generics };
    return null;
}

/// The callee of `call` as written — a function of this module or an imported
/// one, one through a module namespace or std's, or a type method of the
/// receiver's nominal type — or null.
fn tokenCallee(env: *Env, call: anytype, typedReceiver: ?*ast.TypedExpr) ?TokenCallee {
    if (call.is_builtin or call.calleeExpr != null or call.args.len == 0) return null;
    if (call.receiver) |recv| {
        if (recv.* == .identifier and recv.identifier.kind == .ident) {
            const rn = recv.identifier.kind.ident;
            if (env.namespaces.paths.contains(rn)) {
                const key = std.fmt.allocPrint(env.arena, "{s}.{s}", .{ rn, call.callee }) catch return null;
                const f = env.importedFnDecls.get(key) orelse return null;
                return .{ .params = f.params, .generics = f.genericParams };
            }
            if (env.stdImports.get(rn)) |key| {
                const fns = env.stdModuleFns.get(key) orelse return null;
                for (fns) |f| if (f.isPub and std.mem.eql(u8, f.name, call.callee))
                    return .{ .params = f.params, .generics = f.genericParams };
                return null;
            }
        }
        const tr = typedReceiver orelse return null;
        const tn = nominalName(tr.getType()) orelse return null;
        const m = env.getInherentMethodDecl(tn, call.callee) orelse return null;
        const ps = if (m.params.len > 0 and std.mem.eql(u8, m.params[0].name, "self")) m.params[1..] else m.params;
        return .{ .params = ps, .generics = m.genericParams };
    }
    if (env.localBindDepth(call.callee) != null) return null;
    const f = env.fnDecls.get(call.callee) orelse env.importedFnDecls.get(call.callee) orelse return recordTokenCallee(env, call.callee);
    return .{ .params = f.params, .generics = f.genericParams };
}

/// Decisions 668, 757, 758 — the type a call argument stands for when it
/// writes a type (a primitive, a declared or an imported type) where a
/// `type<T>` parameter, `T` the callee's own type parameter, takes it — with
/// or without `comptime`. The argument is typed as that type, so unifying it
/// with the parameter binds `T` to the type, never to the type's constructor
/// function (`type mismatch: expected Row, got function`). Null for any other
/// argument.
fn typeTokenArgType(env: *Env, callee: TokenCallee, pi: usize, arg: ast.Expr) InferError!?*T.Type {
    if (pi >= callee.params.len) return null;
    const p = callee.params[pi];
    if (p.typeRef != .typeparam or p.typeRef.typeparam.len != 1 or p.typeRef.typeparam[0] != .named) return null;
    const tp = p.typeRef.typeparam[0].named;
    const own = for (callee.generics) |g| {
        if (std.mem.eql(u8, g.name, tp)) break true;
    } else for (callee.genericNames) |g| {
        if (std.mem.eql(u8, g, tp)) break true;
    } else false;
    if (!own) return null;
    if (arg != .identifier or arg.identifier.kind != .ident) return null;
    const n = arg.identifier.kind.ident;
    if (env.localBindDepth(n) != null) return null;
    if (isPrimitiveTypeName(n)) return try env.namedType(n);
    const real = importedTypeAliasTarget(env, n) orelse n;
    if (env.lookupTypeDef(real) == null) return null;
    return try resolveTypeRef(env, .{ .named = real });
}

/// `t.value` — the parser's read of a `comptime` parameter — where `t` is a
/// `comptime t: type<T>` parameter of the body being inferred: its name.
fn typeTokenHandOn(env: *const Env, e: ast.Expr) ?[]const u8 {
    if (e != .identifier or e.identifier.kind != .identAccess) return null;
    const ia = e.identifier.kind.identAccess;
    if (!std.mem.eql(u8, ia.member, "value")) return null;
    if (ia.receiver.* != .identifier or ia.receiver.identifier.kind != .ident) return null;
    const n = ia.receiver.identifier.kind.ident;
    _ = typeTokenParam(env.bodyParams, n) orelse return null;
    return n;
}

/// Decision 757 — each argument of `c` that hands on a type token of the
/// body (`self.count(t)`): its read is the type, not refused as an `@Expr`'s
/// value (`refuseExprValueRead`); `noteTypeTokenArgs` checks that a token
/// takes it.
fn noteTypeTokenHandOns(env: *Env, c: ast.CallExprOf(.untyped)) InferError!void {
    if (c.kind != .call) return;
    for (c.kind.call.args) |a| if (typeTokenHandOn(env, a.value.*) != null)
        try env.typeTokenHandOns.put(env.arena, a.value.getLoc(), {});
}

/// Whether `f` is an ordinary function whose `comptime t: type<T>` parameters
/// specialise it (decision 757): it has a body, and is neither a decorator nor
/// a template.
fn isTypeTokenCallee(f: ast.FnDecl) bool {
    if (f.body.len == 0) return false;
    if (memberFn.declParamName(f) != null) return false;
    if (f.returnType) |rt| if (rt.isTemplateReturnType()) return false;
    for (f.params) |p| if (p.arrival == .syntax) return false;
    return true;
}

fn checkIsTestableType(env: *Env, ref: ast.TypeRef, loc: ast.Loc) InferError!void {
    switch (ref) {
        .generic => |g| {
            if (ref.unionMembers()) |members| {
                for (members) |m| try checkIsTestableType(env, m, loc);
                return;
            }
            for (g.args) |arg| {
                const isUnknownArg = arg == .named and
                    std.mem.eql(u8, arg.named, ast.unknown_type_name);
                if (isUnknownArg) continue;
                var e = TypeError.custom(
                    try std.fmt.allocPrint(
                        env.arena,
                        "`is` cannot test the type argument of `{s}`",
                        .{g.name},
                    ),
                    "A run-time test sees the type, not what is inside it. Write the argument as `unknown` (`Box<unknown>`) and narrow the contents separately.",
                );
                env.lastError = e.withLoc(loc);
                return error.TypeError;
            }
        },
        else => {},
    }
}

/// Decision 8 §4.3 — `a is string` on a value statically known to be an `i32`
/// is always false: a **warning** (decision 57's channel), and the program
/// still checks. "Statically known" is a value whose type is one concrete
/// head — a primitive, or a `type` the module declares — with no possibility
/// set behind it: `unknown`, a union, an optional, a behavior and an
/// unresolved variable are exactly the values `is` exists to test, and are
/// left alone. Numbers are tested by range, not by origin (§4.1): `2.0 is i32`
/// can be true, so a number tested against another number type never warns.
fn warnAlwaysFalseIs(env: *Env, valueType: *T.Type, tested: ast.TypeRef, loc: ast.Loc) InferError!void {
    const v = valueType.deref();
    if (v.* != .named) return;
    const vname = v.named.name;
    const eq = std.mem.eql;
    if (eq(u8, vname, ast.unknown_type_name) or eq(u8, vname, "optional")) return;
    const v_scalar = for (scalar_type_names) |n| {
        if (eq(u8, n, vname)) break true;
    } else false;
    if (!v_scalar) {
        const td = env.lookupTypeDef(vname) orelse return;
        _ = td;
    }
    const tname: []const u8 = switch (tested) {
        .named => |n| n,
        .generic => |g| if (tested.unionMembers() != null) return else g.name,
        .array => "array",
        .optional => return,
        else => return,
    };
    // A dotted name (`Token.Text`, a variant or a section) tests inside the
    // value's own type; `unknown` is always true.
    if (std.mem.indexOfScalar(u8, tname, '.') != null) return;
    if (eq(u8, tname, ast.unknown_type_name)) return;
    if (eq(u8, tname, vname)) return;
    const numeric = struct {
        fn of(n: []const u8) bool {
            const nums = [_][]const u8{ "i8", "u8", "i16", "u16", "i32", "u32", "i64", "u64", "isize", "usize", "f32", "f64" };
            for (nums) |x| if (std.mem.eql(u8, x, n)) return true;
            return false;
        }
    }.of;
    if (numeric(vname) and numeric(tname)) return;
    // A tested name the module knows nothing about is the unknown-name
    // diagnostic's business, not this one's.
    const t_known = numeric(tname) or env.lookupTypeDef(tname) != null or
        eq(u8, tname, "string") or eq(u8, tname, "bool") or eq(u8, tname, "array");
    if (!t_known) return;
    const rendered = try snapshotMod.typeNameOf(env.arena, v);
    const msg = try std.fmt.allocPrint(env.arena, "this `is {s}` test is always false: the value's type is `{s}`", .{ tname, rendered });
    try env.warn(TypeError.custom(msg, "The value's type is known here, so the test can never succeed. Test a value whose type is `unknown` or a union, or delete the test.").withLoc(loc));
}

/// Decision 8 §4 — the narrowing an `if` condition records: the name it tested
/// and the type it tested it for. Null when the condition is not one of the
/// forms that narrow.
const IsNarrowing = struct { name: []const u8, ref: ast.TypeRef };

/// `x is T` where `x` is a plain name. Only a name can be narrowed: narrowing
/// rebinds it for the branch, and there is nothing to rebind for `f().x`.
fn isNarrowingOf(cond: ast.Expr) ?IsNarrowing {
    if (cond != .call) return null;
    const c = cond.call.kind;
    if (c != .call) return null;
    const cc = c.call;
    if (!cc.is_builtin or !std.mem.eql(u8, cc.callee, ast.is_builtin_name)) return null;
    const tested = cc.isType orelse return null;
    if (cc.args.len != 1) return null;
    const arg = cc.args[0].value.*;
    if (arg != .identifier or arg.identifier.kind != .ident) return null;
    return .{ .name = arg.identifier.kind.ident, .ref = tested };
}

/// Decision 8 §4, as the null test extends it — one name a condition narrows,
/// and the type it takes on each SIDE of that condition. `then_` is the type
/// the name has where the condition held, `else_` the type it has where it did
/// not; either may be null, which means "that side leaves the name's own type
/// alone". `x is T` fills `then_` only; `x != null` fills `then_`, `x == null`
/// fills `else_`, and that symmetry is the whole of the negative form.
const CondNarrowing = struct {
    name: []const u8,
    then_: ?*T.Type = null,
    else_: ?*T.Type = null,
    /// Decision 810 (2) — the narrowing is an `is` test's over a union, which
    /// narrows a `var` too until it is assigned (the null test narrows a
    /// `val` alone after an early exit).
    fromIs: bool = false,
};

/// The payload of a `?T`, or null for every other type — an unresolved type
/// VARIABLE included, because an inference gap must not narrow a name to a
/// guess. `optional` is the named type the parser lands `?T` as.
fn optionalPayloadOf(ty: *T.Type) ?*T.Type {
    const t = ty.deref();
    if (t.* != .named) return null;
    const n = t.named;
    if (!std.mem.eql(u8, n.name, "optional") or n.args.len != 1) return null;
    return n.args[0];
}

/// The name of a plain identifier expression, or null. Only a NAME narrows,
/// for the same reason `x is T` only narrows one: narrowing is a rebinding,
/// and there is nothing to rebind for `o.inner` or `f().x`.
fn plainIdentName(expr: ast.Expr) ?[]const u8 {
    if (expr != .identifier or expr.identifier.kind != .ident) return null;
    return expr.identifier.kind.ident;
}

fn isNullLiteral(expr: ast.Expr) bool {
    return expr == .literal and expr.literal.kind == .null_;
}

/// `x != null` / `x == null`, in either operand order. `present_when_true` says
/// which side of the test holds the value.
fn nullTestOf(cond: ast.Expr) ?struct { name: []const u8, present_when_true: bool } {
    if (cond != .binaryOp) return null;
    const b = cond.binaryOp;
    const present = switch (b.op) {
        .ne => true,
        .eq => false,
        else => return null,
    };
    const name = if (isNullLiteral(b.rhs.*))
        plainIdentName(b.lhs.*)
    else if (isNullLiteral(b.lhs.*))
        plainIdentName(b.rhs.*)
    else
        null;
    return .{ .name = name orelse return null, .present_when_true = present };
}

/// Every name a condition narrows, appended to `out`. The null test is the leaf
/// (`x != null`, `x == null`); `&&`, `||` and `not` combine leaves, and each
/// combines exactly one side:
///
///   * `a && b` HOLDS only when both hold, so the then side keeps both halves'
///     narrowings. Its failure says nothing — either half may be the one that
///     failed — so the else side of an `&&` narrows nothing.
///   * `a || b` FAILS only when both fail: the mirror, and the shape a library
///     writes as `if (a == null || b == null) { return …; }`.
///   * `not a` swaps the two sides.
///
/// A name whose type is not an optional is skipped rather than refused: `x !=
/// null` on a non-optional is a comparison this function has no opinion about.
fn collectCondNarrowings(
    env: *Env,
    cond: ast.Expr,
    out: *std.ArrayListUnmanaged(CondNarrowing),
) InferError!void {
    // Only the narrowings THIS call appends may be rewritten by the combinator
    // below it: `a && (b || c)` must not let the `||` clear `a`'s half.
    const start = out.items.len;
    switch (cond) {
        .binaryOp => |b| switch (b.op) {
            .@"and", .@"or" => {
                try collectCondNarrowings(env, b.lhs.*, out);
                try collectCondNarrowings(env, b.rhs.*, out);
                for (out.items[start..]) |*n| {
                    if (b.op == .@"and") n.else_ = null else n.then_ = null;
                }
            },
            .eq, .ne => {
                const test_ = nullTestOf(cond) orelse return;
                const bound = env.lookup(test_.name) orelse return;
                const inner = optionalPayloadOf(bound) orelse return;
                try out.append(env.arena, if (test_.present_when_true)
                    .{ .name = test_.name, .then_ = inner }
                else
                    .{ .name = test_.name, .else_ = inner });
            },
            else => {},
        },
        // Decision 810 (2) — `x is A` over a union: where it failed, `x` is
        // the union without `A` (the member it tested); the branch where it
        // held is narrowed by `isNarrowingOf`'s channel.
        .call => {
            const n = isNarrowingOf(cond) orelse return;
            const bound = env.lookup(n.name) orelse return;
            const b = bound.deref();
            if (b.* != .union_) return;
            const tested = resolveTypeRef(env, typeTokenRef(env, n.ref) orelse runtimeTokenRef(env, n.ref) orelse n.ref) catch return;
            var rest: std.ArrayListUnmanaged(*T.Type) = .empty;
            for (b.union_) |m| if (!memberTestedBy(m, tested)) try rest.append(env.arena, m);
            if (rest.items.len == 0 or rest.items.len == b.union_.len) return;
            const else_ = if (rest.items.len == 1) rest.items[0] else try env.unionType(try rest.toOwnedSlice(env.arena));
            try out.append(env.arena, .{ .name = n.name, .else_ = else_, .fromIs = true });
        },
        .unaryOp => |u| {
            if (u.op != .not) return;
            try collectCondNarrowings(env, u.expr.*, out);
            for (out.items[start..]) |*n| {
                const held = n.then_;
                n.then_ = n.else_;
                n.else_ = held;
            }
        },
        else => {},
    }
}

/// Decision 810 (2) — whether `x is tested` holding means `x` is the union
/// member `m`: the same named type (its arguments are `x`'s own, 810 (1)), or a
/// function type of the same shape. `unknown` tests every member.
fn memberTestedBy(m: *T.Type, tested: *T.Type) bool {
    const dm = m.deref();
    const dt = tested.deref();
    if (unifyMod.isUnknown(dt)) return true;
    return switch (dm.*) {
        .named => |nm| dt.* == .named and std.mem.eql(u8, nm.name, dt.named.name),
        .func => dt.* == .func and sameTypeWritten(dm, dt),
        else => false,
    };
}

/// Decision 810 (1), (2) — the member of a union-typed `x` that `x is tested`
/// narrows it to inside the branch: the member itself, its arguments from
/// `x`'s type. Null when `x`'s type is no union or no member is the one.
fn testedUnionMember(env: *Env, name: []const u8, tested: *T.Type) ?*T.Type {
    const bound = env.lookup(name) orelse return null;
    const b = bound.deref();
    if (b.* != .union_) return null;
    var found: ?*T.Type = null;
    for (b.union_) |m| if (memberTestedBy(m, tested)) {
        if (found != null) return null;
        found = m;
    };
    return found;
}

/// Rebind `name` to its narrowed type for one branch, remembering what it was.
/// A `val` stays a `val`: `env.bind` drops the marker decision 38 reads, and a
/// narrowed name is still the same binding, not a new assignable one.
fn bindNarrowed(
    env: *Env,
    name: []const u8,
    ty: *T.Type,
    snapshots: *std.ArrayListUnmanaged(PatternBindingSnapshot),
) InferError!void {
    const wasVal = env.isVal(name);
    const previous = env.lookup(name);
    const prevDecl = env.narrowedDecl.get(name);
    try snapshots.append(env.arena, .{ .name = name, .previous = previous, .wasVal = wasVal, .narrowed = true, .prevDecl = prevDecl });
    if (wasVal) {
        try env.bindVal(name, ty);
    } else {
        // A `var` keeps the type it was declared with for its assignments.
        if (prevDecl orelse previous) |declared| try env.narrowedDecl.put(env.arena, name, declared);
        try env.bind(name, ty);
    }
}

/// A statement list that cannot fall through: its last statement is a `return`,
/// `throw`, `break` or `continue`. That is all the early-return shape needs —
/// a body ending any other way reaches the code below its `if`.
///
/// A call that never returns ends a branch too (maintainer, 24-box-1): a
/// builtin `@panic` / `@todo` / `@trap` / `@compilerError`, or any function
/// whose declared return is `noreturn` — a framework's `notFound()` and
/// `redirect(…)` — so `if (post == null) { notFound(); }` narrows `post` below.
fn stmtsAlwaysExit(env: *Env, stmts: []const ast.Stmt) bool {
    var n = stmts.len;
    while (n > 0) : (n -= 1) {
        const last = stmts[n - 1].expr;
        if (last == .literal and last.literal.kind == .comment) continue;
        if (last == .call and last.call.kind == .call) return callNeverReturns(env, last.call.kind.call);
        if (last != .jump) return false;
        return switch (last.jump.kind) {
            .@"return", .throw_, .@"break", .@"continue" => true,
            else => false,
        };
    }
    return false;
}

/// Whether a call's callee is declared `-> noreturn` (or is one of the
/// builtins that are).
fn callNeverReturns(env: *Env, cc: anytype) bool {
    if (cc.is_builtin) return builtinsMod.neverReturns(cc.callee);
    if (cc.receiver != null) return false;
    const ty = env.lookup(cc.callee) orelse return false;
    const d = ty.deref();
    return d.* == .func and d.func.ret.isNamed("noreturn");
}

/// The early-exit shape: `if (x == null) { return …; }` and then the REST of
/// the block, where `x` holds a value because the branch that did not left.
/// The narrowing outlives the `if`, so unlike the two branch shapes it is
/// applied by the statement walker and restored at the end of the block.
///
/// Only a `val` narrows here. A `var` may be assigned below the `if` — the
/// branch shapes restore before the next statement and never meet that, this
/// one would carry a type the name no longer has.
fn narrowAfterEarlyExit(
    env: *Env,
    stmt: ast.Expr,
    rest: []const ast.Stmt,
    snapshots: *std.ArrayListUnmanaged(PatternBindingSnapshot),
) InferError!void {
    if (stmt != .branch or stmt.branch.kind != .if_) return;
    const i = stmt.branch.kind.if_;
    if (i.binding != null or i.else_ != null) return;
    if (!stmtsAlwaysExit(env, i.then_)) return;
    var narrowings: std.ArrayListUnmanaged(CondNarrowing) = .empty;
    defer narrowings.deinit(env.arena);
    try collectCondNarrowings(env, i.cond.*, &narrowings);
    for (narrowings.items) |n| {
        const ty = n.else_ orelse continue;
        // Decision 810 (2) — an `is` test narrows a `var` too, until it is
        // assigned: an assignment written as a statement of the rest ends it
        // (`narrowedDecl`); one nested in a branch, a loop or a function
        // would leave the rest typed by a value it no longer holds, so such a
        // `var` is not narrowed.
        if (!env.isVal(n.name) and !(n.fromIs and !assignedNested(env, rest, n.name))) continue;
        try bindNarrowed(env, n.name, ty, snapshots);
    }
}

/// Whether `name` is assigned inside a nested construct of `rest` (a branch, a
/// loop, a function), anywhere but as one of `rest`'s own statements.
fn assignedNested(env: *Env, rest: []const ast.Stmt, name: []const u8) bool {
    for (rest) |s| {
        if (s.expr == .binding and s.expr.binding.kind == .assign) {
            const a = s.expr.binding.kind.assign;
            if (a.target == .name and std.mem.eql(u8, a.target.name, name)) {
                if (exprAssigns(env, a.value.*, name)) return true;
                continue;
            }
        }
        if (exprAssigns(env, s.expr, name)) return true;
    }
    return false;
}

fn exprAssigns(env: *Env, e: ast.Expr, name: []const u8) bool {
    var names: std.ArrayListUnmanaged([]const u8) = .empty;
    const one = [_]ast.Stmt{.{ .expr = e }};
    ast.collectAssignedNames(env.arena, &one, &names) catch return true;
    for (names.items) |n| if (std.mem.eql(u8, n, name)) return true;
    return false;
}

fn requireNumericOperand(env: *Env, ty: *T.Type, op: []const u8, loc: ast.Loc) InferError!void {
    const t = ty.deref();
    if (t.* != .named) return;
    // §2.2 — arithmetic is refused on `unknown` for its own reason, not as a
    // "takes numbers" mismatch: the value may well be a number, and what is
    // wrong is that nothing has established it.
    try refuseUnknownUse(env, ty, loc, "do arithmetic on");
    const n = t.named.name;
    const eq = std.mem.eql;
    if (!(eq(u8, n, "string") or eq(u8, n, "bool") or eq(u8, n, "void") or eq(u8, n, "array"))) return;
    var e = TypeError.custom(
        try std.fmt.allocPrint(env.arena, "`{s}` takes numbers, not `{s}`", .{ op, n }),
        "Arithmetic is defined on the integer and float types. `+` also concatenates strings; the other operators do not.",
    );
    env.lastError = e.withLoc(loc);
    return error.TypeError;
}

/// The named types that hold no variant at all: a variant pattern asserted
/// against one of them can never match. Every other unregistered name stays
/// permissive (a forward reference, or an imported type).
pub const scalar_type_names = [_][]const u8{
    "i8",       "u8",     "i16",   "u16", "i32",  "u32",    "i64",  "u64",
    "isize",    "usize",  "f32",   "f64", "bool", "string", "void", "v128",
    "noreturn", "bigint", "bytes",
};

/// Decision 8 § 9 — a `val assert` variant pattern must name a variant the
/// subject's type can actually hold. Permissive while the subject's type is
/// still an unresolved type variable (an inference gap must not red), and for
/// every non-variant pattern, whose shapes (`42`, `"hi"`, `[a, ..]`) the
/// backends test at run time.
fn checkAssertPatternSubject(
    env: *Env,
    pattern: ast.Pattern,
    subjectType: *T.Type,
    loc: ast.Loc,
    fatal: bool,
    catchLoc: ?ast.Loc,
) InferError!void {
    const name = switch (pattern) {
        // A path names its variant by its last segment (`Result.Error`).
        .variant => |v| bareVariantName(v.name),
        else => return,
    };
    const st = subjectType.deref();
    if (st.* != .named) return;
    const eq = std.mem.eql;
    const n = st.named;
    // Decision 8 § 9 — `val assert Ok(n) = parse("42") catch 0;` is an error:
    // `catch` is what turns a `@Result` into its success value, so a `@Result`
    // subject and a handler cannot both be written. The handler-less form is
    // the one that asserts a variant, and its failure is fatal.
    if (!fatal and eq(u8, n.name, "Result")) {
        var ce = TypeError.custom(
            "after `catch` the value is not a Result — a `val assert` over a `Result` takes no `catch`",
            "`catch` already yields the success value, so the pattern would be asserted against the unwrapped one. Write `val assert Ok(n) = parse(s);` — a failure is a fatal assert (decision 8 § 9).",
        );
        // 01 R9 — the caret is on the `catch` that makes it an error.
        env.lastError = ce.withLoc(catchLoc orelse loc);
        return error.TypeError;
    }
    const known = blk: {
        if (eq(u8, n.name, "Result")) break :blk eq(u8, name, "Ok") or eq(u8, name, "Err") or eq(u8, name, "Error");
        if (eq(u8, n.name, "optional")) break :blk eq(u8, name, "Some") or eq(u8, name, "None");
        if (env.lookupTypeDef(n.name)) |td| switch (td) {
            .enum_ => |en| {
                for (en.variants) |vd| {
                    if (eq(u8, vd.name, name)) break :blk true;
                }
                break :blk false;
            },
            // A record's own constructor is its only "variant"; a struct is
            // opened by name too.
            .record => break :blk eq(u8, n.name, name),
            .struct_ => break :blk eq(u8, n.name, name),
        };
        // No typedef: a primitive holds no variant at all, anything else is a
        // forward reference or an imported type C10 has yet to register — stay
        // permissive there.
        for (scalar_type_names) |p| {
            if (eq(u8, n.name, p)) break :blk false;
        }
        return;
    };
    if (known) return;
    var e = TypeError.custom(
        try std.fmt.allocPrint(env.arena, "`{s}` names no variant of `{s}`", .{ name, n.name }),
        "The pattern of a `val assert` has to be able to match its subject. After `catch` the value is the unwrapped one, so `val assert Ok(n) = parse(s) catch 0;` asserts `Ok(…)` against an `i32` — drop the `catch` (decision 8 § 9: a failure is a fatal assert).",
    );
    env.lastError = e.withLoc(loc);
    return error.TypeError;
}

/// Decision 54 — the `null` pattern. The parser lands it as `.ident` carrying
/// the keyword's own lexeme (`parser/patterns.zig`), so `null` is never a
/// binding: no source can spell a binder with that name, `null` being a keyword
/// token. This predicate is the only reader of that spelling.
fn isNullPattern(pattern: ast.Pattern) bool {
    return pattern == .ident and std.mem.eql(u8, pattern.ident, "null");
}

/// The `T` of a `?T`, or null when the type is not an optional.
fn optionalInner(ty: *T.Type) ?*T.Type {
    const d = ty.deref();
    if (d.* != .named) return null;
    if (!std.mem.eql(u8, d.named.name, "optional") or d.named.args.len != 1) return null;
    return d.named.args[0];
}

/// The name a pattern binds when it is the binder half of decision 54's `?T`
/// form: a plain lower-case name, or `""` for `_`. Null when the pattern is
/// anything else.
fn optionalBinderName(pattern: ast.Pattern) ?[]const u8 {
    return switch (pattern) {
        .wildcard => "",
        .ident => |n| if (isNullPattern(pattern) or std.mem.indexOfScalar(u8, n, '.') != null)
            null
        else
            n,
        else => null,
    };
}

/// Decision 54 — a `case` over a `?T` has exactly one spelling:
/// `case x { null { … } v { … } }`. This validates it and answers the binder's
/// name, or reds with a located diagnostic. Called only when an arm's pattern
/// is `null`; the arms are the untyped ones, since the shape is a property of
/// what was written.
///
/// Three things are refused here, and each names the form it wants:
///   * a `null` arm over a subject that is not an optional;
///   * a `case` over a `?T` whose arms are not exactly `null` then a binder
///     (a third arm, a guard, a reversed order, a payload pattern);
///   * the arms' bodies taking a parameter (`v { n -> … }`) — §5.1 P1's
///     whole-value binder means nothing here, where the binder is the payload.
fn optionalNullCaseBinder(
    env: *Env,
    subjectType: *T.Type,
    arms: []const ast.CaseArm,
    loc: ast.Loc,
) InferError!?[]const u8 {
    var nullArm: ?usize = null;
    for (arms, 0..) |arm, i| {
        if (isNullPattern(arm.pattern)) {
            nullArm = i;
            break;
        }
    }
    const nullIdx = nullArm orelse return null;

    if (optionalInner(subjectType) == null) {
        env.lastError = TypeError.custom(
            "`null` is a pattern only over an optional",
            "`case x { null { … } v { … } }` matches a `?T` (decision 54). This subject is not one.",
        ).withLoc(arms[nullIdx].patternLoc);
        return error.TypeError;
    }

    const shapeError = "an optional is matched by `null` and a binder, in that order";
    const shapeHint = "Decision 54: a `?T` has one pattern form — `case x { null { … } v { … } }`, two arms, no guards. `null` first, because a binder written first would match the absent value too.";

    if (arms.len != 2 or nullIdx != 0 or arms[0].guard != null or arms[1].guard != null) {
        env.lastError = TypeError.custom(shapeError, shapeHint).withLoc(loc);
        return error.TypeError;
    }
    const binder = optionalBinderName(arms[1].pattern) orelse {
        env.lastError = TypeError.custom(shapeError, shapeHint).withLoc(arms[1].patternLoc);
        return error.TypeError;
    };
    for (arms) |arm| {
        if (arm.body == .function and arm.body.function.kind.params.len > 0) {
            env.lastError = TypeError.custom(
                "an arm of a `?T` `case` takes no parameter",
                "The binder is the payload already: `case x { null { … } v { … } }` binds `v` to the value inside the optional.",
            ).withLoc(arm.body.getLoc());
            return error.TypeError;
        }
    }
    return binder;
}

/// Decision 54 — `.Some(v)` / `.None` over a `?T` is a **located error**. The
/// optional is not a variant: the checker still models `?T` as having `Some`
/// and `None` (`variantPayloadTypes`), which is why the spelling compiled and
/// then answered four different things on four backends. It is refused here,
/// at the arm, naming the form the language does have.
fn refuseVariantPatternOverOptional(
    env: *Env,
    subjectType: *T.Type,
    arms: []const ast.CaseArm,
) InferError!void {
    if (optionalInner(subjectType) == null) return;
    for (arms) |arm| {
        const isVariantShaped = switch (arm.pattern) {
            // A path is never a binder (§5.1 P8), and a bare `Some` / `None`
            // is the spelling the decision names: both are variant patterns
            // over a value that has no variants.
            .ident => |n| isVariantPath(n) or
                std.mem.eql(u8, n, "Some") or std.mem.eql(u8, n, "None"),
            // `.Some(v)`, `Option.Some(value: v)`, `Circle(r)` — a payload
            // pattern. `#(a, b)` and `1...9` ride the same node under `shape`
            // and are not variants, so they are left alone.
            .variant => |v| v.shape == .variant and v.name.len > 0,
            else => false,
        };
        if (!isVariantShaped) continue;
        env.lastError = TypeError.custom(
            "an optional is matched by `null`, not by a variant",
            "Decision 54: write `case x { null { … } v { … } }` — the shape `??` and `?.` already use. `Some` and `None` are not spellings this language has.",
        ).withLoc(arm.patternLoc);
        return error.TypeError;
    }
}

/// Decision 8 §5.1 P8 / §5.2 — a leading-dot variant (`.Some(v)`, `.None`)
/// takes its enum from the matched value's type. An `unknown` value has none,
/// so the shorthand names nothing and the arm must write the full name
/// (`Maybe.Some(v)`). Without this refusal the arm was accepted and tested
/// against whatever the flat variant table held under that name.
fn refuseShorthandOverUnknown(env: *Env, subjectType: *T.Type, arms: []const ast.CaseArm) InferError!void {
    if (!unifyMod.isUnknown(subjectType)) return;
    for (arms) |arm| {
        const written: []const u8 = switch (arm.pattern) {
            .ident => |n| n,
            .variant => |v| if (v.shape == .variant) v.name else continue,
            else => continue,
        };
        if (written.len < 2 or written[0] != '.') continue;
        env.lastError = TypeError.custom(
            try std.fmt.allocPrint(env.arena, "`{s}` on an `unknown` value names no enum — write the variant's full name", .{written}),
            "The leading-dot shorthand takes the enum from the matched value's type, and `unknown` has none: write `Type.Variant(…)` (decision 8 §5.2).",
        ).withLoc(arm.patternLoc);
        return error.TypeError;
    }
}

/// Decision 8 §5.1 P7 — without a trailing `..` a variant pattern names every
/// field of the variant. `.Rect(width: w)` over `Rect(width: i32, height: i32)`
/// is a missing field, not a shorthand: the fields it does not name would be
/// silently dropped, and `..` is the spelling that says "drop them".
///
/// Only a written variant payload is judged. A whole-payload binding (`Ok ok`)
/// stands for the payload entire, a tuple or range rides the same node under
/// `shape`, and a variant whose declaration is not resolvable is left alone.
fn checkCaseArmArity(
    env: *Env,
    subjectType: *T.Type,
    arms: []const ast.CaseArm,
) InferError!void {
    for (arms) |arm| {
        const v = switch (arm.pattern) {
            .variant => |vv| vv,
            else => continue,
        };
        if (v.shape != .variant or v.rest or v.name.len == 0) continue;
        const written: usize = switch (v.payload) {
            .fields => |f| f.len,
            .literals => |l| l.len,
            .binding => continue,
        };
        const declared = (try variantPayloadFieldNames(env, subjectType, v.name)) orelse continue;
        if (written >= declared.len) continue;
        env.lastError = TypeError
            .missingField(bareVariantName(v.name), declared[written])
            .withLoc(arm.patternLoc);
        return error.TypeError;
    }
}

/// The declared field names of `writtenName`'s variant on `subjectType`, or
/// null when the subject's type or the variant is not resolvable.
fn variantPayloadFieldNames(env: *Env, subjectType: *T.Type, writtenName: []const u8) InferError!?[]const []const u8 {
    const st = subjectType.deref();
    if (st.* != .named) return null;
    const td = env.lookupTypeDef(st.named.name) orelse return null;
    if (td != .enum_) return null;
    const variantName = bareVariantName(writtenName);
    for (td.enum_.variants) |vd| {
        if (!std.mem.eql(u8, vd.name, variantName)) continue;
        const out = try env.arena.alloc([]const u8, vd.fields.len);
        for (vd.fields, 0..) |f, i| out[i] = f.name;
        return out;
    }
    return null;
}

/// Record `pattern` at `at` when it is `Ok(…)` / `Err(…)` / `Error(…)` written
/// bare against a `@Result` subject (`Env.resultPatternLocs`). The name is the
/// `@Result` variant whatever else the module declares: a user enum with an
/// `Error` variant made erlang, beam and wasm test the subject for THAT
/// variant, and a `{error, E}` fell through every arm (`case_clause`, or no
/// arm at all at exit 0).
fn noteResultPattern(env: *Env, pattern: ast.Pattern, subjectType: *T.Type, at: ast.Loc) InferError!void {
    if (pattern != .variant) return;
    const name = pattern.variant.name;
    if (std.mem.indexOfScalar(u8, name, '.') != null) return;
    if (!std.mem.eql(u8, name, "Ok") and !std.mem.eql(u8, name, "Err") and !std.mem.eql(u8, name, "Error")) return;
    const st = subjectType.deref();
    if (st.* != .named or !std.mem.eql(u8, st.named.name, "Result")) return;
    if (at.line == 0) return;
    const prior = env.resultPatternLocs.get(at) orelse envMod.PatternNote{};
    try env.resultPatternLocs.put(env.arena, at, .{ .result = true, .resolved = prior.resolved });
}

/// B-154 — a bare name inside a nested pattern that is a nullary variant of the
/// matched sub-pattern's type is that variant (154's rule for expression
/// position, applied to patterns); it is a binder only when no variant of the
/// type has the name. The parser keeps a payload of plain names as `fields`,
/// where `Error(Timeout)` reads as a binder; a name that is a variant is
/// rewritten here to the leading-dot variant path every backend already
/// lowers as a variant test (`.Timeout`), the payload becoming `literals`.
fn resolveNestedVariants(env: *Env, pattern: ast.Pattern, subjectType: *T.Type) InferError!ast.Pattern {
    switch (pattern) {
        .variant => |v| {
            if (v.shape != .variant) return pattern;
            const payload = try variantPayloadTypes(env, subjectType, v.name) orelse return pattern;
            switch (v.payload) {
                .fields => |fields| {
                    if (payload.len != fields.len) return pattern;
                    var any = false;
                    for (fields, payload) |name, ty| {
                        if (isNullaryVariantOfType(env, ty, name)) any = true;
                    }
                    if (!any) return pattern;
                    const args = try env.arena.alloc(ast.Pattern, fields.len);
                    for (fields, payload, args) |name, ty, *out| {
                        out.* = if (isNullaryVariantOfType(env, ty, name))
                            .{ .ident = try std.fmt.allocPrint(env.arena, ".{s}", .{name}) }
                        else
                            .{ .ident = name };
                    }
                    var out = v;
                    out.payload = .{ .literals = args };
                    return .{ .variant = out };
                },
                .literals => |args| {
                    if (payload.len != args.len) return pattern;
                    var changed = false;
                    const next = try env.arena.alloc(ast.Pattern, args.len);
                    for (args, payload, next) |arg, ty, *out| {
                        out.* = switch (arg) {
                            .ident => |name| if (isNullaryVariantOfType(env, ty, name))
                                ast.Pattern{ .ident = try std.fmt.allocPrint(env.arena, ".{s}", .{name}) }
                            else
                                arg,
                            else => try resolveNestedVariants(env, arg, ty),
                        };
                        if (!std.meta.eql(out.*, arg)) changed = true;
                    }
                    if (!changed) return pattern;
                    var out = v;
                    out.payload = .{ .literals = next };
                    return .{ .variant = out };
                },
                .binding => return pattern,
            }
        },
        .@"or" => |alts| {
            const next = try env.arena.alloc(ast.Pattern, alts.len);
            for (alts, next) |alt, *out| out.* = try resolveNestedVariants(env, alt, subjectType);
            return .{ .@"or" = next };
        },
        else => return pattern,
    }
}

/// True when `name` (bare, no path) is a variant of the enum `ty` names that
/// carries no payload.
fn isNullaryVariantOfType(env: *Env, ty: *T.Type, name: []const u8) bool {
    if (std.mem.indexOfScalar(u8, name, '.') != null) return false;
    const t = ty.deref();
    if (t.* != .named) return false;
    const td = env.lookupTypeDef(t.named.name) orelse return false;
    if (td != .enum_) return false;
    for (td.enum_.variants) |vd| {
        if (std.mem.eql(u8, vd.name, name)) return vd.fields.len == 0;
    }
    return false;
}

/// Record the arm's pattern with its nested bare variant names resolved
/// (`resolveNestedVariants`) when that changes it, for the transform to put
/// in the arm's place.
fn noteResolvedPattern(env: *Env, pattern: ast.Pattern, subjectType: *T.Type, at: ast.Loc) InferError!void {
    if (at.line == 0) return;
    const resolved = try resolveNestedVariants(env, pattern, subjectType);
    if (std.meta.eql(resolved, pattern)) return;
    const prior = env.resultPatternLocs.get(at) orelse envMod.PatternNote{};
    try env.resultPatternLocs.put(env.arena, at, .{ .result = prior.result, .resolved = resolved });
}

fn bindCaseArmPatternNames(
    env: *Env,
    pattern: ast.Pattern,
    typedSubjects: []const ast.TypedExpr,
    snapshots: *std.ArrayListUnmanaged(PatternBindingSnapshot),
) InferError!void {
    if (pattern == .multi) {
        const patterns = pattern.multi;
        for (patterns, 0..) |p, i| {
            const subjectTy = if (i < typedSubjects.len) typedSubjects[i].getType() else try env.freshVar();
            try bindPatternNamesForSubject(env, p, subjectTy, snapshots);
        }
        return;
    }
    const subjectTy = if (typedSubjects.len > 0) typedSubjects[0].getType() else try env.freshVar();
    try bindPatternNamesForSubject(env, pattern, subjectTy, snapshots);
}

fn namesContain(list: []const []const u8, name: []const u8) bool {
    for (list) |n| {
        if (std.mem.eql(u8, n, name)) return true;
    }
    return false;
}

/// True when `pattern`, as a top-level case arm, binds the whole subject and so
/// matches any value of an enum/string domain — i.e. it is a catch-all. A `_`
/// wildcard, or an identifier that is NOT one of the subject enum's variant
/// names, both bind unconditionally. An OR pattern is a catch-all if any
/// alternative is.
fn patternIsCatchAll(env: *Env, pattern: ast.Pattern, subjectType: *T.Type) bool {
    return switch (pattern) {
        .wildcard => true,
        // §5.1 P8 — a name carrying a `.` is a variant path and never a binder,
        // so it is never a catch-all even when it names no variant of the
        // subject (that case is a mistake the coverage walk reports).
        //
        // §5.2 / §5.4 — nor is a **type pattern**. `i32 { n -> … }` tests the
        // value; whether it happens to cover the subject whole is the coverage
        // walk's question (`caseSubjectDomain`), not a catch-all's.
        .ident => |name| !isVariantPath(name) and
            !isEnumVariantNameForSubject(env, subjectType, name) and
            typePatternName(env, pattern, subjectType) == null,
        .@"or" => |pats| blk: {
            for (pats) |p| {
                if (patternIsCatchAll(env, p, subjectType)) break :blk true;
            }
            break :blk false;
        },
        else => false,
    };
}

/// True when a variant pattern's payload matches *every* value of that variant,
/// so the variant is fully covered. Refined payloads like `Ok(1)` do not; a
/// payload of only bindings / wildcards (e.g. `Err(_)`, `Rgb(r, g, b)`) does.
/// Decision 8 §5.1 — does this pattern match **every** value of its type?
///
/// A binder and a `_` do; a literal, a range, a list and a variant path do not
/// (each selects some values and not others). A tuple pattern (§5.1 P6) matches
/// every tuple when each of its elements does — which is what
/// `.Some(#(a, b))` needs: the payload is one tuple pattern, all binders, so
/// the `Some` variant is fully covered. The `.literals` walk used to answer
/// `false` for every nested pattern, so an enum matched that way read as
/// uncovered ("missing variant(s) Some").
///
/// `elemType` is the type the pattern is matched against, when it is known: an
/// `.ident` is a binder unless it names a variant of that type, which is how a
/// section refinement (`Text(Bold)`) is told from a binding (N28).
fn patternIsIrrefutable(env: *Env, pattern: ast.Pattern, elemType: ?*T.Type) InferError!bool {
    return switch (pattern) {
        .wildcard => true,
        .ident => |nm| blk: {
            if (isVariantPath(nm)) break :blk false;
            // `null`, `true` and `false` are literals, not binders: each
            // selects some values and not others.
            if (isLiteralKeyword(nm)) break :blk false;
            const ty = elemType orelse break :blk true;
            break :blk !isEnumVariantNameForSubject(env, ty, nm);
        },
        .variant => |v| switch (v.shape) {
            // `#(a, b)` / `#(a, ..)` — every tuple of the right shape matches
            // when each element pattern does. `..` drops the rest, which is
            // exactly what makes the remainder irrefutable (P7).
            .tuple => blk: {
                const elemTypes: ?[]*T.Type = if (elemType) |t| tupleElementTypes(t) else null;
                switch (v.payload) {
                    .literals => |args| {
                        for (args, 0..) |a, i| {
                            const at: ?*T.Type = if (elemTypes != null and i < elemTypes.?.len)
                                elemTypes.?[i]
                            else
                                null;
                            if (!try patternIsIrrefutable(env, a, at)) break :blk false;
                        }
                        break :blk true;
                    },
                    // A whole-payload binder or a field list over a tuple binds
                    // names and tests nothing.
                    .binding, .fields => break :blk true,
                }
            },
            // A variant path selects one variant; a range selects an interval.
            .variant, .range => false,
        },
        .numberLit, .stringLit, .list => false,
        // An OR is irrefutable only if some alternative is, and an alternative
        // that is makes the others unreachable — the reachability walk reports
        // that separately, so answering on the whole is enough here.
        .@"or" => |pats| blk: {
            for (pats) |alt| {
                if (try patternIsIrrefutable(env, alt, elemType)) break :blk true;
            }
            break :blk false;
        },
        .multi => false,
    };
}

/// The element types of a tuple type, or null when the type is not a tuple (or
/// is not known yet).
fn tupleElementTypes(ty: *T.Type) ?[]*T.Type {
    const d = ty.deref();
    if (d.* != .named or !std.mem.eql(u8, d.named.name, "tuple")) return null;
    return d.named.args;
}

/// `null`, `true` and `false` written as a pattern name: literals the parser
/// keeps as plain identifiers, never binders.
fn isLiteralKeyword(name: []const u8) bool {
    return std.mem.eql(u8, name, "null") or std.mem.eql(u8, name, "true") or std.mem.eql(u8, name, "false");
}

/// The record type a constructor pattern (`Dog(name: n, breed: b)`) tests when
/// it matches every value of that record: a `.variant` pattern whose bare name
/// is a known type and not a variant of the subject, with a payload of binders
/// only. A payload that carries a literal makes the arm partial (null).
fn fullConstructorPatternType(env: *Env, pattern: ast.Pattern, subjectType: *T.Type) InferError!?*T.Type {
    const v = switch (pattern) {
        .variant => |v| v,
        else => return null,
    };
    if (v.shape != .variant) return null;
    if (isVariantPath(v.name)) return null;
    if (isEnumVariantNameForSubject(env, subjectType, v.name)) return null;
    if (!isKnownTypeName(env, v.name)) return null;
    switch (v.payload) {
        .binding, .fields => {},
        .literals => |args| for (args) |a| {
            if (!try patternIsIrrefutable(env, a, null)) return null;
        },
    }
    return try env.namedType(v.name);
}

fn variantPayloadIrrefutable(
    env: *Env,
    subjectType: *T.Type,
    variantName: []const u8,
    payload: anytype,
) InferError!bool {
    return switch (payload) {
        // A single-name payload (`Text(Bold)`) is a binder unless the name is a
        // variant of the payload's own type — inside a section wrapper it is a
        // refinement, not a binding.
        .binding => |name| blk: {
            const payloadTypes = try variantPayloadTypes(env, subjectType, variantName);
            if (payloadTypes) |p| {
                if (p.len == 1 and isEnumVariantNameForSubject(env, p[0], name)) break :blk false;
            }
            break :blk true;
        },
        .fields => |names| blk: {
            const payloadTypes = try variantPayloadTypes(env, subjectType, variantName);
            if (payloadTypes) |p| {
                for (names, 0..) |name, i| {
                    if (i < p.len and isEnumVariantNameForSubject(env, p[i], name)) break :blk false;
                }
            }
            break :blk true;
        },
        .literals => |args| blk: {
            // N28 — an `.ident` arg is a binder (`Ok(v)`, irrefutable) *unless*
            // it names a variant of the payload's own type, as it does inside a
            // section wrapper (`Text(Bold)`). That match refines the section,
            // so the wrapper variant stays open: counting it as full coverage
            // would let a `case` skip the section's other variants in silence
            // (decision 8 §5.4).
            const payloadTypes = try variantPayloadTypes(env, subjectType, variantName);
            for (args, 0..) |a, i| {
                const argTy: ?*T.Type = if (payloadTypes != null and i < payloadTypes.?.len)
                    payloadTypes.?[i]
                else
                    null;
                if (!try patternIsIrrefutable(env, a, argTy)) break :blk false;
            }
            break :blk true;
        },
    };
}

/// Append to `covered` every enum variant that `pattern` *fully* covers (an
/// irrefutable variant match). Refined matches (`Ok(1)`) are skipped so the
/// variant stays "open".
fn collectFullyCoveredVariants(
    env: *Env,
    pattern: ast.Pattern,
    subjectType: *T.Type,
    covered: *std.ArrayListUnmanaged([]const u8),
) InferError!void {
    switch (pattern) {
        .ident => |name| {
            const bare = bareVariantName(name);
            if (isEnumVariantNameForSubject(env, subjectType, name) and !namesContain(covered.items, bare)) {
                try covered.append(env.arena, bare);
            }
        },
        .variant => |v| {
            const bare = bareVariantName(v.name);
            if (try variantPayloadIrrefutable(env, subjectType, v.name, v.payload) and !namesContain(covered.items, bare)) {
                try covered.append(env.arena, bare);
            }
        },
        .@"or" => |pats| {
            for (pats) |p| try collectFullyCoveredVariants(env, p, subjectType, covered);
        },
        else => {},
    }
}

/// The payload of a variant pattern as one pattern per field, positional, or
/// null when the written payload cannot be read that way (labels written out
/// of order). A whole-payload binder or a field list is a list of names, a
/// name being a nested variant when the field's type has a variant so named;
/// `..` pads with wildcards up to `arity`.
fn variantPayloadPatterns(
    env: *Env,
    v: anytype,
    arity: usize,
) InferError!?[]ast.Pattern {
    for (v.labels) |l| if (l.len > 0) return null;
    var out: std.ArrayListUnmanaged(ast.Pattern) = .empty;
    switch (v.payload) {
        .binding => |name| try out.append(env.arena, .{ .ident = name }),
        .fields => |names| for (names) |name| try out.append(env.arena, .{ .ident = name }),
        .literals => |args| try out.appendSlice(env.arena, args),
    }
    if (out.items.len > arity) return null;
    while (out.items.len < arity) try out.append(env.arena, .wildcard);
    return try out.toOwnedSlice(env.arena);
}

/// Whether `rows` (one pattern per column, matched against `types`) together
/// match every value of those columns: the usual specialisation over the
/// first column. A variant of an enum column is covered when the rows naming
/// it, or irrefutable there, cover its payload and the remaining columns; any
/// other first column is covered only through the rows irrefutable in it.
fn rowsCoverColumns(
    env: *Env,
    rows: []const []const ast.Pattern,
    types: []const *T.Type,
) InferError!bool {
    if (rows.len == 0) return false;
    if (types.len == 0) return true;
    const first = types[0].deref();
    const rest = types[1..];

    var enumDef: ?envMod.TypeDef.Enum = null;
    if (first.* == .named) {
        if (env.lookupTypeDef(first.named.name)) |td| {
            if (td == .enum_) enumDef = td.enum_;
        }
    }

    if (enumDef) |en| {
        for (en.variants) |vd| {
            const payloadTypes = (try variantPayloadTypes(env, first, vd.name)) orelse &[_]*T.Type{};
            var sub: std.ArrayListUnmanaged([]const ast.Pattern) = .empty;
            for (rows) |row| {
                const head = row[0];
                if (try patternIsIrrefutable(env, head, first)) {
                    const widened = try env.arena.alloc(ast.Pattern, payloadTypes.len + rest.len);
                    for (widened[0..payloadTypes.len]) |*w| w.* = .wildcard;
                    @memcpy(widened[payloadTypes.len..], row[1..]);
                    try sub.append(env.arena, widened);
                    continue;
                }
                switch (head) {
                    .ident => |name| if (isEnumVariantNameForSubject(env, first, name) and
                        std.mem.eql(u8, bareVariantName(name), vd.name) and payloadTypes.len == 0)
                    {
                        try sub.append(env.arena, row[1..]);
                    },
                    .variant => |v| {
                        if (v.shape != .variant or !std.mem.eql(u8, bareVariantName(v.name), vd.name)) continue;
                        const pats = (try variantPayloadPatterns(env, v, payloadTypes.len)) orelse continue;
                        const widened = try env.arena.alloc(ast.Pattern, pats.len + rest.len);
                        @memcpy(widened[0..pats.len], pats);
                        @memcpy(widened[pats.len..], row[1..]);
                        try sub.append(env.arena, widened);
                    },
                    else => {},
                }
            }
            const subTypes = try env.arena.alloc(*T.Type, payloadTypes.len + rest.len);
            @memcpy(subTypes[0..payloadTypes.len], payloadTypes);
            @memcpy(subTypes[payloadTypes.len..], rest);
            if (!try rowsCoverColumns(env, sub.items, subTypes)) return false;
        }
        return true;
    }

    var sub: std.ArrayListUnmanaged([]const ast.Pattern) = .empty;
    for (rows) |row| {
        if (try patternIsIrrefutable(env, row[0], first)) try sub.append(env.arena, row[1..]);
    }
    return rowsCoverColumns(env, sub.items, rest);
}

/// A variant no single arm covers whole may still be covered by several arms
/// that refine its payload (`Run(Fast)` and `Run(Slow)` over a `Run(speed:
/// Speed)`): add to `covered` every variant of the enum subject whose unguarded
/// arms, taken together, cover all its payloads.
fn collectVariantsCoveredByNestedPayloads(
    env: *Env,
    arms: []const ast.CaseArm,
    subjectType: *T.Type,
    variantNames: []const []const u8,
    covered: *std.ArrayListUnmanaged([]const u8),
) InferError!void {
    for (variantNames) |vn| {
        if (namesContain(covered.items, vn)) continue;
        const payloadTypes = (try variantPayloadTypes(env, subjectType, vn)) orelse continue;
        var rows: std.ArrayListUnmanaged([]const ast.Pattern) = .empty;
        for (arms) |arm| {
            if (arm.guard != null) continue;
            try collectVariantRows(env, arm.pattern, vn, payloadTypes.len, &rows);
        }
        if (rows.items.len < 2) continue;
        if (try rowsCoverColumns(env, rows.items, payloadTypes)) try covered.append(env.arena, vn);
    }
}

fn collectVariantRows(
    env: *Env,
    pattern: ast.Pattern,
    variantName: []const u8,
    arity: usize,
    rows: *std.ArrayListUnmanaged([]const ast.Pattern),
) InferError!void {
    switch (pattern) {
        .variant => |v| {
            if (v.shape != .variant or !std.mem.eql(u8, bareVariantName(v.name), variantName)) return;
            const pats = (try variantPayloadPatterns(env, v, arity)) orelse return;
            try rows.append(env.arena, pats);
        },
        .@"or" => |pats| for (pats) |p| try collectVariantRows(env, p, variantName, arity, rows),
        else => {},
    }
}

/// When `pattern` is a *single* irrefutable variant match whose variant is
/// already covered, return that variant's name (the arm is unreachable). OR
/// patterns are skipped — one covered alternative does not make the arm dead.
fn alreadyCoveredVariant(
    env: *Env,
    pattern: ast.Pattern,
    subjectType: *T.Type,
    covered: []const []const u8,
) InferError!?[]const u8 {
    switch (pattern) {
        .ident => |name| {
            const bare = bareVariantName(name);
            if (isEnumVariantNameForSubject(env, subjectType, name) and namesContain(covered, bare)) return bare;
        },
        .variant => |v| {
            const bare = bareVariantName(v.name);
            if (try variantPayloadIrrefutable(env, subjectType, v.name, v.payload) and namesContain(covered, bare)) return bare;
        },
        else => {},
    }
    return null;
}

/// Decision 8 §5.4 — the set of values a `case` subject draws from, and what it
/// takes to cover that set.
const CaseDomain = union(enum) {
    /// A `type` with variants: covered when every variant is.
    enum_: []const []const u8,
    /// `A | B` (§3.3): covered when every member is named by a type pattern.
    /// The identity of a union *is* its members, so the members are the domain.
    union_: []*T.Type,
    /// `string`, `i32`, `unknown` — an unbounded set of values no finite list of
    /// literal arms reaches. Only `_`, or a type pattern naming the subject's own
    /// type (§5.4's "a type covered whole"), covers it. `unknown` has no such
    /// type pattern, which is why §5.4 always requires `_` over it.
    open,
};

/// The two open domains §5.4 names by hand, beside `unknown`. Deliberately not
/// every scalar: widening the rule to `f64`, `bool` and the sized integers turns
/// every `case` on one of them that has no `_` into an error, and §5.4 states
/// the rule for `i32` and `string`. The rest is reported, not assumed.
const open_case_domain_names = [_][]const u8{ "i32", "string" };

/// Resolve a `case` subject's domain, or null when the subject is not
/// exhaustiveness-checked at all (a record, a generic, an array, a `?T`, an
/// unresolved type variable).
fn caseSubjectDomain(env: *Env, resolved: *T.Type) InferError!?CaseDomain {
    // §3.3 — a `case` covering every member of a union needs no `_`.
    if (resolved.* == .union_) return CaseDomain{ .union_ = resolved.union_ };
    if (resolved.* != .named) return null;
    // §5.4 — `unknown` always needs `_`: no type pattern covers it, because a
    // value of any other type is still a possibility the arm did not test.
    if (unifyMod.isUnknown(resolved)) return CaseDomain.open;
    const name = resolved.named.name;
    if (env.lookupTypeDef(name)) |td| {
        switch (td) {
            .enum_ => |en| {
                const names = try env.arena.alloc([]const u8, en.variants.len);
                for (en.variants, 0..) |v, i| names[i] = v.name;
                return CaseDomain{ .enum_ = names };
            },
            else => return null,
        }
    }
    for (open_case_domain_names) |p| {
        if (std.mem.eql(u8, name, p)) return CaseDomain.open;
    }
    return null;
}

/// A printable label for a `case` subject: a named type's own name, or a union
/// spelled out `i32 | string` — "union" on its own names nothing the author
/// wrote. Owned by `env.arena`.
fn caseSubjectLabel(env: *Env, ty: *T.Type) InferError![]const u8 {
    const d = ty.deref();
    if (d.* != .union_) return switch (d.*) {
        .named => |n| n.name,
        else => "value",
    };
    var buf: std.ArrayListUnmanaged(u8) = .empty;
    for (d.union_, 0..) |m, i| {
        if (i > 0) try buf.appendSlice(env.arena, " | ");
        try buf.appendSlice(env.arena, try caseSubjectLabel(env, m));
    }
    return buf.toOwnedSlice(env.arena);
}

/// True when the type a type pattern tests is the same named type as `member` —
/// the only way a union member is covered arm by arm (§3.3).
fn sameNamedType(a: *T.Type, b: *T.Type) bool {
    const da = a.deref();
    const db = b.deref();
    if (da.* != .named or db.* != .named) return false;
    return std.mem.eql(u8, da.named.name, db.named.name);
}

/// Full exhaustiveness + reachability analysis for a `case`. Sets
/// `env.lastError` and returns `error.TypeError` on the first problem: an
/// unreachable arm, an open domain with no `_`, a union with an uncovered member,
/// or an enum with uncovered variants. Subjects whose type names no domain
/// (`caseSubjectDomain`) are not checked.
fn checkCaseExhaustiveness(
    env: *Env,
    subjectType: *T.Type,
    arms: []const ast.CaseArm,
    loc: ast.Loc,
) InferError!void {
    const resolved = subjectType.deref();
    const domain = (try caseSubjectDomain(env, resolved)) orelse return;
    const typeName = try caseSubjectLabel(env, resolved);

    var covered: std.ArrayListUnmanaged([]const u8) = .empty;
    defer covered.deinit(env.arena);
    var hasCatchAll = false;
    // §5.4 — a type pattern naming the subject's own type covers it whole
    // (`case n { i32 { m -> … } }` on an `i32`).
    var wholeTypeCovered = false;
    // §3.3 — one flag per union member, set by the arm that tests that member.
    const memberCovered: []bool = switch (domain) {
        .union_ => |members| blk: {
            const flags = try env.arena.alloc(bool, members.len);
            @memset(flags, false);
            break :blk flags;
        },
        else => &.{},
    };

    for (arms) |arm| {
        const guarded = arm.guard != null;

        // Any unguarded arm following an unguarded catch-all can never run.
        if (hasCatchAll and !guarded) {
            env.lastError = TypeError.redundantPattern(typeName, "this arm").withLoc(arm.body.getLoc());
            return error.TypeError;
        }

        // §5.3 / §5.4 — a guarded arm may fail its guard, so it neither covers
        // anything for exhaustiveness nor shadows a later arm.
        if (guarded) continue;

        if (patternIsCatchAll(env, arm.pattern, resolved)) {
            hasCatchAll = true;
            continue;
        }

        // §5.2 / §5.4 — a type pattern. What it covers depends on the domain: the
        // subject's own type covers an open domain whole, and a union member
        // covers that member. Over `unknown` it covers nothing.
        if (try typePatternType(env, arm.pattern, resolved)) |tested| {
            switch (domain) {
                .open => if (!unifyMod.isUnknown(resolved) and sameNamedType(tested, resolved)) {
                    wholeTypeCovered = true;
                },
                .union_ => |members| for (members, 0..) |m, i| {
                    if (sameNamedType(tested, m)) memberCovered[i] = true;
                },
                .enum_ => {},
            }
            continue;
        }

        // §3.3 — a constructor pattern naming a union member and binding all of
        // its fields covers that member whole.
        if (domain == .union_) {
            if (try fullConstructorPatternType(env, arm.pattern, resolved)) |tested| {
                for (domain.union_, 0..) |m, i| {
                    if (sameNamedType(tested, m)) memberCovered[i] = true;
                }
                continue;
            }
        }

        if (try alreadyCoveredVariant(env, arm.pattern, resolved, covered.items)) |dup| {
            const desc = try std.fmt.allocPrint(env.arena, "variant '{s}'", .{dup});
            env.lastError = TypeError.redundantPattern(typeName, desc).withLoc(arm.body.getLoc());
            return error.TypeError;
        }

        try collectFullyCoveredVariants(env, arm.pattern, resolved, &covered);
    }

    if (hasCatchAll) return;

    if (domain == .enum_) try collectVariantsCoveredByNestedPayloads(env, arms, resolved, domain.enum_, &covered);

    switch (domain) {
        .open => {
            if (wholeTypeCovered) return;
            env.lastError = TypeError.nonExhaustive(typeName, &.{}).withLoc(loc);
            return error.TypeError;
        },
        .union_ => |members| {
            var missing: std.ArrayListUnmanaged([]const u8) = .empty;
            for (members, 0..) |m, i| {
                if (!memberCovered[i]) try missing.append(env.arena, try caseSubjectLabel(env, m));
            }
            if (missing.items.len > 0) {
                env.lastError = TypeError
                    .nonExhaustiveOf(typeName, try missing.toOwnedSlice(env.arena), "member(s)")
                    .withLoc(loc);
                return error.TypeError;
            }
        },
        .enum_ => |variantNames| {
            var missing: std.ArrayListUnmanaged([]const u8) = .empty;
            for (variantNames) |name| {
                if (!namesContain(covered.items, name)) try missing.append(env.arena, name);
            }
            if (missing.items.len > 0) {
                env.lastError = TypeError.nonExhaustive(typeName, try missing.toOwnedSlice(env.arena)).withLoc(loc);
                return error.TypeError;
            }
        },
    }
}

/// Infer the type of `expr` AND build the fully-annotated `TypedExpr` in one
/// pass.  Every child node is recursively typed before its parent is built, so
/// no expression is visited more than once.  All allocations go into env.arena.
pub fn inferExprTyped(env: *Env, expr: ast.Expr) InferError!TypedExpr {
    // 00 · 01-checker — an expectation belongs to the position it was set for.
    // Only an identifier chain reads it (a leading-dot enum path) and only an
    // array literal passes it on (to its elements); every other node clears it
    // so a nested expression never inherits its parent's expected type. A
    // leading-dot call (`.Circle(radius: 1)`) reads it too: its head is the
    // same path, and `inferCallExpr` clears it before the arguments.
    const outer_expected = env.expectedType;
    defer env.expectedType = outer_expected;
    switch (expr) {
        // `.literal`, `.unaryOp` and `.binaryOp` read it for an integer
        // literal's width (the literal takes the integer type its position
        // asks for — `val k: i64 = 1000;`, `n * 1000` with `n: i64`);
        // `inferBinaryOpExpr` hands it on only to arithmetic operands.
        // `.function` reads a FALLIBLE function expectation (decision 147,
        // `inferFunctionExpr`) and clears it before its body.
        .identifier, .collection, .literal, .unaryOp, .binaryOp, .function => {},
        .call => |c| if (!isLeadingDotCall(c) and !isUnappliedGenericCtorCall(env, c)) {
            env.expectedType = null;
        },
        else => env.expectedType = null,
    }
    return switch (expr) {
        // ── literals ──────────────────────────────────────────────────────────
        .literal => |l| inferLiteralExpr(env, l, l.loc),

        // ── identifiers ───────────────────────────────────────────────────────
        .identifier => |i| inferIdentifierExpr(env, i, i.loc),

        // ── binary operations ───────────────────────────────────────────────────
        .binaryOp => |b| inferBinaryOpExpr(env, b, b.loc),

        // ── unary operations ──────────────────────────────────────────────────
        .unaryOp => |u| inferUnaryOpExpr(env, u, u.loc),

        // ── control flow ──────────────────────────────────────────────────────
        .jump => |j| inferJumpExpr(env, j, j.loc),
        .branch => |b| inferBranchExpr(env, b, b.loc),
        .loop => |lp| inferLoopExpr(env, lp, lp.loc),

        // ── binding expressions ────────────────────────────────────────────────
        .binding => |b| inferBindingExpr(env, b, b.loc),

        // ── use-hook expressions (@Context F7) ────────────────────────────────
        .useHook => |uh| inferUseHookExpr(env, uh, uh.loc),

        // ── call expressions ───────────────────────────────────────────────────
        .call => |c| blk: {
            try checkStdContextCall(env, c);
            try checkOpaqueCall(env, c);
            // Decisions 416, 722 — `inject(R)` names a type: the call answers
            // `@Component<R>`, typed here; `context(T)` with a bare type is
            // refused here, `context(ctx)` typed as any call.
            if (try contextReadCall(env, c)) |typed| break :blk typed;
            try noteTypeTokenHandOns(env, c);
            const typedCall = try inferCallExpr(env, c, c.loc);
            try checkOpaqueMethodCall(env, typedCall, c);
            try noteComponentCall(env, c, typedCall);
            try noteHostCall(env, c);
            try noteTypeTokenArgs(env, c, typedCall);
            try noteAsyncCall(env, c, typedCall);
            try noteStageCall(env, c, typedCall);
            // Decision 791 (1) — a call of a component makes its lambda wherever it
            // is written, a component body included: it answers `Component<R>`.
            break :blk applyReceiverTypeArgs(env, c, try applyExplicitTypeArgs(env, c, typedCall));
        },

        // ── function definition expressions ────────────────────────────────────
        .function => |f| inferFunctionExpr(env, f, f.loc),

        // ── collection expressions ─────────────────────────────────────────────
        .collection => |co| inferCollectionExpr(env, co, co.loc),

        // ── comptime expressions ───────────────────────────────────────────────
        .comptime_ => |a| inferComptimeExpr(env, a, a.loc),
    };
}

/// Infer `expr` in a position whose type the site already knows (00 ·
/// 01-checker). The expectation is only a hint — `tryResolveEnumSectionPath`
/// is its one reader — and the caller's own expectation is restored on the way
/// out, so a site can set one per sub-expression.
fn inferExprTypedExpecting(env: *Env, expr: ast.Expr, expected: ?*T.Type) InferError!TypedExpr {
    const prev = env.expectedType;
    defer env.expectedType = prev;
    env.expectedType = expected;
    return inferExprTyped(env, expr);
}

/// `inferExprTypedExpecting` for the untyped inference path.
fn inferExprExpecting(env: *Env, expr: ast.Expr, expected: ?*T.Type) InferError!*T.Type {
    const prev = env.expectedType;
    defer env.expectedType = prev;
    env.expectedType = expected;
    return inferExpr(env, expr);
}

// ── Helper functions for each expression category ───────────────────────────

/// Infer type for literal expressions (strings, numbers, null, comments)
/// The integer type the position of an integer literal expects, if any
/// (through one `?T`).
fn expectedIntegerType(env: *Env) ?[]const u8 {
    var t = (env.expectedType orelse return null).deref();
    if (t.* == .named and std.mem.eql(u8, t.named.name, "optional") and t.named.args.len == 1) t = t.named.args[0].deref();
    if (t.* != .named or t.named.args.len != 0) return null;
    const ints = [_][]const u8{ "i8", "u8", "i16", "u16", "i32", "u32", "i64", "u64", "isize", "usize" };
    for (ints) |i| if (std.mem.eql(u8, i, t.named.name)) return i;
    return null;
}

/// `==` / `!=` do not widen an integer literal against an `f64` operand
/// (decision 209 reads every other position): the comparison is refused at
/// the literal instead (decision 215, `inferBinaryOpExpr`).
fn equalityOperandExpectation(op: @FieldType(ast.BinOpExprOf(.untyped), "op"), other: *T.Type) ?*T.Type {
    if ((op == .eq or op == .ne) and other.deref().isNamed("f64")) return null;
    return other;
}

/// Decision 332 — whether the written type `t` is or holds `bigint`.
fn typeRefMentionsBigint(t: ast.TypeRef) bool {
    return typeRefMentions(t, "bigint");
}

/// Whether the written type `t` is or holds the primitive `name` (`bigint`,
/// decision 346's `Bytes`).
fn typeRefMentions(t: ast.TypeRef, name: []const u8) bool {
    return switch (t) {
        .named => |n| std.mem.eql(u8, n, name),
        .optional => |inner| typeRefMentions(inner.*, name),
        .array => |inner| typeRefMentions(inner.*, name),
        .generic => |g| for (g.args) |a| {
            if (typeRefMentions(a, name)) break true;
        } else false,
        else => if (t.tupleElems()) |elems| for (elems) |e| {
            if (typeRefMentions(e, name)) break true;
        } else false else false,
    };
}

/// Decision 332 — whether the position of a literal asks for a `bigint`
/// (through one `?T`).
fn expectsBigint(env: *Env) bool {
    var t = (env.expectedType orelse return false).deref();
    if (t.* == .named and std.mem.eql(u8, t.named.name, "optional") and t.named.args.len == 1) t = t.named.args[0].deref();
    return t.* == .named and t.named.args.len == 0 and std.mem.eql(u8, t.named.name, "bigint");
}

/// Decision 247 — the floating type the position of a literal expects
/// (through one `?T`): `"f64"`, `"f32"`, or null.
fn expectedFloatType(env: *Env) ?[]const u8 {
    var t = (env.expectedType orelse return null).deref();
    if (t.* == .named and std.mem.eql(u8, t.named.name, "optional") and t.named.args.len == 1) t = t.named.args[0].deref();
    if (t.* != .named or t.named.args.len != 0) return null;
    if (std.mem.eql(u8, t.named.name, "f64")) return "f64";
    if (std.mem.eql(u8, t.named.name, "f32")) return "f32";
    return null;
}

/// True for an integer literal written without a suffix (`1000`), which
/// takes its width from its position; false for everything else (decision
/// 247: `1000l` is an `i64` wherever it stands).
fn isIntegerLiteral(e: ast.Expr) bool {
    if (e != .literal) return false;
    return switch (e.literal.kind) {
        .numberLit => |n| blk: {
            const parts = lexerMod.splitNumber(n);
            break :blk !parts.floating and parts.suffix.len == 0;
        },
        else => false,
    };
}

/// `isIntegerLiteral`, or a unary `-` of one (`-9007199254740991`): either
/// takes its width from the other operand of an arithmetic or comparison
/// operator. Decision 319 range-checks the literal in that width, so a negated
/// one typed `i32` by default (`value >= -9007199254740991` over an `i64`) was
/// refused where the positive one on the other side was not.
fn isIntegerLiteralOperand(e: ast.Expr) bool {
    if (e == .unaryOp and e.unaryOp.op == .neg) return isIntegerLiteral(e.unaryOp.expr.*);
    return isIntegerLiteral(e);
}

/// Whether a number literal is a float: a fraction, a decimal exponent
/// (`5e-324`, `1e10`; `0x1E` is an integer) or a floating suffix (`1f`).
fn isFloatLiteralText(n: []const u8) bool {
    const parts = lexerMod.splitNumber(n);
    return parts.floating or lexerMod.numberSuffixIsFloat(parts.suffix);
}

/// Decision 247 — an integer literal's digits fit the integer type it is
/// (`300u8` and `val b: u8 = 300` are refused at the literal). Radix and `_`
/// separators read as written; a literal past `i128` is past every type.
/// Decision 319 — an integer literal is a value of its type: suffixed or not
/// (an unsuffixed one has the type its position asks for, `i32` otherwise), it
/// is refused at the literal when the type has no such value. The operand of a
/// unary `-` (`env.negatingLiteral`) is read as the negative value, so each
/// signed type's minimum is written as itself (`-9223372036854775808l`), and an
/// unsigned type takes no negative one.
fn refuseIntegerOutOfRange(env: *Env, digits: []const u8, typeName: []const u8, loc: ast.Loc) InferError!void {
    var clean: std.ArrayListUnmanaged(u8) = .empty;
    for (digits) |c| if (c != '_') try clean.append(env.arena, c);
    const magnitude = std.fmt.parseInt(i128, clean.items, 0) catch std.math.maxInt(i128);
    const v: i128 = if (env.negatingLiteral) -magnitude else magnitude;
    const Range = struct { min: i128, max: i128 };
    const range: Range = inline for (.{ i8, u8, i16, u16, i32, u32, i64, u64, isize, usize }) |I| {
        if (std.mem.eql(u8, typeName, @typeName(I))) break .{ .min = std.math.minInt(I), .max = std.math.maxInt(I) };
    } else .{ .min = std.math.minInt(i64), .max = std.math.maxInt(u64) };
    if (v >= range.min and v <= range.max) return;
    const msg = if (v > range.max)
        try std.fmt.allocPrint(env.arena, "the literal `{s}` does not fit `{s}` (at most {d})", .{ digits, typeName, range.max })
    else
        try std.fmt.allocPrint(env.arena, "the literal `-{s}` does not fit `{s}` (at least {d})", .{ digits, typeName, range.min });
    env.lastError = TypeError.custom(msg, "An integer literal is a value of its type, and the type has no such value (decision 319): write a wider type's suffix (`l`, `ul`) or annotate the position with one.").withLoc(loc);
    return error.TypeError;
}

/// Decision 247 — a number pattern matches only a subject of its type: a
/// suffixed literal its suffix's type, a floating one `f64`, an integer one
/// any integer type (the subject's, within range). A subject that is a
/// union is matched by one of its members; a subject not yet known is left
/// to the arms that know it.
fn checkNumberPattern(env: *Env, text: []const u8, subjectType: *T.Type) InferError!void {
    const st = subjectType.deref();
    var candidates: []const *T.Type = &.{};
    var single = [_]*T.Type{st};
    switch (st.*) {
        .named => candidates = &single,
        .union_ => |members| candidates = members,
        else => return,
    }
    const ints = [_][]const u8{ "i8", "u8", "i16", "u16", "i32", "u32", "i64", "u64", "isize", "usize" };
    const parts = lexerMod.splitNumber(text);
    const own: ?[]const u8 = if (parts.suffix.len != 0) lexerMod.numberSuffixType(parts.suffix) else if (parts.floating) "f64" else null;
    for (candidates) |c| {
        const cd = c.deref();
        if (cd.* != .named or cd.named.args.len != 0) continue;
        const name = cd.named.name;
        if (own) |o| {
            if (std.mem.eql(u8, o, name)) return;
        } else for (ints) |i| if (std.mem.eql(u8, i, name)) return;
    }
    const subjectName = try snapshotMod.typeNameOf(env.arena, subjectType);
    const msg = if (own) |o|
        try std.fmt.allocPrint(env.arena, "the pattern `{s}` is an `{s}` literal and the subject is `{s}`", .{ text, o, subjectName })
    else
        try std.fmt.allocPrint(env.arena, "the pattern `{s}` is an integer literal and the subject is `{s}`", .{ text, subjectName });
    env.lastError = TypeError.custom(msg, "A number pattern matches a subject of its own type (decision 247): write the literal the subject's type takes — `1.0` for an `f64`, `1.5f` for an `f32`, `42` or a suffix for an integer.");
    return error.TypeError;
}

fn inferLiteralExpr(env: *Env, lit: ast.LiteralExprOf(.untyped), loc: ast.Loc) InferError!TypedExpr {
    return switch (lit.kind) {
        .stringLit => |s| TypedExpr{ .literal = .{ .loc = loc, .type_ = try env.namedType("string"), .kind = .{ .stringLit = s } } },
        // Decisions 519, 520 — a `Bytes` build constant (never written).
        .bytesLit => |b| TypedExpr{ .literal = .{ .loc = loc, .type_ = try env.namedType("bytes"), .kind = .{ .bytesLit = b } } },
        .stringTemplate => |t| {
            // Desugar `"a ${x} b"` into the concatenation chain `"a " + x + " b"`
            // (same semantics as written-out string `+`, incl. coercion). The
            // typed AST therefore never contains a stringTemplate node, so
            // transform/eval/codegen stay untouched.
            var acc: ?*ast.Expr = null;
            if (t.parts.len > 0 and t.parts[0] == .expr) {
                // Force a string-typed result when the template starts with a hole.
                const empty = try env.arena.create(ast.Expr);
                empty.* = .{ .literal = .{ .loc = loc, .kind = .{ .stringLit = "" } } };
                acc = empty;
            }
            for (t.parts) |p| {
                const operand: *ast.Expr = switch (p) {
                    .text => |txt| blk: {
                        const e = try env.arena.create(ast.Expr);
                        e.* = .{ .literal = .{ .loc = loc, .kind = .{ .stringLit = txt } } };
                        break :blk e;
                    },
                    .expr => |e| e,
                };
                if (acc) |lhs| {
                    const bin = try env.arena.create(ast.Expr);
                    bin.* = .{ .binaryOp = .{ .loc = loc, .op = .add, .lhs = lhs, .rhs = operand } };
                    acc = bin;
                } else {
                    acc = operand;
                }
            }
            return inferExprTyped(env, acc.?.*);
        },
        .numberLit => |n| blk: {
            // Decision 247 (209 reversed) — a suffixed literal is its suffix's
            // type wherever it stands (`1.5f` f32, `42ul` u64); without one,
            // `1.5` is `f64` and `42` an integer that takes the integer type
            // its position asks for (`val k: i64 = 1000;`, an `i64` argument,
            // the other operand of an arithmetic or comparison operator) and
            // `i32` with nothing asking. A literal never changes type to fit:
            // an integer where a float is expected and an unsuffixed fraction
            // where an `f32` is are refused at the literal, naming the
            // spelling. The suffix is stripped here once, for the typed tree
            // and — through `env.indexRewrites` — for the program every
            // backend lowers.
            const parts = lexerMod.splitNumber(n);
            if (parts.suffix.len != 0) {
                const typeName = lexerMod.numberSuffixType(parts.suffix) orelse {
                    const msg = try std.fmt.allocPrint(env.arena, "`{s}` is not a numeric suffix", .{parts.suffix});
                    env.lastError = TypeError.custom(msg, "The suffixes are `f`, `d`, `l`, `u`, `ul`, `i8`, `i16`, `u8`, `u16`, `isize`, `usize` (decision 247) and `n` (decision 332).").withLoc(loc);
                    return error.TypeError;
                };
                // Decision 332 — a `bigint` has no range to leave.
                if (!lexerMod.numberSuffixIsFloat(parts.suffix) and !std.mem.eql(u8, typeName, "bigint")) {
                    try refuseIntegerOutOfRange(env, parts.digits, typeName, loc);
                }
                const text = try lexerMod.numberBackendText(env.arena, n);
                if (!env.indexRewrites.contains(loc)) {
                    const stripped = try env.arena.create(ast.Expr);
                    stripped.* = .{ .literal = .{ .loc = loc, .kind = .{ .numberLit = text } } };
                    try env.indexRewrites.put(loc, stripped);
                }
                break :blk TypedExpr{ .literal = .{ .loc = loc, .type_ = try env.namedType(typeName), .kind = .{ .numberLit = text } } };
            }
            if (parts.floating) {
                if (expectedFloatType(env)) |want| if (std.mem.eql(u8, want, "f32")) {
                    const msg = try std.fmt.allocPrint(env.arena, "`{s}` is an `f64` where an `f32` is expected — write `{s}f`", .{ n, n });
                    env.lastError = TypeError.custom(msg, "A floating literal without a suffix is an `f64` and never changes type to fit (decision 247); the `f` suffix makes it an `f32`.").withLoc(loc);
                    return error.TypeError;
                };
                break :blk TypedExpr{ .literal = .{ .loc = loc, .type_ = try env.namedType("f64"), .kind = .{ .numberLit = n } } };
            }
            if (expectedFloatType(env)) |want| {
                const asFloat = (try floatSpelling(env, n)) orelse n;
                const suffix: []const u8 = if (std.mem.eql(u8, want, "f32")) "f" else "d";
                const msg = try std.fmt.allocPrint(env.arena, "the integer literal `{s}` is not an `{s}` — write `{s}{s}` or `{s}`", .{ n, want, n, suffix, if (std.mem.eql(u8, want, "f32")) try std.fmt.allocPrint(env.arena, "{s}f", .{asFloat}) else asFloat });
                env.lastError = TypeError.custom(msg, "A literal without a suffix never changes type to fit (decision 247, which reverses decision 209): an integer literal is an integer, and a float is written as one.").withLoc(loc);
                return error.TypeError;
            }
            // Decision 332 — an unsuffixed literal is never a `bigint` (247):
            // the position asking for one is answered with the spelling.
            if (expectsBigint(env)) {
                const msg = try std.fmt.allocPrint(env.arena, "the integer literal `{s}` is not a `bigint` — write `{s}n`", .{ n, n });
                env.lastError = TypeError.custom(msg, "A literal without a suffix never changes type to fit (decision 247): the `n` suffix makes an integer literal a `bigint` (decision 332).").withLoc(loc);
                return error.TypeError;
            }
            const width: []const u8 = expectedIntegerType(env) orelse "i32";
            try refuseIntegerOutOfRange(env, parts.digits, width, loc);
            break :blk TypedExpr{ .literal = .{ .loc = loc, .type_ = try env.namedType(width), .kind = .{ .numberLit = n } } };
        },
        .null_ => blk: {
            const innerVar = try env.freshVar();
            const optArgs = try env.arena.alloc(*T.Type, 1);
            optArgs[0] = innerVar;
            break :blk TypedExpr{ .literal = .{ .loc = loc, .type_ = try env.namedTypeArgs("optional", optArgs), .kind = .null_ } };
        },
        .comment => |c| TypedExpr{ .literal = .{ .loc = loc, .type_ = try env.namedType("void"), .kind = .{ .comment = c } } },
    };
}

/// Infer type for identifier expressions (ident, dotIdent, identAccess)
/// Decision 110 rule 1 — the declared name behind an imported type's `as`
/// alias written in expression position, or null when `name` is no such alias
/// or a local binding shadows it (the alias is bound to the declared type's
/// constructor, when it has one, by `registerImportedTypeAlias`).
fn importedTypeAliasTarget(env: *Env, name: []const u8) ?[]const u8 {
    const real = env.importedTypeAliases.get(name) orelse return null;
    if (env.lookup(name)) |bound| {
        const own = if (env.importedTypeAliasCtors.get(name)) |c| c == bound else false;
        const ctor = env.lookup(real) orelse return if (own) real else null;
        if (bound != ctor and !own) return null;
    }
    return real;
}

/// Decision 110 rule 1 — a receiver that is an imported type's alias (`D` in
/// `D.empty()`, `S` in `S.Red`) becomes the declared name. The renamed
/// identifier is recorded under the alias's own loc (`Env.indexRewrites`), so
/// `comptime/transform.zig` splices it and no backend sees the alias.
fn importedTypeAliasReceiver(env: *Env, re: *ast.Expr) !?*ast.Expr {
    if (re.* != .identifier or re.identifier.kind != .ident) return null;
    const real = importedTypeAliasTarget(env, re.identifier.kind.ident) orelse return null;
    const recv = try env.arena.create(ast.Expr);
    recv.* = .{ .identifier = .{ .loc = re.identifier.loc, .kind = .{ .ident = real } } };
    try env.indexRewrites.put(re.identifier.loc, recv);
    return recv;
}

fn inferIdentifierExpr(env: *Env, ident: ast.IdentifierExprOf(.untyped), loc: ast.Loc) InferError!TypedExpr {
    return switch (ident.kind) {
        .ident => |name| {
            // Decision 110 — the alias as a value (`xs.map(P)`) is the
            // declared name's binding, renamed for the backends.
            if (importedTypeAliasTarget(env, name)) |real| {
                const renamed = try env.arena.create(ast.Expr);
                renamed.* = .{ .identifier = .{ .loc = loc, .kind = .{ .ident = real } } };
                try env.indexRewrites.put(loc, renamed);
                return inferIdentifierExpr(env, renamed.identifier, loc);
            }
            if (env.lookup(name)) |ty| {
                try refuseBareVariant(env, name, ty, loc, false);
                if (env.localBindDepth(name) == null) if (env.stdContextNames.get(name)) |which| if (which == .provide or which == .context)
                    return refuseContextHookWithoutUse(env, name, loc);
                // A template function exists only while the program
                // compiles: named without a call it is no value, refused
                // where it is read (a local of the name is the local).
                if (env.localBindDepth(name) == null) if (templateFnNamed(env, name) != null) {
                    const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is a template function, which exists only while the program compiles, so it is no value", .{ diagnostics.template_function_value, name });
                    const hint = try std.fmt.allocPrint(env.arena, "Call it where its code should stand (`{s} \"…\"`); a template call expands there (decision 425).", .{name});
                    env.lastError = TypeError.custom(msg, hint).withLoc(loc);
                    return error.TypeError;
                };
                // A generic fn referenced as a value (`val f = identity;`,
                // `xs.map(identity)`) gets its own instantiation — the
                // scheme's `.generic` vars must never reach `unify`.
                const inst = try instantiateGenericType(env, ty);
                try noteComponentValue(env, name, inst, loc);
                // 144 B-115 (decision 673) — a module fn of type parameters
                // named as a value: commonJS hands its body the print shape of
                // each, read off the function type this use instantiates
                // (`text_fn_value_col`).
                if (inst != ty and env.localBindDepth(name) == null and inst.deref().* == .func) {
                    var key = loc;
                    key.col += ast.text_fn_value_col;
                    try noteTextValue(env, key, inst);
                }
                return TypedExpr{ .identifier = .{ .loc = loc, .type_ = inst, .kind = .{ .ident = name } } };
            }
            env.lastError = try unboundAt(env, name, loc);
            return error.TypeError;
        },
        .dotIdent => |written| {
            // A numeric section leaf (`.50`, row 22) is declared under the F1
            // mangling `__50`; it resolves by the expected section like an
            // identifier leaf, and only that way.
            const name = if (looksNumeric(written)) try std.fmt.allocPrint(env.arena, "__{s}", .{written}) else written;
            // Decision 631 — a field a typed meta read splices: its run-time
            // form `Field(Book, "pages")`.
            if (try inferFieldRunTimeForm(env, written, loc)) |te| return te;
            // 01 step 12 — a leading-dot variant takes its enum from the
            // position's expected type (as `.Circle(…)` does), spliced in as
            // `Enum.Variant` so the backends see the qualified form. Without
            // an expectation the flat table answers only when one enum
            // claims the name.
            if (expectedEnumDeclaring(env, name)) |en| {
                try noteImplicitEnum(env, en);
                const recv = try env.arena.create(ast.Expr);
                recv.* = .{ .identifier = .{ .loc = loc, .kind = .{ .ident = en } } };
                const qualified = try env.arena.create(ast.Expr);
                qualified.* = .{ .identifier = .{ .loc = loc, .kind = .{ .identAccess = .{ .receiver = recv, .member = name } } } };
                try env.indexRewrites.put(loc, qualified);
                return inferExprTyped(env, qualified.*);
            }
            if (name.ptr == written.ptr) if (env.lookup(name)) |ty| {
                try refuseAmbiguousVariant(env, name, ty, loc);
                return TypedExpr{ .identifier = .{ .loc = loc, .type_ = ty, .kind = .{ .dotIdent = name } } };
            };
            // A section leaf has a leading-dot shorthand only where the
            // position's type is that section (`val b: Token.Layout.Break =
            // .Zeta;`); anywhere else it is named for what it is, not
            // reported as a variable nobody declared.
            if (try sectionOwningLeaf(env, name)) |section| {
                const msg = try std.fmt.allocPrint(env.arena, "`.{s}` is a leaf of the section `{s}`, and nothing here says the position is that section", .{ written, section });
                const hint = try std.fmt.allocPrint(env.arena, "Give the position the section's type (`val v: {s} = .{s};`, a typed parameter) or write the full path.", .{ section, written });
                env.lastError = TypeError.custom(msg, hint).withLoc(loc);
                return error.TypeError;
            }
            env.lastError = try unboundAt(env, name, loc);
            return error.TypeError;
        },
        .identAccess => |ia| {
            // Decision 216 (2) — `@typeInfo(X).name`, `….meta.<d>.<k>`.
            if (try inferTypeinfoRead(env, ia, loc)) |read| return read;
            // Decision 110 — `S.Red` for `import {Shape as S}` is `Shape.Red`.
            if (try importedTypeAliasReceiver(env, ia.receiver)) |recv| {
                var direct = ident;
                direct.kind.identAccess.receiver = recv;
                return inferIdentifierExpr(env, direct, loc);
            }
            // §enum-sections F2 — path-access via dot-shorthand chain.
            // `.Color.Red.500` parses as `identAccess(identAccess(dotIdent(Color),
            // Red), 500)`. When the chain root is a `dotIdent`, the chain may
            // resolve as a section path into an enum that carries sections:
            // walk the chain through the parent enum's section tree and lower
            // to nested constructor calls.
            if (try tryResolveEnumSectionPath(env, ia.member, ia.receiver, loc)) |resolved| return resolved;

            // Decision 255 (1) — `Opt<i32>.None`: a unit variant read off the
            // instantiated type is that `Opt<i32>`; no other member of a type
            // is a value a type application could instantiate.
            const application: ?TypeApplication = if (ia.receiverTypeArgs) |w| try resolveTypeApplication(env, ia.receiver, w) else null;
            if (application) |app| {
                const isVariant = app.def == .enum_ and for (app.def.enum_.variants) |v| {
                    if (std.mem.eql(u8, v.name, ia.member)) break true;
                } else false;
                if (!isVariant) {
                    const msg = try std.fmt.allocPrint(env.arena, "`{s}` is not a variant of `{s}`, so its type arguments reach nothing", .{ ia.member, app.name });
                    env.lastError = TypeError.custom(msg, "Without a call, a type application reads a unit variant (`Opt<i32>.None`); a fn the type declares is called (`Dict<string, i32>.empty()`).").withLoc(loc);
                    return error.TypeError;
                }
            }
            // 144 B-10 (decision 430) — `Box.wrap` without a call: the
            // associated fn of a named type as a function value, typed by its
            // declared signature (instantiated fresh at each read, as a call
            // through the type is). It was a fresh variable that checked
            // nothing, and erlang emitted `Box` as an unbound variable.
            if (application == null) if (try associatedFnValue(env, ia, loc)) |typed| return typed;
            // When receiver is an identifier, check if it's a type name rather than a variable.
            // This handles enum/record/struct constructor access like Color.Red, Option.None
            if (ia.receiver.* == .identifier) {
                if (ia.receiver.*.identifier.kind == .ident) {
                    const receiverName = ia.receiver.*.identifier.kind.ident;
                    // Check if this identifier is a registered type definition
                    if (env.lookupTypeDef(receiverName)) |td| {
                        switch (td) {
                            .enum_ => |en| {
                                var found = false;
                                for (en.variants) |v| {
                                    if (std.mem.eql(u8, v.name, ia.member)) {
                                        found = true;
                                        break;
                                    }
                                }
                                if (!found) {
                                    env.lastError = TypeError.unknownField(receiverName, ia.member).withLoc(loc);
                                    return error.TypeError;
                                }
                                // C7: a generic enum's unit variant carries one
                                // fresh var per declared generic param, so
                                // `val n: Option<i32> = Option.None` unifies.
                                const ty = if (en.genericParams.len == 0)
                                    try env.namedType(receiverName)
                                else if (application) |app|
                                    try env.namedTypeArgs(receiverName, app.args)
                                else blk: {
                                    const args = try env.arena.alloc(*T.Type, en.genericParams.len);
                                    for (args) |*a| a.* = try env.freshVar();
                                    break :blk try env.namedTypeArgs(receiverName, args);
                                };
                                const recvTyped = try makeTypedPtr(env, TypedExpr{ .identifier = .{
                                    .loc = ia.receiver.*.getLoc(),
                                    .type_ = ty,
                                    .kind = .{ .ident = receiverName },
                                } });
                                return TypedExpr{ .identifier = .{ .loc = loc, .type_ = ty, .kind = .{ .identAccess = .{
                                    .receiver = recvTyped,
                                    .member = ia.member,
                                } } } };
                            },
                            else => {},
                        }
                    }
                }
            }
            // Regular instance field access on a variable/instance.
            // Optional chaining (`a?.b`): the receiver may be `?T` — resolve the
            // member on the inner `T` and wrap the result back into an optional
            // (already-optional member types are not double-wrapped).
            const recvPtr = if (try templateNameReceiver(env, ia.receiver.*)) |tr| tr else try makeTypedPtr(env, try inferExprTyped(env, ia.receiver.*));
            const recvTyped = recvPtr.*;
            var recvType = recvTyped.getType().deref();
            if (ia.optional) try refuseNeverNull(env, recvType, "?.", loc);
            if (ia.optional) {
                if (recvType.* == .named and std.mem.eql(u8, recvType.named.name, "optional") and
                    recvType.named.args.len >= 1)
                {
                    recvType = recvType.named.args[0].deref();
                }
            }
            // Decision 8 §2.2 — an `unknown` receiver has no members. Without
            // this the field falls through every arm below and lands on a fresh
            // variable, so `a.x` on an `unknown` checks silently.
            try refuseUnknownUse(env, recvType, loc, "read a field of");
            try refuseResultMemberAccess(env, recvType, ia.member, false, loc);
            // Decision 353 — a template body's catalogue is answered at build,
            // where a declaration of the program is no value; decision 356 —
            // a `val` with a `comptime` initializer is, its build value. The
            // read is recorded and refused at an expansion whose answer holds
            // an entry with no build value (`answerTemplateQueries`).
            if (env.inTemplateFn and recvType.* == .named and std.mem.eql(u8, recvType.named.name, "Declared") and std.mem.eql(u8, ia.member, "value")) record: {
                const r = env.reflection orelse break :record;
                const name = env.currentTemplateFn orelse break :record;
                const gop = try r.templateValueReads.getOrPut(r.arena, try reflectionMod.Reflection.templateKey(r.arena, env.modulePath, name));
                if (!gop.found_existing) gop.value_ptr.* = loc;
            }
            if (env.inTemplateFn and (env.reflection == null or env.currentTemplateFn == null) and recvType.* == .named and std.mem.eql(u8, recvType.named.name, "Declared") and std.mem.eql(u8, ia.member, "value")) {
                env.lastError = TypeError.custom(
                    diagnostics.typeinfo_all_template_value ++ ": a template body reads the catalogue at build, where a declaration of the program is no value",
                    "Read `name`, `module`, `meta` and `returnTypeName` of the entry; the declaration's value is the program's, at run time.",
                ).withLoc(loc);
                return error.TypeError;
            }
            // Decision 330 — a field read written after a `?.` link
            // (`p(true)?.me().x`, `a?.b.c`) continues the chain, as a method
            // there does (`inferResultOptionMethod`) and as TypeScript's does:
            // it reads the payload, and absent anywhere before it is absent.
            // It IS the `if` over the chain so far — `if (<chain>) { n -> n.x }
            // else { null }`, `?X` flattened — recorded for the transform to
            // splice in (`enumSectionRewrites`), so no backend learns a rule.
            if (!ia.optional and recvType.* == .named and std.mem.eql(u8, recvType.named.name, "optional") and
                recvType.named.args.len == 1 and continuesOptionalChain(recvPtr.*))
            {
                return inferOptionalChainField(env, ia.receiver, recvPtr, ia.member, loc);
            }
            // Decision 45 (1.0.5) — a member read off a `?T` is an error
            // naming `?.`: the value may be absent, and a plain `.` used to
            // check and then read a field off `null` (or, through a tuple
            // label, not get the label rewrite at all).
            if (!ia.optional and recvType.* == .named and std.mem.eql(u8, recvType.named.name, "optional") and recvType.named.args.len == 1) {
                const inner = try snapshotMod.typeNameOf(env.arena, recvType.named.args[0]);
                const msg = try std.fmt.allocPrint(env.arena, "`{s}` is read off an optional `?{s}` — write `?.{s}`", .{ ia.member, inner, ia.member });
                env.lastError = TypeError.custom(msg, "The value may be absent: `x?.field` answers `null` when it is, or narrow it first (`if (x != null) { x.field }`, `if (x) { v -> v.field }`).").withLoc(loc);
                return error.TypeError;
            }
            var outType: *T.Type = try env.freshVar();
            // Anonymous structural record: resolve the field directly.
            if (recvType.* == .record) {
                const fields = recvType.record;
                var found = false;
                for (fields) |f| {
                    if (std.mem.eql(u8, f.name, ia.member)) {
                        outType = f.type_;
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    env.lastError = TypeError.unknownField("record", ia.member).withLoc(loc);
                    return error.TypeError;
                }
            }
            // Tuple element access: `t._0`, `t._1`, … on a `#(A, B, …)` value.
            // The element type comes from the tuple's positional type args.
            if (recvType.* == .named and std.mem.eql(u8, recvType.named.name, "tuple")) {
                const idxStr = if (ia.member.len > 0 and ia.member[0] == '_') ia.member[1..] else ia.member;
                if (std.fmt.parseInt(usize, idxStr, 10)) |idx| {
                    if (idx < recvType.named.args.len) outType = recvType.named.args[idx];
                } else |_| {
                    // Decision 8 §6 T4: `row.pop` names an element by its label.
                    // The label exists only here — record the positional rewrite
                    // (`row._1`) for the transform, so every backend sees an index.
                    const idx = tupleLabelIndex(recvType.named.labels, ia.member) orelse {
                        env.lastError = TypeError.custom(
                            try std.fmt.allocPrint(env.arena, "this tuple has no element labeled `{s}`", .{ia.member}),
                            "labels come from the tuple's written type or from the variables it was built from; use the position instead: `._0`, `._1`, …",
                        ).withLoc(loc);
                        return error.TypeError;
                    };
                    outType = recvType.named.args[idx];
                    const rewrite = try env.arena.create(ast.Expr);
                    rewrite.* = .{ .identifier = .{ .loc = loc, .kind = .{ .identAccess = .{
                        .receiver = ia.receiver,
                        .member = try std.fmt.allocPrint(env.arena, "_{d}", .{idx}),
                        .optional = ia.optional,
                    } } } };
                    try env.enumSectionRewrites.put(loc, rewrite);
                    try env.tupleLabelReads.put(env.arena, loc, idx);
                }
            }
            if (recvType.* == .named) {
                const recvNamed = recvType.named;
                // `arr.length` / `s.length` / `arr.len`: the host length op
                // (`length(Arr)` / `string:length(S)` / `.length` in JS), NOT a
                // map field read. Record the primitive kind so the non-JS
                // backends lower the field access correctly.
                if ((std.mem.eql(u8, recvNamed.name, "array") or std.mem.eql(u8, recvNamed.name, "string")) and
                    (std.mem.eql(u8, ia.member, "length") or std.mem.eql(u8, ia.member, "len")))
                {
                    const k: envMod.PrimKind = if (std.mem.eql(u8, recvNamed.name, "string")) .string else .array;
                    // Decision 887 (2) — the property is the table's, `pub val length: i32;`.
                    try methodVisibility.refusePrimitiveMember(env, primitiveTable(env, recvNamed.name), recvNamed.name, ia.member, loc);
                    try env.instanceLowerings.put(loc, .{ .prim = k });
                    outType = try env.namedType("i32");
                }
                // `b.length` on a `bytes` is its byte count, as `b.length()` is:
                // the primitive kind makes erlang and beam lower it to
                // `byte_size/1`, never a text length.
                else if (std.mem.eql(u8, recvNamed.name, "bytes") and std.mem.eql(u8, ia.member, "length")) {
                    try env.instanceLowerings.put(loc, .{ .prim = .bytes });
                    outType = try env.namedType("i32");
                }
                // Tuple index access (`t._0`, `t._1`, …): resolve to the Nth
                // element type so a `?T` element keeps its `@Option` method
                // surface (`.unwrapOr`) — without this the element gets a fresh
                // var and the method-call lowering can't fire.
                else if (std.mem.eql(u8, recvNamed.name, "tuple")) {
                    if (tupleMemberIndex(ia.member)) |idx| {
                        if (idx < recvNamed.args.len) outType = recvNamed.args[idx];
                    }
                } else if (std.mem.eql(u8, recvNamed.name, ast.expr_type_name) and recvNamed.args.len == 1) {
                    // Decision 364 (2), (3) — `x.value` is the expression's
                    // value at build: `T`, unless `T` is a function or a type.
                    if (!std.mem.eql(u8, ia.member, "value")) {
                        env.lastError = TypeError.unknownField(ast.expr_type_name, ia.member).withLoc(loc);
                        return error.TypeError;
                    }
                    try refuseExprValueRead(env, ia.receiver.*, loc);
                    outType = recvNamed.args[0];
                } else if (env.lookupTypeDef(recvNamed.name)) |td| {
                    switch (td) {
                        .record, .struct_ => {
                            if (td.findField(ia.member)) |f| {
                                try refuseFieldBuildMember(env, recvNamed.name, ia.member, loc);
                                try opaqueTypes.refuseField(env, recvNamed.name, ia.member, loc);
                                // The receiver's type, for the backends that
                                // store a record positionally — erlang and beam
                                // under decision 21 read `element(N + 1, V)`,
                                // and the field's NAME does not carry N.
                                try env.instanceLowerings.put(loc, .{ .field_of = recvNamed.name });
                                // Generic instance: substitute the registered
                                // cells with the instance's type args.
                                outType = try instantiateFieldType(env, recvNamed.name, recvNamed.args, f.type_);
                            } else {
                                env.lastError = TypeError.unknownField(recvNamed.name, ia.member).withLoc(loc);
                                return error.TypeError;
                            }
                        },
                        .enum_ => {
                            env.lastError = TypeError.unknownField(recvNamed.name, ia.member).withLoc(loc);
                            return error.TypeError;
                        },
                    }
                } else try refuseBehaviorUnknownMember(env, recvType, ia.member, false, loc);
            }
            if (ia.optional) {
                const outDeref = outType.deref();
                const alreadyOptional = outDeref.* == .named and
                    std.mem.eql(u8, outDeref.named.name, "optional");
                if (!alreadyOptional) {
                    outType = try env.namedTypeArgs("optional", &.{outType});
                }
            }
            return TypedExpr{ .identifier = .{ .loc = loc, .type_ = outType, .kind = .{ .identAccess = .{
                .receiver = recvPtr,
                .member = ia.member,
                .optional = ia.optional,
            } } } };
        },
    };
}

/// The `comptime x: @Expr<T>` parameter of the function being inferred that
/// `e` names, if any.
fn exprParamNamed(env: *Env, e: ast.Expr) ?ast.Param {
    if (e != .identifier or e.identifier.kind != .ident) return null;
    return exprParamOfName(env, e.identifier.kind.ident);
}

fn exprParamOfName(env: *Env, name: ?[]const u8) ?ast.Param {
    const n = name orelse return null;
    for (env.currentParams) |p| if (p.exprWrapped and std.mem.eql(u8, p.name, n)) return p;
    return null;
}

/// The name a typed identifier reads, null for any other node.
fn typedIdentName(e: ast.TypedExpr) ?[]const u8 {
    if (e != .identifier) return null;
    return switch (e.identifier.kind) {
        .ident => |n| n,
        else => null,
    };
}

/// Decision 364 (3) — an `@Expr` of a type has no `.value`: the type is not
/// inspected while the program compiles. Refused at the read. A function's
/// (or an optional one's) is an ordinary build value, tested against `null`
/// as any `?T` is (decision 735).
fn refuseExprValueRead(env: *Env, receiver: ast.Expr, loc: ast.Loc) InferError!void {
    // Decision 757 — a type token handed on to another call's token.
    if (env.typeTokenHandOns.contains(loc)) return;
    const name: []const u8 = if (receiver == .identifier and receiver.identifier.kind == .ident) receiver.identifier.kind.ident else "the expression";
    if (exprParamNamed(env, receiver)) |p| if (p.typeRef == .typeparam) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is an `@Expr` of a type, which has no `.value`", .{ diagnostics.expr_value_of_type, name });
        env.lastError = TypeError.custom(msg, "A type is not inspected while the program compiles (decision 364 (3)): hand it on to the program.").withLoc(loc);
        return error.TypeError;
    };
}

/// Infer type for binary operation expressions
fn inferBinaryOpExpr(env: *Env, binop: ast.BinOpExprOf(.untyped), loc: ast.Loc) InferError!TypedExpr {
    // An integer literal takes its width from the other operand of an
    // arithmetic or comparison operator (`n * 1000`, `1000 - n`, `x > 0` with
    // `n`, `x: i64`), and an arithmetic operator hands its own position's
    // expectation to its operands (`3 * 86400000` passed to an `i64`).
    const numericOp = switch (binop.op) {
        .add, .sub, .mul, .div, .mod, .lt, .gt, .lte, .gte, .eq, .ne => true,
        else => false,
    };
    const arithmeticOp = switch (binop.op) {
        .add, .sub, .mul, .div, .mod => true,
        else => false,
    };
    const outerExpected = env.expectedType;
    env.expectedType = if (arithmeticOp and expectedIntegerType(env) != null) outerExpected else null;
    // A literal on the left is typed after the right, from it.
    const lhsIsLiteral = numericOp and isIntegerLiteralOperand(binop.lhs.*) and !isIntegerLiteralOperand(binop.rhs.*);
    const early_rhs: ?TypedExpr = if (lhsIsLiteral) try inferExprTypedExpecting(env, binop.rhs.*, env.expectedType) else null;
    const lhsTyped = if (early_rhs) |r|
        try inferExprTypedExpecting(env, binop.lhs.*, equalityOperandExpectation(binop.op, r.getType()))
    else
        try inferExprTyped(env, binop.lhs.*);

    // The right operand of `&&` runs only where the left one held, and the
    // right operand of `||` only where it failed: `x != null && x.f` and
    // `x == null || x.f` read `x` narrowed, by the same rules an `if`
    // condition narrows its branches with (`collectCondNarrowings`).
    var andSnapshots: std.ArrayListUnmanaged(PatternBindingSnapshot) = .empty;
    defer andSnapshots.deinit(env.arena);
    if (binop.op == .@"and" or binop.op == .@"or") {
        var lhsNarrowings: std.ArrayListUnmanaged(CondNarrowing) = .empty;
        defer lhsNarrowings.deinit(env.arena);
        try collectCondNarrowings(env, binop.lhs.*, &lhsNarrowings);
        for (lhsNarrowings.items) |n| {
            const side = if (binop.op == .@"and") n.then_ else n.else_;
            if (side) |ty| try bindNarrowed(env, n.name, ty, &andSnapshots);
        }
    }
    // `x && x.field` — if LHS is an optional variable, narrow it before
    // inferring the RHS so `.field` access resolves.
    if (binop.op == .@"and") {
        if (binop.lhs.* == .identifier and binop.lhs.identifier.kind == .ident) {
            const varName = binop.lhs.identifier.kind.ident;
            const lhsTy = lhsTyped.getType().deref();
            if (lhsTy.* == .named and std.mem.eql(u8, lhsTy.named.name, "optional") and lhsTy.named.args.len >= 1) {
                const innerTy = lhsTy.named.args[0];
                const old = env.lookup(varName);
                try andSnapshots.append(env.arena, .{ .name = varName, .previous = old });
                try env.bind(varName, innerTy);
            }
        }
    }

    // Decision 357 — the right operand of `&&` / `||` runs on some calls only.
    const prevUseConstruct = if (binop.op == .@"and")
        enterUseConstruct(env, "the right operand of `&&`")
    else if (binop.op == .@"or")
        enterUseConstruct(env, "the right operand of `||`")
    else
        env.useConstruct;
    defer env.useConstruct = prevUseConstruct;
    // 01 step 12 — the right side of `==` / `!=` is compared with the left, so
    // the left's type is its expected type: `decl.kind != .Record` names
    // `TypeInfoKind.Record` even where another enum also declares `Record`.
    const rhsTyped = if (early_rhs) |r|
        r
    else if (binop.op == .eq or binop.op == .ne or (numericOp and isIntegerLiteralOperand(binop.rhs.*)))
        try inferExprTypedExpecting(env, binop.rhs.*, equalityOperandExpectation(binop.op, lhsTyped.getType()))
    else
        try inferExprTyped(env, binop.rhs.*);

    // Restore after RHS inference.
    if (andSnapshots.items.len > 0) {
        try restorePatternBindings(env, andSnapshots.items);
    }
    // Decision 215 — `==` / `!=` between an `f64` and an integer literal is
    // refused at the literal: the exact comparison (decision B2) and the
    // literal's widening (decision 209) would read it two ways.
    if (binop.op == .eq or binop.op == .ne) {
        const litSide: ?ast.Expr = if (isIntegerLiteral(binop.lhs.*) and rhsTyped.getType().deref().isNamed("f64"))
            binop.lhs.*
        else if (isIntegerLiteral(binop.rhs.*) and lhsTyped.getType().deref().isNamed("f64"))
            binop.rhs.*
        else
            null;
        if (litSide) |lit| {
            const text = lit.literal.kind.numberLit;
            const fixed = (try floatSpelling(env, text)) orelse text;
            const msg = try std.fmt.allocPrint(env.arena, "comparing f64 with an integer literal — write {s}", .{fixed});
            env.lastError = TypeError.custom(msg, "`==` between numbers is exact and never widens; write the literal as the float it is compared with.").withLoc(lit.getLoc());
            return error.TypeError;
        }
    }
    // Decision 346 — `Bytes` answers `==` / `!=` (its bytes compared) and no
    // other operator: `+` would read it as text, and an ordering has no one
    // answer across the targets. The backends without a native comparison of
    // two byte sequences read the `==` from the operator's lowering.
    switch (binop.op) {
        .eq, .ne => if (lhsTyped.getType().deref().isNamed("bytes") or rhsTyped.getType().deref().isNamed("bytes")) {
            try env.instanceLowerings.put(loc, .{ .prim = .bytes });
        },
        .add, .sub, .mul, .div, .mod, .lt, .gt, .lte, .gte => for ([_]TypedExpr{ lhsTyped, rhsTyped }, [_]ast.Expr{ binop.lhs.*, binop.rhs.* }) |t, e| {
            if (!t.getType().deref().isNamed("bytes")) continue;
            const sym: []const u8 = switch (binop.op) {
                .add => "+",
                .sub => "-",
                .mul => "*",
                .div => "/",
                .mod => "%",
                .lt => "<",
                .gt => ">",
                .lte => "<=",
                else => ">=",
            };
            // A string template's holes are joined with `+` (`inferLiteralExpr`).
            const msg = if (binop.op == .add)
                "`bytes` is no text to join with `+` or a string template"
            else
                try std.fmt.allocPrint(env.arena, "`bytes` takes no `{s}`", .{sym});
            env.lastError = TypeError.custom(msg, "`bytes` answers `==` and `!=` alone (decision 346): join two with `a.concat(b)`, read one as text with `b.toUtf8()`.").withLoc(e.getLoc());
            return error.TypeError;
        },
        else => {},
    }
    const lhsPtr = try makeTypedPtr(env, lhsTyped);
    const rhsPtr = try makeTypedPtr(env, rhsTyped);

    // Determine result type based on operator
    const resultType: *T.Type = switch (binop.op) {
        // §2.2 — `==` and `!=` are the two comparisons an `unknown` answers
        // (they compare by value, §2.3). An ordering comparison is arithmetic:
        // it is not in §2.2's allowed list, and it reads the value's magnitude
        // exactly as `+` does.
        .lt, .gt, .lte, .gte => blk: {
            try refuseUnknownUse(env, lhsTyped.getType(), binop.lhs.getLoc(), "compare");
            try refuseUnknownUse(env, rhsTyped.getType(), binop.rhs.getLoc(), "compare");
            break :blk try env.namedType("bool");
        },
        .eq, .ne => try env.namedType("bool"),
        .@"and", .@"or" => blk: {
            // 06 C3 — `unifyAt(env, a, b, loc)` is TARGET-first: `a` is what
            // the context expects, `b` what was written
            // (`typeMismatch(a, b)` renders "expected a, got b"). These two
            // passed the operand as `a`, so `1 && true` read "expected i32,
            // got bool". The caret is on the OPERAND, not the whole expression.
            try unifyAt(env, try env.namedType("bool"), lhsTyped.getType(), binop.lhs.getLoc());
            try unifyAt(env, try env.namedType("bool"), rhsTyped.getType(), binop.rhs.getLoc());
            break :blk try env.namedType("bool");
        },
        .add => blk: {
            // String + anything → string (coercion)
            const lhsTy = lhsTyped.getType();
            const rhsTy = rhsTyped.getType();
            // §2.2 — `+` is the one arithmetic operator `requireNumericOperand`
            // below does not guard, because it also concatenates strings. An
            // `unknown` operand is refused here for both readings at once:
            // nothing has established that it is either.
            try refuseUnknownUse(env, lhsTy, binop.lhs.getLoc(), "do arithmetic on");
            try refuseUnknownUse(env, rhsTy, binop.rhs.getLoc(), "do arithmetic on");
            if (lhsTy.isNamed("string") or rhsTy.isNamed("string")) {
                // 144 B-78 — the other side is written as text.
                if (!lhsTy.isNamed("string")) {
                    try noteTextValue(env, binop.lhs.getLoc(), lhsTy);
                    try noteTextHole(env, binop.lhs.getLoc(), lhsTy);
                }
                if (!rhsTy.isNamed("string")) {
                    try noteTextValue(env, binop.rhs.getLoc(), rhsTy);
                    try noteTextHole(env, binop.rhs.getLoc(), rhsTy);
                }
                break :blk try env.namedType("string");
            }
            // Numeric promotion: float wins over int
            if (isFloatType(lhsTy) and isIntType(rhsTy)) break :blk lhsTy;
            if (isIntType(lhsTy) and isFloatType(rhsTy)) break :blk rhsTy;
            // Located at the right operand (01 step 9): the left one set the
            // type the right must take.
            try unifyAt(env, lhsTy, rhsTy, binop.rhs.getLoc());
            break :blk lhsTy;
        },
        .sub, .mul, .div, .mod => blk: {
            const lhsTy = lhsTyped.getType();
            const rhsTy = rhsTyped.getType();
            // 06 C3 — both operands must be numeric. `unify(lhs, rhs)` alone
            // accepted `"a" * "b"`: two strings agree with each other.
            const opName = switch (binop.op) {
                .sub => "-",
                .mul => "*",
                .div => "/",
                else => "%",
            };
            try requireNumericOperand(env, lhsTy, opName, binop.lhs.getLoc());
            try requireNumericOperand(env, rhsTy, opName, binop.rhs.getLoc());
            if (isFloatType(lhsTy) and isIntType(rhsTy)) break :blk lhsTy;
            if (isIntType(lhsTy) and isFloatType(rhsTy)) break :blk rhsTy;
            // Located at the right operand (01 step 9): the left one set the
            // type the right must take.
            try unifyAt(env, lhsTy, rhsTy, binop.rhs.getLoc());
            break :blk lhsTy;
        },
    };
    switch (binop.op) {
        .add, .sub, .mul, .div, .mod => try env.divisions.put(loc, resultType),
        else => {},
    }
    return TypedExpr{ .binaryOp = .{
        .loc = loc,
        .type_ = resultType,
        .op = binop.op,
        .lhs = lhsPtr,
        .rhs = rhsPtr,
    } };
}

/// Infer type for unary operation expressions
fn inferUnaryOpExpr(env: *Env, unaryop: ast.UnaryOpExprOf(.untyped), loc: ast.Loc) InferError!TypedExpr {
    // Decision 319 — `-<integer literal>` is range-checked as the negative
    // value (`refuseIntegerOutOfRange`); any other operand is a value of its own.
    const saved_negating = env.negatingLiteral;
    env.negatingLiteral = unaryop.op == .neg and unaryop.expr.* == .literal and unaryop.expr.literal.kind == .numberLit;
    const operandTyped = inferExprTyped(env, unaryop.expr.*) catch |e| {
        env.negatingLiteral = saved_negating;
        return e;
    };
    env.negatingLiteral = saved_negating;
    const operandPtr = try makeTypedPtr(env, operandTyped);
    return switch (unaryop.op) {
        .not => blk: {
            // 06 C3 — target-first, located at the operand (see the `&&`/`||`
            // note in `inferBinaryOpExpr`).
            try unifyAt(env, try env.namedType("bool"), operandTyped.getType(), unaryop.expr.getLoc());
            break :blk TypedExpr{ .unaryOp = .{ .loc = loc, .type_ = try env.namedType("bool"), .op = .not, .expr = operandPtr } };
        },
        // 06 C3 — `-x` applied no constraint at all, so `-"s"` checked.
        .neg => blk: {
            try requireNumericOperand(env, operandTyped.getType(), "-", unaryop.expr.getLoc());
            try env.divisions.put(loc, operandTyped.getType());
            break :blk TypedExpr{ .unaryOp = .{ .loc = loc, .type_ = operandTyped.getType(), .op = .neg, .expr = operandPtr } };
        },
    };
}

/// Returns the called member name when `expr` is `<wrapper>.<member>(...)`
/// AND `member` appears in `members`. Otherwise null. Syntactic check —
/// no type inference required. Drives the §1 / §1F manual-construction
/// rejections (R11 / R12 / RF1 / RF2 / RF5).
fn wrapperMemberCallName(expr: ast.Expr, wrapper: []const u8, members: []const []const u8) ?[]const u8 {
    if (expr != .call) return null;
    const call = expr.call;
    if (call.kind != .call) return null;
    const cc = call.kind.call;
    const recv = cc.receiver orelse return null;
    if (recv.* != .identifier) return null;
    if (recv.identifier.kind != .ident) return null;
    if (!std.mem.eql(u8, recv.identifier.kind.ident, wrapper)) return null;
    for (members) |m| {
        if (std.mem.eql(u8, cc.callee, m)) return cc.callee;
    }
    return null;
}

/// Returns the `Result` variant name when `expr` is the form
/// `Result.Ok(...)` / `Result.Error(...)` (§1 / §2 R11–R12 detection).
fn resultVariantCallName(expr: ast.Expr) ?[]const u8 {
    return wrapperMemberCallName(expr, "Result", &.{ "Ok", "Error" });
}

/// True when `env` is currently inside a body whose effect is `kind`.
fn inEffectContext(env: *Env, kind: ast.EffectKind) bool {
    const ctx = env.starFn orelse return false;
    return ctx.effect == kind;
}

/// The refusal for `what` written outside a generator scope: the returns and
/// the loop prefixes that open one (decisions 122, 125), read off the chain.
fn generatorScopeRefusal(env: *Env, code: []const u8, what: []const u8) ![]const u8 {
    const names = try effectChain.grantingMarkersSpelled(env.arena, .yield_);
    const body: []const u8 = if (env.fnEffect) |e|
        (if (e == .result) "this body carries no marker" else try std.fmt.allocPrint(env.arena, "this body is marked `{s}`, which is no sequence", .{e.markerWord()}))
    else
        "this body carries no marker";
    return std.fmt.allocPrint(
        env.arena,
        "{s}: {s} needs a generator scope — a body marked {s}, or an `iter` / `stream` loop; {s}",
        .{ code, what, names, body },
    );
}

/// Decision 431 (1) — the ways out `effect-try-without-fallible-channel` names:
/// `try … catch` handles the failure on the spot, and a host binding answers a
/// `@Result` only under `result: true` (490).
const fallible_channel_ways_out = "; `try … catch` handles the failure on the spot, and a host binding answers a `Result` with `result: true`";

/// Decision 121 — the refusal for `throw` / `try` in a body whose return
/// carries no `@Result` layer, naming the return.
fn fallibleChannelRefusal(env: *Env, what: []const u8) ![]const u8 {
    if (env.inLambdaBody) return std.fmt.allocPrint(
        env.arena,
        "{s}: `{s}` in a lambda needs a `Result` in the lambda's expected return — a lambda's return is the type its position expects, and this one has none{s}",
        .{ diagnostics.effect_try_without_fallible_channel, what, fallible_channel_ways_out },
    );
    // Decision 570 — an unmarked `-> Async<Result<T, E>>` body is an ordinary
    // function: its `Result` is inside the `Async` it returns whole, no
    // channel of the body's; the marker opens it.
    const unmarked: ?ast.EffectKind = if (env.fnEffect == null) blk: {
        const w = (env.returnWhole orelse break :blk null).deref();
        if (w.* != .named) break :blk null;
        break :blk ast.EffectKind.fromWrapperName(w.named.name);
    } else null;
    const shape: []const u8 = if (env.fnEffect) |e| switch (e) {
        .iterator, .stream => try std.fmt.allocPrint(env.arena, "the item of `{s}<T>` has to be `Result<T, E>` to use `throw` / `try`", .{e.returnWrapper()}),
        else => try std.fmt.allocPrint(env.arena, "this fn returns `{s}<…>` with no `Result` in it", .{e.returnWrapper()}),
    } else if (unmarked != null and unmarked.? != .result)
        try std.fmt.allocPrint(env.arena, "this body carries no `{s}` marker, so it returns the whole `{s}<…>` and a `Result` inside it is no channel of the body's — write `{s} fn`", .{ unmarked.?.markerWord(), unmarked.?.returnWrapper(), unmarked.?.markerWord() })
    else
        "this fn's return has no `Result` in it";
    return std.fmt.allocPrint(
        env.arena,
        "{s}: `{s}` needs a `Result` in some layer of the return — {s}{s}",
        .{ diagnostics.effect_try_without_fallible_channel, what, shape, fallible_channel_ways_out },
    );
}

/// Unify a `throw` / `try`'s error with the fallible channel's `E`. Where the
/// `E` is INFERRED (an `async { }` block or an `iter` / `stream` loop with no
/// annotation, decisions 124 / 125), two that do not unify are
/// `gen-infer-conflicting-errors`, asking for the annotation.
fn unifyErrorChannel(env: *Env, errType: *T.Type, got: *T.Type, loc: ast.Loc) InferError!void {
    if (!env.inferredErrorScope) return unifyAt(env, errType, got, loc);
    unifyUnlocated(env, errType, got) catch |err| switch (err) {
        error.TypeError => {
            env.lastError = TypeError.custom(
                diagnostics.gen_infer_conflicting_errors ++
                    ": the error types of this block's `throw` / `try` do not agree, so its `Result<U, E>` has no one `E`",
                "Annotate the value with the error you mean: `val x: Async<Result<U, E>> = async { … };` (or `Iter<Result<U, E>>` for a loop), and handle the other error where it happens.",
            ).withLoc(loc);
            return error.TypeError;
        },
        else => return err,
    };
}

/// Decision 118 rule 1 — refuse `what` (a capability) in a body whose return
/// is an ALIAS of an effect wrapper: the alias types the function but
/// activates nothing. Returns true (with `lastError` set) when it refused.
fn refuseBehindAlias(env: *Env, what: []const u8, loc: ast.Loc) InferError!bool {
    const w = env.aliasWrapper orelse return false;
    env.lastError = TypeError.custom(
        try std.fmt.allocPrint(
            env.arena,
            "{s}: `{s}` under an aliased return — the alias resolves to `{s}<…>`, and an alias does not activate the effect",
            .{ diagnostics.effect_wrapper_behind_alias, what, w },
        ),
        try std.fmt.allocPrint(env.arena, "Write `{s}<…>` literally in the return type to activate the effect (decision 118): whoever reads the signature has to see the wrapper.", .{w}),
    ).withLoc(loc);
    return true;
}

/// The value of a `return` / `yield` that passes a wrapper layer through
/// unchanged rather than being wrapped (decision 119): a `@Result` into a
/// `@Result` layer, or the whole declared wrapper.
fn valuePassesThrough(env: *Env, vt: *T.Type) bool {
    const v = vt.deref();
    if (v.* != .named) return false;
    if (std.mem.eql(u8, v.named.name, "Result")) return true;
    const w = env.returnWhole orelse return false;
    const wd = w.deref();
    return wd.* == .named and std.mem.eql(u8, wd.named.name, v.named.name) and
        ast.EffectKind.fromWrapperName(v.named.name) != null;
}

/// Decision 539 — what `enterDefer` saves, for `leaveDefer`.
const DeferFrame = struct {
    active: bool,
    lambda: u32,
    async_: u32,
    generator: u32,
    floor: usize,
    loopDepth: u32,
    breakScope: @TypeOf(@as(Env, undefined).breakScope),
    tryRegion: @TypeOf(@as(Env, undefined).tryRegion),
};

/// Decision 539 — the statement `defer <expr>;` is inferred as a path of its
/// own: no loop and no label outside it is a target, and `return`, `yield`
/// and `await` are refused (`refuseInDefer`). Its value is discarded.
fn enterDefer(env: *Env) DeferFrame {
    const f: DeferFrame = .{
        .active = env.deferActive,
        .lambda = env.deferLambdaDepth,
        .async_ = env.deferAsyncDepth,
        .generator = env.deferGeneratorDepth,
        .floor = env.deferLabelFloor,
        .loopDepth = env.loopDepth,
        .breakScope = env.breakScope,
        .tryRegion = env.tryRegion,
    };
    // Decision 866 — a `try` region outside the body is not the body's.
    env.tryRegion = null;
    env.deferActive = true;
    env.deferLambdaDepth = env.lambdaDepth;
    env.deferAsyncDepth = env.asyncBlockDepth;
    env.deferGeneratorDepth = env.generatorLoopDepth;
    env.deferLabelFloor = env.labelStack.items.len;
    env.loopDepth = 0;
    env.breakScope = .none;
    return f;
}

fn leaveDefer(env: *Env, f: DeferFrame) void {
    env.deferActive = f.active;
    env.deferLambdaDepth = f.lambda;
    env.deferAsyncDepth = f.async_;
    env.deferGeneratorDepth = f.generator;
    env.deferLabelFloor = f.floor;
    env.loopDepth = f.loopDepth;
    env.breakScope = f.breakScope;
    env.tryRegion = f.tryRegion;
}

/// Whether the position being inferred is the body of a `defer` itself, and
/// not a function, async block or generator loop nested in it.
fn inDeferBody(env: *const Env) bool {
    return env.deferActive and env.lambdaDepth == env.deferLambdaDepth and
        env.asyncBlockDepth == env.deferAsyncDepth and
        env.generatorLoopDepth == env.deferGeneratorDepth;
}

/// Decision 539 (5) — the jumps a `defer` body cannot make: they would leave
/// the path the deferred code runs on. `throw` and, outside a `try … catch` region written in the body, `try` are
/// refused too (decision 866, 595 (1)).
fn refuseInDefer(env: *Env, kind: anytype, loc: ast.Loc) InferError!void {
    const Hint = "A `defer` runs when its block ends, whichever way it ends; its body cannot choose another way out. Do that before the `defer` or after the block.";
    const code: []const u8, const what: []const u8 = switch (kind) {
        .@"return" => .{ diagnostics.defer_return, "`return`" },
        .@"continue" => |c| blk: {
            if (c.label) |lbl| {
                var i = env.labelStack.items.len;
                while (i > 0) : (i -= 1) {
                    if (std.mem.eql(u8, env.labelStack.items[i - 1], lbl)) break;
                } else return;
                if (i - 1 >= env.deferLabelFloor) return;
            } else if (env.loopDepth > 0) return;
            break :blk .{ diagnostics.defer_continue, "`continue`" };
        },
        .yield => .{ diagnostics.defer_yield, "`yield`" },
        .await_ => .{ diagnostics.defer_await, "`await`" },
        .throw_ => .{ diagnostics.defer_throw, "`throw`" },
        .try_ => if (env.tryRegion == null) .{ diagnostics.defer_try, "`try`" } else return,
        .@"break" => |b| blk: {
            if (b.label) |lbl| {
                var i = env.labelStack.items.len;
                while (i > 0) : (i -= 1) {
                    if (std.mem.eql(u8, env.labelStack.items[i - 1], lbl)) break;
                } else return;
                if (i - 1 >= env.deferLabelFloor) return;
            } else if (env.loopDepth > 0) return else if (b.value != null) {
                const generator = env.starFn != null and env.starFn.?.allowsYield;
                if (!generator or env.breakScope == .valueBlock) return;
            }
            break :blk .{ diagnostics.defer_break, "`break`" };
        },
    };
    env.lastError = TypeError.custom(
        try std.fmt.allocPrint(env.arena, "{s}: {s} inside a `defer` leaves the path the deferred code runs on", .{ code, what }),
        Hint,
    ).withLoc(loc);
    return error.TypeError;
}

/// Infer type for jump expressions (return, throw, try, break, continue, yield)
fn inferJumpExpr(env: *Env, j: ast.MakeExpr(.untyped, ast.JumpExprOf(.untyped)), loc: ast.Loc) InferError!TypedExpr {
    if (inDeferBody(env)) try refuseInDefer(env, j.kind, loc);
    return switch (j.kind) {
        .@"return" => |r| {
            // R11 (§2) — `return Result.Ok(<r>);` / `return Result.Error(<e>);`
            // inside a body whose return carries a `@Result` is the manual
            // wrapping form that the auto-wrap contract forbids: the @Result
            // variants are constructed by `return` / `throw` ALONE, never by
            // the author.
            if (env.throwContext == .result) {
                if (r) |rv| {
                    if (resultVariantCallName(rv.*)) |variant| {
                        if (std.mem.eql(u8, variant, "Ok")) {
                            env.lastError = TypeError.custom(
                                diagnostics.return_must_be_bare_R ++
                                    ": a body whose return carries `Result<R, E>` must `return` a value of type R; the Result::Ok wrapping is implicit.",
                                "Drop the `Result.Ok(...)` wrapping — write `return <r>;` directly.",
                            ).withLoc(loc);
                        } else {
                            env.lastError = TypeError.custom(
                                diagnostics.result_return_type_mismatch ++
                                    ": a body whose return carries `Result<R, E>` returns R via `return`; use `throw` for the error variant.",
                                "If the value is an error, change `return Result.Error(<e>);` to `throw <e>;`.",
                            ).withLoc(loc);
                        }
                        return error.TypeError;
                    }
                }
            }
            // RI1 (§1I / §2 R14) — `return <expr>;` inside a sequence body
            // (an `@Iter` / `@AsyncIter` that yields, or an `iter` / `stream`
            // loop) is forbidden: a sequence carries no return channel
            // (decision 122). The author writes `break <v>` to emit a last
            // item and end, or bare `break` for a clean end. Bare `return;`
            // (no value, an implicit clean end) stays legal. Decision 123 —
            // a body that RETURNS an iterator and never yields is a factory,
            // and mixing the two is `iter-mixed-yield-return`.
            if (r != null and (inEffectContext(env, .iterator) or inEffectContext(env, .stream))) {
                // Decision 584 (2) — a marked lambda's loop is its function
                // body: its `return <value>` reads as an `iter fn`'s.
                const inLoop = env.generatorLoopDepth > 0 and !(env.starFn != null and env.starFn.?.markedLambda);
                env.lastError = if (inLoop) TypeError.custom(
                    diagnostics.iterator_return_forbidden ++
                        ": a sequence has no return channel — `break <v>` emits `v` as the last item and ends, bare `break` ends cleanly",
                    "Replace `return <expr>;` with `break <expr>;` (the value is an item of type `T`), or with `yield <expr>; return;`.",
                ).withLoc(loc) else TypeError.custom(
                    diagnostics.iter_mixed_yield_return ++
                        ": this body yields, so it is an iterator — and `return <value>` answers a ready one, which is a factory (decision 123)",
                    "Pick one: keep the `yield`s and end with `break <v>` / `break`, or drop them and `return` the iterator (`return iter for (xs) { x -> … };`).",
                ).withLoc(loc);
                return error.TypeError;
            }
            // 00 · 01-checker — the body's return target is the expected type
            // of a returned value (`fn pick() -> Token { return .Color.Red.500; }`).
            // A lambda returned from a fn declared `-> fn(n: i32) -> R` takes its
            // parameters from that function type, as a `val f: fn(…) -> R = { … }`
            // does, so `n.toString()` in the body resolves against `i32`.
            const lambdaTarget: ?*T.Type = if (r) |rv| blk: {
                if (rv.* != .function or rv.function.kind.syntax != .lambda) break :blk null;
                // A method sets only `returnWhole`; a fn sets both.
                const tgt = env.returnWhole orelse env.returnTarget orelse break :blk null;
                const d = tgt.deref();
                if (d.* != .func or d.func.params.len != rv.function.kind.params.len) break :blk null;
                break :blk tgt;
            } else null;
            const valPtr: ?*TypedExpr = if (r) |rv| try makeTypedPtr(env, if (lambdaTarget) |tgt|
                try inferFunctionExprExpected(env, rv.function, rv.function.loc, tgt, false)
            else
                try inferExprTypedExpecting(env, rv.*, env.returnTarget)) else null;
            // Decision 432 — a task handed over whole (`taskLowerings`): the
            // body's declared return and the returned value are both a `@Async`.
            if (valPtr) |vp| if (env.returnWhole) |w| {
                const wd = w.deref();
                const vt = vp.getType().deref();
                if (wd.* == .named and std.mem.eql(u8, wd.named.name, "Async") and
                    vt.* == .named and std.mem.eql(u8, vt.named.name, "Async"))
                    try env.taskReturns.put(env.arena, loc, vp.getType());
            };
            // Decision 119 — inside a body whose return carries a `@Result`
            // layer, a returned plain value is wrapped into `{ok, V}` by the
            // transform pass (`__bp_ok`); a value already a `@Result`, or the
            // whole declared wrapper, passes through; `try` / `catch` forms
            // have dedicated statement-level lowerings in each backend.
            if (env.throwContext == .result) {
                if (r) |rv| {
                    // Decision 595 — a region answers its success value: it is
                    // returned as any value is (`wrap_ok`).
                    const isCatchForm = rv.* == .branch and rv.branch.kind == .tryCatch and !rv.branch.kind.tryCatch.region;
                    const isTryJump = rv.* == .jump and rv.jump.kind == .try_;
                    const passes = valuePassesThrough(env, valPtr.?.getType());
                    // Decision 119 — a nested wrapper (`-> @Result<@Result<U, E>, E>`)
                    // where a returned `@Result` fits both the value layer and the
                    // `@Result` layer: which one is meant is not the compiler's to
                    // guess.
                    const looksWhole = blk: {
                        const vt = valPtr.?.getType().deref();
                        break :blk vt.* == .named and vt.named.args.len >= 1 and isResultType(vt.named.args[0]);
                    };
                    if (passes and !isTryJump and !isCatchForm and !looksWhole and isResultType(valPtr.?.getType())) {
                        if (env.returnTarget) |target| if (isResultType(target)) {
                            env.lastError = TypeError.custom(
                                diagnostics.effect_return_ambiguous_nesting ++
                                    ": this `Result` fits two layers of the nested return — the value layer (wrapped `Ok(…)`) and the `Result` layer (passed through)",
                                "Say which: return the inner value and let `return` wrap it (`return try r;`), or bind the whole value with the declared type (`val w: Result<Result<U, E>, E> = …; return w;`) and return that.",
                            ).withLoc(loc);
                            return error.TypeError;
                        };
                    }
                    if (isTryJump) {
                        // `return try f()` — unwrap-then-rewrap is the identity;
                        // the transform returns `f()`'s Result directly.
                        try env.result_jump_lowerings.put(loc, .unwrap_passthrough);
                    } else if (!isCatchForm and !passes) {
                        try env.result_jump_lowerings.put(loc, .wrap_ok);
                    }
                } else {
                    // A bare `return;` is the `ok` position of a
                    // `-> @Result<void, E>` (decision 74): `{ok, null}`.
                    try env.result_jump_lowerings.put(loc, .wrap_ok);
                }
            }
            // C1 — unify the returned value with the body's return target.
            // A value that is already a wrapper layer (a `@Result` passthrough,
            // `try` / `catch` forms, the whole declared wrapper) is not
            // unwrapped here.
            if (env.returnTarget) |target| {
                if (valPtr) |vp| {
                    const rv = r.?.*;
                    const passthrough = blk: {
                        if (rv == .branch and rv.branch.kind == .tryCatch and !rv.branch.kind.tryCatch.region) break :blk true;
                        if (rv == .jump and rv.jump.kind == .try_) break :blk true;
                        const vt = vp.getType().deref();
                        if (vt.* == .named and env.throwContext == .result and std.mem.eql(u8, vt.named.name, "Result")) break :blk true;
                        break :blk false;
                    };
                    // B-162 (decision 791) — a body written `-> Component<R>`
                    // answers `R`: a returned component (`return mk(1)`, its
                    // `R` a `Renderable`) is a lambda, not its answer, and the
                    // types differ. `use` resolves it. A hook handing over
                    // another hook whole keeps the rule below.
                    if (env.returnWhole) |w| {
                        const wd = w.deref();
                        const vt = vp.getType().deref();
                        if (w != target and wd.* == .named and std.mem.eql(u8, wd.named.name, "Component") and
                            isComponentType(env, vt))
                        {
                            const rName = try snapshotMod.typeNameOf(env.arena, target.deref());
                            const msg = try std.fmt.allocPrint(env.arena, "type mismatch: expected {s}, got {s} — a body written `-> {s}` answers `{s}`, and a component call only makes its lambda: resolve it with `use` (decision 791)", .{
                                rName,
                                try snapshotMod.typeNameOf(env.arena, vt),
                                try snapshotMod.typeNameOf(env.arena, wd),
                                rName,
                            });
                            env.lastError = TypeError.custom(msg, "Resolve the component with `use` and return its answer (`val v = use c; return v;`), or place it in the tree as a child (decision 791 (3)).").withLoc(rv.getLoc());
                            return error.TypeError;
                        }
                    }
                    // A value that is already the declared wrapper (`return
                    // state(start)` in a `-> Component<X>` hook) unifies with
                    // the whole declared return type.
                    const whole: ?*T.Type = blk: {
                        const w = env.returnWhole orelse break :blk null;
                        const wd = w.deref();
                        const vt = vp.getType().deref();
                        if (wd.* == .named and vt.* == .named and w != target and
                            std.mem.eql(u8, wd.named.name, vt.named.name)) break :blk w;
                        break :blk null;
                    };
                    if (!passthrough) try refuseBareValueInUnmarked(env, target, vp.getType(), rv.getLoc());
                    if (whole) |w| {
                        try unifyAt(env, w, vp.getType(), rv.getLoc());
                    } else if (!passthrough and !behaviorCoercion(env, target, vp.getType())) {
                        try unifyAt(env, target, vp.getType(), rv.getLoc());
                    }
                } else if (env.returnBareIsVoid) {
                    try unifyAt(env, target, try env.namedType("void"), loc);
                }
            }
            return TypedExpr{ .jump = .{ .loc = loc, .type_ = try env.namedType("void"), .kind = .{ .@"return" = valPtr } } };
        },
        .throw_ => |e| {
            // R11-mirror (§2) — `throw Result.Error(<e>)` / `throw Result.Ok(<r>)`
            // inside a body whose return carries a `@Result` forbids the
            // manual wrapping by §1.
            if (env.throwContext == .result) {
                if (e) |ev| {
                    if (resultVariantCallName(ev.*)) |variant| {
                        if (std.mem.eql(u8, variant, "Error")) {
                            env.lastError = TypeError.custom(
                                diagnostics.throw_must_be_bare_E ++
                                    ": a body whose return carries `Result<R, E>` must `throw` a value of type E; the Result::Err wrapping is implicit.",
                                "Drop the `Result.Error(...)` wrapping — write `throw <e>;` directly.",
                            ).withLoc(loc);
                        } else {
                            env.lastError = TypeError.custom(
                                diagnostics.result_throw_type_mismatch ++
                                    ": a body whose return carries `Result<R, E>` raises E via `throw`; use `return` for the success variant.",
                                "If the value is the success payload, change `throw Result.Ok(<r>);` to `return <r>;`.",
                            ).withLoc(loc);
                        }
                        return error.TypeError;
                    }
                }
            }
            if (env.throwContext == .plain and try refuseBehindAlias(env, "throw", loc)) return error.TypeError;
            const valPtr: ?*TypedExpr = if (e) |ev| try makeTypedPtr(env, try inferExprTyped(env, ev.*)) else null;
            // Validate the thrown value against the fallible channel's `E`
            // (decision 121).
            switch (env.throwContext) {
                .result => |errType| {
                    if (valPtr) |vp| {
                        // Order matters: `errType` is the expected `E`, the thrown
                        // value is what we got — so unify(expected, got).
                        try unifyErrorChannel(env, errType, vp.getType(), loc);
                        // `throw e` produces the value `{error, E}`: returned
                        // from a `@Result` / `@Async` / `@Component` body
                        // (`return __bp_error(e)`), emitted as the last item of
                        // a sequence whose item is the `@Result` (`break
                        // __bp_error(e)`, decision 122 — it never rejects).
                        const inSequence = env.starFn != null and env.starFn.?.allowsYield;
                        try env.result_jump_lowerings.put(loc, if (inSequence) .break_error else .wrap_error);
                    }
                },
                .plain => {
                    env.lastError = TypeError.custom(
                        try fallibleChannelRefusal(env, "throw"),
                        "Put a `Result` in the return (`-> Result<T, E>`, `-> Async<Result<T, E>>`, `-> Iter<Result<T, E>>`, …) or handle the failure where it happens.",
                    ).withLoc(loc);
                    return error.TypeError;
                },
                .unchecked => {},
            }
            return TypedExpr{ .jump = .{ .loc = loc, .type_ = try env.namedType("void"), .kind = .{ .throw_ = valPtr } } };
        },
        .try_ => |e| {
            const valPtr: ?*TypedExpr = if (e) |ev| try makeTypedPtr(env, try inferExprTyped(env, ev.*)) else null;
            const rawTy = if (valPtr) |vp| vp.getType() else try env.freshVar();
            const ty = try tryUnwrapOrError(env, rawTy, loc);
            // Decision 595 (1), (5) — a `try` in a region hands its failure to
            // the region's `catch`: it needs no channel of the function's, and
            // it fails with the region's one error type.
            if (env.tryRegion) |region| {
                try joinTryRegion(env, region, rawTy, loc);
                return TypedExpr{ .jump = .{ .loc = loc, .type_ = ty, .kind = .{ .try_ = valPtr } } };
            }
            // Decisions 124 / 125 — in a block or prefixed loop whose `E` is
            // inferred, every propagating `try` joins it.
            if (env.inferredErrorScope and env.throwContext == .result) {
                const rt = rawTy.deref();
                if (rt.* == .named and std.mem.eql(u8, rt.named.name, "Result") and rt.named.args.len >= 2) {
                    try unifyErrorChannel(env, env.throwContext.result, rt.named.args[1], loc);
                }
            }
            // Decision 121 — bare `try` PROPAGATES: it returns the `Error` out of
            // the enclosing function (or, in a sequence whose item is a
            // `@Result`, emits it as the last item), so the body needs the
            // fallible channel — a `@Result` in some layer of the return. A
            // plain `fn` and a return with no `@Result` layer have none.
            // `try … catch` is a different node (`branch.tryCatch`): it
            // supplies its own fallback, propagates nothing and is not gated
            // here. The check runs AFTER the operand is known to be a
            // `@Result`, so `try <non-result>` keeps its own, more specific
            // refusal.
            //
            // `throwContext` is `.plain` exactly where a declared return type
            // carries no fallible channel, and `.unchecked` in a body with no
            // declared return type (a lambda, a `test` block), which stays
            // lenient.
            if (env.throwContext == .plain) {
                if (try refuseBehindAlias(env, "try", loc)) return error.TypeError;
                env.lastError = TypeError.custom(
                    try fallibleChannelRefusal(env, "try"),
                    "Use `try <expr> catch <fallback>`, which handles the error here and needs no channel, or put a `Result` in the return.",
                ).withLoc(loc);
                return error.TypeError;
            }
            return TypedExpr{ .jump = .{ .loc = loc, .type_ = ty, .kind = .{ .try_ = valPtr } } };
        },
        .@"break" => |b| {
            // Decision 105 — a bare `break` leaves the nearest loop, or ends
            // the generator scope when no loop encloses it; `break <value>`
            // emits the value and ends the nearest generator scope — an
            // annotated fn or an annotated `loop` — and needs one, unless it
            // is the value of a `comptime` block or a `case` arm's block
            // (decision 2). A label names an enclosing loop; the generator
            // scope's own label (a fn's signature label, an annotated loop's)
            // names it for `break :label <value>`.
            const ctx = env.starFn;
            const inGenerator = ctx != null and ctx.?.allowsYield;
            if (b.label) |lbl| try checkJumpLabel(env, lbl, "break", loc);
            if (b.value) |expr| {
                const targetsGenerator = inGenerator and (b.label == null or
                    (ctx.?.fnLabel != null and std.mem.eql(u8, b.label.?, ctx.?.fnLabel.?)));
                if (targetsGenerator and ctx.?.markedLambda) {
                    // Decision 584 (2) — a marked lambda's body is a function
                    // body: no `break <value>` ends it.
                    env.lastError = TypeError.custom(
                        diagnostics.marker_lambda_break_value ++
                            ": a marked lambda's body is a function body — `break <value>` does not end it",
                        "Write `yield <value>;` and then `return;`, which ends the iteration (decision 584); a bare `break` leaves the nearest loop.",
                    ).withLoc(loc);
                    return error.TypeError;
                }
                if (targetsGenerator) {
                    const typedPtr = try makeTypedPtr(env, try inferExprTyped(env, expr.*));
                    if (ctx.?.iterItem) |item| try unifyItem(env, item, typedPtr.getType(), loc);
                    return TypedExpr{ .jump = .{ .loc = loc, .type_ = try env.namedType("void"), .kind = .{ .@"break" = .{ .label = b.label, .value = typedPtr } } } };
                }
                if (b.label == null and env.breakScope == .armBlock) {
                    // Decision 541 (3) — a `case` arm's `break <value>` is
                    // removed, as `comptime`'s was: the arm's value is its tail.
                    try refuseBlockBreak(env, loc);
                    unreachable;
                }
                if (b.label == null and env.breakScope == .valueBlock) {
                    const typedPtr = try makeTypedPtr(env, try inferExprTyped(env, expr.*));
                    return TypedExpr{ .jump = .{ .loc = loc, .type_ = try env.namedType("void"), .kind = .{ .@"break" = .{ .label = null, .value = typedPtr } } } };
                }
                env.lastError = TypeError.custom(
                    try generatorScopeRefusal(env, diagnostics.break_value_outside_generator, "`break <value>`"),
                    "`break <value>` emits the value and ends the generator; a loop is a statement and has no value. Collect in a `var`, or with `map` / `filter`; end a loop with a bare `break`.",
                ).withLoc(loc);
                return error.TypeError;
            }
            // A bare `break` at loop depth 0 ends the generator scope; with
            // no loop, no generator scope and no value block there is nothing
            // to leave.
            if (b.label == null and env.loopDepth == 0) {
                if (!inGenerator and env.breakScope != .valueBlock) {
                    env.lastError = TypeError.custom(
                        diagnostics.break_outside_loop ++ ": `break` outside a loop",
                        "A `break` leaves the nearest `for` / `while` / `loop`, or ends a generator scope.",
                    ).withLoc(loc);
                    return error.TypeError;
                }
            }
            return TypedExpr{ .jump = .{ .loc = loc, .type_ = try env.namedType("void"), .kind = .{ .@"break" = .{ .label = b.label, .value = null } } } };
        },
        .await_ => |e| {
            // Decision 120 — `await` belongs to `@Async`, so every return whose
            // wrapper extends `@Async` answers it: `@Async`, `@Component` and
            // `@AsyncIter`, plus a `stream` loop. `@Iter` has none (`iter-await`).
            if (env.starFn == null or !env.starFn.?.allowsAwait) {
                if (try refuseBehindAlias(env, "await", loc)) return error.TypeError;
                if (env.starFn != null and env.starFn.?.effect == .iterator) {
                    env.lastError = TypeError.custom(
                        diagnostics.iter_await ++ ": `await` does not exist in an `iter` body — its items are produced synchronously",
                        "Write `async iter fn` (an `AsyncIter<T>`, or a `stream` loop): a stream is the sequence that may wait between items.",
                    ).withLoc(loc);
                    return error.TypeError;
                }
                env.lastError = TypeError.custom(
                    try effectChain.refusal(env.arena, diagnostics.await_without_async, .await_, env.fnEffect),
                    "Write `async fn` (its return is `Async<…>`; `component fn` / `async iter fn` answer `Component<…>` / `AsyncIter<…>`), or consume the Async through its own functions (`.map`, `.then`).",
                ).withLoc(loc);
                return error.TypeError;
            }
            // Decision 375 — a body that writes `await` is asynchronous.
            if (env.hookBuilder) |b| b.is_async = true;
            const valTyped = try inferExprTyped(env, e.*);
            const valPtr = try makeTypedPtr(env, valTyped);
            const rawTy = valPtr.getType();
            // `await @Async<T>` answers `T` and propagates nothing (decision
            // 120). A resolved non-Async named type is an error; an unresolved
            // type variable stays lenient.
            const deref = rawTy.deref();
            if (deref.* == .named and unwrapTaskType(rawTy) == null) {
                env.lastError = TypeError.custom(
                    "`await` expects an `Async<_>` value",
                    null,
                ).withLoc(loc);
                return error.TypeError;
            }
            // Decision 791 (4) — `await` is for `Async` alone: a component
            // value is resolved by `use c` or run by the tree. An operand
            // still unresolved here is checked once inference is done
            // (`refuseComponentAwaits`).
            if (deref.* == .named and std.mem.eql(u8, deref.named.name, "Component")) {
                return refuseAwaitComponent(env, rawTy, loc);
            }
            // Decision 432 — read once inference is done (`taskLowerings`).
            try env.taskAwaits.put(env.arena, loc, rawTy);
            const ty = try markResultSource(env, unwrapTaskType(rawTy) orelse rawTy, .await_);
            return TypedExpr{ .jump = .{ .loc = loc, .type_ = ty, .kind = .{ .await_ = valPtr } } };
        },
        .@"continue" => |c| {
            if (c.label) |lbl| try checkJumpLabel(env, lbl, "continue", loc);
            if (env.loopDepth == 0) {
                env.lastError = TypeError.custom(
                    diagnostics.continue_outside_loop ++ ": `continue` outside a loop",
                    "`continue` starts the next round of the nearest `for` / `while` / `loop`.",
                ).withLoc(loc);
                return error.TypeError;
            }
            return TypedExpr{ .jump = .{ .loc = loc, .type_ = try env.namedType("void"), .kind = .{ .@"continue" = .{ .label = c.label } } } };
        },
        .yield => |y| {
            // Decision 105 — `yield` feeds the NEAREST generator scope, an
            // `@Iter` / `@AsyncIter` fn or an `iter` / `stream` loop, through
            // every unprefixed loop between them; there is no other target. A
            // body without one — a plain `fn`, a `@Async`, a `@Result` —
            // refuses it naming the returns that grant it.
            const ctx = env.starFn orelse null;
            if (ctx == null or !ctx.?.allowsYield) {
                if (try refuseBehindAlias(env, "yield", loc)) return error.TypeError;
                env.lastError = TypeError.custom(
                    try effectChain.refusal(env.arena, diagnostics.yield_without_iter, .yield_, env.fnEffect),
                    "A `yield` feeds the nearest generator scope: write `iter fn` (`async iter fn` for an `AsyncIter<T>`), or write the loop as `iter loop { … }` (decision 125). To collect in a plain fn, use `map` / `filter` or a `var`.",
                ).withLoc(loc);
                return error.TypeError;
            }
            // `yield :label` names the generator scope — the fn's signature
            // label or the prefixed loop's — never a plain loop.
            if (y.label) |lbl| {
                const names_scope = if (ctx.?.fnLabel) |fl| std.mem.eql(u8, lbl, fl) else false;
                if (!names_scope) {
                    if (env.hasLabel(lbl)) {
                        env.lastError = TypeError.custom(
                            diagnostics.yield_label_not_generator ++ ": `yield :<label>` names a loop, and a `yield` feeds a generator scope",
                            "Label the scope it feeds: `iter fn … -> Iter<T> :name` or `iter loop :name { … }`; an unlabelled `yield` feeds the nearest one.",
                        ).withLoc(loc);
                        return error.TypeError;
                    }
                    env.lastError = TypeError.custom(
                        diagnostics.yield_label_unbound ++
                            ": `yield` targets an unknown label",
                        "Label a generator fn (`iter fn … -> Iter<T> :name`) or a prefixed loop (`iter loop :name { … }`).",
                    ).withLoc(loc);
                    return error.TypeError;
                }
            }
            const typedPtr: ?*TypedExpr = if (y.value) |expr| try makeTypedPtr(env, try inferExprTyped(env, expr.*)) else null;
            if (ctx.?.iterItem) |item| {
                if (typedPtr) |vp| try unifyItem(env, item, vp.getType(), loc);
            }
            return TypedExpr{ .jump = .{ .loc = loc, .type_ = try env.namedType("void"), .kind = .{ .yield = .{ .label = y.label, .value = typedPtr } } } };
        },
    };
}

/// Decision 122 — an item `v` emitted by `yield v` / `break v` into a sequence
/// of `item`: with an item `@Result<U, E>`, a `v: U` is emitted as `Ok(v)`
/// (recorded for the transform's `__bp_ok` wrap) and a `v: @Result<U, E>`
/// as is; otherwise `v` unifies with the item.
fn unifyItem(env: *Env, item: *T.Type, got: *T.Type, loc: ast.Loc) InferError!void {
    const it = item.deref();
    if (it.* == .named and std.mem.eql(u8, it.named.name, "Result") and it.named.args.len >= 1 and !isResultType(got)) {
        try unifyAt(env, it.named.args[0], got, loc);
        try env.result_jump_lowerings.put(loc, .yield_ok);
        return;
    }
    try unifyAt(env, got, item, loc);
}

/// Infer type for branch expressions (if and try-catch)
fn inferBranchExpr(env: *Env, b: ast.MakeExpr(.untyped, ast.BranchExprOf(.untyped)), loc: ast.Loc) InferError!TypedExpr {
    return switch (b.kind) {
        .if_ => |i| {
            const condTyped = try inferExprTyped(env, i.cond.*);
            const condPtr = try makeTypedPtr(env, condTyped);
            // Decision 357 — a branch runs on some calls only: no `use` in it.
            const prevUseConstruct = enterUseConstruct(env, if (i.binding != null and std.mem.eql(u8, i.binding.?, ast.nullish_binding_name))
                "the right operand of `??`"
            else
                "an `if` / `else`");
            defer env.useConstruct = prevUseConstruct;

            // Every name this condition narrows, and the type it takes on
            // each side of it. It is still ONE channel — `x is T`, a type-guard
            // call and the null test all write here — but it holds a LIST now:
            // `if (a != null && b != null)` narrows two names, and one slot
            // could only ever have narrowed the last of them.
            var narrowings: std.ArrayListUnmanaged(CondNarrowing) = .empty;
            defer narrowings.deinit(env.arena);
            var nullishPayload: ?*T.Type = null;

            if (i.binding) |binding_name| {
                // Null-check form: `if (x) { e -> ... }` — condition is optional, not bool.
                // Bind the unwrapped inner type to `binding_name`.
                const condTy = condTyped.getType().deref();
                // Decision 330 (2) — `a ?? b` with an `a` that is never null.
                if (std.mem.eql(u8, binding_name, ast.nullish_binding_name)) try refuseNeverNull(env, condTy, "??", loc);
                const innerTy: *T.Type = switch (condTy.*) {
                    .named => |n| if (std.mem.eql(u8, n.name, "optional") and n.args.len == 1)
                        n.args[0]
                    else
                        try env.freshVar(),
                    else => try env.freshVar(),
                };
                try env.bind(binding_name, innerTy);
                // `a ?? b`'s default is the payload's: an integer literal takes
                // its width (`delay(n) ?? 0` over `?i64`), as `unwrapOr`'s did.
                if (std.mem.eql(u8, binding_name, ast.nullish_binding_name)) nullishPayload = innerTy;
            } else {
                // Check for type guard call: `if (guardName(arg, ...))`
                // Narrow the argument's type in the then-branch.
                // Decision 8 §4 — `if (x is T)` narrows `x` to `T` inside the
                // branch. It is the same channel C5 built for the type-guard fn
                // form (`-> x is T`), which is why both write into
                // `narrowings` rather than growing a second narrowing
                // mechanism — and so does the null test below it.
                if (isNarrowingOf(i.cond.*)) |n| {
                    const tested = try resolveTypeRef(env, typeTokenRef(env, n.ref) orelse runtimeTokenRef(env, n.ref) orelse n.ref);
                    // Decision 810 (1) — over a union, the member tested, its
                    // arguments from the value's own type.
                    const member = if (typeTokenRef(env, n.ref) == null and runtimeTokenRef(env, n.ref) == null) testedUnionMember(env, n.name, tested) else null;
                    try narrowings.append(env.arena, .{ .name = n.name, .then_ = member orelse tested });
                }
                // The null test: `if (x != null)` rebinds `x` to the `?T`'s
                // payload inside the branch, `if (x == null)` rebinds it in the
                // ELSE branch, and `&&` / `||` / `not` combine them. Before
                // this the body still saw a `?Record`, so a field read off it
                // was a fresh type variable and commonJS — which needs the
                // receiver's type to know `.length()` is a PROPERTY — emitted a
                // call on a number where erlang, dispatching dynamically,
                // happened to answer.
                try collectCondNarrowings(env, i.cond.*, &narrowings);
                if (i.cond.* == .call) {
                    const ci = i.cond.call.kind.call;
                    if (env.typeGuardFns.get(ci.callee)) |guardInfo| {
                        if (guardInfo.paramIndex < ci.args.len) {
                            const argExpr = ci.args[guardInfo.paramIndex].value.*;
                            if (argExpr == .identifier and argExpr.identifier.kind == .ident) {
                                const guardArgName = argExpr.identifier.kind.ident;
                                const argTyped = try inferExprTyped(env, argExpr);
                                const argTy = argTyped.getType().deref();
                                const narrowed: *T.Type = switch (argTy.*) {
                                    .named => |n| if (std.mem.eql(u8, n.name, "optional") and n.args.len == 1)
                                        n.args[0]
                                    else if (std.mem.eql(u8, n.name, guardInfo.narrowedTypeName))
                                        argTy
                                    else
                                        try env.namedType(guardInfo.narrowedTypeName),
                                    else => try env.namedType(guardInfo.narrowedTypeName),
                                };
                                try narrowings.append(env.arena, .{ .name = guardArgName, .then_ = narrowed });
                            }
                        }
                    }
                }
                try unifyAt(env, try env.namedType("bool"), condTyped.getType(), loc);
            }

            // Narrow for the then-branch, restore, then narrow for the else.
            var snapshots: std.ArrayListUnmanaged(PatternBindingSnapshot) = .empty;
            defer snapshots.deinit(env.arena);
            for (narrowings.items) |n| {
                if (n.then_) |ty| try bindNarrowed(env, n.name, ty, &snapshots);
            }

            const thenTyped = try inferStmtsTyped(env, i.then_);

            try restorePatternBindings(env, snapshots.items);
            snapshots.clearAndFree(env.arena);

            const elseTyped = if (i.else_) |els| blk: {
                for (narrowings.items) |n| {
                    if (n.else_) |ty| try bindNarrowed(env, n.name, ty, &snapshots);
                }
                const savedExpected = env.expectedType;
                if (nullishPayload) |p| env.expectedType = p;
                defer env.expectedType = savedExpected;
                const typed = try inferStmtsTyped(env, els);
                try restorePatternBindings(env, snapshots.items);
                snapshots.clearAndFree(env.arena);
                break :blk typed;
            } else null;

            const bodyType = if (lastNonComment(thenTyped)) |t| t.expr.getType() else try env.namedType("void");
            const elseType = if (elseTyped) |els| blk: {
                if (lastNonComment(els)) |t| break :blk t.expr.getType();
                break :blk try env.namedType("void");
            } else try env.namedType("void");

            // Decision 2 — a block is not a value, so the branches of an `if`
            // only have to agree when the `if` is used as one. A branch whose
            // last statement is a STATEMENT (an assignment, a `val`/`var`
            // binding, a loop) has no value to agree with, and unifying the
            // two used to red a legitimate shape:
            //
            //     if (pred(x)) { out = out.append([x]); } else { taking = false; }
            //
            // — "expected array, got bool". A library in this repository
            // writes it in a `takeWhile` / `skipWhile`, and so does a plain
            // fn of the same shape. Only the row that removes
            // block-as-value outright can delete the unification entirely; this
            // narrows it to the branches that do produce a value.
            //
            // Decision 8 §3.2 — when both branches DO produce a value and the
            // two disagree, that is not an error: the `if` is their union, the
            // same answer `caseTypeFromArms` already gives a `case`. Branches
            // that agree still unify, so a branch pins the other's type
            // variables exactly as before.
            var ifType = bodyType;
            if (elseTyped != null and stmtsYieldValue(thenTyped) and stmtsYieldValue(elseTyped.?)) {
                if (caseArmTypesAgree(bodyType, elseType)) {
                    try unifyAt(env, bodyType, elseType, loc);
                } else {
                    ifType = unionOf(env, &.{ bodyType, elseType }) catch |err| return locateLast(env, err, loc);
                    const u = ifType.deref();
                    if (u.* == .union_) {
                        try env.unionOrigins.put(env.arena, u, .{ .loc = loc, .kind = "if" });
                        const armTypes = try env.arena.alloc(?*T.Type, 2);
                        armTypes[0] = bodyType;
                        armTypes[1] = elseType;
                        try env.unionValues.put(env.arena, loc, .{ .type_ = ifType, .arms = armTypes });
                    }
                }
            }
            return TypedExpr{ .branch = .{ .loc = loc, .type_ = ifType, .kind = .{ .if_ = .{
                .cond = condPtr,
                .binding = i.binding,
                .then_ = thenTyped,
                .else_ = elseTyped,
            } } } };
        },

        .tryCatch => |tc| return inferTryCatch(env, tc, loc),
    };
}

/// Decision 595 (5) — a `try` of the region `region` failing with the
/// `Result` `rawTy`: the first fixes the region's one error type, every other
/// must fail with it — a second type is `try-region-errors-differ`, at that
/// `try`, naming both.
fn joinTryRegion(env: *Env, region: *envMod.TryRegion, rawTy: *T.Type, loc: ast.Loc) InferError!void {
    region.tries += 1;
    const rt = rawTy.deref();
    const errTy: *T.Type = if (rt.* == .named and std.mem.eql(u8, rt.named.name, "Result") and rt.named.args.len >= 2)
        rt.named.args[1]
    else
        try env.freshVar();
    const first = region.err orelse {
        region.err = errTy;
        region.errLoc = loc;
        return;
    };
    unifyUnlocated(env, first, errTy) catch {
        const want = try errorMod.typeLabelAlloc(env.arena, first);
        const got = try errorMod.typeLabelAlloc(env.arena, errTy);
        env.lastError = TypeError.custom(
            try std.fmt.allocPrint(env.arena, "try-region-errors-differ: every `try` in a region fails with one error type — this region fails with {s}, and this `try` with {s}; handle this failure on the spot (`try … catch …`) or convert it (`catch throw …`)", .{ want, got }),
            "A region's `catch` handles one error type: the first `try` written in it fixes it.",
        ).withLoc(loc);
        return error.TypeError;
    };
}

/// Decision 525 — the statements of a block `{ … }` (`case true { _ { … } }`),
/// or null when `e` is no block.
fn blockStmtsOf(e: ast.Expr) ?[]const ast.Stmt {
    if (e != .collection or e.collection.kind != .case) return null;
    const c = e.collection.kind.case;
    if (!c.isBlock or c.arms.len != 1 or c.arms[0].body != .function) return null;
    return c.arms[0].body.function.kind.body;
}

/// Decision 595 (3), (4) — whether a handler block leaves on every path it
/// ends on: its last statement is a `throw`, a `return`, a `break` or a
/// `continue`, so it answers no fallback of its own.
fn handlerBlockLeaves(body: []const ast.Stmt) bool {
    var i = body.len;
    while (i > 0) {
        i -= 1;
        const e = body[i].expr;
        if (e == .literal and e.literal.kind == .comment) continue;
        return e == .jump and switch (e.jump.kind) {
            .throw_, .@"return", .@"break", .@"continue" => true,
            else => false,
        };
    }
    return false;
}

/// `try … catch` (decisions 431, 537, 595). Two shapes share the node:
///
///   - the operand form, `try e catch h` with no `try` inside `e`: `e` is a
///     `Result` and the handler answers its `Error`; `e catch h` with no `try`
///     at all is `try-region-cannot-fail` (595 (7), 783);
///   - a region (`tc.region`), the block `try { … }` or a left side holding a
///     `try`: every `try` written in it hands its failure here (595 (1)), all
///     with one error type (595 (5)), and the region answers the success
///     value itself. A region with no `try` is `try-region-cannot-fail`.
///
/// The handler is a fallback expression, a `throw`, a block whose value is
/// the fallback, or a block with a binder `{ e -> … }` — the binder bound to
/// the error like a `case` arm's (595 (3)). An empty block is `catch-empty`
/// (595 (4)). The handler's own `try`s belong to the region around this one,
/// or the function (595 (6)).
fn inferTryCatch(env: *Env, tc: anytype, loc: ast.Loc) InferError!TypedExpr {
    var region: envMod.TryRegion = .{};
    const exprTyped = blk: {
        if (!tc.region) break :blk try inferExprTyped(env, tc.expr.*);
        const saved = env.tryRegion;
        env.tryRegion = &region;
        defer env.tryRegion = saved;
        break :blk try inferExprTyped(env, tc.expr.*);
    };
    const exprPtr = try makeTypedPtr(env, exprTyped);
    const rawTy = exprTyped.getType();
    var errTy: *T.Type = undefined;
    const resultTy: *T.Type = if (tc.region) blk: {
        if (region.tries == 0) {
            env.lastError = TypeError.custom(
                "try-region-cannot-fail: this region holds no `try`, so its `catch` handles nothing — write `try` before each call that can fail, or drop the `try { … } catch`",
                "A `try { … } catch …` handles the failures of the `try`s written in its block.",
            ).withLoc(loc);
            return error.TypeError;
        }
        errTy = region.err orelse try env.freshVar();
        break :blk rawTy;
    } else blk: {
        // Decision 595 (7), 783 — `e catch h` whose `e` holds no `try` is a
        // region that cannot fail, whatever `e` answers: a `Result`'s failure
        // reaches a `catch` only through a `try` (`try f() catch h`).
        const d = rawTy.deref();
        if (!tc.tryKeyword) {
            env.lastError = TypeError.custom(
                "try-region-cannot-fail: this `catch` closes a region that holds no `try`, so it handles nothing — write `try` before the call that can fail (`try f() catch …`), or drop the `catch`",
                "A `catch` handles the failures of the `try`s written on its left.",
            ).withLoc(loc);
            return error.TypeError;
        }
        const ok = try tryUnwrapOrError(env, rawTy, loc);
        errTy = if (d.* == .named and std.mem.eql(u8, d.named.name, "Result") and d.named.args.len >= 2) d.named.args[1] else try env.freshVar();
        break :blk ok;
    };

    // Decision 595 (4) — `catch { }` swallows the failure in silence.
    const handlerBlock = blockStmtsOf(tc.handler.*);
    if (handlerBlock) |body| {
        var any = false;
        for (body) |st| {
            if (st.expr == .literal and st.expr.literal.kind == .comment) continue;
            any = true;
        }
        if (!any) {
            env.lastError = TypeError.custom(
                "catch-empty: an empty `catch { }` swallows the failure in silence — handle it with a value, a statement or a `throw`, or leave it to propagate",
                "Write the fallback value, the statement that handles the failure, or `throw` to make it the function's; or drop the `catch` and let the `try` propagate.",
            ).withLoc(tc.handler.getLoc());
            return error.TypeError;
        }
    }

    const prevUseConstruct = enterUseConstruct(env, "a `try` / `catch` handler");
    defer env.useConstruct = prevUseConstruct;
    var snapshots: std.ArrayListUnmanaged(PatternBindingSnapshot) = .empty;
    if (tc.binder) |b| try saveAndBindPatternName(env, &snapshots, b, errTy);
    const handlerTyped = try inferExprTyped(env, tc.handler.*);
    try restorePatternBindings(env, snapshots.items);
    const handlerPtr = try makeTypedPtr(env, handlerTyped);
    const handlerTy = handlerTyped.getType().deref();
    const effectiveTy = switch (handlerTy.*) {
        .func => |f| f.ret,
        else => handlerTyped.getType(),
    };
    // The handler's value is the other way the expression ends. A
    // `null` (or any `?U`) handler makes the whole an optional of the
    // success value — `try await loadPost(id) catch null` is a `?Post`
    // (maintainer, 24-box-1): the success value is a present `Post`,
    // the handler the absent one. Any other handler must be the
    // success type, and a mismatch is located at the handler. A block
    // that leaves (`throw`, `return`) answers no value.
    var outTy = resultTy;
    const leaves = if (handlerBlock) |body| handlerBlockLeaves(body) else false;
    const voidHandler = effectiveTy.isNamed("void");
    if (!leaves and !(voidHandler and handlerBlock == null) and !(voidHandler and resultTy.isNamed("void"))) {
        const eff = effectiveTy.deref();
        const isOpt = eff.* == .named and std.mem.eql(u8, eff.named.name, "optional") and eff.named.args.len == 1;
        const resIsOpt = resultTy.deref().* == .named and std.mem.eql(u8, resultTy.deref().named.name, "optional");
        if (isOpt and !resIsOpt) {
            try unifyAt(env, eff.named.args[0], resultTy, tc.handler.getLoc());
            outTy = effectiveTy;
        } else {
            try unifyAt(env, resultTy, effectiveTy, tc.handler.getLoc());
        }
    }
    return TypedExpr{ .branch = .{ .loc = loc, .type_ = outTy, .kind = .{ .tryCatch = .{
        .expr = exprPtr,
        .handler = handlerPtr,
        .tryKeyword = tc.tryKeyword,
        .region = tc.region,
        .binder = tc.binder,
    } } } };
}

/// Decision 105 — the three loop keywords are statements typed `void`; the
/// annotated `loop` is an expression worth its wrapper (`inferGeneratorLoop`).
fn inferLoopExpr(env: *Env, lp: ast.LoopExprOf(.untyped), loc: ast.Loc) InferError!TypedExpr {
    if (lp.generator) |eff| return inferGeneratorLoop(env, lp, eff, loc);
    // Decision 357 — a loop runs its body any number of times: no `use` in it.
    const prevUseConstruct = enterUseConstruct(env, "a loop");
    defer env.useConstruct = prevUseConstruct;
    const iterTyped = try inferExprTyped(env, lp.iter.*);
    const iterPtr = try makeTypedPtr(env, iterTyped);
    const iterTy = iterTyped.getType().deref();

    // The `for` parameter binds the ITEM of what is iterated: the element of
    // an array, the integer of a range, the `T` of a generator. Nothing else
    // is iterable, and a `bool` is a `while`. An unresolved type variable
    // stays lenient, as every effect check does.
    var itemTy: ?*T.Type = null;
    // `while (x != null) { … }` — the body runs only where the condition
    // held, so it reads the names the condition narrows as an `if`'s
    // then-branch does; restored when the body ends.
    var whileSnapshots: std.ArrayListUnmanaged(PatternBindingSnapshot) = .empty;
    defer whileSnapshots.deinit(env.arena);
    if (lp.condition) {
        // `while (cond) { … }` / `loop { … }` — the condition is a `bool`.
        try unifyAt(env, try env.namedType("bool"), iterTyped.getType(), loc);
        var narrowings: std.ArrayListUnmanaged(CondNarrowing) = .empty;
        defer narrowings.deinit(env.arena);
        try collectCondNarrowings(env, lp.iter.*, &narrowings);
        for (narrowings.items) |n| {
            if (n.then_) |ty| try bindNarrowed(env, n.name, ty, &whileSnapshots);
        }
    } else if (lp.awaitLoop) {
        // `for await (s) { x -> … }` — a `@AsyncIter<T>` where there is an await
        // channel (decision 122); the loop param binds `T`, a `@Result` when
        // `T` is one (no implicit `try`).
        if (env.starFn == null or !env.starFn.?.allowsAwait) {
            if (try refuseBehindAlias(env, "for await", loc)) return error.TypeError;
            env.lastError = TypeError.custom(
                try effectChain.refusal(env.arena, diagnostics.await_without_async, .await_, env.fnEffect),
                "`for await` suspends at every item: it needs an await channel — write `async fn` (or `component fn` / `async iter fn`), or a `stream` loop.",
            ).withLoc(loc);
            return error.TypeError;
        }
        if (iterTy.* == .named and std.mem.eql(u8, iterTy.named.name, "AsyncIter") and iterTy.named.args.len >= 1) {
            itemTy = try markResultSource(env, iterTy.named.args[0], .for_item);
            try env.instanceLowerings.put(lp.loc, .{ .sequence_next = .stream });
        } else if (iterTy.* != .typeVar) {
            env.lastError = TypeError.custom(
                diagnostics.for_await_expects_stream ++ ": `for await` expects an `AsyncIter<T>` value",
                "An `Iter<T>` is iterated by `for (it) { x -> … }`; only an `AsyncIter` suspends between items.",
            ).withLoc(loc);
            return error.TypeError;
        }
    } else if (iterTy.isNamed("bool")) {
        env.lastError = TypeError.custom(
            diagnostics.for_over_condition ++ ": `for` iterates a collection, a range or an iterator — a condition is a `while`",
            "Write `while (cond) { … }`; it repeats while the condition holds and binds nothing.",
        ).withLoc(loc);
        return error.TypeError;
    } else if (iterTy.* == .named) {
        const n = iterTy.named;
        if (std.mem.eql(u8, n.name, "Range")) {
            // `for (a..b) { i -> … }` — a range counts in integers.
            itemTy = try env.namedType("i32");
        } else if (n.args.len >= 1 and std.mem.eql(u8, n.name, "array")) {
            itemTy = n.args[0];
        } else if (n.args.len >= 1 and std.mem.eql(u8, n.name, "AsyncIter")) {
            env.lastError = TypeError.custom(
                diagnostics.for_over_stream ++ ": an `AsyncIter` suspends between items — iterate it with `for await`",
                "`for await (s) { x -> … }` where there is an await channel.",
            ).withLoc(loc);
            return error.TypeError;
        } else if (n.args.len >= 1 and std.mem.eql(u8, n.name, "Iter")) {
            // Decision 122 — `for` over any `@Iter<X>` is legal in any
            // function and hands over each `X`, a `@Result` when `X` is one:
            // there is no implicit `try`.
            itemTy = try markResultSource(env, n.args[0], .for_item);
            // 144 B-128 — the loop steps a sequence, which erlang and beam
            // walk lazily (a generator is a process there).
            try env.instanceLowerings.put(lp.loc, .{ .sequence_next = .iterator });
        }
    } else if (iterTy.* == .typeVar) {
        // An iterable nothing typed yet — an iterator method's answer
        // (`gen().take(3)`) — may be a sequence too.
        try env.instanceLowerings.put(lp.loc, .{ .sequence_next = .iterator });
    }
    for (lp.params) |p| try env.bind(p, itemTy orelse try env.freshVar());

    // The loop's own label is a `break :label` / `continue :label` target for
    // its body; the body is one loop deeper and a bare `break` leaves it.
    const prevLabelsLen = env.labelStack.items.len;
    defer env.labelStack.shrinkRetainingCapacity(prevLabelsLen);
    if (lp.label) |lbl| try env.labelStack.append(env.arena, lbl);
    const prevBreakScope = env.breakScope;
    env.breakScope = .loop;
    env.loopDepth += 1;
    defer {
        env.loopDepth -= 1;
        env.breakScope = prevBreakScope;
    }
    const typedBody = try inferStmtsTyped(env, lp.body);
    if (whileSnapshots.items.len > 0) try restorePatternBindings(env, whileSnapshots.items);
    return TypedExpr{ .loop = .{
        .loc = loc,
        .type_ = try env.namedType("void"),
        .keyword = lp.keyword,
        .generator = null,
        .iter = iterPtr,
        .indexRange = null,
        .params = lp.params,
        .paramsLoc = lp.paramsLoc,
        .condition = lp.condition,
        .body = typedBody,
        .awaitLoop = lp.awaitLoop,
        .label = lp.label,
    } };
}

/// Decision 125 — `iter …` / `stream …`: the body is a generator scope with
/// exactly the iterator's / stream's capabilities, worth `@Iter<T>` /
/// `@AsyncIter<T>`. `T` is the type of its `yield` / `break v`; when the body has
/// `throw` / `try` of its own the item becomes `@Result<U, E>` on its own,
/// `U` from the `yield`s and `E` from the `throw` / `try`s. The scope is
/// closed: the enclosing fn's effect, labels, `use` anchor and throw channel
/// are all replaced for the body and restored after it, so a `use` or an
/// `await` the prefix does not grant is refused inside it whatever the fn
/// grants, and a `break :outer` / `continue :outer` naming an enclosing loop
/// is refused as crossing the border. The loop itself is one loop deep for
/// its body: a bare `break` ends it (and so the sequence), a `continue`
/// starts its next round.
fn inferGeneratorLoop(env: *Env, lp: ast.LoopExprOf(.untyped), eff: ast.EffectKind, loc: ast.Loc) InferError!TypedExpr {
    // Decision 357 — its body runs on demand, at each `next`: no `use` in it.
    const prevUseConstruct = enterUseConstruct(env, "an `iter` / `stream` loop");
    defer env.useConstruct = prevUseConstruct;
    const fails = ast.bodyFails(lp.body);
    const errTy: ?*T.Type = if (fails) try env.freshVar() else null;
    const item: *T.Type = if (errTy) |et|
        try env.namedTypeArgs("Result", &.{ try env.freshVar(), et })
    else
        try env.freshVar();
    if (fails) try noteInferredResult(env, item, lp.body);
    const wrapper = try env.namedTypeArgs(eff.returnWrapper(), &.{item});
    const iterTyped = try inferExprTyped(env, lp.iter.*);
    const iterPtr = try makeTypedPtr(env, iterTyped);

    const prevStarFn = env.starFn;
    const prevFnEffect = env.fnEffect;
    const prevThrowCtx = env.throwContext;
    // Decision 595 — a region's `try`s stop at a function's border.
    const prevTryRegion = env.tryRegion;
    env.tryRegion = null;
    defer env.tryRegion = prevTryRegion;
    const prevInContextFn = env.inContextFn;
    const prevLoopDepth = env.loopDepth;
    const prevBreakScope = env.breakScope;
    const prevClosedLabels = env.closedLabels;
    const prevAliasWrapper = env.aliasWrapper;
    const prevReturnWhole = env.returnWhole;
    const prevInferredErrLoop = env.inferredErrorScope;
    const prevLabels = try env.arena.dupe([]const u8, env.labelStack.items);
    defer {
        env.inferredErrorScope = prevInferredErrLoop;
        env.starFn = prevStarFn;
        env.fnEffect = prevFnEffect;
        env.throwContext = prevThrowCtx;
        env.inContextFn = prevInContextFn;
        env.loopDepth = prevLoopDepth;
        env.breakScope = prevBreakScope;
        env.closedLabels = prevClosedLabels;
        env.aliasWrapper = prevAliasWrapper;
        env.returnWhole = prevReturnWhole;
        env.labelStack.shrinkRetainingCapacity(0);
        env.labelStack.appendSlice(env.arena, prevLabels) catch {};
        env.generatorLoopDepth -= 1;
    }
    env.closedLabels = prevLabels;
    env.labelStack.shrinkRetainingCapacity(0);
    if (lp.label) |lbl| try env.labelStack.append(env.arena, lbl);
    env.starFn = starCtxFromEffect(eff, wrapper, lp.label);
    env.starFn.?.markedLambda = lp.markedLambda;
    env.fnEffect = eff;
    // `throw` / a failing `try` emit `Error(e)` as the last item when the
    // item became a `@Result` (decision 122); with no `throw` / `try` in the
    // body the channel is closed.
    env.throwContext = if (errTy) |et| .{ .result = et } else .plain;
    env.inferredErrorScope = errTy != null;
    env.inContextFn = false;
    env.aliasWrapper = null;
    env.returnWhole = null;
    // Decision 584 (2) — a marked lambda's loop is its function body: no loop
    // encloses its top level, so a `continue` there is `continue-outside-loop`
    // (a bare `break` still ends the generator scope).
    env.loopDepth = if (lp.markedLambda) 0 else 1;
    env.breakScope = .loop;
    env.generatorLoopDepth += 1;

    const typedBody = try inferStmtsTyped(env, lp.body);
    return TypedExpr{ .loop = .{
        .loc = loc,
        .type_ = wrapper,
        .keyword = lp.keyword,
        .generator = eff,
        .prefixedKeyword = lp.prefixedKeyword,
        .iter = iterPtr,
        .indexRange = null,
        .params = lp.params,
        .paramsLoc = lp.paramsLoc,
        .condition = true,
        .body = typedBody,
        .awaitLoop = false,
        .label = lp.label,
    } };
}
/// Decision 583 — every function is typed where it is written: a lambda bound
/// to a `val` / `var` with no annotation — a local or a module-level one,
/// with parameters or none — is typed by nothing (a later call no longer
/// types it, 328 amended), and is refused at the lambda.
fn refuseUntypedLambdaBinding(env: *Env, value: ast.Expr) InferError!void {
    if (value != .function) return;
    const fk = value.function.kind;
    if (fk.syntax == .asyncBlock or fk.marker != null or (fk.syntax == .fnExpr and fk.isTyped())) return;
    const msg = try std.fmt.allocPrint(env.arena, "{s}: nothing types this lambda — write fn(n: T) -> R {{ … }} or type the val", .{diagnostics.lambda_untyped});
    env.lastError = TypeError.custom(msg, "A lambda `{ x -> … }` is written where its position fixes its type: the parameter it is passed to, an annotated `val`, a typed return (decision 583).").withLoc(value.function.loc);
    return error.TypeError;
}

/// Infer type for binding expressions (variable declarations and assignments)
fn inferBindingExpr(env: *Env, b: ast.BindingExprOf(.untyped), loc: ast.Loc) InferError!TypedExpr {
    return switch (b.kind) {
        .localBind => |lb| {
            try refuseValuelessIf(env, lb.value.*);
            // 01 R8 — a refusal in the annotation needs a location; the
            // binding carries none of its own for the annotation, so an
            // unlocated one reds at the `val`. (Setting `typeRefLoc` instead
            // would also enter every unresolved name into C10's pending list.)
            const annType: ?*T.Type = if (lb.typeAnnotation) |ann|
                resolveAnnotationAt(env, ann, loc, lb.typeLoc) catch |err| return locateTypeRefError(env, err, loc)
            else
                null;
            if (annType == null) try refuseUntypedLambdaBinding(env, lb.value.*);
            // Feed a `fn(...) -> ...` annotation into a lambda RHS so its
            // params are typed from context (mirrors `inferDeclTyped`).
            // Decision 148 — a local closure called only at statement
            // position (`val bump = { -> n = n + 1; }; bump();`) may write a
            // captured `var`.
            if (lb.value.* == .function and env.statementClosures.contains(lb.name)) env.nextLambdaExempt = true;
            defer env.nextLambdaExempt = false;
            const valTyped = if (annType != null and lb.value.* == .function)
                try inferFunctionExprExpected(env, lb.value.function, lb.value.function.loc, annType, false)
            else
                // 00 · 01-checker — the annotation is this position's expected
                // type (`val t: Token = .Color.Red.500;`).
                try inferExprTypedExpecting(env, lb.value.*, annType);
            const valPtr = try makeTypedPtr(env, valTyped);
            // A behavior annotation takes an implementer, as a parameter does.
            if (annType) |at| try unifyArgument(env, at, valTyped.getType(), lb.value.getLoc());
            // The annotation is the DECLARED type — bind it, not the RHS type
            // (`val head: ?i32 = 5;` must bind `?i32`).
            const bindTy = annType orelse valTyped.getType();
            if (annType == null and isEmptyArrayLiteral(lb.value.*))
                try env.birthWarnings.append(env.arena, .{ .name = lb.name, .mutable = lb.mutable, .type_ = bindTy, .loc = loc });
            try noteTypeValue(env, lb.name, lb.value.*, annType == null and !lb.mutable);
            if (lb.mutable) try env.bind(lb.name, bindTy) else try env.bindVal(lb.name, bindTy);
            return TypedExpr{ .binding = .{ .loc = loc, .type_ = bindTy, .kind = .{ .localBind = .{
                .name = lb.name,
                .value = valPtr,
                .mutable = lb.mutable,
                .typeAnnotation = lb.typeAnnotation,
            } } } };
        },

        .assign => |a| {
            const prevExpected = env.expectedType;
            const valTyped = inferExprTyped(env, a.value.*) catch |err| {
                env.expectedType = prevExpected;
                return err;
            };
            env.expectedType = prevExpected;
            const valPtr = try makeTypedPtr(env, valTyped);

            return TypedExpr{
                .binding = .{
                    .loc = loc,
                    .type_ = valTyped.getType(),
                    .kind = .{
                        .assign = .{
                            .target = switch (a.target) {
                                .name => |name| blk: {
                                    if (env.lookup(name)) |ty| {
                                        try refuseValAssign(env, name, loc);
                                        try refuseCapturedVarWrite(env, name, loc);
                                        // A narrowed `var` is assigned its DECLARED type, and
                                        // the assignment ends the narrowing.
                                        const declared = env.narrowedDecl.get(name);
                                        // A `var` typed by a behavior takes an implementer.
                                        try unifyArgument(env, declared orelse ty, valTyped.getType(), loc);
                                        // Decision 264 — `n += v` is checked against `n`'s type.
                                        if (a.op == .plusAssign) try env.divisions.put(loc, declared orelse ty);
                                        if (declared) |d| {
                                            const keepDepth = env.localDepth.get(name);
                                            const prevSuppress = env.suppressDepthNote;
                                            env.suppressDepthNote = true;
                                            defer env.suppressDepthNote = prevSuppress;
                                            try env.bind(name, d);
                                            if (keepDepth) |kd| try env.localDepth.put(env.arena, name, .{ .depth = kd.depth, .ty = d });
                                        }
                                    } else {
                                        env.lastError = try unboundAt(env, name, loc);
                                        return error.TypeError;
                                    }
                                    break :blk .{ .name = name };
                                },
                                .fieldAccess => |fa| blk: {
                                    const recvTyped = try inferExprTyped(env, fa.receiver.*);
                                    try refuseRecordFieldAssign(env, fa.receiver.*, recvTyped.getType(), fa.field, loc);
                                    if (a.op == .plusAssign) try env.divisions.put(loc, valTyped.getType());
                                    const recvPtr = try makeTypedPtr(env, recvTyped);
                                    break :blk .{ .fieldAccess = .{ .receiver = recvPtr, .field = fa.field } };
                                },
                            },
                            .op = a.op,
                            .value = valPtr,
                        },
                    },
                },
            };
        },

        .localBindDestruct => |lb| {
            const valTyped = try inferExprTyped(env, lb.value.*);
            const valPtr = try makeTypedPtr(env, valTyped);
            // Destructuring a hook (`val {v, s} = use state(0)`) is lenient: the
            // hook's Return type `R` need not be a record, so unknown fields bind
            // to fresh type vars rather than triggering a `notARecord` error.
            if (isUseHookValue(lb.value)) {
                try bindUseDestructure(env, lb.pattern, valTyped.getType(), loc);
                return TypedExpr{ .binding = .{ .loc = loc, .type_ = valTyped.getType(), .kind = .{ .localBindDestruct = .{
                    .pattern = lb.pattern,
                    .value = valPtr,
                    .mutable = lb.mutable,
                } } } };
            }
            // Bind destructured names into the environment.
            const derefedTy = valTyped.getType().deref();
            switch (lb.pattern) {
                .names => |n| {
                    const typeName: []const u8 = switch (derefedTy.*) {
                        .named => |nm| nm.name,
                        else => "",
                    };
                    const maybeDef = env.typeDefs.get(typeName);
                    // For concrete named types that are not records/structs, reject destructuring.
                    if (maybeDef == null and typeName.len > 0 and derefedTy.* == .named) {
                        env.lastError = TypeError.notARecord(typeName).withLoc(loc);
                        return error.TypeError;
                    }
                    for (n.fields) |fld| {
                        const fieldTy = if (maybeDef) |td|
                            if (td.findField(fld.field_name)) |f| f.type_ else try env.freshVar()
                        else
                            try env.freshVar();
                        try env.bind(fld.bind_name, fieldTy);
                    }
                },
                .tuple_ => |t| {
                    const tupleArgs: []*T.Type = switch (derefedTy.*) {
                        .named => |n| if (std.mem.eql(u8, n.name, "tuple")) n.args else &.{},
                        else => &.{},
                    };
                    for (t, 0..) |nm, i| {
                        const elemTy = if (i < tupleArgs.len) tupleArgs[i] else try env.freshVar();
                        try env.bind(nm, elemTy);
                    }
                },
                // 01 R5 — `val Circle(r) = s;` / `val [..rest] = xs;` bind
                // through the walk a `case` arm uses, typed by the subject.
                .list, .ctor => |pat| try bindDestructPattern(env, pat, valTyped.getType(), lb.mutable, loc),
            }
            return TypedExpr{ .binding = .{ .loc = loc, .type_ = valTyped.getType(), .kind = .{ .localBindDestruct = .{
                .pattern = lb.pattern,
                .value = valPtr,
                .mutable = lb.mutable,
            } } } };
        },
    };
}

/// 01 R5 — a pattern in binding position: `val Circle(r) = s;`,
/// `val Person(name, age) = p;`, `val [..rest] = xs;`.
///
/// The bare form has no failure path of its own, so it is legal only where the
/// pattern matches **every** value of the subject's type: a one-variant `type`,
/// a record's own constructor, a list pattern that is only a spread. Anything
/// that can fail to match is refused at the binding (`refutable-val-pattern`),
/// naming the two forms that say what a mismatch does — `val assert <Pattern>
/// = e;` (fatal) and `case`. Nothing is left for a backend to decide: every
/// program that checks destructures without a test.
///
/// The names land in the enclosing scope — the snapshots the walk collects
/// are dropped, as `val assert` does — and a `val` binds them as `val`s.
fn bindDestructPattern(env: *Env, pattern: ast.Pattern, subjectType: *T.Type, mutable: bool, loc: ast.Loc) InferError!void {
    var snapshots: std.ArrayListUnmanaged(PatternBindingSnapshot) = .empty;
    defer snapshots.deinit(env.arena);
    const covers = try destructCovers(env, pattern, subjectType);
    if (covers) {
        const st = subjectType.deref();
        const record: ?envMod.TypeDef = if (pattern == .variant and st.* == .named) env.lookupTypeDef(st.named.name) else null;
        if (record != null and record.? == .record) {
            const rec = record.?.record;
            for (pattern.variant.payload.literals, 0..) |a, i| {
                // A generic record's field types are its declaration's
                // cells; the subject's instantiation is not read here.
                const fieldTy = if (rec.genericParams.len == 0) rec.fields[i].type_ else try env.freshVar();
                bindPatternNamesForSubject(env, a, fieldTy, &snapshots) catch |err| return locateLast(env, err, loc);
            }
        } else {
            bindPatternNamesForSubject(env, pattern, subjectType, &snapshots) catch |err| return locateLast(env, err, loc);
        }
    }
    if (!covers) {
        const msg = try std.fmt.allocPrint(
            env.arena,
            "{s}: `val <Pattern> = e;` needs a pattern that matches every value of `{s}`, and this one can fail",
            .{ diagnostics.refutable_val_pattern, try snapshotMod.typeNameOf(env.arena, subjectType) },
        );
        env.lastError = TypeError.custom(
            msg,
            "write `val assert <Pattern> = e;` (a mismatch is a fatal assert) or a `case` that says what a mismatch does",
        ).withLoc(loc);
        return error.TypeError;
    }
    if (!mutable) {
        for (snapshots.items) |sn| {
            if (env.lookup(sn.name)) |ty| try env.bindVal(sn.name, ty);
        }
    }
}

/// 144 B-22 step 13 — does a binding pattern match **every** value of
/// `subjectType`? A list pattern that is only a spread over an array; the
/// constructor of a one-variant `type`, or a record's own constructor, whose
/// every argument covers its field's type in turn — so a constructor nests
/// (`val Pair(Circle(r), n) = p;`); anything else as `patternIsIrrefutable`
/// answers.
fn destructCovers(env: *Env, pattern: ast.Pattern, subjectType: *T.Type) InferError!bool {
    const st = subjectType.deref();
    switch (pattern) {
        .list => |lst| return lst.elems.len == 0 and lst.spread != null and
            st.* == .named and std.mem.eql(u8, st.named.name, "array"),
        .variant => |v| {
            if (v.shape != .variant) return patternIsIrrefutable(env, pattern, subjectType);
            if (st.* != .named) return false;
            const bare = bareVariantName(v.name);
            const td = env.lookupTypeDef(st.named.name) orelse return false;
            switch (td) {
                .enum_ => |en| {
                    if (en.variants.len != 1 or !std.mem.eql(u8, en.variants[0].name, bare)) return false;
                    if (v.payload != .literals) return variantPayloadIrrefutable(env, subjectType, v.name, v.payload);
                    const payloadTypes = try variantPayloadTypes(env, subjectType, v.name);
                    for (v.payload.literals, 0..) |a, i| {
                        const at: ?*T.Type = if (payloadTypes) |p| (if (i < p.len) p[i] else null) else null;
                        const ok = if (at) |t| try destructCovers(env, a, t) else try patternIsIrrefutable(env, a, null);
                        if (!ok) return false;
                    }
                    return true;
                },
                .record => |rec| {
                    if (!std.mem.eql(u8, rec.name, bare) or v.payload != .literals) return false;
                    const args = v.payload.literals;
                    if (args.len > rec.fields.len or (args.len < rec.fields.len and !v.rest)) return false;
                    for (args, 0..) |a, i| {
                        const ok = if (rec.genericParams.len == 0)
                            try destructCovers(env, a, rec.fields[i].type_)
                        else
                            try patternIsIrrefutable(env, a, null);
                        if (!ok) return false;
                    }
                    return true;
                },
                .struct_ => return false,
            }
        },
        else => return patternIsIrrefutable(env, pattern, subjectType),
    }
}

/// `.Circle(…)` — a call chained onto a leading-dot head.
/// A generic type's constructor called with no written type arguments
/// (`Sort(by: .title)`): the position's expected type pins its parameters
/// (`inferCallExprWith`), so `inferExprTyped` hands the expectation on to it.
fn isUnappliedGenericCtorCall(env: *Env, c: ast.CallExprOf(.untyped)) bool {
    if (c.kind != .call) return false;
    const cc = c.kind.call;
    if (cc.receiver != null or cc.is_builtin or cc.calleeExpr != null or cc.typeArgs != null) return false;
    const td = env.lookupTypeDef(cc.callee) orelse return false;
    return td.genericParams().len > 0;
}

fn isLeadingDotCall(c: ast.CallExprOf(.untyped)) bool {
    if (c.kind != .call) return false;
    const ce = c.kind.call.calleeExpr orelse return false;
    return ce.* == .identifier and ce.identifier.kind == .dotIdent;
}

/// The name of the enum the expected type names, when it declares a variant
/// called `variant` (front 15 handover, `.Circle(radius: 1)`).
/// 144 B-10 — `en`, an enum a dot-shorthand variant resolved to, recorded in
/// `Env.implicitEnumImports` when this module neither declares nor imports
/// it by name: the one non-std module of the registry that declares it. Two
/// such modules leave it unrecorded (nothing here says which one). An enum
/// no such module declares and one std module declares `pub` (`failure`'s
/// `HostErrorName`, reached through `HostError`'s field after `import
/// {failure.HostError} from "std"`) is imported from that module the way a
/// lifted std type is (`Env.liftedStdTypes`).
fn noteImplicitEnum(env: *Env, en: []const u8) InferError!void {
    if (env.explicitTypeNames.contains(en) or env.implicitEnumImports.contains(en) or env.liftedStdTypes.contains(en)) return;
    var owner: ?[]const u8 = null;
    if (env.typeDeclRegistry) |reg| {
        var it = reg.iterator();
        while (it.next()) |e| {
            if (std.mem.startsWith(u8, e.key_ptr.*, "std/")) continue;
            if (std.mem.eql(u8, e.key_ptr.*, env.modulePath)) return;
            const d = e.value_ptr.get(en) orelse continue;
            if (d != .type_ or d.type_.shape != .enum_) continue;
            if (owner != null) return;
            owner = e.key_ptr.*;
        }
    }
    if (owner) |o| return env.implicitEnumImports.put(env.arena, en, o);
    if (std.mem.startsWith(u8, env.modulePath, "std/")) return;
    var std_owner: ?[]const u8 = null;
    var sit = env.stdModuleTypes.iterator();
    while (sit.next()) |e| for (e.value_ptr.*) |d| {
        if (d != .type_ or d.type_.shape != .enum_ or !std.mem.eql(u8, d.type_.name, en)) continue;
        if (std_owner != null) return;
        std_owner = e.key_ptr.*;
    };
    if (std_owner) |o| try env.liftedStdTypes.put(env.arena, en, o);
}

fn expectedEnumDeclaring(env: *Env, variant: []const u8) ?[]const u8 {
    const exp = env.expectedType orelse return null;
    // A `?Place` position expects a `Place` (or nothing): `.Here` is
    // `Place.Here` there too. Unqualified, commonJS emitted a bare `Here`
    // (`ReferenceError`) and beam printed the atom `'Here'`.
    const d = if (optionalInner(exp)) |inner| inner.deref() else exp.deref();
    if (d.* != .named) return null;
    const td = env.lookupTypeDef(d.named.name) orelse return null;
    if (td != .enum_) return null;
    for (td.enum_.variants) |v| {
        if (std.mem.eql(u8, v.name, variant)) return d.named.name;
    }
    return null;
}

/// A `val` annotation carries its own location (`typeLoc`, the annotation's
/// first token) but a body's type parameters are not in the generic map, so a
/// name cannot be recorded for the second pass here. Every written name — a
/// bare one and a generic application's head — is looked up at once (every
/// declaration is registered by the time a body is inferred): a name nothing
/// declares is `unknown type`, at the annotation. Any other refusal in a `val`
/// annotation is located at the value (`valueLoc`).
fn resolveAnnotationAt(env: *Env, ref: ast.TypeRef, valueLoc: ast.Loc, typeLoc: ast.Loc) InferError!*T.Type {
    const ty = try resolveTypeRef(env, ref);
    try refuseUnknownTypeName(env, ref, if (typeLoc.line != 0) typeLoc else valueLoc);
    return ty;
}

fn refuseUnknownName(env: *Env, name: []const u8, loc: ast.Loc) InferError!void {
    if (std.mem.eql(u8, name, "Self") or std.mem.eql(u8, name, ast.unknown_type_name) or std.mem.eql(u8, name, ast.inline_type_name)) return;
    if (std.mem.indexOfScalar(u8, name, '.') != null or std.mem.indexOf(u8, name, "__") != null) return;
    if (env.fnGenericMap) |gm| if (gm.contains(name)) return;
    if (env.methodGenericMap) |gm| if (gm.contains(name)) return;
    if (env.typeAliases.get(name) != null or env.typeNameDeclared(name)) return;
    if (env.ownDecls.contains(name) or env.ownTypeDecls.contains(name)) return;
    env.lastError = TypeError.unknownTypeName(name).withLoc(loc);
    return error.TypeError;
}

fn refuseUnknownTypeName(env: *Env, ref: ast.TypeRef, loc: ast.Loc) InferError!void {
    switch (ref) {
        .named => |n| try refuseUnknownName(env, n, loc),
        .array => |e| try refuseUnknownTypeName(env, e.*, loc),
        .optional => |e| try refuseUnknownTypeName(env, e.*, loc),
        .tuple_ => |es| for (es) |e| try refuseUnknownTypeName(env, e, loc),
        .labeledTuple => |lt| for (lt.elems) |e| try refuseUnknownTypeName(env, e, loc),
        .function => |f| {
            for (f.params) |p| try refuseUnknownTypeName(env, p, loc);
            try refuseUnknownTypeName(env, f.returnType.*, loc);
        },
        .generic => |b| {
            for (b.args) |a| try refuseUnknownTypeName(env, a, loc);
            if (b.is_builtin or ref.unionMembers() != null) return;
            try refuseUnknownName(env, b.name, loc);
        },
        else => {},
    }
}

/// 01 R8 — give an annotation's unlocated error the binding's location.
fn locateTypeRefError(env: *Env, err: InferError, loc: ast.Loc) InferError {
    if (env.lastError) |*e| {
        if (e.loc == null) e.loc = loc;
    }
    return err;
}

/// 01 R8 — record whether `val name = value` binds a TYPE: `value` is a name
/// that is itself a type (a primitive, a declared `type`/`behavior`, an
/// imported constructor, or another such `val`). Checked before `name` is
/// bound, so `val T = T;` cannot vouch for itself. A binding that is not one
/// clears the mark, so a value shadowing a type alias is a value.
fn noteTypeValue(env: *Env, name: []const u8, value: ast.Expr, eligible: bool) InferError!void {
    const isType = eligible and blk: {
        if (value != .identifier or value.identifier.kind != .ident) break :blk false;
        const n = value.identifier.kind.ident;
        if (env.typeDefs.contains(n) or env.assocInterfaceDecls.contains(n) or env.typeValueNames.contains(n)) break :blk true;
        const ty = env.lookup(n) orelse break :blk false;
        const d = ty.deref();
        if (d.* == .func and d.func.ret.isNamed(n)) break :blk true;
        break :blk d.isNamed(n);
    };
    if (isType) try env.typeValueNames.put(name, {}) else _ = env.typeValueNames.remove(name);
}

fn containsStr(haystack: []const []const u8, needle: []const u8) bool {
    for (haystack) |s| if (std.mem.eql(u8, s, needle)) return true;
    return false;
}

/// The nominal type name of `ty`, or null if `ty` is not a named type.
fn nominalName(ty: *T.Type) ?[]const u8 {
    const d = ty.deref();
    return switch (d.*) {
        .named => |n| n.name,
        else => null,
    };
}

/// C-04 (01 step 7) — the callee's parameters AS WRITTEN, for a call whose
/// arity is about to be judged. A `T.func` carries no `default` expressions, so
/// this is the only thing that can tell an omitted trailing default (N1) from a
/// missing required argument (N2). `null` when the declaration is not reachable
/// from here — the arity check then stays exactly what it was.
fn calleeParams(env: *Env, callee: []const u8) ?[]const ast.Param {
    if (env.fnParams.get(callee)) |ps| return ps;
    if (env.ctorParams.get(callee)) |ps| return ps;
    if (env.stdlibFnDecls.get(callee)) |fd| return fd.params;
    return null;
}

/// 00 · 01-checker — which parameter each ARGUMENT of a call lands in, when
/// that is not simply its own index.
///
/// A label claims the parameter it names (C-04), so `f(y: <path>)` against
/// `fn f(x: i32 = 0, y: Token)` writes the SECOND parameter from its FIRST
/// argument. `planDefaultFill` is the one thing that knows that mapping, so
/// this inverts its plan rather than working a second one out — the two could
/// then disagree, and the expectation would name the wrong enum.
///
/// `null` is the ordinary answer and means "argument `i` is parameter `i`":
/// every call that writes its arguments positionally, which is nearly all of
/// them, allocates nothing here — nor does a labelled call whose labels name
/// the parameters in order (the plan is the identity). A returned slice
/// carries a parameter index per argument — a complete labelled call that
/// moves an argument is planned as a reorder, like a short one — or
/// `params.len` for an argument whose parameter is not knowable (a label that
/// names no parameter, one named twice: the call is refused below). Reading no
/// expectation is right there: a wrong one would pick an enum.
fn argumentParamSlots(
    env: *Env,
    params: []const ast.Param,
    args: []const ast.CallArg,
) InferError!?[]const usize {
    var labelled = false;
    for (args) |a| {
        if (a.label != null) {
            labelled = true;
            break;
        }
    }
    if (!labelled) return null;

    const labels = try env.arena.alloc(?[]const u8, args.len);
    for (args, 0..) |a, i| labels[i] = a.label;
    const unknown = try env.arena.alloc(usize, args.len);
    @memset(unknown, params.len);
    const planned = envMod.planDefaultFill(env.arena, params, labels) catch return unknown;
    const fill = planned orelse return if (args.len == params.len) null else unknown;

    const slots = try env.arena.alloc(usize, args.len);
    @memset(slots, params.len);
    for (fill.slots, 0..) |slot, pi| {
        const ai = slot orelse continue;
        if (ai < slots.len) slots[ai] = pi;
    }
    return slots;
}

/// A default an importer can materialise at its own call site: it names no
/// binding of the declaring module. Literals (a string without a `${…}` hole),
/// `true` / `false`, `null`, a sign, and array / tuple literals of those.
pub fn isClosedDefault(e: ast.Expr) bool {
    return switch (e) {
        .literal => |l| switch (l.kind) {
            .stringLit, .numberLit, .null_ => true,
            else => false,
        },
        .identifier => |id| switch (id.kind) {
            .ident => |n| std.mem.eql(u8, n, "true") or std.mem.eql(u8, n, "false"),
            else => false,
        },
        .unaryOp => |op| isClosedDefault(op.expr.*),
        .collection => |col| switch (col.kind) {
            .grouped => |inner| isClosedDefault(inner.*),
            .arrayLit => |al| for (al.elems) |x| {
                if (!isClosedDefault(x)) break false;
            } else true,
            .tupleLit => |tl| for (tl.elems) |x| {
                if (!isClosedDefault(x)) break false;
            } else true,
            else => false,
        },
        else => false,
    };
}

/// Decision 37's update form — `Name(..base, f: v)` — reaches every backend as
/// the complete constructor call it means: one positional argument per field in
/// declaration order, the labelled value where the call names the field and
/// `base.<field>` where it does not. No backend lowers a `..` argument, and each
/// used to drop it and zip what was left (`Cfg(..b, r: 60)` built
/// `Cfg(b, 60)`). Residue: no source reaches it since decision 529 (3), and
/// decision 864 (2) deleted its name-only refusal (`inferRecordSpread` evaluates
/// any source once).
fn rewriteRecordUpdate(env: *Env, c: anytype, fields: anytype, loc: ast.Loc) InferError!void {
    const call = c.kind.call;
    var base: ?*ast.Expr = null;
    for (call.args) |a| if (a.label) |l| if (std.mem.eql(u8, l, "..")) {
        base = a.value;
    };
    const b = base orelse return;
    const args = try env.arena.alloc(ast.CallArg, fields.len);
    for (fields, 0..) |fd, fi| {
        const written: ?*ast.Expr = for (call.args) |a| {
            const l = a.label orelse continue;
            if (std.mem.eql(u8, l, fd.name)) break a.value;
        } else null;
        const value = written orelse blk: {
            // Each read gets a loc of its own — the base's line, a column no
            // source reaches — and is inferred like a written `base.field`, so
            // what a backend reads under a field access's loc (the record it
            // belongs to) is there, and never mistaken for the base's own.
            // The field index sits in the upper half of `col`: bit 32 on a
            // 64-bit host, bit 16 on wasm32 (`compiler-web`), where `usize`
            // is 32 bits and a shift by 32 does not compile.
            const bl = b.getLoc();
            const read = try env.arena.create(ast.Expr);
            read.* = .{ .identifier = .{
                .loc = .{ .line = bl.line, .col = bl.col | (@as(usize, fi + 1) << (@bitSizeOf(usize) / 2)), .expansion = bl.expansion },
                .kind = .{ .identAccess = .{ .receiver = b, .member = fd.name } },
            } };
            _ = try inferExpr(env, read.*);
            break :blk read;
        };
        args[fi] = .{ .label = null, .value = value };
    }
    const rewrite = try env.arena.create(ast.Expr);
    // An import alias already renamed the callee under this loc (decision 110).
    var rc = if (env.enumSectionRewrites.get(loc)) |prev| (if (prev.* == .call) prev.call else c) else c;
    rc.kind.call.args = args;
    rewrite.* = .{ .call = rc };
    try env.enumSectionRewrites.put(loc, rewrite);
}

/// Decision 359 — `Name(...src, f: v, ...other)`: a record's construction
/// whose fields come from spreads and labels, applied left to right, the later
/// winning. Each `src` is a value of the record's own type or of a type
/// derived from it by `Type.pick` / `omit` / `merge` (307, `Env.derivedTypes`);
/// any other type is `record-spread-type` and a `Type.partial` value
/// `record-spread-partial`, both at the `...`. A field without a default that
/// nothing supplies is `record-spread-missing-field` at the call; a label
/// written twice, or an argument without one, `record-spread-arguments`. A
/// spread at any other call is `call-spread` (267: a function call takes no
/// spread).
///
/// The call reaches the backends as the complete constructor call it means —
/// one positional argument per field, in declaration order: the last label or
/// spread that supplies it (`src.<field>`), else the field's default. A source
/// that is a name or a path of names is read where it stands; any other is
/// bound once, ahead of the construction, by a `val` in an `if (true) { … }`
/// block — the expression form every backend lowers — so it is evaluated once
/// (359 (6)). A labelled value a later spread overrides is typed against its
/// field and, when it is not a name or a plain literal, evaluated once in that
/// block after the sources, its value dropped. The rewrite is recorded under the call's loc
/// (`enumSectionRewrites`, spliced by the transform) and typed here.
fn inferRecordSpread(env: *Env, c: ast.CallExprOf(.untyped), loc: ast.Loc) InferError!TypedExpr {
    const call = c.kind.call;
    const firstSpread = for (call.args) |a| {
        if (a.label) |l| if (std.mem.eql(u8, l, ast.record_spread_label)) break a;
    } else unreachable;
    const spreadAt = firstSpread.spreadLoc orelse firstSpread.value.getLoc();
    // The record the call constructs: a plain call of a record type's name (an
    // import alias of one included, decision 110).
    const typeName: ?[]const u8 = blk: {
        if (call.receiver != null or call.calleeExpr != null or call.is_builtin) break :blk null;
        const name = env.importedTypeAliases.get(call.callee) orelse call.callee;
        if (env.namespaceTypes.contains(name)) break :blk null;
        const td = env.lookupTypeDef(name) orelse break :blk null;
        break :blk switch (td) {
            .record, .struct_ => name,
            .enum_ => null,
        };
    };
    const recName = typeName orelse {
        const what: []const u8 = if (call.receiver != null or call.calleeExpr != null) "this call" else call.callee;
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` constructs no record — a spread copies a record's fields into its constructor, and a function call takes none", .{ diagnostics.call_spread, what });
        env.lastError = TypeError.custom(msg, "Pass the arguments one by one; a function that takes an existing array declares `values: T[]` (decision 267).").withLoc(spreadAt);
        return error.TypeError;
    };
    const fields: []const envMod.FieldDef = switch (env.lookupTypeDef(recName).?) {
        .record => |r| r.fields,
        .struct_ => |st| st.fields,
        .enum_ => unreachable,
    };
    const ctorRaw = env.lookup(call.callee) orelse env.lookup(recName) orelse return error.TypeError;
    const ctor = (try instantiateGenericType(env, try instantiateCtorType(env, recName, ctorRaw))).deref();
    if (ctor.* != .func or ctor.func.params.len != fields.len) return error.TypeError;
    const params = ctor.func.params;
    const ret = ctor.func.ret;

    // Who supplies each field: the index of the last argument that does.
    const supplier = try env.arena.alloc(?usize, fields.len);
    @memset(supplier, null);
    const labelled = try env.arena.alloc(bool, fields.len);
    @memset(labelled, false);
    const saved = env.expectedType;
    defer env.expectedType = saved;
    for (call.args, 0..) |a, ai| {
        const lbl = a.label orelse {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: beside a spread, every argument of `{s}` names its field", .{ diagnostics.record_spread_arguments, recName });
            env.lastError = TypeError.custom(msg, "Write `Name(..src, field: value)`.").withLoc(a.value.getLoc());
            return error.TypeError;
        };
        if (std.mem.eql(u8, lbl, ast.record_spread_label)) {
            env.expectedType = null;
            const srcTy = try inferExpr(env, a.value.*);
            const at = a.spreadLoc orelse a.value.getLoc();
            const srcName = nominalName(srcTy);
            // A source inference has not resolved yet (an untyped lambda's
            // parameter) is the record's own type, as `..base` reads it.
            const unresolved = srcTy.deref().* == .typeVar and srcTy.deref().typeVar.state == .unbound;
            const own = unresolved or if (srcName) |n| std.mem.eql(u8, n, recName) else false;
            if (own) {
                try unifyAt(env, ret, srcTy, a.value.getLoc());
                for (supplier) |*sp| sp.* = ai;
                continue;
            }
            const lineage: ?envMod.DerivedLineage = if (srcName) |n| env.derivedTypes.get(n) else null;
            if (lineage) |lin| if (lin.partial) {
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is `Type.partial(…)`'s answer — a field of it may be null, so it is not spread into `{s}`", .{ diagnostics.record_spread_partial, srcName.?, recName });
                env.lastError = TypeError.custom(msg, "Read the fields it holds and label them (`field: p.field ?? fallback`).").withLoc(at);
                return error.TypeError;
            };
            const derived = if (lineage) |lin| for (lin.from) |f| {
                if (std.mem.eql(u8, f, recName)) break true;
            } else false else false;
            if (!derived) {
                // A record by its name; any other type — `?Pessoa`, `i32` —
                // in its source spelling.
                const isRecord = if (srcName) |n| env.lookupTypeDef(n) != null else false;
                const shown = if (isRecord) srcName.? else try snapshotMod.typeSignatureOf(env.arena, srcTy.deref());
                const msg = try std.fmt.allocPrint(env.arena, "{s}: a spread into `{s}` copies a `{s}` or a type derived from it by `Type.pick`, `Type.omit` or `Type.merge` — `{s}` is neither", .{ diagnostics.record_spread_type, recName, recName, shown });
                env.lastError = TypeError.custom(msg, "Label the fields to copy, or derive the source's type from the record (decision 307).").withLoc(at);
                return error.TypeError;
            }
            const srcFields: []const envMod.FieldDef = switch (env.lookupTypeDef(srcName.?) orelse return error.TypeError) {
                .record => |r| r.fields,
                .struct_ => |st| st.fields,
                .enum_ => &.{},
            };
            for (fields, 0..) |fd, fi| for (srcFields) |sf| {
                if (std.mem.eql(u8, sf.name, fd.name)) {
                    try unifyArgument(env, params[fi], sf.type_, a.value.getLoc());
                    supplier[fi] = ai;
                }
            };
            continue;
        }
        const idx = for (fields, 0..) |fd, fi| {
            if (std.mem.eql(u8, fd.name, lbl)) break fi;
        } else {
            const vloc = a.value.getLoc();
            const labelCol = if (vloc.col > lbl.len + 2) vloc.col - lbl.len - 2 else vloc.col;
            env.lastError = TypeError.unknownField(recName, lbl).withLoc(.{ .line = vloc.line, .col = labelCol, .expansion = vloc.expansion });
            return error.TypeError;
        };
        if (labelled[idx]) {
            const vloc = a.value.getLoc();
            const labelCol = if (vloc.col > lbl.len + 2) vloc.col - lbl.len - 2 else vloc.col;
            const msg = try std.fmt.allocPrint(env.arena, "{s}: field `{s}` of `{s}` is labelled twice", .{ diagnostics.record_spread_arguments, lbl, recName });
            env.lastError = TypeError.custom(msg, "A spread may be overridden by a label; a label is written once.").withLoc(.{ .line = vloc.line, .col = labelCol, .expansion = vloc.expansion });
            return error.TypeError;
        }
        labelled[idx] = true;
        supplier[idx] = ai;
    }
    // A labelled value a later spread overrides supplies no field, yet it is
    // written: typed against its field here, and evaluated in the
    // construction below (`overridden`).
    var overridden: std.ArrayListUnmanaged(*ast.Expr) = .empty;
    for (call.args, 0..) |a, ai| {
        const l = a.label orelse continue;
        if (std.mem.eql(u8, l, ast.record_spread_label)) continue;
        const idx = for (fields, 0..) |fd, fi| {
            if (std.mem.eql(u8, fd.name, l)) break fi;
        } else unreachable;
        if (supplier[idx] == ai) continue;
        env.expectedType = params[idx];
        const argTy = try inferExpr(env, a.value.*);
        try unifyArgument(env, params[idx], argTy, a.value.getLoc());
        const pure = isNamePath(a.value.*) or (a.value.* == .literal and a.value.literal.kind != .stringTemplate);
        if (!pure) try overridden.append(env.arena, a.value);
    }
    env.expectedType = null;
    const declared = env.ctorParams.get(recName);
    for (fields, 0..) |fd, fi| {
        if (supplier[fi] != null) continue;
        const hasDefault = if (declared) |ps| fi < ps.len and ps[fi].default != null else false;
        if (hasDefault) continue;
        const msg = try std.fmt.allocPrint(env.arena, "{s}: field `{s}` of `{s}` has no default, and no spread or label supplies it", .{ diagnostics.record_spread_missing_field, fd.name, recName });
        env.lastError = TypeError.custom(msg, "Label it (`field: value`), or spread a value that holds it.").withLoc(loc);
        return error.TypeError;
    }

    // The construction: each spread source bound once when it is not a name.
    var binds: std.ArrayListUnmanaged(ast.Stmt) = .empty;
    const sources = try env.arena.alloc(*ast.Expr, call.args.len);
    for (call.args, 0..) |a, ai| {
        sources[ai] = a.value;
        const l = a.label orelse continue;
        if (!std.mem.eql(u8, l, ast.record_spread_label) or isNamePath(a.value.*)) continue;
        const at = a.spreadLoc orelse a.value.getLoc();
        const binder = try std.fmt.allocPrint(env.arena, "__bp_spread_{d}_{d}_{d}", .{ at.line, at.col, at.expansion });
        const synth: ast.Loc = .{ .line = at.line, .col = at.col + ast.spread_synthetic_col, .expansion = at.expansion };
        const bound = try env.arena.create(ast.Expr);
        bound.* = .{ .identifier = .{ .loc = synth, .kind = .{ .ident = binder } } };
        sources[ai] = bound;
        const value = try env.arena.create(ast.Expr);
        value.* = a.value.*;
        try binds.append(env.arena, .{ .expr = .{ .binding = .{
            .loc = .{ .line = synth.line, .col = synth.col + 1, .expansion = synth.expansion },
            .kind = .{ .localBind = .{ .name = binder, .value = value, .mutable = false } },
        } } });
    }
    // Each overridden labelled value, evaluated once after the sources, in
    // the order written; its value is dropped.
    for (overridden.items) |v| try binds.append(env.arena, .{ .expr = v.* });
    const args = try env.arena.alloc(ast.CallArg, fields.len);
    for (fields, 0..) |fd, fi| {
        const ai = supplier[fi] orelse {
            const dv = try env.arena.create(ast.Expr);
            dv.* = declared.?[fi].default.?;
            args[fi] = .{ .label = null, .value = dv };
            continue;
        };
        const a = call.args[ai];
        if (a.label) |l| if (!std.mem.eql(u8, l, ast.record_spread_label)) {
            args[fi] = .{ .label = null, .value = a.value };
            continue;
        };
        // `src.<field>`, each read at a loc of its own — the source's, the
        // field index in the upper half of `col` (`rewriteRecordUpdate`).
        const src = sources[ai];
        const sl = src.getLoc();
        const read = try env.arena.create(ast.Expr);
        read.* = .{ .identifier = .{
            .loc = .{ .line = sl.line, .col = sl.col | (@as(usize, fi + 1) << (@bitSizeOf(usize) / 2)), .expansion = sl.expansion },
            .kind = .{ .identAccess = .{ .receiver = src, .member = fd.name } },
        } };
        args[fi] = .{ .label = null, .value = read };
    }
    var ctorCall = c;
    ctorCall.kind.call.callee = recName;
    ctorCall.kind.call.args = args;
    const rewrite = try env.arena.create(ast.Expr);
    if (binds.items.len == 0) {
        rewrite.* = .{ .call = ctorCall };
    } else {
        // `if (true) { val __bp_spread_… = src; …; Name(…) } else { @panic(…) }`
        // — the construction at a loc of its own, so the transform splices
        // the `if` at the call's and never meets the call again.
        const inner: ast.Loc = .{ .line = loc.line, .col = loc.col + ast.spread_synthetic_col, .expansion = loc.expansion };
        ctorCall.loc = inner;
        try binds.append(env.arena, .{ .expr = .{ .call = ctorCall } });
        const cond = try env.arena.create(ast.Expr);
        cond.* = .{ .identifier = .{ .loc = .{ .line = inner.line, .col = inner.col + 1, .expansion = inner.expansion }, .kind = .{ .ident = "true" } } };
        const panicLoc: ast.Loc = .{ .line = inner.line, .col = inner.col + 2, .expansion = inner.expansion };
        const msgLit = try env.arena.create(ast.Expr);
        msgLit.* = .{ .literal = .{ .loc = .{ .line = inner.line, .col = inner.col + 3, .expansion = inner.expansion }, .kind = .{ .stringLit = "unreachable: a record spread's construction" } } };
        const panicArgs = try env.arena.alloc(ast.CallArg, 1);
        panicArgs[0] = .{ .label = null, .value = msgLit };
        var else_ = try env.arena.alloc(ast.Stmt, 1);
        else_[0] = .{ .expr = .{ .call = .{ .loc = panicLoc, .kind = .{ .call = .{
            .receiver = null,
            .callee = "panic",
            .is_builtin = true,
            .args = panicArgs,
            .trailing = &.{},
        } } } } };
        rewrite.* = .{ .branch = .{ .loc = loc, .kind = .{ .if_ = .{
            .cond = cond,
            .binding = null,
            .then_ = try binds.toOwnedSlice(env.arena),
            .else_ = else_,
        } } } };
    }
    env.expectedType = saved;
    const typed = try inferExprTyped(env, rewrite.*);
    try unifyAt(env, ret, typed.getType(), loc);
    try env.enumSectionRewrites.put(loc, rewrite);
    return typed;
}

/// `a` or `a.b.c` — an expression that reads a binding and nothing else.
fn isNamePath(e: ast.Expr) bool {
    return switch (e) {
        .identifier => |id| switch (id.kind) {
            .ident => true,
            .identAccess => |ia| !ia.optional and isNamePath(ia.receiver.*),
            .dotIdent => false,
        },
        else => false,
    };
}

/// Row 32 — a call whose callee is a value whose type is a record, an enum or
/// a primitive (not a function, not a constructor) is `callee-not-a-function`
/// at the call, naming the value's type and the read the author likely meant.
/// A name that IS the type (a constructor reached by its own name) is not a
/// value and passes.
fn refuseCallOfValue(env: *Env, callee: []const u8, typeName: []const u8, loc: ast.Loc) InferError!void {
    if (callee.len == 0) return;
    if (std.mem.eql(u8, callee, typeName)) return;
    if (env.lookupTypeDef(callee) != null) return;
    const td = env.lookupTypeDef(typeName);
    const isPrim = !std.mem.eql(u8, typeName, "void") and !std.mem.eql(u8, typeName, "noreturn") and for (scalar_type_names) |p| {
        if (std.mem.eql(u8, p, typeName)) break true;
    } else false;
    if (td == null and !isPrim) return;
    const field: ?[]const u8 = if (td) |t| switch (t) {
        .record => |r| if (r.fields.len > 0) r.fields[0].name else null,
        else => null,
    } else null;
    const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is a value of type `{s}`, not a function — it cannot be called", .{ diagnostics.callee_not_a_function, callee, typeName });
    const hint = if (field) |f|
        try std.fmt.allocPrint(env.arena, "Read the value without calling it: `{s}.{s}`. A function-typed field is called through the value (`{s}.f(…)`).", .{ callee, f, callee })
    else
        try std.fmt.allocPrint(env.arena, "Use `{s}` without `( … )`; only a function or a constructor is called.", .{callee});
    env.lastError = TypeError.custom(msg, hint).withLoc(loc);
    return error.TypeError;
}

/// A label on a call whose callee has a function TYPE and no declaration —
/// a parameter, a local, a record's function-typed field, a tuple element —
/// is `label-on-function-value`, at the labelled argument.
fn refuseLabelsOnFunctionValue(env: *Env, callee: []const u8, typedArgs: []const ast.CallArgOf(.typed)) InferError!void {
    for (typedArgs) |ta| {
        const l = ta.label orelse continue;
        if (std.mem.eql(u8, l, "..")) continue;
        const msg = try std.fmt.allocPrint(
            env.arena,
            "{s}: `{s}` is a function value, whose parameters have no names — `{s}:` names nothing",
            .{ diagnostics.label_on_function_value, callee, l },
        );
        env.lastError = TypeError.custom(msg, "A function type is positional (`fn(i32, string) -> string`): pass the arguments in its order, without labels.").withLoc(ta.value.getLoc());
        return error.TypeError;
    }
}

/// `lhs |> f(args…)` / `lhs |> f` against the declared parameters of `f`: the
/// piped value is the first argument, and a call that leaves out defaulted
/// parameters or labels one is planned like any call (C-04, 01) and recorded
/// under the PIPELINE's loc, which `transform.zig` rewrites into the call
/// `f(lhs, args…)` before the fill. Null when there is nothing to plan: a
/// complete positional pipeline, or a callee with no declaration.
fn planPipelineFill(
    env: *Env,
    callee: []const u8,
    f: anytype,
    lhsPtr: *ast.TypedExpr,
    args: []const ast.CallArg,
    loc: ast.Loc,
) InferError!?*T.Type {
    const declared = calleeParams(env, callee) orelse return null;
    if (declared.len != f.params.len) return null;
    var labelled = false;
    for (args) |a| if (a.label != null) {
        labelled = true;
    };
    if (!labelled and args.len + 1 == declared.len) return null;
    const typedArgs = try env.arena.alloc(ast.CallArgOf(.typed), args.len + 1);
    typedArgs[0] = .{ .label = null, .value = lhsPtr };
    for (args, 1..) |a, i| {
        const val = try inferExprTyped(env, a.value.*);
        typedArgs[i] = .{ .label = a.label, .value = try makeTypedPtr(env, val) };
    }
    const plan = (if (typedArgs.len == declared.len)
        try planLabelledCall(env, callee, declared, typedArgs, loc)
    else
        try recordDefaultFill(env, loc, declared, typedArgs)) orelse return null;
    try env.defaultInjections.put(loc, plan);
    try unifyFilledArgs(env, plan, f.params, typedArgs);
    return f.ret;
}

/// Decision 719 — `ns.f(…)`, `f` a function of the module `ns` with a `syntax`
/// expression parameter (bound under `<ns>.<f>` by the namespace import): the
/// call is expanded where it is written, as the bare `f(…)` of a leaf import
/// is — each `syntax` argument captured as written, every other one a
/// literal, the body run at build and the code it answers typed here.
fn expandQualifiedSyntaxCall(
    env: *Env,
    ns: []const u8,
    tfn: ast.FnDecl,
    call: anytype,
    params: []const *T.Type,
    ret: *T.Type,
    typedArgs: []ast.CallArgOf(.typed),
    trailing: usize,
    loc: ast.Loc,
) InferError!TypedExpr {
    const qn = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ ns, call.callee });
    if (params.len != typedArgs.len + trailing) {
        env.lastError = TypeError.arityMismatch(qn, params.len, typedArgs.len + trailing).withLoc(loc);
        return error.TypeError;
    }
    if (call.templateText != null) {
        const si = ast.syntaxExprIndex(tfn.params).?;
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` takes the expression `{s}` between parentheses, `{s}(…)`, and is called here with a template text", .{ diagnostics.syntax_call_outside_syntax, qn, tfn.params[si].name, qn });
        env.lastError = TypeError.custom(msg, "A `syntax` parameter of a type other than `string` takes the expression written between the call's parentheses; only `syntax q: string` takes a template text `` f @`…` `` (decisions 578 (1), 719).").withLoc(loc);
        return error.TypeError;
    }
    const exprParams = env.lookupExprParams(qn);
    var captures: std.ArrayListUnmanaged(template.CapturedExpr) = .empty;
    var plainArgs: std.ArrayListUnmanaged(template.PlainArg) = .empty;
    for (typedArgs, params[0..typedArgs.len], 0..) |ta, paramType, i| {
        if (exprParams) |eps| if (exprParamAt(eps, i)) |ep| {
            try captures.append(env.arena, try captureExprArg(env, qn, ep, call.args[i].value, ta, paramType, call.templateText));
            continue;
        };
        try unifyArgument(env, paramType, ta.value.getType(), ta.value.getLoc());
        if (i < tfn.params.len) {
            const jsVal = try literalSourceAlloc(env.arena, call.args[i].value) orelse {
                env.lastError = TypeError.custom(
                    "non-`@Expr` parameter of a template function must receive a literal value at the call site",
                    "Pass a string, integer, or boolean literal directly; runtime values have no compile-time meaning (V1).",
                ).withLoc(ta.value.getLoc());
                return error.TypeError;
            };
            try plainArgs.append(env.arena, .{ .paramName = tfn.params[i].name, .source = jsVal });
        }
    }
    const capturedSlice: []const template.CapturedExpr = try captures.toOwnedSlice(env.arena);
    if (capturedSlice.len > 0) try env.exprCaptures.put(loc, capturedSlice);
    return expandTemplateCall(env, tfn, capturedSlice, try plainArgs.toOwnedSlice(env.arena), ret, loc);
}

/// A qualified call's plan (a namespace import's `ns.f(…)`, a `"std"`
/// module's `bool.negate(…)`): the reorder a complete labelled call needs, or
/// the fill of a short one, against the parameters as written. `null` when
/// there is nothing to plan — the call is then zipped by position and its
/// arity judged by the caller, as before.
fn planQualifiedCall(
    env: *Env,
    callee: []const u8,
    declared: ?[]const ast.Param,
    paramTypes: []const *T.Type,
    typedArgs: []ast.CallArgOf(.typed),
    trailing: usize,
    loc: ast.Loc,
) InferError!?envMod.DefaultFill {
    const d = declared orelse return null;
    if (trailing != 0 or d.len != paramTypes.len or typedArgs.len > d.len) return null;
    const plan = (if (typedArgs.len == d.len)
        try planLabelledCall(env, callee, d, typedArgs, loc)
    else
        try recordDefaultFill(env, loc, d, typedArgs)) orelse return null;
    try env.defaultInjections.put(loc, plan);
    try unifyFilledArgs(env, plan, paramTypes, typedArgs);
    return plan;
}

/// The parameters as written of the `pub fn` `callee` of the `"std"` module
/// `std_key`, a default that is not closed dropped (it names a binding of the
/// std module, which the call site cannot write).
fn stdFnParams(env: *Env, std_key: []const u8, callee: []const u8) InferError!?[]const ast.Param {
    const fns = env.stdModuleFns.get(std_key) orelse return null;
    for (fns) |f| {
        if (!f.isPub or !std.mem.eql(u8, f.name, callee)) continue;
        const params = try env.arena.dupe(ast.Param, f.params);
        for (params) |*p| if (p.default) |dv| if (!isClosedDefault(dv)) {
            p.default = null;
        };
        return params;
    }
    return null;
}

/// C-04 — plan the fill for a short call and record it under the call's loc for
/// `transform.zig`. Answers the plan, or `null` when the call cannot be filled:
/// that is N2, and the caller then raises the arity error it always raised.
/// 01 — the reorder a complete labelled call needs, or null when its labels
/// name the parameters in order (or it has none). A label that names no
/// parameter, or names one twice, is refused here, located at the call.
fn planLabelledCall(
    env: *Env,
    callee: []const u8,
    params: []const ast.Param,
    typedArgs: []const ast.CallArgOf(.typed),
    loc: ast.Loc,
) InferError!?envMod.DefaultFill {
    const labels = try env.arena.alloc(?[]const u8, typedArgs.len);
    for (typedArgs, 0..) |ta, i| {
        // A `..` spread is a record update, matched field by field elsewhere.
        if (ta.label) |l| if (std.mem.eql(u8, l, "..")) return null;
        labels[i] = ta.label;
    }
    return envMod.planDefaultFill(env.arena, params, labels) catch |e| switch (e) {
        error.CannotFill => {
            for (labels) |ml| {
                const l = ml orelse continue;
                const known = for (params) |p| {
                    if (std.mem.eql(u8, p.name, l)) break true;
                } else false;
                if (!known) {
                    const msg = try std.fmt.allocPrint(env.arena, "`{s}` has no parameter named `{s}`", .{ callee, l });
                    env.lastError = TypeError.custom(msg, "A label names the parameter its argument fills.").withLoc(loc);
                    return error.TypeError;
                }
            }
            // A label twice, or a parameter with no default left out.
            for (labels, 0..) |ml, i| {
                const l = ml orelse continue;
                for (labels[i + 1 ..]) |other| if (other) |o| if (std.mem.eql(u8, l, o)) {
                    env.lastError = TypeError.custom(
                        try std.fmt.allocPrint(env.arena, "a parameter of `{s}` is given twice", .{callee}),
                        "Each parameter takes one argument: by its label, or by its position among the unlabelled ones.",
                    ).withLoc(loc);
                    return error.TypeError;
                };
            }
            if (labels.len <= params.len) {
                env.lastError = TypeError.arityMismatch(callee, params.len, labels.len).withLoc(loc);
                return error.TypeError;
            }
            env.lastError = TypeError.custom(
                try std.fmt.allocPrint(env.arena, "a parameter of `{s}` is given twice", .{callee}),
                "Each parameter takes one argument: by its label, or by its position among the unlabelled ones.",
            ).withLoc(loc);
            return error.TypeError;
        },
        else => |rest| return rest,
    };
}

fn recordDefaultFill(
    env: *Env,
    loc: ast.Loc,
    params: []const ast.Param,
    typedArgs: []const ast.CallArgOf(.typed),
) InferError!?envMod.DefaultFill {
    const labels = try env.arena.alloc(?[]const u8, typedArgs.len);
    for (typedArgs, 0..) |ta, i| labels[i] = ta.label;
    const planned = envMod.planDefaultFill(env.arena, params, labels) catch |e| switch (e) {
        error.CannotFill => return null,
        else => |rest| return rest,
    };
    const fill = planned orelse return null;
    try env.defaultInjections.put(loc, fill);
    return fill;
}

/// C-04 — unify a filled call's arguments with the parameters they actually
/// landed in. `P(y: 2)` against `type P(x: i32 = 0, y: i32)` puts its one
/// argument in the SECOND slot; zipping positionally would check it against `x`.
fn unifyFilledArgs(
    env: *Env,
    fill: envMod.DefaultFill,
    paramTypes: []const *T.Type,
    typedArgs: []ast.CallArgOf(.typed),
) InferError!void {
    for (fill.slots, 0..) |slot, pi| {
        const ai = slot orelse continue;
        if (pi >= paramTypes.len) continue;
        try unifyArgument(env, paramTypes[pi], typedArgs[ai].value.getType(), typedArgs[ai].value.getLoc());
    }
}

/// Build a typed method-call node, preserving the surface `recv.callee(args)`
/// shape (`recvPtr` is the typed receiver expression). External dispatch
/// (rewriting to `Sym.callee(recv, args)`) is recorded separately in
/// `env.dispatchRewrites` and applied by the transform pass.
fn makeMethodCall(
    env: *Env,
    recvPtr: ?*ast.TypedExpr,
    callee: []const u8,
    typedArgs: []ast.CallArgOf(.typed),
    typedTrailing: []ast.TrailingLambdaOf(.typed),
    loc: ast.Loc,
) InferError!TypedExpr {
    // C-04 / N1 — an instance call may omit an argument whose parameter
    // declares a default. Inference never arity-checked this shape, so there is
    // no error to keep honest here; what was missing is the fill, and without it
    // `b.bump()` reached node as `bump()` and answered `NaN`.
    var checkedArgs: []ast.CallArgOf(.typed) = typedArgs;
    // A method call is arity-checked like a function call: an argument short
    // of what the method declares, with no default to fill it, and one too
    // many are both `expects N argument(s)`. It used to check, and the
    // backends passed the short list — `undef` on erlang, `undefined` read as
    // the missing argument on commonJS.
    if (recvPtr) |rp| if (nominalName(rp.getType())) |tn| {
        if (env.getInherentMethodParams(tn, callee)) |declared| {
            if (declared.len > 0 and std.mem.eql(u8, declared[0].name, "self")) {
                const want = declared.len - 1;
                const total = typedArgs.len + typedTrailing.len;
                const fillable = typedTrailing.len == 0 and total < want and blk: {
                    const labels = try env.arena.alloc(?[]const u8, typedArgs.len);
                    for (typedArgs, 0..) |ta, i| labels[i] = ta.label;
                    const planned = envMod.planDefaultFill(env.arena, declared[1..], labels) catch |e| switch (e) {
                        error.CannotFill => break :blk false,
                        else => |rest| return rest,
                    };
                    break :blk planned != null;
                };
                if (total != want and !fillable) {
                    env.lastError = TypeError.arityMismatch(callee, want, total).withLoc(loc);
                    return error.TypeError;
                }
            }
        }
    };
    if (typedTrailing.len == 0) {
        if (recvPtr) |rp| if (nominalName(rp.getType())) |tn| {
            if (env.getInherentMethodParams(tn, callee)) |declared| {
                if (declared.len > 0 and std.mem.eql(u8, declared[0].name, "self")) {
                    const plan = if (typedArgs.len == declared.len - 1)
                        try planLabelledCall(env, callee, declared[1..], typedArgs, loc)
                    else
                        try recordDefaultFill(env, loc, declared[1..], typedArgs);
                    // 01 — a complete call whose labels move an argument is
                    // lowered in declaration order, and checked in it.
                    if (plan) |p| if (typedArgs.len == declared.len - 1) {
                        try env.defaultInjections.put(loc, p);
                        const ordered = try env.arena.alloc(ast.CallArgOf(.typed), typedArgs.len);
                        for (p.slots, 0..) |slot, pi| ordered[pi] = typedArgs[slot.?];
                        checkedArgs = ordered;
                    };
                }
            }
        };
    }
    const retType = try methodCallReturnType(env, recvPtr, callee, checkedArgs, typedTrailing, loc);
    return TypedExpr{ .call = .{ .loc = loc, .type_ = retType, .kind = .{ .call = .{
        .receiver = recvPtr,
        .callee = callee,
        .is_builtin = false,
        .args = typedArgs,
        .trailing = typedTrailing,
    } } } };
}

/// Recover the return type of an inherent-method call `recv.callee(args)` from
/// the registered signature. The signature's type-level generics (the record's
/// `<T>` cells, `Self`, method generics) are instantiated fresh per call site;
/// the self param is unified with the receiver type and the remaining params
/// with the arguments, propagating concrete types into the return. Falls back
/// to a fresh var when no signature is registered (extension dispatch, etc.).
fn methodCallReturnType(
    env: *Env,
    recvPtr: ?*ast.TypedExpr,
    callee: []const u8,
    typedArgs: []ast.CallArgOf(.typed),
    typedTrailing: []ast.TrailingLambdaOf(.typed),
    loc: ast.Loc,
) InferError!*T.Type {
    const recv = recvPtr orelse return env.freshVar();
    const recvType = recv.getType();
    const typeName = nominalName(recvType) orelse return env.freshVar();
    const sigRaw = env.getInherentMethodType(typeName, callee) orelse return env.freshVar();

    // Fresh per-call-site copy so the shared registration cells never collapse.
    var seen = std.AutoHashMap(*T.TypeCell, *T.Type).init(env.arena);
    defer seen.deinit();
    const sig = try instantiateType(env, sigRaw, &seen, .allVars);
    const fn_ = sig.deref();
    if (fn_.* != .func or fn_.func.params.len == 0) return env.freshVar();

    // params[0] is `self` — bind the type's generics to the receiver instance.
    try unifyAt(env, fn_.func.params[0], recvType, loc);
    // Unify positional args when the (self-excluded) arity matches and there
    // are no trailing lambdas (whose value type isn't available here). The
    // self-unification alone already propagates the receiver's type args into
    // the return type; arg unification refines method-generic params.
    const rest = fn_.func.params[1..];
    if (typedTrailing.len == 0 and rest.len == typedArgs.len) {
        // 144 B-10 — an argument meets its parameter as a free function's
        // does (`unifyArgument`): a behavior-typed parameter takes an
        // implementer. `sheet.add("c", s)` with `item: Styleable` and a
        // `Styled` `s` was `expected Styleable, got Styled`.
        for (typedArgs, rest) |ta, p| {
            try unifyArgument(env, p, ta.value.getType(), ta.value.getLoc());
        }
    } else if (typedTrailing.len == 0) {
        // C-04 — a short call whose omitted parameters take their declared
        // defaults: unify each argument with the parameter it landed in.
        if (env.defaultInjections.get(loc)) |fill| try unifyFilledArgs(env, fill, rest, typedArgs);
    }
    return fn_.func.ret;
}

/// Decision 62 — the return type of a **type-qualified** call to one of a type's
/// own methods (`Counter.zero()`, and the explicit-receiver spelling of an
/// instance method, `Counter.bump(c)`). Null when the type declares no such
/// method, or declares it without a return-type annotation — in which case the
/// caller's fresh-var fallback still stands, exactly as it does for the instance
/// form (`registerInherentMethodTypes` only stores an annotated signature).
///
/// The signature is instantiated fresh per call site, like
/// `methodCallReturnType`, so the type's shared generic cells never collapse
/// across two calls. Unlike that function there is no receiver value to unify
/// `self` against: every declared parameter lines up with an argument, so the
/// arity must match exactly for the signature to be read at all.
fn associatedCallReturnType(
    env: *Env,
    typeName: []const u8,
    callee: []const u8,
    typedArgs: []ast.CallArgOf(.typed),
    typedTrailing: []ast.TrailingLambdaOf(.typed),
    loc: ast.Loc,
) InferError!?*T.Type {
    if (!env.hasInherentMethod(typeName, callee)) return null;
    const sigRaw = env.getInherentMethodType(typeName, callee) orelse return null;

    var seen = std.AutoHashMap(*T.TypeCell, *T.Type).init(env.arena);
    defer seen.deinit();
    const sig = try instantiateType(env, sigRaw, &seen, .allVars);
    const fn_ = sig.deref();
    if (fn_.* != .func) return null;
    // A trailing lambda's value type is not available here — leave it to the
    // fallback rather than unify against the wrong slots.
    if (typedTrailing.len > 0) return null;
    // 01 — a label names the parameter it fills: `Box.make(count: 5,
    // label: "a")` is checked and lowered in declaration order, never zipped;
    // C-04 — a short call is filled from the declared defaults. Both as a
    // std module's fn is (`planQualifiedCall`).
    if (try planQualifiedCall(env, callee, env.getInherentMethodParams(typeName, callee), fn_.func.params, typedArgs, 0, loc) != null) return fn_.func.ret;
    // Any other count is the call's arity error: `Bag.of("p", "q")` against
    // one parameter used to fall through to the fallback, which checked
    // nothing, and compiled.
    if (fn_.func.params.len != typedArgs.len) {
        env.lastError = TypeError.arityMismatch(callee, fn_.func.params.len, typedArgs.len).withLoc(loc);
        return error.TypeError;
    }
    for (typedArgs, fn_.func.params) |ta, p| {
        try unifyArgument(env, p, ta.value.getType(), ta.value.getLoc());
    }
    return fn_.func.ret;
}

/// 144 B-10 (decision 430) — `T.f` read without a call, where `T` names a
/// record, struct or enum and `f` is one of its associated fns (no `self`):
/// the fn as a value, of its declared signature, and the lowering the
/// backends without native static members place it by. Null for any other
/// member read.
fn associatedFnValue(env: *Env, ia: anytype, loc: ast.Loc) InferError!?TypedExpr {
    if (ia.optional) return null;
    if (ia.receiver.* != .identifier or ia.receiver.*.identifier.kind != .ident) return null;
    const typeName = ia.receiver.*.identifier.kind.ident;
    if (env.lookupTypeDef(typeName) == null) return null;
    if (!env.hasInherentMethod(typeName, ia.member)) return null;
    const params = env.getInherentMethodParams(typeName, ia.member) orelse return null;
    if (params.len > 0 and std.mem.eql(u8, params[0].name, "self")) return null;
    const sigRaw = env.getInherentMethodType(typeName, ia.member) orelse return null;
    var seen = std.AutoHashMap(*T.TypeCell, *T.Type).init(env.arena);
    defer seen.deinit();
    const sig = try instantiateType(env, sigRaw, &seen, .allVars);
    if (sig.deref().* != .func) return null;
    try env.instanceLowerings.put(loc, .{ .assoc_fn_value = .{ .type_name = typeName, .method = ia.member, .arity = params.len } });
    const recvTyped = try makeTypedPtr(env, TypedExpr{ .identifier = .{
        .loc = ia.receiver.*.getLoc(),
        .type_ = try env.namedType(typeName),
        .kind = .{ .ident = typeName },
    } });
    return TypedExpr{ .identifier = .{ .loc = loc, .type_ = sig, .kind = .{ .identAccess = .{
        .receiver = recvTyped,
        .member = ia.member,
    } } } };
}

/// A member of a `@Result<R, E>` value is one of its builtin methods, or
/// refused. A `@Result` is its `Ok` / `Error` carrier, not the payload:
/// `querystring.parse(q).length` read a field off `{ok, V}` — it checked,
/// printed `null` on commonJS and crashed on erlang. A field read and a call
/// of any other name are refused, located at the member, naming `try` and
/// `unwrapOr`. `recvTy` is the receiver's type after an optional chain's
/// unwrapping; a non-`@Result` receiver passes, and so does every receiver
/// while the program declares a type named `Result` of its own.
fn refuseResultMemberAccess(env: *Env, recvTy: *T.Type, member: []const u8, is_call: bool, loc: ast.Loc) InferError!void {
    const t = recvTy.deref();
    if (t.* != .named or !std.mem.eql(u8, t.named.name, "Result")) return;
    // A program's own `type Result { … }` is that type, with its own fields
    // and methods (`unknownField` answers for it), not the builtin carrier.
    if (env.lookupTypeDef("Result") != null) return;
    // So is a `behavior Result` it declares or imports (`takeNameFromPrelude`).
    if (env.assocInterfaceDecls.get("Result") != null or env.importedBehaviorDecls.contains("Result")) return;
    // The builtin methods of a `@Result<R, E>` value — `inferResultOptionMethod`
    // resolves each; `comptime/builtins.zig` `methods` holds them to
    // `libs/std/src/primitives.bp`'s compiler section (decision 252).
    if (is_call and builtinsMod.hasMethod("Result", member)) return;
    const msg = try std.fmt.allocPrint(
        env.arena,
        diagnostics.result_member_not_a_method ++ ": `{s}` is not a member of a `Result` — take the payload with `try` or `unwrapOr(<default>)` first; a `Result`'s methods are `map`, `flatMap`, `unwrapOr`, `isOk` and `isError`",
        .{member},
    );
    const hint = try std.fmt.allocPrint(
        env.arena,
        "A `Result` is `Ok` or `Error`, not its payload: take the payload with `try` (`val v = try r;`, then `v.{s}`) or with a default (`r.unwrapOr(<default>).{s}`).",
        .{ member, member },
    );
    env.lastError = TypeError.custom(msg, hint).withLoc(loc);
    return error.TypeError;
}

/// The behavior `name` names — a module's own, imported or ambient one
/// (`Env.behaviorDecl`), else one of `primitives.bp`'s that a compiler rule
/// reads (`Env.ruleReadBehaviorDecls`: `Async`, `Component`, `Iter`, …).
fn memberBehaviorDecl(env: *const Env, name: []const u8) ?ast.BehaviorDecl {
    if (env.behaviorDecl(name)) |d| return d;
    if (env.typeDefs.contains(name)) return null;
    return env.ruleReadBehaviorDecls.get(name);
}

/// Whether behavior `name`, or a behavior it extends, declares `member` — a
/// field or a method, with or without a body.
fn behaviorNamesMember(env: *const Env, name: []const u8, member: []const u8, depth: usize) bool {
    if (depth >= 16) return false;
    const decl = memberBehaviorDecl(env, name) orelse return false;
    for (decl.fields) |f| if (std.mem.eql(u8, f.name, member)) return true;
    for (decl.methods) |m| if (std.mem.eql(u8, m.name, member)) return true;
    for (decl.extends) |parent| if (behaviorNamesMember(env, parent, member, depth + 1)) return true;
    return false;
}

/// The members behavior `name` declares, its own and those it extends, in
/// declaration order, written `` `a`, `b` `` — "" when it declares none.
fn behaviorMemberList(env: *const Env, out: *std.ArrayListUnmanaged(u8), name: []const u8, depth: usize) InferError!void {
    if (depth >= 16) return;
    const decl = memberBehaviorDecl(env, name) orelse return;
    for (decl.fields) |f| {
        if (out.items.len > 0) try out.appendSlice(env.arena, ", ");
        try out.print(env.arena, "`{s}`", .{f.name});
    }
    for (decl.methods) |m| {
        if (out.items.len > 0) try out.appendSlice(env.arena, ", ");
        try out.print(env.arena, "`{s}`", .{m.name});
    }
    for (decl.extends) |parent| try behaviorMemberList(env, out, parent, depth + 1);
}

/// Decision 596's iterator helpers, which `Iter` declares once B-128 lands.
const iter_helpers_596 = [_][]const u8{ "take", "drop", "map", "filter", "flatMap", "forEach", "toArray", "reduce", "some", "every", "find" };

/// B-162 — a field read or a method call on a value a behavior types
/// (`Component<P>`, `Async<string>`, a module's own `behavior Shape`) names a
/// member the behavior — or one it extends — declares, or an activated
/// extension of it; anything else is the unknown member it is, refused at the
/// name. It was typed as a fresh variable and reached the backends (`c.zzz`
/// compiled, crashing at run time). A receiver typed by a `type` passes, and so
/// does every other receiver.
fn refuseBehaviorUnknownMember(env: *Env, recvTy: *T.Type, member: []const u8, is_call: bool, loc: ast.Loc) InferError!void {
    const t = recvTy.deref();
    if (t.* != .named) return;
    const name = t.named.name;
    if (env.lookupTypeDef(name) != null) return;
    if (memberBehaviorDecl(env, name) == null) return;
    if (behaviorNamesMember(env, name, member, 0)) return;
    // Decision 596 — a sequence's helpers (`take`, `map`, `toArray`, …) are
    // `Iter`'s, decided but not yet declared in `primitives.bp` (B-128); the
    // backends answer them today.
    if (std.mem.eql(u8, name, "Iter") or std.mem.eql(u8, name, "AsyncIter")) {
        for (iter_helpers_596) |h| if (std.mem.eql(u8, h, member)) return;
    }
    var it = env.extensions.iterator();
    while (it.next()) |e| {
        const entry = e.value_ptr.*;
        if (std.mem.eql(u8, entry.target, name) and namesContain(entry.methods, member)) return;
    }
    const shown = try snapshotMod.typeNameOf(env.arena, t);
    var members: std.ArrayListUnmanaged(u8) = .empty;
    try behaviorMemberList(env, &members, name, 0);
    const what: []const u8 = if (is_call) "method" else "field";
    const msg = if (members.items.len == 0)
        try std.fmt.allocPrint(env.arena, "unknown {s} '{s}' on '{s}': the behavior `{s}` declares no members", .{ what, member, shown, name })
    else
        try std.fmt.allocPrint(env.arena, "unknown {s} '{s}' on '{s}': the behavior `{s}` declares {s}", .{ what, member, shown, name, members.items });
    env.lastError = TypeError.custom(msg, "A value typed by a behavior answers only the members the behavior, and what it extends, declares; a component is resolved by `use c` in a component body or placed in the tree as a child, a task by `await` (decision 791).").withLoc(loc);
    return error.TypeError;
}

/// Decision 388 (2) — `c.run(scope)` on a `@Component<R>` value: runs the
/// lambda the component value is with `scope` (a `RenderScope`, std's
/// `context` module), answering `@Async<Rendered<R>>` — the body's result and
/// the scope its `use provide`s made for its children; a `@Async` because
/// whether the node is asynchronous (375) is not in the type. Recorded for
/// the lowering (`Env.componentRuns`, `context_lower.zig`). Null for any other
/// receiver or method.
fn inferComponentRun(
    env: *Env,
    recvPtr: *ast.TypedExpr,
    callee: []const u8,
    typedArgs: []ast.CallArgOf(.typed),
    typedTrailing: []ast.TrailingLambdaOf(.typed),
    loc: ast.Loc,
) InferError!?ast.TypedExpr {
    if (!std.mem.eql(u8, callee, "run")) return null;
    const recvTy = recvPtr.getType().deref();
    if (recvTy.* != .named or !std.mem.eql(u8, recvTy.named.name, "Component") or recvTy.named.args.len != 1) return null;
    if (typedArgs.len != 1 or typedArgs[0].label != null or typedTrailing.len != 0) {
        env.lastError = TypeError.custom(
            "`run` takes the scope to run the component with, and nothing else: `c.run(scope)` (decision 388)",
            "Pass a `RenderScope` — `RenderScope.root()` outside every render, or the scope a parent's `run` answered.",
        ).withLoc(loc);
        return error.TypeError;
    }
    try unifyAt(env, try env.namedType("RenderScope"), typedArgs[0].value.getType(), typedArgs[0].value.getLoc());
    const rendered = try env.namedTypeArgs("Rendered", &.{recvTy.named.args[0]});
    try env.componentRuns.put(env.arena, loc, recvTy.named.args[0]);
    return TypedExpr{ .call = .{ .loc = loc, .type_ = try env.namedTypeArgs("Async", &.{rendered}), .kind = .{ .call = .{
        .receiver = recvPtr,
        .callee = callee,
        .is_builtin = false,
        .args = typedArgs,
        .trailing = typedTrailing,
    } } } };
}

/// Resolve a builtin method call on a `@Result<R, E>` or `@Option<T>` receiver
/// (`.map` / `.flatMap` / `.unwrapOr` / `.isOk` / `.isError`).
///
/// Returns the typed call node (with the correct result type) and records a
/// lowering decision in `env.method_lowerings` keyed by `loc`, so the AST
/// transform can rewrite it into a `__bp_<domain>_<op>(receiver, arg)` builtin
/// call. Returns `null` when the receiver is not a Result/Option or the method
/// is unknown — the caller then falls back to permissive method typing.
fn inferResultOptionMethod(
    env: *Env,
    recvPtr: *ast.TypedExpr,
    callee: []const u8,
    typedArgs: []ast.CallArgOf(.typed),
    typedTrailing: []ast.TrailingLambdaOf(.typed),
    loc: ast.Loc,
) InferError!?ast.TypedExpr {
    const recvTy = recvPtr.getType().deref();
    if (recvTy.* != .named) return null;
    const named = recvTy.named;
    const isResult = std.mem.eql(u8, named.name, "Result");
    const isOption = std.mem.eql(u8, named.name, "optional");
    if (!isResult and !isOption) return null;

    // F11 — `expect` was `unwrapOr` under a name that says the opposite, and
    // is gone. The refusal is explicit because the fallback for an unknown
    // method on a `?T` is permissive typing: without it, `.expect(…)` would
    // still compile and fail at run time, which is worse than the alias was.
    // Decision 330 — `?T` has no methods: its whole surface is `??`, `?.`,
    // `?.[]`, `?.()` and the postfix `!`. `map`, `flatMap` and `unwrapOr` left
    // it (they stay on `@Result`), and any other method is called on the
    // value through `?.`.
    // `recv?.m(args)` typed as it always was (`inferOptionalOperator`), and
    // a link that continues a `?.` chain (`e?.key.length()`): the chain after
    // a `?.` runs under its guard, as TypeScript's does, so the method is the
    // payload's.
    // The methods `?T` lost stay refused there unless the payload answers
    // them itself (an array's `map`, a `@Result`'s `unwrapOr`).
    const payloadName: []const u8 = if (named.args.len >= 1 and named.args[0].deref().* == .named) named.args[0].deref().named.name else "";
    const lostMethod = ((std.mem.eql(u8, callee, "map") or std.mem.eql(u8, callee, "flatMap")) and !std.mem.eql(u8, payloadName, "array")) or
        ((std.mem.eql(u8, callee, "unwrapOr") or std.mem.eql(u8, callee, "expect")) and !std.mem.eql(u8, payloadName, "Result"));
    if (isOption and !lostMethod and (env.inOptionalChain or continuesOptionalChain(recvPtr.*))) return null;
    if (isOption) {
        const inner = try snapshotMod.typeNameOf(env.arena, if (named.args.len >= 1) named.args[0] else try env.freshVar());
        const msg = try std.fmt.allocPrint(
            env.arena,
            "{s}: unknown method `{s}` on `?{s}` — an optional has no methods",
            .{ diagnostics.optional_has_no_methods, callee, inner },
        );
        const hint: []const u8 = if (std.mem.eql(u8, callee, "unwrapOr"))
            "Write `x ?? fallback` for the value or a default."
        else if (std.mem.eql(u8, callee, "map") or std.mem.eql(u8, callee, "flatMap"))
            "Read through the optional with `?.` (`x?.f()`), or narrow it (`if (x) { v -> … }`); `?.` flattens a `?U` answer."
        else
            try std.fmt.allocPrint(env.arena, "Call it on the value through `?.` (`x?.{s}(…)`), or narrow the optional first (`if (x) {{ v -> v.{s}(…) }}`).", .{ callee, callee });
        env.lastError = TypeError.custom(msg, hint).withLoc(loc);
        return error.TypeError;
    }

    const op: envMod.MethodLowering.Op =
        if (std.mem.eql(u8, callee, "map")) .map else if (std.mem.eql(u8, callee, "flatMap")) .flatMap else if (std.mem.eql(u8, callee, "unwrapOr")) .unwrapOr else if (isResult and std.mem.eql(u8, callee, "isOk")) .isOk else if (isResult and std.mem.eql(u8, callee, "isError")) .isError else return null;

    // The success-payload type: `R` for `Result<R, E>`, `T` for `Option<T>`.
    const okTy: *T.Type = if (named.args.len >= 1) named.args[0] else try env.freshVar();
    const errTy: *T.Type = if (isResult and named.args.len >= 2) named.args[1] else try env.freshVar();

    // The functional / default argument arrives as the first positional arg.
    const arg0: ?*T.Type = if (typedArgs.len >= 1) typedArgs[0].value.getType() else null;

    const retType: *T.Type = switch (op) {
        .map => blk: {
            const r2 = try env.freshVar();
            if (arg0) |a| try unifyAt(env, a, try env.funcType(&.{okTy}, r2), loc);
            break :blk if (isResult)
                try env.namedTypeArgs("Result", &.{ r2, errTy })
            else
                try env.namedTypeArgs("optional", &.{r2});
        },
        .flatMap => blk: {
            const r2 = try env.freshVar();
            const resTy = if (isResult)
                try env.namedTypeArgs("Result", &.{ r2, errTy })
            else
                try env.namedTypeArgs("optional", &.{r2});
            if (arg0) |a| try unifyAt(env, a, try env.funcType(&.{okTy}, resTy), loc);
            break :blk resTy;
        },
        .unwrapOr => blk: {
            if (arg0) |a| try unifyAt(env, a, okTy, loc);
            break :blk okTy;
        },
        .isOk, .isError => try env.namedType("bool"),
    };

    try env.method_lowerings.put(loc, .{ .domain = if (isResult) .result else .option, .op = op });

    return ast.TypedExpr{ .call = .{ .loc = loc, .type_ = retType, .kind = .{ .call = .{
        .receiver = recvPtr,
        .callee = callee,
        .is_builtin = false,
        .args = typedArgs,
        .trailing = typedTrailing,
    } } } };
}

/// True when `e` is a `?.` link (`a?.b`, `a?.m()`) or a link written after
/// one (`a?.b.c()`): the rest of a `?.` chain reads the payload.
fn continuesOptionalChain(e: ast.TypedExpr) bool {
    return switch (e) {
        .identifier => |id| switch (id.kind) {
            .identAccess => |a| a.optional or continuesOptionalChain(a.receiver.*),
            else => false,
        },
        .call => |c| switch (c.kind) {
            .call => |cc| cc.optional or (!cc.is_builtin and cc.calleeExpr == null and
                if (cc.receiver) |r| continuesOptionalChain(r.*) else false),
            else => false,
        },
        else => false,
    };
}

/// The expectation of `unwrapOr`'s default: the payload of the `?T` /
/// `@Result<T, E>` it is called on, so an integer literal takes the payload's
/// width (`delay(n).unwrapOr(0)` over `?i64`) as it does as an argument of a
/// declared parameter or a field (`inferLiteralExpr`).
fn unwrapOrDefaultExpected(recv: ?*ast.TypedExpr, callee: []const u8) ?*T.Type {
    if (!std.mem.eql(u8, callee, "unwrapOr")) return null;
    const r = recv orelse return null;
    const t = r.getType().deref();
    if (t.* != .named or t.named.args.len < 1) return null;
    if (!std.mem.eql(u8, t.named.name, "optional") and !std.mem.eql(u8, t.named.name, "Result")) return null;
    return t.named.args[0];
}

/// Resolve a compiler-provided template method (expr-templates F4):
/// `text`/`parts`/`lookup`/`fail`/`failAt` on an `expr` receiver, plus
/// `ref()` on a `Binding`.
///
/// The data model (`Span`, `Part`, `Decl`) lives in `std.syntax`
/// (libs/std/src/syntax.bp); these methods are inference-resolved like the
/// `@Result`/`@Option` builtins — no runtime dispatch table — and recorded in
/// `env.templateLowerings` (keyed by call loc) for the expansion pass (F6).
/// Instances only exist at comptime; no codegen backend ever sees these calls.
/// Returns null when the receiver is not an `expr` or the method is
/// unknown — the caller falls back to permissive method typing.
/// Decision 643 — `compiler.name(d)` on a declaration handle
/// (`ast.decl_name_method`, as `parser/compiler_surface.zig` writes it)
/// answers `?string`: the
/// declaration's name, never `null` — `compiler.name(d)!` reads it as the
/// `string` it is.
fn inferHandleName(env: *Env, recvPtr: *ast.TypedExpr, callee: []const u8, typedArgs: []ast.CallArgOf(.typed), loc: ast.Loc) InferError!?ast.TypedExpr {
    if (!std.mem.eql(u8, callee, ast.decl_name_method) or typedArgs.len != 0) return null;
    const d = recvPtr.getType().deref();
    if (d.* != .named or !std.mem.eql(u8, d.named.name, ast.decl_type_name)) return null;
    const ty = try env.namedTypeArgs("optional", &.{try env.namedType("string")});
    return ast.TypedExpr{ .identifier = .{ .loc = loc, .type_ = ty, .kind = .{ .identAccess = .{
        .receiver = recvPtr,
        .member = "name",
        .optional = false,
    } } } };
}

fn inferTemplateMethod(
    env: *Env,
    recvPtr: *ast.TypedExpr,
    callee: []const u8,
    typedArgs: []ast.CallArgOf(.typed),
    typedTrailing: []ast.TrailingLambdaOf(.typed),
    loc: ast.Loc,
) InferError!?ast.TypedExpr {
    const recvTy = recvPtr.getType().deref();
    if (recvTy.* != .named) return null;
    const named = recvTy.named;

    const unifyArg = struct {
        fn unifyArg(e: *Env, args: []ast.CallArgOf(.typed), i: usize, expected: *T.Type) InferError!void {
            if (i >= args.len) return;
            try unifyAt(e, expected, args[i].value.getType(), args[i].value.getLoc());
        }
    }.unifyArg;

    var op: envMod.TemplateOp = undefined;
    var retType: *T.Type = undefined;

    // Decision 364 — a `comptime` parameter's `@Expr` (not a template's
    // capture) answers `.value`, and in a decorator `.fail(…)`, located at
    // the argument.
    if (std.mem.eql(u8, named.name, ast.expr_type_name)) if (exprParamOfName(env, typedIdentName(recvPtr.*))) |p| {
        // `rule.value(x)` calls the function at build: refused as its read.
        if (std.mem.eql(u8, callee, "value") and named.args.len == 1) {
            const recvExpr: ast.Expr = .{ .identifier = .{ .loc = recvPtr.getLoc(), .kind = .{ .ident = p.name } } };
            try refuseExprValueRead(env, recvExpr, loc);
        }
        // Decision 576 (2) — in a decorator, `compiler.text(x)` reads the
        // argument as the annotation wrote it.
        // Decision 643 — `compiler.name(x)` reads the name it is written as,
        // `null` when it has none.
        if (!(env.inDecoratorFn and (std.mem.eql(u8, callee, "fail") or ((std.mem.eql(u8, callee, "text") or std.mem.eql(u8, callee, "name")) and typedArgs.len == 0)))) {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is a `comptime` parameter, whose `@Expr` answers `.value`{s} — not `.{s}(…)`", .{ diagnostics.expr_param_method, p.name, if (env.inDecoratorFn) " and `.fail(…)`" else "", callee });
            env.lastError = TypeError.custom(msg, "Read the argument's value at build with `x.value` (decision 364); a template function's capture is the one `@Expr` with the template methods.").withLoc(loc);
            return error.TypeError;
        }
    };

    if (std.mem.eql(u8, named.name, ast.expr_type_name)) {
        if (std.mem.eql(u8, callee, "value")) {
            // The expression's value type slot — what the code evaluates to.
            op = .value;
            retType = if (named.args.len >= 1) named.args[0] else try env.freshVar();
        } else if (std.mem.eql(u8, callee, "name") and typedArgs.len == 0) {
            // Decision 643 — `compiler.name(e)` answers `?string` in every
            // body: the name the expression is written as, `null` for none.
            op = .text;
            retType = try env.namedTypeArgs("optional", &.{try env.namedType("string")});
        } else if (std.mem.eql(u8, callee, "text")) {
            op = .text;
            retType = try env.namedType("string");
        } else if (std.mem.eql(u8, callee, "source")) {
            // Declaration position — where the expression was written.
            op = .source;
            retType = try env.namedType("__Source");
        } else if (std.mem.eql(u8, callee, "context")) {
            // The full second-layer input: source + text + shape. The record is
            // `ExprContext`, not `Context`: `@Renderable` is the owner
            // marker and one name cannot mean both (front 20 F1).
            op = .context;
            retType = try env.namedType("__ExprContext");
        } else if (std.mem.eql(u8, callee, "bindings")) {
            // Every declaration a word of the text names (decision 237), as
            // `lookup` answers it (decision 415 (2)).
            op = .bindings;
            retType = try env.namedTypeArgs("array", &.{try env.namedType(ast.decl_type_name)});
        } else if (std.mem.eql(u8, callee, "holes")) {
            // Decision 637 — the text's `${…}` holes, each a `syntax` value
            // (or, handed by a body that runs at build, the hole's value).
            op = .holes;
            retType = try env.namedTypeArgs("array", &.{try env.namedType("unknown")});
        } else if (std.mem.eql(u8, callee, "isSyntax")) {
            // Decision 637 — whether a value is a `syntax` value.
            op = .isSyntax;
            retType = try env.namedType("bool");
        } else if (std.mem.eql(u8, callee, "build")) {
            // Parse source text into an expression carrying the receiver's
            // origin scope + provenance — how a second-layer language emits
            // code without quoting (`expr { … }` covers the pattern case).
            op = .build;
            try unifyArg(env, typedArgs, 0, try env.namedType("string"));
            retType = try env.namedTypeArgs(ast.expr_type_name, &.{try env.freshVar()});
        } else if (std.mem.eql(u8, callee, "ast")) {
            // Decision 625 (2) — code built from a tree of `compiler.Node`s,
            // read at the run's reply (`astBuild`); its value type is
            // revealed at expansion, as `build`'s is.
            op = .ast;
            retType = try env.namedTypeArgs(ast.expr_type_name, &.{try env.freshVar()});
        } else if (std.mem.eql(u8, callee, "custom")) {
            // Pack a reference `CustomNode` tree + executable `code` into the
            // `@ExprCustom<R>` carrier (expr-custom). The `code`'s value type `R`
            // is revealed at expansion; the tree is stored by call-location for
            // tooling. Generic — the core never inspects `kind`/`label`.
            op = .custom;
            const r = try env.freshVar();
            try unifyArg(env, typedArgs, 0, try env.namedType("__CustomNode"));
            try unifyArg(env, typedArgs, 1, try env.namedTypeArgs(ast.expr_type_name, &.{r}));
            retType = try env.namedTypeArgs("CustomExpr", &.{r});
        } else if (std.mem.eql(u8, callee, "lookup")) {
            // Decision 415 (2) — the call site's declaration, a read-only
            // `?@Decl`.
            op = .lookup;
            try unifyArg(env, typedArgs, 0, try env.namedType("string"));
            retType = try env.namedTypeArgs("optional", &.{try env.namedType(ast.decl_type_name)});
        } else if (std.mem.eql(u8, callee, "fail")) {
            op = .fail;
            try unifyArg(env, typedArgs, 0, try env.namedType("string"));
            // `fail` never returns — a fresh var unifies with any context.
            retType = try env.freshVar();
        } else if (std.mem.eql(u8, callee, "note")) {
            // Decision 426 (4) — a reason attached to an error reported at
            // the call (`finishExpansion`, `unifyAt`).
            op = .note;
            try unifyArg(env, typedArgs, 0, try env.namedType("string"));
            retType = try env.namedType("void");
        } else if (std.mem.eql(u8, callee, "failAt")) {
            op = .failAt;
            try unifyArg(env, typedArgs, 0, try env.namedType("__Span"));
            try unifyArg(env, typedArgs, 1, try env.namedType("string"));
            retType = try env.freshVar();
        } else if (std.mem.eql(u8, callee, "tagDecl")) {
            // Decision 302 — a tag's `@Decl`, built by the template.
            op = .tagDecl;
            try unifyArg(env, typedArgs, 0, try env.namedType("__DeclKind"));
            try unifyArg(env, typedArgs, 1, try env.namedType("string"));
            const pair = try env.namedTypeArgs("tuple", &.{ try env.namedType("string"), try env.namedType("string") });
            try unifyArg(env, typedArgs, 2, try env.namedTypeArgs("array", &.{pair}));
            retType = try env.namedType(ast.decl_type_name);
        } else if (std.mem.eql(u8, callee, "annotate")) {
            // Decision 302 — the annotation written at a span of the text,
            // run over a tag's `@Decl` (`expandTemplateCallViaRuntime`).
            op = .annotate;
            try unifyArg(env, typedArgs, 0, try env.namedType(ast.decl_type_name));
            try unifyArg(env, typedArgs, 1, try env.namedType("__Span"));
            retType = try env.namedType(ast.decl_type_name);
        } else return null;
    } else return null;

    try env.templateLowerings.put(loc, op);

    return ast.TypedExpr{ .call = .{ .loc = loc, .type_ = retType, .kind = .{ .call = .{
        .receiver = recvPtr,
        .callee = callee,
        .is_builtin = false,
        .args = typedArgs,
        .trailing = typedTrailing,
    } } } };
}

/// Resolve `recv.callee(args)` against inherent methods and activated extensions.
///
/// Returns the typed call on success, or null when there is no method/extension
/// match (the caller then falls back to a plain callee lookup). Raises
/// `error.TypeError` for the diagnostic cases: not-active, and ambiguity.
fn resolveReceiverCall(
    env: *Env,
    recv: []const u8,
    recvPtr: ?*ast.TypedExpr,
    callee: []const u8,
    typedArgs: []ast.CallArgOf(.typed),
    typedTrailing: []ast.TrailingLambdaOf(.typed),
    loc: ast.Loc,
) InferError!?TypedExpr {
    // (a) Qualified call: receiver is an extension symbol, e.g. `PatoNada.swim(donald)`.
    //     Qualified calls resolve without activation.
    if (env.extensions.get(recv)) |ext| {
        if (!containsStr(ext.methods, callee)) return null;
        return try makeMethodCall(env, recvPtr, callee, typedArgs, typedTrailing, loc);
    }

    // A type-qualified call (`EnumType.Variant(args)`, struct static call) is not an
    // instance dispatch — leave it to the constructor-resolution path.
    if (env.lookupTypeDef(recv) != null) return null;

    // (b) Instance call: `recv` is a value; dispatch on its nominal type.
    const recvType = env.lookup(recv) orelse return null;
    const typeName = nominalName(recvType) orelse return null;

    // Rule 1 — inherent method (declared on the type or inline `implement`).
    if (env.hasInherentMethod(typeName, callee)) {
        try recordInstanceCall(env, loc, typeName);
        return try makeMethodCall(env, recvPtr, callee, typedArgs, typedTrailing, loc);
    }

    // Rule 2 — an `implement` block providing `callee` for this type. Every entry
    // in `env.extensions` is declared in the current module (imports do not register
    // here), so all are auto-applied: no activation is required (Rule B). Two local
    // impls of the same method for the same type are ambiguous.
    var matchSym: ?[]const u8 = null;
    var ambiguousWith: ?[]const u8 = null;
    var it = env.extensions.valueIterator();
    while (it.next()) |ext| {
        if (!std.mem.eql(u8, ext.target, typeName)) continue;
        if (!containsStr(ext.methods, callee)) continue;
        if (matchSym == null) {
            matchSym = ext.name;
        } else if (ambiguousWith == null) {
            ambiguousWith = ext.name;
        }
    }

    if (matchSym) |sym| {
        if (ambiguousWith) |other| {
            env.lastError = TypeError.ambiguousExtension(typeName, callee, sym, other).withLoc(loc);
            return error.TypeError;
        }
        // External dispatch: lower `recv.callee(args)` → `sym.callee(recv, args)`.
        try env.dispatchRewrites.put(loc, sym);
        return try makeMethodCall(env, recvPtr, callee, typedArgs, typedTrailing, loc);
    }

    return null;
}

/// Resolve `xs.method(args)` where `xs: Array<T>` against the `list` stdlib
/// module's exported functions. Returns a typed call on success, null when no
/// match. Records a `StdArrayLowering` so the transform rewrites to the
/// qualified `list.method(xs, args)` form (no explicit import needed).
fn resolveStdArrayMethod(
    env: *Env,
    recv: *ast.Expr,
    recvPtr: ?*ast.TypedExpr,
    callee: []const u8,
    typedArgs: []ast.CallArgOf(.typed),
    typedTrailing: []ast.TrailingLambdaOf(.typed),
    loc: ast.Loc,
) InferError!?TypedExpr {
    _ = recv;
    // Don't dispatch inside the module that implements the methods. Every
    // other std module is a caller like any program: skipped as well, a
    // `default fn` it calls (`std/path`'s `makeUps(n - 1).prepend("..")`)
    // never marked its interface used, so commonJS emitted no prototype
    // method for it and the call was `… .prepend is not a function`.
    if (std.mem.eql(u8, env.modulePath, "std/primitives")) return null;
    const rp = recvPtr orelse return null;
    const recvType = rp.getType().deref();
    if (recvType.* != .named) return null;

    // Map the receiver's primitive type to its interface, then resolve `callee`
    // against that interface's `default fn` instance methods, following the
    // `extends` chain. Only `default fn` methods are materialized; `@[external]`
    // methods (`map`, `abs`, …) and unknown methods fall through to the permissive
    // path. (Numeric tower deferred until `@[external]` method lowering lands —
    // its `default fn`s like `clamp` call host-backed `min`/`max`.)
    const ifaceName = primitiveInterfaceName(recvType.named.name) orelse return null;
    const found = findInterfaceDefaultFn(env, ifaceName, callee) orelse return null;
    const im = found.method;

    // Mark the owning interface used so codegen emits its prototype methods.
    try env.usedAssocInterfaces.put(found.owner, {});

    // Per-call generic scope: `Self` = the receiver array, `T` = its element.
    var gm = std.StringHashMap(*T.Type).init(env.arena);
    defer gm.deinit();
    try gm.put("Self", recvType);
    if (recvType.named.args.len >= 1) try gm.put("T", recvType.named.args[0]);
    for (im.genericParams) |gp| try gm.put(gp.name, try env.freshVar());

    const restParams = im.params[1..]; // drop `self`
    const total = typedArgs.len + typedTrailing.len;
    // C-04 / N1 — `s.slice(1)` against `slice(self, start: i32, end: ?i32 = null)`.
    // The interface declares the default; the call may omit it.
    var fillPlan: ?envMod.DefaultFill = null;
    if (restParams.len != total) {
        if (typedTrailing.len == 0) fillPlan = try recordDefaultFill(env, loc, restParams, typedArgs);
        // N2 — anything the defaults do not cover is still the arity error.
        if (fillPlan == null) {
            env.lastError = TypeError.arityMismatch(callee, restParams.len, total).withLoc(loc);
            return error.TypeError;
        }
    } else if (typedTrailing.len == 0) {
        // 01 — a complete call whose labels move an argument
        // (`s.slice(end: 3, start: 1)`) is checked and lowered by label.
        fillPlan = try planLabelledCall(env, callee, restParams, typedArgs, loc);
        if (fillPlan) |plan| try env.defaultInjections.put(loc, plan);
    }
    if (fillPlan) |fill| {
        for (fill.slots, restParams) |slot, p| {
            const ai = slot orelse continue;
            const pType = try paramTypeInContext(env, p, gm);
            try unifyAt(env, pType, typedArgs[ai].value.getType(), typedArgs[ai].value.getLoc());
        }
    } else for (restParams[0..typedArgs.len], typedArgs) |p, ta| {
        const pType = try paramTypeInContext(env, p, gm);
        try unifyAt(env, pType, ta.value.getType(), ta.value.getLoc());
    }
    for (typedTrailing, 0..) |tl, i| {
        const pType = try paramTypeInContext(env, restParams[typedArgs.len + i], gm);
        const lamParams = try env.arena.alloc(*T.Type, tl.params.len);
        for (lamParams) |*lp| lp.* = try env.freshVar();
        try unifyAt(env, pType, try env.funcType(lamParams, try env.freshVar()), loc);
    }
    const retType = if (im.returnType) |rt| try resolveTypeRefInContext(env, rt, gm) else try env.namedType("void");

    if (primKindOfName(recvType.named.name) != null) {
        try recordInstanceCall(env, loc, recvType.named.name);
        try recordWidthMember(env, loc, recvType.named.name, callee);
    }

    return TypedExpr{ .call = .{ .loc = loc, .type_ = retType, .kind = .{ .call = .{
        .receiver = recvPtr,
        .callee = callee,
        .is_builtin = false,
        .args = typedArgs,
        .trailing = typedTrailing,
    } } } };
}

const primKindOfName = envMod.primKindOfName;

/// The return type of a builtin-primitive method call derived from its declared
/// signature in `primitives.bp` (`Self` substitutes to the receiver, `T` to its
/// first type arg, and any method-level `<U>` becomes a fresh var). Lets a chained
/// call keep tracking its type (`xs.filter(f).at(0)` → `?T`). Returns null when
/// the method is unknown to the interface; the caller then types it permissively.
/// Two intrinsic shapes don't map to a `fn` slot: a `val name: T` interface field
/// (e.g. `Array.length` — a property, not a fn) and the `len`/`size` aliases for
/// that same length property — both are read off the interface field directly.
fn primMethodReturnTypeFromIface(env: *Env, recvTy: *T.Type, callee: []const u8, typedArgs: []ast.CallArgOf(.typed)) InferError!?*T.Type {
    const ifaceName = primitiveInterfaceName(recvTy.named.name) orelse return null;
    var current: ?[]const u8 = ifaceName;
    var guard: usize = 0;
    while (current) |cname| {
        if (guard >= 16) break;
        guard += 1;
        const decl = env.assocInterfaceDecls.get(cname) orelse return null;

        // (a) Declared `fn` method (host-backed or `default fn`) — derive its
        // return type via the same generic-substitution path the stdlib lib
        // dispatch uses, so `map<U>(…) -> Array<U>` yields a fresh-var element.
        for (decl.methods) |m| {
            if (!std.mem.eql(u8, m.name, callee)) continue;
            if (m.params.len == 0 or !std.mem.eql(u8, m.params[0].name, "self")) continue;
            var gm = std.StringHashMap(*T.Type).init(env.arena);
            defer gm.deinit();
            try gm.put("Self", recvTy);
            if (recvTy.named.args.len >= 1) try gm.put("T", recvTy.named.args[0]);
            for (m.genericParams) |gp| try gm.put(gp.name, try env.freshVar());
            // A method-level type parameter is what the ARGUMENT says it is:
            // `map<U>(self, f: fn(T) -> U)` answers `Array<U>` with `U` the
            // lambda's own return, `fold<A>(self, init: A, …)` an `A` of the
            // initial value. Left fresh, `es.map({ e -> e.key })` was an array
            // of nothing known, so `ks.at(0)?.length()` never took the
            // `length` rename and commonJS called the property. Only a
            // parameter that IS the type parameter, or a function parameter
            // RETURNING it, binds it — a `fn(item: T)` declared `void` is
            // never held to its return (`forEach`'s value-bodied lambdas).
            for (m.params[1..], 0..) |p, i| {
                if (i >= typedArgs.len) break;
                if (typedArgs[i].label != null) break;
                const argTy = typedArgs[i].value.getType();
                const target: ?[]const u8, const from: *T.Type = switch (p.typeRef) {
                    .named => |n| .{ n, argTy },
                    .function => |f| blk: {
                        const d = argTy.deref();
                        if (d.* != .func) continue;
                        // 144 B-115 — a function named as the argument
                        // (`xs.map(show)`, `show` generic) takes the declared
                        // parameter types where its own are still open, so
                        // the instance this use makes is known (commonJS
                        // reads its print shapes off it).
                        if (typedArgs[i].value.* == .identifier and f.params.len == d.func.params.len) for (f.params, d.func.params) |fp, ap| {
                            if (ap.deref().* != .typeVar) continue;
                            const want = try resolveTypeRefInContext(env, fp, gm);
                            if (!typeIsGround(want, 0)) continue;
                            try unifyAt(env, ap, want, typedArgs[i].value.getLoc());
                        };
                        break :blk switch (f.returnType.*) {
                            .named => |n| .{ n, d.func.ret },
                            else => .{ null, argTy },
                        };
                    },
                    else => continue,
                };
                const name = target orelse continue;
                // A lambda whose body ends in `return` statements is typed
                // `void` here; its returns say nothing this could hold it to.
                const fd = from.deref();
                if (fd.* == .named and (std.mem.eql(u8, fd.named.name, "void") or std.mem.eql(u8, fd.named.name, "noreturn"))) continue;
                for (m.genericParams) |gp| if (std.mem.eql(u8, gp.name, name)) {
                    try unifyAt(env, gm.get(name).?, from, typedArgs[i].value.getLoc());
                    break;
                };
            }
            return if (m.returnType) |rt|
                try resolveTypeRefInContext(env, rt, gm)
            else
                try env.namedType("void");
        }

        // (b) `val name: T` interface field accessed as `recv.name()`. The
        // `length` rename routes both `xs.len()` and `xs.size()` to the same
        // intrinsic property, so they share the field's declared type.
        const field_name: []const u8 = if (std.mem.eql(u8, callee, "len") or std.mem.eql(u8, callee, "size"))
            "length"
        else
            callee;
        for (decl.fields) |f| {
            if (std.mem.eql(u8, f.name, field_name)) return switch (f.typeRef) {
                .named => |n| try env.namedType(n),
                else => try resolveTypeRefInContext(env, f.typeRef, std.StringHashMap(*T.Type).init(env.arena)),
            };
        }

        current = if (decl.extends.len > 0) decl.extends[0] else null;
    }
    return null;
}

/// The declared parameter types of a builtin-primitive method, `self` dropped
/// and resolved against the receiver: `Array<Item>.filter` answers
/// `[fn(Item) -> bool]`. Same interface walk and same generic substitution as
/// `primMethodReturnTypeFromIface` — `Self` is the receiver, `T` its first type
/// argument, a method-level `<U>` a fresh var. Null when the receiver is not a
/// builtin primitive or the interface does not declare `callee`.
///
/// Read before the call's arguments are inferred, so a lambda argument's
/// parameters are bound to the element type instead of a fresh var. Without it
/// `xs.filter({ e -> e.name.contains("x") })` typed `e` as an unresolved
/// variable, the `contains` receiver never reached `.named`, and the
/// `@External.Node("includes")` rename never fired — commonJS emitted
/// `.contains(…)`, which node refuses.
fn primMethodParamTypes(env: *Env, recvTy: *T.Type, callee: []const u8) InferError!?[]*T.Type {
    const rt = recvTy.deref();
    if (rt.* != .named) return null;
    if (primKindOfName(rt.named.name) == null) return null;
    const ifaceName = primitiveInterfaceName(rt.named.name) orelse return null;
    var current: ?[]const u8 = ifaceName;
    var guard: usize = 0;
    while (current) |cname| {
        if (guard >= 16) break;
        guard += 1;
        const decl = env.assocInterfaceDecls.get(cname) orelse return null;
        for (decl.methods) |m| {
            if (!std.mem.eql(u8, m.name, callee)) continue;
            if (m.params.len == 0 or !std.mem.eql(u8, m.params[0].name, "self")) continue;
            var gm = std.StringHashMap(*T.Type).init(env.arena);
            defer gm.deinit();
            try gm.put("Self", rt);
            if (rt.named.args.len >= 1) try gm.put("T", rt.named.args[0]);
            for (m.genericParams) |gp| try gm.put(gp.name, try env.freshVar());
            const out = try env.arena.alloc(*T.Type, m.params.len - 1);
            for (m.params[1..], 0..) |p, i| {
                out[i] = try paramTypeInContext(env, p, gm);
            }
            return out;
        }
        current = if (decl.extends.len > 0) decl.extends[0] else null;
    }
    return null;
}

/// True when `ty` carries no type variable anywhere — the receiver's element
/// type is actually KNOWN. `primMethodParamTypes`' answer is only pushed into a
/// lambda when the declared PARAMETERS are ground: an element type that is
/// still a variable tells the lambda nothing it did not already have, and
/// unifying the lambda's parameter with it adds edges that are not the method's
/// meaning — `Query<T>.min`'s `var best = keys.at(0); keys.forEach({ k -> …
/// best = k; })` becomes `?K = K` and reds "recursive type detected". The
/// declared RETURN is not checked: `map<U>(self, transform: fn(item: T) -> U)`
/// has a fresh `U` by construction, and `params_only` drops it anyway.
fn typeIsGround(ty: *T.Type, depth: usize) bool {
    if (depth > 8) return false;
    const d = ty.deref();
    return switch (d.*) {
        .typeVar => false,
        .named => |n| blk: {
            for (n.args) |a| if (!typeIsGround(a, depth + 1)) break :blk false;
            break :blk true;
        },
        .func => |f| blk: {
            for (f.params) |a| if (!typeIsGround(a, depth + 1)) break :blk false;
            break :blk typeIsGround(f.ret, depth + 1);
        },
        .union_ => |ms| blk: {
            for (ms) |m| if (!typeIsGround(m, depth + 1)) break :blk false;
            break :blk true;
        },
        .record => |fs| blk: {
            for (fs) |f| if (!typeIsGround(f.type_, depth + 1)) break :blk false;
            break :blk true;
        },
    };
}

/// E3.9 — `ty` as the value of `source` (an `await`, a `for` item): when it is
/// a `@Result`, a fresh copy of its type node carrying that origin in
/// `env.resultOrigins` (and the `try` / `throw` the original was inferred
/// from, if any), so a mismatch on it names the fix for that source. Any other
/// type is answered as is.
fn markResultSource(env: *Env, ty: *T.Type, source: errorMod.ResultOrigin.Source) InferError!*T.Type {
    const d = ty.deref();
    if (d.* != .named or !std.mem.eql(u8, d.named.name, "Result")) return ty;
    var origin = env.resultOrigins.get(d) orelse errorMod.ResultOrigin{};
    origin.source = source;
    const copy = try env.arena.create(T.Type);
    copy.* = d.*;
    try env.resultOrigins.put(env.arena, copy, origin);
    return copy;
}

/// E3.9 — `result` is the `@Result` an `async { }` block's value or an `iter` /
/// `stream` item became on its own: record the first `try` / `throw` of
/// `body` that made it one.
fn noteInferredResult(env: *Env, result: *T.Type, body: []const ast.Stmt) InferError!void {
    const at = ast.bodyFirstFail(body) orelse return;
    const by: errorMod.ResultOrigin.MadeBy = if (ast.bodyFirstThrow(body)) |t|
        (if (t.eql(at)) .throw_ else .try_)
    else
        .try_;
    try env.resultOrigins.put(env.arena, result, .{ .made_at = at, .made_by = by });
}

/// The prelude enum a sequence steps with (decision 122), registered by
/// `comptime.zig` (`yield_step_src`) and spliced into a module that names it.
pub const yield_step_type_name = "YieldStep";

/// Decision 122 — `.next()` on an `@Iter<T>` / `@AsyncIter<T>` receiver, or
/// null when the call is anything else.
fn inferSequenceNext(
    env: *Env,
    recv: *TypedExpr,
    callee: []const u8,
    args: anytype,
    trailing: anytype,
    loc: ast.Loc,
) InferError!?TypedExpr {
    if (!std.mem.eql(u8, callee, "next") or args.len != 0 or trailing.len != 0) return null;
    const rt = recv.getType().deref();
    if (rt.* != .named or rt.named.args.len != 1) return null;
    const kind: envMod.SequenceKind = if (std.mem.eql(u8, rt.named.name, "Iter"))
        .iterator
    else if (std.mem.eql(u8, rt.named.name, "AsyncIter"))
        .stream
    else
        return null;
    env.usesYieldStep = true;
    try env.instanceLowerings.put(loc, .{ .sequence_next = kind });
    const step_args = try env.arena.alloc(*T.Type, 1);
    step_args[0] = rt.named.args[0];
    const step = try env.namedTypeArgs(yield_step_type_name, step_args);
    const ret = switch (kind) {
        .iterator => step,
        .stream => blk: {
            const task_args = try env.arena.alloc(*T.Type, 1);
            task_args[0] = step;
            break :blk try env.namedTypeArgs("Async", task_args);
        },
    };
    return TypedExpr{ .call = .{ .loc = loc, .type_ = ret, .kind = .{ .call = .{
        .receiver = recv,
        .callee = callee,
        .is_builtin = false,
        .args = args,
        .trailing = trailing,
    } } } };
}

/// Record how a value-receiver instance call `recv.callee(args)` lowers on the
/// backends without native method dispatch (erlang/beam/wasm). A primitive
/// receiver records its `PrimKind`; any other nominal type records as a record
/// method carrying its type name (the backend resolves local vs imported owner).
/// commonJS ignores the table (it dispatches natively).
/// Decision 328 — a lambda's types come from where it is used. A method call
/// whose receiver was still free when its body was checked (`(fn(n) {
/// n.toString() })(2)`: `n` is `i32` only once the call is; a binding no
/// longer reaches it, decision 583) is answered here,
/// after the module's bodies: the receiver's type now known, the call records
/// the lowering and the return type a call on that type records when it is
/// checked, so wasm, erlang and beam lower it as commonJS dispatches it. A
/// lambda parameter nothing typed is refused at the call: no position, no
/// annotation and no use gave it a type (328), and no backend can choose a
/// method for it.
fn resolvePendingReceiverCalls(env: *Env) InferError!void {
    defer env.pendingReceiverCalls.clearRetainingCapacity();
    var i: usize = 0;
    // A resolved call can type the receiver of a later one (`n.toString().length()`).
    while (i < env.pendingReceiverCalls.items.len) : (i += 1) {
        const p = env.pendingReceiverCalls.items[i];
        const recvTy = p.receiver.deref();
        switch (recvTy.*) {
            .named => |n| {
                if (env.instanceLowerings.get(p.loc) != null) continue;
                if (primKindOfName(n.name)) |pk| {
                    try recordInstanceCall(env, p.loc, n.name);
                    try recordWidthMember(env, p.loc, n.name, p.callee);
                    if ((pk == .array or pk == .string or pk == .bytes) and
                        (std.mem.eql(u8, p.callee, "len") or std.mem.eql(u8, p.callee, "size") or std.mem.eql(u8, p.callee, "length")))
                    {
                        try env.jsMethodRenames.put(p.loc, "length");
                    } else if (try primMethodNodeRename(env, recvTy, p.callee)) |rn| {
                        try env.jsMethodRenames.put(p.loc, rn);
                    }
                    if (try primMethodReturnTypeFromIface(env, recvTy, p.callee, p.args)) |ret| {
                        try unifyAt(env, p.ret, ret, p.loc);
                    } else try refuseUndeclaredPrimMethod(env, recvTy, p.callee, p.loc, true);
                } else if (env.hasInherentMethod(n.name, p.callee)) {
                    try recordInstanceCall(env, p.loc, n.name);
                } else if (env.lookupTypeDef(n.name)) |td| if (!typeAnswersMember(env, td, p.callee)) {
                    env.lastError = TypeError.unknownMethod(n.name, p.callee).withLoc(p.loc);
                    return error.TypeError;
                };
            },
            .typeVar => |cell| if (cell.state == .unbound) if (p.param) |name| {
                const msg = try std.fmt.allocPrint(env.arena, "cannot infer the type of `{s}`: the lambda's parameter calls `{s}` and nothing gives it a type", .{ name, p.callee });
                env.lastError = TypeError.custom(msg, "A lambda's types come from where it is used (decision 328): annotate the binding (`val f: fn(n: i32) -> string = { n -> … };`), pass the lambda where a function type is expected, or write a typed `fn` expression (`fn(n: i32) -> string { … }`).").withLoc(p.loc);
                return error.TypeError;
            },
            else => {},
        }
    }
}

/// Decisions 617 (3), 496 — a call of a member the primitive width declares
/// itself (`n.abs()` on an `i32`: `pub type i32 implement Signed { … declare fn
/// abs(self: Self) -> Self; }`) is that width's own function: recorded as a
/// `.width` lowering, which the transform writes `__i32_abs(n)`
/// (`prelude_cache.widthMemberName`). A member only a contract declares keeps
/// the primitive dispatch.
fn recordWidthMember(env: *Env, loc: ast.Loc, typeName: []const u8, callee: []const u8) InferError!void {
    if (preludeCache.widthMember(typeName, callee) == null) return;
    try env.method_lowerings.put(loc, .{ .domain = .width, .op = .map, .width = typeName });
}

fn recordInstanceCall(env: *Env, loc: ast.Loc, typeName: []const u8) InferError!void {
    if (primKindOfName(typeName)) |k| {
        try env.instanceLowerings.put(loc, .{ .prim = k });
    } else {
        try env.instanceLowerings.put(loc, .{ .type_ = typeName });
    }
}

/// The member table of `primitives.bp` a primitive type's methods are found
/// in first. A width is a type (decision 617 (1)): its contract is the
/// `implement` clause of its `pub type i32 implement Signed { … }`, read from
/// the text (`prelude_cache.primitiveContract`). `string`, `bool`, `array`,
/// `bigint` and `bytes` hold their own methods (decision 641): the table is
/// the type's own name (`prelude_cache.dissolvedTypesAsMemberTables`).
fn primitiveInterfaceName(typeName: []const u8) ?[]const u8 {
    if (preludeCache.primitiveContract(typeName)) |c| return c;
    for (owned_member_types) |t| if (std.mem.eql(u8, typeName, t)) return t;
    return null;
}

/// Decision 641 — the primitive types that hold their own members, each
/// table under the type's name.
const owned_member_types = [_][]const u8{ "array", "bool", "string", "bigint", "bytes" };

/// The primitive a member table of `primitives.bp` is the table of (`string`
/// → `string`), the inverse of `primitiveInterfaceName` for the primitives
/// that hold their own members. A contract the widths share (`Signed`,
/// `Float`) is no one type's: null.
fn primitiveOfInterface(iface: []const u8) ?[]const u8 {
    for (owned_member_types) |p| if (std.mem.eql(u8, p, iface)) return p;
    return null;
}

/// JS prototype-method rename driven by the bare-symbol `.JavaScript("X")`
/// implementation of a primitive-receiver interface method. Returns the host
/// symbol `X` when it differs from `callee` (the call site emits
/// `recv.X(args)` instead of `recv.callee(args)`); returns null when there is
/// no node implementation, or when the symbol carries a call template
/// (`"sym(a, self)"`) — those are not call-site renames. Walks the receiver's interface and its `extends`
/// chain so an annotation on `Number.toString` covers every numeric width.
fn primMethodNodeRename(env: *Env, recvTy: *T.Type, callee: []const u8) InferError!?[]const u8 {
    const ifaceName = primitiveInterfaceName(recvTy.named.name) orelse return null;
    var current: ?[]const u8 = ifaceName;
    var guard: usize = 0;
    while (current) |cname| {
        if (guard >= 16) break;
        guard += 1;
        const decl = env.assocInterfaceDecls.get(cname) orelse return null;
        for (decl.methods) |m| {
            if (!std.mem.eql(u8, m.name, callee)) continue;
            if (m.params.len == 0 or !std.mem.eql(u8, m.params[0].name, "self")) continue;
            const ref = m.externalFor("node") orelse return null;
            if (ref.cell != null) return null;
            if (std.mem.indexOfScalar(u8, ref.text, '(') != null) return null;
            if (std.mem.eql(u8, ref.text, callee)) return null;
            return ref.text;
        }
        current = if (decl.extends.len > 0) decl.extends[0] else null;
    }
    return null;
}

/// Pending 0203-a, answered (b): a primitive receiver answers only what its
/// interface (and the interfaces it extends) declares — a `fn` method, a `val`
/// field, the `len`/`size` spellings of `length` — or what an `extend` block on
/// it adds. Anything else used to type as a fresh variable and reach the host
/// under its own spelling: `"abc".toUpperCase()` ran on node, and erlang/beam
/// needed an alias table to follow. Refused at the call, naming the declared
/// method a near spelling points at: the one whose `@External.Node` host symbol
/// is the name written, else one an edit away. Silent when the interface is not
/// registered (an environment without the prelude has nothing to check against).
/// Decision 873 (2) — the receiver is a primitive type's own name, no binding
/// shadowing it (`string.fromCodepoint(65)`): its statics answer there. A
/// local or a parameter of the name (`val bytes = …`) is the value.
fn receiverNamesPrimitiveType(env: *Env, recv: ?*ast.Expr) bool {
    const r = recv orelse return false;
    if (r.* != .identifier or r.identifier.kind != .ident) return false;
    const name = r.identifier.kind.ident;
    if (primitiveInterfaceName(name) == null) return false;
    if (env.boundInBody(name)) return false;
    if (env.lookup(name)) |t| if (!t.deref().isNamed(name)) return false;
    return true;
}

fn refuseUndeclaredPrimMethod(env: *Env, recvTy: *T.Type, callee: []const u8, loc: ast.Loc, statics: bool) InferError!void {
    const ifaceName = primitiveInterfaceName(recvTy.named.name) orelse return;
    if (env.assocInterfaceDecls.get(ifaceName) == null) return;
    if (std.mem.eql(u8, callee, "len") or std.mem.eql(u8, callee, "size")) return;
    if (env.hasInherentMethod(recvTy.named.name, callee)) return;
    var ext_it = env.extensions.iterator();
    while (ext_it.next()) |e| {
        const entry = e.value_ptr.*;
        if (!std.mem.eql(u8, entry.target, recvTy.named.name) and !std.mem.eql(u8, entry.target, ifaceName)) continue;
        if (namesContain(entry.methods, callee)) return;
    }
    var host_match: ?[]const u8 = null;
    var near_match: ?[]const u8 = null;
    var current: ?[]const u8 = ifaceName;
    var guard: usize = 0;
    while (current) |cname| : (guard += 1) {
        if (guard >= 16) break;
        const decl = env.assocInterfaceDecls.get(cname) orelse break;
        for (decl.methods) |m| {
            // Decision 873 (2) — a static (no `self`) answers the type's name,
            // never a value: `bytes.fromUtf8(s)` on a local `bytes` is a
            // method call on the value.
            if (std.mem.eql(u8, m.name, callee)) {
                if (statics or (m.params.len > 0 and std.mem.eql(u8, m.params[0].name, "self"))) return;
                continue;
            }
            if (host_match == null) if (m.externalFor("node")) |ref| {
                if (std.mem.eql(u8, ref.text, callee)) host_match = m.name;
            };
            if (near_match == null and editDistanceIsOne(callee, m.name)) near_match = m.name;
        }
        for (decl.fields) |f| {
            if (std.mem.eql(u8, f.name, callee)) return;
            if (near_match == null and editDistanceIsOne(callee, f.name)) near_match = f.name;
        }
        current = if (decl.extends.len > 0) decl.extends[0] else null;
    }
    const tn = try errorMod.typeLabelAlloc(env.arena, recvTy);
    const msg = if (host_match orelse near_match) |sugg|
        try std.fmt.allocPrint(env.arena, "{s}: `{s}` has no method `{s}` — did you mean `{s}`?", .{ diagnostics.unknown_primitive_method, tn, callee, sugg })
    else
        try std.fmt.allocPrint(env.arena, "{s}: `{s}` has no method `{s}`", .{ diagnostics.unknown_primitive_method, tn, callee });
    const hint = try std.fmt.allocPrint(env.arena, "The methods of `{s}` are the ones `{s}` declares in the std prelude (`primitives.bp`), and those of a contract implemented for it (`implement <Behavior> for {s}`, decision 799).", .{ tn, ifaceName, tn });
    env.lastError = TypeError.custom(msg, hint).withLoc(loc);
    return error.TypeError;
}

const FoundMethod = struct { method: ast.BehaviorMethod, owner: []const u8 };

/// Find an instance method (`self` receiver) named `callee` in interface
/// `ifaceName`, following its `extends` chain. Matches `default fn` methods (their
/// body is materialized) and `@[external]` declarations that bind to a JS global
/// namespace (`Math`) — those lower to `Math.sym(self, …)`. `@[external]` methods
/// backed by a relative companion (`./gleam_stdlib.mjs`, e.g. `map`/`filter`/
/// `join`/`split`) are left to the permissive path (native JS handles them), so
/// this doesn't intercept array/string methods that already work.
fn findInterfaceDefaultFn(env: *Env, ifaceName: []const u8, callee: []const u8) ?FoundMethod {
    var current: ?[]const u8 = ifaceName;
    var guard: usize = 0;
    while (current) |cname| {
        if (guard >= 16) break;
        guard += 1;
        const decl = env.assocInterfaceDecls.get(cname) orelse return null;
        for (decl.methods) |m| {
            if (!std.mem.eql(u8, m.name, callee)) continue;
            if (m.params.len == 0 or !std.mem.eql(u8, m.params[0].name, "self")) continue;
            if (m.is_default) return .{ .method = m, .owner = cname };
            if (m.externalFor("node")) |ref| {
                // Template-form implementation (`$0`/`$1`/… markers): the
                // commonJS prototype patcher (§F1) renders the template into a
                // `Owner.prototype.<m>` body, so dispatch resolution should run
                // here too (marks the interface used so codegen walks it). A
                // bare symbol (`.JavaScript("X")`) names a native prototype method —
                // the prim-block rename's, NOT here.
                if (primOpTemplate.looksLikeTemplate(ref.text)) {
                    return .{ .method = m, .owner = cname };
                }
            }
        }
        current = if (decl.extends.len > 0) decl.extends[0] else null;
    }
    return null;
}

/// Resolve a method/param's type within a generic context, handling both
/// fn-typed params (`f: fn(a: A) -> B`) and ordinary type-ref params.
fn paramTypeInContext(env: *Env, p: ast.Param, gm: std.StringHashMap(*T.Type)) InferError!*T.Type {
    return try resolveParamType(env, p, gm);
}

/// Infer type for `use`-hook expressions (decisions 104, 354, 357).
///
/// The enclosing function's return type decides whether `use` is allowed. The
/// capability was recorded in
/// `env.fnContext` by `inferFnDecl` before the body was visited.
fn inferUseHookExpr(env: *Env, uh: ast.UseHookExprOf(.untyped), loc: ast.Loc) InferError!TypedExpr {
    // Decision 354 (3) — `use` exists only where there is a render tree: a
    // decorator body, a template body and a `comptime { … }` are compile-time
    // evaluation with none. What they need comes from the catalogue (353).
    if (env.comptimeDepth > 0 or env.inDecoratorFn or env.inTemplateFn) {
        const where: []const u8 = if (env.comptimeDepth > 0)
            "a `comptime` block or expression"
        else if (env.inDecoratorFn)
            "a decorator's body"
        else
            "a template function's body";
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `use` inside {s} — compile-time evaluation has no render tree, so no hook runs there (decision 354)", .{ diagnostics.use_outside_render_tree, where });
        env.lastError = TypeError.custom(msg, "Read what compile-time code needs from the catalogue (`@TypeInfo.all(with: …)`) or from its arguments; `use` belongs in a `component` body.").withLoc(loc);
        return error.TypeError;
    }
    // Decision 357 — the rules of hooks: a `use` stands at the top level of a
    // `@Component` body and runs on every call (an `iter` / `stream` loop's
    // body, decision 125, is one of the constructs it may not stand in).
    if (env.useConstruct) |what| {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `use` inside {s} — a `use` is written at the top level of a `component` body and runs on every call (decision 357)", .{ diagnostics.use_not_top_level, what });
        env.lastError = TypeError.custom(msg, "Move the `use` to the top level of the body; a condition goes inside its argument (`use provide(Ctx, if (c) a else b);`), never around it.").withLoc(loc);
        return error.TypeError;
    }
    const fc = env.fnContext orelse {
        env.lastError = TypeError.useNotAllowed("void").withLoc(loc);
        return error.TypeError;
    };
    // Decision 104 — `use` is legal only in a `#[@use]` body, whatever the
    // return type: a `#[@future] fn … -> @Future<Element>` does not activate
    // (decision 90 revoked), and neither does an unannotated fn.
    // Decision 804 (1) — a type component's helper is an ordinary method.
    if (!fc.annotated) if (fc.composeHelperOf) |comp| {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `use` in `{s}.{s}`, a helper of the type component `{s}` — hooks are read in its `compose` alone (decision 804 (1))", .{ diagnostics.component_use_outside_compose, comp, fc.fnName, comp });
        env.lastError = TypeError.custom(msg, "Read the hook in `compose` and hand its value to the helper as an argument.").withLoc(loc);
        return error.TypeError;
    };
    if (!fc.annotated) {
        env.lastError = TypeError.useWithoutComponent(fc.fnName, fc.returnDisplay).withLoc(loc);
        return error.TypeError;
    }
    // A nested closure is not the `#[@use]` body: like `await`, which a
    // closure does not inherit either (`env.starFn` is cleared there), `use`
    // stays in the body that carries the annotation (decision 87: `use` never
    // leaves a function body). On commonJS the hook is an `async function`
    // (decision 104), and an `await` in a plain arrow would not parse.
    if (env.earlyExitLine) |line| {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `use` after the statement on line {d}, which may return early — this `use` would not run on every call (decision 357)", .{ diagnostics.use_not_top_level, line });
        env.lastError = TypeError.custom(msg, "Move every `use` before the first statement that may `return`, `throw` or `try`.").withLoc(loc);
        return error.TypeError;
    }
    if (env.asyncBlockDepth > 0) {
        env.lastError = TypeError.custom(
            diagnostics.use_without_component ++
                ": `use` inside an `async { }` block — the block is closed like a closure (decision 124), and `use` does not enter it",
            "Activate the hook in the `component` body before the block and let the block read its value.",
        ).withLoc(loc);
        return error.TypeError;
    }
    if (env.starFn == null) {
        env.lastError = TypeError.custom(
            diagnostics.use_without_component ++
                ": `use` inside a nested closure — the closure is not the `component` body, and `use` is not inherited (as `await` is not)",
            "Activate the hook in the `component` body itself (`val s = use state(0);`) and let the closure read `s`.",
        ).withLoc(loc);
        return error.TypeError;
    }
    // The `@Component` return granted `use`; this is the belt for a return
    // type still unresolved.
    if (!fc.implementsContext) {
        env.lastError = TypeError.useNotAllowed(fc.returnDisplay).withLoc(loc);
        return error.TypeError;
    }

    // `use <hookcall>` — infer the wrapped call, check it is a hook, and
    // expose its Return type `R` as the prefix's type. Any
    // binding/destructuring is performed by the enclosing `val`/`var`.
    const prevInUse = env.inUseOperand;
    env.inUseOperand = true;
    const prevUseOperand = env.useOperandLoc;
    env.useOperandLoc = if (uh.kind.inner.* == .call) uh.kind.inner.call.loc else null;
    const valTyped = inferExprTyped(env, uh.kind.inner.*) catch |err| {
        env.inUseOperand = prevInUse;
        env.useOperandLoc = prevUseOperand;
        return err;
    };
    env.inUseOperand = prevInUse;
    env.useOperandLoc = prevUseOperand;
    const valPtr = try makeTypedPtr(env, valTyped);
    try validateUseOperand(env, valTyped.getType(), loc);
    try env.useOperandTypes.put(env.arena, loc, valTyped.getType());
    // Decision 791 (3) — `use c` over a component resolves it: the body
    // renders a child here (354 (2)), run with its children's scope.
    if (isComponentType(env, valTyped.getType())) {
        try env.componentUses.put(env.arena, loc, {});
        if (env.firstRenderAt == null) env.firstRenderAt = loc;
    }
    try noteContextUse(env, uh.kind.inner.*, valTyped, fc, loc);
    try noteMemoUse(env, uh.kind.inner.*, valTyped, loc);
    try noteHookUse(env, uh.kind.inner.*, valTyped, loc);
    // Decision 723 — `use context(ctx)` answers `T`, the type of the
    // `Context<T>` it names; `use inject(R)` answers `R` (416).
    const srcTy = if (env.contextUses.get(loc)) |cu| (if (cu.kind == .read or cu.kind == .inject) cu.value_type else bindingSourceType(valTyped.getType())) else bindingSourceType(valTyped.getType());
    return TypedExpr{ .useHook = .{ .loc = loc, .type_ = srcTy, .kind = .{ .inner = valPtr } } };
}

/// True when a binding's value is a `use`-hook prefix expression.
fn isUseHookValue(value: *const ast.ExprOf(.untyped)) bool {
    return value.* == .useHook;
}

/// Verify a `use` operand is a `Component<R>`: a hook (`R` does not
/// implement `@Renderable`, decisions 104, 354) or a component, which `use`
/// resolves inside a component body (decision 791 (3)); anything else is not
/// a hook at all.
fn validateUseOperand(env: *Env, valTy: *T.Type, loc: ast.Loc) InferError!void {
    if (isHookType(env, valTy)) return;
    if (isComponentType(env, valTy)) return;
    const disp = baseNameOfType(valTy) orelse "value";
    env.lastError = TypeError.useNotContext(disp).withLoc(loc);
    return error.TypeError;
}

/// Decision 354 (8) — a call whose value is (or may resolve to) a
/// `@Component<R>` passes the hidden context map; `context_lower.zig` reads
/// the type once it is resolved. std's `provide` / `context` are lowered
/// where they are `use`d, and a builtin takes no map.
fn noteComponentCall(env: *Env, c: ast.CallExprOf(.untyped), typed: TypedExpr) InferError!void {
    if (c.kind != .call or c.kind.call.is_builtin) return;
    if (stdContextCallee(env, c) != null) return;
    const ty = typed.getType();
    switch (ty.deref().*) {
        .named => |n| if (!std.mem.eql(u8, n.name, "Component")) return,
        .typeVar => {},
        else => return,
    }
    try noteHookCall(env, c, ty);
    // A call walked twice keeps the type its first walk recorded; built code
    // is located by its expansion (decision 429), so no other call shares
    // the location.
    const gop = try env.componentCalls.getOrPut(env.arena, c.loc);
    if (!gop.found_existing) gop.value_ptr.* = ty;
}

/// The host function a call names — a bodyless `declare fn` or an
/// `#[@External…]` binding of this module, or one an imported module
/// published as a host — or null. std's `provide` / `context` are lowered
/// where they are written and are no host.
fn hostCallee(env: *Env, c: ast.CallExprOf(.untyped)) InferError!?hooksMod.DeclRef {
    const ref = try hookCalleeDecl(env, c) orelse return null;
    if (std.mem.eql(u8, ref.module, "std/context")) return null;
    if (std.mem.eql(u8, ref.module, env.modulePath)) {
        const f = env.fnDecls.get(ref.name) orelse return null;
        return if (isHookHost(f)) ref else null;
    }
    const r = env.reflection orelse return null;
    const info = r.hookFns.get(try envMod.declIdentity(env.arena, ref.module, ref.name)) orelse return null;
    return if (info.host) ref else null;
}

/// Decision 388 — a call of a host function: what a host answers is the
/// host's own value, never a lambda over a `RenderScope`, so a `use` or an
/// `await` of it runs nothing (`context_lower.zig`).
fn noteHostCall(env: *Env, c: ast.CallExprOf(.untyped)) InferError!void {
    if (c.kind != .call or c.kind.call.is_builtin) return;
    _ = try hostCallee(env, c) orelse return;
    try env.hostCalls.put(env.arena, c.loc, {});
}

/// Decision 357 — enter a construct a `use` may not stand in (a branch, a
/// loop, a lambda, …); the outermost one names it. Answers the value to
/// restore on the way out.
fn enterUseConstruct(env: *Env, what: []const u8) ?[]const u8 {
    const prev = env.useConstruct;
    if (prev == null) env.useConstruct = what;
    return prev;
}

/// Decision 354 — which declaration of std's `context` module a call names:
/// a leaf import's local name (`provide(…)`), or a call through the
/// namespace (`context.provide(…)` after `import {context} from "std"`).
fn stdContextCallee(env: *Env, c: ast.CallExprOf(.untyped)) ?envMod.StdContextName {
    if (c.kind != .call) return null;
    const call = c.kind.call;
    if (call.is_builtin or call.calleeExpr != null) return null;
    if (call.receiver) |r| {
        if (r.* != .identifier or r.identifier.kind != .ident) return null;
        const handle = r.identifier.kind.ident;
        if (env.localBindDepth(handle) != null) return null;
        const module = env.stdImports.get(handle) orelse return null;
        if (!std.mem.eql(u8, module, "context")) return null;
        if (std.mem.eql(u8, call.callee, "Context")) return .context_type;
        if (std.mem.eql(u8, call.callee, "createContext")) return .create_context;
        if (std.mem.eql(u8, call.callee, "inject")) return .inject;
        if (std.mem.eql(u8, call.callee, "provide")) return .provide;
        if (std.mem.eql(u8, call.callee, "context")) return .context;
        if (std.mem.eql(u8, call.callee, "RenderScope")) return .render_scope;
        return null;
    }
    if (env.localBindDepth(call.callee) != null) return null;
    return env.stdContextNames.get(call.callee);
}

/// Decisions 771, 774 — whether `c` calls std's `hooks.memo`: a name a leaf
/// import binds to it, or `hooks.memo(…)` through the module's handle.
fn isStdMemoCall(env: *Env, c: ast.CallExprOf(.untyped)) bool {
    if (c.kind != .call) return false;
    const call = c.kind.call;
    if (call.is_builtin or call.calleeExpr != null) return false;
    if (call.receiver) |r| {
        if (r.* != .identifier or r.identifier.kind != .ident) return false;
        const handle = r.identifier.kind.ident;
        if (env.localBindDepth(handle) != null) return false;
        const module = env.stdImports.get(handle) orelse return false;
        return std.mem.eql(u8, module, "hooks") and std.mem.eql(u8, call.callee, "memo");
    }
    if (env.localBindDepth(call.callee) != null) return false;
    return env.stdMemoNames.contains(call.callee);
}

/// Decisions 755, 771 — a `use memo(make)`: recorded with the `T` it answers,
/// so the scope lowering gives it a slot made with the component's value.
fn noteMemoUse(env: *Env, operand: ast.Expr, typed: TypedExpr, loc: ast.Loc) InferError!void {
    if (operand != .call or !isStdMemoCall(env, operand.call)) return;
    const d = typed.getType().deref();
    const answered = if (d.* == .named and std.mem.eql(u8, d.named.name, "Component") and d.named.args.len == 1) d.named.args[0] else typed.getType();
    try env.memoUses.put(env.arena, loc, answered);
}

/// Decision 354 — the two hooks are `use`d and nothing else, and a context is
/// made only where it is declared: `Context<T>()`, with no argument, as the
/// whole initializer of a module-level `val` (its identity is the
/// declaration, 281).
fn checkStdContextCall(env: *Env, c: ast.CallExprOf(.untyped)) InferError!void {
    const which = stdContextCallee(env, c) orelse return;
    switch (which) {
        .context_type => {
            env.lastError = TypeError.custom(
                diagnostics.context_not_declared ++ ": a context is made by `createContext(value)`, not by its type's constructor (decision 379)",
                "Declare a type's default once at module level (`pub val themeContext = comptime createContext(Theme(…));`) and provide another with `use provide(createContext(Theme(…)));`.",
            ).withLoc(c.loc);
            return error.TypeError;
        },
        .create_context => try env.createContextCalls.put(env.arena, c.loc, {}),
        .provide, .context, .inject => {
            if (env.useOperandLoc) |at| if (std.meta.eql(at, c.loc)) return;
            return refuseContextHookWithoutUse(env, c.kind.call.callee, c.loc);
        },
        // Decision 388 (2) — a scope is opaque: the render library holds the
        // ones `run` answers, and the first comes from `RenderScope.root()`.
        .render_scope => {
            env.lastError = TypeError.custom(
                diagnostics.render_scope_construction ++ ": a `RenderScope` is made only by `RenderScope.root()` — every other scope is the one a component's `run` answered (decision 388)",
                "Start a render with `c.run(RenderScope.root())` and run each child with the `scope` its parent's `Rendered` holds.",
            ).withLoc(c.loc);
            return error.TypeError;
        },
    }
}

/// Decision 811 (1) — `X(…)` of an opaque `X`, or `X.m(…)` naming one of its
/// methods without `pub`, outside `X`'s own methods (`opaque_types.zig`).
fn checkOpaqueCall(env: *Env, c: ast.CallExprOf(.untyped)) InferError!void {
    if (c.kind != .call) return;
    const call = c.kind.call;
    if (call.is_builtin or call.calleeExpr != null) return;
    if (call.receiver) |recv| {
        if (recv.* != .identifier or recv.identifier.kind != .ident) return;
        const raw = recv.identifier.kind.ident;
        if (env.localBindDepth(raw) != null) return;
        const name = env.importedTypeAliases.get(raw) orelse raw;
        return methodVisibility.refuseCall(env, name, call.callee, c.loc, call.lowering);
    }
    if (env.localBindDepth(call.callee) != null) return;
    const name = env.importedTypeAliases.get(call.callee) orelse call.callee;
    return opaqueTypes.refuseConstruction(env, name, c.loc, call.lowering);
}

/// Decision 859 — `x.m(…)` on a value of a type of another module, `m`
/// written without `pub` (`method_visibility.zig`); a primitive's member is
/// read from its table of `primitives.bp` (887 (2)).
fn checkOpaqueMethodCall(env: *Env, typed: TypedExpr, c: ast.CallExprOf(.untyped)) InferError!void {
    if (typed != .call or typed.call.kind != .call) return;
    const call = typed.call.kind.call;
    const recv = call.receiver orelse return;
    const name = nominalName(recv.getType()) orelse return;
    const lowering = c.kind == .call and c.kind.call.lowering;
    if (primitiveOfInterface(name)) |p| {
        if (lowering) return;
        return methodVisibility.refusePrimitiveMember(env, primitiveTable(env, p), p, call.callee, typed.call.loc);
    }
    return methodVisibility.refuseCall(env, name, call.callee, typed.call.loc, lowering);
}

/// The member table of `primitives.bp` the primitive `name` holds its own
/// members in (decision 641), as std registered it.
fn primitiveTable(env: *Env, name: []const u8) ?ast.BehaviorDecl {
    return env.stdBehaviorBase.get(name) orelse env.assocInterfaceDecls.get(name);
}

fn refuseContextHookWithoutUse(env: *Env, name: []const u8, loc: ast.Loc) InferError {
    const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is a hook of std's `context` module — it is `use`d (`use {s}(…)`), never called or passed as a value (decision 354)", .{ diagnostics.context_hook_without_use, name, name });
    env.lastError = TypeError.custom(msg, "Write `use provide(ctx);` in a component's body, or `val v = use context(themeContext);` in a `component fn` body.").withLoc(loc);
    return error.TypeError;
}

/// Decisions 378, 379 — a module-level `val` holding a `Context<T>` declares
/// `T`'s default, and only `createContext(value)` (or `comptime
/// createContext(…)`) declares one: one declaration per type in the program
/// (`Env.contextDefaults`, published as `Reflection.contextDefaults`), a
/// second refused naming the first. `val B = A;` would give one default two
/// declarations, and is refused.
fn noteContextDeclaration(env: *Env, v: ast.ValDecl, ty: *T.Type) InferError!void {
    if (!importsStdContextType(env)) return;
    const d = ty.deref();
    if (d.* != .named or !std.mem.eql(u8, d.named.name, "Context") or d.named.args.len != 1) return;
    var init = v.value.*;
    if (init == .comptime_ and init.comptime_.kind == .comptimeExpr) init = init.comptime_.kind.comptimeExpr.*;
    const declared = !v.mutable and init == .call and stdContextCallee(env, init.call) == .create_context;
    if (!declared) {
        env.lastError = TypeError.custom(
            diagnostics.context_not_declared ++ ": a module-level `Context<T>` declares `T`'s default, and only `createContext(value)` declares one — a `var`, or a `val` naming another context, would give one type two defaults (decisions 378, 379)",
            "Declare the type's default once at module level: `pub val themeContext = comptime createContext(Theme(…));`.",
        ).withLoc(v.value.getLoc());
        return error.TypeError;
    }
    const value_type = d.named.args[0];
    const key = try contextTypeKey(env, value_type) orelse return;
    const typeName = try errorMod.typeLabelAlloc(env.arena, value_type);
    const at = init.getLoc();
    const here: reflectionMod.ContextDefault = .{ .module = env.modulePath, .name = v.name, .line = at.line, .col = at.col, .typeName = typeName };
    const prior: ?reflectionMod.ContextDefault = env.contextDefaults.get(key) orelse if (env.reflection) |r| r.contextDefaults.get(key) else null;
    if (prior) |p| if (!std.mem.eql(u8, p.module, here.module) or !std.mem.eql(u8, p.name, here.name)) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` already has its context declared — `{s}` in {s} at {d}:{d}; a type declares one default in the program (decision 379 (1))", .{ diagnostics.context_declared_twice, typeName, p.name, if (p.module.len == 0) "main" else p.module, p.line, p.col });
        env.lastError = TypeError.custom(msg, "Keep one `createContext(…)` declaration per type; a second context over the same base type is a type of its own (`type Moeda(code: string)`).").withLoc(at);
        return error.TypeError;
    };
    try env.contextDefaults.put(env.arena, key, here);
    if (env.reflection) |r| try r.contextDefaults.put(r.arena, key, .{
        .module = try r.arena.dupe(u8, here.module),
        .name = try r.arena.dupe(u8, here.name),
        .line = here.line,
        .col = here.col,
        .typeName = try r.arena.dupe(u8, here.typeName),
    });
}

fn importsStdContextType(env: *Env) bool {
    if (env.stdContextNames.count() > 0) return true;
    return env.stdImports.count() > 0 and stdImportsContextModule(env);
}

fn stdImportsContextModule(env: *Env) bool {
    var it = env.stdImports.valueIterator();
    while (it.next()) |m| if (std.mem.eql(u8, m.*, "context")) return true;
    return false;
}

/// Decision 379 — a context's identity, the run-time key in a `RenderScope`:
/// its value's type, by its declared name — the name the checker and the
/// backends tell types apart by (decision 170), whichever module reads or
/// provides it and whatever it imports. Null for a type that names no
/// declaration (a type variable, a function).
fn contextTypeKey(env: *Env, t: *T.Type) InferError!?[]const u8 {
    _ = env;
    const d = t.deref();
    if (d.* != .named) return null;
    return d.named.name;
}

/// Decisions 378, 379 — a `use` of std's `provide` / `context`: `provide`
/// only in a component's body and before it renders a child, taking a
/// `Context<T>` value; `context(T)` naming a type. Both keyed by the type,
/// recorded for the lowering (`Env.contextUses`); a read's default is found
/// once the module's bodies are inferred (`resolveContextReads`).
fn noteContextUse(env: *Env, operand: ast.Expr, typed: TypedExpr, fc: envMod.FnContext, loc: ast.Loc) InferError!void {
    if (operand != .call) return;
    const which = stdContextCallee(env, operand.call) orelse return;
    if (which != .provide and which != .context and which != .inject) return;
    const call = operand.call.kind.call;
    if (which == .provide) {
        const statement = if (env.useStatementLoc) |at| std.meta.eql(at, loc) else false;
        if (!statement) {
            env.lastError = TypeError.custom(
                diagnostics.context_provide_outside_component ++ ": `use provide(…)` is a statement of a component's body of its own — it yields nothing to bind or pass",
                "Write it alone on its line: `use provide(createContext(value));`.",
            ).withLoc(loc);
            return error.TypeError;
        }
        if (!fc.renderable) {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `use provide(…)` in '{s}', which returns '{s}' — a provider gives its value to what a COMPONENT renders below it, and this body is no component (its `R` does not implement `@Renderable`)", .{ diagnostics.context_provide_outside_component, fc.fnName, fc.returnDisplay });
            env.lastError = TypeError.custom(msg, "Provide the context in the component that renders the children which read it (`component fn App() -> Component<Element> { use provide(…); … }`).").withLoc(loc);
            return error.TypeError;
        }
        if (env.firstRenderAt) |r| {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `use provide(…)` after this body renders a component on line {d} — that child would not see the value", .{ diagnostics.context_provide_after_render, r.line });
            env.lastError = TypeError.custom(msg, "Move every `use provide(…)` before the first component the body renders.").withLoc(loc);
            return error.TypeError;
        }
    }
    if (call.args.len == 0) return;
    const arg = call.args[0].value.*;
    // `provide` takes the context (`Context<T>`); `context` answers `T`.
    const value_type: *T.Type = if (which == .provide) blk: {
        const ctx_ty = typedCallArgType(typed, 0) orelse return;
        const d = ctx_ty.deref();
        if (d.* != .named or d.named.args.len != 1) return;
        break :blk d.named.args[0];
    } else if (which == .context) blk: {
        // `context(ctx)` answers `T`, the type of the `Context<T>` it names
        // (decision 723).
        const d = typed.getType().deref();
        break :blk if (d.* == .named and std.mem.eql(u8, d.named.name, "Component") and d.named.args.len == 1) d.named.args[0] else typed.getType();
    } else blk: {
        // `inject(R)` answers `R`, the type its argument names (416).
        const d = typed.getType().deref();
        const answered = if (d.* == .named and std.mem.eql(u8, d.named.name, "Component") and d.named.args.len == 1) d.named.args[0] else typed.getType();
        if (arg == .identifier and arg.identifier.kind == .ident) {
            const tn = arg.identifier.kind.ident;
            if (env.lookupTypeDef(tn) != null or env.importedTypeDecls.contains(tn) or isPrimitiveTypeName(tn)) {
                break :blk try env.namedType(tn);
            }
        }
        break :blk answered;
    };
    const key = try contextTypeKey(env, value_type) orelse {
        env.lastError = TypeError.custom(
            diagnostics.context_not_declared ++ ": a context is named by its value's type, and this one names none (decision 379)",
            "Read a context through a context value of a declared type: `use context(themeContext)`; provide one made by `createContext(Theme(…))`.",
        ).withLoc(arg.getLoc());
        return error.TypeError;
    };
    var fields: []envMod.InjectField = &.{};
    if (which == .inject) {
        // Decision 416 (1) — each field read as the context of its type; the
        // field's own default where the record declares one.
        const tn = value_type.deref().named.name;
        const defs = (env.lookupTypeDef(tn) orelse return).fields() orelse return;
        const params = env.ctorParams.get(tn) orelse &.{};
        fields = try env.arena.alloc(envMod.InjectField, defs.len);
        for (defs, 0..) |fd, i| {
            var field_default: ?*const ast.Expr = null;
            for (params) |p| if (std.mem.eql(u8, p.name, fd.name)) {
                if (p.default) |dv| {
                    const copy = try env.arena.create(ast.Expr);
                    copy.* = dv;
                    field_default = copy;
                }
            };
            fields[i] = .{
                .name = fd.name,
                .key = try contextTypeKey(env, fd.type_),
                .value_type = fd.type_,
                .type_name = try errorMod.typeLabelAlloc(env.arena, fd.type_),
                .field_default = field_default,
            };
        }
    }
    try env.contextUses.put(env.arena, loc, .{
        .kind = switch (which) {
            .provide => .provide,
            .inject => .inject,
            else => .read,
        },
        .key = key,
        .name = try errorMod.typeLabelAlloc(env.arena, value_type),
        .value_type = value_type,
        .fields = fields,
        // Decision 723 — a read's fallback is the default the handle it names
        // carries: the module-level value itself, a `Context<T>` being its
        // value at run time.
        .default_ref = if (which == .context) arg.identifier.kind.ident else null,
    });
}

/// The name `arg` gives a type a context can be keyed by — a declared type,
/// an imported one, a primitive or a behavior (416) — or null.
fn contextTypeName(env: *Env, arg: ast.Expr) ?[]const u8 {
    if (arg != .identifier or arg.identifier.kind != .ident) return null;
    const n = arg.identifier.kind.ident;
    if (env.localBindDepth(n) != null) return null;
    if (env.lookupTypeDef(n) != null or env.importedTypeDecls.contains(n) or isPrimitiveTypeName(n) or isBehaviorName(env, n)) return n;
    return null;
}

/// A `behavior` this module declares or imports.
fn isBehaviorName(env: *Env, name: []const u8) bool {
    for (env.moduleDecls) |d| if (d == .behavior and std.mem.eql(u8, d.behavior.name, name)) return true;
    return env.importedBehaviorDecls.contains(name);
}

/// std's `context(T)`, `inject(T)` and the two-argument `createContext(v,
/// Behavior)`, typed here: their type argument is a type, not a value.
/// `context(T)` answers `@Component<T>`; `inject(R)` (416) answers
/// `@Component<R>` for a record `R` (a behavior is refused); `createContext(v,
/// B)` answers `Context<B>`, `v` checked to implement `B` at the argument.
/// Null for any other call.
fn contextReadCall(env: *Env, c: ast.CallExprOf(.untyped)) InferError!?TypedExpr {
    const which = stdContextCallee(env, c) orelse return null;
    const call = c.kind.call;
    switch (which) {
        .context => {
            // Decisions 722, 723 — a context is read through a context value
            // the module declares or imports (`use context(themeContext)`),
            // typed by std's `context<T>(ctx: Context<T>)` as any call; a bare
            // type name is refused at the argument, and so is a value that is
            // no module-level name (a parameter, a local, an expression).
            if (call.args.len != 1) return null;
            const arg = call.args[0].value.*;
            if (contextTypeName(env, arg)) |tn| {
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `use context({s})` names a type — a context is read through a context value, `use context(<a context value>)`, matched to the provider by the context's type (decisions 722, 723)", .{ diagnostics.context_read_by_type, tn });
                env.lastError = TypeError.custom(msg, "Import or declare the context value and name it: `pub val themeContext = comptime createContext(Theme(…));`, then `val t = use context(themeContext);`.").withLoc(arg.getLoc());
                return error.TypeError;
            }
            if (arg == .identifier and arg.identifier.kind == .ident and env.localBindDepth(arg.identifier.kind.ident) == null) return null;
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `use context(…)` reads a context value the module declares or imports, and this argument names none (decisions 722, 723)", .{diagnostics.context_not_declared});
            env.lastError = TypeError.custom(msg, "Name a module-level context value: `import {theme.themeContext};`, then `val t = use context(themeContext);`.").withLoc(arg.getLoc());
            return error.TypeError;
        },
        .inject => {
            if (call.args.len != 1) return null;
            const arg = call.args[0].value.*;
            const tn = contextTypeName(env, arg) orelse {
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `inject(…)` builds a record, and this argument names no type (decisions 379 (3), 416)", .{diagnostics.context_not_declared});
                env.lastError = TypeError.custom(msg, "Name the record type: `use inject(Deps)`.").withLoc(arg.getLoc());
                return error.TypeError;
            };
            {
                const fields = if (env.lookupTypeDef(tn)) |td| td.fields() else null;
                if (isBehaviorName(env, tn) or fields == null) {
                    const msg = try std.fmt.allocPrint(env.arena, "{s}: `inject({s})` builds a record from the contexts of its fields' types, and `{s}` is no record type (decision 416 (1))", .{ diagnostics.inject_not_record, tn, tn });
                    env.lastError = TypeError.custom(msg, "Read a behavior's context through its context value, `use context(repoContext)`; `inject` takes a record whose fields are what it reads.").withLoc(arg.getLoc());
                    return error.TypeError;
                }
            }
            const named = try env.namedType(tn);
            return TypedExpr{ .call = .{ .loc = c.loc, .type_ = try env.namedTypeArgs("Component", &.{named}), .kind = .{ .call = .{
                .receiver = null,
                .callee = call.callee,
                .is_builtin = false,
                .args = &.{},
                .trailing = &.{},
            } } } };
        },
        .create_context => {
            if (call.args.len != 2) return null;
            const keyArg = call.args[1].value.*;
            const bn = contextTypeName(env, keyArg) orelse "";
            if (bn.len == 0 or !isBehaviorName(env, bn)) {
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `createContext(value, B)` names the behavior the context is provided as, and this argument names no behavior (decision 416 (2))", .{diagnostics.context_behavior_not_implemented});
                env.lastError = TypeError.custom(msg, "Name a behavior the value implements: `createContext(PgRepository(pool), MyRepository)`.").withLoc(keyArg.getLoc());
                return error.TypeError;
            }
            const value = try inferExprTyped(env, call.args[0].value.*);
            const vt = value.getType().deref();
            const implements = vt.* == .named and typeImplementsBehavior(env, vt.named.name, bn);
            if (!implements) {
                const shown = try errorMod.typeLabelAlloc(env.arena, value.getType());
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` does not implement `{s}` (decision 416 (2))", .{ diagnostics.context_behavior_not_implemented, shown, bn });
                env.lastError = TypeError.custom(msg, "A context keyed by a behavior holds a value of a type that implements it (`type PgRepository(…) implement MyRepository`).").withLoc(call.args[0].value.getLoc());
                return error.TypeError;
            }
            const args = try env.arena.alloc(ast.CallArgOf(.typed), 1);
            args[0] = .{ .label = null, .value = try makeTypedPtr(env, value) };
            return TypedExpr{ .call = .{ .loc = c.loc, .type_ = try env.namedTypeArgs("Context", &.{try env.namedType(bn)}), .kind = .{ .call = .{
                .receiver = null,
                .callee = call.callee,
                .is_builtin = false,
                .args = args,
                .trailing = &.{},
            } } } };
        },
        else => return null,
    }
}

/// The `val` declaring the default of the context keyed `key`: this
/// module's, or another analysed module's under a hidden import alias.
fn contextDefaultRef(env: *Env, key: []const u8) InferError!?[]const u8 {
    if (env.contextDefaults.get(key)) |d| return d.name;
    const r = env.reflection orelse return null;
    const d = r.contextDefaults.get(key) orelse return null;
    var it = env.contextDefaultImports.iterator();
    while (it.next()) |e| if (std.mem.eql(u8, e.value_ptr.module, d.module) and std.mem.eql(u8, e.value_ptr.name, d.name)) return e.key_ptr.*;
    const alias = try std.fmt.allocPrint(env.arena, "bpContextDefault__{d}", .{env.contextDefaultImports.count()});
    try env.contextDefaultImports.put(env.arena, alias, .{ .module = d.module, .name = d.name });
    return alias;
}

/// Decision 416 (1) — each `inject` field of this module gets its type's
/// declared default: this module's `val`, or another analysed module's
/// through a hidden import (the type's own module or one analysed before
/// this one); a field with none and no default of its own is refused at the
/// `inject`. A `use context(ctx)` needs nothing here: its fallback is the
/// value it names (decision 723, `noteContextUse`).
fn resolveContextReads(env: *Env) InferError!void {
    var it = env.contextUses.iterator();
    while (it.next()) |e| {
        const use = e.value_ptr;
        if (use.kind != .inject) continue;
        for (use.fields) |*f| {
            if (f.key) |k| if (try contextDefaultRef(env, k)) |ref| {
                f.default_ref = ref;
                continue;
            };
            if (f.field_default != null) continue;
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}.{s}`: `{s}` has no context declared — declare its default with `createContext(…)` (decision 416 (1))", .{ diagnostics.context_not_declared, use.name, f.name, f.type_name });
            env.lastError = TypeError.custom(msg, "A field `inject` reads is the context of its type provided above, else that type's declared default, else the field's own default.").withLoc(e.key_ptr.*);
            return error.TypeError;
        }
    }
}

/// The type of the `i`-th argument of a typed call, or null.
fn typedCallArgType(typed: TypedExpr, i: usize) ?*T.Type {
    if (typed != .call or typed.call.kind != .call) return null;
    const args = typed.call.kind.call.args;
    if (i >= args.len) return null;
    return args[i].value.getType();
}

// ── decision 277 — the hooks a function reaches (`hooks.zig`) ────────────────

/// The declaration a call names: a top-level function of this module, an
/// imported one, one reached through a namespace import, or std's `provide`
/// / `context`. Null for a function value (a parameter, a local) and a method.
fn hookCalleeDecl(env: *Env, c: ast.CallExprOf(.untyped)) InferError!?hooksMod.DeclRef {
    if (c.kind != .call) return null;
    const call = c.kind.call;
    if (call.is_builtin or call.calleeExpr != null) return null;
    if (stdContextCallee(env, c)) |which| return switch (which) {
        .provide, .context, .inject => .{ .module = "std/context", .name = call.callee },
        .context_type, .create_context, .render_scope => null,
    };
    if (call.receiver) |r| {
        if (r.* != .identifier or r.identifier.kind != .ident) return null;
        const handle = r.identifier.kind.ident;
        if (env.localBindDepth(handle) != null) return null;
        const path = env.namespaces.paths.get(handle) orelse return null;
        return try importedHookDecl(env, path, call.callee);
    }
    if (env.localBindDepth(call.callee) != null) return null;
    if (env.fnDecls.get(call.callee)) |f| if (env.ownDecls.contains(call.callee)) return .{
        .module = env.modulePath,
        .name = f.name,
        .returnTypeName = if (f.returnType) |rt| try declTypeName(env.arena, rt) else "",
    };
    if (env.importOwners.get(call.callee)) |o| return try importedHookDecl(env, o.owner, o.name);
    return null;
}

/// An imported function's reference, its return type as its module published it.
fn importedHookDecl(env: *Env, module: []const u8, name: []const u8) InferError!hooksMod.DeclRef {
    if (env.reflection) |r| if (r.hookFns.get(try envMod.declIdentity(env.arena, module, name))) |info| return info.ref;
    return .{ .module = module, .name = name };
}

/// The decorator an annotation of this module names, as its identity
/// (`declIdentity` of the decorator's declaring module and declared name): an
/// alias (`#[srv]` for `serverOnly`) and a namespace (`#[web.route]`) answer
/// the declaration. A builtin annotation (`#[@External.Node(…)]`) is `@<name>`.
fn annotationDecoratorId(env: *Env, a: ast.Annotation) InferError![]const u8 {
    if (a.is_builtin) return std.fmt.allocPrint(env.arena, "@{s}", .{a.name});
    if (env.importOwners.get(a.name)) |o| return envMod.declIdentity(env.arena, o.owner, o.name);
    if (std.mem.indexOfScalar(u8, a.name, '.')) |dot| if (env.namespaces.paths.get(a.name[0..dot])) |path|
        return envMod.declIdentity(env.arena, path, a.name[dot + 1 ..]);
    // A std decorator through its namespace handle (`#[mocks.mock]`) is
    // registered with its std module as owner.
    if (env.decorators.get(a.name)) |sig| if (sig.fn_decl) |d| {
        const owner = env.comptimeOwnerOf(d);
        if (owner.len > 0) return envMod.declIdentity(env.arena, owner, d.name);
    };
    return envMod.declIdentity(env.arena, env.modulePath, a.name);
}

/// A declaration's annotations with the decorators they name resolved here.
fn hookAnnotations(env: *Env, anns: []const ast.Annotation) InferError![]const hooksMod.Annotation {
    const out = try env.arena.alloc(hooksMod.Annotation, anns.len);
    for (anns, 0..) |a, i| out[i] = .{
        .name = a.name,
        .args = a.args,
        .decorator = try annotationDecoratorId(env, a),
    };
    return out;
}

/// The annotations of the function `ref` names: this module's from its
/// declaration, another module's as that module published them.
fn hookDeclAnnotations(env: *Env, ref: hooksMod.DeclRef) InferError![]const hooksMod.Annotation {
    if (std.mem.eql(u8, ref.module, env.modulePath)) {
        const f = env.fnDecls.get(ref.name) orelse return &.{};
        return hookAnnotations(env, f.annotations);
    }
    const r = env.reflection orelse return &.{};
    const info = r.hookFns.get(try envMod.declIdentity(env.arena, ref.module, ref.name)) orelse return &.{};
    return info.annotations;
}

/// One explicit type argument of a `use`, as `TypeInfo<unknown>` hands it
/// out: its declared name and module, and a record's fields as the checker
/// spells their types.
fn hookTypeArg(env: *Env, tr: ast.TypeRef) InferError!hooksMod.TypeArg {
    const spelled = try declTypeName(env.arena, tr);
    if (tr != .named) return .{ .name = spelled, .module = "", .fields = &.{} };
    const n = tr.named;
    // A type of this module, an imported one, or a primitive / std type
    // (module `""`).
    const name, const module = if (env.importedTypeDecls.get(n)) |it|
        .{ it.name, it.module }
    else if (env.ownDecls.contains(n))
        .{ n, if (env.modulePath.len == 0) "main" else env.modulePath }
    else
        .{ n, "" };
    var fields: std.ArrayListUnmanaged(hooksMod.TypeArg.Field) = .empty;
    if (env.lookupTypeDef(n)) |td| if (td.fields()) |fs| for (fs) |f| {
        try fields.append(env.arena, .{ .name = f.name, .typeName = try decoratorSpelling(env, f.type_, 0) });
    };
    return .{ .name = name, .module = module, .fields = fields.items };
}

/// Decision 277 — a `use` written in the body being recorded: the hook it
/// activates (null over a function value), the hook's annotations, the
/// `use`'s explicit type arguments, and for std's `provide` / `context` the
/// context object it names (decision 354 (4)).
fn noteHookUse(env: *Env, operand: ast.Expr, typed: TypedExpr, loc: ast.Loc) InferError!void {
    const isCall = operand == .call and operand.call.kind == .call;
    const target: ?hooksMod.DeclRef = if (isCall) try hookCalleeDecl(env, operand.call) else null;
    if (target) |t| try env.hookTargets.put(env.arena, loc, .{ .ref = t, .type_ = null });
    const b = env.hookBuilder orelse return;
    // Decision 375 — a `use` the checker cannot follow (`hook: null`), or of
    // a host hook (no node: a host's `@Component` extends `@Task`), makes
    // the node asynchronous. A `use` of a method's answer (791 (3): `use
    // m.render()`) is followed through the method's own mark (04s12-a), as
    // a call of it is.
    if (target == null) {
        if (isCall and operand.call.kind.call.receiver != null and try hostCallee(env, operand.call) == null) {
            try noteMethodCallTarget(env, operand.call, typed);
            try b.dynamicCalls.append(env.arena, .{ .type_ = typed.getType(), .at = operand.call.loc });
        } else b.is_async = true;
    }
    if (isCall) if (try hostCallee(env, operand.call) != null) {
        b.is_async = true;
    };
    if (!isCall) {
        return b.uses.append(env.arena, .{ .hook = null, .annotations = &.{}, .at = loc, .typeArgs = &.{} });
    }
    const c = operand.call;
    const call = c.kind.call;
    const hook = target;
    var typeArgs: std.ArrayListUnmanaged(hooksMod.TypeArg) = .empty;
    if (call.typeArgs) |tas| for (tas) |ta| try typeArgs.append(env.arena, try hookTypeArg(env, ta));
    // Decisions 354 (4), 379, 723 — `use context(ctx)` names the `val` it
    // reads (this module's or an imported one); `use provide(createContext(x))`
    // the declaration of `x`'s type's default.
    var context: ?hooksMod.DeclRef = null;
    if (stdContextCallee(env, c)) |which| if (call.args.len > 0) {
        const arg = call.args[0].value.*;
        if (arg == .identifier and arg.identifier.kind == .ident) {
            const name = arg.identifier.kind.ident;
            // Decision 723 — `use context(ctx)` names the context value it
            // reads: this module's `val`, or the one it imports.
            if (which == .context and env.localBindDepth(name) == null) {
                if (env.importOwners.get(name)) |o|
                    context = .{ .module = o.owner, .name = o.name }
                else if (env.ownDecls.contains(name))
                    context = .{ .module = env.modulePath, .name = name };
            }
        }
        // `use provide(createContext(x))`: the declaration of `x`'s type's
        // default (the context's identity is its type, 379).
        if (context == null and which == .provide) if (env.contextUses.get(loc)) |cu| {
            const found = env.contextDefaults.get(cu.key) orelse if (env.reflection) |r| r.contextDefaults.get(cu.key) else null;
            if (found) |d| context = .{ .module = d.module, .name = d.name };
        };
    };
    try b.uses.append(env.arena, .{
        .hook = hook,
        .annotations = if (hook) |h| try hookDeclAnnotations(env, h) else &.{},
        .at = loc,
        .typeArgs = typeArgs.items,
        .context = context,
    });
}

/// Decision 277 — a call of a `@Component` function written in the body being
/// recorded (its type read when the body is done). The operand of a `use` is
/// the `use`'s, and a call of a function value names no declaration.
fn noteHookCall(env: *Env, c: ast.CallExprOf(.untyped), ty: *T.Type) InferError!void {
    if (env.inUseOperand) if (env.useOperandLoc) |at| if (std.meta.eql(at, c.loc)) return;
    const callee = try hookCalleeDecl(env, c) orelse return;
    // Decision 389 — a declared function whose own return is no `@Component`
    // (`fn first<T>(xs: T[]) -> T`) answers one only through its type
    // arguments: what generic code answers is a component value the checker
    // does not follow — an edge with `callee: null`, and no synchronous mark.
    if (c.kind == .call and c.kind.call.receiver == null) if (env.lookup(c.kind.call.callee)) |declared| {
        const d = declared.deref();
        if (d.* == .func) {
            const r = d.func.ret.deref();
            const component = r.* == .named and std.mem.eql(u8, r.named.name, "Component");
            if (!component) {
                const b = env.hookBuilder orelse return;
                try b.dynamicCalls.append(env.arena, .{ .type_ = ty, .at = c.loc });
                return;
            }
        }
    };
    try env.hookTargets.put(env.arena, c.loc, .{ .ref = callee, .type_ = ty });
    const b = env.hookBuilder orelse return;
    try b.calls.append(env.arena, .{ .call = .{ .callee = callee, .at = c.loc }, .type_ = ty });
}

/// Decision 389 — a `@Component` function named as a value in the body being
/// recorded (`itens.map(Card)`, `val c = Card;`, a record field, any call's
/// argument): under 388 a component value is rendered wherever its lambda
/// lands, so naming it reaches it — an edge as a call is. A local of that name
/// is a value the checker does not follow here (a parameter is called, and
/// that call is the edge).
fn noteComponentValue(env: *Env, name: []const u8, ty: *T.Type, loc: ast.Loc) InferError!void {
    const b = env.hookBuilder orelse return;
    if (env.localBindDepth(name) != null) return;
    const d = ty.deref();
    if (d.* != .func) return;
    const ret = d.func.ret.deref();
    if (ret.* != .named or !std.mem.eql(u8, ret.named.name, "Component")) return;
    const callee: hooksMod.DeclRef = blk: {
        if (env.fnDecls.get(name)) |f| if (env.ownDecls.contains(name)) {
            if (isHookHost(f)) return;
            break :blk .{
                .module = env.modulePath,
                .name = f.name,
                .returnTypeName = if (f.returnType) |rt| try declTypeName(env.arena, rt) else "",
            };
        };
        if (env.importOwners.get(name)) |o| {
            const ref = try importedHookDecl(env, o.owner, o.name);
            if (env.reflection) |r| if (r.hookFns.get(try envMod.declIdentity(env.arena, o.owner, o.name))) |info| if (info.host) return;
            break :blk ref;
        }
        return;
    };
    try b.calls.append(env.arena, .{ .call = .{ .callee = callee, .at = loc }, .type_ = ret });
}

/// Decision 375 — what a call written in the body being recorded says of the
/// node's asynchrony by itself: a host function answering `@Async` (or
/// `@Component`, which extends it) makes it asynchronous; a call of a
/// function value or a method is kept by type, to be read when the body is
/// done (`finishHookNode`). A call of a declaration is followed through its
/// node (`markHookAsync`); the operand of a `use` is the `use`'s.
fn noteAsyncCall(env: *Env, c: ast.CallExprOf(.untyped), typed: TypedExpr) InferError!void {
    const b = env.hookBuilder orelse return;
    if (c.kind != .call or c.kind.call.is_builtin) return;
    if (env.inUseOperand) if (env.useOperandLoc) |at| if (std.meta.eql(at, c.loc)) return;
    if (stdContextCallee(env, c) != null) return;
    if (try hostCallee(env, c) != null) {
        if (unwrapTaskType(typed.getType()) != null) b.is_async = true;
        return;
    }
    if (try hookCalleeDecl(env, c) != null) return;
    try noteMethodCallTarget(env, c, typed);
    try b.dynamicCalls.append(env.arena, .{ .type_ = typed.getType(), .at = c.loc });
}

/// 04s12-a — a call of a method of a declared type (`menu.render()`): the
/// method it reaches, `<Type>.<method>`, by the call's location.
fn noteMethodCallTarget(env: *Env, c: ast.CallExprOf(.untyped), typed: TypedExpr) InferError!void {
    if (c.kind.call.receiver == null) return;
    if (typed != .call or typed.call.kind != .call) return;
    const recv = typed.call.kind.call.receiver orelse return;
    const d = recv.getType().deref();
    if (d.* != .named) return;
    const callee = c.kind.call.callee;
    if (env.hasInherentMethod(d.named.name, callee)) {
        try env.methodCallTargets.put(env.arena, c.loc, try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ d.named.name, callee }));
        return;
    }
    // A behavior's `default fn` the type adopts: its body is the behavior's
    // (`inferBehaviorDefaultBodies`, keyed `<Behavior>.<method>`).
    const td = env.lookupTypeDef(d.named.name) orelse return;
    const implements = switch (td) {
        .record => |r| r.implements,
        .struct_ => |st| st.implements,
        .enum_ => |e| e.implements,
    };
    for (implements) |b| {
        const key = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ b, callee });
        if (env.methodHooks.contains(key)) return env.methodCallTargets.put(env.arena, c.loc, key);
    }
}

/// The top-level function of this module `f` is (methods and lambdas are not).
fn isModuleFn(env: *Env, f: ast.FnDecl) bool {
    if (f.body.len == 0) return false;
    const d = env.fnDecls.get(f.name) orelse return false;
    return d.body.ptr == f.body.ptr and env.ownDecls.contains(f.name);
}

/// The node of `f` once its body is inferred: its `use`s, and its calls whose
/// type resolved to `@Component<R>`.
fn finishHookNode(env: *Env, f: ast.FnDecl, b: *hooksMod.Builder) InferError!void {
    var calls: std.ArrayListUnmanaged(hooksMod.Call) = .empty;
    for (b.calls.items) |pc| {
        const d = pc.type_.deref();
        if (d.* == .named and std.mem.eql(u8, d.named.name, "Component")) try calls.append(env.arena, pc.call);
    }
    // Decision 375 — a call of a function value or a method answering
    // `@Component<R>`, or one whose type is still open, cannot be followed:
    // the node is asynchronous, and (389) the call is an edge with `callee:
    // null`, its reader deciding on the safe side.
    var isAsync = b.is_async;
    // Decision 388 — a function typed by an alias of `@Component` (`->
    // StyledView`) is no component body (118: the alias activates nothing):
    // it answers a lambda another body made, which may run asynchronously,
    // so a run of what it answers is awaited.
    const writtenComponent = if (f.returnType) |rt| rt == .generic and rt.generic.is_builtin and std.mem.eql(u8, rt.generic.name, "Component") else false;
    if (!writtenComponent) if (env.lookup(f.name)) |declared| {
        const d = declared.deref();
        if (d.* == .func) {
            const r = d.func.ret.deref();
            if (r.* == .named and std.mem.eql(u8, r.named.name, "Component")) isAsync = true;
        }
    };
    for (b.dynamicCalls.items) |dc| {
        const follows = switch (dc.type_.deref().*) {
            .named => |n| std.mem.eql(u8, n.name, "Component"),
            .typeVar => true,
            else => false,
        };
        if (!follows) continue;
        // 04s12-a — a `@Component` method of this module is followed through
        // its own mark (`markHookAsync`), as a call of a function is.
        if (env.methodCallTargets.get(dc.at)) |key| if (env.methodHooks.contains(key)) {
            try env.methodEdges.append(env.arena, .{ .from = f.name, .method = key });
            try calls.append(env.arena, .{ .callee = null, .at = dc.at });
            continue;
        };
        isAsync = true;
        try calls.append(env.arena, .{ .callee = null, .at = dc.at });
    }
    std.mem.sort(hooksMod.Call, calls.items, {}, struct {
        fn lt(_: void, a: hooksMod.Call, z: hooksMod.Call) bool {
            return hooksMod.before(a.at, z.at);
        }
    }.lt);
    var moduleVars: std.ArrayListUnmanaged([]const u8) = .empty;
    for (env.moduleDecls) |d| if (d == .val and d.val.mutable) try moduleVars.append(env.arena, d.val.name);
    const written = hooksMod.foldBlocker(f.body, moduleVars.items);
    const blocker = if (b.blocker) |m| (if (written) |w| (if (hooksMod.before(w.at, m.at)) w else m) else m) else written;
    try env.stageFacts.put(env.arena, f.name, .{
        .build = b.build,
        .run = b.run,
        .blocker = blocker,
        .calls = b.stageCalls.items,
        .buildBody = if (isDecoratorParams(f.params)) "decorator" else if (f.returnType) |rt| (if (rt.isTemplateReturnType()) "template" else null) else null,
    });
    try env.hookNodes.put(env.arena, f.name, .{
        .function = .{
            .module = env.modulePath,
            .name = f.name,
            .returnTypeName = if (f.returnType) |rt| try declTypeName(env.arena, rt) else "",
        },
        .uses = b.uses.items,
        .calls = calls.items,
        .is_async = isAsync,
    });
}

/// Decision 375 — whether the declaration `ref` names is asynchronous: std's
/// `provide` / `context` are not; this module's function by its node; another
/// module's as that module published it; a host function, or a declaration
/// with no node, is (the conservative answer).
fn hookTargetAsync(env: *Env, ref: hooksMod.DeclRef) InferError!bool {
    if (std.mem.eql(u8, ref.module, "std/context")) return false;
    if (std.mem.eql(u8, ref.module, env.modulePath)) {
        const f = env.fnDecls.get(ref.name) orelse return true;
        if (isHookHost(f)) return true;
        const n = env.hookNodes.get(ref.name) orelse return true;
        return n.is_async;
    }
    const r = env.reflection orelse return true;
    const info = r.hookFns.get(try envMod.declIdentity(env.arena, ref.module, ref.name)) orelse return true;
    if (info.host) return true;
    const n = info.node orelse return true;
    return n.is_async;
}

// ── decision 376 — every function's stage ───────────────────────────────────

/// A host function's stage: `any` when std (or its library) declares it so
/// with `#[compiler.stage(.Any)]` (decision 663) — a pure primitive —, else `run`
/// (376 (4)).
fn hostStage(f: ast.FnDecl) hooksMod.Stage {
    for (f.annotations) |a| if (a.stageOf()) |s| if (std.mem.eql(u8, s.case, "Any")) return .any;
    return .run;
}

/// The std function a call names — through a namespace (`clock.nowMillis()`
/// after `import {io.clock} from "std"`) or a leaf import (`nowMillis()`).
fn stdCallee(env: *Env, c: ast.CallExprOf(.untyped)) ?envMod.StdLeafFn {
    const call = c.kind.call;
    if (call.calleeExpr != null) return null;
    if (call.receiver) |r| {
        if (r.* != .identifier or r.identifier.kind != .ident) return null;
        const handle = r.identifier.kind.ident;
        if (env.localBindDepth(handle) != null) return null;
        const module = env.stdImports.get(handle) orelse return null;
        return .{ .module = module, .name = call.callee };
    }
    if (env.localBindDepth(call.callee) != null) return null;
    if (env.ownDecls.contains(call.callee) or env.importOwners.contains(call.callee)) return null;
    return env.stdLeafFns.get(call.callee);
}

/// A std function's stage: as its module published it once analysed
/// (`Reflection.hookFns`), else from its declaration (`stdFnStage`).
fn stdStage(env: *Env, module: []const u8, name: []const u8) InferError!hooksMod.Stage {
    if (env.reflection) |r| {
        const path = try std.fmt.allocPrint(env.arena, "std/{s}", .{module});
        if (r.hookFns.get(try envMod.declIdentity(env.arena, path, name))) |info| return info.stage;
    }
    return stdFnStage(env, module, name, 0);
}

/// A std function's stage: a host declaration's by `hostStage`, a body's the
/// stages of the functions of its module it reaches (std's bodies call their
/// own module's functions by name).
fn stdFnStage(env: *Env, module: []const u8, name: []const u8, depth: usize) hooksMod.Stage {
    if (depth > 24) return .any;
    const fns = env.stdModuleFns.get(module) orelse return .any;
    const f = for (fns) |g| {
        if (std.mem.eql(u8, g.name, name)) break g;
    } else return .any;
    if (isHookHost(f)) return hostStage(f);
    var names: std.ArrayListUnmanaged([]const u8) = .empty;
    ast.collectNames(env.arena, f.body, &names) catch return .any;
    for (names.items) |n| {
        if (std.mem.eql(u8, n, name)) continue;
        for (fns) |g| if (std.mem.eql(u8, g.name, n)) {
            if (stdFnStage(env, module, n, depth + 1) == .run) return .run;
            break;
        };
    }
    return .any;
}

/// The call as a refusal names it: `` `callee(…)` `` / `` `recv.callee(…)` ``.
fn stageCallText(env: *Env, c: ast.CallExprOf(.untyped)) InferError![]const u8 {
    const call = c.kind.call;
    if (call.receiver) |r| if (r.* == .identifier and r.identifier.kind == .ident)
        return std.fmt.allocPrint(env.arena, "`{s}.{s}(…)`", .{ r.identifier.kind.ident, call.callee });
    return std.fmt.allocPrint(env.arena, "`{s}(…)`", .{call.callee});
}

/// Decision 376 — what a call written in the body being recorded says of
/// its stage: a host function `run` unless declared `#[compiler.stage(.Any)]`, a std
/// function by its declaration, a declaration of the program by its node
/// (read once every body is inferred, `markStages`); std's `provide` /
/// `context` are `any` (388: a scope push and a lookup); a method or a
/// function value is not followed.
fn noteStageCall(env: *Env, c: ast.CallExprOf(.untyped), typed: TypedExpr) InferError!void {
    if (c.kind != .call or c.kind.call.is_builtin) return;
    // A `comptime` is computed at build into a constant: it gives the
    // function no stage (376 (2)).
    if (env.comptimeDepth > 0) return;
    if (stdContextCallee(env, c) != null) return;
    // A template call is expanded where it is written: the code it builds is
    // inferred here and gives the stage, never the template's body (which
    // runs at build to build it). A namespace's template is `<ns>.<name>`.
    if (c.kind.call.receiver == null and env.templateFns.contains(c.kind.call.callee)) return;
    if (c.kind.call.receiver) |r| if (r.* == .identifier and r.identifier.kind == .ident) {
        if (env.templateFns.contains(try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ r.identifier.kind.ident, c.kind.call.callee }))) return;
    };
    var run: ?hooksMod.Mark = null;
    var ref: ?hooksMod.DeclRef = null;
    if (try hostCallee(env, c)) |h| {
        if (try declaredStage(env, h) != .run) return;
        run = .{ .at = c.loc, .what = try std.fmt.allocPrint(env.arena, "{s}, a host function that runs only when the program runs", .{try stageCallText(env, c)}) };
    } else if (try hookCalleeDecl(env, c)) |d| {
        ref = d;
    } else if (stdCallee(env, c)) |sf| {
        if (try stdStage(env, sf.module, sf.name) != .run) {
            // Decision 380 — an `any` std function computed at build when
            // nothing in it is kept from it.
            if (!try stdFoldable(env, sf.module, sf.name)) try noteFoldBlocker(env, c.loc, "a std function that is not computed at build");
            return;
        }
        run = .{ .at = c.loc, .what = try std.fmt.allocPrint(env.arena, "{s}, a std function that runs only when the program runs", .{try stageCallText(env, c)}) };
    } else {
        // Decision 380 — a call the stage does not follow: a function value,
        // or a method of a declared type (a primitive's, an array's or a
        // collection's is computed as written).
        if (!callOnPureReceiver(c, typed) and !isConstructorCall(env, c)) try noteFoldBlocker(env, c.loc, "a call that is not followed");
        return;
    }
    const what = try stageCallText(env, c);
    const b = env.hookBuilder orelse return;
    if (run) |m| {
        if (b.run == null or hooksMod.before(m.at, b.run.?.at)) b.run = m;
        return;
    }
    if (ref) |d| try b.stageCalls.append(env.arena, .{ .ref = d, .at = c.loc, .what = what });
}

fn noteFoldBlocker(env: *Env, at: ast.Loc, what: []const u8) InferError!void {
    const b = env.hookBuilder orelse return;
    if (b.blocker == null or hooksMod.before(at, b.blocker.?.at)) b.blocker = .{ .at = at, .what = what };
}

/// A record's or a variant's constructor (`Rule(text: …)`, `Shape.Rect(…)`,
/// `.Rect(…)`): data, computed as written.
fn isConstructorCall(env: *Env, c: ast.CallExprOf(.untyped)) bool {
    const call = c.kind.call;
    if (call.calleeExpr != null) return false;
    if (call.callee.len == 0 or !std.ascii.isUpper(call.callee[0])) return false;
    if (call.receiver) |r| {
        if (r.* != .identifier or r.identifier.kind != .ident) return false;
        return env.lookupTypeDef(r.identifier.kind.ident) != null;
    }
    if (env.localBindDepth(call.callee) != null) return false;
    return env.lookupTypeDef(call.callee) != null;
}

/// A method call whose receiver is a primitive, an array or a std
/// collection: computed as written wherever it runs.
fn callOnPureReceiver(c: ast.CallExprOf(.untyped), typed: TypedExpr) bool {
    if (c.kind.call.receiver == null) return false;
    if (typed != .call or typed.call.kind != .call) return false;
    const recv = typed.call.kind.call.receiver orelse return false;
    const d = recv.getType().deref();
    if (d.* != .named) return false;
    const pure = [_][]const u8{ "i8", "i16", "i32", "i64", "u8", "u16", "u32", "u64", "f32", "f64", "bool", "string", "array", "Dict", "Set", "bigint", "decimal" };
    for (pure) |n| if (std.mem.eql(u8, n, d.named.name)) return true;
    return false;
}

/// Decision 380 — whether a std function is computed at build: a host one
/// when it is `any`, a body as its module published it.
fn stdFoldable(env: *Env, module: []const u8, name: []const u8) InferError!bool {
    if (env.stdModuleFns.get(module)) |fns| for (fns) |f| if (std.mem.eql(u8, f.name, name)) {
        if (isHookHost(f)) return hostStage(f) == .any and servedAtBuild(f);
        break;
    };
    const r = env.reflection orelse return true;
    const path = try std.fmt.allocPrint(env.arena, "std/{s}", .{module});
    const info = r.hookFns.get(try envMod.declIdentity(env.arena, path, name)) orelse return true;
    if (info.host) return info.stage == .any;
    const n = info.node orelse return false;
    return n.foldable;
}

/// The stage a host declaration `ref` names declares (own module or
/// published).
fn declaredStage(env: *Env, ref: hooksMod.DeclRef) InferError!hooksMod.Stage {
    if (std.mem.eql(u8, ref.module, env.modulePath)) {
        const f = env.fnDecls.get(ref.name) orelse return .run;
        return hostStage(f);
    }
    const r = env.reflection orelse return .run;
    const info = r.hookFns.get(try envMod.declIdentity(env.arena, ref.module, ref.name)) orelse return .run;
    return info.stage;
}

const StageAnswer = struct { stage: hooksMod.Stage, why: []const u8 };

/// Decision 380 (`block_eval.knownAtBuild`, through `Env.foldableCall`) —
/// whether the call `c` is of a function computed at build: a host or std
/// function that is `any`, or a declaration of the program whose node is
/// `foldable` (this module's computed now). Builtins, methods and function
/// values are not.
pub fn callFoldable(env: *Env, c: ast.CallExprOf(.untyped)) bool {
    return callFoldableOrErr(env, c) catch false;
}

fn callFoldableOrErr(env: *Env, c: ast.CallExprOf(.untyped)) InferError!bool {
    if (c.kind != .call) return false;
    const call = c.kind.call;
    if (call.is_builtin or call.trailing.len > 0 or call.calleeExpr != null) return false;
    if (stdContextCallee(env, c) != null) return false;
    if (try hostCallee(env, c)) |h| {
        if (try declaredStage(env, h) != .any) return false;
        if (std.mem.eql(u8, h.module, env.modulePath)) if (env.fnDecls.get(h.name)) |f| return servedAtBuild(f);
        return true;
    }
    if (try hookCalleeDecl(env, c)) |d| return foldableNow(env, d);
    if (stdCallee(env, c)) |sf| return try stdStage(env, sf.module, sf.name) == .any and try stdFoldable(env, sf.module, sf.name);
    return false;
}

/// Decisions 434 (4), 452 — a host function the comptime runtime answers:
/// one whose `.Wasm` implementation is a `std:` cell or a `body:` (an `op:`
/// instruction is the wasm target's alone).
fn servedAtBuild(f: ast.FnDecl) bool {
    for (f.implementations) |i| {
        if (i.target != .wasm) continue;
        const c = i.cell orelse continue;
        if (c.kind == .std_ or c.kind == .body) return true;
    }
    return false;
}

/// Decision 380 — whether the declaration `ref` names is computed at build
/// (its node's `foldable`, once its stage is computed; a host when `any`).
fn foldableRef(env: *Env, ref: hooksMod.DeclRef) InferError!bool {
    if (std.mem.eql(u8, ref.module, "std/context")) return false;
    if (std.mem.eql(u8, ref.module, env.modulePath)) {
        const f = env.fnDecls.get(ref.name) orelse return false;
        if (isHookHost(f)) return hostStage(f) == .any and servedAtBuild(f);
        if (!env.stagesDone.contains(ref.name)) return false;
        const n = env.hookNodes.get(ref.name) orelse return false;
        return n.foldable;
    }
    const r = env.reflection orelse return false;
    const info = r.hookFns.get(try envMod.declIdentity(env.arena, ref.module, ref.name)) orelse return false;
    if (info.host) return info.stage == .any;
    const n = info.node orelse return false;
    return n.foldable;
}

/// Decision 380 — the stage of this module's function `name` now, while the
/// module is being inferred: computed when its body and every body of this
/// module it reaches are inferred (`Env.stageFacts`), else null — a call of
/// a function declared later is not computed at build (14s8-d's order).
pub fn foldableNow(env: *Env, ref: hooksMod.DeclRef) InferError!bool {
    if (std.mem.eql(u8, ref.module, env.modulePath)) {
        if (env.fnDecls.get(ref.name)) |f| if (isHookHost(f)) return hostStage(f) == .any and servedAtBuild(f);
        var seen: std.StringHashMapUnmanaged(void) = .empty;
        if (!try factsComplete(env, ref.name, &seen)) return false;
        var visiting: std.StringHashMapUnmanaged(void) = .empty;
        _ = try stageOfOwn(env, ref.name, &visiting);
    }
    return foldableRef(env, ref);
}

fn factsComplete(env: *Env, name: []const u8, seen: *std.StringHashMapUnmanaged(void)) InferError!bool {
    if (seen.contains(name)) return true;
    try seen.put(env.arena, name, {});
    const facts = env.stageFacts.get(name) orelse return false;
    for (facts.calls) |sc| if (std.mem.eql(u8, sc.ref.module, env.modulePath)) {
        if (env.fnDecls.get(sc.ref.name)) |f| if (isHookHost(f)) continue;
        if (!try factsComplete(env, sc.ref.name, seen)) return false;
    };
    return true;
}

/// The stage of the declaration `ref` names: std's `provide` / `context`
/// `any`; this module's function by its body (`stageOfOwn`); another
/// module's as it published it.
fn stageOfRef(env: *Env, ref: hooksMod.DeclRef, visiting: *std.StringHashMapUnmanaged(void)) InferError!StageAnswer {
    if (std.mem.eql(u8, ref.module, "std/context")) return .{ .stage = .any, .why = "" };
    if (std.mem.eql(u8, ref.module, env.modulePath)) {
        const f = env.fnDecls.get(ref.name) orelse return .{ .stage = .any, .why = "" };
        if (isHookHost(f)) {
            const st = hostStage(f);
            return .{ .stage = st, .why = if (st == .run) try std.fmt.allocPrint(env.arena, "it is the host function `{s}`", .{f.name}) else "" };
        }
        return stageOfOwn(env, ref.name, visiting);
    }
    const r = env.reflection orelse return .{ .stage = .any, .why = "" };
    const info = r.hookFns.get(try envMod.declIdentity(env.arena, ref.module, ref.name)) orelse return .{ .stage = .any, .why = "" };
    return .{ .stage = info.stage, .why = info.why };
}

/// A resource as a function's stage is named by: what it is and where, the
/// module included (`main:9:12`).
fn markText(env: *Env, m: hooksMod.Mark) InferError![]const u8 {
    return std.fmt.allocPrint(env.arena, "{s} at {s}", .{ m.what, try hooksMod.atText(env.arena, env.modulePath, m.at) });
}

/// Decision 376 (2) — the stage of this module's function `name`: its own
/// resources joined with its calls' stages (`any + x = x`); `build` and `run`
/// together are `build-and-run` at the second, naming the first. A cycle
/// adds nothing to itself.
fn stageOfOwn(env: *Env, name: []const u8, visiting: *std.StringHashMapUnmanaged(void)) InferError!StageAnswer {
    const node = env.hookNodes.getPtr(name) orelse return .{ .stage = .any, .why = "" };
    const facts = env.stageFacts.get(name) orelse return .{ .stage = node.stage, .why = node.why };
    if (env.stagesDone.contains(name)) return .{ .stage = node.stage, .why = node.why };
    if (visiting.contains(name)) return .{ .stage = .any, .why = "" };
    try visiting.put(env.arena, name, {});
    defer _ = visiting.remove(name);
    var build = facts.build;
    var run = facts.run;
    for (facts.calls) |sc| {
        const st = try stageOfRef(env, sc.ref, visiting);
        switch (st.stage) {
            .any => {},
            .build => if (build == null or hooksMod.before(sc.at, build.?.at)) {
                build = .{ .at = sc.at, .what = try std.fmt.allocPrint(env.arena, "{s}, which runs only at build ({s})", .{ sc.what, st.why }), .root = st.why };
            },
            .run => if (run == null or hooksMod.before(sc.at, run.?.at)) {
                run = .{ .at = sc.at, .what = try std.fmt.allocPrint(env.arena, "{s}, which runs only when the program runs ({s})", .{ sc.what, st.why }), .root = st.why };
            },
        }
    }
    // A decorator's or a template's body runs at build whatever it calls:
    // `Build`, and no `build-and-run` (what it may reach is 376 (5)'s,
    // question `b17-a`).
    if (facts.buildBody != null) {
        node.stage = .build;
        node.why = try std.fmt.allocPrint(env.arena, "the {s} `{s}` runs at build", .{ facts.buildBody.?, name });
        try env.stagesDone.put(env.arena, name, {});
        return .{ .stage = node.stage, .why = node.why };
    }
    if (build) |bm| if (run) |rm| {
        const first, const second = if (hooksMod.before(bm.at, rm.at)) .{ bm, rm } else .{ rm, bm };
        return failAt(
            env,
            second.at,
            try std.fmt.allocPrint(env.arena, "{s}: `{s}` would run at build and when the program runs — {s} here, and {s} at {d}:{d}", .{ diagnostics.build_and_run, name, second.what, first.what, first.at.line, first.at.col }),
            "A function has one stage (decision 376 (2)): compute the build half under `comptime` (`val names = comptime fields(Post);`) or move it to a function of its own.",
        );
    };
    // Decision 380 — computed at build when `any`, nothing in it kept from
    // the build and every callee so.
    node.foldable = run == null and build == null and facts.blocker == null and for (facts.calls) |sc| {
        if (!try foldableRef(env, sc.ref)) break false;
    } else true;
    if (run) |m| {
        node.stage = .run;
        node.why = m.root orelse try markText(env, m);
    } else if (build) |m| {
        node.stage = .build;
        node.why = m.root orelse try markText(env, m);
    } else {
        node.stage = .any;
        node.why = "";
    }
    try env.stagesDone.put(env.arena, name, {});
    return .{ .stage = node.stage, .why = node.why };
}

/// Decision 376 — every top-level function's stage, in declaration order
/// (a refusal names the first function that mixes the two).
fn markStages(env: *Env, program: ast.Program) InferError!void {
    var visiting: std.StringHashMapUnmanaged(void) = .empty;
    for (program.decls) |d| {
        if (d != .@"fn") continue;
        _ = try stageOfOwn(env, d.@"fn".name, &visiting);
    }
}

/// Decision 375 — mark this module's nodes once its bodies are inferred: a
/// node reaching an asynchronous one through a `use` or a call is
/// asynchronous, so a cycle is asynchronous when any node in it is (the
/// marks only grow, until none changes). Then record what commonJS reads:
/// the synchronous functions and the calls and `use`s of one.
fn markHookAsync(env: *Env) InferError!void {
    var changed = true;
    while (changed) {
        changed = false;
        var it = env.hookNodes.iterator();
        while (it.next()) |e| {
            const n = e.value_ptr;
            if (n.is_async) continue;
            const reaches = blk: {
                for (n.uses) |u| if (u.hook) |h| if (try hookTargetAsync(env, h)) break :blk true;
                for (n.calls) |c| {
                    const callee = c.callee orelse {
                        // A `@Component` method of this module: its own mark, below.
                        if (env.methodCallTargets.get(c.at)) |key| if (env.methodHooks.contains(key)) continue;
                        break :blk true;
                    };
                    if (try hookTargetAsync(env, callee)) break :blk true;
                }
                break :blk false;
            };
            if (reaches) {
                n.is_async = true;
                changed = true;
            }
        }
    }
    // 04s12-a — each `@Component` method marked as a node is (its body,
    // the hooks it `use`s and the components it calls); then a function
    // reaching an asynchronous method is asynchronous, and the nodes are
    // marked again.
    var asyncMethods: std.StringHashMapUnmanaged(void) = .empty;
    var mit = env.methodHooks.iterator();
    while (mit.next()) |e| {
        const mh = e.value_ptr.*;
        const isAsync = mh.is_async or blk: {
            for (mh.uses) |u| {
                const h = u.hook orelse break :blk true;
                if (try hookTargetAsync(env, h)) break :blk true;
            }
            for (mh.calls) |pc| {
                const d = pc.type_.deref();
                if (d.* != .named or !std.mem.eql(u8, d.named.name, "Component")) continue;
                const callee = pc.call.callee orelse break :blk true;
                if (try hookTargetAsync(env, callee)) break :blk true;
            }
            for (mh.dynamicCalls) |dc| switch (dc.type_.deref().*) {
                .named => |n| if (std.mem.eql(u8, n.name, "Component")) break :blk true,
                .typeVar => break :blk true,
                else => {},
            };
            break :blk false;
        };
        if (isAsync) try asyncMethods.put(env.arena, e.key_ptr.*, {});
    }
    var reMark = false;
    for (env.methodEdges.items) |edge| if (asyncMethods.contains(edge.method)) {
        if (env.hookNodes.getPtr(edge.from)) |n| if (!n.is_async) {
            n.is_async = true;
            reMark = true;
        };
    };
    if (reMark) {
        changed = true;
        while (changed) {
            changed = false;
            var it = env.hookNodes.iterator();
            while (it.next()) |e| {
                const n = e.value_ptr;
                if (n.is_async) continue;
                const reaches = blk: {
                    for (n.uses) |u| if (u.hook) |h| if (try hookTargetAsync(env, h)) break :blk true;
                    for (n.calls) |cl| {
                        const callee = cl.callee orelse continue;
                        if (try hookTargetAsync(env, callee)) break :blk true;
                    }
                    break :blk false;
                };
                if (reaches) {
                    n.is_async = true;
                    changed = true;
                }
            }
        }
    }
    env.syncFns.clearRetainingCapacity();
    var nit = env.hookNodes.iterator();
    while (nit.next()) |e| if (!e.value_ptr.is_async) try env.syncFns.put(env.arena, e.key_ptr.*, {});
    var mkit = env.methodHooks.iterator();
    while (mkit.next()) |e| if (!asyncMethods.contains(e.key_ptr.*)) try env.syncFns.put(env.arena, e.key_ptr.*, {});
    env.syncCalls.clearRetainingCapacity();
    var tit = env.hookTargets.iterator();
    while (tit.next()) |e| {
        const t = e.value_ptr.*;
        if (t.type_) |ty| {
            const d = ty.deref();
            if (d.* != .named or !std.mem.eql(u8, d.named.name, "Component")) continue;
        }
        if (!try hookTargetAsync(env, t.ref)) try env.syncCalls.put(env.arena, e.key_ptr.*, {});
    }
    var cit = env.methodCallTargets.iterator();
    while (cit.next()) |e| if (env.methodHooks.contains(e.value_ptr.*) and !asyncMethods.contains(e.value_ptr.*))
        try env.syncCalls.put(env.arena, e.key_ptr.*, {});
}

/// A host function — `declare fn`, an implemented one — or std's
/// compiler-lowered `provide` / `context`: no node.
fn isHookHost(f: ast.FnDecl) bool {
    if (f.isDeclare or f.body.len == 0) return true;
    return f.isExternal();
}

/// Decision 277 — publish this module's top-level functions with their nodes
/// to the session, for the modules that import them.
fn publishHookFns(env: *Env, program: ast.Program) InferError!void {
    const r = env.reflection orelse return;
    for (program.decls) |d| {
        if (d != .@"fn") continue;
        const f = d.@"fn";
        const host = isHookHost(f) or std.mem.eql(u8, env.modulePath, "std/context");
        const ref: hooksMod.DeclRef = .{
            .module = env.modulePath,
            .name = f.name,
            .returnTypeName = if (f.returnType) |rt| try declTypeName(r.arena, rt) else "",
        };
        try r.hookFns.put(r.arena, try envMod.declIdentity(r.arena, env.modulePath, f.name), .{
            .ref = ref,
            .host = host,
            .annotations = try hookAnnotations(env, f.annotations),
            .node = if (host) null else env.hookNodes.get(f.name),
            .stage = if (host) hostStage(f) else if (env.hookNodes.get(f.name)) |n| n.stage else .any,
            .why = if (host) (if (hostStage(f) == .run) try std.fmt.allocPrint(r.arena, "it is the host function `{s}`", .{f.name}) else "") else if (env.hookNodes.get(f.name)) |n| n.why else "",
        });
    }
}

/// The node of the function `ref` names, or null for one that has none (a
/// host function). A `.hooks` reader runs after Pass 2 (decision 372), so
/// every body of this module has been inferred and its node recorded.
fn hookNodeOf(env: *Env, ref: hooksMod.DeclRef) InferError!?hooksMod.Node {
    if (std.mem.eql(u8, ref.module, "std/context")) return null;
    if (std.mem.eql(u8, ref.module, env.modulePath)) {
        const f = env.fnDecls.get(ref.name) orelse return null;
        if (isHookHost(f)) return null;
        return env.hookNodes.get(ref.name);
    }
    const r = env.reflection orelse return null;
    const info = r.hookFns.get(try envMod.declIdentity(env.arena, ref.module, ref.name)) orelse return null;
    return info.node;
}

/// Decision 277 — `decl.hooks` of the function `f`: its node, then every node
/// reachable through its `use`s and calls, breadth-first, each node's edges in
/// body order, each function once (an edge back to a listed node adds none).
/// Computed only when a decorator on `f` reads it (`hooks.readsMember`).
fn declHooks(env: *Env, f: ast.FnDecl) InferError![]const hooksMod.Node {
    if (!try decoratorsReadHooks(env, f.annotations)) return &.{};
    const start: hooksMod.DeclRef = .{ .module = env.modulePath, .name = f.name };
    var seen: std.StringHashMapUnmanaged(void) = .empty;
    try seen.put(env.arena, try envMod.declIdentity(env.arena, start.module, start.name), {});
    var queue: std.ArrayListUnmanaged(hooksMod.DeclRef) = .empty;
    try queue.append(env.arena, start);
    var nodes: std.ArrayListUnmanaged(hooksMod.Node) = .empty;
    var i: usize = 0;
    while (i < queue.items.len) : (i += 1) {
        const node = try hookNodeOf(env, queue.items[i]) orelse continue;
        try nodes.append(env.arena, node);
        // The node's edges in body order: its `use`s (over a declaration)
        // and its calls, merged by where they are written.
        var u: usize = 0;
        var c: usize = 0;
        while (u < node.uses.len or c < node.calls.len) {
            const takeUse = c >= node.calls.len or (u < node.uses.len and hooksMod.before(node.uses[u].at, node.calls[c].at));
            const next: ?hooksMod.DeclRef = if (takeUse) node.uses[u].hook else node.calls[c].callee;
            if (takeUse) u += 1 else c += 1;
            const target = next orelse continue;
            const gop = try seen.getOrPut(env.arena, try envMod.declIdentity(env.arena, target.module, target.name));
            if (!gop.found_existing) try queue.append(env.arena, target);
        }
    }
    return nodes.items;
}

/// Whether a body-carrying decorator among `anns` reads `.hooks` — in its
/// body or a function it reaches.
fn decoratorsReadHooks(env: *Env, anns: []const ast.Annotation) InferError!bool {
    for (anns) |a| if (try decoratorReadsHooks(env, a)) return true;
    return false;
}

/// Whether the body-carrying decorator `a` names reads `.hooks` — in its body
/// or a function it reaches (`hooks.readsMember`). Decision 372: such a
/// decorator runs after the module's bodies are inferred.
fn decoratorReadsHooks(env: *Env, a: ast.Annotation) InferError!bool {
    if (a.is_builtin) return false;
    const sig = env.decorators.get(a.name) orelse return false;
    const dfn = sig.fn_decl orelse return false;
    if (dfn.body.len == 0) return false;
    const local = std.mem.eql(u8, env.comptimeOwnerOf(dfn), env.modulePath);
    const support: []const ast.FnDecl = if (local)
        (try decoratorSupport(env.arena, env.fnDecls, &env.importedFnSupport, dfn)).fns
    else
        sig.support;
    return hooksMod.readsMember(&.{dfn}, "hooks") or hooksMod.readsMember(support, "hooks");
}

/// The decorator identities a handle's annotations name (`DeclAnnotation.decorator`),
/// for every annotation of `handle` (its own, its fields', its methods').
fn handleDecoratorIds(env: *Env, handle: decoratorEval.DeclHandle) InferError![]const decoratorEval.DecoratorId {
    var out: std.ArrayListUnmanaged(decoratorEval.DecoratorId) = .empty;
    const lists = [_][]const ast.Annotation{handle.annotations};
    for (lists) |anns| for (anns) |a| try out.append(env.arena, .{ .name = a.name, .id = try annotationDecoratorId(env, a) });
    for (handle.fields) |f| for (f.annotations) |a| try out.append(env.arena, .{ .name = a.name, .id = try annotationDecoratorId(env, a) });
    for (handle.methods) |m| for (m.annotations) |a| try out.append(env.arena, .{ .name = a.name, .id = try annotationDecoratorId(env, a) });
    return out.items;
}

/// `Declared.meta` of a reached declaration: every entry its decorators set
/// so far, keyed `<decorator>.<key>`.
fn hookMetaOf(ctx: *const anyopaque, arena: std.mem.Allocator, module: []const u8, name: []const u8) anyerror![]const hooksMod.MetaPair {
    const r: *const reflectionMod.Reflection = @ptrCast(@alignCast(ctx));
    const entries = try r.metaOf(arena, module, name);
    const out = try arena.alloc(hooksMod.MetaPair, entries.len);
    for (entries, 0..) |e, i| out[i] = .{ .key = try std.fmt.allocPrint(arena, "{s}.{s}", .{ e.decorator, e.key }), .value = e.value };
    return out;
}

fn noMeta(_: *const anyopaque, _: std.mem.Allocator, _: []const u8, _: []const u8) anyerror![]const hooksMod.MetaPair {
    return &.{};
}

/// Decision 526 — `decl.owner` of a member's handle: the `Declared<unknown>`
/// of the type or behavior `owner` of this module that holds the annotated
/// method or field, its meta what the reflection holds so far (a member's
/// decorators run before its owner's). Null `owner` — a top-level
/// declaration — leaves the handle's `null`.
fn withOwner(env: *Env, handle: decoratorEval.DeclHandle, owner: ?[]const u8) InferError!decoratorEval.DeclHandle {
    const name = owner orelse return handle;
    const source: hooksMod.MetaSource = if (env.reflection) |r|
        .{ .ctx = r, .metaOf = hookMetaOf }
    else
        .{ .ctx = env, .metaOf = noMeta };
    var h = handle;
    h.owner = hooksMod.declaredTerm(env.arena, .{ .module = env.modulePath, .name = name }, source) catch return error.OutOfMemory;
    return h;
}

/// The handle a decorator body reads, completed with the decorators its
/// annotations name (`DeclAnnotation.decorator`), which only the checker knows.
fn completeHandle(env: *Env, handle: decoratorEval.DeclHandle) InferError!decoratorEval.DeclHandle {
    var h = handle;
    h.decoratorIds = try handleDecoratorIds(env, handle);
    // Decision 415 (2) — `decl.module`: a declaration of this module, unless
    // the handle names another's (a `q.lookup` answer).
    if (h.module.len == 0 and !h.isTag()) h.module = env.modulePath;
    if (h.package.len == 0 and h.lookup == null and !h.isTag()) h.package = if (env.inStd) "std" else env.package;
    return h;
}

/// Decision 277 — `decl.hooks` of the function `f` as the term its decorator
/// body reads (empty unless one of its decorators reads it).
fn declHooksTerm(env: *Env, f: ast.FnDecl) InferError![]const decoratorEval.Term {
    const nodes = try declHooks(env, f);
    if (nodes.len == 0) return &.{};
    const source: hooksMod.MetaSource = if (env.reflection) |r|
        .{ .ctx = r, .metaOf = hookMetaOf }
    else
        .{ .ctx = env, .metaOf = noMeta };
    return hooksMod.nodesToTerm(env.arena, nodes, source) catch return error.OutOfMemory;
}

/// Bind the names introduced by a destructuring `val { … } = use …` /
/// `val #(…) = use …` against the hook's Return type `R`.
///
/// The record form is lenient — `R` need not be a record, so a field `R` does
/// not declare binds a fresh type var. The tuple form is not (front 19 step 3,
/// decision 67): each name is bound to the element of `R` at its position, and
/// a pattern of another arity, or a hook whose `R` is no tuple at all, is
/// refused at the binding (`use-tuple-arity`). An `R` still unresolved — a
/// generic hook whose instantiation left the tuple open — is committed to a
/// tuple of the pattern's arity, so every element is one variable shared with
/// the hook's own type, never a fresh one unrelated to it.
fn bindUseDestructure(env: *Env, pattern: ast.ParamDestruct, srcTy: *T.Type, loc: ast.Loc) InferError!void {
    const derefed = srcTy.deref();
    switch (pattern) {
        .names => |n| {
            const typeName: []const u8 = switch (derefed.*) {
                .named => |nm| nm.name,
                else => "",
            };
            const maybeDef = env.typeDefs.get(typeName);
            for (n.fields) |fld| {
                const fieldTy = if (maybeDef) |td|
                    if (td.findField(fld.field_name)) |f| f.type_ else try env.freshVar()
                else
                    try env.freshVar();
                try env.bind(fld.bind_name, fieldTy);
            }
        },
        .tuple_ => |t| {
            switch (derefed.*) {
                .named => |n| if (std.mem.eql(u8, n.name, "tuple")) {
                    if (n.args.len != t.len) {
                        env.lastError = TypeError.useTupleArity(t.len, n.args.len, srcTy).withLoc(loc);
                        return error.TypeError;
                    }
                    for (t, n.args) |nm, elemTy| try env.bind(nm, elemTy);
                    return;
                },
                .typeVar => {
                    const elems = try env.arena.alloc(*T.Type, t.len);
                    for (elems) |*e| e.* = try env.freshVar();
                    try unifyAt(env, srcTy, try env.namedTypeArgs("tuple", elems), loc);
                    for (t, elems) |nm, elemTy| try env.bind(nm, elemTy);
                    return;
                },
                else => {},
            }
            env.lastError = TypeError.useTupleArity(t.len, null, srcTy).withLoc(loc);
            return error.TypeError;
        },
        .list, .ctor => {},
    }
}

/// C-02 (decision 63, amended 2026-09-19) — **an index is a method call.**
///
/// The index expression has no typing rule of its own. `xs[k]` **is**
/// `xs.at(k)`, `xs[a..b]` is `xs.slice(a, b)` and `xs[1..]` is
/// `xs.slice(1, null)`; the type of the expression is whatever the method
/// answers, which for `Index<K, V>.at` is `?V`.
///
/// So indexing stops being a privilege of the three built-in collections: a
/// library's own `Matrix`, `Row` or `Buffer` answers `at` / `slice` — ambient
/// behaviors, like `Display`, so the syntax finds the method with nothing
/// imported — and is indexable **with no compiler change**.
///
/// Two halves meet at ONE loc. This function records the untyped method call
/// under the index node's own loc (`env.indexRewrites`) and types that call;
/// `comptime/transform.zig` splices it into the untyped AST before codegen.
/// Because the spliced call keeps the index's loc, every loc-keyed plan
/// inference made while typing it — the method lowering, C-04's default fill —
/// still finds its node. **No backend learns a new rule**: all four already
/// emit a method call, and none of them is touched by this row.
///
/// A range second argument is the slice — one AST node serves indexing and
/// slicing because the index is an ordinary expression (`ast.zig`'s contract) —
/// and an open end travels as `null`, because `start..end` is an AST node and
/// not a value: there is no `Range` type to pass.
fn inferIndexExpr(env: *Env, call: anytype, loc: ast.Loc) InferError!TypedExpr {
    if (call.args.len != 2) {
        env.lastError = TypeError.custom(
            "an index expression carries a receiver and an index",
            "This is the parser's own sugar (`xs[0]`); reaching here with another shape is a compiler bug.",
        ).withLoc(loc);
        return error.TypeError;
    }
    const recvExpr = call.args[0].value;
    const idxExpr = call.args[1].value;

    // The receiver is typed once, HERE, because only its type tells a tuple
    // from everything else — and a tuple is the one receiver the behavior
    // cannot cover. Everything else re-reads it through the rewritten call,
    // which is the ordinary method path and owes nothing to this row.
    const typedRecv = try inferExprTyped(env, recvExpr.*);
    const recvType = typedRecv.getType().deref();
    if (recvType.* == .named and std.mem.eql(u8, recvType.named.name, "tuple")) {
        return inferTupleIndexExpr(env, recvType.named.args, recvExpr, idxExpr, loc);
    }

    const rewrite = try env.arena.create(ast.Expr);
    if (idxExpr.* == .collection and idxExpr.collection.kind == .range) {
        const r = idxExpr.collection.kind.range;
        const args = try env.arena.alloc(ast.CallArgOf(.untyped), 2);
        args[0] = .{ .label = null, .value = r.start };
        args[1] = .{
            .label = null,
            .value = if (r.end) |end| blk: {
                if (!r.inclusive) break :blk end;
                // `xs[a...b]` (decisions 53, 105) includes `b`: `slice` stops
                // before its end, so the end is `b + 1`.
                const one = try env.arena.create(ast.Expr);
                // Located inside the `...` token: no written node shares it.
                const oneLoc: ast.Loc = .{ .line = idxExpr.collection.loc.line, .col = idxExpr.collection.loc.col + 1, .expansion = idxExpr.collection.loc.expansion };
                one.* = .{ .literal = .{ .loc = oneLoc, .kind = .{ .numberLit = "1" } } };
                const sum = try env.arena.create(ast.Expr);
                sum.* = .{ .binaryOp = .{ .loc = idxExpr.collection.loc, .op = .add, .lhs = end, .rhs = one } };
                break :blk sum;
            } else blk: {
                const nullLit = try env.arena.create(ast.Expr);
                nullLit.* = .{ .literal = .{ .loc = idxExpr.collection.loc, .kind = .null_ } };
                break :blk nullLit;
            },
        };
        rewrite.* = .{ .call = .{ .loc = loc, .kind = .{ .call = .{
            .receiver = recvExpr,
            .callee = index_slice_method,
            .is_builtin = false,
            .args = args,
            .trailing = &.{},
        } } } };
    } else {
        const args = try env.arena.alloc(ast.CallArgOf(.untyped), 1);
        args[0] = .{ .label = null, .value = idxExpr };
        rewrite.* = .{ .call = .{ .loc = loc, .kind = .{ .call = .{
            .receiver = recvExpr,
            .callee = index_at_method,
            .is_builtin = false,
            .args = args,
            .trailing = &.{},
        } } } };
    }
    try env.indexRewrites.put(loc, rewrite);
    return inferExprTyped(env, rewrite.*);
}

/// Decision 330 (2) — an optional operator over a value whose type is not
/// `?T` is refused at the operator, naming the type: the value is never
/// `null`, so the operator says something the program does not mean. An
/// operand still a type variable is left to the rest of the check.
fn refuseNeverNull(env: *Env, ty: *T.Type, op: []const u8, loc: ast.Loc) InferError!void {
    const t = ty.deref();
    if (t.* == .typeVar) return;
    if (optionalInner(t) != null) return;
    try refuseUnknownUse(env, t, loc, "apply an optional operator to");
    const shown = try snapshotMod.typeNameOf(env.arena, t);
    const msg = try std.fmt.allocPrint(
        env.arena,
        "{s}: `{s}` over a value that is never null — this is `{s}`, not `?{s}`",
        .{ diagnostics.optional_operator_never_null, op, shown, shown },
    );
    env.lastError = TypeError.custom(msg, "`??`, `?.`, `?.[]`, `?.()` and the postfix `!` read a `?T`. Drop the operator, or give the value an optional type.").withLoc(loc);
    return error.TypeError;
}

/// The column added to a node `inferOptionalOperator` synthesises where no
/// written token stands (the abort of `x!`): past any written column, so its
/// loc keys no plan of a written node.
const optional_synthetic_col = ast.optional_synthetic_col;

/// Decision 330 — `recv?.[i]`, `f?.(args)`, `recv?.m(args)` and `x!` have no
/// typing rule of their own: each IS the `if` over the optional it reads,
/// with a binder of its own (`__bp_opt_<line>_<col>`, so nested ones never
/// share an Erlang variable):
///
///   recv?.[i]       if (recv) { n -> n[i] } else { null }
///   f?.(args)       if (f) { n -> n(args) } else { null }
///   recv?.m(args)   if (recv) { n -> n.m(args) } else { null }
///   x!              if (x) { n -> n } else { @panic("value is null — x! at <file>:<line>:<col>") }
///
/// The `if` is recorded under the operator's loc (`env.indexRewrites`) and
/// typed here — for `recv?.m(args)` only typed, the call keeping its node —
/// so the three `?.` forms answer `?U` flattened (a link answering
/// `?U` joins `null` as `?U`, never `??U`) and `x!` answers `T`; the transform
/// splices it in, and no backend learns a new rule. The inner link keeps a
/// written loc of its own — the `[` or `(` after `?.`, the method's name — so
/// the plans inference makes while typing it find it. The operand is refused
/// first when it is never `null` (`refuseNeverNull`).
fn inferOptionalOperator(env: *Env, call: anytype, loc: ast.Loc) InferError!TypedExpr {
    const isBang = call.is_builtin and std.mem.eql(u8, call.callee, ast.non_null_builtin_name);
    const isIndex = call.is_builtin and std.mem.eql(u8, call.callee, ast.index_builtin_name);
    const operand: *ast.Expr = if (isBang or isIndex)
        call.args[0].value
    else if (call.calleeExpr) |ce|
        ce
    else
        call.receiver orelse {
            env.lastError = TypeError.custom("`?.` reads an optional, and this call has no receiver", "Write `recv?.m(…)`, `recv?.[i]` or `f?.(…)`.").withLoc(loc);
            return error.TypeError;
        };
    const op: []const u8 = if (isBang) "!" else if (isIndex) "?.[]" else if (call.calleeExpr != null) "?.()" else "?.";
    const saved = env.expectedType;
    env.expectedType = null;
    const typedOperand = try inferExprTyped(env, operand.*);
    env.expectedType = saved;
    try refuseNeverNull(env, typedOperand.getType(), op, loc);

    const binder = if (loc.expansion == 0)
        try std.fmt.allocPrint(env.arena, "__bp_opt_{d}_{d}", .{ loc.line, loc.col })
    else
        try std.fmt.allocPrint(env.arena, "__bp_opt_{d}_{d}_{d}", .{ loc.line, loc.col, loc.expansion });
    const bound = try env.arena.create(ast.Expr);
    bound.* = .{ .identifier = .{ .loc = loc, .kind = .{ .ident = binder } } };
    const inner = try env.arena.create(ast.Expr);
    const elseExpr = try env.arena.create(ast.Expr);
    // The link after `?.` is located at its own token: two columns on.
    const linkLoc: ast.Loc = .{ .line = loc.line, .col = loc.col + 2, .expansion = loc.expansion };
    if (isBang) {
        inner.* = bound.*;
        const text = try defaultLexeme(env.arena, operand.*);
        const start = leftmostLoc(operand);
        const message = try std.fmt.allocPrint(env.arena, "value is null — {s}! at {s}:{d}:{d}", .{ text, env.srcPath, start.line, start.col });
        const msgLit = try env.arena.create(ast.Expr);
        const panicLoc: ast.Loc = .{ .line = loc.line, .col = loc.col + optional_synthetic_col, .expansion = loc.expansion };
        msgLit.* = .{ .literal = .{ .loc = panicLoc, .kind = .{ .stringLit = message } } };
        const args = try env.arena.alloc(ast.CallArg, 1);
        args[0] = .{ .label = null, .value = msgLit };
        elseExpr.* = .{ .call = .{ .loc = panicLoc, .kind = .{ .call = .{
            .receiver = null,
            .callee = "panic",
            .is_builtin = true,
            .args = args,
            .trailing = &.{},
        } } } };
    } else {
        elseExpr.* = .{ .literal = .{ .loc = loc, .kind = .null_ } };
        var link = call;
        link.optional = false;
        const payload = optionalInner(typedOperand.getType().deref());
        const isTuple = if (payload) |p| p.deref().* == .named and std.mem.eql(u8, p.deref().named.name, "tuple") else false;
        const idx = if (isIndex) call.args[1].value else undefined;
        if (isIndex and !isTuple and !(idx.* == .collection and idx.collection.kind == .range)) {
            // `xs?.[k]` reads `xs.at(k)` through the optional (the index IS
            // `at`, `inferIndexExpr`): written as the method call, which every
            // backend lowers on a binder (wasm does not lower `n[k]` there).
            const args = try env.arena.alloc(ast.CallArg, 1);
            args[0] = .{ .label = null, .value = idx };
            link = .{
                .receiver = bound,
                .callee = index_at_method,
                .is_builtin = false,
                .args = args,
                .trailing = &.{},
            };
            inner.* = .{ .call = .{ .loc = linkLoc, .kind = .{ .call = link } } };
        } else if (isIndex) {
            const args = try env.arena.alloc(ast.CallArg, 2);
            args[0] = .{ .label = null, .value = bound };
            args[1] = call.args[1];
            link.args = args;
            inner.* = .{ .call = .{ .loc = linkLoc, .kind = .{ .call = link } } };
        } else if (call.calleeExpr != null) {
            link.calleeExpr = bound;
            inner.* = .{ .call = .{ .loc = linkLoc, .kind = .{ .call = link } } };
        } else {
            // Typed only (below): at a loc of its own, so the plans its
            // typing records do not land on the written call's.
            link.receiver = bound;
            inner.* = .{ .call = .{ .loc = .{ .line = loc.line, .col = loc.col + optional_synthetic_col, .expansion = loc.expansion }, .kind = .{ .call = link } } };
        }
    }
    const isMethod = !isBang and !isIndex and call.calleeExpr == null;
    var then_ = try env.arena.alloc(ast.Stmt, 1);
    then_[0] = .{ .expr = inner.* };
    var else_ = try env.arena.alloc(ast.Stmt, 1);
    else_[0] = .{ .expr = elseExpr.* };
    const rewrite = try env.arena.create(ast.Expr);
    rewrite.* = .{ .branch = .{ .loc = loc, .kind = .{ .if_ = .{
        .cond = operand,
        .binding = binder,
        .then_ = then_,
        .else_ = else_,
    } } } };
    const typed = inferExprTyped(env, rewrite.*) catch |err| {
        // A refusal inside the synthesised link is the written call's.
        if (env.lastError) |*e| if (e.loc) |*l| if (l.col > optional_synthetic_col) {
            l.col -= optional_synthetic_col;
        };
        return err;
    };
    // `recv?.m(args)` keeps its own node: the backends lower the optional
    // method call as they did before 330 (wasm included), from the plans the
    // call's own typing records under its loc; the `if` only types it —
    // `?U`, flattened.
    if (isMethod) {
        var direct = call;
        direct.optional = false;
        const savedChain = env.inOptionalChain;
        env.inOptionalChain = true;
        defer env.inOptionalChain = savedChain;
        var old = try inferCallExpr(env, .{ .loc = loc, .kind = .{ .call = direct } }, loc);
        if (old == .call) {
            old.call.type_ = typed.getType();
            if (old.call.kind == .call) old.call.kind.call.optional = true;
        }
        // The written call's receiver is the `?T`, so typing it recorded no
        // instance lowering (the payload `T` owns the method); the synthesised
        // link over the binder did, at its own loc (a nominal type's alone: a
        // primitive's is the payload's, and `?.` over it stays the guard). A backend without native
        // dispatch (beam) reads the written call's loc: carry the link's over,
        // or an imported enum's `x?.m()` called the variant's atom as a module.
        const synthLoc: ast.Loc = .{ .line = loc.line, .col = loc.col + optional_synthetic_col, .expansion = loc.expansion };
        if (env.instanceLowerings.get(loc) == null) {
            if (env.instanceLowerings.get(synthLoc)) |il| if (il == .type_ or (il == .prim and il.prim == .array)) try env.instanceLowerings.put(loc, il);
        }
        return old;
    }
    try env.indexRewrites.put(loc, rewrite);
    return typed;
}

/// `<chain>.member` after a `?.` link: the `if` over the chain's optional
/// with a binder of its own, the member read off the binder, `null` when the
/// chain is absent. Typed here and recorded under the access's loc; its own
/// nodes sit at the synthetic column so the transform's splice never meets
/// the access's loc again. The typed node answered is the access as a `?.`
/// link over `typedReceiver`.
fn inferOptionalChainField(env: *Env, receiver: *ast.Expr, typedReceiver: *ast.TypedExpr, member: []const u8, loc: ast.Loc) InferError!TypedExpr {
    const inner_loc: ast.Loc = .{ .line = loc.line, .col = loc.col + optional_synthetic_col, .expansion = loc.expansion };
    const binder = if (loc.expansion == 0)
        try std.fmt.allocPrint(env.arena, "__bp_optf_{d}_{d}", .{ loc.line, loc.col })
    else
        try std.fmt.allocPrint(env.arena, "__bp_optf_{d}_{d}_{d}", .{ loc.line, loc.col, loc.expansion });
    const bound = try env.arena.create(ast.Expr);
    bound.* = .{ .identifier = .{ .loc = inner_loc, .kind = .{ .ident = binder } } };
    const read = try env.arena.create(ast.Expr);
    read.* = .{ .identifier = .{ .loc = inner_loc, .kind = .{ .identAccess = .{ .receiver = bound, .member = member } } } };
    const absent = try env.arena.create(ast.Expr);
    absent.* = .{ .literal = .{ .loc = inner_loc, .kind = .null_ } };
    var then_ = try env.arena.alloc(ast.Stmt, 1);
    then_[0] = .{ .expr = read.* };
    var else_ = try env.arena.alloc(ast.Stmt, 1);
    else_[0] = .{ .expr = absent.* };
    const rewrite = try env.arena.create(ast.Expr);
    rewrite.* = .{ .branch = .{ .loc = loc, .kind = .{ .if_ = .{
        .cond = receiver,
        .binding = binder,
        .then_ = then_,
        .else_ = else_,
    } } } };
    const typed = inferExprTyped(env, rewrite.*) catch |err| {
        // A refusal inside the synthesised read is the written access's.
        if (env.lastError) |*e| if (e.loc) |*l| if (l.col > optional_synthetic_col) {
            l.col -= optional_synthetic_col;
        };
        return err;
    };
    try env.enumSectionRewrites.put(loc, rewrite);
    // Typed as the `?.` link it reads like, so a link after it continues the
    // chain too (`p?.me().name.length()`, `continuesOptionalChain`).
    return TypedExpr{ .identifier = .{ .loc = loc, .type_ = typed.getType(), .kind = .{ .identAccess = .{
        .receiver = typedReceiver,
        .member = member,
        .optional = true,
    } } } };
}

/// Where an expression starts: the loc of its leftmost operand (`a` in
/// `a.b.c()`, `xs` in `xs[0]`), for the location `x!`'s abort names.
fn leftmostLoc(e: *const ast.Expr) ast.Loc {
    return switch (e.*) {
        .identifier => |id| switch (id.kind) {
            .identAccess => |a| leftmostLoc(a.receiver),
            else => id.loc,
        },
        .call => |c| switch (c.kind) {
            .call => |cc| if (cc.receiver) |r|
                leftmostLoc(r)
            else if (cc.calleeExpr) |ce|
                leftmostLoc(ce)
            else if (cc.is_builtin and cc.args.len > 0 and
                (std.mem.eql(u8, cc.callee, ast.index_builtin_name) or std.mem.eql(u8, cc.callee, ast.non_null_builtin_name)))
                leftmostLoc(cc.args[0].value)
            else
                c.loc,
            else => c.loc,
        },
        inline else => |n| n.loc,
    };
}

/// The two method names the index expression rewrites to — the ones
/// `Index<K, V>` and `Slice<V>` declare in `libs/std/src/primitives.bp`'s compiler section.
const index_at_method = "at";
const index_slice_method = "slice";

/// A tuple index — the checker's one special case, and the reason the ambient
/// behavior covers the other three receivers and not this one: `t[0]` needs a
/// **constant** index and answers a type **per position**, which
/// `at(key: K) -> ?V` cannot say with a single `V`.
///
/// It rewrites to the positional member access the checker already types and
/// all four backends already emit (`t[0]` → `t._0`), so the special case costs
/// a checker arm and no backend arm — the same bargain as the method rewrite,
/// through a different door.
fn inferTupleIndexExpr(
    env: *Env,
    elems: []*T.Type,
    recvExpr: *ast.Expr,
    idxExpr: *ast.Expr,
    loc: ast.Loc,
) InferError!TypedExpr {
    const digits: []const u8 = if (idxExpr.* == .literal and idxExpr.literal.kind == .numberLit)
        idxExpr.literal.kind.numberLit
    else {
        env.lastError = TypeError.custom(
            "a tuple index must be a constant — a tuple answers a type per position",
            "Write the position (`t[0]`, `t[1]`) or read the element by its label (`t.pop`); an array or a `Dict` is the indexable a computed key belongs to.",
        ).withLoc(loc);
        return error.TypeError;
    };
    const idx = std.fmt.parseInt(usize, digits, 10) catch {
        env.lastError = TypeError.custom(
            "a tuple index must be a constant — a tuple answers a type per position",
            "Write the position (`t[0]`, `t[1]`) or read the element by its label (`t.pop`).",
        ).withLoc(loc);
        return error.TypeError;
    };
    if (idx >= elems.len) {
        env.lastError = TypeError.custom(
            try std.fmt.allocPrint(
                env.arena,
                "this tuple has {d} element(s), so `[{d}]` names no position",
                .{ elems.len, idx },
            ),
            "A tuple's positions are fixed by its type; the last one is one less than its length.",
        ).withLoc(loc);
        return error.TypeError;
    }
    const rewrite = try env.arena.create(ast.Expr);
    rewrite.* = .{ .identifier = .{ .loc = loc, .kind = .{ .identAccess = .{
        .receiver = recvExpr,
        .member = try std.fmt.allocPrint(env.arena, "_{d}", .{idx}),
        .optional = false,
    } } } };
    try env.indexRewrites.put(loc, rewrite);
    return inferExprTyped(env, rewrite.*);
}

/// The parameters of the callee a call names: a plain function's (or a
/// constructor's), or — with the receiver typed — a method's, `self` left
/// out, and an associated function's (`Bag.of(…)`: a receiver naming a type
/// calls its associated fn; the name's own binding is the constructor, typed
/// as a function).
fn calleeParamsOf(env: *Env, call: anytype, typedReceiver: ?*ast.TypedExpr) ?[]const ast.Param {
    if (typedReceiver) |tr| {
        const typeNamed: ?[]const u8 = if (call.receiver) |r|
            (if (r.* == .identifier and r.identifier.kind == .ident and env.lookupTypeDef(r.identifier.kind.ident) != null) r.identifier.kind.ident else null)
        else
            null;
        const owner = nominalName(tr.getType()) orelse typeNamed orelse return null;
        const ps = env.getInherentMethodParams(owner, call.callee) orelse return null;
        return if (ps.len > 0 and std.mem.eql(u8, ps[0].name, "self")) ps[1..] else ps;
    }
    return calleeParams(env, call.callee);
}

/// Decision 267 — the parameters a call's arguments bind (a method's `self`
/// left out) when the last one is variadic; null for every other callee. A
/// plain call reads the declaration by name (`calleeParams`), a method or an
/// associated function the receiver's type's (`Env.getInherentMethodParams`).
fn variadicCalleeParams(env: *Env, call: anytype, typedReceiver: ?*ast.TypedExpr) ?[]const ast.Param {
    const params = calleeParamsOf(env, call, typedReceiver) orelse return null;
    if (params.len == 0 or !params[params.len - 1].variadic) return null;
    return params;
}

/// Decision 267 — `c` with the arguments past the fixed parameters packed
/// into one array literal (`variadicPacked`), recorded under the call's loc
/// for the transform. A spread (`f(..xs)`) and a label on a variadic
/// argument are refused at the argument; a trailing lambda at the call.
fn packVariadicCall(env: *Env, c: ast.CallExprOf(.untyped), params: []const ast.Param, loc: ast.Loc) InferError!ast.CallExprOf(.untyped) {
    const call = c.kind.call;
    const fixed = params.len - 1;
    const v = params[fixed];
    for (call.args, 0..) |a, i| {
        const label = a.label orelse continue;
        if (std.mem.eql(u8, label, "..") or std.mem.eql(u8, label, ast.record_spread_label)) {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is variadic, and a call passes its arguments one by one — there is no spread at a call", .{ diagnostics.variadic_spread, call.callee });
            const hint = try std.fmt.allocPrint(env.arena, "Write the arguments after the fixed ones (`{s}(a, b, c)`); a function that takes an existing array declares `{s}: T[]`, not `..{s}` (decision 267).", .{ call.callee, v.name, v.name });
            env.lastError = TypeError.custom(msg, hint).withLoc(a.value.getLoc());
            return error.TypeError;
        }
        if (i >= fixed or std.mem.eql(u8, label, v.name)) {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` of `{s}` is variadic and takes no label", .{ diagnostics.variadic_label, v.name, call.callee });
            env.lastError = TypeError.custom(msg, "Pass the variadic's arguments by position, after the fixed ones (decision 267).").withLoc(a.value.getLoc());
            return error.TypeError;
        }
    }
    if (call.trailing.len > 0) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is variadic, and a trailing lambda is not one of its arguments", .{ diagnostics.variadic_label, call.callee });
        env.lastError = TypeError.custom(msg, "Pass the lambda inside the parentheses, by position (decision 267).").withLoc(loc);
        return error.TypeError;
    }
    if (call.args.len < fixed) {
        const msg = try std.fmt.allocPrint(env.arena, "'{s}' expects at least {d} argument(s), got {d}", .{ call.callee, fixed, call.args.len });
        const hint = try std.fmt.allocPrint(env.arena, "Pass the {d} fixed argument(s) first; `..{s}` takes the ones after them (decision 267).", .{ fixed, v.name });
        env.lastError = TypeError.custom(msg, hint).withLoc(loc);
        return error.TypeError;
    }
    const elems = try env.arena.alloc(ast.Expr, call.args.len - fixed);
    for (call.args[fixed..], elems) |a, *e| e.* = a.value.*;
    const arr = try env.arena.create(ast.Expr);
    arr.* = .{ .collection = .{ .loc = loc, .kind = .{ .arrayLit = .{ .elems = elems } } } };
    const args = try env.arena.alloc(ast.CallArgOf(.untyped), fixed + 1);
    @memcpy(args[0..fixed], call.args[0..fixed]);
    args[fixed] = .{ .label = null, .value = arr };
    const out = markPacked(c, args);
    // The backends read the program's call: the transform splices this one
    // in (`index_rewrites`, a `variadicPacked` call).
    const spliced = try env.arena.create(ast.Expr);
    spliced.* = .{ .call = out };
    try env.indexRewrites.put(loc, spliced);
    return out;
}

/// Decision 529 (2) — the name a `..props: R` parameter's type is declared
/// under (`R`, or `Props` of `Props<T>`); null when the type is no name.
fn recordParamTypeName(p: ast.Param) ?[]const u8 {
    return switch (p.typeRef) {
        .named => |n| n,
        .generic => |g| g.name,
        else => null,
    };
}

/// Decision 529 (2) — the fields of the record a `..props: R` parameter names,
/// or null when `R` is no record (an enum, an unknown name).
fn recordParamFields(env: *Env, p: ast.Param) ?[]const envMod.FieldDef {
    const raw = recordParamTypeName(p) orelse return null;
    const name = env.importedTypeAliases.get(raw) orelse raw;
    if (env.namespaceTypes.contains(name)) return null;
    const td = env.lookupTypeDef(name) orelse return null;
    return switch (td) {
        .record => |r| r.fields,
        .struct_ => |st| st.fields,
        .enum_ => null,
    };
}

/// Decision 529 (2) — the declaration's rules for `..props: R`: at most one per
/// function, `R` a record, no name that is both a parameter and a field of
/// `R`, and no variadic beside it. Each is refused at the declaration.
fn checkRecordParams(env: *Env, f: ast.FnDecl) InferError!void {
    return checkRecordParamList(env, f.name, f.params);
}

fn checkRecordParamList(env: *Env, name: []const u8, params: []const ast.Param) InferError!void {
    var first: ?usize = null;
    for (params, 0..) |p, i| {
        if (!p.recordParam) continue;
        if (first) |fi| {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` already takes `..{s}` as its record parameter — a function has at most one", .{ diagnostics.record_param_twice, name, params[fi].name });
            env.lastError = TypeError.custom(msg, "Declare the second one as an ordinary parameter `name: R`, or merge the two records (`Type.merge`, decision 307).").withLoc(p.loc);
            return error.TypeError;
        }
        first = i;
    }
    const k = first orelse return;
    const rp = params[k];
    const fields = recordParamFields(env, rp) orelse {
        const shown = recordParamTypeName(rp) orelse "this type";
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `..{s}: {s}` — `{s}` is no record type, and only a record's fields can be a function's parameters from outside", .{ diagnostics.record_param_not_record, rp.name, shown, shown });
        env.lastError = TypeError.custom(msg, "Write a record type (or one derived by `Type.pick` / `Type.omit` / `Type.merge`, decision 307); a rest of positional values is `..values: T[]` (decision 267).").withLoc(rp.typeLoc);
        return error.TypeError;
    };
    for (params, 0..) |p, i| {
        if (i == k) continue;
        if (p.variadic) {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` takes both `..{s}: R` and the variadic `..{s}` — a record parameter and a variadic do not share a function", .{ diagnostics.record_param_variadic, name, rp.name, p.name });
            env.lastError = TypeError.custom(msg, "Pass the values in an array parameter `name: T[]`, or move them into a field of the record.").withLoc(p.loc);
            return error.TypeError;
        }
        for (fields) |fd| if (std.mem.eql(u8, fd.name, p.name)) {
            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is both a parameter of `{s}` and a field of `{s}`, the type of `..{s}`", .{ diagnostics.record_param_clash, p.name, name, recordParamTypeName(rp).?, rp.name });
            env.lastError = TypeError.custom(msg, "A call passes both by label, so one name cannot stand for two: rename the parameter or the field.").withLoc(p.loc);
            return error.TypeError;
        };
    }
}

/// Decision 529 (2) — the parameters of a plain call's callee when one of them
/// is a record parameter `..props: R`; null for every other callee.
fn recordParamCalleeParams(env: *Env, call: anytype) ?[]const ast.Param {
    if (call.recordPacked or call.is_builtin or call.receiver != null or call.calleeExpr != null) return null;
    const ps = calleeParams(env, call.callee) orelse return null;
    for (ps) |p| if (p.recordParam) return ps;
    return null;
}

/// Decision 864 (5) — the same for a method (`x.m(title: "a")`) and an
/// associated function (`T.make(..p)`), once the receiver is typed.
fn recordParamMethodParams(env: *Env, call: anytype, typedReceiver: ?*ast.TypedExpr) ?[]const ast.Param {
    if (typedReceiver == null or call.recordPacked or call.is_builtin or call.calleeExpr != null) return null;
    const ps = calleeParamsOf(env, call, typedReceiver) orelse return null;
    for (ps) |p| if (p.recordParam) return ps;
    return null;
}

/// Decision 529 (2) — a call of a function with a record parameter
/// (`Card(title: "a", featured: true, onClick: f)`, `Card(..p, featured: true)`):
/// the labels that name a field of `R` and the spread are gathered into one
/// record construction `R(…)`, the argument of the record parameter (labelled
/// with its name); the other arguments stay. The rewritten call is typed and
/// recorded for the transform under the call's loc; the construction goes
/// through the record's own rules (359: the later supplier wins, a missing
/// field without a default, the spread's source type). A label naming neither
/// a parameter nor a field is `record-param-label` at the label.
fn packRecordParamCall(env: *Env, c: ast.CallExprOf(.untyped), params: []const ast.Param, loc: ast.Loc) InferError!ast.CallExprOf(.untyped) {
    const call = c.kind.call;
    var k: usize = 0;
    for (params, 0..) |p, i| if (p.recordParam) {
        k = i;
    };
    const rp = params[k];
    const fields = recordParamFields(env, rp) orelse {
        const shown = recordParamTypeName(rp) orelse "this type";
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `..{s}: {s}` — `{s}` is no record type here", .{ diagnostics.record_param_not_record, rp.name, shown, shown });
        env.lastError = TypeError.custom(msg, "The record parameter's type must be a record visible where the function is called.").withLoc(loc);
        return error.TypeError;
    };
    const recName = recordParamTypeName(rp).?;
    var outer: std.ArrayListUnmanaged(ast.CallArg) = .empty;
    var inner: std.ArrayListUnmanaged(ast.CallArg) = .empty;
    var pos: usize = 0;
    for (call.args) |a| {
        const label = a.label orelse {
            // The record parameter takes no positional argument: positions
            // count the other parameters.
            var j: usize = 0;
            var seen: usize = 0;
            while (j < params.len) : (j += 1) {
                if (j == k) continue;
                if (seen == pos) break;
                seen += 1;
            }
            pos += 1;
            if (j > k and j < params.len) {
                var labelled = a;
                labelled.label = params[j].name;
                try outer.append(env.arena, labelled);
            } else try outer.append(env.arena, a);
            continue;
        };
        if (std.mem.eql(u8, label, ast.record_spread_label)) {
            try inner.append(env.arena, a);
            continue;
        }
        const isParam = for (params, 0..) |p, i| {
            if (i != k and std.mem.eql(u8, p.name, label)) break true;
        } else false;
        if (isParam) {
            try outer.append(env.arena, a);
            continue;
        }
        const isField = for (fields) |fd| {
            if (std.mem.eql(u8, fd.name, label)) break true;
        } else false;
        if (isField) {
            try inner.append(env.arena, a);
            continue;
        }
        const vloc = a.value.getLoc();
        const labelCol = if (vloc.col > label.len + 2) vloc.col - label.len - 2 else vloc.col;
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` names neither a parameter of `{s}` nor a field of `{s}`, the type of `..{s}`", .{ diagnostics.record_param_label, label, call.callee, recName, rp.name });
        env.lastError = TypeError.custom(msg, "A call passes the record parameter's fields and the other parameters by label.").withLoc(.{ .line = vloc.line, .col = labelCol, .expansion = vloc.expansion });
        return error.TypeError;
    }
    const innerLoc: ast.Loc = .{ .line = loc.line, .col = loc.col + ast.record_param_synthetic_col, .expansion = loc.expansion };
    const record = try env.arena.create(ast.Expr);
    record.* = .{ .call = .{ .loc = innerLoc, .kind = .{ .call = .{
        .receiver = null,
        .callee = recName,
        .is_builtin = false,
        .args = try inner.toOwnedSlice(env.arena),
        .trailing = &.{},
    } } } };
    try outer.append(env.arena, .{ .label = rp.name, .value = record });
    var out = c;
    out.kind.call.args = try outer.toOwnedSlice(env.arena);
    out.kind.call.recordPacked = true;
    const spliced = try env.arena.create(ast.Expr);
    spliced.* = .{ .call = out };
    try env.indexRewrites.put(loc, spliced);
    return out;
}

fn markPacked(c: ast.CallExprOf(.untyped), args: []ast.CallArgOf(.untyped)) ast.CallExprOf(.untyped) {
    var out = c;
    out.kind.call.args = args;
    out.kind.call.variadicPacked = true;
    return out;
}

fn inferCallExpr(env: *Env, c: ast.CallExprOf(.untyped), loc: ast.Loc) InferError!TypedExpr {
    if (try asyncResolveBlock(env, c, loc)) |block| {
        const spliced = try env.arena.create(ast.Expr);
        spliced.* = block;
        try env.templateExpansions.put(loc, spliced);
        return inferExprTyped(env, block);
    }
    const expected = env.expectedType;
    try refuseBehaviorCallOnEntry(env, c, loc);
    try refuseComposeCall(env, c, loc);
    const typed = try inferCallExprWith(env, c, loc, null);
    // Decision 562 — a call of a function whose every parameter is
    // `comptime` is replaced by the code its body emits.
    if (try expandCall.expand(env, c, loc, expected)) |expanded| return expanded;
    return typed;
}

/// Decision 804 (1) — `Card.compose()`, `Card` a type component of this
/// module: the body is never called; the component is (`Card(…)`), or placed
/// in the tree.
fn refuseComposeCall(env: *Env, c: ast.CallExprOf(.untyped), loc: ast.Loc) InferError!void {
    if (c.kind != .call) return;
    const call = c.kind.call;
    if (call.is_builtin or !std.mem.eql(u8, call.callee, "compose")) return;
    const recv = call.receiver orelse return;
    if (recv.* != .identifier or recv.identifier.kind != .ident) return;
    const name = recv.identifier.kind.ident;
    var it = env.composedTypes.valueIterator();
    while (it.next()) |comp| if (std.mem.eql(u8, comp.*, name)) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}.compose()` calls the body of the type component `{s}` — call the component, not its body: `{s}(…)`, or place it in the tree (decision 804 (1))", .{ diagnostics.component_compose_called, name, name, name });
        env.lastError = TypeError.custom(msg, "A component's body runs when the component is resolved (`use` in a component body) or rendered as a child; `compose` is never called by hand.").withLoc(loc);
        return error.TypeError;
    };
}

/// Decision 570 — `Async.resolve(v)`, std's one way to hand on a value as an `Async<T>` from a
/// function that carries no marker (JS `Promise.resolve`, Rust `std::future::ready`): the
/// closed block `async { v }` (decision 124), which every backend already runs. Null unless the
/// call is `Async.resolve(<one argument>)` with no `Async` of the program's own in scope.
fn asyncResolveBlock(env: *Env, c: ast.CallExprOf(.untyped), loc: ast.Loc) InferError!?ast.Expr {
    if (c.kind != .call) return null;
    const call = c.kind.call;
    if (call.is_builtin or call.calleeExpr != null or call.args.len != 1 or call.trailing.len != 0) return null;
    if (!std.mem.eql(u8, call.callee, "resolve")) return null;
    const recv = call.receiver orelse return null;
    if (recv.* != .identifier or recv.identifier.kind != .ident) return null;
    if (!std.mem.eql(u8, recv.identifier.kind.ident, "Async")) return null;
    if (env.lookup("Async") != null or env.lookupTypeDef("Async") != null) return null;
    const body = try env.arena.alloc(ast.Stmt, 1);
    body[0] = .{ .expr = .{ .jump = .{ .loc = loc, .kind = .{ .@"return" = call.args[0].value } } }, .tail = .returned };
    return ast.Expr{ .function = .{ .loc = loc, .kind = .{
        .syntax = .asyncBlock,
        .params = &.{},
        .body = body,
    } } };
}

/// Decision 564 — `d.value.f(…)`, `d` a catalogue entry `Declared<B>` and
/// `f` a function of the behavior `B`: legal only inside a 562 expansion,
/// where each entry is a concrete type and the call is emitted direct.
/// Elsewhere it is refused at the call.
fn refuseBehaviorCallOnEntry(env: *Env, c: ast.CallExprOf(.untyped), loc: ast.Loc) InferError!void {
    if (env.inExpansion or c.kind != .call) return;
    const call = c.kind.call;
    if (call.is_builtin or call.calleeExpr != null) return;
    const recv = call.receiver orelse return;
    if (recv.* != .identifier or recv.identifier.kind != .identAccess) return;
    const ia = recv.identifier.kind.identAccess;
    if (!std.mem.eql(u8, ia.member, "value")) return;
    if (ia.receiver.* != .identifier or ia.receiver.identifier.kind != .ident) return;
    const entry = ia.receiver.identifier.kind.ident;
    const ty = (env.lookup(entry) orelse return).deref();
    if (ty.* != .named or !std.mem.eql(u8, ty.named.name, "Declared") or ty.named.args.len != 1) return;
    const b = ty.named.args[0].deref();
    if (b.* != .named) return;
    const decl = env.behaviorDecl(b.named.name) orelse return;
    for (decl.methods) |m| if (std.mem.eql(u8, m.name, call.callee)) break else return;
    const msg = try std.fmt.allocPrint(env.arena, "`{s}.value.{s}()` calls `{s}`'s `{s}` on a catalogue entry, which is legal only inside a function expanded at its call site", .{ entry, call.callee, b.named.name, call.callee });
    env.lastError = TypeError.custom(msg, "An entry's `value` is the type seen through the behavior: call its functions in a function whose every parameter is `comptime` (decision 562), where each entry is a concrete type and the call is emitted direct (decision 564).").withLoc(loc);
    return error.TypeError;
}

/// Decision 525 — a trailing lambda is a call argument (`ast.lowerTrailingLambdas`);
/// null when the call has none to lower.
fn lowerTrailingLambdas(env: *Env, c: ast.CallExprOf(.untyped)) InferError!?ast.CallExprOf(.untyped) {
    if (c.kind != .call) return null;
    var out = c;
    if (!try ast.lowerTrailingLambdas(env.arena, &out.kind.call)) return null;
    return out;
}

/// `inferCallExpr` with the receiver already typed — the variadic packing
/// (decision 267) re-enters with the packed call, and the receiver is not
/// inferred twice.
fn inferCallExprWith(env: *Env, c: ast.CallExprOf(.untyped), loc: ast.Loc, typedReceiverIn: ?*ast.TypedExpr) InferError!TypedExpr {
    if (try lowerTrailingLambdas(env, c)) |lowered| return inferCallExprWith(env, lowered, loc, typedReceiverIn);
    // The type the position expects of the call (`val t: Sort<Book> = …`),
    // read before the receiver and the arguments set their own.
    const callExpected = env.expectedType;
    // Only the constructor reads it; its receiver and arguments never inherit it.
    if (isUnappliedGenericCtorCall(env, c)) env.expectedType = null;
    // R12 (§2) — manual `Result.Ok(...)` / `Result.Error(...)` construction
    // anywhere inside a `#[@result]` body is forbidden by the auto-wrap
    // contract: the @Result type is opaque inside the body and is constructed
    // by `return` / `throw` ALONE. Direct `return Result.Ok(...)` / `throw
    // Result.Error(...)` forms are caught at the jump site with the dedicated
    // R11 / `throw-must-be-bare-E` diagnostics; anything else reaching here is
    // a let-binding, an argument, a nested expression, etc.
    if (env.throwContext == .result) {
        if (resultVariantCallName(.{ .call = c })) |_| {
            env.lastError = TypeError.custom(
                diagnostics.result_manual_construction_forbidden ++
                    ": in a body whose return carries a `Result`, the variants are constructed by `return` / `throw` alone.",
                "Replace the manual `Result.Ok(...)` / `Result.Error(...)` with the implicit form (`return <r>;` / `throw <e>;`), or move the construction outside this body.",
            ).withLoc(loc);
            return error.TypeError;
        }
    }
    // STD-001 (decision 518 (4)) — a call of a std function that reaches a
    // host declaration with no binding for the target is refused here, at
    // the call; the import never is.
    if (c.kind == .call) if (stdCallee(env, c)) |sf| try recordStdCall(env, sf.module, sf.name, loc);
    return switch (c.kind) {
        .call => |call| {
            // Decision 370 (2) — `decl.addMember(name, fn…)` in a decorator's
            // body: the member function is the program's code.
            if (currentDeclParam(env)) |declName| if (call.args.len == 2 and memberFn.isAddMemberOn(call, declName)) {
                return inferMemberFnCall(env, call, loc);
            };
            // Decision 575 (3) — `compiler.init(f)` in a decorator's body:
            // the executor is the program's code.
            if (currentDeclParam(env)) |declName| if (memberFn.isCompileOn(call, declName)) {
                return inferCompileCall(env, call, loc);
            };
            // Decision 298 — `decl.setMeta(v)` / `decl.addMeta(v)` in a
            // decorator's body: a typed meta value.
            if (currentDeclParam(env)) |declName| if (isTypedMetaOn(call, declName)) {
                return inferTypedMetaCall(env, call, loc);
            };
            // Decision 298 — `@typeInfo(X).meta(T)` / `.metaAll(T)`.
            if (!call.is_builtin and call.calleeExpr == null and (std.mem.eql(u8, call.callee, "meta") or std.mem.eql(u8, call.callee, "metaAll"))) {
                if (call.receiver) |r| if (r.* == .call and r.call.kind == .call and r.call.kind.call.is_builtin and std.mem.eql(u8, r.call.kind.call.callee, "typeInfo")) {
                    return inferTypedMetaRead(env, call, loc);
                };
            }
            // Decision 330 — `recv?.[i]`, `f?.(args)`, `recv?.m(args)` and
            // `x!`: each is the `if` over the optional it reads, recorded for
            // the transform (`inferOptionalOperator`).
            if (call.optional or (call.is_builtin and std.mem.eql(u8, call.callee, ast.non_null_builtin_name))) {
                return inferOptionalOperator(env, call, loc);
            }
            // Front 15 handover — `.Circle(radius: 1)`: the parser chains the
            // call onto a `.dotIdent` head, so the callee arrives as an
            // expression with `callee == ""`. It is the variant constructor
            // the leading dot names: `Shape.Circle(…)` when the expected type
            // is an enum declaring that variant, and a located refusal when
            // nothing says which type (decision 67 — no guess). The
            // rewrite is recorded like `xs[k]`'s, so no backend learns a shape.
            if (call.calleeExpr) |ce| {
                if (ce.* == .identifier and ce.identifier.kind == .dotIdent) {
                    const name = ce.identifier.kind.dotIdent;
                    var direct = c;
                    direct.kind.call.calleeExpr = null;
                    direct.kind.call.callee = name;
                    const en = expectedEnumDeclaring(env, name) orelse {
                        const msg = try std.fmt.allocPrint(
                            env.arena,
                            "`.{s}(…)` names a variant by its leading dot, and nothing here says which type declares it",
                            .{name},
                        );
                        const hint = try std.fmt.allocPrint(
                            env.arena,
                            "give the position a type that declares `{s}` (`val v: T = .{s}(…);`, a typed parameter or array), or write `T.{s}(…)`",
                            .{ name, name, name },
                        );
                        env.lastError = TypeError.custom(msg, hint).withLoc(ce.identifier.loc);
                        return error.TypeError;
                    };
                    env.expectedType = null;
                    const recv = try env.arena.create(ast.Expr);
                    recv.* = .{ .identifier = .{ .loc = ce.identifier.loc, .kind = .{ .ident = en } } };
                    direct.kind.call.receiver = recv;
                    // The backends read the untyped program: the transform
                    // splices the named call in, through the index channel.
                    const spliced = try env.arena.create(ast.Expr);
                    spliced.* = .{ .call = direct };
                    spliced.call.loc = loc;
                    try env.indexRewrites.put(loc, spliced);
                    return inferCallExpr(env, direct, loc);
                }
            }
            // Decision 329 — a namespace type has no value: `Type()` is
            // refused at the call, naming what the type is.
            if (call.receiver == null and call.calleeExpr == null and !call.is_builtin and
                env.namespaceTypes.contains(call.callee))
            {
                const msg = try std.fmt.allocPrint(
                    env.arena,
                    "{s}: `{s}` is a namespace type — it has no field list and no value, so `{s}()` constructs nothing",
                    .{ diagnostics.namespace_type_construction, call.callee, call.callee },
                );
                const hint = try std.fmt.allocPrint(
                    env.arena,
                    "Call one of its functions through it (`{s}.f(…)`); a type with values writes its field list (`type {s}()`).",
                    .{ call.callee, call.callee },
                );
                env.lastError = TypeError.custom(msg, hint).withLoc(loc);
                return error.TypeError;
            }
            // Decision 529 (2) — a callee with a record parameter `..props: R`
            // takes its fields by label or by a spread: gathered into the
            // record argument before anything else reads the arguments.
            if (recordParamCalleeParams(env, call)) |rps| {
                const packedCall = try packRecordParamCall(env, c, rps, loc);
                return inferCallExprWith(env, packedCall, loc, typedReceiverIn);
            }
            // Decision 359 — a record spread (`Pessoa(..old, nome: n)`):
            // the complete constructor call it means, or `call-spread` at a
            // call that constructs no record.
            // A call with a receiver waits for the receiver's type: a method or an
            // associated function with a record parameter packs the spread
            // (decision 864 (5)); any other refuses it below.
            for (call.args) |a| if (a.label) |l| if (std.mem.eql(u8, l, ast.record_spread_label) and call.receiver == null) {
                // A variadic callee refuses the spread by its own rule (267).
                if (call.receiver == null and !call.variadicPacked and !call.is_builtin and call.calleeExpr == null) {
                    if (variadicCalleeParams(env, call, null)) |vps| _ = try packVariadicCall(env, c, vps, loc); // always refuses: the spread
                }
                return inferRecordSpread(env, c, loc);
            };
            // Decision 110 — `D.empty()` for `import {Dict as D}` is
            // `Dict.empty()`: the receiver is renamed before anything reads
            // it, so every path below resolves the declared type and no
            // backend sees `D`.
            if (call.receiver) |re| if (try importedTypeAliasReceiver(env, re)) |recv| {
                var direct = c;
                direct.kind.call.receiver = recv;
                return inferCallExpr(env, direct, loc);
            };
            // Decision 332 — `bigint.of(n)` / `bigint.parse(text)`: an
            // associated function of the primitive, declared in
            // `primitives.bp`'s `behavior BigInt`.
            if (call.receiver) |re| if (!call.is_builtin and call.calleeExpr == null and primitiveStaticReceiver(env, re.*) != null) {
                return inferPrimitiveStaticCall(env, call, re, loc);
            };
            // 01 step 12 — a section path whose leaf is a payload variant
            // (`.Color.Hex("#abc")`, `Token.Color.Hex("#abc")`).
            if (call.receiver) |re| {
                if (try tryResolveSectionPayloadCall(env, c, re, loc)) |te| return te;
            }
            // C-02 (decision 63, amended 2026-09-19) — `xs[k]` IS `xs.at(k)`.
            // First of all, and before the arguments are inferred: the index
            // has no typing rule of its own, so there is nothing here to type
            // until it has become the method call it is.
            if (call.is_builtin and std.mem.eql(u8, call.callee, ast.index_builtin_name)) {
                return inferIndexExpr(env, call, loc);
            }
            // `@src()` (1.0.10-beta decision 73) — before the arguments are
            // inferred, so `@src(x)` reports the builtin's rule and not `x`.
            if (call.is_builtin and std.mem.eql(u8, call.callee, "typeInfo.all")) {
                // Decision 253 — the catalogue is a static method of the
                // builtin type `TypeInfo`, not a member of the function.
                env.lastError = TypeError.custom(
                    diagnostics.typeinfo_all_on_function ++ ": `@typeInfo.all` is spelled `@TypeInfo.all` — the catalogue is a static method of the type `TypeInfo`",
                    "`@typeInfo(X)` reflects one declaration; `@TypeInfo.all(with: d)` answers every declaration carrying `d`.",
                ).withLoc(loc);
                return error.TypeError;
            }
            if (call.is_builtin and std.mem.eql(u8, call.callee, "TypeInfo.all")) {
                // Decision 268 — the arguments are held to the declaration
                // (`with: Decorator | Decorator[]`) like any builtin's: a
                // `with:` that names no decorator is the ordinary mismatch at
                // the argument. `typeinfo_all.plan` answered no such query.
                // Decision 551 — the query a call leaving a catalogue default
                // out is given carries the key of the default's resolution,
                // no argument of the source's.
                if (typeinfoAll.defaultKeyOf(call.args) == null) try checkCatalogueArguments(env, call, loc);
                // Decision 216 (4) — the answer `typeinfo_all.plan` built for
                // this call; tooling that runs no decorator reads an empty one.
                const answer = env.typeinfoAll.get(loc) orelse empty: {
                    const node = try env.arena.create(ast.Expr);
                    node.* = .{ .collection = .{ .loc = loc, .kind = .{ .arrayLit = .{ .elems = &.{} } } } };
                    break :empty node;
                };
                env.usesDeclared = true;
                // Decision 353 — a template body's query keeps its call: it is
                // answered where the template is expanded, and the transform
                // (which splices a rewrite into the shared declaration) would
                // hand every importer this empty stand-in.
                if (!env.inTemplateFn) try env.srcRewrites.put(loc, answer);
                // Decision 254 — the answer is `Declared<unknown>[]`, one
                // fixed type whatever the program declares: every entry's
                // `value` is `unknown`, and a use narrows it with `is`.
                // Decision 564 — `Declared<B>[]` when the decorators share
                // the behavior `B` their `@Decl<B>` names.
                return inferCatalogueAnswer(env, answer.*, loc, env.typeinfoAllBehaviors.get(loc));
            }
            if (call.is_builtin and (std.mem.eql(u8, call.callee, "typeinfo") or std.mem.startsWith(u8, call.callee, "typeinfo."))) {
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `@{s}` is spelled `@{s}`", .{ diagnostics.typeinfo_lowercase, call.callee, if (std.mem.eql(u8, call.callee, "typeinfo.all")) "TypeInfo.all" else try std.mem.concat(env.arena, u8, &.{ "typeInfo", call.callee["typeinfo".len..] }) });
                env.lastError = TypeError.custom(msg, "The one reflection builtin is `@typeInfo` — `@typeInfo(X).name`, `@typeInfo(X).meta.<decorator>.<key>`, `@TypeInfo.all(with: d)`, and `@typeInfo(T)` as a value is a `TypeInfo<T>`.").withLoc(loc);
                return error.TypeError;
            }
            if (call.is_builtin and std.mem.eql(u8, call.callee, "src")) {
                return inferSrcBuiltin(env, call, loc);
            }
            if (call.is_builtin and std.mem.eql(u8, call.callee, "embed")) {
                return inferEmbedBuiltin(env, call, loc);
            }
            if (call.is_builtin and std.mem.eql(u8, call.callee, compilerSurface.load_builtin)) {
                return inferLoadBuiltin(env, call, loc);
            }
            // A hand-written `SourceLocation(file: …, …)` needs the record
            // declaration spliced in exactly like the rewrite does.
            if (call.receiver == null and !call.is_builtin and std.mem.eql(u8, call.callee, source_location_type_name)) {
                env.usesSourceLocation = true;
            }
            // A run-time `Source(file: …, line: …, col: …)` (`compiler.Source`,
            // the alias of the prelude's `__Source`) builds the record the
            // same way: its declaration is spliced into the module.
            if (call.receiver == null and !call.is_builtin and callsSourceRecord(env, call.callee)) {
                env.usesSourceRecord = true;
            }
            // Method calls carry a receiver expression — infer it first.
            // Exception: a `"std"` module receiver (`bool.negate(x)`) or the
            // builtin `result` namespace (`result.map(r, f)`) is a namespace,
            // not a value binding — synthesize its typed node instead of
            // looking it up (it would be an unbound variable).
            const typedReceiver: ?*ast.TypedExpr = if (typedReceiverIn) |tr| tr else if (call.receiver) |recvExpr| blk: {
                if (recvExpr.* == .identifier and recvExpr.*.identifier.kind == .ident) {
                    const rn = recvExpr.*.identifier.kind.ident;
                    // An explicit `from "std"` import wins over same-named value
                    // bindings (e.g. the primitive type name `bool`).
                    if (env.stdImports.contains(rn) or
                        env.namespaces.modules.contains(rn))
                    {
                        break :blk try makeTypedPtr(env, TypedExpr{ .identifier = .{
                            .loc = recvExpr.*.identifier.loc,
                            .type_ = try env.namedType("#std_module"),
                            .kind = .{ .ident = rn },
                        } });
                    }
                    // Associated interface fn receiver (`Array.range`): `rn` names an
                    // interface (a type, not a value). Synthesize the receiver
                    // node; the call resolves to the registered `rn.callee` below.
                    if (env.lookup(rn) == null) {
                        const qn = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ rn, call.callee });
                        // 144 B-10 — a payload variant of an enum the module
                        // reaches only through a signature (`.Two("x")` where
                        // a `Mode` is expected, `Mode` never imported): the
                        // enum is a type here, its name bound to no value.
                        const typeOnlyVariant = if (env.lookupTypeDef(rn)) |td| td == .enum_ and env.variantCtors.contains(qn) else false;
                        if (env.lookup(qn) != null or typeOnlyVariant) {
                            break :blk try makeTypedPtr(env, TypedExpr{ .identifier = .{
                                .loc = recvExpr.*.identifier.loc,
                                .type_ = try env.namedType(rn),
                                .kind = .{ .ident = rn },
                            } });
                        }
                    }
                    if (try templateNameReceiver(env, recvExpr.*)) |tr| break :blk tr;
                }
                break :blk try makeTypedPtr(env, try inferExprTyped(env, recvExpr.*));
            } else null;

            // Decisions 311 (3), 415 (1) — `value.method "…"` on a template
            // method of the call site's scope; a method of the receiver's own
            // type of that name is the type's.
            if (typedReceiver) |rp| if (call.receiver != null and !call.is_builtin and call.calleeExpr == null) if (templateMethodNamed(env, call.callee)) |tfn| {
                const own = if (nominalName(rp.getType())) |tn| receiverHasMethod(env, tn, call.callee) else false;
                if (!own and !isStdModuleType(rp.getType())) return inferTemplateMethodCall(env, call, rp, tfn, loc);
                try env.templateMethodDeclined.put(loc, {});
            };
            // Decision 534 — `Dict.bump(key, by)` exists for an integer `V` alone
            // (340): on a `Dict` whose `V` is a concrete type that is not an
            // integer the call is refused, located at the call.
            if (typedReceiver) |rp| if (!call.is_builtin and call.calleeExpr == null and call.args.len == 2 and std.mem.eql(u8, call.callee, "bump") and typeIsDict(rp.getType())) {
                if (keyedValueType(rp.getType())) |vt| {
                    const v = vt.deref();
                    if (v.* != .typeVar and !isIntType(v)) return failAt(
                        env,
                        loc,
                        try std.fmt.allocPrint(env.arena, "`Dict.bump` counts integers alone — the values of this `Dict` are {s}", .{try describeForKeyed(env, v)}),
                        "Declare the `Dict` with integer values, or write the row whole with `insert(key, value)`.",
                    );
                }
            };
            // Decision 519 — `a.text()` on an `Asset`, computed at build.
            if (typedReceiver) |rp| if (!call.is_builtin and call.calleeExpr == null and std.mem.eql(u8, call.callee, "text") and isAssetType(rp.getType())) {
                return inferAssetText(env, call, rp, loc);
            };
            // Decisions 787, 792 — `m.run()` on a `compiler.Module`.
            if (typedReceiver) |rp| if (!call.is_builtin and call.calleeExpr == null and std.mem.eql(u8, call.callee, "run") and isLoadModuleType(env, rp.getType())) {
                if (try inferModuleRun(env, call, loc)) |typed| return typed;
            };
            // Decision 538 — `a.open()` on an `Asset`: the `File` std's `io.fs`
            // opens over its bytes (`fs.openAsset(a)`).
            if (typedReceiver) |rp| if (!call.is_builtin and call.calleeExpr == null and std.mem.eql(u8, call.callee, "open") and isAssetType(rp.getType())) {
                return inferAssetOpen(env, call, loc);
            };
            // Decision 371 — `d.same(other)` on a `Decorator`.
            if (typedReceiver) |rp| if (!call.is_builtin and call.calleeExpr == null and std.mem.eql(u8, call.callee, "same") and isDecoratorType(rp.getType())) {
                return inferDecoratorSame(env, call, rp, loc);
            };
            // Question s29-b — `m.meta(T)` / `m.metaAll(T)` on a
            // `decl.methods` entry: the typed meta the method's decorators
            // recorded, read at build.
            if (typedReceiver) |rp| if (!call.is_builtin and call.calleeExpr == null and (std.mem.eql(u8, call.callee, "meta") or std.mem.eql(u8, call.callee, "metaAll")) and isReflectedMethodType(rp.getType())) {
                return inferMethodMetaRead(env, call, rp, loc);
            };
            // Decision 302 — `d.meta(T)` / `d.metaAll(T)` on a tag's `@Decl`
            // (`q.annotate`'s answer): what the tag's annotations recorded.
            if (typedReceiver) |rp| if (!call.is_builtin and call.calleeExpr == null and (std.mem.eql(u8, call.callee, "meta") or std.mem.eql(u8, call.callee, "metaAll")) and isDeclHandleType(rp.getType())) {
                return inferTagMetaRead(env, call, rp, loc);
            };
            // Decision 298 — `d.meta(T)` / `d.metaAll(T)` on a catalogue entry.
            if (typedReceiver) |rp| if (!call.is_builtin and call.calleeExpr == null and (std.mem.eql(u8, call.callee, "meta") or std.mem.eql(u8, call.callee, "metaAll")) and isDeclaredType(rp.getType())) {
                return inferDeclaredMetaRead(env, call, rp, loc);
            };
            // Decision 415 (2) — a declaration a template body looked up is
            // read-only: what writes a declaration is refused on it.
            if (typedReceiver) |rp| if (env.inTemplateFn and !call.is_builtin and call.calleeExpr == null and isDeclHandleType(rp.getType()) and isDeclWrite(call.callee)) {
                const own = if (currentDeclParam(env)) |dp| std.mem.eql(u8, typedIdentName(rp.*) orelse "", dp) else false;
                if (!own) {
                    const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` writes a declaration, and a declaration a template looks up is read-only", .{ diagnostics.template_lookup_decl_write, call.callee });
                    env.lastError = TypeError.custom(msg, "`q.lookup(name)` answers the call site's declaration to read — `name`, `kind`, `module`, `fields`, `meta(T)` (decision 415 (2)); a decorator on that declaration records what it carries.").withLoc(loc);
                    return error.TypeError;
                }
            };
            // Decision 298 — a typed meta value is recorded in the decorator's
            // own body, on its `@Decl` parameter (`typed_meta.collect`).
            if (typedReceiver) |rp| if (!call.is_builtin and isDeclHandleType(rp.getType()) and
                (std.mem.eql(u8, call.callee, typedMeta.add_meta) or (std.mem.eql(u8, call.callee, typedMeta.set_meta) and call.args.len == 1)))
            {
                const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}(v)` records typed meta from the decorator's own body, on its `@Decl` parameter", .{ diagnostics.decorator_meta_not_record, call.callee });
                env.lastError = TypeError.custom(msg, "Call `decl.setMeta(v)` / `decl.addMeta(v)` in the decorator itself: the value is read back by its type where the decorator is declared (decision 298).").withLoc(loc);
                return error.TypeError;
            };

            // Decision 267 — a callee whose last parameter is variadic takes
            // the arguments past its fixed ones as one array: the call is
            // typed with them packed into an array literal, and the program's
            // call is replaced by that packed call for the backends.
            if (recordParamMethodParams(env, call, typedReceiver)) |rps| {
                const packedCall = try packRecordParamCall(env, c, rps, loc);
                return inferCallExprWith(env, packedCall, loc, typedReceiver);
            }
            if (call.receiver != null) for (call.args) |a| if (a.label) |l| if (std.mem.eql(u8, l, ast.record_spread_label)) {
                if (!call.variadicPacked and !call.is_builtin and call.calleeExpr == null) {
                    if (variadicCalleeParams(env, call, typedReceiver)) |vps| _ = try packVariadicCall(env, c, vps, loc); // always refuses: the spread
                }
                return inferRecordSpread(env, c, loc);
            };
            if (!call.variadicPacked and !call.is_builtin and call.calleeExpr == null) {
                if (variadicCalleeParams(env, call, typedReceiver)) |vps| {
                    const packedCall = try packVariadicCall(env, c, vps, loc);
                    return inferCallExprWith(env, packedCall, loc, typedReceiver);
                }
            }

            // A builtin-primitive receiver declares its own signature in
            // `primitives.bp`, and the receiver is already inferred here — so a
            // lambda argument can be typed from the receiver's element type
            // BEFORE its body is inferred. Anything else keeps the permissive
            // fresh-var path.
            const primParams: ?[]*T.Type = if (typedReceiver) |rp|
                try primMethodParamTypes(env, rp.getType(), call.callee)
            else
                null;

            // C-04 — the callee's parameters AS WRITTEN, read once here and
            // used twice: 00 · 01-checker's expectation just below, and the
            // default fill the arity arm plans further down.
            // A qualified variant constructor (`Tok.Size(percent: .100)`,
            // row 22) names its variant under `Enum.Variant`; its fields are
            // the parameters an argument is inferred under, as a plain call's.
            const qualifiedCtor: ?[]const u8 = blk: {
                if (call.is_builtin) break :blk null;
                const r = call.receiver orelse break :blk null;
                if (r.* != .identifier or r.identifier.kind != .ident) break :blk null;
                const qn = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ r.identifier.kind.ident, call.callee });
                if (!env.variantCtors.contains(qn)) break :blk null;
                break :blk qn;
            };
            // Decision 587 — `phase.describe(.Slow)` through a module
            // namespace: the exported function's parameters are the
            // expectation, as a leaf import's are.
            const namespaceCallee: ?[]const u8 = blk: {
                if (call.is_builtin or call.calleeExpr != null) break :blk null;
                const r = call.receiver orelse break :blk null;
                if (r.* != .identifier or r.identifier.kind != .ident) break :blk null;
                const ns = r.identifier.kind.ident;
                if (!env.namespaces.modules.contains(ns)) break :blk null;
                break :blk ns;
            };
            // 144 B-120 — `process.onSignal(.Term, h)` through a std module
            // namespace: the std function's parameters are the expectation,
            // as a program module's (above) and a leaf import's are.
            const stdNamespaceKey: ?[]const u8 = blk: {
                if (call.is_builtin or call.calleeExpr != null or namespaceCallee != null) break :blk null;
                const r = call.receiver orelse break :blk null;
                if (r.* != .identifier or r.identifier.kind != .ident) break :blk null;
                const key = env.stdImports.get(r.identifier.kind.ident) orelse break :blk null;
                const exports = env.stdModules.get(key) orelse break :blk null;
                if (!exports.contains(call.callee)) break :blk null;
                break :blk key;
            };
            const declParamsAst: ?[]const ast.Param = if (qualifiedCtor) |qn|
                env.ctorParams.get(qn)
            else if (namespaceCallee) |ns|
                env.namespaces.params.get(try envMod.NamespaceImports.paramsKey(env.arena, ns, call.callee))
            else if (stdNamespaceKey) |key|
                try stdFnParams(env, key, call.callee)
            else
                calleeParams(env, call.callee);
            if (call.receiver == null) if (declParamsAst) |dps| try refuseInlineFieldsAcrossModules(env, call.callee, dps, call.args, loc);

            // 00 · 01-checker — the DECLARED parameter types of a plain call,
            // read only as the expectation an argument is inferred under
            // (`tokenDeclarations(.Color.Red.500)` resolves the path on the
            // parameter's enum). The arm that types the call still unifies
            // each argument with its parameter. The expectation is a fresh
            // instance of the callee's signature, as that arm's is: a lambda
            // under a fallible expectation unifies its return with it
            // (decision 147), and against the registration-time cells of a
            // generic constructor that binds `T` for every later call — in a
            // generic type's own methods, `Schema(…)` answering `Schema<?T>`
            // made the next `Schema(…)` expect `?T` too.
            const declParamTypes: ?[]*T.Type = blk: {
                if (qualifiedCtor) |qn| {
                    const enumName = call.receiver.?.identifier.kind.ident;
                    const inst = try instantiateGenericType(env, try instantiateCtorType(env, enumName, env.variantCtors.get(qn).?));
                    const d = inst.deref();
                    break :blk if (d.* == .func) d.func.params else null;
                }
                if (namespaceCallee) |ns| {
                    const exports = env.namespaces.modules.get(ns) orelse break :blk null;
                    const exported_ = exports.get(call.callee) orelse break :blk null;
                    const exported = if (env.namespaces.paths.get(ns)) |path| try renameImportedType(env, exported_, path) else exported_;
                    var seen = std.AutoHashMap(*T.TypeCell, *T.Type).init(env.arena);
                    defer seen.deinit();
                    const inst = (try instantiateType(env, exported, &seen, .allVars)).deref();
                    // The types its signature names come with it, as types
                    // only (01 R2), as a leaf import's do: `.Slow` resolves
                    // on the parameter's enum though this module imports none.
                    if (env.namespaces.paths.get(ns)) |path| if (env.typeDeclRegistry) |reg| if (reg.get(path)) |decls| {
                        try registerImportedSignatureClosure(env, decls, exported);
                    };
                    break :blk if (inst.* == .func) inst.func.params else null;
                }
                if (stdNamespaceKey) |key| {
                    const exported = env.stdModules.get(key).?.get(call.callee).?;
                    var seen = std.AutoHashMap(*T.TypeCell, *T.Type).init(env.arena);
                    defer seen.deinit();
                    const inst = (try instantiateType(env, exported, &seen, .allVars)).deref();
                    break :blk if (inst.* == .func) inst.func.params else null;
                }
                if (call.receiver != null or call.is_builtin) break :blk null;
                const calleeTy = env.lookup(call.callee) orelse break :blk null;
                if (calleeTy.deref().* != .func) break :blk null;
                const d = (try instantiateGenericType(env, try instantiateCtorType(env, call.callee, calleeTy))).deref();
                // A constructor's written type arguments (`Sort<Book>(by:
                // .pages)`) pin its parameters before the arguments are read,
                // so a field key resolves against `Book` (decision 308);
                // `applyExplicitTypeArgs` checks their count after.
                if (call.typeArgs) |written| if (env.lookupTypeDef(call.callee)) |td| {
                    const ret = d.func.ret.deref();
                    if (td.genericParams().len == written.len and ret.* == .named and ret.named.args.len == written.len) {
                        for (written, ret.named.args) |w, a| try unifyAt(env, try resolveTypeRef(env, w), a, c.loc);
                    }
                };
                // The position's written type pins them alike when the call
                // writes none (`val t: Sort<Book> = Sort(by: .title)` is
                // `Sort<Book>(by: .title)`): the annotation names the type
                // the constructor answers.
                if (call.typeArgs == null) if (callExpected) |want| if (env.lookupTypeDef(call.callee)) |td| {
                    const ret = d.func.ret.deref();
                    const w = want.deref();
                    if (td.genericParams().len > 0 and ret.* == .named and w.* == .named and
                        std.mem.eql(u8, ret.named.name, w.named.name) and ret.named.args.len == w.named.args.len)
                    {
                        for (w.named.args, ret.named.args) |wa, a| try unifyAt(env, wa, a, c.loc);
                    }
                };
                break :blk d.func.params;
            };
            // Which parameter each argument lands in. Null is the ordinary
            // answer — argument `i` is parameter `i` — and a slice appears
            // only when a label moved one (C-04).
            const argParamIndex: ?[]const usize = if (declParamTypes != null)
                if (declParamsAst) |ps| try argumentParamSlots(env, ps, call.args) else null
            else
                null;

            const typedArgs = try env.arena.alloc(ast.CallArgOf(.typed), call.args.len);
            // Decision 297 — the argument a type was written for, if any.
            var typeArgAt: ?usize = null;
            // Decisions 668, 757, 758 — the arguments that write a type where
            // a `type<T>` parameter takes it, typed as the type.
            const tokCallee = tokenCallee(env, call, typedReceiver);
            var tokenTyped: []bool = &.{};
            if (tokCallee != null) {
                tokenTyped = try env.arena.alloc(bool, call.args.len);
                @memset(tokenTyped, false);
            }
            for (call.args, 0..) |arg, i| {
                if (tokCallee) |tc| if (arg.label == null) {
                    const pi = if (call.receiver == null) (if (argParamIndex) |slots| (if (i < slots.len) slots[i] else tc.params.len) else i) else i;
                    if (try typeTokenArgType(env, tc, pi, arg.value.*)) |ty| {
                        typedArgs[i] = .{ .label = arg.label, .value = try makeTypedPtr(env, TypedExpr{ .identifier = .{ .loc = arg.value.identifier.loc, .type_ = ty, .kind = .{ .ident = arg.value.identifier.kind.ident } } }) };
                        tokenTyped[i] = true;
                        continue;
                    }
                };
                if (call.receiver == null and !call.is_builtin and call.calleeExpr == null) if (declParamsAst) |dps| {
                    const pi = if (argParamIndex) |slots| (if (i < slots.len) slots[i] else dps.len) else i;
                    if (pi < dps.len) {
                        if (dps[pi].typeArgOf) |tp| if (typeArgName(env, arg.value.*)) |tn| {
                            typedArgs[i] = .{ .label = arg.label, .value = try makeTypedPtr(env, try typeArgument(env, dps[pi], tp, tn, arg.value.*)) };
                            typeArgAt = i;
                            continue;
                        };
                        try refuseRuntimeComptimeArg(env, dps[pi], arg.value.*);
                    }
                };
                // Only the declared PARAMETER types are pushed down
                // (`params_only`). The declared RETURN is not a constraint the
                // lambda has to meet here — `Array.forEach`'s `action` is
                // declared `fn(item: T)`, and every `xs.forEach({ p -> <value> })`
                // in `libs/std` would red against its `void` — and the call's
                // own type is `primMethodReturnTypeFromIface`'s answer anyway.
                // Ground only: every parameter of the declared fn-typed param
                // must mention no type variable (`typeIsGround`). An element
                // type still unresolved tells the lambda nothing, and unifying
                // against it adds edges the method never meant.
                const expected: ?*T.Type = if (primParams) |ps| blk: {
                    if (i >= ps.len) break :blk null;
                    const d = ps[i].deref();
                    if (d.* != .func) break :blk null;
                    for (d.func.params) |fp| if (!typeIsGround(fp, 0)) break :blk null;
                    break :blk ps[i];
                } else null;
                const argExpected: ?*T.Type = if (declParamTypes) |ps| blk: {
                    const pi = if (argParamIndex) |slots|
                        (if (i < slots.len) slots[i] else ps.len)
                    else
                        i;
                    if (pi >= ps.len) break :blk null;
                    break :blk ps[pi];
                } else if (i == 0 and isDeclImplementCall(typedReceiver, call.callee))
                    // Decision 587 — `compiler.implement(.Erlang(…))`: the
                    // parameter's type, `Implementation`, names the variant
                    // a leading dot writes.
                    try env.namedType("Implementation")
                else if (i == 0) unwrapOrDefaultExpected(typedReceiver, call.callee) else null;
                // Decision 148 — a `forEach` body may write a captured `var`.
                if (arg.value.* == .function and typedReceiver != null and std.mem.eql(u8, call.callee, "forEach") and (isArrayType(typedReceiver.?.getType()) or typedReceiver.?.getType().deref().* == .typeVar))
                    env.nextLambdaExempt = true;
                // An untyped lambda handed to a parameter whose function type
                // is ground takes its parameter types from it before its body
                // is read, as a primitive method's does: `{ a -> a?.length() }`
                // for `fn(h: ?Holder[]) -> i32` read `a?.length()` over a type
                // variable, and commonJS called the property.
                const groundFnExpected: ?*T.Type = if (expected == null and arg.value.* == .function) blk: {
                    const w = argExpected orelse break :blk null;
                    const d = w.deref();
                    if (d.* != .func or d.func.params.len != arg.value.function.kind.params.len) break :blk null;
                    for (d.func.params) |fp| if (!typeIsGround(fp, 0)) break :blk null;
                    break :blk w;
                } else null;
                const val = if (expected != null and arg.value.* == .function)
                    try inferFunctionExprExpected(env, arg.value.*.function, arg.value.*.function.loc, expected.?, true)
                else if (groundFnExpected) |w|
                    try inferFunctionExprExpected(env, arg.value.*.function, arg.value.*.function.loc, w, true)
                else
                    try inferExprTypedExpecting(env, arg.value.*, argExpected);
                env.nextLambdaExempt = false;
                typedArgs[i] = .{ .label = arg.label, .value = try makeTypedPtr(env, val) };
            }
            if (typeArgAt) |ti| try noteTypeArgCall(env, c, ti, loc);
            if (call.receiver == null and !call.is_builtin and call.calleeExpr == null) try noteEmbedCall(env, call, declParamsAst, argParamIndex, loc);
            const typedTrailing = try inferTrailingLambdasTyped(env, call.trailing);

            // 01 handover 15 — `adder(3)(4)`: what is called is the result of
            // the previous call, carried in `calleeExpr` with `callee == ""`.
            // Type that expression and apply it: it must be a function taking
            // the written arguments (trailing lambdas after them), and the
            // call's type is its return.
            if (call.calleeExpr) |ce| {
                const calleeTyped = try inferExprTyped(env, ce.*);
                const argTypes = try env.arena.alloc(*T.Type, typedArgs.len + typedTrailing.len);
                for (typedArgs, 0..) |a, i| argTypes[i] = a.value.getType();
                for (typedTrailing, 0..) |_, i| argTypes[typedArgs.len + i] = try env.freshVar();
                const ret = try env.freshVar();
                const expectedFn = try env.funcType(argTypes, ret);
                const got = calleeTyped.getType().deref();
                if (got.* == .func and got.func.params.len != argTypes.len) {
                    env.lastError = TypeError.arityMismatch("the called value", got.func.params.len, argTypes.len).withLoc(loc);
                    return error.TypeError;
                }
                try unifyAt(env, got, expectedFn, loc);
                return TypedExpr{ .call = .{ .loc = loc, .type_ = ret, .kind = .{ .call = .{
                    .receiver = null,
                    .callee = call.callee,
                    .is_builtin = false,
                    .args = typedArgs,
                    .trailing = typedTrailing,
                    .calleeExpr = try makeTypedPtr(env, calleeTyped),
                } } } };
            }

            if (call.is_builtin) {
                // Decision 354 — `@getContext(T)` (269) left: a context is a
                // `Context<T>` object read with `use context(…)`.
                if (std.mem.eql(u8, call.callee, "getContext")) {
                    env.lastError = TypeError.custom(
                        diagnostics.unknown_builtin ++ ": unknown builtin `@getContext` — a context is read through a context value with `use context(ctx)` (decisions 354, 722)",
                        "Declare the type's default (`pub val themeContext = comptime createContext(Theme(…));`), provide another above (`use provide(createContext(theme));`) and read it with `val t = use context(themeContext);`.",
                    ).withLoc(loc);
                    return error.TypeError;
                }
                // Decision 8 §4 — `x is T`. The parser lands it as the `is`
                // builtin with the tested type in the call's `isType` slot;
                // nothing typed it, so `inferBuiltinCallReturnType` had no arm
                // for the name and the call came out `void`.
                if (std.mem.eql(u8, call.callee, ast.is_builtin_name)) {
                    // Decision 322 — `is` is only an operator. The parser's carrier
                    // of `x is T` always sets `isType`; a call without it is a
                    // hand-written `@is(…)`, and `primitives.bp`'s compiler section declares no `is`.
                    if (call.isType == null) {
                        env.lastError = TypeError.custom(
                            diagnostics.unknown_builtin ++ ": unknown builtin `@is` — `is` is an operator",
                            "Test a type with the operator: `x is T`.",
                        ).withLoc(loc);
                        return error.TypeError;
                    }
                    if (call.isType) |tested| if (tested == .typeparam) {
                        // Decisions 297, 736 — `x is type<T>` (or the bare
                        // `x is type`) is folded where `x` is a `comptime x: V |
                        // type<T>` parameter (`value_or_type.zig`); anything
                        // else reaching here tests nothing.
                        env.lastError = TypeError.custom(
                            diagnostics.is_type_outside_value_or_type ++ ": `is type` tests a `comptime` parameter that takes a value or a type (`comptime x: V | type<T>`)",
                            "Declare the parameter `comptime x: V | type<T>`, or test a type with `x is T`.",
                        ).withLoc(loc);
                        return error.TypeError;
                    };
                    // Decision 757 — `v is t`, `t` a `comptime t: type<T>`
                    // parameter: the function is specialised per type
                    // argument (`type_token.zig`), so in each copy the test
                    // is the concrete type's; here it narrows `v` to `T`.
                    // Decision 758 — `x is t`, `t` a run-time `t: type<T>`:
                    // the run-time test over the value and the token
                    // (`type_token.zig` writes it `__bp_is_type(x, t)`).
                    const runtimeRef = runtimeTokenRef(env, call.isType.?);
                    if (runtimeRef != null) try env.runtimeTokenTests.put(env.arena, loc, {});
                    const tokenRef = typeTokenRef(env, call.isType.?) orelse runtimeRef;
                    // Decision 667 — `v is T` on a bare type parameter.
                    if (tokenRef == null) try refuseIsTypeParameter(env, call.isType.?, loc);
                    // Decision 810 (1) — `v is X<T>` with `X<T>` a member of
                    // `v`'s static type: its arguments come from `v`'s type,
                    // so the run-time test is `X`'s identity alone, as
                    // `v is X<unknown>` is; the backends get that form.
                    const boundIdentity: ?ast.TypeRef = if (tokenRef == null and typedArgs.len == 1)
                        try boundTypeTestIdentity(env, typedArgs[0].value.getType(), call.isType.?, loc)
                    else
                        null;
                    if (boundIdentity == null) if (tokenRef orelse call.isType) |tested| {
                        // Decision 332 (question 139-a) — no run-time test
                        // tells a `bigint` from another integer: `is` neither
                        // tests for one nor tests one.
                        if (typeRefMentionsBigint(tested) or (typedArgs.len == 1 and unifyMod.mentionsBigint(typedArgs[0].value.getType()))) {
                            env.lastError = TypeError.custom(
                                diagnostics.bigint_type_test ++ ": `is` does not test a `bigint`",
                                "A `bigint`'s type is static (decision 332): a value typed `bigint` is one, and nothing else is.",
                            ).withLoc(loc);
                            return error.TypeError;
                        }
                        // Decision 346 — nor `bytes`, which erlang and beam
                        // hold as a `string` is held (a binary).
                        if (typeRefMentions(tested, "bytes") or (typedArgs.len == 1 and unifyMod.mentionsBytes(typedArgs[0].value.getType()))) {
                            env.lastError = TypeError.custom(
                                diagnostics.bytes_type_test ++ ": `is` does not test `bytes`",
                                "`bytes`' type is static (decision 346): a value typed `bytes` is one, and nothing else is.",
                            ).withLoc(loc);
                            return error.TypeError;
                        }
                        try refuseUnboundTypeArgument(env, tested, loc);
                        try checkIsTestableType(env, tested, loc);
                        if (typedArgs.len == 1) try warnAlwaysFalseIs(env, typedArgs[0].value.getType(), tested, loc);
                    };
                    // Decision 810 (1) — a behavior tested: its identity,
                    // written into the program by `type_token.apply`.
                    if (tokenRef == null) {
                        const lowered = try behaviorTestRef(env, boundIdentity orelse call.isType.?);
                        if (ast.behaviorTestName(lowered) != null) try env.behaviorTests.put(env.arena, loc, lowered.named);
                    }
                    return TypedExpr{
                        .call = .{
                            .loc = loc,
                            .type_ = try env.namedType("bool"),
                            .kind = .{
                                .call = .{
                                    .receiver = null,
                                    .callee = call.callee,
                                    .is_builtin = true,
                                    .args = typedArgs,
                                    .trailing = typedTrailing,
                                    // The tested type is what the backends lower the run-time
                                    // test from; dropping it here left them nothing to read.
                                    .isType = boundIdentity orelse tokenRef orelse call.isType,
                                },
                            },
                        },
                    };
                }
                // `@makeRecord(fields)` — when fields is a literal array of RecordField
                // values, evaluate at inference time and create a synthetic record type.
                if (std.mem.eql(u8, call.callee, "makeRecord") and call.args.len >= 1) {
                    if (try tryEvalMakeRecord(env, call.args[0].value.*, loc)) |result| {
                        return result;
                    }
                }
                const retType = try inferBuiltinCallReturnType(env, call.callee, typedArgs, typedTrailing, loc);
                // 144 B-78 — each argument `@print` writes is written as text.
                if (call.is_builtin and isPrintBuiltin(call.callee)) for (typedArgs) |a| {
                    try noteTextValue(env, a.value.getLoc(), a.value.getType());
                };
                return TypedExpr{ .call = .{ .loc = loc, .type_ = retType, .kind = .{ .call = .{
                    .receiver = null,
                    .callee = call.callee,
                    .is_builtin = call.is_builtin,
                    .args = typedArgs,
                    .trailing = typedTrailing,
                } } } };
            }
            if (call.receiver) |recvExpr| {
                if (recvExpr.* == .identifier and recvExpr.*.identifier.kind == .ident) {
                    const recvName = recvExpr.*.identifier.kind.ident;
                    // Associated interface fn (`Array.range(0, n)`, `Array.repeat(x, n)`):
                    // `recvName.callee` is registered by
                    // `registerInterfaceAssociatedFns`. Each call instantiates fresh
                    // generics. Guarded by `lookup(recvName) == null` so value
                    // bindings of the same name keep their normal method dispatch.
                    //
                    // 01 R6 — a behavior's own name is bound too (std's `Array`
                    // is a function-typed binding), and that binding is not a
                    // value that shadows the behavior: without this the
                    // associated call (`Array.range(0, 3)`) fell through to a
                    // fresh var, and the method on its result (`.map`) recorded
                    // no lowering — erlang's `'__bp_prim_map'` run-time helper.
                    // Decision 641 — a primitive's table is named like its
                    // type (`array.range`); a local of that name shadows it.
                    const shadowedTable = preludeCache.isMemberTable(recvName) and env.boundInBody(recvName);
                    const behaviorName = env.assocInterfaceDecls.contains(recvName) and !env.isVal(recvName) and !shadowedTable;
                    if (env.lookup(recvName) == null or behaviorName) {
                        const qn = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ recvName, call.callee });
                        if (env.lookup(qn)) |fnTy| {
                            return try inferAssociatedFnCall(env, recvName, call.callee, fnTy, typedReceiver, typedArgs, typedTrailing, loc);
                        }
                    }
                    // Decision 62 — a type's own associated fn, called through the
                    // type (`Counter.zero()`). Its result reached here as a fresh
                    // var, so `val c = Counter.zero(); c.bump()` recorded no
                    // `instanceLowerings` entry for `bump`: beam answered
                    // `{unresolved_method, bump, 1}` and wasm trapped, while
                    // commonJS and erlang happened to be right because neither
                    // needs the type. The signature is already registered by
                    // `registerInherentMethodTypes` (with `Self` resolved to the
                    // type) — it was simply never read for the type-qualified form.
                    if (env.lookupTypeDef(recvName) != null) {
                        if (try associatedCallReturnType(env, recvName, call.callee, typedArgs, typedTrailing, loc)) |ret| {
                            return TypedExpr{ .call = .{ .loc = loc, .type_ = ret, .kind = .{ .call = .{
                                .receiver = typedReceiver,
                                .callee = call.callee,
                                .is_builtin = false,
                                .args = typedArgs,
                                .trailing = typedTrailing,
                            } } } };
                        }
                    }
                    // Decision 216 — a record-shaped type's members are closed: a
                    // call through the type names one it declares (by hand or
                    // through a decorator's `decl.addMember`), or one of the
                    // behaviors it implements. `City.revisionsOf(…)` on an entity
                    // without `#[revisions]` used to compile.
                    if (env.lookupTypeDef(recvName)) |td| if (td == .record and
                        !env.hasInherentMethod(recvName, call.callee) and
                        !typeAnswersMember(env, td, call.callee))
                    {
                        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` has no associated fn `{s}`", .{ diagnostics.unknown_associated_fn, recvName, call.callee });
                        env.lastError = TypeError.custom(msg, "Call a fn the type declares in its body, or one a decorator on it adds with `decl.addMember`.").withLoc(loc);
                        return error.TypeError;
                    };
                }
            }

            // `"std"` package qualified call (F2a): `bool.negate(x)` where
            // `bool` was imported via `import {bool} from "std"`. The explicit
            // import wins over same-named value bindings (e.g. the primitive
            // type name `bool`). The callee resolves in the module's exports
            // table; the fn type is instantiated per call site.
            if (call.receiver) |recvExpr| {
                if (recvExpr.* == .identifier and recvExpr.*.identifier.kind == .ident) {
                    const recvName = recvExpr.*.identifier.kind.ident;
                    if (env.stdImports.get(recvName)) |std_key| {
                        if (env.stdModules.get(std_key)) |exports| {
                            const exported = exports.get(call.callee) orelse {
                                var e = TypeError.custom(
                                    "this \"std\" module has no such public function",
                                    "Check the function name against the module's exports.",
                                );
                                e = e.withLoc(loc);
                                env.lastError = e;
                                return error.TypeError;
                            };
                            try refuseShadowedStdSignature(env, recvName, std_key, call.callee, exported, loc);
                            var seen = std.AutoHashMap(*T.TypeCell, *T.Type).init(env.arena);
                            defer seen.deinit();
                            const instantiated = try instantiateType(env, exported, &seen, .allVars);
                            const retType: *T.Type = switch (instantiated.deref().*) {
                                .func => |f| blk: {
                                    // 01 / C-04 — by label, and short calls
                                    // filled, against the std fn as written.
                                    const declared = try stdFnParams(env, std_key, call.callee);
                                    if (try planQualifiedCall(env, call.callee, declared, f.params, typedArgs, typedTrailing.len, loc) != null) break :blk f.ret;
                                    const total = typedArgs.len + typedTrailing.len;
                                    if (f.params.len != total) {
                                        env.lastError = TypeError.arityMismatch(call.callee, f.params.len, total).withLoc(loc);
                                        return error.TypeError;
                                    }
                                    for (typedArgs, f.params[0..typedArgs.len]) |ta, p| {
                                        try unifyAt(env, p, ta.value.getType(), ta.value.getLoc());
                                    }
                                    break :blk f.ret;
                                },
                                else => try env.freshVar(),
                            };
                            return TypedExpr{ .call = .{ .loc = loc, .type_ = retType, .kind = .{ .call = .{
                                .receiver = typedReceiver,
                                .callee = call.callee,
                                .is_builtin = false,
                                .args = typedArgs,
                                .trailing = typedTrailing,
                            } } } };
                        }
                    }
                }
            }

            // Decision 107's namespace form over a module of the program
            // (`import {jwt} from "sec"`; `jwt.sign(x)`): the call resolves in
            // the module's exports and is recorded for the transform, which
            // writes it as a call of an aliased import every backend lowers.
            if (call.receiver) |recvExpr| {
                if (recvExpr.* == .identifier and recvExpr.*.identifier.kind == .ident) {
                    const ns = recvExpr.*.identifier.kind.ident;
                    // An explicit import wins over a same-named prelude
                    // binding, as a `from "std"` one does.
                    if (env.namespaces.modules.get(ns)) |exports| {
                        const exported_ = exports.get(call.callee) orelse {
                            const msg = try std.fmt.allocPrint(env.arena, "module `{s}` has no public `{s}`", .{ ns, call.callee });
                            env.lastError = TypeError.custom(msg, "Check the name against the module's `pub` declarations.").withLoc(loc);
                            return error.TypeError;
                        };
                        // Decision 310 — its signature names a type this
                        // module holds under an alias.
                        const exported = if (env.namespaces.paths.get(ns)) |path| try renameImportedType(env, exported_, path) else exported_;
                        var seen = std.AutoHashMap(*T.TypeCell, *T.Type).init(env.arena);
                        defer seen.deinit();
                        const instantiated = try instantiateType(env, exported, &seen, .allVars);
                        const f = switch (instantiated.deref().*) {
                            .func => |f| f,
                            else => {
                                const msg = try std.fmt.allocPrint(env.arena, "`{s}.{s}` is not a function", .{ ns, call.callee });
                                env.lastError = TypeError.custom(msg, "Only a function is called through a module namespace; import the name itself for anything else.").withLoc(loc);
                                return error.TypeError;
                            },
                        };
                        // Decision 719 — `ns.f(…)` of a function with a `syntax`
                        // expression parameter expands at its call as `f(…)` does.
                        if (env.templateFns.get(try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ ns, call.callee }))) |tfn| {
                            return expandQualifiedSyntaxCall(env, ns, tfn, call, f.params, f.ret, typedArgs, typedTrailing.len, loc);
                        }
                        const total = typedArgs.len + typedTrailing.len;
                        // The parameters as written travel with the export:
                        // a label names the one it fills (01) and a short call
                        // takes the declared defaults (C-04), as for a leaf
                        // import.
                        const declared = env.namespaces.params.get(try envMod.NamespaceImports.paramsKey(env.arena, ns, call.callee));
                        if (try planQualifiedCall(env, call.callee, declared, f.params, typedArgs, typedTrailing.len, loc) == null) {
                            if (f.params.len != total) {
                                env.lastError = TypeError.arityMismatch(call.callee, f.params.len, total).withLoc(loc);
                                return error.TypeError;
                            }
                            for (typedArgs, f.params[0..typedArgs.len]) |ta, p| {
                                try unifyArgument(env, p, ta.value.getType(), ta.value.getLoc());
                            }
                        }
                        try env.namespaces.calls.put(env.arena, loc, .{ .namespace = ns, .callee = call.callee });
                        return TypedExpr{ .call = .{ .loc = loc, .type_ = f.ret, .kind = .{ .call = .{
                            .receiver = typedReceiver,
                            .callee = call.callee,
                            .is_builtin = false,
                            .args = typedArgs,
                            .trailing = typedTrailing,
                        } } } };
                    }
                }
            }

            // Decision 122 — `seq.next()` called by hand on an `@Iter<T>`
            // answers `YieldStep<T>`, on a `@AsyncIter<T>` `@Async<YieldStep<T>>`.
            // Neither wrapper is a declared type, so no method table answers
            // it: the lowering is recorded per call site for every backend.
            if (typedReceiver) |recvPtr| {
                if (try inferSequenceNext(env, recvPtr, call.callee, typedArgs, typedTrailing, loc)) |te| return te;
                if (try inferHandleName(env, recvPtr, call.callee, typedArgs, loc)) |te| return te;
                // Decision 523 — `map`, `then`, `mapError` and `catch` are
                // withdrawn from a task: its value is read by `await`, and
                // every composition of it is an `async { … }` block.
                const taskRecv = recvPtr.getType().deref();
                if (taskRecv.* == .named and std.mem.eql(u8, taskRecv.named.name, "Async") and
                    (std.mem.eql(u8, call.callee, "map") or std.mem.eql(u8, call.callee, "then") or
                        std.mem.eql(u8, call.callee, "mapError") or std.mem.eql(u8, call.callee, "catch")))
                {
                    var err = TypeError.unknownMethod(try errorMod.typeLabelAlloc(env.arena, taskRecv), call.callee);
                    env.lastError = err.withLoc(loc);
                    return error.TypeError;
                }
            }

            // Static extension dispatch (F6): `obj.method(args)` resolved via
            // inherent methods, activated `implement`/`extend` blocks, or a
            // qualified call `Sym.method(obj)`. Only bare-identifier receivers
            // dispatch this way; a null result falls through to Result/Option
            // builtins and feat's permissive method typing below.
            if (call.receiver) |recvExpr| {
                if (recvExpr.* == .identifier and recvExpr.*.identifier.kind == .ident) {
                    const recvName = recvExpr.*.identifier.kind.ident;
                    if (try resolveReceiverCall(env, recvName, typedReceiver, call.callee, typedArgs, typedTrailing, loc)) |te| {
                        return te;
                    }
                }
            }

            // Stdlib array method dispatch: `xs.method(args)` where `xs: Array<T>`
            // and `method` is defined in the `list` stdlib module. Rewired by the
            // transform to `list.method(xs, args)` — no explicit import needed.
            if (call.receiver) |recvExpr| {
                if (try resolveStdArrayMethod(env, recvExpr, typedReceiver, call.callee, typedArgs, typedTrailing, loc)) |te| {
                    return te;
                }
            }

            if (typedReceiver) |recvPtr| {
                // Qualified constructor / static call: `EnumType.Variant(args)`.
                // The receiver names a type definition, so the callee is a global
                // constructor binding (not a method) — resolve it the same way as
                // a plain call and keep the receiver for codegen (`Color.Rgb(..)`).
                if (call.receiver) |re| {
                    if (re.* == .identifier and re.*.identifier.kind == .ident and
                        env.lookupTypeDef(re.*.identifier.kind.ident) != null)
                    {
                        // 01 step 12 — the qualification the author wrote is
                        // the answer: `Shape.Circle` is Shape's constructor
                        // whatever other enum also declares `Circle`.
                        const qualified = try std.fmt.allocPrint(env.arena, "{s}.{s}", .{ re.*.identifier.kind.ident, call.callee });
                        if (env.variantCtors.get(qualified) orelse env.lookup(call.callee)) |calleeTypeRaw| {
                            // Generic enum variant constructor — instantiate per
                            // call site (the receiver names the type def).
                            const calleeType = try instantiateCtorType(env, re.*.identifier.kind.ident, calleeTypeRaw);
                            const resolved = calleeType.deref();
                            const retType: *T.Type = switch (resolved.*) {
                                .func => |f| blk: {
                                    // 01 — `Shape.Rect(height: 2, width: 5)`: a
                                    // label names the field it fills; the call
                                    // is checked and lowered in declaration
                                    // order (erlang zipped it positionally). A
                                    // field left out takes its default
                                    // (`Implementation.Erlang("…", result:
                                    // true)`, decision 575 (6)): the call is
                                    // planned as a record constructor's is, and
                                    // a label no field declares is refused.
                                    const declared = env.ctorParams.get(qualified);
                                    const plan = if (declared) |d| (if (d.len == f.params.len) try planLabelledCall(env, qualified, d, typedArgs, loc) else null) else null;
                                    if (plan) |p| {
                                        try env.defaultInjections.put(loc, p);
                                        try unifyFilledArgs(env, p, f.params, typedArgs);
                                    } else if (f.params.len == typedArgs.len) {
                                        for (typedArgs, f.params) |ta, p|
                                            try unifyAt(env, p, ta.value.getType(), ta.value.getLoc());
                                    }
                                    break :blk f.ret;
                                },
                                .named => resolved,
                                else => try env.freshVar(),
                            };
                            return TypedExpr{ .call = .{ .loc = loc, .type_ = retType, .kind = .{ .call = .{
                                .receiver = recvPtr,
                                .callee = call.callee,
                                .is_builtin = false,
                                .args = typedArgs,
                                .trailing = typedTrailing,
                            } } } };
                        }
                    }
                }

                // 06 N24 / decision 8 §6 — a tuple element of function type
                // called like a method (`#(value: i32, set: fn(…))`, `c.set(9)`).
                // The label→index rewrite the member-access path records
                // (`row.pop` → `row._1`) never fired for a CALL, so every
                // backend emitted `c.set(9)` on a value that is a tuple —
                // `c.set is not a function` on commonJS.
                if (try inferTupleLabelCall(env, recvPtr, call.receiver, call.callee, typedArgs, typedTrailing, loc)) |dispatched| {
                    return dispatched;
                }

                // Decision 388 (2) — `c.run(scope)` on a component value.
                if (try inferComponentRun(env, recvPtr, call.callee, typedArgs, typedTrailing, loc)) |ran| {
                    return ran;
                }

                // Builtin `@Result` / `@Option` methods — type-check and record
                // the lowering decision.
                if (try inferResultOptionMethod(env, recvPtr, call.callee, typedArgs, typedTrailing, loc)) |dispatched| {
                    return dispatched;
                }
                try refuseResultMemberAccess(env, recvPtr.getType(), call.callee, true, loc);

                // Compiler-provided template methods on `expr` / `Binding`
                // receivers (expr-templates F4) — comptime-only.
                if (try inferTemplateMethod(env, recvPtr, call.callee, typedArgs, typedTrailing, loc)) |dispatched| {
                    return dispatched;
                }

                // Inherent method on the receiver's nominal type, for ANY
                // receiver expression (chained calls `a.b().c()`, field access)
                // — `resolveReceiverCall` above only fires for bare-identifier
                // receivers. This recovers the method's real return type so a
                // `Queue<i32>` chain keeps tracking `?i32` through `.peek()`.
                // Decision 641 — a primitive type's name names its member
                // table too (`bytes`): a call on a primitive value is the
                // primitive's, below, never a behavior-typed receiver's.
                if (nominalName(recvPtr.getType())) |tn| if (primKindOfName(tn) == null) {
                    if (env.hasInherentMethod(tn, call.callee)) {
                        try recordInstanceCall(env, loc, tn);
                        return try makeMethodCall(env, recvPtr, call.callee, typedArgs, typedTrailing, loc);
                    }
                    // A receiver whose static type is a `behavior` declaring
                    // `callee` without a body: the method is the VALUE's —
                    // whichever type implements the behavior, or the host.
                    // Recorded so a backend without native dispatch asks the
                    // value instead of guessing an owner from the method's
                    // name (erlang called another type's `query/2` that
                    // shared the name, or a local no module defined).
                    if (behaviorDeclaresBodyless(env, tn, call.callee, 0)) {
                        try env.instanceLowerings.put(loc, .{ .by_value = tn });
                        // The call answers what the behavior DECLARES, `Self`
                        // being the receiver. Typed as a fresh variable, the
                        // result reached a chained primitive method untyped:
                        // `x.name().length()` lowered as a call of a property
                        // on commonJS (`length is not a function`), and
                        // `toUpper` / `toString` found no lowering on wasm.
                        if (try behaviorMethodCallType(env, tn, recvPtr, call.callee, typedArgs, typedTrailing)) |ret| {
                            return TypedExpr{ .call = .{ .loc = loc, .type_ = ret, .kind = .{ .call = .{
                                .receiver = recvPtr,
                                .callee = call.callee,
                                .is_builtin = false,
                                .args = typedArgs,
                                .trailing = typedTrailing,
                            } } } };
                        }
                    }
                    // A FIELD of function type called like a method
                    // (`out.write(x)`): recorded as the record's, so a backend
                    // applies what the field holds instead of looking for a
                    // method of that name — on erlang an imported record's
                    // field call went to whichever type declared `write/2`
                    // (another type's answer at exit 0), or to none (`undef`).
                    if (env.lookupTypeDef(tn)) |td| if (td.findField(call.callee)) |fd| {
                        if (fd.type_.deref().* == .func and env.instanceLowerings.get(loc) == null)
                            try env.instanceLowerings.put(loc, .{ .type_ = tn });
                        // B-147 — the call answers what the field's function
                        // type returns (`m.make()` with `make: fn() ->
                        // Component<V>` is a `Component<V>`, so `.run(scope)`
                        // and `await` read it as one). A record with type
                        // parameters keeps the permissive answer below: its
                        // field type is not instantiated here.
                        const recvNamed = recvPtr.getType().deref();
                        if (fd.type_.deref().* == .func and recvNamed.* == .named and recvNamed.named.args.len == 0 and
                            fd.type_.deref().func.params.len == typedArgs.len and typedTrailing.len == 0)
                        {
                            const ft = fd.type_.deref().func;
                            for (typedArgs, ft.params) |ta, p|
                                try unifyArgument(env, p, ta.value.getType(), ta.value.getLoc());
                            return TypedExpr{ .call = .{ .loc = loc, .type_ = ft.ret, .kind = .{ .call = .{
                                .receiver = recvPtr,
                                .callee = call.callee,
                                .is_builtin = false,
                                .args = typedArgs,
                                .trailing = typedTrailing,
                            } } } };
                        }
                    };
                };

                // A builtin-primitive receiver (`xs.map(f)`, `s.split(sep)`) has
                // no native method dispatch on erlang/beam/wasm — record the
                // primitive family so those backends lower it to the host op,
                // and recover the method's real return type so a chained call
                // (`xs.filter(f).at(0)`) keeps tracking the element/array type.
                {
                    const recvTy = recvPtr.getType().deref();
                    if (recvTy.* == .named and primKindOfName(recvTy.named.name) != null) {
                        try recordInstanceCall(env, loc, recvTy.named.name);
                        try recordWidthMember(env, loc, recvTy.named.name, call.callee);
                        // `arr.len()`/`.size()`/`.length()` and `str.length()` are
                        // the native JS `.length` PROPERTY (commonJS emits it
                        // without call parens); erlang/beam lower them to the host
                        // length op. Recording the rename only on a typed array/
                        // string receiver keeps it safe — a `record` with a `len`/
                        // `size`/`length` method is never renamed.
                        const pk = primKindOfName(recvTy.named.name).?;
                        if ((pk == .array or pk == .string or pk == .bytes) and
                            (std.mem.eql(u8, call.callee, "len") or
                                std.mem.eql(u8, call.callee, "size") or
                                std.mem.eql(u8, call.callee, "length")))
                        {
                            try env.jsMethodRenames.put(loc, "length");
                        }
                        // §A4: per-call-site JS prototype rename driven by the
                        // bare-symbol `#[@External.Node("X")]` annotation on the method
                        // (`String.contains` ⇒ `includes`, `Array.append` ⇒
                        // `concat`, …). When the annotated symbol equals the
                        // method name nothing is recorded — call site emits the
                        // bare name unchanged. The rename is gated on a typed
                        // primitive receiver, so a user record method like
                        // `Set.contains` is never renamed.
                        if (try primMethodNodeRename(env, recvTy, call.callee)) |rn| {
                            try env.jsMethodRenames.put(loc, rn);
                        }
                        if (try primMethodReturnTypeFromIface(env, recvTy, call.callee, typedArgs)) |ret| {
                            return TypedExpr{ .call = .{ .loc = loc, .type_ = ret, .kind = .{ .call = .{
                                .receiver = recvPtr,
                                .callee = call.callee,
                                .is_builtin = false,
                                .args = typedArgs,
                                .trailing = typedTrailing,
                            } } } };
                        }
                        try refuseUndeclaredPrimMethod(env, recvTy, call.callee, loc, receiverNamesPrimitiveType(env, call.receiver));
                    }
                }

                // The same `.length` rename through ONE optional layer.
                // `xs.at(0)?.key` is a `?string`, and a `!= null` narrowing
                // does not rewrite the type either, so neither reached the
                // typed-primitive branch above and the call site kept its
                // parens: commonJS emitted `x.length()` against JavaScript's
                // `length` PROPERTY (`TypeError: … is not a function`, exit 1)
                // where erlang printed the number. Only the RENAME is taken
                // from the unwrapped type — the call's own type is whatever
                // the branches below give it. §A4's prototype rename the
                // same way: `s?.contains("x")` over a `?string` is JavaScript's
                // `includes` (`…?.contains is not a function`, exit 1).
                if (env.jsMethodRenames.get(loc) == null) {
                    if (optionalInner(recvPtr.getType())) |inner| {
                        const innerTy = inner.deref();
                        if (innerTy.* == .named) {
                            if (primKindOfName(innerTy.named.name)) |pk| {
                                // A link continuing a `?.` chain over a
                                // primitive (`o?.trim().toLower()`): its
                                // kind at the synthetic column, where a
                                // `recv?.m()` link records it, so commonJS
                                // calls std-wasm's helper under the chain's
                                // guard (decision 521) — the written loc
                                // stays the other backends'.
                                if (continuesOptionalChain(recvPtr.*)) {
                                    const synthLoc: ast.Loc = .{ .line = loc.line, .col = loc.col + optional_synthetic_col, .expansion = loc.expansion };
                                    if (env.instanceLowerings.get(synthLoc) == null) try env.instanceLowerings.put(synthLoc, .{ .prim = pk });
                                }
                                if ((pk == .array or pk == .string or pk == .bytes) and
                                    (std.mem.eql(u8, call.callee, "len") or
                                        std.mem.eql(u8, call.callee, "size") or
                                        std.mem.eql(u8, call.callee, "length")))
                                {
                                    try env.jsMethodRenames.put(loc, "length");
                                } else if (try primMethodNodeRename(env, innerTy, call.callee)) |rn| {
                                    try env.jsMethodRenames.put(loc, rn);
                                }
                            }
                        }
                    }
                }

                // 144 B-155 — a link that continues a `?.` chain over a nominal
                // payload (`post?.params.at("slug")`, `params` a `Dict`): the
                // call is the payload's, so it is recorded as the payload's
                // (`recordInstanceCall`, else the type this module has no
                // declaration of), at the written loc. Left unrecorded, erlang
                // and beam ran the untyped primitive shim and aborted with
                // `bp_unsupported_method`.
                if (continuesOptionalChain(recvPtr.*) and env.instanceLowerings.get(loc) == null) {
                    if (optionalInner(recvPtr.getType())) |inner| if (nominalName(inner)) |tn| {
                        if (primKindOfName(tn) == null and tn.len > 0 and std.ascii.isUpper(tn[0]) and !std.mem.eql(u8, tn, "Self")) {
                            if (env.hasInherentMethod(tn, call.callee))
                                try recordInstanceCall(env, loc, tn)
                            else if (env.lookupTypeDef(tn) == null)
                                try env.instanceLowerings.put(loc, .{ .unplaced_type = tn });
                        }
                    };
                }

                // 06 C9 — a receiver whose type is a nominal the env actually
                // registered has a closed method surface: nothing above matched,
                // so the method does not exist. `d.swim()` on a `type D(id: i32)`
                // used to be typed `freshVar()` and compile.
                //
                // Everything else stays permissive, which is what the fresh var
                // was for: a receiver still an unresolved type variable (an
                // inference gap must not red), and a named type the env cannot
                // open — an imported record whose typedef lives in its own
                // module, a `@Result`/`?T` wrapper, a forward reference.
                // §2.2 — an `unknown` receiver answers no method. It has to be
                // refused before the permissive fresh-var tail below, which is
                // what let `a.len()` check.
                try refuseUnknownUse(env, recvPtr.getType(), loc, "call a method on");
                try refuseBehaviorUnknownMember(env, recvPtr.getType(), call.callee, true, loc);
                // A nominal receiver this module has no declaration of (its
                // type reached here through an imported fn's return, never
                // imported itself): record the name, so a backend without
                // native dispatch can ask the value rather than guess an owner
                // from the method's name (erlang ran the untyped primitive
                // shim: `bp_unsupported_method` for `Dict.at`).
                if (nominalName(recvPtr.getType())) |tn| {
                    if (env.lookupTypeDef(tn) == null and env.instanceLowerings.get(loc) == null and
                        tn.len > 0 and std.ascii.isUpper(tn[0]) and !std.mem.eql(u8, tn, "Self"))
                        try env.instanceLowerings.put(loc, .{ .unplaced_type = tn });
                }
                if (nominalName(recvPtr.getType())) |tn| {
                    if (env.lookupTypeDef(tn)) |td| if (!typeAnswersMember(env, td, call.callee)) {
                        var ext_err: ?TypeError = null;
                        var it = env.extensions.iterator();
                        while (it.next()) |e| {
                            const entry = e.value_ptr.*;
                            if (!std.mem.eql(u8, entry.target, tn)) continue;
                            if (!namesContain(entry.methods, call.callee)) continue;
                            if (env.isActivated(entry.name)) continue;
                            ext_err = TypeError.methodNotActive(tn, call.callee, entry.name);
                            break;
                        }
                        var err = ext_err orelse TypeError.unknownMethod(tn, call.callee);
                        env.lastError = err.withLoc(loc);
                        return error.TypeError;
                    };
                }

                if (nominalName(recvPtr.getType())) |tn| if (env.lookupTypeDef(tn)) |td| {
                    if (try adoptedDefaultCallType(env, td, recvPtr, call.callee, typedArgs, typedTrailing)) |ret| {
                        return TypedExpr{ .call = .{ .loc = loc, .type_ = ret, .kind = .{ .call = .{
                            .receiver = recvPtr,
                            .callee = call.callee,
                            .is_builtin = false,
                            .args = typedArgs,
                            .trailing = typedTrailing,
                        } } } };
                    }
                };

                // Other method calls (struct getters, activated extensions) are
                // handled by sibling work — type them permissively as a fresh var
                // so they don't error here.
                const callTy = try env.freshVar();
                // Decision 328 — a receiver still free (a lambda's parameter
                // typed only by the call that applies it, `(fn(n) {
                // n.toString() })(2)`) is answered once the module's bodies are inferred,
                // when its type is known (`resolvePendingReceiverCalls`).
                if (recvPtr.getType().isUnbound()) {
                    const param: ?[]const u8 = if (call.receiver) |re| blk: {
                        if (re.* != .identifier or re.*.identifier.kind != .ident) break :blk null;
                        const bound = env.lookup(re.*.identifier.kind.ident) orelse break :blk null;
                        break :blk env.freeLambdaParams.get(bound);
                    } else null;
                    try env.pendingReceiverCalls.append(env.arena, .{
                        .loc = loc,
                        .receiver = recvPtr.getType(),
                        .callee = call.callee,
                        .ret = callTy,
                        .args = typedArgs,
                        .param = param,
                    });
                }
                return TypedExpr{ .call = .{ .loc = loc, .type_ = callTy, .kind = .{ .call = .{
                    .receiver = recvPtr,
                    .callee = call.callee,
                    .is_builtin = false,
                    .args = typedArgs,
                    .trailing = typedTrailing,
                } } } };
            }

            const calleeTypeRaw = if (env.lookup(call.callee)) |ty| ty else {
                env.lastError = try unboundAt(env, call.callee, loc);
                return error.TypeError;
            };
            try refuseBareVariant(env, call.callee, calleeTypeRaw, loc, true);
            // The nearest binding wins: a parameter or a local named like a
            // module function (a template, one with comptime parameters) is
            // the value called here, never that function — no expansion, no
            // capture. A template's name so hidden owes no expansion
            // (`refuseUnexpandedTemplateCalls`).
            const localCallee = env.localBindDepth(call.callee) != null;
            if (localCallee and templateFnNamed(env, call.callee) != null) try env.templateMethodDeclined.put(loc, {});
            if (localCallee) try env.localCalleeCalls.put(env.arena, loc, {});
            // Decision 110 — `D(…)` for `import {Dict as D}` constructs the
            // declared `Dict`: the name moves at the call (the channel that
            // renames a tuple-label callee), so no backend sees `D`.
            if (call.receiver == null) if (env.importedTypeAliases.get(call.callee)) |real| {
                const renamed = try env.arena.create(ast.Expr);
                var rc = c;
                rc.kind.call.callee = real;
                renamed.* = .{ .call = rc };
                try env.enumSectionRewrites.put(loc, renamed);
            };
            // Generic record/struct/enum constructor: instantiate per call site
            // so the registration-time cells never unify destructively.
            const ctorInstantiated = try instantiateCtorType(env, call.callee, calleeTypeRaw);
            // Generic fn (declared `<T, …>`): standard HM instantiation — each
            // call site gets fresh vars for the fn's `.generic` params, so two
            // calls with different concrete types in one scope never conflict.
            const calleeType = try instantiateGenericType(env, ctorInstantiated);
            const resolved = calleeType.deref();
            const retType: *T.Type = switch (resolved.*) {
                .func => |f| blk: {
                    // Constrained comptime typeparam args are validated against their
                    // declared constraints; their param slots skip ordinary unification.
                    const typeparams = if (localCallee) null else env.lookupTypeparams(call.callee);
                    if (typeparams) |constraints| try validateTypeparams(env, constraints, typedArgs);
                    // `expr` meta-kind params capture their argument unevaluated
                    // instead of unifying it against `expr T` (expr-templates F4).
                    const exprParams = if (localCallee) null else env.lookupExprParams(call.callee);
                    // Decision 311, question s29-a — a template taking the
                    // annotated declaration's `@Decl` is written only as an
                    // annotation, `#[f "…"]`.
                    if (!localCallee) if (templateFnNamed(env, call.callee)) |tfn| if (memberFn.isTemplateAnnotation(tfn)) {
                        const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` takes the annotated declaration (`syntax {s}: unknown`), so it is written as an annotation `#[{s} @`…`]`, never called", .{ diagnostics.template_annotation_only, call.callee, tfn.params[1].name, call.callee });
                        env.lastError = TypeError.custom(msg, "A template called in an expression has no declaration to record on; write the template without the `syntax decl` parameter for a call site (decision 311, question s29-a).").withLoc(loc);
                        return error.TypeError;
                    };

                    var spreadCount: usize = 0;
                    var nonSpreadCount: usize = 0;
                    for (typedArgs) |ta| {
                        if (ta.label) |lbl| {
                            if (std.mem.eql(u8, lbl, "..")) {
                                spreadCount += 1;
                                continue;
                            }
                        }
                        nonSpreadCount += 1;
                    }

                    if (spreadCount == 0) {
                        if (f.params.len != call.args.len) {
                            // C-04 / N1 — a call may omit an argument whose
                            // parameter declares a default. The fill is planned
                            // here and materialised in `transform.zig`, so all
                            // four backends see a complete call and none of them
                            // learns a new rule. A comptime / `@Expr` / template
                            // callee keeps the exact check: its own machinery is
                            // driven by the argument INDEX, and a short call has
                            // never reached it.
                            const filled: ?envMod.DefaultFill = fillBlk: {
                                if (call.args.len > f.params.len) break :fillBlk null;
                                if (typeparams != null or exprParams != null) break :fillBlk null;
                                if (!localCallee and env.templateFns.get(call.callee) != null) break :fillBlk null;
                                const declared = declParamsAst orelse break :fillBlk null;
                                if (declared.len != f.params.len) break :fillBlk null;
                                break :fillBlk try recordDefaultFill(env, loc, declared, typedArgs);
                            };
                            if (filled) |fill| {
                                try unifyFilledArgs(env, fill, f.params, typedArgs);
                                break :blk f.ret;
                            }
                            // Decision 207 — an inline parameter type's
                            // constructor is the call's labelled fields: name
                            // the field left out.
                            if (ast.ownerOfInlineType(call.callee) != null) if (declParamsAst) |declared| {
                                for (declared) |dp| {
                                    if (dp.default != null) continue;
                                    const given = for (call.args) |a| {
                                        if (a.label) |l| if (std.mem.eql(u8, l, dp.name)) break true;
                                    } else false;
                                    if (given) continue;
                                    const msg = try std.fmt.allocPrint(env.arena, "missing field `{s}` of {s}", .{ dp.name, call.callee });
                                    env.lastError = TypeError.custom(msg, "Write it as a labelled argument of the call, or give the field a default in the inline type.").withLoc(loc);
                                    return error.TypeError;
                                }
                            };
                            // N2 — a missing REQUIRED argument is the arity
                            // error it has always been, word for word.
                            env.lastError = TypeError.arityMismatch(call.callee, f.params.len, call.args.len).withLoc(loc);
                            return error.TypeError;
                        }
                        // 01 — a complete call whose labels move an argument
                        // (`diff(b: 1, a: 10)`, `P(y: "a", x: 1)`) is checked and
                        // lowered by the parameter each label names: every
                        // consumer used to zip the arguments positionally, so the
                        // checker typed `y`'s value against `x` and the backends
                        // passed `b` as `a` (a fully-labelled self tail call
                        // assigned its arguments crosswise and never ended).
                        if (typeparams == null and exprParams == null and (localCallee or env.templateFns.get(call.callee) == null)) {
                            if (declParamsAst) |declared| if (declared.len == f.params.len) {
                                if (try planLabelledCall(env, call.callee, declared, typedArgs, loc)) |plan| {
                                    try env.defaultInjections.put(loc, plan);
                                    try unifyFilledArgs(env, plan, f.params, typedArgs);
                                    break :blk f.ret;
                                }
                            };
                            // A function VALUE (a parameter, a local, a field)
                            // has a type and no parameter names: a label there
                            // names nothing, and zipping it by position would
                            // let `f(s: "x", n: 1)` mean `f("x", 1)`. Refused.
                            if (declParamsAst == null) {
                                // A constructor reached under another name (an
                                // import alias, `D(pairs: [])` for std's
                                // `Dict`) is its type's: the labels name its
                                // fields.
                                const aliasedCtor: ?[]const ast.Param = ctorBlk: {
                                    if (call.callee.len == 0 or !std.ascii.isUpper(call.callee[0])) break :ctorBlk null;
                                    const r = f.ret.deref();
                                    if (r.* != .named) break :ctorBlk null;
                                    const ps = env.ctorParams.get(r.named.name) orelse break :ctorBlk null;
                                    break :ctorBlk if (ps.len == f.params.len) ps else null;
                                };
                                if (aliasedCtor) |declared| {
                                    if (try planLabelledCall(env, call.callee, declared, typedArgs, loc)) |plan| {
                                        try env.defaultInjections.put(loc, plan);
                                        try unifyFilledArgs(env, plan, f.params, typedArgs);
                                        break :blk f.ret;
                                    }
                                } else try refuseLabelsOnFunctionValue(env, call.callee, typedArgs);
                            }
                        }
                        // Look up the template fn before the loop so non-@Expr
                        // params can also be collected as plain arg bindings.
                        const maybeTfn: ?ast.FnDecl = if (localCallee) null else env.templateFns.get(call.callee);
                        // Decisions 577 (3), 578 (1) — a template is called one
                        // way: its name before a template text, `` f @`…` ``.
                        // Decision 719 — a function with a `syntax` expression
                        // parameter is called with ordinary parentheses, never
                        // with a template text.
                        if (maybeTfn) |tf| if (ast.syntaxExprIndex(tf.params)) |si| if (call.templateText != null) {
                            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` takes the expression `{s}` between parentheses, `{s}(…)`, and is called here with a template text", .{ diagnostics.syntax_call_outside_syntax, call.callee, tf.params[si].name, call.callee });
                            env.lastError = TypeError.custom(msg, "A `syntax` parameter of a type other than `string` takes the expression written between the call's parentheses; only `syntax q: string` takes a template text `` f @`…` `` (decisions 578 (1), 719).").withLoc(loc);
                            return error.TypeError;
                        };
                        if (maybeTfn) |tf| if (tf.returnType) |rt| if (ast.isExprKeywordReturn(rt) and ast.syntaxExprIndex(tf.params) == null and (call.templateText == null or (env.inDecoratorFn and loc.expansion == 0))) {
                            const msg = try std.fmt.allocPrint(env.arena, "{s}: `{s}` is a template, called only with a template text, and is called here another way", .{ diagnostics.syntax_call_outside_syntax, call.callee });
                            env.lastError = TypeError.custom(msg, "Write its text after its name: `f @`select …``, `value.f @`…``, or `#[f @`…`]` (decision 577 (3)).").withLoc(loc);
                            return error.TypeError;
                        };
                        // Decision 637 — a template answering `anyvalue`
                        // called in a template's body runs where the body
                        // runs, at build (`build_template_calls.zig`): the
                        // holes of its text are the body's expressions, typed
                        // here, and the call's value is the code it builds.
                        if (maybeTfn) |tf| if (env.inTemplateFn and loc.expansion == 0 and call.templateText != null and call.receiver == null and buildCalls.answersAnyvalue(tf)) {
                            for (try textHoleExprs(env, call.templateText.?, call.args[0].value.getLoc())) |h| _ = try inferExpr(env, h);
                            break :blk try env.namedTypeArgs(ast.expr_type_name, &.{try env.freshVar()});
                        };
                        var captures: std.ArrayListUnmanaged(template.CapturedExpr) = .empty;
                        var plainArgs: std.ArrayListUnmanaged(template.PlainArg) = .empty;
                        for (typedArgs, f.params, 0..) |ta, paramType, i| {
                            if (typeparams) |constraints| if (isTypeparamIndex(constraints, i) and !(i < tokenTyped.len and tokenTyped[i])) continue;
                            if (exprParams) |eps| if (exprParamAt(eps, i)) |ep| {
                                try captures.append(env.arena, try captureExprArg(env, call.callee, ep, call.args[i].value, ta, paramType, call.templateText));
                                continue;
                            };
                            try unifyArgument(env, paramType, ta.value.getType(), ta.value.getLoc());
                            // For template fns: collect the arg value as a JS literal.
                            if (maybeTfn != null and i < maybeTfn.?.params.len) {
                                const jsVal = try literalSourceAlloc(env.arena, call.args[i].value) orelse {
                                    env.lastError = TypeError.custom(
                                        "non-`@Expr` parameter of a template function must receive a literal value at the call site",
                                        "Pass a string, integer, or boolean literal directly; runtime values have no compile-time meaning (V1).",
                                    ).withLoc(ta.value.getLoc());
                                    return error.TypeError;
                                };
                                try plainArgs.append(env.arena, .{
                                    .paramName = maybeTfn.?.params[i].name,
                                    .source = jsVal,
                                });
                            }
                        }
                        const capturedSlice: []const template.CapturedExpr = if (captures.items.len > 0)
                            try captures.toOwnedSlice(env.arena)
                        else
                            &.{};
                        const plainSlice: []const template.PlainArg = if (plainArgs.items.len > 0)
                            try plainArgs.toOwnedSlice(env.arena)
                        else
                            &.{};
                        if (capturedSlice.len > 0) {
                            try env.exprCaptures.put(loc, capturedSlice);
                        }
                        // Call-site expansion (F6): a call to a template fn
                        // (`-> @Expr<T>`) is replaced by its expansion,
                        // re-type-checked in the caller's environment.
                        if (maybeTfn) |tfn| {
                            return try expandTemplateCall(env, tfn, capturedSlice, plainSlice, f.ret, loc);
                        }
                        break :blk f.ret;
                    }

                    // C11: a call carrying a `..` spread on a record constructor
                    // is a record *update*: the spread must be that record, and
                    // each labelled arg is matched to the field its label names.
                    if (spreadCount == 1) updBlk: {
                        const td = env.lookupTypeDef(call.callee) orelse break :updBlk;
                        const fields = switch (td) {
                            .record => |r| r.fields,
                            .struct_ => |st| st.fields,
                            .enum_ => break :updBlk,
                        };
                        if (fields.len != f.params.len) break :updBlk;
                        for (typedArgs, 0..) |ta, ai| {
                            const lbl = ta.label orelse {
                                // Positional args beside a spread have no field to name.
                                env.lastError = TypeError.custom(
                                    "a record update names its fields",
                                    "Write `Name(..base, field: value)`.",
                                ).withLoc(ta.value.getLoc());
                                return error.TypeError;
                            };
                            if (std.mem.eql(u8, lbl, "..")) {
                                try unifyAt(env, f.ret, ta.value.getType(), ta.value.getLoc());
                                continue;
                            }
                            const idx = for (fields, 0..) |fd, fi| {
                                if (std.mem.eql(u8, fd.name, lbl)) break fi;
                            } else {
                                const vloc = call.args[ai].value.getLoc();
                                const labelCol = if (vloc.col > lbl.len + 2) vloc.col - lbl.len - 2 else vloc.col;
                                env.lastError = TypeError.unknownField(call.callee, lbl).withLoc(.{ .line = vloc.line, .col = labelCol, .expansion = vloc.expansion });
                                return error.TypeError;
                            };
                            try unifyArgument(env, f.params[idx], ta.value.getType(), ta.value.getLoc());
                        }
                        try rewriteRecordUpdate(env, c, fields, loc);
                        break :blk f.ret;
                    }

                    // Keep the historical spread behavior (and snapshots) for narrow update/error cases.
                    if (spreadCount != 1 or nonSpreadCount < 2) {
                        if (f.params.len != call.args.len) {
                            env.lastError = TypeError.arityMismatch(call.callee, f.params.len, call.args.len).withLoc(loc);
                            return error.TypeError;
                        }
                        for (typedArgs, f.params, 0..) |ta, paramType, i| {
                            if (typeparams) |constraints| if (isTypeparamIndex(constraints, i) and !(i < tokenTyped.len and tokenTyped[i])) continue;
                            try unifyArgument(env, paramType, ta.value.getType(), ta.value.getLoc());
                        }
                        break :blk f.ret;
                    }

                    if (nonSpreadCount > f.params.len) {
                        env.lastError = TypeError.arityMismatch(call.callee, f.params.len, nonSpreadCount).withLoc(loc);
                        return error.TypeError;
                    }

                    var paramIndex: usize = 0;
                    for (typedArgs) |ta| {
                        if (ta.label) |lbl| {
                            if (std.mem.eql(u8, lbl, "..")) continue;
                        }
                        if (paramIndex >= f.params.len) {
                            env.lastError = TypeError.arityMismatch(call.callee, f.params.len, nonSpreadCount).withLoc(loc);
                            return error.TypeError;
                        }
                        try unifyArgument(env, f.params[paramIndex], ta.value.getType(), ta.value.getLoc());
                        paramIndex += 1;
                    }
                    break :blk f.ret;
                },
                .named => |n| blk: {
                    try refuseCallOfValue(env, call.callee, n.name, loc);
                    break :blk resolved;
                },
                else => try env.freshVar(),
            };
            // 144 B-114 (decision 521) — each argument of a generic fn's call:
            // commonJS hands the callee's body the print shape of each type
            // parameter, read off the argument it binds (`text_arg_col`).
            // 144 B-115 — and of a generic record's constructor: the value
            // carries the shape of each field a type parameter types.
            if (!localCallee and (calleeType != ctorInstantiated or ctorInstantiated != calleeTypeRaw)) for (typedArgs) |ta| {
                var key = ta.value.getLoc();
                key.col += ast.text_arg_col;
                try noteTextValue(env, key, ta.value.getType());
            };
            return TypedExpr{ .call = .{ .loc = loc, .type_ = retType, .kind = .{ .call = .{
                .receiver = null,
                .callee = call.callee,
                .is_builtin = call.is_builtin,
                .args = typedArgs,
                .trailing = typedTrailing,
            } } } };
        },
        .pipeline => |p| {
            const lhsTyped = try inferExprTyped(env, p.lhs.*);
            const lhsPtr = try makeTypedPtr(env, lhsTyped);
            // When the RHS is a plain call, the LHS value is the first argument.
            // Build the typed RHS manually to avoid the arity check in inferCallExpr.
            if (p.rhs.* == .call and p.rhs.*.call.kind == .call) {
                const call = p.rhs.*.call.kind.call;
                const calleeTypeRaw = if (env.lookup(call.callee)) |ty| ty else try env.freshVar();
                // Generic fn in pipeline position gets the same per-call-site
                // instantiation as a plain call.
                const calleeType = try instantiateGenericType(env, calleeTypeRaw);
                const resolved = calleeType.deref();
                const retType: *T.Type = switch (resolved.*) {
                    .func => |f| blk: {
                        const totalArgs = call.args.len + 1 + call.trailing.len;
                        // C-04 / 01 — `lhs |> f(b: 1)` is the call `f(lhs, b: 1)`:
                        // a short one takes the declared defaults and a label
                        // names its parameter, planned under the pipeline's loc
                        // (`transform.zig` rewrites the pipeline into that call).
                        if (call.trailing.len == 0) if (try planPipelineFill(env, call.callee, f, lhsPtr, call.args, loc)) |ret| break :blk ret;
                        // C12: a pipeline whose RHS does not take the piped
                        // value plus its own arguments is an arity error at
                        // the RHS, not a silently skipped unification.
                        if (f.params.len != totalArgs) {
                            env.lastError = TypeError.arityMismatch(call.callee, f.params.len, totalArgs).withLoc(p.rhs.*.getLoc());
                            return error.TypeError;
                        }
                        try unifyAt(env, f.params[0], lhsTyped.getType(), loc);
                        for (call.args, 1..) |arg, i| {
                            const argTyped = try inferExprTyped(env, arg.value.*);
                            try unifyAt(env, f.params[i], argTyped.getType(), loc);
                        }
                        break :blk f.ret;
                    },
                    else => try env.freshVar(),
                };
                // Build a typed call node for the RHS (with pipeline arity).
                const typedCallArgs = try env.arena.alloc(ast.CallArgOf(.typed), call.args.len);
                for (call.args, 0..) |arg, i| {
                    const val = try inferExprTyped(env, arg.value.*);
                    typedCallArgs[i] = .{ .label = arg.label, .value = try makeTypedPtr(env, val) };
                }
                const typedTrailing = try inferTrailingLambdasTyped(env, call.trailing);
                const rhsNode = TypedExpr{ .call = .{ .loc = p.rhs.*.getLoc(), .type_ = retType, .kind = .{ .call = .{
                    .receiver = null,
                    .callee = call.callee,
                    .is_builtin = call.is_builtin,
                    .args = typedCallArgs,
                    .trailing = typedTrailing,
                } } } };
                const rhsPtr = try makeTypedPtr(env, rhsNode);
                return TypedExpr{ .call = .{ .loc = loc, .type_ = retType, .kind = .{ .pipeline = .{
                    .lhs = lhsPtr,
                    .rhs = rhsPtr,
                    .comment = p.comment,
                } } } };
            }
            const rhsTyped = try inferExprTyped(env, p.rhs.*);
            const rhsPtr = try makeTypedPtr(env, rhsTyped);
            // C12: `lhs |> f` with `f` a function is the call `f(lhs)`: its
            // type is `f`'s return, and `f` must take exactly one argument —
            // or declare a default for every other one (C-04).
            const pipeType: *T.Type = switch (rhsTyped.getType().deref().*) {
                .func => |f| blk: {
                    if (f.params.len != 1) if (p.rhs.* == .identifier and p.rhs.*.identifier.kind == .ident) {
                        if (try planPipelineFill(env, p.rhs.*.identifier.kind.ident, f, lhsPtr, &.{}, loc)) |ret| break :blk ret;
                    };
                    if (f.params.len != 1) {
                        const name = switch (p.rhs.*) {
                            .identifier => |id| switch (id.kind) {
                                .ident => |n| n,
                                else => "|>",
                            },
                            else => "|>",
                        };
                        env.lastError = TypeError.arityMismatch(name, f.params.len, 1).withLoc(p.rhs.*.getLoc());
                        return error.TypeError;
                    }
                    try unifyAt(env, f.params[0], lhsTyped.getType(), loc);
                    break :blk f.ret;
                },
                else => rhsTyped.getType(),
            };
            return TypedExpr{ .call = .{ .loc = loc, .type_ = pipeType, .kind = .{ .pipeline = .{
                .lhs = lhsPtr,
                .rhs = rhsPtr,
                .comment = p.comment,
            } } } };
        },
    };
}

/// True when an untyped `case` arm body is a block (`_ -> { … }`), which the
/// parser represents as a zero-parameter lambda.
fn isBlockArmBody(body: ast.Expr) bool {
    return body == .function and body.function.kind.syntax == .lambda and body.function.kind.params.len == 0;
}

/// Decision 8 §5.1 P3 — the arm body forms that are a lambda node: the block
/// arm (`_ -> { … }`, no parameter) and the decision-8 binder arm
/// (`i32 { n -> … }`, exactly one). Both are arm bodies, so both keep the
/// enclosing fn's return target.
fn isArmBodyLambda(body: ast.Expr) bool {
    if (body != .function or body.function.kind.syntax != .lambda) return false;
    return body.function.kind.params.len <= 1;
}

/// Infer an arm's body, binding a single-parameter binder arm's parameter to
/// the matched value's type (§5.1 P1/P5) instead of to a fresh variable.
fn inferCaseArmBody(
    env: *Env,
    arm: ast.CaseArm,
    typedSubjects: []const ast.TypedExpr,
) InferError!TypedExpr {
    const body = arm.body;
    const isBinderArm = body == .function and
        body.function.kind.syntax == .lambda and
        body.function.kind.params.len == 1;
    if (!isBinderArm or typedSubjects.len != 1) return inferExprTyped(env, body);
    // The subject **as this arm's pattern narrowed it** (§5.1 P1/P5). A type
    // pattern (`i32 { n -> … }`) makes the binder that type; every other
    // pattern leaves the subject's own, which is P5's answer for them — a
    // variant payload's own binding comes from the pattern instead, and
    // `bindCaseArmPatternNames` has already bound it.
    const subjectTy = typedSubjects[0].getType();
    const narrowed = (try typePatternType(env, arm.pattern, subjectTy)) orelse subjectTy;
    const expected = try env.funcType(&.{narrowed}, try env.freshVar());
    return inferFunctionExprExpected(env, body.function, body.getLoc(), expected, false);
}

/// C2a — the value an arm contributes to its `case`'s type, or null when it
/// contributes nothing: a jump arm, a `void` arm, a block arm without a
/// top-level `break <value>` (decision 2: a block's value comes from `break`).
fn caseArmValueType(env: *Env, body: ast.TypedExpr) InferError!?*T.Type {
    _ = env;
    if (body == .jump) return null;
    // Decision 8 §5.1 P3 — `Pattern { body }` lands as the same lambda node the
    // older block arm produced, and the body **is** a lambda body: its last
    // expression is the arm's value. Only the `break` half was read, so
    // `0 { "zero" }` contributed nothing at all and the `case` typed `void`,
    // while `_ { n -> … }` was unified as a `function`.
    if (body == .function and body.function.kind.syntax == .lambda) {
        // Decision 525 — the arm is a block: its value is its tail, the last
        // expression written without `;`.
        const stmts = body.function.kind.body;
        const last = lastNonComment(stmts) orelse return null;
        const tail = last.expr;
        // §3.2 — an arm whose body jumps (`return`/`throw`/`continue`) does not
        // contribute to the `case`'s type.
        if (tail == .jump and !valueJump(tail)) return null;
        if (last.tail == .none) return null;
        return nonVoid(tail.getType());
    }
    return nonVoid(body.getType());
}

/// `try e` and `await e` are jumps in the tree and values in the language: a
/// block's tail may be one.
fn valueJump(e: ast.TypedExpr) bool {
    return e == .jump and (e.jump.kind == .try_ or e.jump.kind == .await_);
}

/// The last statement of a body that is not a comment, or null.
fn lastNonComment(stmts: []const ast.TypedStmt) ?ast.TypedStmt {
    var n = stmts.len;
    while (n > 0) : (n -= 1) {
        const e = stmts[n - 1].expr;
        if (e == .literal and e.literal.kind == .comment) continue;
        return stmts[n - 1];
    }
    return null;
}

/// Decision 525 — whether an arm of a `case` used as a value answers nothing:
/// a block arm whose last statement is no tail (written with `;`, or a
/// binding) and does not leave (a jump, a `noreturn` call), or whose tail is
/// `void`. A `break <value>` arm answers its value.
fn armAnswersNothing(body: ast.TypedExpr) bool {
    if (body == .jump) return false;
    if (body == .function and body.function.kind.syntax == .lambda) {
        const last = lastNonComment(body.function.kind.body) orelse return true;
        if (last.expr == .jump and !valueJump(last.expr)) return false;
        const d = last.expr.getType().deref();
        if (d.isNamed("noreturn")) return false;
        if (last.tail == .none) return true;
        return d.isNamed("void");
    }
    return body.getType().deref().isNamed("void");
}

/// The type, unless it is `void` — a statement arm contributes nothing.
fn nonVoid(t: *T.Type) ?*T.Type {
    const d = t.deref();
    if (d.* == .named and std.mem.eql(u8, d.named.name, "void")) return null;
    return t;
}

/// Decision 8 §3 — add one member to a union under construction, flattening a
/// nested union (`(A | B) | C` is `A | B | C`) and dropping a duplicate. Union
/// membership is set-like: the members are what the value may be, and saying
/// one of them twice says nothing more.
fn appendUnionMember(
    env: *Env,
    into: *std.ArrayListUnmanaged(*T.Type),
    member: *T.Type,
) InferError!void {
    const m = member.deref();
    if (m.* == .union_) {
        for (m.union_) |inner| try appendUnionMember(env, into, inner);
        return;
    }
    // A variable inference has not decided is not a distinct alternative. It
    // joins whatever is already there instead of standing beside it, so a
    // union never carries a `?` member that says nothing.
    // Located by the caller that holds the union's place (`locateLast`).
    if (m.isUnbound() and into.items.len > 0) return unifyUnlocated(env, into.items[0], m);
    for (into.items) |existing| {
        if (sameTypeShape(existing, m)) return;
        if (existing.isUnbound()) return unifyUnlocated(env, existing, m);
    }
    try into.append(env.arena, m);
}

/// Decision 8 §3.2/§3.4 — finish a union that `appendUnionMember` has already
/// flattened and de-duplicated.
///
/// `?T` **absorbs**: a `null` branch makes the whole thing optional, so
/// `if (c) { 1 } else { null }` is `?i32` and not `i32 | ?_`. Recursively, that
/// is also §3.4's `Option<A> | Option<B>` → `Option<A | B>`.
///
/// No other head joins here. §3.4 also lists `Box`, `@Result` and `Dict`, but a
/// join is only sound when the type's parameter is **read** and never written:
/// joining `Box<i32> | Box<string>` into `Box<i32 | string>` would let a
/// `set(v: T)` store a `string` in what is really a `Box<i32>`. The "only read"
/// test is a member-signature walk this front has not built; until it exists
/// those members stay side by side, which refuses more than §3.4 and is never
/// wrong. Arrays never join at all — that is §3.4's own rule.
fn finishUnion(env: *Env, all: []*T.Type) InferError!*T.Type {
    // `noreturn` is the bottom type: a branch or an arm that never returns adds
    // no alternative (`if (c) { a } else { @todo() }` is `a`'s type).
    var kept: usize = 0;
    for (all) |m| {
        if (m.deref().isNamed("noreturn")) continue;
        all[kept] = m;
        kept += 1;
    }
    const members = if (kept > 0) all[0..kept] else all;
    if (members.len == 0) return env.namedType("void");
    if (members.len == 1) return members[0];
    for (members, 0..) |m, idx| {
        const d = m.deref();
        if (d.* != .named) continue;
        if (!std.mem.eql(u8, d.named.name, "optional") or d.named.args.len != 1) continue;
        var inner: std.ArrayListUnmanaged(*T.Type) = .empty;
        try appendUnionMember(env, &inner, d.named.args[0]);
        for (members, 0..) |other, j| {
            if (j != idx) try appendUnionMember(env, &inner, other);
        }
        // Each step consumes one optional member, so the recursion is finite.
        const innerTy = try finishUnion(env, inner.items);
        const args = try env.arena.alloc(*T.Type, 1);
        args[0] = innerTy;
        return env.namedTypeArgs("optional", args);
    }
    return env.unionType(try env.arena.dupe(*T.Type, members));
}

/// The union of `members`, flattened, de-duplicated and normalised.
fn unionOf(env: *Env, members: []const *T.Type) InferError!*T.Type {
    var flat: std.ArrayListUnmanaged(*T.Type) = .empty;
    for (members) |m| try appendUnionMember(env, &flat, m);
    return finishUnion(env, flat.items);
}

/// Two types are the same union member. Structural and conservative: it decides
/// membership, so it must never call two members the same when a value could
/// tell them apart, and it must not unify (a probe that mutated would leave the
/// failed alternative linked).
fn sameTypeShape(a: *T.Type, b: *T.Type) bool {
    const da = a.deref();
    const db = b.deref();
    if (da == db) return true;
    return switch (da.*) {
        .named => |na| switch (db.*) {
            .named => |nb| blk: {
                if (!std.mem.eql(u8, na.name, nb.name)) break :blk false;
                if (na.args.len != nb.args.len) break :blk false;
                for (na.args, nb.args) |x, y| {
                    if (!sameTypeShape(x, y)) break :blk false;
                }
                break :blk true;
            },
            else => false,
        },
        .func => |fa| switch (db.*) {
            .func => |fb| blk: {
                if (fa.params.len != fb.params.len) break :blk false;
                for (fa.params, fb.params) |x, y| {
                    if (!sameTypeShape(x, y)) break :blk false;
                }
                break :blk sameTypeShape(fa.ret, fb.ret);
            },
            else => false,
        },
        .union_ => |ua| switch (db.*) {
            .union_ => |ub| blk: {
                if (ua.len != ub.len) break :blk false;
                for (ua, ub) |x, y| {
                    if (!sameTypeShape(x, y)) break :blk false;
                }
                break :blk true;
            },
            else => false,
        },
        .record => |fa| switch (db.*) {
            .record => |fb| blk: {
                if (fa.len != fb.len) break :blk false;
                for (fa, fb) |x, y| {
                    if (!std.mem.eql(u8, x.name, y.name)) break :blk false;
                    if (!sameTypeShape(x.type_, y.type_)) break :blk false;
                }
                break :blk true;
            },
            else => false,
        },
        // Two distinct variables are not the same member: nothing has said so.
        .typeVar => false,
    };
}

/// Decision 525 — what a block refuses before its body is typed: a position
/// that expects a function (the block is no closure — "missing `->`?"), and
/// a `break <value>` meant as its value (its value is its tail).
fn refuseBlockShape(env: *Env, c: anytype, expected: ?*T.Type, loc: ast.Loc) InferError!void {
    if (expected) |want| if (want.deref().* == .func) return refuseBlockAt(env, want, want, loc);
    const body = c.arms[0].body.function.kind.body;
    if (blockBreakValue(body)) |at| return refuseBlockBreak(env, at);
}

/// A block handed to a parameter of type `param`: refused where `param` is a
/// function, and where it is `unknown` and the block answers `void`.
fn refuseBlockAt(env: *Env, param: *T.Type, arg: *T.Type, loc: ast.Loc) InferError!void {
    const p = param.deref();
    if (p.* == .func) {
        env.lastError = TypeError.custom(
            diagnostics.block_not_function ++ ": expected a function, got a block's value — missing `->`?",
            "A `{` without `->` is a block, never a closure (decision 525): a lambda with no parameter is written `{ -> … }`.",
        ).withLoc(loc);
        return error.TypeError;
    }
    if (p.isNamed("unknown") and arg.deref().isNamed("void")) {
        env.lastError = TypeError.custom(
            diagnostics.block_void_value ++ ": a block whose value is `void` is handed where a value is expected",
            "A block's value is its last expression written without `;` (decision 525).",
        ).withLoc(loc);
        return error.TypeError;
    }
}

/// A `break :label` / `continue :label` names a loop (or generator scope)
/// that encloses it in the same function: an `iter` / `stream` loop's body is
/// a closure and a jump out of it is `generator-loop-closed-scope`; a label no
/// enclosing loop carries is `break-label-unbound`.
fn checkJumpLabel(env: *Env, lbl: []const u8, comptime word: []const u8, loc: ast.Loc) InferError!void {
    const ctx = env.starFn;
    for (env.closedLabels) |outer| {
        if (std.mem.eql(u8, outer, lbl)) {
            env.lastError = TypeError.custom(
                try std.fmt.allocPrint(env.arena, "{s}: `" ++ word ++ " :{s}` crosses the border of an `{s}` loop — its body is a closure and cannot leave a loop outside it", .{ diagnostics.generator_loop_closed_scope, lbl, if (ctx.?.effect == .stream) "stream" else "iter" }),
                "End the prefixed loop (`break`) and leave the outer loop after it.",
            ).withLoc(loc);
            return error.TypeError;
        }
    }
    if (!env.hasLabel(lbl)) {
        env.lastError = TypeError.custom(
            diagnostics.break_label_unbound ++
                ": `" ++ word ++ " :<label>` targets an unknown label",
            "Label a loop (`for :name (…)`, `while :name (…)`, `loop :name {`) or a generator scope (`iter fn … -> Iter<…> :name`, `iter loop :name {`).",
        ).withLoc(loc);
        return error.TypeError;
    }
}

fn refuseBlockBreak(env: *Env, at: ast.Loc) InferError!void {
    env.lastError = TypeError.custom(
        diagnostics.block_break_value ++ ": a block's value is its last expression — `break <value>` does not give it",
        "Write the value as the block's last expression, without `;` (decision 525): `comptime { val x = 10; x * 2 }`.",
    ).withLoc(at);
    return error.TypeError;
}

/// Decision 525 — the first written `break <value>` (no label) that would
/// leave the block `body` belongs to — in its own statements and its `if`
/// branches; a loop, a closure, a `case` arm's block and a nested block are
/// scopes of their own. The tail the parser wrapped in the block's `break`
/// (`comptime { … }`, `tail = .returned`) is the block's value, not one.
fn blockBreakValue(body: []const ast.Stmt) ?ast.Loc {
    for (body) |st| {
        if (st.tail == .returned) continue;
        if (exprBreakValue(st.expr)) |l| return l;
    }
    return null;
}

fn exprBreakValue(e: ast.Expr) ?ast.Loc {
    return switch (e) {
        .jump => |j| switch (j.kind) {
            .@"break" => |b| if (b.label == null and b.value != null) j.loc else null,
            else => null,
        },
        .branch => |b| switch (b.kind) {
            .if_ => |i| blockBreakValue(i.then_) orelse (if (i.else_) |els| blockBreakValue(els) else null),
            else => null,
        },
        else => null,
    };
}

/// C2a — unify the arms that agree; distinct named types become union members.
/// `armTypes` (one slot per arm) receives each arm's own type, null for an
/// arm that contributes nothing.
fn caseTypeFromArms(env: *Env, arms: []const ast.CaseArmOf(.typed), armTypes: []?*T.Type) InferError!*T.Type {
    var members: std.ArrayListUnmanaged(*T.Type) = .empty;
    for (arms, 0..) |arm, i| {
        armTypes[i] = null;
        const t = (try caseArmValueType(env, arm.body)) orelse continue;
        armTypes[i] = t;
        var merged = false;
        for (members.items) |m| {
            if (caseArmTypesAgree(m, t)) {
                try unifyAt(env, m, t, arm.body.getLoc());
                merged = true;
                break;
            }
        }
        if (!merged) try members.append(env.arena, t);
    }
    return finishUnion(env, members.items);
}

/// Decision 150 (D5, decision 8 §3.2) — the element type of an array literal
/// whose elements were inferred with nothing expected of them. Elements that
/// agree unify (the first pins the others' variables, as before); the ones
/// that do not stand beside each other as union members, so `[1, "a"]` is
/// `(i32 | string)[]` and `[1, null]` is `?i32[]` (`finishUnion`'s optional
/// absorption). §3.2's one numeric rule: an integer LITERAL fits `f64`, so
/// `[1, 2.5]` is `f64[]` — the literal is typed `f64` and re-spelt as a float
/// for the backends (`env.indexRewrites`, literal for literal). An `i32` that
/// is not a literal does not widen. A union made here records its first
/// disagreeing element in `env.unionOrigins`, which the refusal at a use names.
fn arrayLiteralJoin(env: *Env, elems: []const ast.Expr, typed: []ast.TypedExpr) InferError!*T.Type {
    // Decision 247 (209 reversed) — an integer literal beside a float is
    // not re-spelt into an `f64[]`: the literal never changes type, and
    // `[1, 2.5]` would otherwise be the union nobody meant.
    const floatElem = for (typed) |t| {
        const d = t.getType().deref();
        if (d.isNamed("f64") or d.isNamed("f32")) break d.named.name;
    } else null;
    if (floatElem) |ft| {
        for (elems, 0..) |e, i| {
            if (!isIntegerLiteral(e)) continue;
            if (!typed[i].getType().deref().isNamed("i32")) continue;
            const text = e.literal.kind.numberLit;
            const asFloat = (try floatSpelling(env, text)) orelse text;
            const msg = try std.fmt.allocPrint(env.arena, "the integer literal `{s}` stands beside an `{s}` in an array literal — write `{s}`", .{ text, ft, if (std.mem.eql(u8, ft, "f32")) try std.fmt.allocPrint(env.arena, "{s}f", .{asFloat}) else asFloat });
            env.lastError = TypeError.custom(msg, "A literal without a suffix never changes type to fit (decision 247): write every element as the float it is, `[1.0, 2.5]`, or annotate the array.").withLoc(e.literal.loc);
            return error.TypeError;
        }
    }
    var members: std.ArrayListUnmanaged(*T.Type) = .empty;
    var widenedAt: ?ast.Loc = null;
    for (typed) |elem| {
        const t = elem.getType();
        var merged = false;
        for (members.items) |m| {
            if (caseArmTypesAgree(m, t)) {
                try unifyAt(env, m, t, elem.getLoc());
                merged = true;
                break;
            }
        }
        if (!merged) {
            if (members.items.len > 0 and widenedAt == null) widenedAt = elem.getLoc();
            try members.append(env.arena, t);
        }
    }
    const joined = try finishUnion(env, members.items);
    if (widenedAt) |at| {
        if (joined.deref().* == .union_) try env.unionOrigins.put(env.arena, joined.deref(), .{ .loc = at, .kind = "array element" });
    }
    return joined;
}

/// The float spelling of an integer literal's text (`1` → `1.0`, `0xFF` →
/// `255.0`, `1_000` → `1000.0`); null when it does not parse.
fn floatSpelling(env: *Env, text: []const u8) InferError!?[]const u8 {
    var digits: std.ArrayListUnmanaged(u8) = .empty;
    for (text) |c| if (c != '_') try digits.append(env.arena, c);
    const v = std.fmt.parseInt(i128, digits.items, 0) catch return null;
    return try std.fmt.allocPrint(env.arena, "{d}.0", .{v});
}

/// Two arm types agree (and are unified) when either is still a type
/// variable, both name the same type constructor with the same arity, or both
/// are function types — the join of `case` arms, `if` branches and array
/// elements. A function is never a union member beside another function
/// (nothing could call `fn | fn`), so two of them unify structurally: the
/// same arity, unifiable parameters and return, and any difference is the
/// located mismatch at the second (rows 28/31 of `language-gaps.md`).
fn caseArmTypesAgree(a: *T.Type, b: *T.Type) bool {
    const da = a.deref();
    const db = b.deref();
    if (da.* == .typeVar or db.* == .typeVar) return true;
    if (da.* == .func and db.* == .func) return true;
    if (da.* == .named and db.* == .named) {
        return std.mem.eql(u8, da.named.name, db.named.name) and da.named.args.len == db.named.args.len;
    }
    return false;
}

/// Infer type for function definition expressions (lambdas and anonymous functions)
/// Decision 370 (2) — `decl.addMember(name, fn(self: T) -> R { … })` in a
/// decorator's body. `name` is a `string` the body computes; the function is
/// the member the annotated type receives, so it is typed here as the
/// program's code: its parameters and return as written (the decorator's type
/// parameters in scope), each `comptime x: @Expr<T>` parameter read as the `T`
/// its argument is — spliced where the member uses it (`member_fn.render`) —,
/// the handle the annotated type as code, typed by the `syntax decl`
/// parameter's declared type (decision 716), and a local of the body the
/// literal of its value (575 (4)). A second argument that is not a function
/// expression written at the call is `decorator-member-not-fn`, a parameter
/// without a type `decorator-member-fn-untyped`.
fn inferMemberFnCall(env: *Env, call: anytype, loc: ast.Loc) InferError!TypedExpr {
    const fnArg = call.args[1].value.*;
    if (fnArg != .function or fnArg.function.kind.syntax != .fnExpr) {
        env.lastError = TypeError.custom(
            diagnostics.decorator_member_not_fn ++ ": `decl.addMember(name, f)` takes the member as a function expression written at the call",
            "Write the member there — `decl.addMember(\"validate\", fn(self: T) -> R { … })` —: its body is where the decorator's parameters are spliced (decision 370 (2)).",
        ).withLoc(fnArg.getLoc());
        return error.TypeError;
    }
    const func = fnArg.function;
    try refuseMemberFnShape(env, func, env.currentParams, env.decoratorBody orelse &.{});

    // `name`: a string the body computes.
    const nameTyped = try env.arena.create(TypedExpr);
    nameTyped.* = try inferExprTyped(env, call.args[0].value.*);
    try unifyAt(env, try env.namedType("string"), nameTyped.getType(), call.args[0].value.getLoc());

    // The member's signature, the decorator's type parameters in scope.
    const generics: std.StringHashMap(*T.Type) = if (env.fnGenericMap) |gm| gm.* else std.StringHashMap(*T.Type).init(env.arena);
    const params = try env.arena.alloc(*T.Type, func.kind.paramTypes.len);
    for (func.kind.paramTypes, 0..) |pt, i| params[i] = try resolveTypeRefInContext(env, pt, generics);
    const ret = if (func.kind.returnType) |rt| try resolveTypeRefInContext(env, rt, generics) else try env.namedType("void");
    const expected = try env.funcType(params, ret);

    // Each `@Expr<T>` parameter is its `T` in the member; nothing of the
    // decorator's own `x.value` / `x.fail` surface reaches it.
    const Rebound = struct { name: []const u8, was: *T.Type };
    var rebound: std.ArrayListUnmanaged(Rebound) = .empty;
    for (env.currentParams) |p| if (p.exprWrapped) {
        const was = env.lookup(p.name) orelse continue;
        const d = was.deref();
        const inner = if (d.* == .named and std.mem.eql(u8, d.named.name, ast.expr_type_name) and d.named.args.len == 1) d.named.args[0] else continue;
        try rebound.append(env.arena, .{ .name = p.name, .was = was });
        try env.bind(p.name, inner);
    };
    // Decision 716 (3) — the handle is the annotated declaration as code,
    // typed by its contract, as in an executor.
    if (env.currentParams.len > 0) {
        const h = env.currentParams[0].name;
        const already = for (rebound.items) |r| {
            if (std.mem.eql(u8, r.name, h)) break true;
        } else false;
        if (!already) if (env.lookup(h)) |was| {
            try rebound.append(env.arena, .{ .name = h, .was = was });
            try env.bind(h, try handleContract(env, was));
        };
    }
    const savedParams = env.currentParams;
    const savedInDecorator = env.inDecoratorFn;
    const savedBody = env.decoratorBody;
    env.currentParams = &.{};
    env.inDecoratorFn = false;
    env.decoratorBody = null;
    env.memberFnAt = func.loc;
    const savedMemberGenerics = env.memberFnGenerics;
    env.memberFnGenerics = &generics;
    const fnTyped = try env.arena.create(TypedExpr);
    fnTyped.* = blk: {
        defer {
            env.currentParams = savedParams;
            env.inDecoratorFn = savedInDecorator;
            env.decoratorBody = savedBody;
            env.memberFnAt = null;
            env.memberFnGenerics = savedMemberGenerics;
        }
        break :blk try inferFunctionExprExpected(env, func, func.loc, expected, false);
    };
    for (rebound.items) |r| try env.bind(r.name, r.was);

    const recv = try env.arena.create(TypedExpr);
    recv.* = try inferExprTyped(env, call.receiver.?.*);
    const typedArgs = try env.arena.alloc(ast.CallArgOf(.typed), 2);
    typedArgs[0] = .{ .label = call.args[0].label, .value = nameTyped };
    typedArgs[1] = .{ .label = call.args[1].label, .value = fnTyped };
    return TypedExpr{ .call = .{ .loc = loc, .type_ = try env.namedType("void"), .kind = .{ .call = .{
        .receiver = recv,
        .callee = memberFn.add_member,
        .is_builtin = false,
        .args = typedArgs,
        .trailing = &.{},
    } } } };
}

/// Decision 575 (3) — `compiler.init(f)` in a decorator's body (read onto
/// the handle, `decl.compile(f)`). `f` is the executor, a function written at
/// the call that takes nothing; it is the program's code, typed here as a
/// member function is (`inferMemberFnCall`): each `comptime x: T` parameter read as
/// its `T`, the body's locals read as the literals of their values (the tree
/// rule, 575 (4); a local that is no literal is `decorator-member-local-not-literal`, 759). The
/// executor is checked against `fn()` (decision 409): a tail that answers a
/// value is refused at it.
fn inferCompileCall(env: *Env, call: anytype, loc: ast.Loc) InferError!TypedExpr {
    const func = call.args[0].value.function;
    try refuseCaptures(env, func, env.currentParams, env.decoratorBody orelse &.{}, true, true);
    const expected = try env.funcType(&.{}, try env.freshVar());

    // Each `syntax x: T` parameter (a tree) is its `T` in the executor.
    const Rebound = struct { name: []const u8, was: *T.Type };
    var rebound: std.ArrayListUnmanaged(Rebound) = .empty;
    for (env.currentParams) |p| if (p.exprWrapped) {
        const was = env.lookup(p.name) orelse continue;
        const d = was.deref();
        const inner = if (d.* == .named and std.mem.eql(u8, d.named.name, ast.expr_type_name) and d.named.args.len == 1) d.named.args[0] else continue;
        try rebound.append(env.arena, .{ .name = p.name, .was = was });
        try env.bind(p.name, inner);
    };
    // Decisions 581 (2), 716 — the handle is the annotated declaration as
    // code, typed once, here, by the `syntax decl` parameter's declared type:
    // the contract every annotated declaration meets (`checkDecoratorArgs`).
    if (env.currentParams.len > 0) {
        const h = env.currentParams[0].name;
        const already = for (rebound.items) |r| {
            if (std.mem.eql(u8, r.name, h)) break true;
        } else false;
        if (!already) if (env.lookup(h)) |was| {
            try rebound.append(env.arena, .{ .name = h, .was = was });
            try env.bind(h, try handleContract(env, was));
        };
    }
    const savedParams = env.currentParams;
    const savedInDecorator = env.inDecoratorFn;
    const savedBody = env.decoratorBody;
    env.currentParams = &.{};
    env.inDecoratorFn = false;
    env.decoratorBody = null;
    // Decisions 787, 792 (7) — `Module.run()` is written here.
    env.initArgDepth += 1;
    const fnTyped = try env.arena.create(TypedExpr);
    fnTyped.* = blk: {
        defer {
            env.currentParams = savedParams;
            env.inDecoratorFn = savedInDecorator;
            env.decoratorBody = savedBody;
            env.initArgDepth -= 1;
        }
        break :blk try inferFunctionExprExpected(env, func, func.loc, expected, false);
    };
    {
        var tailTy: ?*T.Type = null;
        // The typed body may end with one statement the written one lacks (the
        // bare `return` that discards a `;`-ended tail, decision 541): pair by
        // index over the written statements.
        for (func.kind.body, 0..) |s, k| if (s.tail == .value) {
            tailTy = fnTyped.function.kind.body[k].expr.getType();
        };
        try refuseValueTailInVoid(env, "the executor", func.kind.body, tailTy);
    }
    for (rebound.items) |r| try env.bind(r.name, r.was);

    const recv = try env.arena.create(TypedExpr);
    recv.* = try inferExprTyped(env, call.receiver.?.*);
    const typedArgs = try env.arena.alloc(ast.CallArgOf(.typed), 1);
    typedArgs[0] = .{ .label = call.args[0].label, .value = fnTyped };
    return TypedExpr{ .call = .{ .loc = loc, .type_ = try env.namedType("void"), .kind = .{ .call = .{
        .receiver = recv,
        .callee = memberFn.compile_name,
        .is_builtin = false,
        .args = typedArgs,
        .trailing = &.{},
    } } } };
}

/// Decision 370 (2) — what a member function is, whoever runs first: the
/// checker over the decorator's body (`inferMemberFnCall`), or the annotation
/// of the decorator's own module, which runs it before any body of the module
/// is inferred (`memberFnSource`). Every parameter typed
/// (`decorator-member-fn-untyped`), refused where it is written; the handle
/// is the annotated type as code (decision 716 (3)) and a local of the body
/// its literal (575 (4)).
fn refuseMemberFnShape(env: *Env, func: ast.FunctionExpr, params: []const ast.Param, body: []const ast.Stmt) InferError!void {
    if (func.kind.paramTypes.len != func.kind.params.len) {
        const msg = try std.fmt.allocPrint(env.arena, "{s}: the member's parameter `{s}` has no type", .{ diagnostics.decorator_member_fn_untyped, func.kind.params[0] });
        env.lastError = TypeError.custom(msg, "A member is written as in the type's body: `fn(self: T, x: i32) -> R { … }`, every parameter typed (decision 370 (2)).").withLoc(func.loc);
        return error.TypeError;
    }
    return refuseCaptures(env, func, params, body, true, true);
}

/// Decision 716 — the type the `syntax decl` handle has in a tree the
/// decorator writes: the parameter's declared type, the contract each
/// annotated declaration meets — `unknown` (no member), a behavior (its
/// members), a function type, a type parameter. `handle` is the handle's
/// type in the body (`__Decl` over that contract).
fn handleContract(env: *Env, handle: *T.Type) InferError!*T.Type {
    const d = handle.deref();
    if (d.* == .named and std.mem.eql(u8, d.named.name, ast.decl_type_name) and d.named.args.len == 1) return d.named.args[0];
    return env.namedType("unknown");
}

/// Decision 316 — a wrapper reads no handle and no local of the decorator's
/// body (`decorator-member-captures`), refused where it is read.
/// Decision 575 (4), the tree rule — a member holds the body's locals as
/// literals (`member_fn.capturedLocals`): `locals` admits them; a wrapper holds
/// only the hoisted `compiler.*` reads (`capturedBuildReads`, decision 642), and
/// neither reads the handle.
/// Decisions 581 (2), 716 (3) — an executor and a member read it (`handle`):
/// there it is the annotated declaration as code, typed by its contract
/// (`handleContract`).
fn refuseCaptures(env: *Env, func: ast.FunctionExpr, params: []const ast.Param, body: []const ast.Stmt, locals: bool, handle: bool) InferError!void {
    const declName = if (params.len > 0) params[0].name else "";
    const decoratorLocals = try memberFn.boundNames(env.arena, &.{}, body);
    for (try memberFn.freeNames(env.arena, func)) |n| {
        const isExprParam = for (params) |p| {
            if (p.exprWrapped and std.mem.eql(u8, p.name, n.name)) break true;
        } else false;
        if (isExprParam) continue;
        const isHandle = std.mem.eql(u8, n.name, declName);
        if (isHandle and handle) continue;
        if (!isHandle and (locals or !decoratorLocals.contains(n.name) or std.mem.startsWith(u8, n.name, memberFn.build_read_prefix))) continue;
        const msg = if (isHandle)
            try std.fmt.allocPrint(env.arena, "{s}: the wrapper reads `{s}`, the decorator's handle, which exists only while the program compiles", .{ diagnostics.decorator_member_captures, n.name })
        else
            try std.fmt.allocPrint(env.arena, "{s}: the member reads `{s}`, a local of the decorator's body, which exists only while the program compiles", .{ diagnostics.decorator_member_captures, n.name });
        env.lastError = TypeError.custom(msg, "A member uses the decorator's parameters — each `@Expr` is spliced where it was written — and what its own body declares (decision 370 (2)).").withLoc(n.loc);
        return error.TypeError;
    }
}

fn inferFunctionExpr(env: *Env, func: ast.FunctionExprOf(.untyped), loc: ast.Loc) InferError!TypedExpr {
    if (func.kind.syntax == .asyncBlock) return inferAsyncBlock(env, func, loc);
    try refuseFnExprReturnMissing(env, func.kind, loc);
    // Decision 357 — a lambda runs when it is called, if ever: no `use` in it.
    const prevUseConstruct = enterUseConstruct(env, "a lambda");
    defer env.useConstruct = prevUseConstruct;
    const prevEarlyExit = env.earlyExitLine;
    env.earlyExitLine = null;
    defer env.earlyExitLine = prevEarlyExit;
    // Decision 147 — a lambda in a position that expects a FALLIBLE function
    // (an argument of a `fn(x: T) -> @Result<U, E>` parameter) takes that
    // channel; any other expectation stays the hint it was.
    const fallibleExpected: ?*T.Type = blk: {
        const e = env.expectedType orelse break :blk null;
        const d = e.deref();
        if (d.* != .func) break :blk null;
        if (!isResultType(d.func.ret)) break :blk null;
        break :blk e;
    };
    // Decision 408 — a typed function expression is checked against the
    // position's function type whatever its return. Decision 553 (4) — a
    // marked lambda is too (147).
    const typedExpected = if ((func.kind.syntax == .fnExpr and func.kind.isTyped()) or func.kind.marker != null) env.expectedType else null;
    // Decision 328 — a lambda written where nothing expects a type (an
    // immediate call's callee; an unannotated `val` is refused, 583): its
    // parameters are typed only by the call that applies it.
    env.lambdaWithoutExpected = env.expectedType == null;
    env.expectedType = null;
    return inferFunctionExprExpected(env, func, loc, typedExpected orelse fallibleExpected, false);
}

/// Decision 553 (4), 147 — a marked lambda (or untyped `fn` expression) is
/// checked against its expected function type: with none it is
/// `marker-lambda-without-expected-type`, and an expected return that is
/// another type than the marker's wrapper is `marker-type-mismatch`, both at
/// the marker. An expected return still free (a type parameter) agrees: the
/// marked body makes the wrapper. A typed `fn` expression's marker was checked
/// against its written return by the parser.
fn checkLambdaMarker(env: *Env, func: ast.FunctionExprOf(.untyped), loc: ast.Loc, expected: ?*T.Type) InferError!void {
    const m = func.kind.marker orelse return;
    if (func.kind.returnType != null) return;
    const want: ?*T.Type = blk: {
        const e = expected orelse break :blk null;
        const d = e.deref();
        if (d.isUnbound()) break :blk null;
        break :blk d;
    };
    const w = want orelse {
        env.lastError = TypeError.custom(
            try std.fmt.allocPrint(env.arena, "{s}: a lambda marked `{s}` needs the function type it is written for", .{ diagnostics.marker_lambda_without_expected_type, m.markerWord() }),
            try std.fmt.allocPrint(env.arena, "A marked lambda takes its type from where it is written (decisions 147, 553): annotate the binding (`val f: fn(x: i32) -> {s}<i32> = …`) or pass it where a function type is expected.", .{m.returnWrapper()}),
        ).withLoc(loc);
        return error.TypeError;
    };
    // Not a function type: the ordinary unification names the disagreement.
    if (w.* != .func) return;
    const r = w.func.ret.deref();
    if (r.isUnbound()) return;
    if (r.* == .named and std.mem.eql(u8, r.named.name, m.returnWrapper())) return;
    env.lastError = TypeError.custom(
        try std.fmt.allocPrint(env.arena, "{s}: a lambda marked `{s}` answers `{s}<…>`, and the function type it is written for returns `{s}`", .{
            diagnostics.marker_type_mismatch,
            m.markerWord(),
            m.returnWrapper(),
            try snapshotMod.typeSignatureOf(env.arena, w.func.ret),
        }),
        try std.fmt.allocPrint(env.arena, "Each marker answers its wrapper (decision 553): `async` an `Async`, `iter` an `Iter`, `async iter` an `AsyncIter`, `component` a `Component`. Write the marker the expected type names, or drop it.", .{}),
    ).withLoc(loc);
    return error.TypeError;
}

/// Decision 124 — `async { … }`: a closed block worth `@Async<T>`, legal in any
/// function. `T` comes from the block's `return`s (a `return` leaves the
/// BLOCK, decision 119); when the body has `throw` / `try` of its own
/// (`ast.bodyFails`) the value becomes `@Result<U, E>` on its own, `E` from
/// them — two that do not unify are `gen-infer-conflicting-errors`. An
/// expected `@Async<X>` (an annotated `val`) pins the value: `X` a `@Result`
/// opens the fallible channel with its `E`, any other `X` closes it, so a `try`
/// in the body is then a located refusal. The body starts a new capability
/// context: it awaits (it IS a Async), never `use`s (not the `@Component`
/// body) and never yields; the enclosing labels are closed.
fn inferAsyncBlock(env: *Env, func: ast.FunctionExprOf(.untyped), loc: ast.Loc) InferError!TypedExpr {
    // Decision 375 — a body that writes `async { … }` is asynchronous.
    if (env.hookBuilder) |b| b.is_async = true;
    const fk = func.kind;
    // The expected `@Async<X>`, when the position says one (`val t: @Async<i32> = async { … }`).
    const expectedValue: ?*T.Type = blk: {
        const want = (env.expectedType orelse break :blk null).deref();
        if (want.* != .named or !std.mem.eql(u8, want.named.name, "Async") or want.named.args.len != 1) break :blk null;
        break :blk want.named.args[0];
    };
    var errTy: ?*T.Type = null;
    var value: *T.Type = undefined;
    var target: *T.Type = undefined;
    if (expectedValue) |ev| {
        value = ev;
        const d = ev.deref();
        if (d.* == .named and std.mem.eql(u8, d.named.name, "Result") and d.named.args.len >= 2) {
            errTy = d.named.args[1];
            target = d.named.args[0];
        } else target = ev;
    } else if (ast.bodyFails(fk.body)) {
        const u = try env.freshVar();
        const e = try env.freshVar();
        errTy = e;
        target = u;
        value = try env.namedTypeArgs("Result", &.{ u, e });
        try noteInferredResult(env, value, fk.body);
    } else {
        value = try env.freshVar();
        target = value;
    }
    const taskTy = try env.namedTypeArgs("Async", &.{value});

    const prevStarFn = env.starFn;
    const prevFnEffect = env.fnEffect;
    const prevThrowCtx = env.throwContext;
    // Decision 595 — a region's `try`s stop at a function's border.
    const prevTryRegion = env.tryRegion;
    env.tryRegion = null;
    defer env.tryRegion = prevTryRegion;
    const prevInContextFn = env.inContextFn;
    const prevLoopDepth = env.loopDepth;
    const prevBreakScope = env.breakScope;
    const prevClosedLabels = env.closedLabels;
    const prevAliasWrapper = env.aliasWrapper;
    const prevReturnTarget = env.returnTarget;
    const prevReturnWhole = env.returnWhole;
    const prevReturnBareIsVoid = env.returnBareIsVoid;
    const prevKeep = env.keepReturnTarget;
    const prevGenLoops = env.generatorLoopDepth;
    const prevInferredErr = env.inferredErrorScope;
    const prevLabels = try env.arena.dupe([]const u8, env.labelStack.items);
    defer {
        env.starFn = prevStarFn;
        env.fnEffect = prevFnEffect;
        env.throwContext = prevThrowCtx;
        env.inContextFn = prevInContextFn;
        env.loopDepth = prevLoopDepth;
        env.breakScope = prevBreakScope;
        env.closedLabels = prevClosedLabels;
        env.aliasWrapper = prevAliasWrapper;
        env.returnTarget = prevReturnTarget;
        env.returnWhole = prevReturnWhole;
        env.returnBareIsVoid = prevReturnBareIsVoid;
        env.keepReturnTarget = prevKeep;
        env.generatorLoopDepth = prevGenLoops;
        env.inferredErrorScope = prevInferredErr;
        env.labelStack.shrinkRetainingCapacity(0);
        env.labelStack.appendSlice(env.arena, prevLabels) catch {};
        env.asyncBlockDepth -= 1;
    }
    env.asyncBlockDepth += 1;
    env.closedLabels = prevLabels;
    env.labelStack.shrinkRetainingCapacity(0);
    env.starFn = .{ .allowsAwait = true, .allowsYield = false, .iterItem = null, .fnLabel = null, .effect = .task };
    env.fnEffect = .task;
    env.throwContext = if (errTy) |et| .{ .result = et } else .plain;
    env.inferredErrorScope = expectedValue == null and errTy != null;
    env.inContextFn = false;
    env.aliasWrapper = null;
    env.loopDepth = 0;
    env.breakScope = .none;
    env.generatorLoopDepth = 0;
    env.keepReturnTarget = false;
    env.returnTarget = target;
    env.returnWhole = taskTy;
    env.returnBareIsVoid = true;

    const bodyTyped = try inferStmtsTyped(env, fk.body);
    // Decision 432 — the block builds its `@Result`: the task it makes fails.
    if (errTy != null) try env.failingTaskBlocks.put(env.arena, loc, {});
    return TypedExpr{ .function = .{ .loc = loc, .type_ = taskTy, .kind = .{
        .syntax = .asyncBlock,
        .params = fk.params,
        .body = bodyTyped,
    } } };
}

/// Infer a lambda / anonymous-function expression. When `expected` is a
/// function type (e.g. from a `val f: fn(A, B) -> R = ...` annotation, or a
/// `fn`-typed parameter), the lambda's parameters are bound to the expected
/// parameter types *before* the body is inferred — so the body can resolve
/// member calls and operators against the annotated types — and the body's
/// result is unified with the expected return type.
///
/// `params_only` keeps the parameter half and drops the return half: the
/// lambda's return type stays free. A caller that only wants the parameters
/// typed (a builtin-primitive method's declared signature — see
/// `primMethodParamTypes`) must use it, because a body whose every path
/// `return`s types its TAIL as void while the `return`s have already fixed the
/// return target, and unifying the two would red a correct lambda
/// (`xs.map({ x -> if (c) { return a; } else { return b; } })`).
fn inferFunctionExprExpected(
    env: *Env,
    func: ast.FunctionExprOf(.untyped),
    loc: ast.Loc,
    expected: ?*T.Type,
    params_only: bool,
) InferError!TypedExpr {
    try checkLambdaMarker(env, func, loc, expected);
    try refuseFnExprReturnMissing(env, func.kind, loc);
    // Decision 408 — the typed function expression `fn(x: T, …) -> R { … }`
    // is legal in every position. The member a decorator hands to
    // `decl.addMember(name, fn…)` arrives with its written signature as
    // `expected` (`inferMemberFnCall`); anywhere else the written types are
    // the function's, checked against the position's when it has one.
    if (func.kind.syntax == .fnExpr and func.kind.isTyped()) {
        const member = if (env.memberFnAt) |at| at.eql(loc) else false;
        if (member) {
            env.memberFnAt = null;
            return inferFunctionExprExpectedInner(env, func, loc, expected, false);
        }
        const written = try writtenFnType(env, func);
        if (expected) |e| {
            const d = e.deref();
            if (d.* == .func and d.func.params.len == func.kind.params.len) {
                const agreed = if (params_only) blk: {
                    for (d.func.params, written.deref().func.params) |want, got| unifyAt(env, want, got, loc) catch |err| break :blk err;
                    break :blk {};
                } else unifyAt(env, e, written, loc);
                agreed catch |err| {
                    if (err != error.TypeError) return err;
                    // Named whole, at the expression: the position's function
                    // type against the one the expression writes.
                    const msg = try std.fmt.allocPrint(env.arena, "type mismatch: expected {s}, got {s}", .{
                        try snapshotMod.typeSignatureOf(env.arena, e),
                        try snapshotMod.typeSignatureOf(env.arena, written),
                    });
                    env.lastError = TypeError.custom(msg, "A function expression's written types are checked against its position's (decision 408): write the types it expects, or leave them out and let the position type it.").withLoc(loc);
                    return error.TypeError;
                };
            }
        }
        return inferFunctionExprExpectedInner(env, func, loc, written, false);
    }
    return inferFunctionExprExpectedInner(env, func, loc, expected, params_only);
}

/// Decision 408 — the type a typed function expression writes: its
/// parameters' types and its `-> R` (`void` when it writes none), the
/// enclosing function's type parameters in scope.
fn writtenFnType(env: *Env, func: ast.FunctionExprOf(.untyped)) InferError!*T.Type {
    const generics: std.StringHashMap(*T.Type) = if (env.fnGenericMap) |gm| gm.* else std.StringHashMap(*T.Type).init(env.arena);
    const params = try env.arena.alloc(*T.Type, func.kind.paramTypes.len);
    for (func.kind.paramTypes, 0..) |pt, i| params[i] = try resolveTypeRefInContext(env, pt, generics);
    const ret = if (func.kind.returnType) |rt| try resolveTypeRefInContext(env, rt, generics) else try env.namedType("void");
    return env.funcType(params, ret);
}

/// Whether a function expression's written `-> R` hands out a value a body
/// running off its end would not: a written type other than `void` /
/// `noreturn`, an effect wrapper aside.
fn writtenReturnHasValue(rt: ?ast.TypeRef) bool {
    const t = rt orelse return false;
    return switch (t) {
        .named => |n| !std.mem.eql(u8, n, "void") and !std.mem.eql(u8, n, "noreturn"),
        .generic => |g| !(g.is_builtin and ast.EffectKind.fromWrapperName(g.name) != null),
        else => true,
    };
}

/// Decision 541 (1) — a lambda whose last expression statement is written
/// with `;` answers nothing. Its value is discarded by a typed bare `return`
/// after it, so every backend reads a lambda that ends in a statement; a last
/// expression that is already `void` / `noreturn` (or not yet known) needs
/// nothing, and a binding, a jump, a loop and a `use` are statements anyway.
fn discardUnwrittenTail(env: *Env, body: []const ast.Stmt, typed: []ast.TypedStmt) InferError![]ast.TypedStmt {
    var i = body.len;
    while (i > 0) : (i -= 1) {
        const e = body[i - 1].expr;
        if (e == .literal and e.literal.kind == .comment) continue;
        break;
    }
    if (i == 0) return typed;
    const s = body[i - 1];
    if (s.tail != .none) return typed;
    const tailable = switch (s.expr) {
        .jump => |j| j.kind == .try_ or j.kind == .await_,
        .binding, .useHook, .loop => false,
        .literal => |lit| lit.kind != .comment,
        else => true,
    };
    if (!tailable) return typed;
    const d = typed[i - 1].expr.getType().deref();
    if (d.isNamed("void") or d.isNamed("noreturn") or d.isUnbound()) return typed;
    const out = try env.arena.alloc(ast.TypedStmt, typed.len + 1);
    @memcpy(out[0..typed.len], typed);
    out[typed.len] = .{ .expr = .{ .jump = .{
        .loc = s.expr.getLoc(),
        .type_ = try env.namedType("void"),
        .kind = .{ .@"return" = null },
    } } };
    return out;
}

fn inferFunctionExprExpectedInner(
    env: *Env,
    func: ast.FunctionExprOf(.untyped),
    loc: ast.Loc,
    expected: ?*T.Type,
    params_only: bool,
) InferError!TypedExpr {
    // Decision 357 — a lambda runs when it is called, if ever: no `use` in it.
    const prevUseConstruct = enterUseConstruct(env, "a lambda");
    defer env.useConstruct = prevUseConstruct;
    const prevEarlyExit = env.earlyExitLine;
    env.earlyExitLine = null;
    defer env.earlyExitLine = prevEarlyExit;
    if (func.kind.syntax == .asyncBlock) {
        const savedExpected = env.expectedType;
        env.expectedType = expected;
        defer env.expectedType = savedExpected;
        return inferAsyncBlock(env, func, loc);
    }
    // Decision 147 (lg-a) — a lambda's return is its expected type's: its
    // `try` / `throw` use the fallible channel of the EXPECTED return, and a
    // lambda whose expected return carries no `@Result` (or that has no
    // expected type) has none. A `case` arm's block body is not a lambda for
    // this: its `throw` is the enclosing function's (row 29), so it keeps the
    // enclosing context.
    const savedThrowCtx = env.throwContext;
    defer env.throwContext = savedThrowCtx;
    const savedInLambda = env.inLambdaBody;
    defer env.inLambdaBody = savedInLambda;
    const armBlock = env.keepReturnTarget;
    const lambdaErr: ?*T.Type = blk: {
        const e = expected orelse break :blk null;
        const d = e.deref();
        if (d.* != .func or d.func.params.len != func.kind.params.len) break :blk null;
        const r = d.func.ret.deref();
        if (r.* != .named or !std.mem.eql(u8, r.named.name, "Result") or r.named.args.len < 2) break :blk null;
        break :blk r.named.args[1];
    };
    // Decision 595 — a lambda's `try`s are its own, never an enclosing
    // region's; a `case` arm's block is the enclosing function's.
    const prevTryRegion = env.tryRegion;
    defer env.tryRegion = prevTryRegion;
    if (!armBlock) {
        env.throwContext = if (lambdaErr) |et| .{ .result = et } else .plain;
        env.inLambdaBody = true;
        env.tryRegion = null;
    }
    // Decision 148 — one lambda deeper; its writes to captured `var`s are
    // legal only in the two exempt shapes the site that infers it named.
    const savedDepth = env.lambdaDepth;
    const savedWriteOk = env.captureWriteOk;
    defer {
        env.lambdaDepth = savedDepth;
        env.captureWriteOk = savedWriteOk;
    }
    if (!armBlock) {
        env.lambdaDepth += 1;
        env.captureWriteOk = env.nextLambdaExempt;
    }
    env.nextLambdaExempt = false;

    // A nested function gets its own async/label scope: it does not inherit
    // the enclosing fn's `await`/`yield`/label context.
    const prevStarFn = env.starFn;
    const prevLabelsLen = env.labelStack.items.len;
    defer {
        env.starFn = prevStarFn;
        env.labelStack.shrinkRetainingCapacity(prevLabelsLen);
    }
    // A lambda body is another function: no loop of the enclosing body is
    // left by a `break` inside it (decision 105), and only a `case` arm's
    // block keeps the value-block scope it was opened in. A `case` arm's block
    // (and so a block `{ … }`) is no function (decision 541 (2)): the labels,
    // the loops and the generator / task scope of the enclosing function are
    // its own.
    const prevLoopDepth = env.loopDepth;
    const prevBreakScope = env.breakScope;
    if (!armBlock) {
        env.labelStack.shrinkRetainingCapacity(0);
        env.loopDepth = 0;
        if (env.breakScope != .valueBlock) env.breakScope = .none;
    }
    defer {
        env.loopDepth = prevLoopDepth;
        env.breakScope = prevBreakScope;
    }

    const fk = func.kind;
    // A lambda inside an `async { }` block is its own function again.
    const prevAsyncDepth = env.asyncBlockDepth;
    if (!armBlock) env.asyncBlockDepth = 0;
    defer env.asyncBlockDepth = prevAsyncDepth;
    const prevInferredErrLambda = env.inferredErrorScope;
    if (!armBlock) env.inferredErrorScope = false;
    defer env.inferredErrorScope = prevInferredErrLambda;
    // Anonymous function expressions never carry an effect annotation, so the
    // async/generator context is always cleared inside them. (The deprecated
    // `*fn(...)` anonymous-generator form was removed in v0.beta.19.) A
    // `case` arm's block keeps it: `await` / `yield` reach the enclosing
    // function (decision 541 (2)).
    if (!armBlock) env.starFn = null;
    // Decision 553 (1), 574 — a `{ component -> … }` lambda's body is a
    // component body, as a `component fn`'s: `use` and `await` are its, its
    // `return`s and its tail answer the `R` of the expected `@Component<R>`,
    // and its hooks are its own, not the enclosing function's node. The other
    // markers need nothing here: the parser wrote their body as the block
    // form they name, which opens its own context.
    const componentLambda = func.kind.marker == .component;
    const savedFnEffectLambda = env.fnEffect;
    const savedInContextLambda = env.inContextFn;
    const savedFnCtxLambda = env.fnContext;
    const savedHookBuilderLambda = env.hookBuilder;
    const savedFirstRenderLambda = env.firstRenderAt;
    const savedAliasWrapperLambda = env.aliasWrapper;
    defer {
        env.fnEffect = savedFnEffectLambda;
        env.inContextFn = savedInContextLambda;
        env.fnContext = savedFnCtxLambda;
        env.hookBuilder = savedHookBuilderLambda;
        env.firstRenderAt = savedFirstRenderLambda;
        env.aliasWrapper = savedAliasWrapperLambda;
    }
    // The `R` the body answers and the `@Component<R>` the lambda returns.
    var componentRenders: ?*T.Type = null;
    var componentWhole: ?*T.Type = null;
    if (componentLambda) {
        const r = try env.freshVar();
        const whole = try env.namedTypeArgs("Component", &.{r});
        if (expected) |e| {
            const d = e.deref();
            if (d.* == .func and d.func.params.len == func.kind.params.len) try unifyAt(env, d.func.ret, whole, loc);
        }
        componentRenders = r;
        componentWhole = whole;
        env.starFn = starCtxFromEffect(.component, whole, null);
        env.useConstruct = null;
        env.fnEffect = .component;
        env.inContextFn = true;
        env.fnContext = .{
            .implementsContext = true,
            .returnDisplay = try snapshotMod.typeSignatureOf(env.arena, whole),
            .annotated = true,
            .fnName = "a `component` lambda",
            .renderable = isComponentType(env, whole),
        };
        env.hookBuilder = null;
        env.firstRenderAt = null;
        env.aliasWrapper = null;
    }

    // Pull expected param/return types out of `expected`, but only when it is a
    // function type whose arity matches this lambda. This lets `val f: fn(A, B)
    // -> R = { a, b -> ... }` bind the params to A/B before the body is inferred.
    var expParams: ?[]*T.Type = null;
    var expRet: ?*T.Type = null;
    if (expected) |e| {
        const d = e.deref();
        if (d.* == .func and d.func.params.len == fk.params.len) {
            expParams = d.func.params;
            if (!params_only) expRet = d.func.ret;
        }
    }

    const withoutExpected = env.lambdaWithoutExpected;
    env.lambdaWithoutExpected = false;
    const params = try env.arena.alloc(*T.Type, fk.params.len);
    for (fk.params, 0..) |p, i| {
        params[i] = if (expParams) |ep| ep[i] else blk: {
            const v = try env.freshVar();
            // A lambda passed where a parameter receives it is typed by that
            // parameter, a free type variable of it included (`registerFilter<Rq,
            // Ch>(…, entry: fn(req: Rq, chain: Ch) -> …)`): only one no position
            // types can be left with nothing.
            if (withoutExpected) try env.freeLambdaParams.put(env.arena, v, p);
            break :blk v;
        };
        try env.bind(p, params[i]);
    }
    // C1 — a lambda's `return`s unify with the expected return type, or with
    // each other through a shared fresh var; it never inherits the enclosing
    // fn's return target.
    const savedReturnTarget = env.returnTarget;
    const savedReturnBareIsVoid = env.returnBareIsVoid;
    const savedReturnWhole = env.returnWhole;
    defer {
        env.returnTarget = savedReturnTarget;
        env.returnBareIsVoid = savedReturnBareIsVoid;
        env.returnWhole = savedReturnWhole;
    }
    // A `case` block arm keeps the enclosing fn's return target.
    const keep = env.keepReturnTarget;
    env.keepReturnTarget = false;
    if (!keep) {
        env.returnTarget = componentRenders orelse expRet orelse try env.freshVar();
        env.returnBareIsVoid = false;
        env.returnWhole = null;
        // A fallible lambda (`fn(x: T) -> @Result<U, E>` expected) returns
        // its payload: `return v` is wrapped `Ok(v)`, as in a fn body.
        if (lambdaErr != null) {
            const whole = expected.?.deref().func.ret;
            env.returnWhole = whole;
            env.returnTarget = whole.deref().named.args[0];
        }
    }
    if (!armBlock) try refuseRedeclaredBindings(env, fk.body, fk.params);
    var bodyTyped = try inferStmtsTyped(env, fk.body);
    // Decision 541 (1) — a lambda answers its last expression written without
    // `;`: with one, the expression is a statement and the lambda answers
    // nothing.
    if (fk.syntax == .lambda and !keep) bodyTyped = try discardUnwrittenTail(env, fk.body, bodyTyped);
    // Decisions 408 / 409 — a typed function expression answers the return it
    // writes: a tail written without `;` is its value (the parser made it a
    // `return`), so a body with `-> R` that can run off its end is refused,
    // and a body answering nothing takes no value from its tail.
    const typedFn = fk.syntax == .fnExpr and fk.isTyped();
    const retType = if (typedFn) blk: {
        const written = expRet orelse try env.namedType("void");
        if (writtenReturnHasValue(fk.returnType)) {
            if (stmtsMayFallThrough(env, bodyTyped)) {
                const rendered = try snapshotMod.typeNameOf(env.arena, written);
                const msg = try std.fmt.allocPrint(env.arena, "the function expression declares `-> {s}` and its body can reach its end without a `return`", .{rendered});
                env.lastError = TypeError.custom(msg, "A value leaves a function through `return`, or as its last expression written without `;` (decisions 2, 409).").withLoc(loc);
                return error.TypeError;
            }
        } else if (answersNothing(fk.returnType)) {
            var tailTy: ?*T.Type = null;
            for (fk.body, bodyTyped) |s, t| if (s.tail == .value) {
                tailTy = t.expr.getType();
            };
            try refuseValueTailInVoid(env, "the function expression", fk.body, tailTy);
        }
        break :blk written;
    } else if (lastNonComment(bodyTyped) != null) blk: {
        const tail = lastNonComment(bodyTyped).?.expr;
        // A fallible lambda's `return` / `throw` answer the expected
        // `@Result` (wrapped by the transform); its value is that type.
        if (lambdaErr != null and !keep and tail == .jump and (tail.jump.kind == .@"return" or tail.jump.kind == .throw_)) break :blk expected.?.deref().func.ret;
        if (tail == .jump and tail.jump.kind == .@"return") {
            break :blk if (tail.jump.kind.@"return") |rv| rv.getType() else try env.namedType("void");
        }
        // A `val` or an assignment is a statement: a body ending in one
        // answers nothing (`{ w -> count = count + 1; }` is a `fn(…) -> void`,
        // decision 541 (1)), never the assigned value's type.
        if (tail == .binding and fk.syntax == .lambda) break :blk try env.namedType("void");
        break :blk tail.getType();
    } else try env.namedType("void");
    if (componentLambda) {
        // Decision 574 — the body's value is the `R` it renders; the lambda
        // answers the `@Component<R>`, lowered as a `component fn`'s body
        // (`context_lower.zig`).
        const r = componentRenders.?;
        if (!typedFn) {
            if (bodyTyped.len != fk.body.len) try unifyAt(env, r, retType, loc) else try unifyAt(env, retType, r, loc);
        }
        try env.componentLambdas.put(env.arena, loc, r);
        return TypedExpr{ .function = .{ .loc = loc, .type_ = try env.funcType(params, componentWhole.?), .kind = .{
            .syntax = fk.syntax,
            .params = fk.params,
            .body = bodyTyped,
        } } };
    }
    if (!typedFn) if (expRet) |er| {
        // A lambda whose last expression ends with `;` answers nothing: say
        // what the position expected, then what the lambda answers.
        if (bodyTyped.len != fk.body.len) try unifyAt(env, er, retType, loc) else try unifyAt(env, retType, er, loc);
    };
    const funcType = try env.funcType(params, retType);
    return TypedExpr{ .function = .{ .loc = loc, .type_ = funcType, .kind = .{
        .syntax = fk.syntax,
        .params = fk.params,
        .body = bodyTyped,
    } } };
}

/// Infer type for collection expressions (arrays, tuples, ranges, case, block, grouped)
fn inferCollectionExpr(env: *Env, col: ast.CollectionExprOf(.untyped), loc: ast.Loc) InferError!TypedExpr {
    return switch (col.kind) {
        .arrayLit => |al| {
            // 00 · 01-checker — an expected `Array<T>` makes `T` the expected
            // type of every element (`val ts: Array<Token> = [.Color.Red.500];`).
            const elemExpected: ?*T.Type = blk: {
                const want = (env.expectedType orelse break :blk null).deref();
                if (want.* != .named) break :blk null;
                if (!std.mem.eql(u8, want.named.name, "array")) break :blk null;
                if (want.named.args.len != 1) break :blk null;
                break :blk want.named.args[0];
            };
            const typedElems = try env.arena.alloc(ast.TypedExpr, al.elems.len);
            for (al.elems, 0..) |elem, i| {
                typedElems[i] = try inferExprTypedExpecting(env, elem, elemExpected);
            }
            // With a BEHAVIOR as the expected element type every element meets
            // it, the way an argument meets its parameter — so
            // `val ps: Array<Plugin> = [A(…), B(…)]` takes two different
            // implementers, where unifying each element with the first one
            // refused the second (`expected A, got B`). Any other expectation
            // stays a hint (it may be a scheme's generic variable).
            const behaviorElem: ?*T.Type = if (elemExpected) |ee| (if (isBehaviorType(env, ee)) ee else null) else null;
            // An expected union is the element type: each element is one of
            // its members (`val xs: (i32 | string)[] = [1, "a"];`).
            const unionElem: ?*T.Type = if (elemExpected) |ee| (if (ee.deref().* == .union_) ee else null) else null;
            // Decision 150 (D5, §3.2) — with nothing expected, elements that
            // disagree make the union of their types, as a `case`'s arms do.
            const joins = behaviorElem == null and unionElem == null and
                (elemExpected == null or elemExpected.?.deref().* == .typeVar);
            const elemType = if (joins and typedElems.len > 1)
                try arrayLiteralJoin(env, al.elems, typedElems)
            else
                behaviorElem orelse unionElem orelse if (typedElems.len > 0) typedElems[0].getType() else try env.freshVar();
            for (typedElems) |elem| {
                // Located at the element that disagrees (01 step 9).
                try unifyArgument(env, elemType, elem.getType(), elem.getLoc());
            }
            const arrayArgs = try env.arena.alloc(*T.Type, 1);
            arrayArgs[0] = elemType;
            const arrayType = try env.namedTypeArgs("array", arrayArgs);
            return TypedExpr{ .collection = .{ .loc = loc, .type_ = arrayType, .kind = .{ .arrayLit = .{
                .elems = typedElems,
                .spread = al.spread,
                .spreadExpr = if (al.spreadExpr) |se| try makeTypedPtr(env, try inferExprTyped(env, se.*)) else null,
                .comments = al.comments,
                .commentsPerElem = al.commentsPerElem,
                .trailingComma = al.trailingComma,
            } } } };
        },

        .tupleLit => |tl| {
            const typedElems = try env.arena.alloc(ast.TypedExpr, tl.elems.len);
            const elemTypes = try env.arena.alloc(*T.Type, tl.elems.len);
            // Decision 8 §6 T1: an element that is a plain variable lends its
            // name as the element's label (`#(name, pop)`); others stay
            // unlabeled. A compiler-built literal (a lifted template value)
            // carries its labels already.
            const labels = try env.arena.alloc([]const u8, tl.elems.len);
            var anyLabel = false;
            for (tl.elems, 0..) |elem, i| {
                typedElems[i] = try inferExprTyped(env, elem);
                elemTypes[i] = typedElems[i].getType();
                labels[i] = if (tl.labels.len == tl.elems.len)
                    tl.labels[i]
                else if (elem == .identifier and elem.identifier.kind == .ident)
                    elem.identifier.kind.ident
                else
                    "";
                if (labels[i].len > 0) anyLabel = true;
            }
            const tupleType = try env.namedTypeArgs("tuple", elemTypes);
            if (anyLabel) tupleType.named.labels = labels;
            return TypedExpr{ .collection = .{ .loc = loc, .type_ = tupleType, .kind = .{ .tupleLit = .{
                .elems = typedElems,
                .comments = tl.comments,
                .commentsPerElem = tl.commentsPerElem,
            } } } };
        },

        .range => |r| {
            const startTyped = try inferExprTyped(env, r.start.*);
            const startPtr = try makeTypedPtr(env, startTyped);
            const endPtr = if (r.end) |e| try makeTypedPtr(env, try inferExprTyped(env, e.*)) else null;
            return TypedExpr{ .collection = .{ .loc = loc, .type_ = try env.namedType("Range"), .kind = .{ .range = .{
                .start = startPtr,
                .end = endPtr,
                .inclusive = r.inclusive,
            } } } };
        },

        .case => |c| {
            // Decision 525 — a block `{ … }` lands as `case true { _ { … } }`.
            const blockExpected = env.expectedType;
            if (c.isBlock) {
                try refuseBlockShape(env, c, blockExpected, loc);
                env.expectedType = null;
            }
            const asStatement = if (env.statementBlockLoc) |sl| sl.eql(loc) else false;
            const typedSubjects = try env.arena.alloc(ast.TypedExpr, c.subjects.len);
            for (c.subjects, 0..) |subj, i| {
                typedSubjects[i] = try inferExprTyped(env, subj);
            }

            // Decision 54 — the optional's pattern form. `optionalNullCaseBinder`
            // validates the whole `case` when any arm is `null` and answers the
            // binder's name; `refuseVariantPatternOverOptional` refuses the
            // spelling the decision rejected. Both run before the arms are
            // typed, so a wrong shape reds at the shape rather than inside a
            // body that was never going to mean anything.
            const subjectTy: ?*T.Type = if (typedSubjects.len == 1) typedSubjects[0].getType() else null;
            var optionalBinder: ?[]const u8 = null;
            if (subjectTy) |st| {
                optionalBinder = try optionalNullCaseBinder(env, st, c.arms, loc);
                if (optionalBinder == null) try refuseVariantPatternOverOptional(env, st, c.arms);
                try refuseShorthandOverUnknown(env, st, c.arms);
            } else for (c.arms) |arm| {
                if (isNullPattern(arm.pattern)) {
                    env.lastError = TypeError.custom(
                        "`null` is a pattern only over an optional",
                        "`case x { null { … } v { … } }` matches one `?T` subject (decision 54).",
                    ).withLoc(arm.patternLoc);
                    return error.TypeError;
                }
            }

            const typedArms = try env.arena.alloc(ast.CaseArmOf(.typed), c.arms.len);
            // Decision 357 — an arm runs on some calls only: no `use` in it.
            const prevUseConstruct = enterUseConstruct(env, "a `case` arm");
            defer env.useConstruct = prevUseConstruct;
            // An arm's block is a scope of the enclosing function: a bare
            // `break` reaches the enclosing loop, `break <value>` is refused
            // (decision 541 (3)).
            const prevBreakScope = env.breakScope;
            env.breakScope = .armBlock;
            defer env.breakScope = prevBreakScope;
            for (c.arms, 0..) |arm, i| {
                var snapshots: std.ArrayListUnmanaged(PatternBindingSnapshot) = .empty;
                defer snapshots.deinit(env.arena);
                if (optionalBinder) |binder| {
                    // The binder is the payload, narrowed (decision 54): `v` is
                    // the `T` of the `?T`, not the optional itself. The `null`
                    // arm binds nothing.
                    if (i == 1 and binder.len > 0) {
                        try saveAndBindPatternName(env, &snapshots, binder, optionalInner(subjectTy.?).?);
                    }
                } else bindCaseArmPatternNames(env, arm.pattern, typedSubjects, &snapshots) catch |err| return locateLast(env, err, arm.patternLoc);
                if (typedSubjects.len == 1) try checkTypePatternArgs(env, arm, typedSubjects[0].getType());
                if (typedSubjects.len == 1) {
                    try noteResolvedPattern(env, arm.pattern, typedSubjects[0].getType(), arm.patternLoc);
                    try noteResultPattern(env, arm.pattern, typedSubjects[0].getType(), arm.patternLoc);
                }

                // A guard clause must type-check to a boolean, with the
                // pattern's bindings in scope.
                var guardTyped: ?ast.TypedExpr = null;
                if (arm.guard) |g| {
                    const gt = inferExprTyped(env, g) catch |err| {
                        try restorePatternBindings(env, snapshots.items);
                        return err;
                    };
                    unifyAt(env, gt.getType(), try env.namedType("bool"), g.getLoc()) catch |err| {
                        try restorePatternBindings(env, snapshots.items);
                        return err;
                    };
                    guardTyped = gt;
                }

                // A block arm (`_ -> { … }`) is a zero-param lambda in the AST,
                // but its `return`s leave the enclosing fn, not the block. So do
                // a decision-8 arm's: `{ n -> … }` is an arm body too, not a
                // function value the arm happens to produce.
                env.keepReturnTarget = isArmBodyLambda(arm.body);
                // §5.1 P1/P5 — `{ n -> … }` binds the WHOLE matched value,
                // already narrowed by this arm's pattern. Its parameter is not a
                // fresh variable: it is the subject. Passing it as the expected
                // parameter type binds it before the body is inferred, so the
                // body resolves methods and operators against the real type.
                const bodyTyped = inferCaseArmBody(env, arm, typedSubjects) catch |err| {
                    env.keepReturnTarget = false;
                    try restorePatternBindings(env, snapshots.items);
                    return err;
                };
                env.keepReturnTarget = false;
                try restorePatternBindings(env, snapshots.items);
                // Decision 810 (3) — a type pattern naming a behavior is
                // lowered as `is` lowers one (`behaviorTestRef`).
                if (typedSubjects.len == 1 and arm.pattern == .ident and typePatternName(env, arm.pattern, typedSubjects[0].getType()) != null) {
                    const ref = try behaviorTestRef(env, .{ .named = arm.pattern.ident });
                    if (ast.behaviorTestName(ref) != null) try env.behaviorTests.put(env.arena, arm.patternLoc, ref.named);
                }
                typedArms[i] = .{
                    .pattern = arm.pattern,
                    .body = bodyTyped,
                    .guard = guardTyped,
                    .emptyLinesBefore = arm.emptyLinesBefore,
                };
            }

            // A single-subject `case` on an enum or string must cover every
            // possibility (or carry a wildcard), and no arm may be unreachable.
            // Decision 54's form covers its `?T` by construction — `null` and a
            // binder are the two halves of an optional — and its `null` arm is
            // not a catch-all, so the walk would read it as uncovered.
            if (typedSubjects.len == 1 and optionalBinder == null) {
                try checkCaseArmArity(env, typedSubjects[0].getType(), c.arms);
                try checkCaseExhaustiveness(env, typedSubjects[0].getType(), c.arms, loc);
            }
            if (optionalBinder) |binder| try env.optionalNullCases.put(loc, binder);
            // C2a — the `case` is typed from its arms: arms that agree unify,
            // arms of different types make a union (decision 8 §3.2). A jump arm
            // (`return`/`throw`/`break`/`continue`) and a statement arm (`void`, a
            // block without `break <value>`) contribute nothing.
            const armTypes = try env.arena.alloc(?*T.Type, typedArms.len);
            const caseType = caseTypeFromArms(env, typedArms, armTypes) catch |err| return locateLast(env, err, loc);
            // Decision 525 — a `case` used as a value answers a value from
            // every arm that does not leave: an arm whose last expression is
            // written with `;` answers nothing.
            if (!asStatement and !c.isBlock and !caseType.deref().isNamed("void")) {
                for (typedArms, 0..) |arm, i| if (armAnswersNothing(arm.body)) {
                    env.lastError = TypeError.custom(
                        diagnostics.case_arm_no_value ++ ": this arm of a `case` used as a value answers nothing",
                        "An arm's value is its last expression written without `;` (decision 525): drop the `;`, or end the arm with a `return` / `throw`.",
                    ).withLoc(c.arms[i].patternLoc);
                    return error.TypeError;
                };
            }
            if (c.isBlock) {
                try env.blockLocs.put(env.arena, loc, {});
                if (caseType.deref().isNamed("void")) if (blockExpected) |want| if (want.deref().isNamed("unknown")) {
                    env.lastError = TypeError.custom(
                        diagnostics.block_void_value ++ ": a block whose value is `void` is handed where a value is expected",
                        "A block's value is its last expression written without `;` (decision 525).",
                    ).withLoc(loc);
                    return error.TypeError;
                };
            }
            if (caseType.deref().* == .union_) {
                try env.unionOrigins.put(env.arena, caseType.deref(), .{ .loc = loc, .kind = "case" });
                try env.unionValues.put(env.arena, loc, .{ .type_ = caseType, .arms = armTypes });
            }
            return TypedExpr{ .collection = .{ .loc = loc, .type_ = caseType, .kind = .{ .case = .{
                .subjects = typedSubjects,
                .arms = typedArms,
                .trailingComments = c.trailingComments,
            } } } };
        },

        .grouped => |e| {
            return try inferExprTyped(env, e.*);
        },

        .behaviorLit => |il| {
            // Interface literal: @InterfaceName(field: value, …).
            // Each field is typed independently; the result type is the named interface.
            const typedFields = try env.arena.alloc(ast.RecordLitFieldOf(.typed), il.fields.len);
            for (il.fields, 0..) |f, i| {
                const typedValue = try inferExprTyped(env, f.value.*);
                typedFields[i] = .{ .name = f.name, .value = try makeTypedPtr(env, typedValue) };
            }
            const ifaceTy = try env.namedType(il.name);
            return TypedExpr{ .collection = .{ .loc = loc, .type_ = ifaceTy, .kind = .{ .behaviorLit = .{
                .name = il.name,
                .fields = typedFields,
            } } } };
        },
    };
}

/// Decisions 266, 331 — a `comptime` is evaluated at compile time everywhere,
/// independent of the target. One `eval.zig` folds (`errorMod.isFoldable`:
/// literals, operators, the block's own locals, `if`, `break`) is answered
/// here; any other — a call, a loop, a lambda, a record — runs on the comptime
/// runtime (`block_eval.zig`) and its value is lifted. Either way the value is
/// recorded in `env.srcRewrites` under the node's loc; the transform splices
/// it in place of the node in every body it walks (`transform.zig`
/// `rewriteExpr`) and in a module-level `val` (`transform.zig`'s phase 2), so
/// no backend meets a `comptime`. The lifted value is not inferred again: it
/// is the value of a node already typed (the `comptime`'s type is its type),
/// and every function it carries is the node the block wrote — the lambda or
/// the identifier inference already walked, its lowerings recorded under its
/// own locations.
/// Tooling that runs no comptime runtime (`env.templateEval` null) leaves a
/// node the folder cannot read as it was.
fn foldBodyComptime(env: *Env, ct: ast.ComptimeExprOf(.untyped), typed: TypedExpr, loc: ast.Loc) InferError!void {
    // Decision 332 — a `bigint` has no compile-time value yet: the folder and
    // the comptime runtimes hold a 64-bit integer, and a value past it was
    // refused unlocated or read back wrong. Refused at the `comptime`.
    if (unifyMod.mentionsBigint(typed.getType())) {
        env.lastError = TypeError.custom(
            diagnostics.comptime_bigint ++ ": a `bigint` is not computed at compile time yet",
            "The compile-time evaluator holds a 64-bit integer (decision 332, front 01-compiler/139): compute the `bigint` when the program runs — drop the `comptime`.",
        ).withLoc(loc);
        return error.TypeError;
    }
    if (errorMod.isFoldable(.{ .comptime_ = ct })) {
        const folded = evalMod.foldToExpr(env.arena, typed, loc) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            error.UnsupportedComptimeValue => null,
        };
        if (folded) |f| return env.srcRewrites.put(loc, f);
    }
    if (try blockEval.runtimeRead(env, ct)) |read| {
        env.lastError = TypeError.custom(
            try std.fmt.allocPrint(env.arena, "expression cannot be evaluated at compile time: '{s}' is a runtime identifier", .{read.name}),
            "A `comptime` runs while the program is compiled (decision 331): it reads its own locals, literals, functions and types — not a local, a parameter or a module-level `val`, which exist only when the program runs.",
        ).withLoc(read.loc);
        return error.TypeError;
    }
    const ctx = env.templateEval orelse return;
    const prepared = try blockEval.prepare(env, ct);
    var support = try blockEval.collectSupport(env, prepared);
    // Decision 364 — a reached function's `comptime x: @Expr<T>` holds the
    // argument's value in `x` where it runs (`syntax_param.zig`): `x.value` is
    // `x` (376's `comptime campos("a,b")`).
    {
        const erased = try env.arena.alloc(ast.FnDecl, support.fns.len);
        for (support.fns, 0..) |f, i| erased[i] = try syntaxParam.eraseFn(env.arena, f, false);
        support.fns = erased;
    }
    if (try blockEval.unexpandedTemplateCall(env, prepared, support)) |msg| {
        env.lastError = TypeError.custom(msg, "A template call is expanded where it is inferred (01-compiler/14 step 8); a `comptime` carries its expansion.").withLoc(loc);
        return error.TypeError;
    }
    if (try blockEval.unresolvedSectionPath(env, support)) |msg| {
        env.lastError = TypeError.custom(msg, "A section path is resolved where it is inferred (`conformance/docs.md` § Sections of an enum); a `comptime` carries the resolved constructor.").withLoc(loc);
        return error.TypeError;
    }
    if (try blockEval.useReached(env, prepared, support)) |msg| {
        env.lastError = TypeError.custom(msg, "A `use` reads its provider in a render tree; compute the value in the program, below the render's provider, or reach what the `comptime` needs through its arguments (01-compiler/14 question `14s8-e`).").withLoc(loc);
        return error.TypeError;
    }
    const printed_from = env.buildOutput.items.len;
    const outcome = blockEval.evaluate(env.arena, ctx.io, env.modulePath, prepared, support, &env.comptimeTraces, &env.buildOutput) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        error.EvalFailed => {
            env.lastError = TypeError.custom(
                "the comptime evaluator failed to run",
                "A `comptime` runs on the wasm comptime runtime inside the compiler at build time (decisions 331, 434); this failure is the compiler's, not the body's — report it.",
            ).withLoc(loc);
            return error.TypeError;
        },
    };
    if (env.buildOutput.items.len > printed_from) try env.buildRuns.append(env.arena, .{ .start = printed_from, .len = env.buildOutput.items.len - printed_from });
    const value = switch (outcome) {
        .value => |v| v,
        .err => |msg| {
            if (if (comptimeTail(ct)) |tail| try blockEval.badarithRefusal(env, msg, tail, &.{}, support) else null) |r| {
                env.lastError = TypeError.custom(r.message, "Raised while the `comptime` ran at build time (decisions 331, 472): an arithmetic error reads as Erlang's `badarith`, whatever the target.").withLoc(r.loc);
                return error.TypeError;
            }
            env.lastError = TypeError.custom(msg, "Raised while the `comptime` ran at build time (decision 331).").withLoc(loc);
            return error.TypeError;
        },
        // Decisions 451 (3), 532 — located at the call that raised, in its own
        // file; every call of the chain is a `called from`, down to the
        // `comptime` that ran it.
        .raised => |r| {
            if (if (comptimeTail(ct)) |tail| try blockEval.badarithRefusal(env, r.message, tail, r.frames, support) else null) |br| {
                env.lastError = try blockEval.raisedError(env, br.message, "Raised while the `comptime` ran at build time (decisions 331, 472): an arithmetic error reads as Erlang's `badarith`, whatever the target.", r.frames, loc);
                return error.TypeError;
            }
            env.lastError = try blockEval.raisedError(env, r.message, "Raised while the `comptime` ran at build time (decisions 331, 451, 532).", r.frames, loc);
            return error.TypeError;
        },
    };
    // Decision 793 (5) — a `comptime { … }` that answers `void` (a block of
    // prints) leaves nothing in the program: its prints are the build's
    // output, written above.
    if (isVoidComptime(typed.getType())) {
        const empty = try env.arena.create(ast.Expr);
        empty.* = exprsMod.makeBlockExpr(env.arena, loc, &.{}) catch return error.OutOfMemory;
        return env.srcRewrites.put(loc, empty);
    }
    const lifted = switch (try blockEval.lift(env, prepared, support, value, typed.getType(), loc)) {
        .expr => |e| e,
        .refused => |msg| {
            env.lastError = TypeError.custom(
                msg,
                "A `comptime`'s value is written into the program (decision 331): a literal, an array, a tuple, a record, a declared function, or a lambda that reads nothing the block declares.",
            ).withLoc(loc);
            return error.TypeError;
        },
    };
    try env.srcRewrites.put(loc, lifted);
}

/// Whether a `comptime`'s type is `void` (decision 793 (5)).
fn isVoidComptime(t: *T.Type) bool {
    const d = t.deref();
    return d.* == .named and std.mem.eql(u8, d.named.name, "void");
}

/// The expression a `comptime` answers, for naming it in a refusal: the
/// expression of `comptime e`, the value of a block's last `break` (its tail,
/// decision 525) — null for a block that answers none. A block is never read
/// as an expression (decision 720's `comptime { val f = clock.nowMillis; f() }`).
fn comptimeTail(ct: ast.ComptimeExprOf(.untyped)) ?ast.Expr {
    return switch (ct.kind) {
        .comptimeExpr => |e| e.*,
        .comptimeBlock => |cb| blk: {
            var i = cb.body.len;
            while (i > 0) {
                i -= 1;
                const e = cb.body[i].expr;
                if (e == .jump and e.jump.kind == .@"break") if (e.jump.kind.@"break".value) |v| break :blk v.*;
            }
            break :blk null;
        },
        else => null,
    };
}

/// Infer type for comptime expressions (comptime, assert, assertPattern).
fn inferComptimeExpr(env: *Env, ct: ast.ComptimeExprOf(.untyped), loc: ast.Loc) InferError!TypedExpr {
    return switch (ct.kind) {
        .comptimeExpr => |e| {
            env.comptimeDepth += 1;
            const typed = inferExprTyped(env, e.*) catch |err| {
                env.comptimeDepth -= 1;
                return err;
            };
            env.comptimeDepth -= 1;
            const typedPtr = try makeTypedPtr(env, typed);
            const node = TypedExpr{ .comptime_ = .{ .loc = loc, .type_ = typed.getType(), .kind = .{ .comptimeExpr = typedPtr } } };
            // Decision 395 (3) — `comptime @typeInfo(X).metaAll(C)`: the
            // checker answered the read at build (its constructors written
            // back), so the list is the build constant; nothing runs on the
            // comptime runtime, and each `@Expr` field runs with the program.
            if (isTypedMetaRead(e.*)) {
                if (env.srcRewrites.get(e.getLoc())) |answer| try env.srcRewrites.put(loc, answer);
                return node;
            }
            try foldBodyComptime(env, ct, node, loc);
            return node;
        },

        .comptimeBlock => |cb| {
            // Decision 808 (4) — a block that calls a function writing
            // `compiler.init`: its lines run at build, each executor's body
            // written where the block is.
            if (try expandCall.expandComptimeBlock(env, cb.body, loc)) |expanded| return expanded;
            // Decision 525 — the block's value is its tail (the parser wrapped
            // it in the block's `break`); a written `break <value>` is refused.
            if (blockBreakValue(cb.body)) |at| try refuseBlockBreak(env, at);
            const prevBreakScope = env.breakScope;
            env.breakScope = .valueBlock;
            defer env.breakScope = prevBreakScope;
            env.comptimeDepth += 1;
            const typedBody = inferStmtsTyped(env, cb.body) catch |err| {
                env.comptimeDepth -= 1;
                return err;
            };
            env.comptimeDepth -= 1;
            // C2b — a `comptime { … }` block's value is its `break <value>`
            // (`eval.zig` `blockValue`'s rule), `void` when there is none.
            const bodyType = blk: {
                var found: ?*T.Type = null;
                for (typedBody) |st| {
                    if (st.expr != .jump) continue;
                    switch (st.expr.jump.kind) {
                        .@"break" => |b| if (b.value) |v| {
                            if (found) |f| try unifyAt(env, f, v.getType(), v.getLoc()) else found = v.getType();
                        },
                        else => {},
                    }
                }
                break :blk found orelse try env.namedType("void");
            };
            const node = TypedExpr{ .comptime_ = .{ .loc = loc, .type_ = bodyType, .kind = .{ .comptimeBlock = .{
                .body = typedBody,
            } } } };
            try foldBodyComptime(env, ct, node, loc);
            return node;
        },

        .assert => |a| {
            const condTyped = try inferExprTyped(env, a.condition.*);
            // The asserted condition must be a bool.
            try unifyAt(env, try env.namedType("bool"), condTyped.getType(), a.condition.getLoc());
            const condPtr = try makeTypedPtr(env, condTyped);
            const msgPtr = if (a.message) |msg| try makeTypedPtr(env, try inferExprTyped(env, msg.*)) else null;
            return TypedExpr{ .comptime_ = .{ .loc = loc, .type_ = try env.namedType("void"), .kind = .{ .assert = .{
                .condition = condPtr,
                .message = msgPtr,
                .text = a.text,
            } } } };
        },

        .assertPattern => |ap| {
            // 06 C12 — the subject and the handler are inferred like any other
            // expression. Both used to swallow `error.TypeError` into a fresh
            // type variable, so `val assert 42 = answer catch 0;` compiled with
            // `answer` bound to nothing and only aborted at run time.
            const exprTyped = try inferExprTyped(env, ap.expr.*);
            const exprPtr = try makeTypedPtr(env, exprTyped);
            // Decision 8 § 9 — the pattern has to be able to match the
            // subject. This is what makes
            // `val assert Ok(n) = parse("42") catch 0;` the error the
            // decision writes: after `catch` the value is an `i32`, and
            // `Ok(…)` names no variant of it.
            try checkAssertPatternSubject(env, ap.pattern, exprTyped.getType(), ap.expr.getLoc(), ap.fatal, ap.catchLoc);
            // Decision 8 § 9 — the pattern's names are bound in the ENCLOSING
            // scope (`val assert Ok(n) = parse("42"); @print(n);`), so the
            // snapshots a case arm would restore are deliberately dropped.
            var bound: std.ArrayListUnmanaged(PatternBindingSnapshot) = .empty;
            bindPatternNamesForSubject(env, ap.pattern, exprTyped.getType(), &bound) catch |err| return locateLast(env, err, loc);
            try noteResultPattern(env, ap.pattern, exprTyped.getType(), loc);
            const handlerExpr = ap.handler.*;
            const handlerTyped = try inferExprTyped(env, handlerExpr);
            const handlerPtr = try makeTypedPtr(env, handlerTyped);
            return TypedExpr{ .comptime_ = .{ .loc = loc, .type_ = exprTyped.getType(), .kind = .{ .assertPattern = .{
                .pattern = ap.pattern,
                .expr = exprPtr,
                .handler = handlerPtr,
                .fatal = ap.fatal,
            } } } };
        },
    };
}

pub fn freshEnv(a: std.mem.Allocator, gpa: std.mem.Allocator) !Env {
    // Lazy-init a process-lifetime template (parses + infers stdlib ONCE)
    // and clone its hashmaps onto the per-test env. The full `registerStdlib`
    // path used to run on every call — ~83ms — even though stdlib never
    // changes between calls. Cloning the populated hashmaps is ~µs and
    // produces a byte-equivalent env (modulo arena ownership: `*Type`
    // pointers still reference the template's process-lifetime arena).
    const tmpl = try comptimeMod.getStdlibTemplate(gpa);
    return Env.cloneFromTemplate(tmpl, a);
}
